INSERT INTO `crs_tabledata1533` VALUES ('1', '{DFCF6F78-E6F1-480A-96D4-7FF2C17CDB96}', '61', 'INHE-0578', '2018-01-12 08:42:32', '0000-00-00 00:00:00', '2018-01-12 08:42:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2018011201/立项申请/MX', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '覃湘君2018-01-12 11:21:13', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('2', '{B75A843E-3924-45BD-9B26-805688E8CB64}', '60', 'INHE-0680', '2018-01-16 11:17:16', '0000-00-00 00:00:00', '2018-01-18 10:51:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018011602/立项申请/MAV', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '陈嘉豪2018-01-16 11:42:00', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('3', '{8F384A52-4E37-41BC-A16F-4EDD1CB3B35B}', '61', 'INHE-0440', '2018-01-22 14:14:13', '0000-00-00 00:00:00', '2018-01-24 08:39:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012202/TTN', '', 'PA/001/16/HQ/G/02', '2018-02-09', 'SUPPLY OF SINGLE PHASE ENERGY METERS, THREE PHASE ENERGY METERS, CONTROL CABLES, CURRENT TRANSFOMERS AND METER SEALS UNDER FRAMEWORK CONTRACT 框架合同供应单相电表，三相电表，控制线，电流互感器和电表铅封', '价格条款：DDP TANESCO Kurasini Central Store (坦先令报价)。项目资金来源：TANZANIA ELECTRIC SUPPLY COMPANY LIMITED。国外厂家的付款条件：付款货币为本地币坦先令。      (1)按季度供货产品10%的合同金额，在签订合同后的30天内支付（TT/LC），需提供相对应的预付款保函。      (2)90%的合同金额通过不可撤销的保兑信用证支付       a.40%的合同金额，在发货时通过不可撤销和保兑的信用证支付。      b.50%的合同金额，收货后在提交付款申请和电力公司的验收证明后30天内支付（延迟付款年利息0.001%）国内厂家的付款条件：付款货币为本地币坦先令。(1)按季度供货产品10%的合同金额，在签订合同后的30天内支付（TT/LC），需提供相对应的收据和银行担保后。(2)40%的合同金额，在发货时提供GCC Clause 12里面所需要的文件后30天内支付。（3）50%的合同金额，收货后在提交付款申请和电力公司的验收证明后30天内支付（延迟付款年利息0.001%）1.	质保期限：自接受货物起12', '{8F384A524E3741BCA16F4EDD1CB3B35B8442F4C2B3234363A3D51C033076BD50}_VOLUME 1 BIDDING DOCUMENT PA 001 16 HQ G 02 REVISED 16012018.pdf', '最低价中标，20年生产经验，10年供货记录，双继电器，超声焊，浪涌12kv,电表尺寸，电池，存储器，处理芯片特殊品牌要求等', '{8F384A524E3741BCA16F4EDD1CB3B35B074E749A304748709C51373D9D483750}_TANESCO 招标采购流程信息.xlsx', '只允许厂家投标，一家厂家最多中标2个lots,参考标书Volume 1 invitation for tenders', '', '保函金额：Lot 1. TZS 400,000,000 equivalent to USD 180,300         Lot 2. TZS 400,000,000 equivalent to USD 180,300         Lot 3. TZS 20,000,000 equivalent to USD 9,500         Lot 4. TZS 55,000,000 equivalent to USD 25,000         Lot 5. TZS 13,000,000 equivalent to USD 5,900         Lot 6. TZS 6,000,000 equivalent to USD 2,800货币：TZS /USD（投标报价货币/保函格式/保函申明中说明的货币）保函有效期：投标有效期后30天，即150天。开立行资质：无特殊要求，国外银行开立的保函必须有本地知名银行确认/转开。', '', 'Financial Capability：财务能力： The Bidder shall furnish documentary evidence that it meets the following financial requirement(s):（提供文件证明以下财务能力） (i) Average annual turnover over the last three years period shall be at least as follows:（过去三年/年平均营业额） Lot 1- TZS 9,000,000,000 Lot 2- TZS 9,000,000,000 Lot 3- TZS 500,000,000 Lot 4- TZS 600,000,000 Lot 5- TZS 200,000,000 Lot 6- TZS 150,000,000 (ii) Audited financial statements (including Balance Sheets) for the last three complete financial years (2014, 2', '', '保函，最迟2月7日要转开到当地。2014，2015，2016的纳税证明，最迟2月4日提供。报价，最迟2月2日要报出来。非危险物质申明里面的表计元器件供应商证书，最迟2月4日提供。图纸和装箱信息，样机常规测试报告等，最迟2月4日。具体参考标书要求。', '', '银河直接投标，或银河授权代理直接投标。', '', '现在电力公司已经是半国营的状态，但政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算，有较多的债务需要偿还，最近收了很多欠款回来，整体朝好的方向发展。具体参考评标流程。', '', '按照标书要求的付款条件付款，预付款TT/LC10%按季度供货支付，需提供个预付款保函，剩余90%通过确认和不可撤销的信用证，发货前40%，提供SCC 12.1里有求的清关文件后30天内支付，50%的合同金额，收货后在提交付款申请和电力公司的验收证明后30天内支付（延迟付款年利息0.001%），目前和财务总监关系较好，付款方面可以得到他的支持。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，每季度几百万美金的款项可以支付出来。', '', '电力公司代理商可以接触到高层MD,配电高级经理，财务总监，采购经理等，目前在往配电技术块发展，如电表部经理和实验室经理等。代理和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验。', '', '采购部总监，电表部经理，配电市场经理，AMR中心主管，实验室测试工程师等。', '', '主要竞争对手EDMI，威胜，CLOU等，EDMI主要的合作伙伴是电表部经理，实验室，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要合作伙伴用服总监，电力化部门经理。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。EDMI主要是供三相分体式直通/CT/VT表，上次投标，三相直通DDP 430 美元，三相CT表加表箱，DDP 1384 美元。威胜TF项目BS单相分体加表箱价格DDP 52 美元，FOB 41 美元左右。科陆农电项目BS单相分体加表箱价格FOB 39 美元，LTA项目FOB 48 美元。', '', '此项目标书商务和技术运作比较明显，倾向于某家厂商，如果不改变标书条款，投标成功的几率小。目前在想办法澄清和延标，修改标书条款，同时准备废标直接采购和运作本地招标。代理在加快工厂建设，预约MD，以及和政府层面的人接触，投函争取废标和直接采购/本地招标。', '', '产品报价符合市场形势，样机制作及时交付，商务和技术支持响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机投标，同时运作废标直接采购，或本地招标。', '汤伟2018-01-22 14:51:07', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('4', '{985A3173-8971-4905-8EE8-C190CF2BBCE4}', '60', 'INHE-0680', '2018-01-23 10:55:09', '0000-00-00 00:00:00', '2018-01-24 14:22:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012303/DOSH', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '陈嘉豪2018-01-23 10:57:23', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('5', '{7EE8B9C0-CB89-414F-9AB7-C15CF7713C62}', '61', 'INHE-0500', '2018-01-29 10:20:19', '0000-00-00 00:00:00', '2018-02-01 09:03:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012902/ERED', '', '16/2017', '2018-02-09', 'PROVISION AND ADMINISTRATION OF ELECTRICITY PREPAYMENT VENDING FOR ERONGO REDERONGO RED公司关于预付费售电系统采购的规定和管理', '付款主体：Erongo RED公司价格条款：本地货币报价，不含VAT付款条款、交期、质保、违约等条款：需要在确定中标后再单独签订正式合同商议，请见标书Page 5/33页', '', '技术评标占比：65%；价格评标占比：20%；BEE评标占比：15%。请见标书Page 32、33/33', '', '一家系统供应商中标', '', '只能是本地BEE资质公司投标，无需投标保函，履约保函和其他商务条款需要在确定中标公司后单独签订合同确认。', '', '1.本地符合BEE资质的公司才能投标，BEE等级占比15%；2.无年限要求，无财务数据要求；3.投标公司或者其供应商要求至少提供两个类似项目的用户证明；4.要求提供STS证书。', '', '需要软件部协助提供标书所需的技术方案和相关文件。最迟提交时间：2月5日。', '', '代理直接投标，银河做系统供应商。', 'N/A', 'Erongo RED招标主要由其内部的Tender Committee负责，初步了解到评标委员会全权负责评标所有里程并推荐中标公司，Erongo RED CEO确认签字并提交给董事会批准，暂无需通过政府层面或采购总署。', '', '付款流程和商务条款需在确定招标公司后单独和Erongo RED签订合同商议确定。', '', '电力公司和代理的财报信息暂缺，跟进调查中，后续提供。', '', '1.BEE资质强制性要求：代理100%满足评标占比15%比例；2.代理公司技术实力：ICT背景，已有Airtime第三方通讯服务经验，可做为银河本地系统长期合作伙伴；3.代理商务实力和电力公司客户关系：待继续跟进验证。', '', '纳米比亚属于银河新市场，以前无较大项目投标或小项目试点/直销，目前对当地电力公司的组织架构、核心负责人、采购流程和本地细致的评标规则相关资料暂缺，需要借助ERED项目的合作代理进一步详细了解，根据项目情况年后从南非办事处调派市场人员出差拓展此市场。', '', '代理反馈可能的竞争对手是：Tusk mobile, Starlite Prepaid, Nampost, First National Bank, Standard Bank, Bank Windhoek, Woerman Brock,Mobipay and NedVend.其中最大的竞争对手为代理反馈可能的竞争对手是：Starlite Prepaid（背后是南非Syntell系统公司，当前Erongo RED老售电系统服务提供商），预测客户关系较强；其次是NedVend，此公司目前是兰吉尔和Itron本地市场的电表合作代理，已有部分供货历史，预测也是银河较强劲的竞争对手之一。', '', '1.寻找符合本地BEE资质，有一定技术实力和商务能力的代理，目前来看当前代理初步合格；2.银河的供货资质和记录，以及价格上预计有一定优势；3.劣势：对于银河属于新市场，以前无较大项目投标或小项目试点/直销，目前对当地电力公司的组织架构、核心负责人、采购流程和本地细致的评标规则相关资料暂缺，需要借助ERED项目的合作代理进一步详细了解，根据项目情况年后从南非办事处调派市场人员出差拓展此市场。						4.银河2018年借助南非办事处，周边国家如纳米比亚是潜在开发市场之一，市场需求容量等信息请见附件纳米比亚市场调查报告。', '', '1.本地代理资质和实力的持续跟进和验证；2.需要提供全套完全符合要求的技术和商务投标文件；3.本地出差：客户公关和技术宣讲和演示。', '1.纳米比亚市场是2018年依托南非办事处潜在开发市场之一，此市场政治经济条件较好、人口虽较少（230万），但通电率较高，用电基数大（26万用户），电力基础设施较好，竞争力不强（目前仅Itron、兰吉尔50% 比例代码表供货，其余多余欧洲机械式电表），有一定市场潜力推广银河售电系统、预付费电表，乃至DTMS、LPU和DA方案；2.ERED项目招标时间紧要，2月9日截标，目前已和代理初步沟通清楚合作意向和竞标策略，新市场开拓请公司支持！', '李忠鹏2018-01-29 11:27:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('6', '{69DDE6B8-C3BB-46E7-A8F3-58492E76FAC3}', '61', 'INHE-0593', '2018-01-29 13:23:40', '0000-00-00 00:00:00', '2018-02-01 16:07:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012903/EGP', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目为zens客户主动电话询盘。上周客户来访银河总部（谭雯胡蝶接待），来访之后客户对银河更有信心，要求本周再次来访公司，进一步讨论合作潜力。预计明天会给到客户一个整体的方案，包括电表的选型（附带技术规格和功能解释）、售电方案、AMI系统、项目执行计划（前提考察、发货、培训计划）、收益分析等。通过方案和对方进一步沟通、推进项目。本项目电表采购量大，而且也上系统，尽管目前没有掌握到全面的信息，但是通过沟通可以感受到zens客户重视并且愿意快速推进此项目，项目及需求是真实存在的，故支持立项。', '胡蝶2018-01-29 14:08:17', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('7', '{FABE07BD-646A-44BC-8592-66FD1EE4C3BE}', '60', 'INHE-0560', '2018-01-29 11:06:34', '0000-00-00 00:00:00', '2020-07-03 15:10:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012901/SUM', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '\"Sagemcom”公司和 \"Elster GmbH\"在乌兹别克斯坦一直有其固定的销售范围，并试图提高其产品比重，但由于新总统上任之后提出优先使用本土品牌制造商产品的政策，并大力扶持其民族产业，导致其在乌兹别克斯坦的发展受挫。除此之外，华立在该国曾建立三家公司分别为Elektr Quvvat Qurilmalari公司-主要生产互感器，Elektron Hisoblagich公司-主要生产电表且为中乌合资企业，以及“QUYOSH ISSIQLIK ENERGIYASI”公司-主要生产太阳能热水器。其中生产电表的这家公司所生产的电表性能不稳定（客户认为是其技术原因），尤其是三相表经常出现故障，终端客户投诉较多，并且生产数量不能满足客户的需求，客户对这种被动局面非常不满。', '', '前期可以直接供货的方式展开合作，推进我司产品在当地的认证及推广，同时辅助制定具体的建厂计划及方案，为后期该工厂大批量在乌兹别克斯坦国供货创造品牌基础及技术保障。在确定具体的合作方案（建立中乌合资或帮助客户建厂）之后，依靠我司丰富的海外建厂经验，推进其建厂方案实施及运用。我司的优势为丰富的建厂经验及项目把控能力，以及产品技术及性能优势，该市场为我司在俄语区的新市场，需要我司在产品价格上给出一定的合作空间。', '', '1，针对客户公司给出适合的建厂方案 2，有竞争力的产品价格 3， 产品技术性能需稳定', '客户对表计需求稳定，且数量可观。未来两年内乌兹别克斯坦电力市场的电表需求依然紧俏，客户自身对从事表计生产具有强烈愿望并计划年后来我司详细洽谈合作事宜，建议立项。', '李美娇2018-01-29 14:55:19', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('8', '{E38F9990-39BC-4442-9D8E-5043926DE508}', '61', 'INHE-0578', '2018-02-01 09:37:45', '0000-00-00 00:00:00', '2018-02-06 08:52:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020101/TSE', '', 'USD EE 31-2017/18USD EE 32-2017/18', '2018-03-20', '1. Tender for the supply of a meter management system of the City of Tshwane.茨瓦内电表管理系统招标2. Tender for the supply, delivery and offloading of single-phase and threephase bidirectional meters, as and when required: three year period. 三年期单三相双向计量电能表供货、发货、卸货招标', '价格条款：DDP (从招标描述中得出，报价单中未标明)付款主体：茨瓦内市政交期：电表为收到茨瓦内市政下达PO后21天内完成交货；系统为收到PO后三个月内完成交付。付款条件：收到供应商发票后30天内支付（兰特币）质保：电表需提供发货后18个月/交货后12个月质保；且需说明备品在多长时间内可提供给市政电力公司；系统需提供一年免费运维质保。', '', '1.电表评标分3步：投标文件及资质等考核；样机及技术评估；倾向性评估（BBBEE资质等，按照80/20规则打分，该部分占20分）；2.系统评标分4步：投标文件及资质等考核；技术性评估；功能评估；倾向性评估（BBBEE资质等，按照80/20规则打分，该部分占20分）；', '', '1.电表分为两个LOT，分LOT授予中标，一家可中多个LOT；2. 系统分3个LOT，仅授予一家。', '', '投标方中标后需在30天内开具履约保函。', '', '1.需本地CSD注册，BBBEE资质公司；需提供财报，供货记录等；2.电表、集中器、系统均需提供测试报告（按照SANS测试要求）生产设备还需提供IEC测试证书及ISO9001证书。', '', '技术部分资料需协助（产品方案，测试报告，应答表，生产设备资质证书等）', '', '代理商投标（NYC直投，银河协助）', '', '由市政自行评估、决策；在决定投标者资质方面受国家财政部要求影响。', '', '1. 市政在收到发票后30天内付款，本地币兰特2.若中标，银河直接与NCY交易，美金', '', '1. 市政财务状况良好；2.NYC在ESA执行顺利前提下积累了一定资金，付款无太大问题。', '', 'NYC与市政有一定的客户关系，但无供货基础，还需深入客户关系的建设和产品等推广。', '', '仅与NYC有客户关系，计划2018年3月出差开始于NYC一起拜访及拓展客户关系。', '', '主要竞争对手为L&G, CONLOG，海兴。前两者在该市政有深厚供货基础及客户关系，后者有本地公司，且有多家代理商合作，在市政有一定的供货基础和优势。', '', '银河目前仅在ESKOM供货以及通过NYC给一些小的市政供应了ESA项目的产品，在市政市场尚未打开局面；茨瓦内市政为最重要的市政之一，2016,、2017年均与NYC合作投过2次标，但未能有较好结果。在ESA项目执行顺利、NYC发展自身实力开始着力拓展市政业务的前提下，此次投标为2018年市政业务发展的第一棒，银河必须参与以及全力竞争。目前银河+NYC在客户关系和供货基础上均处于劣势，因此可考虑在价格上给出具有竞争力的价格；另外在3月份出差时需督促NYC一起拜访该市政，积极做好宣讲、演示等工作以力争先机。', '', '技术上需全部满足，样机需保证，方案需完备，报价需有竞争力；投标资料等需精心准备。', '此项目重要，建议立项。', '覃湘君2018-02-01 11:40:52', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('9', '{2ED09C32-5580-47D5-9436-838EFE8BA51E}', '61', 'INHE-0432', '2018-02-01 15:07:49', '0000-00-00 00:00:00', '2018-02-06 08:51:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020102/TGEN			', '', 'KGN-CW-01-2018', null, 'TENDER FOR THE SUPPLY OF SMART METERS, DESIGN AND IMPLEMENTATION OF METERING AUTOMATION SOLUTION THROUGH ADVANCED METERING INFRASTRUCTURE TECHNOLOGY  发电站智能电表集抄自动化实施项目', '1.价格条款：标书没有明确说要DDP，但是通读标书，理解是货到付款，即DDP。           2.付款条件： 	                                                                 1）本地供应商：交货及项目完成后30天起付款。2）海外供应商：使用信用证结算。第一阶段：电表交货至指定仓库后，开立信用证支付。第二阶段：项目执行完毕后，开立信用证支付除电表外的合同金额的90%。第三阶段： 除电表外的合同金额的10%将在运行观察期过后用信用证支付。整个合同执行不得超过12个月。自项目执行完毕后起的6个月，为观察期。关于信用证，标书无明确详细信息。交期：电表无明确交期。整个工程项目合同执行不得超过12个月。质保：2年。', '', '1）初审：标书资料等是否符合规定。同时报价中凡是涉及本地安装/咨询/服务等费用的，必须列明细，且此类报价必须至少占到总投标报价的40%                                2）技术评审：经验、资质、技术应答、方案。                                        3）价格：综合评标，满足要求且报价最低者中标。', '', '1家中标', '', '投标保函：1500美元。或对应肯先令。                                               履约保函：合同金额的10%', '', '经验：1.至少2份AMI项目的启动报告及运行证明。2.至少2份AMI项目用户证明。对公司年限、财报无要求。', '', '投标资料最迟交付时间：2018年3月15号', '', '银河投标', '无', '待了解', '', '待了解', '', 'KENGEN是发电公司，每个月初和月尾，KPLC都必须优先支付KENGEN几百万美元电费。', '', '目前代理在KENGEN关系不是很清楚，待了解；同时会考虑和PZ03分包商Powergen合作，但也需要了解其客户关系基础。', '', '与KENGEN无具体往来，但认识里面相关工程师。会做进一步了解。', '', 'KENGEN电表项目的招标较少，已知市场潜在竞争对手有海兴、科陆等。', '', '1.客户关系：KENGEN这边代理有一定的基础，但具体的情况如何需要了解。如果他这边实力不是很好，则会找其他代理合作。银河自己本身无较好的客户关系基础，因为平时无具体业务往来。目前只认识里面的一个工程师，会从这里入手，深入联系。                    2.为什么做：发电站计量对我们自身的产品和集抄方案是个挑战但也是机会。预计后续随着肯尼亚配电公司KPLC和肯尼亚发电公司KENGEN不断升级电网，此类项目陆续会增多，对银河资质、经验是很好的机会。                                                        3.如何做：                                                                       1）国内首先应标，准备资料等。2）业务会从工程师入手做好客户关系。同时借助目前的代理或PZ03的分包商尝试合作。此类项目金额不大，竞争相对没那么激烈。如果找不到合适的代理，业务将自己进攻，拿下项目。', '', '', '请公司审核，技术方面是否可以满足。如果可以，业务希望银河直接参与投标。', '谭东羊2018-02-01 16:57:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('10', '{67A1FF74-FD26-4692-BD00-8DDD5D628A84}', '61', 'INHE-0374', '2018-02-05 03:23:27', '0000-00-00 00:00:00', '2018-02-07 11:30:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020501/MTD', '', '暂无', null, 'MTD01 特洛伊', '样机方案由银河负责', '', '代理直采样机', '', '', '', '', '', '', '', '', '', '', '', '', '', 'TT 100%', '', '没有任何问题', '', '', '', '', '', '对手主要为Siame、sagem、Sacem、华为、科陆、海兴等', '', '通过试点说服电力公司技术部门，公关上层关系运作招标规格', '', '试点，需要技术支持', '希望公司支持此次试点运作招标，拿下项目。', '王子强2018-02-05 21:28:00', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('11', '{42957F7B-C103-4A28-B8EE-73CEC56129B2}', '61', 'INHE-0432', '2018-02-06 10:57:10', '0000-00-00 00:00:00', '2018-02-07 11:44:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020601/KE03', '', 'TENDER NO.KP1/9A.3/OT/19/17-18FOR SUPPLY LV CT METERS', '2018-02-27', '低压CT表招标', '1.价格条款：DDP                                                                2.付款主体：KPLC                                                                3.付款条件：同PY02、KF02等一致。交货后，提交付款资料后30天开始付款。            4.交期：2018年6月开始供货，12月底前完成。', '', '1.初审：审查保函、标书商务资料等。                                              2.二审：审查技术应答表，技术资料、样机等。                                     3.终审: 审查报价、财务资料等。', '', '无明确规定是否一家只能中1个LOT。无明确规定一家厂商只能授权1个投标人。', '', '1.投标保函金额：3,500,000肯先令。                                               2.履约保函：合同金额的10%。', '', '1.必须是本地公司才能投标。                                                      2.至少提供4份用户证明，且必须说明该供应商按时完成了合同执行。                   3.需要提供测试报告、本地KEBS认证、ISO9001等认证。', '', '业务将先运作延标，商务资料希望在2月25号左右准备好。', '', 'IAC即银河非洲直接投标。', 'N/A', '决策层：采购总监，用服总监，电力公司MD。', '', '同PY02一致。', '', '该项目金额不会太大，且交付时间至少是2018年下半年，收款问题应该不大。', '', '代理与决策层有较好客户关系基础。', '', '银河与决策层有一定的基础，同时与技术规格制定团队有较好客户关系。', '', '最大竞争对手：海兴。海兴成功运作了KE01，累计安装了6000个大用户计量箱；KE02也中标，安装中压计量箱；该项目从运作来看，海兴运作痕迹最明显。其在价格、产品应用基础上有一定的优势。', '', '竞争策略：                                                                      1.业务运作延标，为研发制样、IAC做KEBS认证争取时间。                             2.银河做技术解析，提供银河的产品亮点，通过澄清运作。                            3.视情况而定，必要的话逼海兴合作分标，排除科陆思达等。', '', '需要的支持：1.报价有竞争力（海兴已批量供货）。2.业务延标，研发能及时交样，IAC及时完成KEBS认证。', '请公司批准立项。', '谭东羊2018-02-06 11:26:24', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('12', '{87EE9C33-5E43-45E6-B903-76FB006CC0BA}', '60', 'INHE-0399', '2018-02-07 15:21:10', '0000-00-00 00:00:00', '2018-02-08 11:45:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020702/WZT', '', '27.22.4785.905.50.040.18/01', '2018-03-05', 'Design, Manufacture, Supply, Installation, Testing & Commissioning of 130,000 nos. Smart Pre-Payment Meter with Related Services on Turn Key Basis.设计，生产，供应，安装，测试和调试，13万台智能预付费电表，以及相关服务。', '1.	价格条款：CIP2.	付款主体：WZPDCL 3.	付款条件:电表部分：交单70% ,货到10%, 安装10%，最终交付10%。网络设备部分：软件和网络设备都用本地货币（BDT）结算。30%的软件和网络设备的合同金额在所有软件和网络设备安装后付款。30%的软件和网络设备的合同金额在系统安装，测试，调试以及提供相应文档（即，完成预付费系统安装，测试和调试的临时验收报告）后付款。30%的软件和网络设备的合同金额在系统运行6个月，并由电力公司提供相关证明后付款。10%最终验收证明后付款。4.	交期：LC开具后60天之内交货。180天之内完成项目安装调试等相关合同内容。', '', '先进行技术评审，然后开价格标。通过技术评审的投标人，低价者中标。', '', '1个lot，一家中标。', '', '$ 285,465', '{87EE9C335E4345E6B90376FB006CC0BA1DD410FC292E4E1893AFBEF9F88431CD}_tender_527649a.jpg', '投标人应具有至少五（5）年的货物供应和相关服务经验，包括以下要求：a）过去5年内，投标人/制造商在网络建设，数据库软件，软硬件集成和接入方面的电力公司智能预付费表项目至少为02个，系统已安装且运行。', '', 'IT设备的厂家GTP，厂家授权，英文画册等资料。', '', '', '', '政府拨款已到电力公司，电力公司自主决策采购。', '', '如项目四4.', '', '政府预算拨款，拥有支付能力。', '', '我司以及代理与电力公司关系好，已经成功运作写技术标书。', '', '关系好', '', '海兴，威盛，思达，科陆。海兴与电力部有关系，价格激进，REB701 项目表计报价（不含模块）约17美元', '', '1. 与电力公司关系好2. 参与写技术标书，将G3 PLC FCC等我司有优势的技术和资质要求写进标书。AMI协议框架写进标书。', '', '1.完成AMI具体协议文档，同时尽快开发出HES。协助电力公司解答其他厂家的澄清问题，坚守我司的技术优势。2.价格同时也需要保持竞争力。', '', '左三维2018-02-07 17:27:00', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('13', '{574BDCEA-AC72-46F1-AEDF-ED0D55F36497}', '66', 'JXINHE-2559', '2018-02-24 10:02:48', '0000-00-00 00:00:00', '2018-02-25 08:58:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022402/MVB', '', '2/EDM-DIA-QPCS/2018.', null, '2/EDM-DIA-QPCS/2018.', '代理商负责投标事宜，我司负责制作标书和样机。', '', '', '', '一家中标', '', '代理商负责', '', '1.ISO9001:2008和14001：20042.五年质保3.三家大型公司的供货纪录', '', '1.产品目录含技术参数 2018年2月28日前', '', '代理商投标', '非联合投标', '代理商和电力公司关系良好，曾直接作废某次电表的投标。', '', '和代理商交易，不和客户发生交易。', '', '代理商资金能力良好，曾以T/T的方式和我司交易。', '', '代理商和电力公司关系良好，主战团队商务能力强，老板40岁左右，头脑精明，行事高效。', '', '拜访过业主一次，初步宣讲后，印象良好，计划三月到访我司。', '', '海兴已供应电表，相关信息收集中。', '', '投标原订2月中旬截标，在代理商的支持下向电力公司成功延标。代理商同意在投标中运用资源强力推广银河已有的表箱，以品质取胜。后表箱和电表相辅相成，以提升两者的供应数量和金额。', '', '最优的报价和良好的品质。', '代理商为KAM02的客户，充分利用代理和电力公司的关系，强力引入我司已有的表箱，从而表箱和电表两者相辅相成，最大程度垄断该市场。以上，恳请同意！', '淦永妍2018-02-24 10:39:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('14', '{0CF81430-79D2-4026-9EC4-2B724D22A097}', '60', 'INHE-0680', '2018-02-24 11:02:36', '0000-00-00 00:00:00', '2018-02-27 10:47:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022403/MAV', '', '18022088444706', '2018-03-16', '奥什电力智能电表采购项目用于变电站 35/10-6KV 线路', '价格条款:DDP 奥什- 奥什电力仓库付款主体:奥什电力付款条件:收到货物后3个月内交期:签约后45days质保:5年违约条款:延期交付违约金 每周0.10% ，最高合同金额5%', '', '1）12/03/2018 提交样品测试。 未参加标前会议测试的标书将不会被采纳。2) 在标前会议时提交（用于测试集抄系统与计量设备）5pcs 计量设备包含模块，测试用软件，安装在奥什电力服务器上。样品将被安装在奥什电力电网中并且在开标后10天内进行兼容性测试。投标方必须确保相关人员到场支持以及软件硬件的支持。3) 投标保函必须列出本标号，金额为2%,有效期开始为：开标日期之前，结束为 ：不少于30天以后。', '', '一家中标', '', '投标包涵：2%，有效期开始为：开标日期之前，结束为 ：不少于30天以后。履约包涵：10%。', '', 'A) 提供允许经营产品范围许可证明原件的扫描件；B) 提供未有欠社保基金证明原件的扫描件；C) 提供公司注册证原件的扫描件#FE54`D) 提供未有欠税证明原件的扫描件；E) 提供由授权机构认证的2016年完整的资产负债表（包含所有附件）原件的扫描件；', '', '', '', '代理商投标', '', '关系 > 技术要求 > 资质 > 价格', '', 'TT:30%/70%', '', '资金来自电力公司自有资金，代理商仓库库存价值约200万USD.', '', '1995年成立，2012年公司更名，副总2014年注资入股，目前员工15-17人，为当地最大规模10KV电缆供应商，一直是伊尔库茨克电缆当地代理商，后来副总入股后开始经营各种电缆，稳压器，开关，简单电表，断路器，电表箱等电缆相关产品，目前也是得力士当地代理。一直供应欣灵电气简单表到贾拉拉巴德和其他电力公司，目前没有智能电表合作伙伴。2015年之前一共参加了50-60个纸质投标，2015年至现在一共参加了261个电子投标，赢得70%的投标，金额最大的约为150万USD，2015-2017年销售额分别为：214万USD、457万USD、371万USD，在首都有2个大型仓库，总货值超过200万USD,获得俄罗斯JSC \"\"EXIAR\"\"最高授信额度100万USD，目前电力公司对其有欠款仍未偿还，奥什电力为13.5万USD、贾拉拉巴德电力为15.4万USD', '', '项目负责人与电力公司关系良好，\"2017年12月19日-20日 奥什电力会面，计量部部长全程陪伴，商务情况了解，产品，方案展示，副总经理表达合作意愿，希望直接跟我们取得联系或合作，不经过BY代理，愿意协助申请修改技术要求，愿意帮忙介绍能源部相关领导，促进建成合资工厂，建议在首都建成售后服务中心，同意运作配电自动化（35KV线路）试点项目。', '', '三星16年直接投标后中标2500台，中标单价：单相90USD,三相146USD，方案：单相，三相可更换模块表带GPRS模块（ZTE方案），', '', '有实力的合作伙伴协助当地沟通和处理客户关系', '', '按时提交符合要求的样品测试，按时派遣相关人员前往电力公司提供测试支持，投标价格排名第一。', '1）问题澄清如下：A: 项目代号MAV的对应客户为该市场的新代理，是为签订合作协议所立项，并没有实质项目，当时提供样机用于 1）奥什电力计量部部长测试使用，后续以个人名义订购50-100台；2)新代理开拓市场演示推广之用，配合我方将提供的完整详细技术要求，争取为电力公司写标书的机会。但因样机还在清关中，暂时没有反馈测试意见。 B: 标准31819-23-2012 对应标准为 IEC 62053-23:2003 #FE54` C：单相表有工精度：0.5S， 为标书技术要求，请查看附件技术要求；  D：本次项目不要求内置5A继电器，是MAVN项目要求内置5A继电器#FE54`单相表： 1: 14条-工作模式：当缺少单相或二相情况下，仪表可在符合要求计量等级下继续工作；（ 此要求请忽略，可不考虑。） 2：16条-必要的测量：测量有功电能和无功电能的总电量和单位消耗电量，测量每相和总相的有功。（无功电能和每相的要求请忽略，可不考虑）     A:表计没有无功计量要求（5条）；     B:单相表没有每相的说法； 3： 17条--数据显示：  Ктт是指什么？（此要求请忽略，可不考虑）三相表： ', '陈嘉豪2018-02-26 10:08:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('15', '{57950AA9-4AAD-4D3E-876F-D4455CD6D0D1}', '60', 'INHE-0680', '2018-02-24 15:29:04', '0000-00-00 00:00:00', '2018-02-25 17:35:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022404/MAVN', '', '18022087854883', '2018-03-19', '', '价格条款:DDP 比什凯克-北方电力仓库 （适用于吉国公民） 或   DAP 比什凯克-北方电力仓库 （适用于非吉国公民）付款主体: 北方电力付款条件: 无约定，根据融资情况而定交期: 60days', '', '在开标时按要求提交样品测试，测试周期为开标后30天内，投标方必须派遣4人（项目经理、计量工程师、计量设备和和集中器工程师、AMI软件开发工程师）出席整个测试周期，如缺席标书将不会被采纳。', '', '一家中标', '', '投标保函：2%， 30天.  履约保函： 2%', '', '1) 在开标时提供符合技术要求的样品；2) 提供允许经营产品范围许可证明原件的扫描件；3) 提供制造商给本次招标投标人的授权（官方）信函，说明标号，制造商信息。4）提供由授权机构认证的过去两年的完整的资产负债表（包含所有附件）原件的扫描件；5）按吉尔吉斯共和国“关于公共采购法”第6条的规定提供关于不存在从属关系证明信；6) 提供未有欠社保基金证明原件的扫描件；7) 提供公司注册证原件的扫描件#FE54`8）提供不少于5份过去2年内智能电表项目供货合同，总金额不少于60万USD#FE54`9) 所有投标文件必须是俄文版本；10）过去两年出货总金额不少于120万USD,由资产负债表证明；11)提供未有欠税证明原件的扫描件；', '', '', '', '代理商投标/银河投标', '', '关系 > 采购文件 > 技术要求 > 价格', '', '', '', '根据CY项目，中标方为三星，到2017年底电力公司已经付清项目款项。北方电力自有资金相对充足，此次采购资金来自银行。', '', '代理商实力比较强', '', '与业主关系不太好，因为业主与三星有很好的关系，比较抗拒其他厂家，', '', '三星 17年最后一次投标价格为 90$，条款为 DAP 比什凯克， 三星与业主关系比较好', '', '通过代理打通对方高层关系，运作项目', '', '按要求按时提交样品测试，测试周期为开标后30天内，投标方必须派遣4人（项目经理、计量工程师、计量设备和和集中器工程师、AMI软件开发工程师）出席整个测试周期。与三星竞争更低价。', '', '陈嘉豪2018-02-24 16:27:09', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('16', '{8D6862FF-DF80-4688-8EF0-E4E8520618BA}', '61', 'INHE-0593', '2018-02-25 09:11:44', '0000-00-00 00:00:00', '2018-02-26 18:40:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022501/BFN10', '', 'N° 007/2018', '2018-03-05', 'Fourniture de matériels électrique à la SONABEL dans le cadre du projet de branchements promotionnels dans le Nord et le Sahel.为SONABEL提供电气设备，以支持北部地区及SAHEL地区项目', '价格条款：DDP电力公司仓库付款条件：预付款，收到合同签订方20%*合同总金额的银行保函后，电力公司会支付与保函总金额对等的合同款项，交货后电力公司退回该保函；尾款，标书中未提及，正在找客户澄清中质保：12个月交期：是在签订履约服务条款之后的90天内。罚金条款：延迟交货部分不含税总金额*千分之一/日的罚金。罚金若超过合同金额的5%将取消合同。', '', '1.	在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。2.	接下来评技术部分，技术资料是否满足标书的技术规格 。3.	评财务部分。评完财务文件，价格最低者中标。', '', '', '', '-	投标保函：20 700 000 FCFA 约为 210 000 RMB			-履约保函：在中标签合同30天内，中标者需要开合同总金额的5%的履约保函。', '', '无特殊要求', '', '资料已准备好，主要是样机', '', '代理投标，银河作为供货商', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '春节期间收到了布基纳法索当地公司询盘32000台预付费电表，要求银河提供样机。通过沟通并咨询电力公司，了解到电力公司当时未放标，计划在2月22号左右放标。当地公司发给了我标书草稿，对比之后发现电表技术规格与此前BFN06 80000台，BFN09 5000台的一致；2月23号晚上收到代理发来的标书，代理十分焦急，代理表示他才买到标书并且截标日期是3月5号，即从电力公司正式放标到截标，中间相差10来天。还有8天截标，投标需要四台样机，我们给了代理三个建议：1.延标；考虑到之前BFN06延标失败惨痛的经历，我们不敢做太多指望；2.此前BFN09时我们提供给了电力公司4台样机，现在电力公司测试已完成，让代理找熟人把这4台样机要回来，再作为本次投标的样机提交。代理工程师回复不可能，暂未得到代理直接回复；3.银河准备4台样机，然后由业务运送样机到现场，参与开标。对于布基纳法索提前发过来询盘信息的当地公司，对方希望能与银河合作，银河直接投标，他作为代表去运标。由于对这个新代理目前了解不多，我们只是表示时间紧急，希望他先去运作延标。支持立项，此次投标仍与老代理合作，也希望能借此机会多了解BFN当地的', '胡蝶2018-02-25 13:25:45', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('17', '{12F8B8F1-92FC-4981-8E4C-C455B6EB5CDC}', '61', 'INHE-0587', '2018-02-28 11:39:49', '0000-00-00 00:00:00', '2018-03-02 16:08:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022803/GZA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '请领导审批同意。', '陆飞雨2018-02-28 14:38:20', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('18', '{4292477C-76D1-4B57-8820-B0D3D927A47D}', '61', 'INHE-0662', '2018-03-05 14:59:37', '0000-00-00 00:00:00', '2018-03-05 16:42:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018030501/DAN', '立项目的何在？需要做什么？如何做？不能弄个询盘就立项。', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '陈丽2018-03-05 15:35:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('19', '{CA416284-D0F3-4BE7-A8AB-FA82AA137B13}', '66', 'INHE-0579', '2018-03-05 17:20:36', '0000-00-00 00:00:00', '2018-03-07 10:33:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018030503/LOP', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.客户做事严谨慎重。从2017年11月开始邮件沟通，了解我司产品及方案。同时也联系多家供应商。客户提出先购买样机，我司提供试用版本软件，待样机测试通过后，进行最终下单采购。目前客户已接受我司样机报价，并向我司下发采购单。2.黎巴嫩市场私人发电售电市场潜力大，且该客户业务和客源广，可借助该客户推广黎巴嫩市场。', '孙娜2018-03-06 15:10:36', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('20', '{D6C4A848-40A7-4E1B-9124-6B94D177A2C7}', '60', 'INHE-0601', '2018-03-09 17:15:43', '0000-00-00 00:00:00', '2018-03-12 13:08:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2018030902/PIK', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '常一琳2018-03-09 17:18:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('21', '{20C5EFC3-6DA1-40AC-95C9-9A1E9D7BAAC6}', '61', 'INHE-0642', '2018-03-14 00:00:27', '0000-00-00 00:00:00', '2018-03-22 09:19:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031401/JJN', '', 'CB No: 5130400/IFB/03/18', '2018-04-04', 'Meter Management System (MMS) for Electricity Company of Ghana (ECG)，加纳电力公司电表管理系统', '价格条款 CIP，费用包括清关', '', '先商务后技术。', '{20C5EFC36DA140AC95C99A1E9D7BAAC6074E749A304748709C51373D9D483750}_评标规则.png', '1家中标', '', '\"无条件银行保函，要求保函金额5W美元.获得授标涵后的28天内投标人应开具履约保函，保函金额应为合同总价值的10%，以美元为货币。保函开立方银河\"', '', '\"1.	5年内有三次相同规格的AMI系统以及售电系统的应用2.	过去5年内有两次以上电力公司规模的系统集成案例3.	投标人应展示在撒哈拉以南非洲国家或其他与加纳相似条件的发展中国家提供MMS的经验。Two reference()4.	在过去的五年里，投标人应展示至少两个类似项目的环境、社会、性别、健康和安全要求5.	投标方应满足表4.0中列出的所有资质要求。Qualification of Section III of the Bidding Document.6.     5年内没有出现过不履行合同的现象7.     在过去五年没有发生收到合同通知后，不签订合同的事项\"', '', '需要客服部门协助评估技术要求。此外需要商务部门协助整理投标资料', '', '银河投标', '客户倾向于佣金模式', '客户告知，评标将会由三名MCA人员协助评标，后续会发送到美国总部进行审核。', '', '1.	预付款 - 整个合同价格的10%2.	除开定制软件和定制材料外的信息技术、材料以及其他物品（1）	发货后支付10%全部合同款或者按比例的合同款项（2） 开始安装后支付10%的全部合同款或者按比例的合同款项（3） 运行验收后支付70%的全部合同款或者按比例的合同款项。3.	软件（1）	开始安装后支付10%的全部合同款或者按比例的合同款项（2）	运行验收后支付80%的全部合同款或者按比例的合同款项。4.	培训以外的服务（1）	按比例的服务合同款项的90%将按月支付欠款，且按照买方发票付款。5.	培训（1）	在全部培训开始时，支付培训服务合同总价的30%（2）	按比例支付的培训服务合同价格的60%(60%)将按月支付，并提交适当的发票6.	完成系统兼容 在系统运行验收后，支付总合同价格的10% （不包括所有经营性成本）7.	经营性成本已完成的服务的价格的百分之百（100%）将按月支付，提交和购买者对拖欠的发票，提交和购买者的批准发票。', '', 'MCA项目，支付能力良好', '', '代理提前从MCA拿到标书，并且在MCA内部有一定的关系，目前还属于投标初期阶段，如果公司同意立项该项目，后续客户会跟进一步开发当地MCA关系。', '', 'PPA为我司老客户，但是一直没有做成大项目，这次想要和我司携手竞标MCA项目，目前客户已经打通了MCA中低层关系，后续如果有必要，可以继续往上运作。', '', '科陆，El sweedy等等。', '', '该投标项目暂时还未公布出来，客户能提前拿到标书，可以证明在MCA项目中运作了一定的关系。现在主要需要考虑的是技术方面的因素，如果我司能够满足大部分的技术要求，在加上客户方面的运作，我司能抢占先机。', '', '据客户告知，MCA对技术部分的要求较高，如果技术部分可以满足，商务部分可以商议。需要客服同事协助分析技术参数。', '该投标项目有以下几点优势，1.MCA项目资金稳定并且项目执行比较规范。2. 该项目是当地电力公司第一个AMI项目，如果我司能够中标系统，可以很好的为后续的78000台的预付费电表项目做铺垫。3.该项目可以帮助我司打开该市场的大门，并且和已在该市场建厂的科陆分庭抗衡。4.目前该项目暂未在网站公布，我司有充足的时间做准备。结合以上优势，向公司申请立项，希望公司能给予支持和帮助，谢谢！', '潘正豪2018-03-15 22:01:44', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('22', '{4B9F5BAD-4D4D-4723-9A77-71CE9AD65CF8}', '61', 'INHE-0434', '2018-03-14 17:01:43', '0000-00-00 00:00:00', '2018-03-15 17:05:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031402/AJA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 希望公司同意AJA立项，该项目基于AZA02项目(5台BOX300)，电力公司希望实现私变用户变压器损耗监控，5台BOX300已于上周移交电力公司测试，预计本周末测试完，当前BOX300测试无异常；2. 据悉该市场暂未有相同或者类似的产品方案，客户需要我司提供产品技术规格供电力公司参考，业务认为可以基于市场当前情况尝试拓展中压产品业务。备注：我司去年也在该市场供过DIN-III产品，产品已完成安装，暂没有上AMI要求，仅预付费要求。3. 希望公司给予支持推动该市场中压产品业务。', '钟云林2018-03-14 17:29:41', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('23', '{D5D65C63-E7A7-49C4-97AC-5AD065DD7710}', '60', 'INHE-0535', '2018-03-14 16:18:44', '0000-00-00 00:00:00', '2018-04-24 14:16:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031403/JPM', 'JPM', 'EESL/06/ICB-Smart Meters-Pan India/171802068 dated 08-Mar-2018.', '2018-04-24', 'International Competitive Bidding (ICB) for Procurement of 5 million Smart Meters for Pan India.为泛印度采购五百万智能电表的国际竞标。', '一：付款计划：(收到相关单据后30天内由EESL付款。)a) 供应阶段：以下材料抵达指定地点/仓库后支付60%（EESL在收到投标人Tax invoice 和在指定交付地点收到所有要求的经EESL EIC(Engineer-in-charge)/授权代表签字盖章的文件后30天内付款）：1. 提交DLMS标准符合验收，APIs, 数据交换信息和配置图表，测试步骤和型式测试报告。2. 订单验收3. 必要的合同履约保函提交4. PDI报告和物料交付许可证（MDCC）b) 兼容和运行阶段：（兼容和测试案例及用户验收测试成功运行后，MDMS生成一个报告证明电表与HES和MDMS的兼容和运行）：1. 剩余30%凭电表与smart vend解决方案兼容和运行后支付。款项在电表与backend 系统成功兼容3个月后的30天内支付。2. 万一兼容延迟（不是由于供应商的责任），此30%款项在电表供应6个月后的30天内支付（条件是其他批次都没有硬件问题出现）c) 质保阶段：剩余10%款项在EESL运行验收后凭提交的TAX invoice支付(SLA report/EESL项目主管签署的验收报告。付款计划如下', '{D5D65C63E7A749C497AC5AD065DD77108442F4C2B3234363A3D51C033076BD50}_Project_Event_Details.xlsx', '1. 先开技术标，技术标通过的厂家才开其价格标；（投标人至少投50%的量）2. 按价格评出：L1， L2， L3，。。。之后根据L1可能会有逆向招标（技术标通过的厂家对L1进行二次报价）；3：成品价格包括：包装费和运费，运送至EESL指定仓库的相关运输费，卸货费，所有使用税收和关税（除GST印度中央销售税外）', '', '3-5家中标， 按价格3家分：L1 最少50%， L2 30%， L3 20%，一家制造商授权1个投标人', '', '1.投标保函：Rs. 142,400,000 / USD 2,225,000有效期至技术标开标(2018/04/12  IST14:30)后225天；2.履约保函：中标通知给出后 28天后开立，合同价值10%有效期7年：交付期1年+质保期5.5/5年+3个月索赔期+3个月动员/测试期以上由此项目代理JPM负责保函开立', '', '1.为商业个体；可形成联合体，联合体主投标人必须是智能电表或电子元器件制造商；NSIC联合体和PSU政府性质企业除外2. 年平均营业额USD33million(2015-2017)3. 投标人应制造和供应智能/普通电表或其他电子设备至少3年4. 过去5年累计供货500,000只电表', '', '17年财报；产品图纸，画册，操作手册等，4月前提供', '', '联合投标（代理商没有相应的供货记录，倾向联合投标，对项目供货更有把控力）代理直采：银河SKD,CKD供货或专利授权，利润分享；客户负责本地采购塑胶件，金属件，组装等，本地工厂直接供货最终成品给电力公司。', '代理主投，负责全部投标文件整理和电子投标，直接与电力公司签订供货合同，收取项目付款，给银河开立对应供货范围的信用证；处理与电力公司的商务和其它复杂关系；协助中标运作；支付新产品研发所需的研发保证金和模具费；负责产品安装、测试调试以及售后服务和维修；开立相应的投标保函，和履约保函或质保保函等。银河负责提供资质和技术上的投标文件；中标后给代理供货核心元器件；提供进行本地制造/装配所需的技术支持；提供投标样机和相关技术资料和产品宣传资料等', '中央政府下达政策计划，并提供项目资金给EESL，EESL负责组织招标和采购。此项目受印度总理2019年大选政绩需求的影响。', '', '电力公司直接付款给供应商：收货后30天内支付60%；与系统兼容后30天支付30%；余下10%验收后5年内每年2%', '', '资金直接来源于政府办公室，资金有保障', '', '客户在电力公司有一定关系；代理主战团队为该公司电表项目核心负责人；代理工厂生产制造管理规范，电表生产具备SMT生产和注塑生产能力，电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。', '', '银河正在通过一定渠道争取与电力公司决策层的直接见面，争取能在项目运作上达成某些共识', '', '1.ITI等政府性质的公司。受招标资质条件束缚较少，政府背景（与电力公司平级），可轻易给出最低价，拿到最大单；2.Secure, Genus等本地表厂。有一定生产制造和智能表研发能力，熟悉本地招标操作。3. Hexing，威盛，科陆等国内厂家。都在通过某些渠道打入印度市场。', '', '针对印度市场严峻的价格竞争态势及巨大的数量，建议在印度市场的报价策略上应按照CKD方式考虑并规划，即我司主要供货不可替代的核心关键器件（如写好程序的MCU、LCD及继电器），同时每台表收取固定技术专利授权使用费（加到核心器件价格上）或者采用毛利润按比例分享模式（最终成交价格减去BOM成本后按约定好的比例与当地合作伙伴分享），至于其他非关键器件，我司直接按照采购成本价核算并报出，如当地合作伙伴采购渠道价格更便宜，则由当地合作伙伴采购', '', '电力公司关系的处理；制造和生产能力；样机；有竞争力的价格；', '与EESL项目技术规格和商务条款等基本一致，EESL项目当初解析过（客服黎珊），并针对特殊技术规格有过讨论。但标书对GPRS模块的要求有放宽，要求：可插拔模块，能够在符合IPv6的GPRS技术上为3G/4G/NB LTE 或 NB LoT提供服务，以便在泛印度部署。【此立项评审在3月16日及4月19日“JPM立项评审问题回复中”，已由王总同意立项。现为再次走流程，立项内容没有变更】', '左亚楠2018-04-19 17:27:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('24', '{FC701BCC-49A9-491B-A27E-D40D2B329ABB}', '66', 'JXINHE-2559', '2018-03-16 17:11:08', '0000-00-00 00:00:00', '2018-04-11 15:49:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031601/MSG', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '淦永妍2018-03-16 17:19:03', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('25', '{F4FEF3EE-AE70-432A-896E-6E16E8399CED}', '60', 'INHE-0514', '2018-03-16 15:38:02', '0000-00-00 00:00:00', '2018-03-22 09:08:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031603/OMA', '', 'Tender 17/2018/Majan', '2018-03-22', 'Supply of Kilowatt Hour Digital Meters Three Phase Directly Connected for Service Connections （针对连接服务的三相直通电表供应）', '价格条款为DDP，我方报价条款为CIP，付款主体为Majan电力公司，银河的付款主体是BPT，付款条件是30%预付款，70%TT尾款，或者70%不可撤销即期或延期LC，或者100%不可撤销即期或者延期LC；电力公司的付款条件是没有预付款，货到验收之后，60天内付款95%，剩下的5%验收1年后支付。交期为下采购订单后30天内交第一批3000台，60天后交第二批1000台，90天后交第三批1500台，120天后交第四批1500台，质保期和合同生效至最终验收，至少一年。违约条款，延迟一天按0.15%交罚金，最多不超过5%#FE54`', '{F4FEF3EEAE70432A896E6E16E8399CED8442F4C2B3234363A3D51C033076BD50}_TENDER_3742_0_1724_1_1.pdf', '先评技术标,再评商务标，没有具体的打分规则', '{F4FEF3EEAE70432A896E6E16E8399CED074E749A304748709C51373D9D483750}_TENDER_3742_0_1724_1_7.pdf', '无定义', '', 'BPT开立，投标保函金额为投标金额的1%；履约保函金额为合同金额的5%；', '{F4FEF3EEAE70432A896E6E16E8399CED1DD410FC292E4E1893AFBEF9F88431CD}_TENDER_3742_0_1724_1_7.pdf', 'ISO9001， DLMS/COSEM，其他的类似Kema我们可以自行提供', '{F4FEF3EEAE70432A896E6E16E8399CED03404677E4D44E9EB56B3D512B2AF9CC}_TENDER_3742_0_1724_1_4（Commented）.pdf', '无', '', '代理商投标', '', '技术部门进行技术评估，然后通过的供应商有采购部进行商务评估，最后由该项目的统筹负责人或者评标委员综合评标结果递交CEO最后决策', '', '项目付款主体为Majan电力公司，银河的付款主体是BPT，付款条件是30%预付款，70%TT尾款，或者70%不可撤销即期或延期LC，或者100%不可撤销即期或者延期LC；电力公司的付款条件是没有预付款，货到验收之后，60天内付款95%，剩下的5%验收1年后支付。', '{F4FEF3EEAE70432A896E6E16E8399CEDDC30B63FF962416CACC9A604CE6ABE1F}_TENDER_3742_0_1724_1_7.pdf', '良好', '', '目前该项目主要竞争对手是sagemcom，Landis，Iskara以及Bluesky，前面三家之前有中国Majan的标，所以客户关系应该比较好。三星方面，我们之前在阿曼有过试点项目，所以相对来讲有一定的优势。我方代理BPT在电力行业关系一般，但是后期可以借助Bahwan集团在当地的影响力去运作。', '', '我们与电力公司技术负责人Said见过一面，介绍过银河的方案和产品，且2012年我们在Majan做过试点，有一定的关系基础', '', 'sagemcom，Landis，Iskara，Bluesky，Secure， Genues， Secure的代理为Oniec，老板是Nama退休的高层，但Majan并不是很喜欢Secure的产品；Genues的代理是Bahwan集团下另一家子公司。其他的代理目前尚不清楚。价格方面，Sagemcom， Landis的价格预计在130-160美金左右，Iskara预计比我们高20%左右；Secure和Genues的价格比我们略低。', '', '优势在于银河之前做过试点项目，有一定的客户关系基础，另外，通过之前的投标以及试点，代理以及客户对我们的产品都是认可的，在产品质量上面我们有自信，特别是相对于价格较低的印度产品Secure 和Genues这是很好的优势和取胜的关键。针对于Sagemcom和landis类似的产品，我们技术上不占下风，但在价格上有优势。所以综合来看，中标的关键在于把握好与电力公司的关系，通过综合价格和技术的优势锁定我们的有利位置。', '', '客户关系', '项目22号截标，目前投标资料已基本完成，需要立项申请报价。', '李成兵2018-03-19 13:12:04', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('26', '{068EEC98-12F4-41FD-87A8-FE942E4E9178}', '66', 'INHE-0634', '2018-03-19 14:08:24', '0000-00-00 00:00:00', '2019-02-28 16:13:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031901/TOD', '', '16(T)ESE/2018-2019', '2018-04-10', '', '', '', '暂不明晰，有待跟进核实。', '', '本标共分3个LOT，分别是CT表带内置CT、CT表不带CT、以及CT表箱带CT，表计部分代理已决定与印度SECURE合作，仅与我司合作表箱部分。', '', '', '', '', '', '', '', '代理直接直采，银河直供。', '', '', '', '', '', '', '', '', '', '', '', '与我司合作的本地代理阿尔法与电力公司之间业务往来频繁，人脉以及经验都积攒充备，且曾在APE项目中与我司合作拿下1000台三相表的订单，综合实力中等偏上，属目前在缅甸市场找到的较好合作搭档。', '', '', '', '按照标书规定递交满足技术要求的样机为成功的第一步。', '本款表箱我司目前暂时没有，且截标时间紧迫，但考虑到这也是一个渗入缅甸市场的好机会，希望公司支持参与。另外，此为与阿尔法的第四次投标合作，彼此之间已经磨合出较为协调的合作状态，建议立项，参与投标。', '陈雁2019-02-28 15:40:38', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('27', '{6F8B71B9-AD35-4FA8-BBF8-0E30FAA313CA}', '61', 'INHE-0695', '2018-03-20 10:57:18', '0000-00-00 00:00:00', '2018-03-22 09:20:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032001/SLV', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '卿于蓝2018-03-20 11:22:35', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('28', '{E0C9A119-3827-4894-B7B1-F4AC6FBE9455}', '88', 'INHE-0091', '2018-03-21 10:23:49', '0000-00-00 00:00:00', '2018-03-26 08:36:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032101/DAK\r\n', '', 'REA/2017-2018/OT/037 或 REA/2017-2018/NT/037 (标书出现2个标号，待澄清)', '2018-04-10', 'Supply, Installation and Commissioning of 1x300kva and 1x500 Kva, 415v 3-PH Enclosed Diesel Generators Plus Associated Distribution Board, at Sololo在Sololo地区供应、安装和调试三相封闭式柴油发电机（1套300KVA，1套500KVA）及相关的配电盘', '价格条款：DDP Sololo付款条件：60%在交付所有设备至现场和经检验后60天内支付，30%在安装和调试成功后支付，10%在缺陷责任期结束后支付。业主延迟付款将不会支付额外利息。缺陷责任期：从业主颁发移交证书(Taking over certificate)后开始12个月', '', '三个阶段：初步评标阶段，技术评标阶段，商务评标阶段初步评标阶段，主要评估投标保函、资质等，在初步评标项目中任意一项不符的投标人将不能进入商务评标。', '{E0C9A11938274894B7B1F4AC6FBE9455074E749A304748709C51373D9D483750}_DAK项目评标流程.pdf', 'N/A', '', '投标保函：金额为投标报价的2%,要求当地银行开出,有效期（投标有效期90天+至少30天）履约保函：金额为合同金额的10%', '', '2年经审计的财报过去五年内有类似工程经验的业绩表和当前合同情况至少4个已提供类似服务的客户的详细联系方式，包括地址，及客户提供的完工证明用于执行合同可用的施工设施和设备证明', '', '', '', '银河投标', '', '待调查', '', '待核实', '', '待调查', '', '', '', '目前在REA无客户关系，需要建立关系。', '', '待调查', '', '', '', '', '通过参与此类项目积累经验，建议立项。', '林丽璇2018-03-21 18:11:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('29', '{73321D9F-3B88-44DD-BF02-8A886CCF1A77}', '61', 'INHE-0432', '2018-03-22 21:46:54', '0000-00-00 00:00:00', '2018-03-27 17:31:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032202/SKI', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '谭东羊2018-03-22 21:55:04', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('30', '{7A904A41-3452-455B-B86E-E4F9B5932A97}', '60', 'INHE-0560', '2018-03-27 18:37:28', '0000-00-00 00:00:00', '2018-04-24 14:16:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032701/SVA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1 研发有能力根据客户需求开发相应产品 2 双方在独家合作方面找到共同方向 3 产品须有MID认证', '与该公司的合作或会成为我司进入欧洲市场的敲门砖，前景广阔，近期该客户将会来我司具体洽谈合作内容，建议立项。', '李美娇2018-03-28 08:53:27', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('31', '{88E372CC-E245-4CC9-AB8E-F14402A9CAF3}', '61', 'INHE-0374', '2018-03-28 17:37:21', '0000-00-00 00:00:00', '2018-03-29 16:48:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032801/SNN', '', '无', null, 'NSN 西风', '建厂设备采购', '{88E372CCE2454CC9AB8EF14402A9CAF38442F4C2B3234363A3D51C033076BD50}_contrat des équipement de rendement .pdf', '', '{88E372CCE2454CC9AB8EF14402A9CAF3074E749A304748709C51373D9D483750}_建厂方案需求申请表（JXIH-E-RE-008）.xls', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户投资建厂决心以及能否搞定订单直采。', '我认为此项目若能做成对SN市场获取订单意义重大，建议公司支持。', '王子强2018-03-28 18:56:16', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('32', '{A0C9E8F9-9691-4621-83CE-CEF6D7B741FA}', '61', 'INHE-0381', '2018-03-29 01:45:08', '0000-00-00 00:00:00', '2018-04-02 09:27:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032901/AOR', '', 'N°AOR/03/EDG/2018', '2018-04-25', 'FOURNITURE DE COMPTEURS POST/PRE-PAIEMENT, ACCESSOIRES DE POSES ET DE BRANCHEMENTS.预/后付费电表，接线安装配件的供货', '1.签订合同后的30天支付25%预付款2.65%发货后通过不可撤销信用证支付3.10%在验货后、签订验收证明后30天内支付。交期：签订合同后的120天。质保：交货后的1年。', '', '1.	对比价格、或给折扣调整后的价格2.交货时间3.配件价格4.维护费用以上四点未详细描述如何评。', '', '此标书只有一个lot,只有一个厂家中标，一个供应商可授权一个投标人。', '', '1.投标保函金额要求为投标总金额的2%。需要在投标有效期（3个月）+28天。2.履约保函：供应商开立合同金额的25%的履约保函。3. 质保一年。', '', '可满足。', '', '1.需要财务部协助开立保函，4月13号以前准备好。2. 需要实验室协助制作样机，4月13号准备好。', '', '银河直接投标', '银河直接投标。', '电力公司自有资金，由电力公司评标委员会决策。', '', '', '', '', '', '此次为银河直接投标，适当给代理佣金，代理处理一线事务。代理在当地与电力公司关系良好，长期有代理工程师在当地负责电表安装。', '', '2015年出差一个半月，但是未深入电力公司关系。', '', '1. IRTON首先进入该市场。法国控股公司VEOLIA为ITRON后台。2.海兴之前通过直采供货8万台，但是由于技术规格不严谨，使用异常。海兴一直在此市场运作，2017年GNB项目招投标，海兴中标。', '', '银河在此市场供货有6万多台，在当地装有银河3套系统。2017年供货5000台表箱。代理在此市场拿下安装电表的项目，且与电力公司有一定的客户关系。根据银河在此市场的口碑产品质量好，以及代理客户关系，只要标书无误，样机OK，价格实惠，拿下该项目是有把握的。', '', '项目成功关键：投标资料确保无误，样机符合标书规格，价格最低。', '希望公司领导同意立项。', '张柳芳2018-03-30 07:07:15', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('33', '{1615C305-6555-4813-B707-AD1111A338A0}', '61', 'INHE-0434', '2018-03-29 14:16:15', '0000-00-00 00:00:00', '2018-03-29 16:54:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032903/APN', '', 'RFQ # PATRP-2018-036', '2018-04-16', 'Procurement of 600 Three-phase Low Voltage CT Operated Energy Meters (DT Metering)', '1. 在买方收到货并认可后30天内付款，没有预付款2. 要求合同执行后60内交付3. 质保24个月', '{1615C30565554813B707AD1111A338A08442F4C2B3234363A3D51C033076BD50}_PATRP_RFQ-PATRP-2018-036_LV CT Operated Meters_Final0315 (2).pdf', '在附件里有说明，技术占60分，商务占40分', '', '买方(Tetra Tech ES, Inc.)有权选择多家中标，或者一家都不中标', '', '我们将以分包商(表计供应商)参与投标', '', '', '', '', '', '代理商投标，银河作为分包商供应表计', '', '', '', '1. 和其中一位客户谈的是30%T/T预付，70%T/T发货前支付2. 与其他潜在客户的付款方式仍在谈3. 对投标人来说，项目文件里规定没有预付款', '', '', '', '', '', '', '', '', '', '', '', '1. 需要尽快安排技术支持解析CT表技术规格，找出当前不满足点2. 有多家客户前来询价，希望公司能尽快报价3. 业务需要尽快核实项目实情，争取延标或者推迟交样时间', '1. 近期有陆续收到该市场询盘，有多位客户询价APN项目2. 阅读项目文件后，认为该项目可以努力去争取，希望公司同意APN立项3. 该市场在几年前咱们有批量供过电表，但而后业务停滞，市场需持续进攻开拓，望公司给予支持。', '钟云林2018-03-29 14:45:47', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('34', '{88130C58-D538-4595-B262-80B3D82403B3}', '61', 'INHE-0654', '2018-03-29 13:34:45', '0000-00-00 00:00:00', '2018-03-30 09:03:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032904/CHE', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '技术规格与CHL提供的样机暂无大差异，需要与代理再进一步确认细节，不需要公司再次研发，但需要支持AMI集抄，望公司领导审批同意立项，便于报价洽谈合同，感谢！', '李明2018-03-29 15:20:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('35', '{4F83630B-5ED4-401F-BDD1-201777F2DF8B}', '61', 'INHE-0695', '2018-03-30 09:04:41', '0000-00-00 00:00:00', '2018-04-02 09:12:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2018033001/EGC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '卿于蓝2018-03-30 10:17:13', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('36', '{A7C47174-C362-4CEB-8D23-FA6A856702BA}', '60', 'INHE-0549', '2018-04-02 09:29:48', '0000-00-00 00:00:00', '2018-04-02 15:57:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018040201/JVE', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '生产前预付款+发货前尾款', '', '', '', '', '', '', '', '', '', '', '', '', '根据客户提供的图片可看出，这应该是我们去年给马里电力公司供的表，由于客户指明需要同款表，而且技术规格要求一样，所以我们只需要翻单即可。我司把表卖给俊威电气，俊威电气再把我们的表和他们的断路器一起出口给他们在马里的一个客户。据俊威说，该客户有个朋友在电力公司，有时候都不用投标直接就下单了，该客户去年在俊威买了65200只断路器，有500多万的货款，样品都没有寄，单子就下了。他这次下单的断路器也有几万个，该客户说要俊威帮他买台电表的样品，俊威希望我司可以提供一台样品，样品费他们出，因为这个是他们老客户，他在他们那边买配套的断路器都是几万的买。如果样品和价格没问题的话，我司直接和俊威签合同。我司报含税人民币价格给俊威，俊威在发货前给我司转账。', '王秀明2018-04-02 10:15:13', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('37', '{3546CF92-E85A-4345-9587-479316DDCF2E}', '61', 'INHE-0654', '2018-04-08 09:55:01', '0000-00-00 00:00:00', '2018-04-09 08:56:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018040802/CHH', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户要去样机交期大约在2个星期左右，希望各位领导审批立项，公司给予支持，谢谢!', '李明2018-04-08 11:08:27', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('38', '{4B43A89E-AA28-4832-A5A8-83C3956078B7}', '61', 'INHE-0593', '2018-04-08 16:44:41', '0000-00-00 00:00:00', '2018-04-09 10:48:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018040803/DDN', '', 'AOI N° 016/DEP/PRMP/DG/CEET/2018', '2018-04-25', 'La Mise en oeuvre d\'un système de protection des revenus (fourniture, installation et mise en exploitation)保护收入系统采购安装运行', '付款条件：预付款：合同签订30天内，收到供货商履约保函及付款请求后，电力公司支付合同总金额10%的预付款；装船：合同总金额80%交单后通过保兑的不可撤销的信用证结算；收货：剩下合同总金额的10%将在收货后的30天内结算，需要获得电力公司验收合格的报告。交期：交期是在验货后的60天内罚金条款：延迟交货的天数*合同CIP金额*1/1000，当罚款达到合同总金额的10%后，取消订单。', '', '1.	在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。2.	接下来评技术部分，技术资料是否满足标书的技术规格 。3.	评财务部分。评完财务文件，价格最低者中标。', '', '一个lot，一家中标', '', '-	投标保函13 500 000francs FCFA无开立行资质要求。-	履约保函金额为5%的合同总金额-	汇率采用截标前十天的BCEAO的汇率, 保函在截标后28天内有效', '', 'a．现金流500 000 000 francs FCFA证明文件b．MDM系统需要有至少管理500000台电表的实施证明汇率采用截标前十天的BCEAO的汇率, 保函在截标后28天内有效', '', '', '', '银河投标', '否', '政府影响大', '', '', '', '', '', '', '', '', '', '', '', '竞争激烈，海兴三星等数十家厂商代表均购买了标书；', '', '银河准备投标资料及保函，代理全力运作拿标。', '这个项目竞争异常激烈，也是TN近几年来的大项目，银河收到了除代理azon外其它两家多哥当地公司的询盘。由于这个是azon的老家，azon以inhemeter的名义购买的标书（凭证他发给了我），我们选择了和azon合作，代理一些资质不符讨论之后我们希望能银河直接投标，代理加强运作。支持立项。', '胡蝶2018-04-08 17:03:46', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('39', '{6650D533-2C57-4ED2-9A8B-6249B71E15B6}', '61', 'INHE-0578', '2018-04-08 16:42:15', '0000-00-00 00:00:00', '2018-04-09 10:48:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2018040804/EXJ', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '覃湘君2018-04-08 17:47:24', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('40', '{25D67216-9F5B-4F12-84B6-910EC6D1A8A3}', '61', 'INHE-0654', '2018-04-10 16:57:29', '0000-00-00 00:00:00', '2018-04-12 08:43:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041101/ADD', '', '7000001560', '2018-04-26', '132#Medidores Integrados de Energía 综合能量计量仪表', '交期：在签订合同的60天后交付。', '', '内部私下评标', '', '取价格最低', '', '代理负责开保函', '', '代理负责开保函', '', '', '', '代理商投标', '', '', '', '', '', '', '', '代理与电力公司关系良好，代理公司也有相应的技术团队。', '', '暂无业务人员在一线，与代理关系较良好。', '', 'HEXING目前是当地最大的竞争对手', '', '银河产品在价格上没有优势，但是产品在性能上做预付费集抄上占有一定优势，技术方面，并且我们在当地通过认证的表是BS安装可更换模块，此次电力公司招标是预付费带集抄系统的。', '', '我们在阿根廷当地做的认证是BS可更换模块电表，需研发提供一份技术解析，对比BS可更换模块表作为集抄预付费表比DIN导轨表的优势在哪里。', '本次投标竞争对手只有海兴，我们电表具有技术优势，海兴目前的产品的集抄功能并不理想，本次投标要加强运作，给出具有竞争力的价格，望公司各部门给予支持与配合，美洲市场较难做，无业务在一线，有项目机会就要尝试，才可慢慢发展起来，吸取经验与寻找不足等。', '李明2018-04-11 10:32:56', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('41', '{30B84C03-1C92-445F-ADC3-5F499BAACE74}', '60', 'INHE-0399', '2018-04-11 11:43:01', '0000-00-00 00:00:00', '2018-04-13 09:50:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041102/DST', '', 'PPM, Lot-06 of Package-C2', '2018-05-07', 'Procurement of supply, installation, testing and commissioning of smart pre-payment meters including related service 供应，安装，测试调试智能预付费电表以及相关服务的采购', '付款条件：1.10% 提前付款，需提供提前付款保函2.	60% on shipment 发货后议付3.	10% R&I report 验收入库28天内4.	20% on installation within 28 days after being checked by purchaser 安装完成又业主检查之后28天内。5.	O&M payment ：1年的维护，培训等服务根据项目进度交期：365天之内完成50%交付，540天之内完成100%交付以及安装和调试。（见招标通知）', '{30B84C031C92445FADC35F499BAACE748442F4C2B3234363A3D51C033076BD50}_DST SCC 付款条件.png', '先技术评审，通过技术评审的投标人进入价格评审，开价格标，低价中标。', '', '1个Lot 1家中标', '', '400,000 USD 投标有效期之后加28天，即2018年12月1日', '{30B84C031C92445FADC35F499BAACE741DD410FC292E4E1893AFBEF9F88431CD}_DST 投标保函要求条款.png', '1.	过去5年内至少1个合同供应/供应&安装预付费电表/智能电表，合同金额达到1000万美元。2.	投标截止日倒推过去5年内至少有在1家电力公司实施预付费电表/智能电表的安装经验。3.	投标人要证明可以满足供应20万台智能预付费电表的产能。4.	提交过去三年财务报表，要求净资产为正数。5.	过去3年内平均年营业额最少达到2000万美元。6.	700万美元流动资产。', '{30B84C031C92445FADC35F499BAACE7403404677E4D44E9EB56B3D512B2AF9CC}_DST 经验和财务要求.rar', '', '', '银河投标', '', '电力部对采购决策有较大影响，ADB对采购决策也具有较大影响。', '', '如上述付款条件', '', 'ADB贷款，有资金支付', '', '合作代理与电力部以及电力公司有较好关系，有助于投标运作，赢得中标。', '', '关系良好', '', '海兴，威胜，科陆，思达等常见对手，加上该项目技术评审没有样机演示，对资质经验和财务要求不高，可以预见会有很多新的大小厂家进来。', '', '较好的付款条件，良好的政府/电力公司关系。', '', '关键仍在价格，可以思考能否为准备后期中标后，制作一款低价的带通讯的预付费电表，以及在报价策略上做一下而支持。中标后本地实施，需要的办事处/项目办公室设立支持。', '建议投标。', '左三维2018-04-11 17:16:52', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('42', '{A3DC2EF0-C946-4109-A2B9-D4B57007FAD3}', '60', 'INHE-0399', '2018-04-11 20:00:03', '0000-00-00 00:00:00', '2018-04-20 10:20:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041104/DEC', '', 'ICT-07/2018', '2018-04-25', 'Design, Manufacture, Supply, Installation, Testing & Commissioning Of Smart Pre-Payment Meters With Related Services On Turnkey Basis Under Deferred Payment System设计，生产，供应，安装，测试，调试智能预付费电表以及相关服务的交钥匙工程的延期付款项目已申请延标。', '无预付款支付给供应商，合同共分为7期分期付款，共还款期为36个月。第1期付款的发票为合同金额的10%，将在合同成功执行且签发临时验收证明之后提供给采购方；剩余的90%合同金额将每隔6个月分期等额支付。第2期付款的15%合同金额的发票将在第1期发票付款之后6个月到期时提供，后续各期的发票的提交时间以此计算方式类推。质保3年交期为签合同后540天之内完成整个项目', '{A3DC2EF0C9464109A2B9D4B57007FAD38442F4C2B3234363A3D51C033076BD50}_重要商务条款.rar', '先评技术标，通过技术评审的投标人进入价格标评审，价格最低者中标。', '', '1家中标', '', '投标保函275,000 USD, 履约保函为合同金额10%，TBEA开立。', '{A3DC2EF0C9464109A2B9D4B57007FAD31DD410FC292E4E1893AFBEF9F88431CD}_保函.rar', '1. 至少有供货/生产150000台智能预付费电表的经验2. 过去5年内须有类似产品的供货经验，有至少2个用户证明（必须是电力公司）以及关联的2个合同，合同包括“设计，生产，供应，安装，测试，调试智能预付费电表/预付费电表/在线智能预付费电表系统”，且至少一个来自投标人所在国以外的国家。', '', '售电中心，用户设置中心，和售电点所需IT物料以及电表安装连接耗材的技术参数应答标，厂家授权。产品资料（如彩页，画册等）全部要英文资料。', '', '联合投标', '延期付款项目融资方案和TBEA洽谈，本地服务和安装和项目运作依靠代理IEEL。', '电力公司自有资金，政府（电力部）对决策影响大。', '', '如上述付款条件', '', '较好', '', 'TBEA 和 IEEL与DESCO均有较好的合作关系，有助于投标运作。', '', '关系良好', '', '海兴，威胜，思达，科陆，开发等常见竞争对手。截至目前除开发在DESCO通过直采模式获得预付费电表这块的订单，DESCO并没有落实一个通过招标采购的项目。', '', '联合TBEA,IEEL解决融资问题，客户关系问题和售后安装维护问题。明确合同的权利义务。', '', '较小的融资成本解决融资问题，获得良好的付款条件，明确责任和义务，管控风险。', '建议投标', '左三维2018-04-18 15:28:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('43', '{36226822-4D69-48ED-BC93-D049ED0F4844}', '0', 'INHE-0717', '2018-04-13 17:17:05', '0000-00-00 00:00:00', '2018-07-03 08:28:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041301/NSI', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '杨浩2018-04-13 17:56:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('44', '{78349F72-4A62-492F-9FEF-27ADA742EDCB}', '79', 'INHE-0605', '2018-04-16 20:04:48', '0000-00-00 00:00:00', '2018-06-14 08:47:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041602/EDM', '', '', '2018-05-31', '', '', '', '', '', '可不招标或假招标', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '介绍人田先生系一家公司员工，在非洲探矿多年，他的交往了10多年的朋友，莫桑比克出生的印度人，关系可至执政党付书记和能源部长', '', '', '', '', '', '1、较大的资金支持；2、有国内光伏厂家合作，这个项目我司可自行选择厂家购买光伏件', '尽快组团前往莫桑比克考察和洽谈', '钟友谊2018-04-17 14:43:52', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('45', '{BCF9F40A-E490-44A1-87B7-872C6AE7FDBA}', '61', 'INHE-0432', '2018-04-17 03:02:54', '0000-00-00 00:00:00', '2018-04-19 09:08:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041701/DAI', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '建议部门立项即可，然后业务申请报价，报给IAC。IAC再自行报给其客户。', '谭东羊2018-04-17 14:43:30', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('46', '{1D71351C-FB47-43D4-A3BC-CC28926E125C}', '61', 'INHE-0725', '2018-04-18 09:47:44', '0000-00-00 00:00:00', '2018-04-19 16:03:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041801/BTS', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 希望公司支持，同意立项BTS2. 付款方式为50%T/T预付款，尾款50%发货前T/T支付3. 客户给予的信息较为充分，提供了竞争对手（华立）的报价，对于当地市场也比较了解，成单可能性比较大，希望领导给予支持，争取成单。', '赵政洁2018-04-18 10:05:57', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('47', '{B0FD9527-F200-4DC3-B29F-C2E5A39D4D5C}', '61', 'INHE-0710', '2018-04-18 09:58:21', '0000-00-00 00:00:00', '2018-04-19 09:07:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041802/IOA', '', 'N°AAO/02/EDG/2017', '2018-04-24', 'Acquisition de Transformateurs， 采购变压器', '1. 25%预付款：合同签署30天内支付 65%发货后通过不可撤销的信用证支付；10%收货30天内支付并提供签收证明 2.交期：最迟签订合同的90天 3.质保：交货后1年，修理或换货时间：45天', '', '1.买方对比价格 2.其他因素：供应品的特性，性能，相关服务以及购买条件。如若考虑到上述条件，考虑以货币的形式进行比较', '', '此标仅有一个Lot,一家制造商可授权一个投标人', '', '1.收到买方合同的28天内提供履约保函，金额为合同金额的10%，时间（90天+28天）位于买方国家境外的保证机构或保险公司必须在买方国家设有代理机构 2.投标保函：金额为合同金额的2%', '', '符合', '', '1. 需要请财务部门协助开立保函', '', '银河直接投标', '银河直接投标', '电力公司自有资金，由电力公司评标委员会决策。', '', '', '', '', '', '此次为银河直接投标，适当给代理佣金，代理处理一线事务。代理在当地与电力公司关系良好，长期有代理工程师在当地负责电表安装。', '', '项目负责人张柳芳于2015年出差一个半月，但是未深入电力公司关系。', '', '1.IRTON首先进入该市场。法国控股公司VEOLIA为ITRON后台。2.海兴之前通过直采供货8万台，但是由于技术规格不严谨，使用异常。海兴一直在此市场运作，2017年GNB项目招投标，海兴中标。', '', '银河在此市场供货有6万多台，在当地装有银河3套系统。2017年供货5000台表箱。代理在此市场拿下安装电表的项目，且与电力公司有一定的客户关系。根据银河在此市场的口碑产品质量好，以及代理客户关系，只要标书无误，价格实惠，拿下该项目是有把握的。', '', '项目成功关键：投标资料确保无误，产品符合标书规格，价格最低。', '希望公司领导同意立项。', '张灿川2018-04-18 10:07:18', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('48', '{C4327859-D882-4E54-958F-659F883DCD82}', '66', 'INHE-0634', '2018-04-18 15:33:15', '0000-00-00 00:00:00', '2018-04-19 09:07:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041803/DYZ', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '我司已有现成产品，不需再次进行研发。本款表计在APE项目中，被缅甸电力局认可，除本次DYZ客户的需求，目前已知还有3家当地特许经营公司向阿尔法（APE项目中的本地合作公司）要求直接采购同款三相电表，相信后续会有更多需求，市场前景可观。建议立项。', '陈雁2018-04-18 15:58:31', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('49', '{F463B181-1075-4B5A-9D4C-2943B345D9BA}', '66', 'INHE-0634', '2018-04-18 16:03:54', '0000-00-00 00:00:00', '2018-04-19 14:02:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041804/PAR', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '在缅甸，仅有35%的地区有相对稳定的电力供应，剩余地区都是由柴油发电机或者是太阳能供电，均需预付费方案。我司表计在APE项目中被缅甸电力局所认可接受，被人所知，可通过本项目更进一步强化银河品牌，未来缅甸剩余65%区域预付费表计的需求银河都有很大机会争取拿下。建议立项。', '陈雁2018-04-18 16:39:10', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('50', '{D6165CB6-2B5E-4273-A4F5-B259ECDA28A0}', '61', 'INHE-0434', '2018-04-19 09:14:21', '0000-00-00 00:00:00', '2018-04-19 16:04:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041901/MAP', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 该市场MAP新规为真实信息，预计在接下来6个月确定MAP公司名单，希望公司支持该客户MAP项目；2. 除MAP项目，该客户近期还正与我司讨论电表直采订单（SPO项目，待立项），客户通过在市场上宣传、推广我司产品，获得了政府直采机会（首批预期50,000台电表）；3. 综合以上，希望公司支持同意立项MAP；', '钟云林2018-04-19 09:32:32', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('51', '{555516C9-73C4-4918-BF5C-1598550D851E}', '61', 'INHE-0500', '2018-04-21 02:39:40', '0000-00-00 00:00:00', '2018-04-24 14:17:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042101/NWH', '', 'NCS/ONB/COW –28/2018', '2018-05-09', 'BACK END SYSTEM FOR PREPAID ELECTRICITY VENDING FUNCTI预付费后端售电系统', '价格条款：CIP不含VAT和关税付款主体：City of Windhoek付款条件：收到发票和相关单据30天内付款交期：3个月内完成项目的整体验收质保：投标者提供自定义的质保和售后服务', '', '技术评标占比：65%；价格评标占比：20%；BEE评标占比：15%。', '', '一家系统供应商中标', '', '投标人需开立投标保函或者投标保证申明', '', '投标人或者其合作供应商需要至少有5年类似项目或服务经验，在过去5年内至少执行过三个同类型的项目，需要提供STS证书', '', '1.需要客服部和软件部提供一份关于银河STS售电系统的项目详细技术方案，请注意此方案里面需要包含符合STS标准的预付费水表的水费收费；2.以上技术方案需要在5月4日前提供。', '', '代理直接投标，银河做厂商授权，当前有两家备选代理，待确认最终的合作代理', 'N/A', 'Procurement Management Unit主导，成立Tender Committee，由PMU成员、财务部成员、电力部成员组成，进行初审，终审由市政委员会主导的Central Procurement Board进行复核和批准，最终授权PMU进行中标公布。', '', '待和代理沟通后更新', '', 'COW为首都市政，也是6个配电和售电主体中最大的一家，管理超过5万台电表，电费收费年均N$ 480,000,000.00。其他客户市场调查信息有待进一步跟新。', '', '1.BEE资质强制性要求：代理100%满足评标占比15%比例；2.代理公司技术实力：ICT背景，已有Airtime第三方通讯服务经验，可做为银河本地系统长期合作伙伴；3.代理商务实力和电力公司客户关系：待继续跟进验证。', '', '1.纳米比亚属于银河新市场，以前无较大项目投标或小项目试点/直销，目前对当地电力公司的组织架构、核心负责人、采购流程和本地细致的评标规则相关资料暂缺；              2.17年立项NEA项目，通过另外一家本地白人公司推进预付费电表项目，供过一台DIN III分体式（PLC代码表）和一台四表位表箱，暂无新进展；                                 3.18年年初投标ERED项目，STS预付费售电系统，当前评标中，暂无进展反馈。', '', '可能的竞争对手是：Tusk mobile, Starlite Prepaid, Nampost, First National Bank, Standard Bank, Bank Windhoek, Woerman Brock,Mobipay and NedVend.其中最大的竞争对手为代理反馈可能的竞争对手是：Starlite Prepaid（背后是南非Syntell系统公司，当前Erongo RED老售电系统服务提供商），预测客户关系较强；其次是NedVend，此公司目前是兰吉尔和Itron本地市场的电表合作代理，已有部分供货历史，预测也是银河较强劲的竞争对手之一。', '', '1.寻找符合本地BEE资质，有一定技术实力和商务能力的代理，目前来看当前代理初步合格；2.银河的供货资质和记录，以及价格上预计有一定优势；3.劣势：对于银河属于新市场，以前无较大项目投标或小项目试点/直销，目前对当地电力公司的组织架构、核心负责人、采购流程和本地细致的评标规则相关资料暂缺，需要借助ERED项目的合作代理进一步详细了解，根据项目情况年后从南非办事处调派市场人员出差拓展此市场。						4.银河2018年借助南非办事处，周边国家如纳米比亚是潜在开发市场之一，市场需求容量等信息请见附件纳米比亚市场调查报告。', '', '1.本地代理的客户关系实力和投入能力有待验证，此市场较小，银河需要找到有竞争力的代理进行合作；2.投标资料和方案在现阶段也至关重要，需要提供全套的有说服力的银河售电系统技术方案。', 'STS预付费售电系统招标，请公司审批！', '李忠鹏2018-04-21 03:55:56', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('52', '{79CB23EF-E522-42C4-A0DF-316D0D63D8A7}', '61', 'INHE-0432', '2018-04-26 00:10:46', '0000-00-00 00:00:00', '2018-04-27 14:03:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042603/LEA', '', 'KP1/6E.3/PT/2/18/A65', '2018-06-19', 'Procurement of Single Phase Pre-Paid Meters and Miniature Circuit Breakers for The Last Mile Connectivity Project (AFD/EU) 最后一公里电表采购项目（法国发展机构资金）', '1）	报价DDP：KPLC Nairobi South Stores at Industrial Area, NAIROBI。2）	厂商负责清关等。但KPLC将提供以下免税涵：1.	关税。2.	IDF3.	RDL4.	VAT3）报价货币单位：肯先令，或者欧元；最终评标时会将报价统一转换成先令。转换汇率按截标当天肯尼亚中央银行汇率计算。                                                4）交期：签合同起后的9-18个月交货                                               5）付款                                                                         1.签合同起60天内付10%预付款2.	发货且提供相关单据后的60天内通过信用证付80%3.	交货且被验收后后60天付10%4.	如果付款延期，KPLC需在60天内支付相关利息', '', '一审：报价、交期（必须满足要求）二审：审核财务、供货经验等', '', '1.满足交期、商务、技术要求；2.最低价中标；3.最终将两个包合一起，只授予一个总合同给1个投标人。', '', '1）投标保函金额：175,000欧元；或者等值的其他货币；2）履约保函：总合同金额的10%', '', '财务要求一、过去3年财报（1）	流动资产比率：大于或等于1.1（2）	负债比例：小于或等于80%二、过去5年财报：年营业额至少2000万欧元三、供货记录：提供过去5年里的至少1个合同金额大于1600万欧元；或者两个合同，每个合同800万欧元以上。供货记录：过去5年至少和标书规定数量一致，电表至少供货：197,494；断路器至少供货：394,988。技术：KF03技术规格', '', '电子投标', '', '银河投标', 'N/A', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目不需要样机，预计将是价格战。希望公司能降低成本，提供较好的价格。注：OA老是崩溃，无发上传技术规格。将另起OA邮件发技术规格。', '谭东羊2018-04-26 13:19:41', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('53', '{BDB497BD-C997-41A6-8C37-5ADF93F17F24}', '61', 'INHE-0432', '2018-04-26 01:00:26', '0000-00-00 00:00:00', '2018-04-27 14:04:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042603/LME', '', 'KP1/6E.3/PT/3/18/A66', '2018-06-19', 'Procurement of Single Phase Pre-Paid Meters and Miniature Circuit Breakers for The Last Mile Connectivity Project (AFD/EU) 最后一公里电表采购项目（法国发展机构资金）', '1）	报价DDP：KPLC Nairobi South Stores at Industrial Area, NAIROBI。2）	厂商负责清关等。但KPLC将提供以下免税涵：1.	关税。2.	IDF3.	RDL4.	VAT3）报价货币单位：肯先令，或者欧元；最终评标时会将报价统一转换成先令。转换汇率按截标当天肯尼亚中央银行汇率计算。                                                4）交期：签合同起后的9-18个月交货                                               5）付款                                                                         1.签合同起60天内付10%预付款2.	发货且提供相关单据后的60天内通过信用证付80%3.	交货且被验收后后60天付10%4.	如果付款延期，KPLC需在60天内支付相关利息', '', '一审：报价、交期（必须满足要求）二审：审核财务、供货经验等', '', '1.满足交期、商务、技术要求；2.最低价中标；3.最终将两个包合一起，只授予一个总合同给1个投标人。', '', '1）投标保函金额：88,000欧元；或者等值的其他货币；2）履约保函：总合同金额的10%', '', '财务要求一、过去3年财报（1）	流动资产比率：大于或等于1.1（2）	负债比例：小于或等于80%二、过去5年财报：年营业额至少2000万欧元三、供货记录：提供过去5年里的至少1个合同金额大于800万欧元；或者两个合同，每个合同400万欧元以上。供货记录：过去5年至少和标书规定数量一致，电表至少供货：10万台；断路器至少供货：20万台。技术：KF03技术规格', '', '电子投标', '', '银河投标', 'N/A', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目不需要样机，预计将是价格战。希望公司能降低成本，提供较好的价格。注：OA老是崩溃，无发上传技术规格。将另起OA邮件发技术规格。', '谭东羊2018-04-26 13:16:49', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('54', '{F8AB11CC-20E2-4BE7-A4EF-8FF23D9DE9DA}', '61', 'INHE-0593', '2018-04-27 10:26:58', '0000-00-00 00:00:00', '2018-04-28 08:48:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042702/BCD', '', '681/18/SBEE/DG/PRMP/DAOAS/SRDAOPV/SP', '2018-05-07', '681/18/SBEE/DG/PRMP/DAOAS/SRDAOPV/SP', '预付款：合同总金额30%预付验收后付款65%质保期（12个月）后付款5%为电力公司和代理的结算方式；提醒代理是否需要澄清', '', '样机通过验收，文件通过认可，价格方面未提及', '', '一个lot 一家中标', '', '无要求', '', '无要求', '', '无', '', '代理商投标（实则为贝宁电力公司直接向代理商邀标）', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '样机', '本项目为年初贝宁电力公司找代理紧急采购14500台单相一体式代码智能表后，直接向代理邀标。中标机会大，支持立项。有一些点需要澄清，我们会发出澄清函并希望电力公司延标。', '胡蝶2018-04-27 10:50:01', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('55', '{DD301D77-DCB6-4149-84F2-61EB99740B6D}', '61', 'INHE-0381', '2018-04-27 10:13:16', '0000-00-00 00:00:00', '2018-04-28 15:57:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042703/CFC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.中非电力公司直接向以下厂家邀标：代理REXEL EXPORT TOULOUSE、印度genus、南非CONNECT AFRICA TECHNOLOGY.2.代理REXEL EXPORT TOULOUSE通过azon向银河询价', '张柳芳2018-04-27 11:16:42', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('56', '{6F06019C-FC48-4F49-8825-7A4F382CD302}', '61', 'INHE-0725', '2018-04-27 11:43:53', '0000-00-00 00:00:00', '2018-04-28 15:46:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042704/KNL', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.希望公司给予支持，同意立项KNL项目；2.客户给出的是50%T/T预付款，尾款50%T/T发货前支付；3.客户对于该项目积极性较高，对于市场较为了解，成单几率较大，希望领导给于支持，争取成单', '赵政洁2018-04-27 14:46:46', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('57', '{E53BEF23-7DC0-4036-86BB-2A20EB0CDA16}', '61', 'INHE-0434', '2018-05-02 13:33:04', '0000-00-00 00:00:00', '2018-05-28 08:51:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050202/PAG', '请钟云林和客户协商，减少试点种类，争取扩大数量（单品超过100台）；费用客户承担。', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '合同将采用30%T/T预付款，70%尾款发货前支付', '', '', '', '', '', '', '', '', '', '', '', '', '1. 近期与代理合作JJN系统投标项目，与代理从11年就开始合作，碍于当时电力公司对表厂成立时间要求(5年)，所以之前合作中断。出差后与代理多次当面沟通并去现场考察，当前定了采购数量和产品类型。希望公司支持PAG项目立项。2. 代理不想购买太多产品（说服了代理每款采购100台），因为想先测试(和代理商量后同意我们准备样机发空运在本地测试，同时签署合同。历史事件：11年给客户供货的产品，客户认为存在质量问题/代码表产品材质，键盘失灵)。3. 关于价格，和代理公司老板沟通后得知，本地推广分表业务如果要收取类似售电系统年费，势必行不通，本地终端用户不接受这一套。所以最终和代理商议，售电系统免费，但产品价格上涨10美金。4. 付款为30%预付，70%尾款发货前支付（代理不同意55开，代理有和一些中国公司合作，都是37开，CHNT给他们的尾款支付时间是发货后150天，代理为CHNT在当地的独家代理，合作超过5年以上）。5. 代理希望我们不打银河LOGO，此事被我否了（该市场CLOU产品不带CLOU的LOGO，而是其代理公司LOGO），此事等后面量上来再说。与此同时，YTL（永泰隆）此前有提供过一', '钟云林2018-05-24 19:19:54', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('58', '{D7EB8E54-BE05-4FAC-B1AC-79D80D01C6FD}', '61', 'INHE-0593', '2018-05-02 15:16:33', '0000-00-00 00:00:00', '2018-05-08 11:39:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050203/FDN', '', 'DAOI N° BJ-PIU-35998-GO-RFB', '2018-06-13', 'DOSSIER D’APPEL D’OFFRES INTERNATIONAL POUR LA FOURNITURE DE SOIXANTE QUINZE MILLE (75 000) COMPTEURS ELECTRONIQUES A PREPAIEMENT DE TYPE STS AU PROFIT DE LA SOCIETE BENINOISE D’ENERGIE ELECTRIQUE (SBEE)', 'CIP SBEE电力公司仓库 Cotonou (Bénin)付款主体：世界银行 PASE付款条件：预付款：合同签订后收到等额的买方认可的履约保函后30天内付款合同总金额20%交货后：收货后及收到规定的文件后付款合同总金额的70%电力公司给供货商签收验收证书后的30天内会付款尾款10%结算方式过于苛刻，澄清中交期：交期：合同签订后的6-7个月超过最迟交期后每周罚款合同总金额的0.5%当罚款金额达到5%时取消订单质保：全部交货或部分交货后12个月或者从原产地发货后的18个月二者中较早到期的一个为质保期', '', '1. 要符合招标文件的要求；2.价格最低者中标', '', '一家中标，一家制造商可以授权多个代理投标', '', '投标保函：60 000 000 FCFA， 汇率采用5.15日西非中央银行的汇率履约保函：履约保函金额为合同总金额的20%', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '支持立项，建议项目组成员：胡蝶，苏宏，张灿川', '胡蝶2018-05-02 15:41:03', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('59', '{6DB2EE6C-BF18-431E-866B-8D26BAD06168}', '61', 'INHE-0434', '2018-05-03 14:40:54', '0000-00-00 00:00:00', '2018-05-08 11:39:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050304/SIC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 客户想和银河在当地做DA项目，业务和客户沟通先从电表业务做起。客户同意从银河采购电表先做本地测试。2. 客户将承担产品费用以及本地认证费用，待本地测试通过后，将讨论4000台电表的采购3. 客户将全额支付SIC产品费用。4. 希望公司支持，同意SIC项目立项。', '钟云林2018-05-03 15:11:04', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('60', '{AF4CB3E4-07BE-41F7-ACFF-DAA0712EE2F8}', '66', 'JXINHE-2559', '2018-05-04 13:50:31', '0000-00-00 00:00:00', '2018-05-08 16:20:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050401/MLG', '', 'IV2-PERIP/2018', '2018-05-25', 'Bidding for Supply, Installation and Commissioning of Automatic Meters Reading (AMR)自动抄表系统的供应，安装和试运行', '1.价格条款，标书为CIP MAPUTO/BEIRA/NACALA,经与代理商议，以CIP MAPUTO报价2.付款主体，标书为EDM，代理表示付款方式稍后再确定。3.交期，中标后一年4.质保，交付后三年', '{AF4CB3E407BE41F7ACFFDAA0712EE2F88442F4C2B3234363A3D51C033076BD50}_MLG标书.pdf', '详见标书P49-64,SECTION Ⅲ EVALUATION AND QUALIFICATION CRITERIA', '{AF4CB3E407BE41F7ACFFDAA0712EE2F8074E749A304748709C51373D9D483750}_Clarification Note 001.pdf', '一家中标', '', '1.投标保函，5万美金，截标日后148天，代理同意负责开具2.履约保函，10%的合同金额，完工后540天或验货接受后365天，暂未与代理协商', '', '1.过去三年，年营业额超过1120万美元，流动资产/流动负债大于等于1；总负债/总资产小于等于0.9；流动资金超过320万美金。2.过去六年，至少成功执行过两个超过600万美金的类似合同或3个300万表美金类似的合同或4个150万的类似的合同；为两个电力公司供应过AMI智能电表并在运行，电表数量不少于2万台。详见标书，55-61页', '', '1.电流互感器，电压互感器，塑壳断路器的技术应答表和型式测试报告，5月15日。', '', '代理商投标', '', '世界银行援助项目', '', '客户按标书规定付款给我司。详见P287-288页', '', '世界银行出资的项目，偿付能力良好。', '', '代理为电力公司实现过2万台的批量供货，关系良好，团队高效配合，老板年纪40岁左右，精明能干。', '', '代理态度较傲慢，但对公司管理层较为尊重，需全力应对。', '', '此次要求电表集成到华为的MDM系统中，已知进入该市场的中国表厂有思达，海兴，国外表厂有兰吉尔，ACTACR等，价格和技术竞争激烈。', '', '基于已批量供货的背景下，凭借代理强大的商务动作能力和有竞争力的价格，全力运作以中标。', '', '完善的技术方案和有竞争力的价格。', '项目为电力公司AMI框架下第一个智能电表的招标，基于代理的强大实力，项目运作空间良好，市场潜力大。', '淦永妍2018-05-08 09:46:35', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('61', '{7A147059-8B6B-46BA-8229-772A7AF82830}', '61', 'INHE-0662', '2018-05-08 09:06:56', '0000-00-00 00:00:00', '2018-05-14 09:03:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050802/HEN', '项目组长汤伟', '2018/S 067-149716', '2018-05-31', 'Ellevio Next Generation AMM Solution(Ellevio新一代AMM方案）', '待拿到标书后确认', '', '待拿到标书后确认', '', '待拿到标书后确认', '', '无', '', '1. Annul Report年报 2016/2017（达到1亿欧元） 2. References项目经验 3. Delivery Capacity 生产额 4. Credit Assessment信用评估（国际2A评级，得到Ellevio认可）', '{7A1470598B6B46BA8229772A7AF8283003404677E4D44E9EB56B3D512B2AF9CC}_AMM2G_Announcement_Instructions_AMM.pdf', '1. Annul Report 年报 2016/2017（达到1亿欧元） 4. Credit Assessment信用评估（国际2A评级，得到Ellevio认可）', '', '联合投标', '银河为主投方，代理和安装方为分包商', '对于大标来说，一般首轮会是RFP，提交申请书，提供资质资料。然后通过打分，选出能进入下一轮的供应商，参与正式投标。最终选出最后的合作方。目前来看，政策对决策较有影响力，本次的招标即是为了响应Ei的要求。', '', '待拿到标书后确认', '', '客户支付能力OK，现金流达到1.75亿欧元。', '', '我们的代理跟瑞典的几十个电力公司有过合作，包括最大的电力公司EON。不过，还未跟Ellevio建立正式合作关系，借此次契机，正好可以熟悉和发展。代理很年轻，比较有冲劲，不是斤斤计较之人。', '', '努力拉近中', '', '瑞典市场已经有海兴，兰吉尔，Iskra,Itron,Aidon, ADD等电表厂家，除海兴外，均参与了瑞典第一次智能电表的部署，据代理反馈，海兴在瑞典市场也有一定市场份额。至于客户关系，目前还在确认。', '', '好好准备RFP所需资料，争取进入下一轮正式招标环节，凭借电表质量和价格优势，同时与代理一起做好客户关系，杀出重围。同时也可以看到银河的劣势明显，首先是在欧洲的市场份额劣势，再次是国际大表厂的来势汹汹。', '', 'RFP是通往正式招标的入口，满足RFP的基本要求是进入应标商的必要条件。目前银河在欧洲市场并未深入，我认为现阶段只能先满足人家的硬性条件，跨过门槛，才能跟欧洲主流电力市场缩短距离。对我们银河来说，Ellevio的RFP的两个主要门槛要求在于去年的营业额以及良好的信用评级证书。所以需要协助提供去年的财报以及信用评级证书，以及我们参与的类似项目的资料。', '像其他的国际性招标一样，Ellevio先要考察应标商的资质.目前手上的文件为RFP（request for proposal）.文件中列明了此次招标的电表数量，系统要求，references要求，商务要求（评级，营业额），可接受的参与方式以及评分规则等。届时Ellevio会根据得分高低选择备选供应商，发给正式的招标文件。此次虽然为国际性招标，要求严格，但是却是我们试探和参与欧洲大标不可多得的机会，也能积累相当的经验。此次的递交途径为网上工具，无需样机，保函，只需准备资料，时间比较充裕。', '陈丽2018-05-10 09:01:14', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('62', '{EB90DA80-5532-42C3-A473-B488B9883452}', '61', 'INHE-0381', '2018-05-08 11:11:19', '0000-00-00 00:00:00', '2018-05-10 13:35:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050803/MSQ', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.随着电力公司数据量的增加，现有服务器架构无法承担运行该数据量的运行。因银河在CDN实施了大量的系统，电力公司提出由银河负责实施数据库服务器的架构。一个供应商统一服务管理。这样可以避免服务器和系统不同供应商，出现问题无法找出问题根源。2.附件方案是前期黄总在现场跟客户沟通后给出的方案。3.此项目电力公司要的比较急，希望能尽快给出技术方案和报价，便于后期执行。', '张柳芳2018-05-08 11:25:16', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('63', '{2AE95F47-1E34-49AD-9B9A-3CCF9812A2DC}', '61', 'INHE-0695', '2018-05-08 19:16:24', '0000-00-00 00:00:00', '2018-05-15 09:54:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050804/FLP', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '卿于蓝2018-05-09 09:26:37', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('64', '{8B111C58-12C5-41ED-812C-4BF6E280D7AD}', '61', 'INHE-0440', '2018-05-09 02:17:59', '0000-00-00 00:00:00', '2018-05-10 13:35:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050901/TTA', '', 'PA/001/18/HQ/G/02', '2018-05-25', 'SUPPLY OF SINGLE PHASE ENERGY METERS AND THREE PHASE ENERGY METERS UNDER FRAMEWORK CONTRACT 框架合同供应单相电表和三相电表', '电力公司付坦先令。借助经销商的经济实力，争取运作成交货后30-60天付款。具体付款条件待拿到标书商务部分草稿后再确认。参考TTN项目国内付款条件为： (1)按季度供货产品10%的合同金额，在签订合同后的30天内支付，需提供相对应的收据和银行担保后。(2)40%的合同金额，在发货时提供GCC Clause 12里面所需要的文件后30天内支付。（3）50%的合同金额，收货后在提交付款申请和电力公司的验收证明后30天内支付。1.	质保期限：自接受货物起12个月，发货后18个月。', '', '国内限制性招标，ITL和EDMI两家厂商参与。先评估技术，然后评估商务，实际上是商务和技术一起评估。电力公司希望授标的价格为53-55美元，ITL和EDMI需参考授标价格报价，数量平分给两家本地厂商。', '', '只允许本地厂商投标，目前符合资格要求的只有ITL和EDMI,每家一个LOT, 单相表175，000台和三相表1500台。', '', 'ITL/Africarriers 开保函，金额1百万美元，保函有效期：投标有效期后30天，即150天。', '', '本地新工厂，无财务和证书资质要求，财务资料来源于投资商，技术资料主要来源技术合作伙伴，电力公司保函金额要求高，具体拿到标书商务草稿后再确认。', '', '非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持代理商投标，代理商中标后，从银河采购SKD或整机', '', '电力公司为国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算，有较多的债务需要偿还，最近收了很多欠款回来，整体朝好的方向发展。具体参考评标流程。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', '电力公司有财务总监支持，争取运作成交货后30-60天付款。具体付款条件待拿到标书商务部分草稿后再确认。参考TTN项目国内付款条件为： (1)按季度供货产品10%的合同金额，在签订合同后的30天内支付，需提供相对应的收据和银行担保后。(2)40%的合同金额，在发货时提供GCC Clause 12里面所需要的文件后30天内支付。（3）50%的合同金额，收货后在提交付款申请和电力公司的验收证明后30天内支付。本地供应商的付款，在提交每个阶段的资料后，30天内TT支付。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，有自己的银行，每季度几百万美金的款项可以支付出来。', '', '代理商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。代理和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是TB主席，电表部经理，实验室，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者退休的配电副总，用服总监，电力化部门经理。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理。TTN项目单相表FOB 41美元。EDMI主要是供三相分体式直通/CT/VT表，上次投标，三相直通DDP 310 美元，单相表FOB 45.26美元。威胜TF项目BS单相分体加表箱价格DDP 52 美元，FOB 41 美元左右。TTN项目FOB 36美元。科陆农电项目BS单相分体加表箱价格FOB 39 美元，LTA项目FOB 48 美元。TTN项目FOB 32.5美元。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签SKD合同和安排付款，囤货1万台SKD，预计5月中下旬会增加囤货数量，满足供货要求。已经在争取运作为3年框架合同，同时加入较难的商务条款，如交货后30-60天付款，投标保函金额1百万美元等。标书的技术规格，我司满足应该没有困难，和TTN基本一致。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以在未来3-5年获得稳定的订单来源。', '', '产品报价符合市场形势，样机制作按时交付，商务和技术支持人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标，同时运作标书技术和商务条款。', '汤伟2018-05-09 04:39:17', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('65', '{29128DC3-535C-4DBA-A4F1-A6DEA69B4755}', '61', 'INHE-0500', '2018-05-09 15:15:06', '0000-00-00 00:00:00', '2018-05-10 13:36:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050902/COE', '', 'A-EE 10-2018', '2018-05-17', 'APPOINTMENT OF SERVICE PROVIDERS FOR THE SUPPLY, DELIVERY AND OFF-LOADING OF ELECTRONIC ENERGY DEMAND METERS WITH REMOTE METER READING CAPABILITIES AND SPLIT PREPAYMENT METERS ON AN AS AND WHEN REQUIRED BASIS FOR A PERIOD WITH EFFECT FROM 1 JULY 2018 UNTIL 30 JUNE 2021三年期带AMR功能智能电能表和分体式预付费代码表供货、发货、卸货招标', '价格条款：DDP付款主体：COE市政                                                            交期：电表为收到COE市政下达PO后21天内完成交货；                                付款条件：收到供应商发票后30天内支付（兰特币）                                  质保：电表需提供发货后18个月/交货后12个月质保；且需说明备品在多长时间内可提供给市政电力公司；系统需提供一年免费运维质保。', '', '1.评标分3步：投标文件及资质等考核；技术评估；倾向性评估（BBBEE资质等，按照90/10规则打分，该部分占10分）；', '', '总共分为10个Lot，未规定几家供应商中标，预计允许多家厂商中标分Lot', '', '投标方中标后需在30天内开具履约保函', '', '需本地CSD注册，BBBEE资质公司；需提供财报，供货记录等；2.电表需提供测试报告（按照SANS测试要求）生产设备还需提供IEC测试证书及ISO9001证书。', '', '技术部分资料需协助（产品方案，测试报告，应答表，生产设备资质证书等）', '', '代理NYC直接投标，银河作为散件厂商支持', 'N/A', '由市政自行评估、决策；在决定投标者资质方面受国家财政部要求影响。', '', '1. 市政在收到发票后30天内付款，本地币兰特；2.若中标，银河直接与NCY交易，美金', '', '此项目为市政公司自筹资金，无需外部或者供应商做卖方融资，关于COE市政公司的支付能力和财务财务能力详细信息待后续持续跟进。', '', 'NYC与市政有一定的客户关系，但无供货基础，还需深入客户关系的建设和产品等推广。', '', '此市政银河当前未有接触过，代理NYC有初步的人脉，June已在此市场出差，会和代理NYC一起做客户关系的建设。', '', '此市政的主要竞争对手为海兴和兰吉尔，海兴和兰吉尔是此市政公司的主要电表供应商，在2014年开始有三年期合同供应，客户基础关系比较好。', '', '1.COE市政公司为南非六大大都市市政公司之一，是银河主要目标市政之一，按照银河和NYC签署的合作协议和行动计划，2018年会对6个大都市市政的投标项目进行重点跟进；2.NYC当前南非工厂已运行流畅，ESA项目已基本执行完毕，积累了一定的资金、客户和品牌影响力；3.当前银河在此市政的劣势为无客户关系和供货历史，对此市政的核心人员、决策流程和产品功能需求不清楚，需要加强对此市政人员关系建设、决策信息探查和产品方案宣讲的力度。', '', '1.产品方案和技术问题预计不大，价格相对海兴需要具有竞争力；2.需要和NYC探讨关于SABS证书的问题，此项为强制性条款；3.此市政核心人员关系的建设，此为项目的重中之重，需要和NYC一起做公关。', '当前南非6大市政公司，银河已和代理NYC投标了TSE（茨瓦尼），此次COE市政为第二个，属于银河在南非的核心目标市政公司之一，请公司批准！', '李忠鹏2018-05-09 16:35:37', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('66', '{EC076CBD-3519-492A-978A-DDB476B2734B}', '61', 'INHE-0654', '2018-05-09 15:25:01', '0000-00-00 00:00:00', '2018-05-15 10:30:14', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050903/COL', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'EPM是哥大的国电，银河此前有供货给该电力公司，并且电力公司有使用我们的SMARTVIEW系统，现电力公司做了一份电表数据管理方案的市场调查，包括一些数据的采集，执行等，见附件。电力公司计划买一套MDM系统，了解到银河也有自己独立的系统，也有开发软件的能力，业务认为软件部可以看一下电力公司的要求，我司是否能满足客户的需求，所以申请立项，需软件部协助做技术应答，而后与电力公司推广，请各位领导审批。', '李明2018-05-09 18:02:35', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('67', '{E40D106E-44A9-422D-9E51-7227E7BA9AA1}', '60', 'INHE-0514', '2018-05-10 18:45:48', '0000-00-00 00:00:00', '2018-05-15 10:30:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051001/IDC', '', '8/2018', '2018-05-16', 'Supply of Cabinet with 10 single-phase DIN-Rails meters and 3G data collector/供应带十个DIN导轨表和3G采集器的表箱', '价格条款CFR，CPT可选，目前我方选择是CFR到约旦亚喀巴港口，付款主体是IDECO电力公司，付款条件标书初步规定是IDECO出具验收证书后2周内付款100%，或者开立不可撤销的加保兑的LC，电力公司将验收证书交给银行后两周内付款；交期要求是2-3个月，质保期：发货出厂日起十五个月内或从工作日起十二个月内（以较晚者为准），包括运输的时间；如果出现延期，每周扣除延迟部分合同金额的0.5%， 但最多不超过10%；', '{E40D106E44A9422D9E517227E7BA9AA18442F4C2B3234363A3D51C033076BD50}_项目相关情况汇总.docx', '只说明电力公司不一定按最低价评标。', '', '说明无', '', '履约保函为合同金额的10%，履约保函的有效期是在IDECO仓库接收最后一批货物后至少一年。', '', '要求提供过去五年类似产品的供货记录，国外投标人需要通过当地注册的代理或者投标人在当地注册的办公室进行投标。', '', '投标资料目前正在准备，最迟5.15号之前提交。', '', '银河投标', '', '主要在于电力公司自身决策', '', 'IDECO出具验收证书后2周内付款100%，或者开立不可撤销的加保兑的LC，电力公司将验收证书交给银行后两周内付款；', '', '无具体信息', '', '合作伙伴之前是海兴的代理，为海兴拿过标，在各电力公司都有一定的关系和资源；', '', '', '', '主要竞争对手是海兴，华立和Iskara', '', '根据技术规范，产品以及技术要求对我们没太大的差异，从商务来讲，我们目前的代理做过主要竞争对手海兴的合作伙伴，对海兴相对了解，尤其是海兴在Jepco系统问题，在投标以及运标过程中我们会相对占有主动；针对华立来讲，在导轨表方面，我们在技术上占有优势，产品各项性能均要好于华立；Iskara方面，我们的优势在于价格，当然，技术方面，我们也没有劣势。综合商务技术来看，该项目银河值得参与。', '', '合作伙伴的运作，与合作伙伴以及客户共赢，客户满意的产品方案', '', '李成兵2018-05-10 19:37:05', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('68', '{A018F160-45DB-4B4B-921E-11564CC5116E}', '61', 'INHE-0695', '2018-05-11 13:28:07', '0000-00-00 00:00:00', '2018-05-16 18:13:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051101/YKA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '代理商投标', '', '', '', '', '', '', '', '', '', '', '', '该国主要的竞争对手为ADD（摩尔多瓦表厂）及几个本地表厂NIK, Teletech, Energo Vinnitsa。 其中最大的为ADD，ADD Grup在本地安装了80万台左右的智能电表', '', '', '', '1. 价格2. 本地认证3. 发展同电力公司的关系', '', '卿于蓝2018-05-14 17:06:53', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('69', '{003559D5-BFD3-4EB3-A6FE-1E53D92F53FE}', '61', 'INHE-0593', '2018-05-13 00:21:08', '0000-00-00 00:00:00', '2018-05-15 09:47:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051301/MLC', '', 'N18/056/AD', '2018-05-22', 'N18/056/AD询价', '订单总金额50%生产前TT预付+50%发货前付款', '', '价低者中标', '', '一家中标', '', '代理解决', '', '', '', '', '', '银河授权代理投标', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '代理解决样机问题，报价有竞争力，相关文件及方案完整', '支持立项，项目组成员王自强，胡蝶，张柳芳。', '胡蝶2018-05-13 00:33:46', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('70', '{D3601BF1-C393-44D2-A112-2FD70B4C1A35}', '60', 'INHE-0549', '2018-05-14 10:00:15', '0000-00-00 00:00:00', '2018-05-21 09:37:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051401/NFA', '', '暂时未知', null, 'Projet \"Systèmes de protection des Revenus\"（“收入保障系统”项目）', '暂时未知', '', '暂时未知', '', '可能会采取两个lot，一个lot给MDM和与SAP的兼容，一个lot给AMR、模块和电表', '', '暂时未知', '', '暂时未知', '', '暂时未知', '', '应该是由电表/AMR供应商，模块提供商，MDM解决方案开发商和IS解决方案集成商组成的联盟联合投标', '因为电力公司考虑到AMI解决方案不同组件之间非常强大的依赖性和整合性让他觉得链条环节水平的不良整合会导致整个环节的故障，在多家供应商的情况下，责任混淆的风险可能导致实施延迟或复杂化，所以建议选择“提篮子”收购，以降低整合风险和责任混淆。具体怎么联合投标要看标书的要求。', '暂时未知', '', '暂时未知', '', '本计划的第一阶段是由国际复兴开发银行（IBRD）和清洁技术基金（FTP）资助的清洁能源和能源效率项目第3部分“需求管理和收入保护计划”的一部分。第一阶段的费用估计为1100万美元，主要由世界银行赞助。', '', '暂时未知', '', '通过之前的几个项目，银河表计在电力公司建立了不错的印象。', '', '暂时未知', '', '相比中国厂家，该项目中要纳入AMI系统的表计里面有我司NF7的1974台中压电表，而没有中国厂家的产品。相比欧美厂家，我司有价格优势，而且该项目还没有正式招标，银河可以根据代理掌握的内部资料提前做技术准备。', '', '项目成功的关键在于项目的前期准备和投标团队的组成。需要公司技术力量的支持。', '银河在电力公司供了中压和低压电表，也在NF2中为电力公司提供了与SAP的接口服务，还在去年底去电力公司做了AMI系统方案的介绍，这些都是很好的铺垫。我相信，只要我们技术支持和商务运作相结合，一定可以赢得这个项目，为之后两个阶段以及接下来的智能电表供应做准备。', '王秀明2018-05-14 14:05:05', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('71', '{74403423-809A-4B2F-9C9D-9C582DB78378}', '61', 'INHE-0654', '2018-05-18 16:22:34', '0000-00-00 00:00:00', '2018-05-22 16:53:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051801/CEO', '', '', '2018-05-25', '', '交期：在签订合同的60天后交付。', '', '', '', '取价格最低', '', '代理负责开保函', '', '代理负责开保函', '', '', '', '代理商投标', '', '', '', '', '', '', '', '代理在电力公司有着良好的人脉关系，同时代理公司也有相应技术团队支持', '', '暂无业务人员在一线，与代理之间关系较好', '', '', '', '', '', '', '第一次参与该公司的招投标，数量较小，但美洲市场的目前情况是，很多电力公司进行招标次数多，可数量较小。业务认为从这一市场情况看来我们现在应该有标就积极应标，在推动代理方面在电力公司的进展同时也积极支持响应代理在当地的参与。其次，此次电表技术规格我们公司基本都满足，详细规格见附件。另外此次为代理投标，采购方为Compa?ía Energética Occidental电力公司。', '李明2018-05-18 19:13:12', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('72', '{C9514B5F-FFE1-4931-8828-69E9B69208CD}', '66', 'JXINHE-2559', '2018-05-22 14:27:46', '0000-00-00 00:00:00', '2018-05-24 16:26:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018052201/SIE', '', 'DD4/P&D/ICB/2018/013/D', '2018-05-31', '三相四线CT接入式（有功精度0.5S）静止式电表含通信模块', '代理作为主投标人，我司作为生产商，授权其使用我司产品参与投标，代理负责开具投标保函，中标后向我司采购。', '', '详见11.METHOD OF EVALUTION BIDS', '{C9514B5FFFE14931882869E9B69208CD074E749A304748709C51373D9D483750}_SIE项目标书.pdf', '一家', '', '代理负责开具投标保函', '', '1.公司年限10年，在代理极力说服下，已和电力公司确认，虽不满足，但仍旧可参加投标2.过去7年10家电力公司的供货纪录，5个为国外电力公司。', '', '供货纪录，5月27日', '', '代理商投标', '', '国际性招标，流程规范', '', '代理同意中标后直接向我司采购，付款方式待确认。', '', '代理直接向我司采购，不与电力公司直接交易。', '', '国内主要竞争对手有，海兴，科陆，威胜等。', '', '良好', '', '相关信息正在收集中', '', '产品符合度高，代理和电力公司关系良好，在我司不满足10年从业经验的情况下，同意开具投标保函，购买样机以参加投标，对项目非常有把握。', '', '有竞争力的报价和样机及时交付（最迟不超过5月28日）。', '斯里兰卡市场的招标一直都有10年或15年从业经验的要求，多数代理都因此放弃了与我司的合作，但在该代理的极力说服下，电力公司同意我司参加投标，并且代理已购买标书，并愿意开具投标保函和采购样机以投标。投标产品为三相四线CT接入式GPRS表，产品符合度高，恳请领导支持！', '淦永妍2018-05-22 16:24:16', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('73', '{3D28E09E-C693-4895-8E78-038CBE7E0A49}', '61', 'INHE-0440', '2018-05-24 02:50:28', '0000-00-00 00:00:00', '2018-05-24 16:41:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018052401/TTR', '', 'AE/008/2017-18/HQ/G/39', '2018-06-19', 'Tender for Supply and Installation Distribution equipment asa part of the Rural Electrification for Peri-Urban Areas ofPwani Region and Kigamboni District for Supply andInstallation of Medium and Low Voltage Lines, distributiontransformers and Consumer Connections on Turnkey Basis 招标供应和安装配电设备作为农村电力化 Kigamboni 区域， Pwani 地区，Peri-Urban 地方的一部分；交钥匙供应和安装中低压线，配电变压器和接入用户。', '（1）10%的合同金额，在签订合同后的30天内支付，需提供相对应的收据和银行担保后。(2)80%的合同金额，在发货时提供所需要的文件后30天内支付。（3）5%的合同金额，提交付款申请和完工证明后30天内支付。（4）5%的合同金额，提交付款申请和运行验收证书后30天内支付。', '', 'EPC工程国际招标，综合考虑报价和承包商的资质和经验，承包商至少在本地的CRB注册为1级/2级。', '', '总共5个LOT,一家最多中标2个LOT,电表厂家允许授权多家投标', '', '分包商开保函，有效期：投标有效期后30天，即150天。', '', 'ITL授权分包商投标，分包商等级为CRB1级/2级，具备EPC工程经验，熟悉当地的工作环境，无违约记录，财务能力满足执行合同的要求，等。电表厂商，提供相关供货记录，测试证书，技术应答表，最好是TANESCO的供应商。', '', '画册，图纸，测试证书，零配件无有害物质测试证书，等', '', 'ITL授权分包商投标，我司提供相关技术资料支持。', '', 'REA属坦能源部管辖，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算，评标流程和TANESCO类似。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。\"', '', '付款主要跟进项目管控部门，采购和财务（1）10%的合同金额，在签订合同后的30天内支付，需提供相对应的收据和银行担保后。(2)80%的合同金额，在发货时提供所需要的文件后30天内支付。（3）5%的合同金额，提交付款申请和完工证明后30天内支付。（4）5%的合同金额，提交付款申请和运行验收证书后30天内支付。', '', 'REA资金主要来自政府预算和国际金融机构，国际援助资金和银行贷款等，和TANESCO的盈利性质有区别。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大。', '', '代理商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层DG,DTS，财务总监，采购经理，等。代理和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好。', '', 'DTS，采购经理和技术部门工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI本地的代理商Comfix&Engineer，建有电表组装厂。威胜价格比较低，分体表带表箱和CIU FOB整机38 美元左右。CLOU本地的代理商Bahdela，农电项目供应电表较多,价格很低。海兴和CONLOG的坦桑代理ACHELIS合做，价格和我司持平。目前真正出现的厂家只有两家ITL和EDMI。', '', '农电项目，BDS要求分包商本地从ITL采购电表，ITL提供厂家授权，我司提供相关技术资料给到分包商，分包商中标后，从ITL采购电表，我司按照农电的技术规格ODM供货给ITL。', '', '推荐或设计合适的产品，报价符合市场形势，技术支持响应到位，必要的客户关系建设等。', '建议立项，准备文件，先支持ITL，授权分包商投标；REA电表供货后，再想办法做分包商的工作。坦桑7月全面禁止进口，标书BDS写明电表需要从本地制造商采购，分包商必须要从本地厂商那拿货。随着订单数量增多，经销商的优势也会逐渐发挥出来，目前市场的潜力也比较好。', '汤伟2018-05-24 05:06:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('74', '{2699BE2B-C598-4986-986F-7F577D300779}', '61', 'INHE-0431', '2018-05-24 13:33:50', '0000-00-00 00:00:00', '2018-06-19 08:52:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018052402/WEG', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '刘佩2018-06-07 14:01:43', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('75', '{2F9A728A-8975-4562-B403-2BA8A1BCBF60}', '66', 'INHE-0634', '2018-05-28 18:11:48', '0000-00-00 00:00:00', '2018-05-30 10:07:05', 'unchecked', 'n', 'n', '', '1', 'EPG', '', '暂无', '2018-06-08', 'for the supply of 33kV Energy Meters (27Nos), 33kV Current Transformer (24Sets), 66kV Energy Meters (40Nos) and 66kV Current Transformer (23Sets)', '交期：签订合同起210天内交货；延期罚金：迟交1天，扣0.1%合同金额的罚金，总罚金比例不超过合同总额的10%；质保期：12个月；支付方式：90%合同金额收到货后付款；10%合同金额顺利验收货物后付款', '{2F9A728A89754562B4032BA8A1BCBF608442F4C2B3234363A3D51C033076BD50}_G-05(1).pdf', '在符合技术要求的基础上，最低价中标。', '{2F9A728A89754562B4032BA8A1BCBF60074E749A304748709C51373D9D483750}_G-04(1).pdf', '', '', '', '', '1. 过去3年内至少完成过一个类似性质的合同，合同需求总数至少＞本标2倍；2. 拥有供应商授权投标函；3. 在缅甸有公司或者办事处以提供售后服务；4.需有交税记录证明；5. 不被政府或者世界银行列入停止参与的名单。（因此只能与当地公司合作投标）', '', '', '', '代理商投标', '', '', '', '', '', '', '', '已知原合作代理阿尔法与SECURE会参与本次投标，其CT表价格比我司产品有竞争力。', '', '', '', '', '', '', '', '该项目为世界银行投资项目，较为公平公正，产品符合要求与价格合适为项目成功的关键。', '建议立项，抓紧准备投标资料和样机。', '陈雁2018-05-28 18:52:10', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('76', '{0B598608-803C-44DB-A09E-C9B5BC89A173}', '61', 'INHE-0381', '2018-05-28 22:53:25', '0000-00-00 00:00:00', '2018-05-30 09:54:17', 'unchecked', 'n', 'n', '', '1', 'TRA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.当前所有的系统均安装在同一台虚拟服务器，已远远不能满足当前应用的需求，导致系统经常出现各种异常，如数据库停止，内存无法分配，抄表效率降低等。这样导致系统维护工作增大，稳定性降低。因此电力公司提出银河协助解决该问题。具体实施方案，请看附件。2. 建议项目组成员：张柳芳，苏宏。', '张柳芳2018-05-28 23:06:25', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('77', '{78CA95EA-55D2-4424-B03E-9285F76C634E}', '61', 'INHE-0431', '2018-05-29 09:34:55', '0000-00-00 00:00:00', '2018-05-30 10:07:15', 'unchecked', 'n', 'n', '', '1', 'TDR', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户下单过EW08和EW09项目，目前看来是重复订单，建议正常跟进下单。因不EW08和EW09的项目是谭雯之前操作的，所以请公司参考上述订单报价。', '刘佩2018-05-29 09:50:15', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('78', '{FEE9BD34-D59B-42AB-89F5-8A126B2EABD9}', '60', 'INHE-0066', '2018-05-31 18:34:04', '0000-00-00 00:00:00', '2018-06-04 09:41:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018053103/ECL', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '邱洁2018-05-31 18:51:09', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('79', '{64C6811F-E4FB-4064-BDC1-15480302F9A2}', '61', 'INHE-0381', '2018-06-04 08:02:44', '0000-00-00 00:00:00', '2018-06-15 08:36:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018060401/AGS', '', 'N?001/AOI/F/PUASEE /2018', '2018-06-26', 'Projet d\'Urgence d\'Amélioration des Services d’Eau et Electricité - Fond additionnel (PUASEE-FA)改善水电服务紧急项目 - 追加基金（PUASEE-FA）', '签订合同：30天内预付合同金额10%发货：提交运输单据结算60％EAGB仓库接受货物后的三十（30）天内支付15%。收到安装报告，软件运行报告， 200台电表安装，对EAGB代理培训之后的30天内支付15%。', '', '价格比较，文件验收', '', '文件通过认可，比较价格', '', '投标保函金额：10.000.000 FCFA，约2万美金。', '', '投标人应通过原始或认证的客户证明曾实施类似于本次招标邀请的解决方案#FE54` 所需参考文献的最少数量为3（三）', '', '暂无。', '', '代理投标。', '', '政府资金项目，政府决策。', '', '签订合同30天内预付合同金额10%发货后提交运输单据结算60％EAGB仓库接受货物后的三十（30）天内支付15%。收到安装报告，软件运行报告， 200台电表安装，对EAGB代理培训之后的30天内支付15%。', '', '', '', '新市场，暂无太多信息', '', 'GS01样机在有不符合的情况下，代理中标。', '', '新市场，暂无太多信息', '', 'GS01供货属于新市场首次供货，且包含4套系统，可联合代理继续运作深入市场。', '', '关键：资料完整无误。需客服部提供投标相关技术资料。', '1. 授权代理投标。与代理之间的结算方式为：20%预付款+80%不可撤销远期信用证。', '张柳芳2018-06-05 16:15:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('80', '{2C5DA88F-4E3A-4D06-8774-CB0C9C3ABDC5}', '61', 'INHE-0440', '2018-06-06 06:58:12', '0000-00-00 00:00:00', '2018-06-08 10:27:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018060601/TTZ', '', 'TENDER ZECO/ ZESS/ 2017-2018/G/01', '2018-06-18', 'SUPPLY OF ELECTRICITY OF ENERGY METERS 供应电能表', '价格条款：CIF Zanzibar Port 付款主体：Ministry ofLand, Housing, Water and Energy (MLHWE) /Zanzibar Electricity Corporation (ZECO) 付款条件：无预付款，无发货款，100%合同金额，提交付款申请和验收证明后在30天内支付。交期：签合同后3个月内交货。质保：验收后12个月。违约：支付未发货产品值的0.1%/天', '', '国际招标，无本地优惠条款，一家制造商可以中标三个LOT,投标人可以选择投任何完整的LOT或者整合不同的LOT一起投标，评标流程和TANESCO类似，投标人资质，报价，样机和交期等符合标书要求。', '', '只允许厂商投标，一家制造商可以中标3个LOT。', '', 'ITL投标开保函，有效期：投标有效期后30天，即150天，保函金额2%的投标报价，需本地知名银行开出，履约保函合同金额的10%。', '', '过去三年电表供货记录，认可的营业执照，VAT,TIN等证书，有效的签字授权，提供资料证明是电表制造商，律师认证测试报告，过去三年的财务数据等。', '', '非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持代理商投标，代理商中标后，从银河采购SKD或整机', '', 'ZECO属桑岛能源部管辖，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际金融机构/援助，评标流程和TANESCO类似。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。\"', '', '付款主要跟进用服，采购和财务（1）无预付款(2)无发货款（3）100%的合同金额，提交付款申请和验收证明后30天内支付。我司主要和ITL签合同和付款，100%假远期信用证支付。', '', 'ZECO资金主要来自政府预算和国际金融机构，国际援助资金和银行贷款等。代理商/经销商公司较大，目前现金流不大好，开信用证问题不大，有偿还能力。', '', '代理商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。ZECO方面关系还需要积累。代理和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好。', '', 'ZECO商务经理，部分工程师，需继续拓展和积累等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI本地的代理商Comfix&Engineer，建有电表组装厂。CLOU本地的代理商Bahdela,价格很低。海兴和CONLOG的坦桑代理ACHELIS合做，价格和我司持平。目前真正出现的本地厂家只有两家ITL和EDMI。', '', 'ZECO项目，要求厂家投标，ITL直接投标，我司提供相关技术资料支持，ITL中标后，从银河采购电表，我司按照ZECO技术规格ODM供货给ITL。', '', '推荐/计合适的产品，报价符合市场形势，技术/商务支持到位，必要的客户关系建设等。', '建议立项，准备文件，支持ITL投标，打开桑岛市场。', '汤伟2018-06-06 08:18:15', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('81', '{B779F2E0-73D2-4441-828F-1F69FCA90168}', '61', 'INHE-0431', '2018-06-07 13:28:24', '0000-00-00 00:00:00', '2018-06-13 11:01:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018060701/TMC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '刘佩2018-06-07 13:45:37', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('82', '{6943AC95-1B6B-471A-9806-36C5180720B7}', '93', 'INHE-0726', '2018-06-13 11:04:27', '0000-00-00 00:00:00', '2018-06-19 08:52:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061302/PIC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '李卓涵2018-06-13 13:48:28', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('83', '{0305DAD2-65B8-4D19-A431-2AEF358994EC}', '61', 'INHE-0722', '2018-06-14 18:55:02', '0000-00-00 00:00:00', '2018-06-19 08:51:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061401/MAC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '墨西哥市场潜力巨大，认证和试点是银河进入墨西哥市场的第一步。并且CENMEX和SMEI在墨西哥电力市场拥有丰富的经验，但技术方面需要银河进行支持。MAC项目对银河进入墨西哥市场能打下重要基础，希望公司同意!', '冯婷2018-06-15 08:43:57', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('84', '{46BF4B26-CEB5-4195-86B1-35E43FBBC351}', '61', 'INHE-0432', '2018-06-15 16:53:36', '0000-00-00 00:00:00', '2018-06-20 14:33:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061501/PRK', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.请公司批准并提供样机报价（已和客户沟通，样机价格较高）                                                       2.与客户就价格、付款条件达成一致后，请公司同意制作并出售5台样机做测试。', '谭东羊2018-06-15 17:57:34', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('85', '{07F20BC2-2EC6-4C9D-8B33-4A136D00E45B}', '61', 'INHE-0642', '2018-06-19 00:04:19', '0000-00-00 00:00:00', '2018-06-21 15:46:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061901/EGJ', '', '', null, 'Expression of interest (EOI) for construction and integration of 1.5MW solar PV with Diesel electricity generation at Likoma and Chizumulu island. (在Likoma 和 Chizumulu 岛屿上施工和整合1.5兆瓦太阳能光伏和柴油发电项目)', '', '', '1.首先审查每一份意见书，以确定其形式和内容是否完整。2.随后如果需要有澄清的地方，EGENCO会要求参与者提供补充信息。3.如果Egenco完成了该澄清步骤，将会开始正式的评估流程，评估流程将会以简单的pass或者fail展示，其评判规则为：（1）展示的所有资质要求符合规定将会收到pass，反之则fail。', '', '', '', '', '', '1. 参与者(联合体投标或财团的领头公司)应提供经公众会计师认证的最近两个完整财政年度的审计财务报表，包括合并资产负债表、损益表、现金流量表和附注。2.参与者应通过以下方式证明其开发和建造太阳能光伏混合动力系统的财力: i. 如果参与者是单一实体，则该实体在最近的两个完整财政年度(截至本函截止日期)结束时，其净资产应至少为800万美元。ii. 如果是联合体投标或者财团，则主要投标人应满足上诉要求。3.参与者应该标明，他们是否曾经用自己的资金或通过出口信贷工具开发项目，以及他们是否有能力为项目融资或获得出口信贷安排来开发这个项目。2. 提供一份意向书原件和2份复印件，并用密封的文件袋标明‘Expression of interest for construction and integration of solar PV on Likoma and Chizumulu islands’装订。', '', '2018年7月2日当地时间下午2点。', '', '已经寻找到了有意向合作的本地合作商，准备在本周三会面细谈合作方式。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '项目成功的关键在于资质和客户关系的运作，需要公司评估该项目的可行性。业务目前已经找到有意向合作的本地代理商，该公司为光伏企业，在马拉维已经有多年的经营历史，业务准备在这周三和该公司相关负责人详细交流合作事项，但同时也希望公司做两手准备，看看是否有中国公司愿意合作该项目。', '资质和客户关系是比较重要的两个点，业务会在当地寻找可以合作的代理商，同时也想公司在国内寻找符合资质的厂商进行合作。如果该项目可行，业务将尽快跟进客户关系。', '潘正豪2018-06-19 17:02:31', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('86', '{56065F4F-6546-4B37-B9FB-E2E3DB9C4811}', '60', 'INHE-0727', '2018-06-20 17:36:42', '0000-00-00 00:00:00', '2018-06-21 15:25:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062001/MTA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '何素贞2018-06-20 17:50:43', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('88', '{95DA8008-4A4B-41A8-AACB-B27020A7FA24}', '60', 'INHE-0712', '2018-06-21 18:06:56', '0000-00-00 00:00:00', '2018-06-28 14:29:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062104/FIJ', '', 'ESPD/TUV/ICB/2', '2018-07-18', 'Tuvalu Energy Sector Development Project 图瓦卢能源部门发展项目', 'CIP#FE54`10%预付款，装船付80%，验收后付剩余10%；交期为90-150天；', '', '无本地优惠、价格最低中标，若价格最低者存在实际不符项则顺延至下一价格最低者。', '', '可联合投标，但不能超过两家公司；一家制造商不允许授权多个投标人；不适用多个Lot。', '', '不需投标保函，只需开投标保证声明；履约保函为合同金额的10%，在产品验收48个月后退回', '', '过去5年间年销售额大于100万美元；流动资产或信用额度为35万美元；有安装1000台以上预付费表的经验；任何证明设备符合IEC 62052-11相关标准的第三方认证', '', '任何证明设备符合IEC 62052-11相关标准的第三方认证；最迟需于7月9日前提供', '', '银河投标', '-', '此项目为图瓦卢电力局公开招标', '', '合同签订后60天内并在发货前提交等值银行担保给采购方后，客户支付合同金额的10%；合同金额的80%在提交GCC第12条规定的文件后，通过以供应商为受益人的不可撤销保兑信用证支付；收到货物30天内提交由买方出具的验收证书，支付剩余10%的款项。买方若延期付款超过90天，则需按年利率1%加付利息。', '', '就此项目，图瓦卢已向世界银行借款US$ 4,800,000', '', '无', '', 'Mr. Mafalu Lotolua', '', '目前该市场主要竞争对手为EDI与Itron.', '', '此项目不需开投标保函，也不需提供样机。银河基本符合其招标要求,有较大希望中标。对于一些不明确的点，后续会与客户澄清并开始准备投标相关文件。', '', '此项目报价很关键，因为是采取价格最低者中标；另外配合态度也很关键，我们需要及时回复并提供技术支持。', '此项目为图瓦卢公开招标项目，由于图瓦卢是个小国，预计项目竞争不大，且不需提供样机与投标保函，因此相对而言前期投入较小，成功概率较高。另外，银河可以通过此项目进一步开发周边国家市场，从而提升市场占有率。希望能同意立项申请。', '杨晓婷2018-06-26 18:24:05', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('89', '{C527D835-2A6C-48ED-B32B-AADC4D7DDD6B}', '61', 'INHE-0718', '2018-06-22 09:18:05', '0000-00-00 00:00:00', '2018-06-28 14:30:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062203/GPL', '', 'ICB No. GPL-IDB-EU-004-20J8', '2018-08-28', 'Rehabilitation of the Medium and Low Voltage Distribution Network, approximately 310km-Lot B中低压配网线路（约310kM）恢复改造-Lot B', '标书商务条款：1.价格条款：交钥匙工程。DDP（含税）（施工现场）2.付款主体：此为融资项目，借方为圭亚那电力和照明公司，融资方为圭亚那电力和照明公司以及泛美开发银行3.付款条件：收到履约保函和预付款保函后21天内或者签发中标函后42天内，以时间晚者为准，业主会提供总包方一笔无息预付贷款，即为合同金额的30%（需要在后期的付款计划金额中，按2%比例扣减，直至扣减结束为止）；后续付款计划金额，需要在收到总包相应付款声明以及相关材料后56天内付款；最后付款金额，需要在收到总包相应的付款证明后56天内付款。4.质保：发货后18个月，承诺与技术规格相符，交货后至少5年内 无需要维修5.投标方需要自行：需要提供从收到PO起的发货计划以及后续的发货计划此次银河不直接投标，银河与代理的付款条件为：签订合同后30%合同金额，发货前70%的余款。', '', '评标会考察如下方面得分：1.资质、历史违约记录、财务状况，技术方案，一般工程经验，特定工程经验，工程人力资源配备，工程工具与设备配备状况。得分至少为72份以上，才有中标资格。2.报价、交货方案评估，综合得分高者胜出', '', '不能一标多投，但是分包商或者供货方可以参与多个投标', '', '投标保函&履约保函代理负责开立', '', '资质上要求出示国籍声明文件及其证明，银行资格合格声明，是否为国有实体声明/在提交投标截止日期前的最后五年内没有发生不履行合同的行为/投标人必须提交经审计的三年财务报表（2014年至2016年）和2017年审定/未经审计的财务报表/投标人必须提供过去八年（2010 - 2017年）的供货合同细节和过去十年的合同具体细节(2008-2017)', '', '需要客服部协助提供新版画册和操作手册，以及实验室提供样机', '', '代理商投标', '', '', '', '合同签订后，客户预付合同总金额的30%', '', '', '', '和代理关系较好，代理在当地有着比较好的运作能力，积极帮助银河开展投标，之前也帮助银河拿下了十万台电表的大单', '', '暂无一线业务员在当地市场', '', '', '', '银河的优势在于之前参加过该市场的投标且成功中标，中标数量较大，这次投标会相对有把握一些', '', '', '业务方面认为圭亚那电表市场有很大的发展潜力，且之前在该市场拿下过数量很大的订单，有过项目经验。另外，此次招标为圭亚那国电发起，如果公司能积极响应并且成功中标，可以为银河树立良好的形象以及得到该电力公司的重视，为之后的项目打下基础。另外，标书中表示电表招标数量仅作为参考，在执行中可能会有变化。', '沈茁2018-06-26 17:11:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('90', '{342FAB90-01C9-4D8E-B4A4-00708D2879E2}', '60', 'INHE-0727', '2018-06-22 16:22:38', '0000-00-00 00:00:00', '2018-06-25 17:43:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062206/WON', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '何素贞2018-06-22 16:36:49', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('91', '{03A34B44-80FB-40B4-B051-B8AEA415FAEF}', '60', 'INHE-0535', '2018-06-25 14:59:44', '0000-00-00 00:00:00', '2018-06-28 10:52:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062501/LTE', 'LTE', 'EESL/06/ICB-AMI-System Integrator-PAN India/181905004 dated 16.05.2018.', '2018-07-05', 'International Competitive Bidding (ICB) for Design, Supply, Installation, Integration, Commissioning, Operation and Maintenace, FMS Support of AMI Solution for 5 million Smart Electricity Meters with GPRS-based Communication Module for Pan India.泛印度五百万GPRS通讯智能电表的AMI解决方案的设计，供应，安装，兼容，调试，运行，维护和现场支持的国际竞标。', '收到相关里程碑资料和单据后30天内由EESL支付给主投标人；详细付款里程碑计划见附件', '{03A34B4480FB40B4B051B8AEA415FAEF8442F4C2B3234363A3D51C033076BD50}_LTE项目 付款计划.xlsx', '1.先开技术标。采用Quality cum Cost Based Selection(QCBS)方法：技术评标得分70分以上的为技术标合格的投标人#FE54`2.接下来只开通过技术标的投标人的价格标。3.如果价格标高于EESL预期或现行价，EESL有权进行逆向招标reverse bidding。', '', '一家中标', '', '1.投标保函：Rs. 172,700,000 / USD 2,65Million有效期至techno-commercial 开标(2018/06/19  IST14:30)后225天2.履约保函：LOA 28天后开立，合同价值10%，有效期至合同期后3个月8年6个月：(安装期1.5年+质保和O&M/FMS期(如6.5年)+3个月索赔期+3个月动员/测试期)主投标人L&T负责开立。', '', '1.可形成<=4家的联合体，联合体主投标人必须至少有2个AMI/AMR项目执行和兼容经验，承担整个项目的连带责任；联合体其他成员的业务必须是供应/执行/兼容AMI系统元件，承担各自项目工作范围内的责任；2. 年平均营业额USD40million(2015-2017)（联合体主投标人满足至少50%）3.技术资质见SI-T2: 过去10年至少3个AMI/AMR项目；累计至少50万台表', '', 'AMI系统架构（应用，网络和安全）资料；操作手册；项目执行计划；部署方案；培训计划；风险控制和灾备计划等。', '', '联合投标', '1.利用主投标人L&T的大项目施工经验，CMMI证书（必要资质），电表安装，本地人员调配等；利用副投银河的AMI项目经验弥补主投标人不足，联合投标。2.L&T主投标人，承担整个项目的连带责任；银河作为AMI系统供应/执行/兼容伙伴，承担其项目工作范围内的责任。', '中央政府下达政策计划，并提供项目资金给EESL，EESL负责组织招标，采购和付款。', '', '电力公司直接根据里程碑计划，在收到相关单据后30天内付款给主投标人。', '', '见附件 EESL资信调查报告', '{03A34B4480FB40B4B051B8AEA415FAEF108D268797C74834B1DDE2FC1083AA37}_ENERGY_EFFICIENCY_SERVICES_LIMITED.pdf', '1.项目工程实施经验丰富，智能表计系统实施经验有限（银河可就此谈判，增加项目渗入力度）；2.与电力公司高层有一定关系，可安排与相关人员的会面及软件演示；3.公司财务资质好，可负责大额保函的开立；4.投标团队经验丰富，分工协调明确。', '', '银河尚未与业主建立直接对话或合作关系。但有一定项目投标运作关系。', '', '本地大型国企；IES labs；等。LTC项目通过技术评标的3家投标人开标总价格如下：L1：L&T+银河 联合体 - USD 135,000,000/INR 864 crores (97.5分)L2: IES labs(山东积成电子) - USD 139,218,750/INR 891 crores (97.47分)L3: Keonics + Bosch联合体 - 价格和技术得分差距较大', '', '1.以供应银河软件为主要目的，价格借鉴LTC项目报价和其他投标人可能的报价，最后作适当调整；2.由L&T安排，在投标前派技术团队去当地电力公司做软件演示，推广银河产品，并获取电力公司意见；3.系统与电表进行兼容时，由于银河将会是电表供应商之一，对项目后期顺利执行有一定优势。4.标书中要求软件覆盖5-7个邦的500万用户，SLA达99%，详细的HES和MDM功能需要根据技术规格做进一步开发，保证系统的稳定性，安全性和适用性。', '', '电力公司的关系处理；有竞争力的价格；软件产品实力；评标环节的把控等。', '申请项目延期，并准备技术团队去电力公司的演示。', '左亚楠2018-06-25 16:27:47', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('92', '{7F34E033-2B89-46E2-827E-2851876D58ED}', '60', 'INHE-0514', '2018-06-26 12:48:06', '0000-00-00 00:00:00', '2018-06-28 10:33:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062602/ICE', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此次立项主要目的是申请参与7月中旬由ECC安排的电力公司演示。上面提到了该演示分为2部分，通过第一部分，我们希望可以为ECC已经提供给SEC的普通电能表提供通信系统方案，实现AMI功能；通过第二部分，我们希望能够拿到后期的AMI项目订单。据ECC CTO表示，演示之后会有一个5000台三相表的AMI试点项目，另外，ECC保证如果演示成功与银河达成合作，后期会有接近100万三相表的订单需求。另外，通过之前ECC与林洋的合作，客观来看业务认为ECC应该是比较有实力的代理和合作伙伴，应该尽力借此次机会踢掉林洋达成与ECC的合作。所以，肯定公司考虑此次演示的事宜。另外，根据与ECC的沟通，此次银河参与演示的交通以及食宿费用有ECC承担。', '李成兵2018-06-26 13:36:35', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('95', '{F65854B3-2E76-4C30-B6EB-FE4DDA6BB62F}', '61', 'INHE-0713', '2018-06-26 17:15:12', '0000-00-00 00:00:00', '2018-06-28 10:33:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062605/DCN', '', 'AOI N°025/DEP/PRMP/DG/CEET/2018', '2018-07-12', 'DCN', '【付款主体】CEET多哥电力公司【付款条件】-预付款：合同签订30天内，收到供货商履约保函及付款请求后，电力公司支付合同总金额10%的预付款；-装船：合同总金额80%交单后通过保兑的不可撤销的信用证结算；-收货：剩下合同总金额的10%将在收货后的30天内结算，需要获得电力公司验收合格的报告。-服务结算方式：服务交付之后且由买方开出的包含有支付申请的验收证明之日起30天内支付100%的服务价格。【质保】所有供货产品需要有效运作15-20年；质保15年。【交期】交期为合同签署后180天内【违约条款】交期为合同签署后180天内，违期将会取消合同【罚金条款】延迟交货的天数*合同CIP金额*1/1000%，当罚款达到合同总金额的10%后，取消订单。', '', '-	评投标者的资格，IS34和IS37，是否有对应财务能力和技术能力证明文件-	评投标文件是否满足技术要求-	根据所有投标方报价,对每一个投标者的两个批次投标（lot1和lot2）进行价格评判，确定基本符合要求的出价和评估成本。根据批次组合价格进行评估出最低报价。-	评估最低报价的原因按根据IS36，看最低报价是否为异常报价', '', '一家中标，一家2个Lot', '', '开具投标保函，保函金额为15 000 000 CFA XOFLot1和Lot2需要分开开两份保函，需要转开当地银行，两份保函开具金额相同。', '', '【财务数据】①近三年的资产负债表（2016，2015，2014）（代理投标，由代理提供）。②财务能力证明（500 000 000F CFA授信额度或者现金流或信贷额度）（代理投标，由代理提供）③压电网设备供应的最后三（03）年（2016年，2015年和2014年）的最低年平均营业额等于至少5亿美元（5亿美元）F CFA 对于每批次，这相当于为进行中或完成的合同收到的强制性付款总额。（代理投标，由代理提供）【供货记录】-近五年内预付费电表的供货记录(银河提供)7月3日-近三年内电气设备或者电气接线设备项目的供货记录(银河提供)7月3日【资质证书】STS证书 7月3日IEC证书 7月3日【测试结报告】供应商自费向买方承担所有与供应服务相关得所有测试和检查，并免费向买方提供测试检查结果。', '', '【技术文件】-投标产品技术 文件 7月4日—产品使用说明书 7月4日-产品设置说明书 7月4日【商务文件】-报价单 7月4日-原产地证明 7月4日-厂家授权 7月4日-签字授权 7月4日', '', '代理商投标', '无', '为了寻求必要的资金支持，CEET在2000年9月进行了私有化，由里昂自来水公司和魁北克国际水利公司买段经营20年，继续从事在多哥的电力生产，分配和销售。且分析本次评标规则，政府/政治对客户决定过程影响不大。', '', '-预付款：合同签订30天内，收到供货商履约保函及付款请求后，电力公司支付合同总金额10%的预付款；-装船：合同总金额80%交单后通过保兑的不可撤销的信用证结算；-收货：剩下合同总金额的10%将在收货后的30天内结算，需要获得电力公司验收合格的报告。-服务结算方式：服务交付之后且由买方开出的包含有支付申请的验收证明之日起30天内支付100%的服务价格。', '', '多哥政府已从世界银行获得资金资助多哥能源部门改革和投资项目（PRISET），并打算将部分贷款用于电表供应和连接设备市场的支付', '', '代理所在国，代理与电力公司总经理关系较好', '', '由代理主要负责业主关系，银河与代理之间合作关系良好', '', '竞争对手：科陆，海兴', '', '银河此项目由代理投标，项目为代理所在国家且代理与电力公司老总关系较好，在电力公司内部有较多朋友，对于业主关系的维持一直较好；电力公司此次两个标DDN与DCN，银河同时都有在投标，但一个为代理投，一个为银河投，两方都有较好的分工，合作状态较好；在CDN完成了技术交流日以及技术交流宣讲后，CEET电力公司以及其他电力公司对银河的认可度提高。2017年银河在综上此次投标若和代理合作顺畅，按时提供对应资料无误，中标的成功率较大。', '', '【项目成功关键】-仔细检查标书要求，按照标书要求，在规定的时间内准备标书文件，维持和代理之间的即时沟通-充分考虑自己的价格和竞争对手的价格，所有符合条件的厂家中，取投投标价格最低中标。【需要的支持】-准备商务资料和技术资料过程中对接部门的支持', '无', '苏宏2018-06-26 18:05:45', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('96', '{2520BD68-2FAC-4115-BA07-F794228177AC}', '61', 'INHE-0725', '2018-06-27 20:08:38', '0000-00-00 00:00:00', '2018-07-03 09:58:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062701/JJO', '', '待定', null, '待定', '价格条款 CIP，费用包括清关', '', '先商务后技术，招标方采用评分表对投标方打分，其中价格占总分的20%； 技术规格（以及资质、项目经验）占总分的80%，其中技术规格满分为80分，投标方在技术规格方面的评分必须不少于64分。', '{2520BD682FAC4115BA07F794228177AC074E749A304748709C51373D9D483750}_评标细则标书原文_20180627.pdf', '一家中标', '', '投标方须在银行开设保函，保函开立金额为XX，以XX为货币，保函有效期至少为截标期后的120天；获得授标函的28天内投标人应开具履约保函，保函金额应为XX，以XX为货币，保函开立方银河', '', '1.投标人应展示三次设计,供应和安装数据中心,通信网络和灾难恢复的经验。投标人应在过去五年成功地在与ECG电力公司规模、增长速度、复杂和情况相似(即3000名用户)的企业中成功运行项目(三个）；2.投标人应说明在过去五年建设同步服务的多站点数据中心的经验（2个）；3.投标人应说明在多数据中心建设灾难恢复站点经验（2个）；4.投标人应展示在过去的5年里在与ECG同等规模甚至规模更大的电力公司中中建设SCADA集成的通信网络的经验（1个）；5.在过去的五年里，投标人应展示遵循环境、社会、性别、健康和安全要求的项目（2个）；6.投标方应满足表4.0中列出的所有资质要求 Qualification of Section III of the Bidding Document；7.5年内没有出现过不履行合同的现象；8.在过去五年没有发生收到合同通知后，不签订合同的事项。', '', '需要客服部门协助评估技术要求。此外需要商务部门协助整理投标资料', '', '银河投标', '客户倾向于佣金模式', '客户告知，评标将会由三名MCA人员协助评标，后续会发送到美国总部进行审核。', '', '1.预付款 - 整个合同价格的10%2.除开定制软件和定制材料外的信息技术、材料以及其他物料（1）发货后支付10%全部合同款或者按比例的合同款项（2）开始安装后支付10%的全部合同款或者按比例的合同款项（3）运行验收后支付70%的全部合同款或者按比例的合同款项3. 软件（1）开始安装后支付10%的全部合同款或者按比例的合同款项（2）运行验收后支付80%的全部合同款或者按比例的合同款项。4. 培训以外的服务（1）系统设计   a. 根据系统设计和供应商的文件，支付70%全部或按比例的合同价格   b.验收后支付20%的全部合同款或者按比例的合同款项（2）调试按比例支付的培训服务合同价格的90%将按月支付，并适当提交发票5.培训（1）在全部培训开始时，支付培训服务合同总价的30%（2）培训服务合同价格的60%将按月支付，并适当提交发票6.完成系统兼容，在系统运行验收后，支付总合同价格的10%（不包括所有经营性成本）7.经营性成本已完成的服务的价格的百分之百（100%）将按月支付', '', 'MCA项目，支付能力良好', '', '代理提前两次从MCA拿到标书，并且在MCA内部有一定的关系，目前JJO项目还属于投标初期阶段，如果公司同意立项该项目，后续客户会跟进一步开发当地MCA关系', '', 'PPA为我司老客户，但一直没有做成大项目，现在正与我方合作JJN项目，我方与客户关系较好，对于类似投标项目运作有一定经验，与当地公司关系较好。目前客户已经打通了MCA中低层关系，后续如果有必要，可以继续往上运作。', '', '科陆，西门子，海兴，El sweedy等等（详见附件）。', '{2520BD682FAC4115BA07F794228177ACC8C3CDC70C5243B796247CC1ED7EC56E}_JJN Bidder整理_20180627.xlsx', '客户提前拿到标书证明在MCA项目运作中有一定的客户关系，该项目暂未在网上公布，我司有充分准备时间。我方已经操作过JJN01投标项目，已有类似经验，也积累了客户关系和人脉，相信在JJN项目的借鉴下，JJO会避免走很多弯路。如果我司能解决技术问题，凭借客户的运作，公司就可抢占先机。', '', '1.MCA对技术部分的要求较高，如果技术部分可以满足，商务部分可以商议，需要客服同事协助分析技术参数2.JJN项目中的安全性问题在JJO中也有出现，安全性问题在JJN中未得到解决，希望在JJO中能够得到公司支持，解决该项问题。', '该投标项目有以下几点优势：1.我方已经操作过JJN项目，对于此类非电表招标项目有一定的经验，在JJN的借鉴下会将JJO运作的更好，避免走很多弯路；2.MCA项目资金稳定并且项目执行比较规范；3.该项目主要是为电力公司建设两个数据中心和一个灾备中心同时进行通讯方面的支持，如果我司能够中标，可以很好地为后续的78000台的预付费电表项目做铺垫；4.该项目可以提高我方在当地的市场份额，在与当地建厂的科陆分庭抗礼，早晚都要进入这个市场，不如早点进去；5.目前该项目暂未在网站上公布，我司有充分的时间做准备；6.以后也会遇到类似的项目，原来在CDN市场遇到过，也有现在在操作的JJN，即将到来的JJO，如果公司能够解决项目中的技术问题，以后将会获得更多的机会，也会使公司得到长足的发展；7.Meralco以后将与ECG电力公司关系很紧密，以后会协助做很多重要决策，但是我们还没和Meralco建立联系，JJN、JJO也是为了和Meralco和ECG建立良好关系，有利于我方占据更多的市场份额拿订单。结合以上优势，向公司申请立项，希望公司予以支持和帮助，谢谢！', '赵政洁2018-06-28 09:38:01', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('97', '{432EAA3D-A93F-4B3D-A2AF-AA7FA4886303}', '17', 'INHE-0450', '2018-06-28 09:13:51', '0000-00-00 00:00:00', '2018-06-28 09:18:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062801/dxgdsgdsgdfg', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '郭林鹏2018-06-28 09:14:58', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('98', '{C4509F27-E57B-4744-9543-39408DA8BAF6}', '61', 'INHE-0432', '2018-07-02 23:12:51', '0000-00-00 00:00:00', '2018-07-04 09:59:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070201/PDS', '', 'KP1/9A-3/OT/26/17-18', '2018-07-18', '供货项目：预装式变电站', '1.报价：DAP                                                                     2.付款条件：满意交付后且提交所有单据的前提下，30天起开始付款（和电表项目一样）  3.交期：签合同后且业主批准可以生产之日起的8个月内。                            4.质保：交货至电力公司后72个月内；或者项目安装完成且正式运行后的60个月内。', '', '1.	初步评标：检查强制性要求提交的文件是否齐全及按要求完整填写及签字\r\n2.	技术评标\r\n3.	价格评标\r\n', '', '符合评标要求且最低价者中标。', '', '投标保函：500,000肯先令，约5000美元。履约保函：合同金额的10%', '', '1.投标人必须是变压器生产厂商。                                                 2.提供至少4份用户证明，至少有7年以上的生产、销售所招标产品的经验。             3.提供18个月内财报。', '', '需要厂商合作提供资料，需要配电事业部参与制作投标资料。', '', '银河不是变压器厂商，因而需要和变压器厂商联合投标。配电事业部有相关的合作厂商。', '联合投标的原因是因为银河不是变压器厂商，如果不联合投标，就没有投标资格。                                        主投方：深圳银河。', '', '', '', '', '', '', '', '', '客户关系：电力公司配电这一块之前没接触，因而正借此投标机会，拓展客户关系，摸清楚核心人员等。', '', '主要竞争对手：永胜集团(中国人开的本地公司，主要是本地组装变压器、代理其他产品投标项目如电表、ADMS等）；东芝；浙江江山变压器厂等。', '', '', '', '', '1.本来截标日期是7月4号。今日确认延标至18号。                                                                   2.技术解析等配电事业部已内部在进行。                                                                          3.业务二部商务组目前只有倪明杰1人，因此标书制作需要配电事业部参与，一起赶时间完成标书制作。', '谭东羊2018-07-03 00:20:23', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('99', '{B2DB786D-5FCF-45FB-B498-9441B014494E}', '66', 'JXINHE-2559', '2018-07-03 14:52:28', '0000-00-00 00:00:00', '2018-07-05 13:38:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070301/PIN', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '代理同意支付1700美元购买以上三款的样机，待样机准备妥当后和我司共同前往当地，和业主见面以确认订单。现申请立项，制作样机，制定合理的商务报价以推进项目。', '淦永妍2018-07-03 15:12:36', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('100', '{663958A1-9271-4C6B-A8FA-E65F6A6BDACB}', '61', 'INHE-0695', '2018-07-04 11:22:43', '0000-00-00 00:00:00', '2018-07-09 16:12:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070402/SLO', '', '2018-US-08-JB', '2018-09-10', 'Jednofazovy inteligentny elektromer s GPRS modemom（Single-Phase Smart Electricity Meter with GPRS modem）带有GRPS通信模块的单相智能电表', 'DDU, 交期为合同签署后六周内，电力公司预算为:190万欧元', '', '先技术后商务\r\r\r\n\r\r\r\n【技术测试】（耗时一到两个月）\r\r\r\n1.电表计量测试\r\r\r\n2.电表通信测试\r\r\r\n若技术部分完全满足，则可以进入下一环节\r\r\r\n\r\r\r\n【招标竞价】\r\r\r\n1.选取报价最低的一家签署合同\r\r\r\n', '{663958A192714C6BA8FAE65F6A6BDACB074E749A304748709C51373D9D483750}_tender procedure.png', '一家中标', '', '19, 000 Euro\r\n需在斯洛伐克本地银行开立\r\n由代理开立\r\n', '', '1. 3个供货记录，（过去三年内至少一万台），供货的电表应该有MID证书\r\n2. ISO 9001 证书\r\n3. ISO 14001 证书\r\n4. OHSAS 18001 证书\r\n5. 年产量证明:一年电表产量不少于40000台\r\n6. 电表寿命大于15年\r\n7. MID证书报告\r\n8. 本地认证\r\n9. 电表参数表\r\n10. 参数符合OKP中的要求（OKP详见附件）\r\n11. 年营收额投入研发的比例\r\n12. 3台样机（免费提供，测试完返回）\r\n', '{663958A192714C6BA8FAE65F6A6BDACB03404677E4D44E9EB56B3D512B2AF9CC}_Documentation Preparation-1.xls', '1. 相关证书\r\n2. EMC 测试报告\r\n3. UART 测试报告\r\n4. 电表及通信模块用户操作手册\r\n5. 电表接线手册\r\n6. 用户参数设定指南\r\n7. 硬件升级用户指南\r\n', '{663958A192714C6BA8FAE65F6A6BDACBC675BD0CC93442C09B990884D4324504}_Documentation.png', '代理商投标', '', '', '', '交货验货后，60天内付全款。', '', '电力公司支付能力良好，之前未出现欠款情况。详细财务信息可见上方附件【ZSE 2017年财报】\r\n代理为Iskra在斯洛伐克的官方代理，信誉良好。同时公司业务也不仅限于代理电表，据查其公司2017年资本为113万欧元，无较大支付问题。\r\n', '', '该代理在电表行业有多年经验，为Iskra的官方代理，替其拿下了许多的订单。\r\n除开电表，该代理同电力公司在变压器领域也有业务往来，同其有长期的业务关系，相互较为熟悉。\r\n', '', '代理对捷克同斯洛伐克的电力公司(共6家)均有业务往来，目前已知客户在斯洛伐克的电力公司中层有关系，后期可将银河引荐给相关人员认识。\r\n', '', '国外表厂中， Iskra暂不准备参加这次招投标（该代理为Iskra的代理），ADD也不准备参加（联系的另外一个代理为ADD代理）。\r\r\r\n\r\r\r\n现潜在国外表厂的竞争对手为兰吉尔，ZPA，EMH及其他表厂。从该国的电表产品注册名单来看，国内表厂进入该市场的有三星（电表型号：SX5A2-SELS-04）同海兴(电表型号: HXE310)。 而其中最大的竞争者为三星。\r\r\r\n\r\r\r\n据两个代理反应，三星在斯洛伐克市场现在占据了有利地位。该国招标首先进行技术测试，若不满足则直接淘汰，其后才是价格竞标环节。而在之前的几次智能电表招标中，最后在技术能够完全满足，价格能够最有优势的，最后为三星。而海兴暂虽然在斯洛伐克国内有登记，但尚未有任何动静。\r\r\r\n', '', '\r\r\r\r\r\n1.国内竞争对手较少，只有海兴同三星，但据代理反馈，三星同电力公司有过直接接触并且建立起了较好的客户关系\r\r\r\r\r\r\r\r\r\n2.技术要求高，该环节会淘汰一大批对手，只有完全满足了才能够进入竞价环节\r\r\r\r\r\r\r\r\r\n3.一代单相模块表有MID 证书，但不确定是否需要做更改，是否能够完全满足要求。\r\r\r\r\r\r\r\r\r\n4.Iskra同ADD 不会参与本次招标，其他如Apator有很大可能在技术环节无法通过\r\r\r\r\r\r，主要竞争对手为兰吉尔，ZPA等\r\r\r\n5.银河在当地市场尚无任何供货记录，需花费较长时间与精力去同电力公司建立客户关系，从而提前了解其需求运作以后的招投标\r\r\n6.代理反应捷克表厂ZPA在寻求被收购，其现金流可能较紧张，参与这种无预付款招标项目可能会有所顾虑\r\r\r\n7.该市场单相表智能电表更新才刚刚开始，运作客户关系，提前了解需求，可以抢占先机。\r\r\r\r\r\n', '', '\r1.了解并熟悉斯洛伐克同捷克市场电能表技术规格，并加强同电力公司的客户关系建设。\r\r\r\r\n2.标书及技术规格为小语种（斯洛伐克语），翻译过程中可能会有一定的理解问题，需要技术支持遇到不懂的地方及时提出，由业务反馈给代理澄清\r\r\r\n3.技术要求高，需完全满足', '', '卿于蓝2018-07-04 15:57:00', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('101', '{EB06FDEA-C434-4634-9715-E5FA30A3ACB4}', '60', 'INHE-0714', '2018-07-04 14:17:22', '0000-00-00 00:00:00', '2018-07-04 15:37:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070403/MRC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '杨叶2018-07-04 15:33:51', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('102', '{D3A46EB1-F531-4EF3-9441-2CACCB1AF0CF}', '61', 'INHE-0713', '2018-07-11 09:44:21', '0000-00-00 00:00:00', '2018-07-18 08:49:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071102/ALG', '', 'N° 12/2018/AMC/DE', '2018-07-19', 'APPEL D’OFFRES NATIONAL ET INTERNATIONAL RESTREINT N°12/2018/AMC/DE', '【付款条件】50%出货后且收到商业发票等资料后59天内，50%到货验收且发出客户的验收单后59天内。\r\r\r\n\r\r\r\n\r\r\r\n【交期】标书中没有固定交期，但交期不得超过6个月，且交期在评标得分中占5分，交期最短者满分。\r\r\r\n\r\r\r\n\r\r\r\n【质保】24个月\r\r\r\n\r\r\r\n\r\r\r\n【违约条款】如果不能按时交货，延期罚金以周计算，每延迟一周，收合同金额2%的罚金，罚金上限为合同金额的10%。', '', '【第一阶段】\r\n检查投标保函，投标文件签名，投标文件是否按照要求放置。不符合者不能够进入下一阶段评标。\r\r\r\n【第二阶段】\r\n评技术标是否符合标书要求并且没有异议\r筛选掉不符合的投标文件，并且不接受修改投标文件。按照打分制满分70，需要达到56分才能进入下一轮评标：实际测试结果：29分；符合技术规范18分；工艺和制造设备（技术转让）10分；历史客户供货情况10分；\r\r\r\n\r\r\r\n【技术文件不符合项\r】\r\r\n\r\r\r\n1-测试分数低于26分。\r\r\n\r\r\n2-规格不符合现行标准。\r\r\r\n3-规格不符合招标档案。\r\r\r\n4-A总分不到56分。\r\r\r\n5 -缺乏ISO 9001认证\r\r\r\n6-不提交处理不合规部件的提议。\r\r\r\n7-A其中一个参数的空注（零）。\r\r\r\n8计数器样品不符合技术要求。\r\r\r\n9-计数器不能通过其中一个STURNE或ZFA系统进行远程通信\r\r\r\n以上情况视为技术文件不合规\r\r\r\n\r\r\r\n【第三阶段】\r\n评商务文件。打分制，报价满分25分（最低报价者得满分），交期5分（最短交期者得满分，交期超过6个月者得0分），\r\r\r\n\r\n\r\n', '', '一家中标，一家一个LOT，一家制造商授权一个投标人', '', '【投标保函】\r\r\r\n需要开具保函\r\r\r\n且需要当地银行转开，\r\r\r\r\n保函金额保函金额需要高于标书总报价的\r\r\r\n1%，美金结算\r\r\r\r\r\n保函有效期为投标截至日期投标有效期（120天）失效后3\r\r\r\n0天内仍有效。\r\r\r\r\n\r\r\r\n\r\r\n【履约保函】\r\r\n\r\r\n要求履约保函，履约保函为合同金额的10%需要在中标后30天内提供', '', '需要提供近三年资产负债表，出货客户参照，ISO9001认证以及其他文件列表中的资质证书和测试报告', '', '【测试报告】标书中有较多测试报告要求，需要请客户服务部按照标书要求提供这些测试报告 最迟提交时间为：7月14日', '{D3A46EB1F5314EF394412CACCB1AF0CFC675BD0CC93442C09B990884D4324504}_ALG技术规格.docx', '银河投标', '无', '标书中已经明确出评标的规则，政府正字对采购决策影响不大', '', '【付款条件】50%出货后且收到商业发票等资料后59天内，50%到货验收且发出客户的验收单后59天内。\r\r\n\r\r\n\r\r\n【交期】标书中没有固定交期，但交期不得超过6个月，且交期在评标得分中占5分，交期最短者满分。\r\r\n\r\r\n\r\r\n【质保】24个月\r\r\n\r\r\n\r\r\n【违约条款】如果不能按时交货，延期罚金以周计算，每延迟一周，收合同金额2%的罚金，罚金上限为合同金额的10%。						\r\n', '', '客户为阿尔及利亚电力公司，采购能力强。', '', '目前与电力公司采购部门主要通过邮件沟通，同时正在寻找有可能与银河进行合作的代理。', '', '新客户，银河未与电力公司有过面对面沟通，目前主要通过邮件与电力公司采购部门就标书事宜进行沟通。', '', '海兴与科陆未进入此市场，推测本次招标的竞争对手主要为外国电表厂家竞争对手。', '', '【竞争策略】标书对于评标规则规定明确，技术要求为评标的大头，在技术技术文件和样机上做好充分准备，使技术评标得分较高，且涉及的技术评标的点较细较多，若银河都满足的情况下，可以由此看其他竞标人是否满足采取淘汰策略；商务评标的价格为大头，给与价格较大的考虑；并且标书对投标文件的格式，有重复强调，标书文件准备工作，能够给招标方较好的印象。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n【优势】目前主要竞争对手海兴与科陆也未在此市场出货，本次招标为限制性招标，仅仅只对电表制造商招标，招标的范围较小；\r\r\r\n\r\r\r\r\n\r\r\r\r\n【劣势】此前没有在阿尔及利亚市场出货，且目前当地没有代理，没有进行过较为亲密的沟通；标书中提出较多技术资质要求，需要在短时间内准备较多的技术资料。', '{D3A46EB1F5314EF394412CACCB1AF0CFB79221563C224206B274FD7CD6B16366}_表3：ALG项目投标文件列表.xlsx', '1.需要客服部门在技术解析的完成时间上优先考虑且准备标书要求的相应的测试证明文件\r\r\n\r\r\n2.需要财务部门协助与银行沟通开立保函。', '', '苏宏2018-07-11 14:00:11', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('103', '{A7B02820-DC5B-4ECE-A783-00E2ABC5A538}', '61', 'INHE-0654', '2018-07-12 09:04:04', '0000-00-00 00:00:00', '2018-07-18 08:47:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071201/ADE', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目在6月底出差的时候，拜访电力公司时就有提到，电力公司对银河的产品还是比较满意的，所以此次采购本来是招标的形式，但是电力公司在邮件中说明，如果银河提供的测试样机满足电力公司的需求，电力公司可以直接采购。与技术支持人员确认说我司的BS安装的模块表（一代的）负荷曲线暂时无法支持每分钟记录一次有功无功功率并且每十五分计算一个平均值，就此点也请丁总核实一下，确保信息准确，如可以远程操作修改，那么我们是否可以直接对ADC已供货的产品修改3台表，满足此需求，这样代理可以快速提供给电力公司，我司只需要提供3G模块即可，可节约时间。备注：产品的技术规格与ADC.ADD一致，但是增加了对负荷曲线的要求，请查看技术规格附件。', '李明2018-07-12 10:14:07', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('104', '{AC3459CB-54AE-43C2-90CE-9EBD1EDF616F}', '66', 'JXINHE-2559', '2018-07-12 11:32:41', '0000-00-00 00:00:00', '2018-07-19 08:39:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071202/NPR', '', 'RFQ No.:RERL/011/2018', '2018-07-20', 'Supply, Installation and After Sales Service of Single-Phase and three phase Pre Paid Energy Meter', '1.当地供货价，含税。\r\n2.付款主体为RERL,付款条件，项目验收付款。\r\n3.交期，签合同日后的四个月。\r\n4.质保两年。', '', '', '', '一家中标。', '', '无', '', '1.安装分包商需要有一年的从业经验\r\r。\r\r\r\n2.投标人为当地公司，需提供纳税证明。', '', '业务部自行准备，无额外资料。', '', '代理商投标', '', '小型项目，由客户自主决定。', '', '中标后，代理直接按我司报价采购产品和设备。', '', '', '', '要求代理正在调查中。', '', '正在了解中。', '', '', '', '我司拥有丰富的预付费经验来执行该项目，项目属于该国的预付费项目的试点，若成功执行，则可以在全国推广开。', '', '有竞争力的报价和代理的大力支持。', '项目为尼泊尔国家替代能源推广中心发出的项目，数量少，关注的势力较少。凭借我司丰富的预付费经验和有竞争力的报价，在代理的大力支持下，中标的可能性非常较大。恳请领导支持！', '淦永妍2018-07-12 11:59:25', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('105', '{41519F6F-EF68-4783-A048-DC734EAA132D}', '60', 'INHE-0729', '2018-07-13 13:45:59', '0000-00-00 00:00:00', '2018-07-18 08:46:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071302/WZC', '', '27.22.4785.700.50.040.18.593', '2018-07-25', 'Supply and delivery of 110V, 3X5(6)A, 3-PHASE, 4-WIRE DOUBLE TARIFF FULLY  PROGRAMMABLE ENERGY METER WITH MODEM. 提供和交付双费率可编程电能表（带GPRS通信模块）', '1.	价格条款：CIP/CIF 2.	付款主体：WZPDCL 3.	付款条件:美金部分：交单80% ,货到10%, 最终交付(FAC)10%。4.	交期：LC开具后120天之内交货。180天之内完成项目安装调试等相关合同内容。', '{41519F6FEF684783A048DC734EAA132D8442F4C2B3234363A3D51C033076BD50}_Tender_Doc_of_110_V_Meter_of_wzpdcl-解析资质V3.docx', '先进行技术评审，然后开价格标。通过技术评审的投标人，低价者中标。', '', '1个lot，一家中标。', '', '投标保函10万达卡/1.3万美金', '', '投标人应具有至少五（5）年的货物供应和相关服务经验，至少3年以上此款电表的生产经验，过去五年至少有一个单一项目金额2000万（未标注币种，暂视为TK），流动资金8000万（未标注币种，暂视为TK）', '', '尽快提供样机，7月22日前准备好。会跟代理申请延标。', '', '', '', '政府拨款已到电力公司，电力公司自主决策采购。', '', '如项目四4.', '', '政府预算拨款，拥有支付能力。', '', '我司以及代理与电力公司关系好，WZT已获中标通知函。', '', '关系好', '', '海兴，威胜，思达，科陆，林洋。海兴与电力部有关系，价格激进。', '', '1. 与电力公司关系好2. 需要接入到银河的HES', '', '1.完成WZT项目AMI具体协议文档，同时尽快开发出HES。协助电力公司解答其他厂家的澄清问题，坚守我司的技术优势。2.价格同时也需要保持竞争力。维护好客户关系。', '', '吴成博2018-07-13 14:26:22', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('106', '{FA16C13A-DCCE-48FF-BB5B-7CB49BFCEAFD}', '61', 'INHE-0662', '2018-07-16 10:31:22', '0000-00-00 00:00:00', '2018-07-18 08:45:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071601/DEK', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '该市场的智能电表有无穷潜力，客户也已经提到当地电力公司有智能售电系统的需求（售电加集抄，可远程通过系统直接给电表充值）。当然，该市场也有较强劲的对手Itron，目前电力公司正在使用其售电系统。但是银河的产品和服务有自身的价格优势，在跟代理的密切配合下，相信银河在该市场能取得较好的市场份额，还望公司能支持配合。', '陈丽2018-07-16 15:09:41', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('107', '{8ABBA1C9-1687-4A52-B665-4E0F43120251}', '93', 'INHE-0091', '2018-07-17 16:55:25', '0000-00-00 00:00:00', '2018-07-19 08:39:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071701/DAL', '', '55/2018', '2018-08-01', 'Supply of Rated 36kV, 630A, 50Hz, three Phase, Outdoor, Pole mounted, air type load break switch with manual operating mechanism type.供应36kV，50H，三相，户外，电线杆安装，空气型手动操作负荷开关', '1）价格条款：CFR Aqaba Port,或者CPT-Amman Customs,或者CPT-IDECO Stores\r\r\r\r\n2) 付款主体： IDECO\r\r\r\r\n3）付款条件：\r\r\r\n   a. IDECO\r倾向于赊销，在IDECO收到货物并在IDECO仓库验收后一个月内支付；款项将在每个月的第一周支付\r\r\r\r\n   b. 如果供应商坚持L/C付款，所有的LC费用将由供应商承担，L/C为保兑、不可撤销且承兑。在IDECO收到货物并在IDECO仓库验收后，并提交验收证书给银行后一个月内支付款项。\r\r\n\r4) 交期：第一批次80套，在2019年2月前交付，第二批次50套，在2019年8月前交付\r\r\n5）质保：工厂发货日起15个月或产品应用在现场之日起12个月\r\r\n6）延期交付罚款：延期交货，IDECO有权要求扣除合同项下的应付款，每周扣除款最少为应付款的1%的一半，总扣除款最多不超过合同金额的10%', '', '标书无披露，将咨询代理该市场该电力公司的常规操作', '', '标书无披露', '', '投标保函：保函金额不能低于投标报价的5%，由代理开具保函\r\r\n履约保函：合同金额的10%，有效期至IDECO收到最后一批货物之日起一年；履约保函必须在收到中标通知后30天内开出', '', '', '', '', '', '银河投标，代理拿佣金，代理开具投标保函', '', '', '', '', '', '良好。', '', '', '', '银河暂未建立客户关系', '', '已要求代理提供相关市场信息，待代理反馈。\r\n', '', '', '', '', '配电事业部首个高压负荷开关招投标项目，建议投标，以弄清楚市场需求及对投标人的资质要求。', '林丽璇2018-07-17 17:52:46', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('108', '{671D4612-C454-43A3-8301-4FBE89D8DFA6}', '61', 'INHE-0744', '2018-07-18 16:24:12', '0000-00-00 00:00:00', '2018-07-20 14:26:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071801/CST', '请附上客户的技术规格', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '郑超波2018-07-18 16:38:00', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('109', '{03B025DC-2B25-47FA-A40E-643554E8EC7D}', '60', 'INHE-0680', '2018-07-19 09:55:36', '0000-00-00 00:00:00', '2018-07-20 14:20:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071901/EOS', '', '', null, 'Rehabilitation of JSC\" Oshelectro \"on the reconstruction of 6-10 / 0.4 kV networks and installation of the automated system of automated informative electric power accounting  / JSC“Oshelectro”在6-10 / 0.4 kV电网改造中的修复及自动化信息电力集抄系统的安装', '资金来自欧洲复兴银行，付款主体是欧洲复兴银行，由银行直接与供应商结算，不经过奥什电力，预付款、发货前款、验收款，交期60-90天，质保5年。', '', '', '', '分开几个LOT招标，一个LOT只能一家中标，不同LOT可以不同供应商中标', '', '', '', '公司年限不少于10年', '', '', '', '银河投标（代理商协助）', '', '', '', '', '', '', '', '', '', '', '', '当前该市场主要的两个竞争对手三星和海兴：三星依靠实力强劲的代理，主攻北方电力；海兴依靠低价策略，主攻奥什电力。一、尚未证实当前代理实力可靠，至少目前还没有通过该代理中过标；二、价格上没有优势，我司两款三相表和海兴三相表价格相差较大，对方DDP价格和我司FOB价格接近。海兴的低价策略（以接近成本价报价，赚取退税）\r\r\r\r\r\n', '{03B025DC2B2547FAA40E643554E8EC7DC8C3CDC70C5243B796247CC1ED7EC56E}_最近一次投标价格对比图.pdf', '', '', '成功关键：通过试点、解决历史遗留问题恢复各个电力公司关系，与奥什电力最高层达成协议，帮助中标。\r\r\r\n需要的支持：价格支持、按时制造符合技术要求的样品和派遣相关人员前往当地协助通过测试。\r\r\r\n', '需要精心准备、运作，提前了解情况。尽早完成立项和样机申请，做好应标准备，尽全力通过这个项目获得新突破。\r\n', '陈嘉豪2018-07-19 12:07:51', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('110', '{9FE661FB-EECC-4D46-B6C8-5EC717C3FB60}', '61', 'INHE-0431', '2018-07-19 10:49:43', '0000-00-00 00:00:00', '2018-07-20 14:17:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071903/UNW', '', '暂未发标', '2018-09-01', 'Single Phase Prepaid Meters, Circuit Breakers, Ready Boards and other Connection accessores.(单相预付费电表，断路器，配电板（Ready Board)和其它连接配件', '暂未发标', '', '暂未发标，可参考的之前评标基本是标准流程：技术评估，商务评估，上交评标小组和ED批准，打分规则是文档10%+样机10%+技术评估60%+制造商经验20%', '', '暂未发标，可参考的之前评标是一个供应商一个Lot', '', '暂未发标，可参考的之前经验是要求总金额10%左右的当地银行转开的保函', '', '暂未发标，供货记录有要求非洲有5万台的销售（计划影响提高此项要求）', '', '', '', '银河投标', '', '政府对决策有较大影响，因为招标客户是国家所属机构，受政府任命。', '', '暂未招标', '', '世行项目，据说2000万美金资金已到位，用于电力更新，我们的电表招标是其中一部分。', '', '暂时未定具体合伙伙伴。可选择的有:1.电力公司项目负责人介绍的公司#FE54`2.TAN市场的工厂合伙人#FE54`', '', '项目负责人，技术评比小组召集人在过去的两年有持续接触（因为项目大概两年前就一直在计划中，因为资金问题一直没有正式发标），并有过公关，关系良好。电力公司上层可通过TLU项目的政治势力进行影响，总体从上到中下都有所布局。', '', '此电力公司之前供过货的是宁波三星。但是客户对三星的评价不是很好。他们的主要威胁是价格会比较低。另外根据TLU经验，海兴，科陆和思达应该也会积极参与。还有一些其它电表厂商，如正泰或江浙厂商等。', '', '银河优势：1.提前布局，项目我们前后跟进有两年的时间，参考标书技术部分也写的是超声焊和零线窃电（双回路）；2.从项目直接负责人和技术人员到上层政府关系都有布局，加上John介绍的代理或者TAN的代理做一些本地关系，我们的优势还是比较明显的。银河挑战：1.如上述所讲，如果项目在两年前如约发布，那么上述的技术指标我们可以毫不费力的踢提绝大多数对手，但是项目拖延到现在的直接后果就是现有技术指标已经有较多可以满足的厂商；2.世行的资金和介入让后续对标书的修改的难度加大；3.他们和TLU项目电力公司有技术交流，所以表箱的部分是按TLU项目写的，所以我们的表箱尺寸不满足。综合上述信息：1.继续通过我们的关系影响标书制定，争取可以争取到的最大优势（如果写成DIN；2.利用现有关系提前拿到参考报价并打通评比关系。', '', '1.技术支持提供评审及建议；2.除了电表以后的配电板(ready board)和配件等请提前联系供应商寻价，以方便后续正式招标后可以快速响应；3.出差及公关费用支持。', '建议在完整标书未收到前先行立项，并对技术标进行解析并提供意见，业务出差前线进行公关和其它必要动作，商务标部分后续再补充.', '刘佩2018-07-19 11:22:25', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('111', '{084F3EDA-C7AF-44F9-80EF-B4CE3760B48B}', '61', 'INHE-0500', '2018-07-24 03:42:20', '0000-00-00 00:00:00', '2018-07-25 09:53:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018072403/COG', '', 'G/10277/E', '2018-08-03', 'Supply of Prepayment Electricity Vending System and Service                                               符合STS标准的全套预付费售电系统和服务，包含硬件和软件，系统包含主体售电系统组织架构、主站建设、售电站管理、第三方售电平台接入和管理、SLA日常服务、其他功能需求和服务等(整合了整体标书的要求后）', '三年期框架供货协议；报价为DPP含VAT价格；付款主体：George Municipality；         交期：90天内完成新售电系统的替换、数据迁移、第三方售电平台接入、培训、试运行和全运行；付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；质保和违约：服务商和市政公司签订SLA服务协议，重大系统事故1小时内反应；中型系统事故2小时内反应；不影响系统主要功能运行的事故8小时内反应。未按照90天的交期完成按照每天1万兰特罚金执行，未按照SLA规定提供服务，按照每天5万兰特罚金执行。         ', '', '评标分为三个流程：1.技术资料评标，满足至少75分，在总数为100分的技术评分的基础上才有资格进入到第二轮的价格评审；2.价格评审，按照BBBEE资质90/10的偏好打分，BBBEE最高资质有10分偏好；3.演示评审：技术评审和价格评审的合格服务商进入到短名单，进行现场系统演示，最终决定中标服务商。', '', '一家中标', '', '需要开立投标保函和履约保函，NYC开立', '', '投标资质主要问题在于供货记录，标书要求的供货记录在南非境内，满分15分，超过8个以上才有满分，少于两个0分。', '', '需要软件部工程师协助做技术解析并提供相应的技术应答资料', '', '代理NYC投标，银河做技术支持', 'N/A', '市政公司自行决定评标全流程，评标委员会由市政指定的技术代理+财务部成员+采购部成员+电力分支负责人组成，中标的最终价格需要参考财务部审批的年初预算', '', '付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；				\r\r\r\n', '', '需跟进调查，取得相关信息', '', 'NYC优势：BBBEE资质10分偏好优势；愿意在本地投入技术驻点（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案\r\r\r\n\rNYC劣势：第一次在次市政投标，无内部客户关系和支持。\r\n', '', '此市政对于银河也是新客户，第一次参与投标', '', '主要竞争对手：1.过去三年合同期售电系统供应商为Ontec（实为Itron分离后的系统独家经销商），	客户关系较好，电力公司熟悉其售电系统，本地有合作技术支持伙伴； 2.Conlog，此市政的主要电表供应商，市政公司内部客户关系较好，本地有合作技术伙伴； 3.海兴，第一次系统投标，价格和系统功能扩展性有优势； 4.Syntell，南非本地较有实力的系统供应商，在南非有多个供货经验。	\r\r\r\n', '', '竞争优势：NYC优势：BBBEE资质10分偏好优势；愿意在本地投入技术驻点（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案。银河技术方案的符合，以及价格优势；\r\r\r\r\n\r竞争劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\n策略：供货记录的澄清，完成商务和技术的无偏差；和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好技术演示，一次性成功完成演示需求。						\r\r\r\n', '', '供货记录的澄清，完成商务和技术的无偏差；和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好技术演示，一次性成功完成演示需求。						\r\r\r\n						\r\r\n', '按照2018年南非市场业务规划，1.ESA翻单和EST竞标；2.主要大都市市政招标全参与，并争取进入到短名单阶段；3.分表和其他小市政公司的投标或者融资项目：AMR和售电系统项目。\r\nCOG市政为少数具有盈利能力的稳定市政公司，对银河来说售电系统项目的发展潜力较优，望公司支持！\r\n建议：覃湘君为项目负责人，主导前期投标资料的所有工作和后期现场演示的组织和协调，李忠鹏负责现场业务，和NYC联合督促客户关系的建立和拓展。', '李忠鹏2018-07-24 04:24:14', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('112', '{A737C311-9F32-417E-82D4-6AA33C1E7BC6}', '61', 'INHE-0500', '2018-07-25 03:02:54', '0000-00-00 00:00:00', '2018-07-26 08:58:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018072501/BAD', '', '2846/18', '2018-08-17', 'Supply & Delivery of Pole Mounted 11kV Metering Unit 50-200/1A to Gaborone and Francistown Warehouse给博茨瓦纳电力公司首都哈博罗内和第二大城市弗朗西斯敦供应11kV杆上安装组合计量装置（50-200/1A）', '价格条款：DDP仓库不含VAT\r\n付款主体：电力公司BPC\r\n交期：自电力公司PO下单日起10到15周内\r\n质保和违约条款：标书未明确质保和违约条款，规定中标者需要和电力公司签署正式合同协商此类条款。', '', '电力公司成立内部评标委员会，成员由采购、财务、用服部门人员组成。\r\n第一阶段评审：基础商务资料评审（不含报价）\r\n第二阶段：技术资料评审，没有使用过的产品需要按需提交样机进行测试；\r\n第三阶段：价格和商务条款评审，本地制造企业有10%的偏好。', '', '一家中标', '', '需要开立投标保函或者投标申明函以及履约保函，代理开立', '', '公司年限、财务数据、供货记录等无特殊要求，测试报告要求提供SABS或者当地BOBS证书，需要提交ISO9001证书', '', '建议：投标资料的技术部分由配电部杨总指派专人负责整理制作和提交，商务资料由李忠鹏或者杨总指派配电部负责人完成', '', '代理投标，银河做厂商支持', 'N/A', '2017年初电力公司进行了组织架构更换，CEO、COO、CFO和配电总监全部外聘为德国白人管理，评标流程趋向正规，但是目前中低层的评标技术委员会还是由各部门经理黑人掌握，对技术评标和样机测试起了很大的促进作用，银河和代理的公关应主要放在评标技术人员身上', '', '要进一步跟进代理和反馈', '', '电力公司BPC的经营状况较好，详细的最新的财务报告和会计年度盈余请见以上BPC2016-2017财年信息', '', '银河代理FFL：代理本身对电力行业较为懂行，属于博本地唯一的涉及预付费电表和水表供应和安装承包商，对本地招投标的流程熟悉，愿意付出和投入，当前在电力公司底层技术人员有一定的人脉。\r\n劣势：代理公司资金实力不强，在电力公司高层的客户关系薄弱。', '', '银河客户关系：之前2017年出差，拜访认识了配电技术一把手和二把手，但仍然处于较为浅层次的客户关系，主要还是依托代理一起联合拓展', '', '1.Powertech，南非本地规模较大的公司，专业变压器、计量装置制造商，也是BPC计量装置的主要供应商之一，实力强，客户关系较好；\r\r\n2.ITT，南非本地规模较大的公司，专业变压器、计量装置制造商，也是BPC计量装置的主要供应商之一，实力强，客户关系较好，报价信息见附件；', '{A737C3119F32417E82D46AA33C1E7BC6C8C3CDC70C5243B796247CC1ED7EC56E}_Q92909.pdf', '银河和代理竞争优势：代理为本地公司，懂行有经验，客户关系愿意投入，当前已通过电表的投标积累了中低层的一定客户关系；\r\n劣势：电力公司的中高层客户关系薄弱，涉及最终授标的建议；无SABS证书', '', '1.澄清SABS证书，将现有的国内测试报告，让代理申请本地BOBS证书；\r\n2.价格优势：结合代理的信息反馈，需要提供具有优势的报价；\r\n3.样机测试准备，一旦第一轮资料评审过关，需要提供样机测试；\r\n4.客户关系：需要和代理加深拓展策略', 'BAP市场第二次联合代理投标，此次投标第一次涉及配电类产品，当前配电部初步评审技术规格OK，障碍在于SABS证书和样机测试的问题，正在和代理、配电一起沟通，请公司审批支持！', '李忠鹏2018-07-25 13:36:51', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('113', '{99E5EEE9-AACB-4AE3-8C0C-1D71EF8AF214}', '60', 'INHE-0712', '2018-07-25 17:13:41', '0000-00-00 00:00:00', '2018-08-03 11:40:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018072503/IDA', '个人意见增加了补充说明', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目技术规格无偏差，可直接采用银河现有表型，且不需准备样机及保函，因此前期投入不需太大，若能成功获取此项目，可进一步开展其他项目合作，希望同意立项申请。\r\n\r\n\r\n立项意见补充：此项目的标号为129/18/SBEE/DG/DPGS/PRMP/SP du 19/06/2018，经确认，与BCD项目标号不同；且此项目是在6月19日发出，8月7日截标，因此IDA项目与BCD项目应为两个不同的项目，请重新审核评估，谢谢。', '杨晓婷2018-08-02 09:49:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('114', '{165565DF-D90D-430F-8FB3-1B1C0CA6FEFA}', '61', 'INHE-0728', '2018-07-25 15:45:12', '0000-00-00 00:00:00', '2018-07-31 09:26:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018072502/CCR', '请提交技术规格和标书附件', '2018-LI-000007-PROV', '2018-08-17', 'Adquisición de medidores con comunicación remota con radio frecuencia AMI RF 通过射频AMI RF远程通信电表招标', '付款条件：货物：收到货物之后的30天之内支付已收到货物的100%。服务：买方验收服务后的30天之内支付100%\r\n交期：分批交货，30天之内交63台，90天之内交55000台，后每隔60天交5万台。300天内交完', '{165565DFD90D430F8FB31B1C0CA6FEFA8442F4C2B3234363A3D51C033076BD50}_标书.doc', '主要比较价格、电表技术规格方面', '', '标书上没有明确说明授权几个投标人，但是是可以授权多个的。', '', '保函金额：US $  300.000\r\r\n有效期180天\r\r\n履约保函：合同金额的10%，有效期为合同期限再加上两个月', '', '投标人财政能力：信用额度至少有US $ 3 000 000,00\r\r\r\r\r\r\n须在美洲发展银行成员国内有过5年的AMI RF经验\r\r\r\r\r\r\n关于认证，标书上没有明确说要UL证书，但是有提到一个SUTEL认证，和通讯模块的FCC认证， 电表还需在哥公共服务管理局进行注册，会继续向代理沟通确认', '', '', '', '因为是最近新找的代理，在和代理商沟通代理商投标的参与方式', '', '', '', '', '', '因为该项目为美洲发展银行出资，所以客户是有支付能力的', '', '代理在很长时间内都是国家电力公司的电力承包商，与电力公司有着良好的客户关系，并且经常参与类似的投标，投标流程等都十分熟悉', '', '', '', '目前知道的竞争对手有海兴，兰吉尔等', '', '此次投标产品与我司产品还是比较符合的，不需要太长的研发时间，而且如果此次中标，有利于打开我司在中美洲的市场，\r\r\r\r\r\r\n哥斯达黎加作为中美洲地区电力发展程度最高的国家，近两年以来率先在中美地区使用智能电表，国内需求有80-90万台的电力用户，而且目前哥斯达黎加在国内进行了一些AMI集抄的试点方案，如果有机会我们可以推广我们的AMI方案。', '', '技术支持，希望尽快评估可以做哪几款产品，是否有哪些技术偏差，做样机需要多久时间。', '希望立项', '补继平2018-07-26 14:59:07', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('115', '{9F404A7A-0049-46A1-8EED-23D13E906C19}', '93', 'INHE-0726', '2018-07-30 09:59:47', '0000-00-00 00:00:00', '2018-07-30 15:37:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073001/AOD', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '李卓涵2018-07-30 10:23:57', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('116', '{B9C5556C-1822-4287-9B09-4C13BB21DF67}', '61', 'INHE-0662', '2018-07-30 13:40:36', '0000-00-00 00:00:00', '2018-07-30 15:52:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073002/TS', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目已于2012-12-18走完流程，见流水号10377。现为补流程。', '陈丽2018-07-30 15:52:08', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('117', '{F3628717-BE07-41D6-BB83-EE7503B03785}', '61', 'INHE-0593', '2018-07-30 16:57:02', '0000-00-00 00:00:00', '2018-08-02 13:34:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073003/BFA', '', '001-2018/SONABEL/PEPU', '2018-08-24', '为bobo地区供应电气设备公开招标', '预付款：收到合同签订方20%*合同总金额的银行保函后，电力公司会支付与保函总金额对等的合同款项，交货后电力公司退回该保函；\r\n提供相关文件后，支付50%货款\r\n验收后支付30%尾款\r\n交期是在签订履约服务条款之后的90天内。\r\n罚金条款：\r\n延迟交货部分不含税总金额*千分之一/日的罚金。罚金若超过合同金额的5%将取消合同。\r\n', '', '1.	在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。\r\n2.	接下来评技术部分，技术资料是否满足标书的技术规格 。\r\n3.	评财务部分。评完财务文件，价格最低者中标。\r\n', '', '两个lot，均可中标', '', '-	金额（汇率根据截标前14天,西非国家中央银行的汇率换算。）\r\n-	投标保函：\r\n-	Lot 1：37 000 000 FCFA \r\n-	Lot 2：6 500 000 FCFA\r\n-	货币要求西非法郎。\r\n-	投标函应在投标有效期内均有效。\r\n-	无开立行资质要求。\r\n', '', '一般要求', '', '主要为电表，可由业务部门自己制作', '', '代理投标，银河作为供货商', '无', '总经理及董事会决定', '', '再议，一般是代理开出信用证，银河备料生产', '', '', '', '', '', '银河与代理在该市场的关系有改善，银河与电力公司关系较为密切', '', '主要为海兴，建交后会有更多的中国厂商', '', '银河在该市场有一定的基础，为了中标而做。', '', '样机', '建议立项，项目组成员 胡蝶，刘一然', '胡蝶2018-07-30 17:21:25', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('118', '{F4061476-ABAF-43AB-A4C3-5683D3C2B8BB}', '61', 'INHE-0593', '2018-07-30 18:57:15', '0000-00-00 00:00:00', '2018-08-02 13:34:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073004/CMA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '支持代理，建议立项。', '胡蝶2018-07-30 19:08:04', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('119', '{D72605E6-6C73-40AC-A90D-8DE5A8FC0260}', '61', 'INHE-0744', '2018-07-31 10:32:17', '0000-00-00 00:00:00', '2018-08-02 13:32:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073102/SCD', '请提供客户技术需求汇总/规格', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '郑超波2018-07-31 12:24:26', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('120', '{62D638CB-CB3C-24DB-C278-C90D5E4F3076}', '60', 'INHE-0729', '2018-07-31 11:38:27', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('121', '{915A371C-75CB-71E7-EFC2-A746EAB89ECE}', '60', 'INHE-0729', '2018-07-31 11:39:07', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('122', '{296691E2-E2FF-4EFB-BF79-5BCC8FC116CC}', '66', 'INHE-0579', '2018-07-31 16:19:21', '0000-00-00 00:00:00', '2018-08-02 13:32:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073104/TUS', '', '2018年9月底开标', null, '', '项目目前未开标', '', '项目目前未开标', '', '最多四家供应商中标。\r\n中标在技术合格的供应商中筛选价格最低的。', '', '每个条款 50000美金。（待拿到商务草稿后确认）', '', '待拿到商务草稿后确认。或开标后明确资质要求。', '', '', '', '银河直接投标', '', '', '', '', '', '', '', '代理与电力公司AMI项目一技术负责人私交甚好，拿到了标书全部草稿。且推荐该技术负责人给我，该技术负责人主动表示愿意帮助银河，会召集AMI项目相关负责人参与银河演示。', '', '联系到电力公司两个AMI项目负责人，都对银河很感兴趣。', '', '市场竞争情况：\r\n1.华为（使用科陆的电表），SAGEM，中兴，华立已经做过演示。据代理表示演示没有问题。\r\n2.华为和SAGEM是突尼斯市场的主要供应商。\r\n3.华为拟用自己的协议，电力公司不满。', '', '劣势分析：\r\r\n1.目前已有多家供应商完成演示，银河还未进行演示。\r\r\n2.华立价格低廉。\r\r\n优势分析：\r\r\n1.代理提前拿到标书草稿（还不确定其他供应商是否有标书草稿），我司可在演示时根据我们现有产品给出修改建议\r\r\n2.中兴和华立只演示了G3-PLC方案，我司如演示可演示G3-PLC,RF和GPRS三种方案（标书要求了三种方案）\r\r\n3.电力公司技术负责人表示会和代理合作，主动帮助我们。多次主动联系我问我进展，希望银河尽快过去演示。', '', '成功的关键：产品，价格以及商务关系。业务会在开标前，截标前努力搜集更多市场信息。\r\r\n需要的支持：代理和电力公司人员都会将英语，但该市场为法语市场，如后期标书制作涉及到法语，还需其他部门协助。\r\r\n           ', '1.采购数量大，银河已得到标书技术规格草稿，可根据要求提供样机进行演示\r；\r\r\r\n2.演示过程中可多方面了解市场信息，电力公司需求等\r；\r\r\r\n3.与代理确定合作后，代理会提供更多的市场信息；\r\r\r\n4.电力公司技术负责人对银河感兴趣，期待银河的方案。\r\r\r\n', '孙娜2018-07-31 17:07:24', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('123', '{EDA43FCE-8DFB-4734-9C63-B65191ADFDAD}', '61', 'INHE-0713', '2018-07-31 16:43:43', '0000-00-00 00:00:00', '2018-08-03 14:01:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073105/BNA', '', '/18/SBEE/DG/DPGS/PRMP/CPMP', '2018-08-16', 'BNI', '【付款主体】SBEE，贝宁电力公司\r\r\n\r\r\n【付款条件】\r\r\n\r\r\n1.标书付款条件\r\r\n30%TT 签订合同的30天内根据收到的发票和付款\r\r\n申请支付支付30%预付款；\r\r\n60%信用证\r\r\n10%验收且收到验收证明之后30天内\r\r\n\r\r\n2.代理付款条件\r\r\n\r\r\n20%预付，80%信用证发货前\r\r\n\r\r\n【延期付款】超过支付期限后的第八天开始计算逾期支付罚金。\r\r\n\r\r\n【交期】需要在2018年下半年完成所有货物交付，根据合同的交期具体日期。\r\r\n\r\r\n【质保】交货后12个月质保，使用寿命至少10年\r\r\n\r\r\n【违约条款】延迟交货不能超过交货日期之后60天，每延期一天交合同金额1/2000的违约金，最高累计到合同金额的3%（既60天）', '', '1.先评技术标，技术文件所提供规格是否和标书要求技术规格相符，不符合则拒绝其投标\r\r\n2.评商务标，是否提供投标保函以及对应的财务能力证明文件。\r\r\n3.最低报价者中标，如果同时投了LOT1和LOT2，投标人最多只能中标一个LOT\r\r\n', '{EDA43FCE8DFB47349C63B65191ADFDAD074E749A304748709C51373D9D483750}_表3：BNA项目投标文件列表.xlsx', '2家中标，一家一个LOT', '', '【投标保函】需要投标保函，代理投标代理开立，每个LOT 100 000 000 francs CFA需要转开当地银行，有效期为投标有效期90天+投标有效期结束后30天\r\r\r\r\r\n\r\r\r\r\r\n【履约保函】需要履约保函，金额为合同金额的5%（代理投标，代理提供）需要在中标后30天内提供\r\r\r', '', '\r【财务数据】\r\r\r\n\r\r\r\n（a）近三年中标合同（2015,2016,1017）\r\r\r\n总数对应本次招标每个LOT至少50 000套\r\r\r\n（b）流动资产达到合同金额的30%\r\r\r\n合同报价至少报每个LOT 50000台\r\r\r\n由授权银行的证明或在贝宁有代理人证明\r\r\r\n能够组织调动对应的人力物力资源\r\r\r\n\r\r\r\n【供货记录】\r\r\r\n1.近三年（2015 #FE54` 2016 ；2017）在贝宁或者在其他气候条件与贝宁相同地区的供货记录。至少三（03）份低压预付费电表供货合同，其中至少\r\r\r\n一份为STS型预付费电表供贝宁或者与贝宁在过去三（具有相同气候条件的国家的电力公司。）\r\r\r\n2.需要在标书中提供一张已执行的合同项目列表和在执行的合同项目列表。\r\r\r\n3.需要提供完工证明以及验收证明原件或者副本。\r\r\r\n', '', '由于截标时间较感，银河作为代理的供货商，主要负责准备样机以及相关技术资料，需要客户部协助技术解析，技术解析需要在8月4日，本周五完成。', '', '代理投标', '无', '本次招标资金来源为电力公司自有预算', '', '1.标书付款条件\r\r\n30%TT 签订合同的30天内根据收到的发票和付款\r\r\n申请支付支付30%预付款；\r\r\n60%信用证\r\r\n10%验收且收到验收证明之后30天内\r\r\n\r\r\n2.代理付款条件\r\r\n\r\r\n20%预付，80%信用证发货前', '', '客户为贝宁电力公司，此次招标资金为贝宁电力公司自有预算。\r\n\r\n\r\n代理财务状况稳定', '', '贝宁为代理老家，代理与在贝宁电力公司以及贝宁政府都有较好关系，代理已经成功运作延标（原截标日期为8月2日）', '', '银河一直在尝试开发此市场，FDN项目招标同样为贝宁电力公司，目前投标顺利；在CDN技术交流日上，贝宁电力公司对银河参展团队印象较好；代理老家在贝宁，在电力公司以及政府有较多关系，代理也一直积极与银河共同开发此市场。', '', '海兴，科陆；\r\n推测海兴应该在贝宁有供货，海兴西非法语区服务总部设在塞内加尔，而西非英语区服务总部设在尼日利亚拉各斯，紧挨贝宁。\r\n', '', '此项目为银河2018年第三次参与贝宁电力公司招标，第一第二次投标准备进行顺利，目前处于评标过程，代理对于此次投标延标操作顺利，代理对于此次投标在电力公司内部有较好的关系。此此次投标，银河作为供货商支持代理投LOT1与LOT2，两家中标，中标概率增加。', '', '样机准备：目前投标时间较赶，需要实验室以及客服部协助，尽快准备出样机\r\n\r\n报价准备：本次招标两个LOT，一个厂家只能中一个LOT，报价需要分别考虑两个LOT的竞争力。', '', '苏宏2018-08-01 14:27:32', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('125', '{77AB71CF-BF2A-42AD-9624-FD6CCA6AED5E}', '60', 'INHE-0514', '2018-08-07 11:17:29', '0000-00-00 00:00:00', '2018-08-09 09:03:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080702/PET', '', '5\\2018', '2018-08-01', '多功能多费率有功无功智能电表以及AMI系统供应（Supply of Active and Reactive Energy Multi-function, Multi-tariff Smart Meters and AMI System）', '付款主体：Pars；付款条件（可选）：1.30%预付款+70%不可撤销保兑即期LC；2.100%不可撤销保兑即期LC；', '', '技术评标+商务评标，采取打分形式', '', '暂未有多家中标的消息', '', '代理投标，投标保函为17500欧元，代理开立；履约保函为合同金额的10%，代理开立；开立银行为目的国中央银行', '', '要求有类似项目经验', '', '无', '', '代理商投标', '', '目前代理所在国政府为项目所在国政府电力行业提供资金援助，用来扶持和恢复目的国电力行业的发展', '', '根据前面付款条件最终确认方式而定', '', '良好', '', '合作伙伴Pars在目的国以及周边国家实施过相关的项目，有一定的项目经验，了解竞争对手的商务情况，且该项目属于客户所在国政府对目的国的援助项目，在政治上有一定的优势', '', '', '', '市场主要竞争对手是海兴，科陆，林洋，据合作伙伴的消息，之前的项目主要中标方为海兴和林洋，产品包括多功能表和单三相智能表', '', '目前主要的竞争优势在于政治偏向方面。另外，代理在当地业主方的人脉资源可为后面提供运作的空间。', '', '客户关系的运作以及技术支持', '', '李成兵2018-08-07 12:14:36', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('127', '{4AD2C8F9-B4AF-4096-A3ED-C727AC2026C2}', '61', 'INHE-0713', '2018-08-08 10:58:50', '0000-00-00 00:00:00', '2018-08-13 08:49:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080802/GNC', '', '04/AOI/PREREC.2/EDG/2018-LOT4', '2018-09-17', 'Travaux de réhabilitation et d\'extension des réseaux électriques de Conakry科纳克里电气网络的修复和扩展工程LOT4 Fourniture et pose de compteurs à prépaiement 预付费电表的供货以及安装', '【付款主体】几内亚电力公司\r\n【付款条件】\r\n标书付款条件：代理作为承包商按承包LOT4，每月向电力公司提交月度结算申请（包含月度工作进度以及月度工作对应价值结算账目），电力公司在收到结算申请之后确认无误进行付款，在收到申请之后的60天内完成付款\r\n代理与银河结算方式：20%TT预付，80%信用证出货前\r\n\r\n【交期】\r\n产品交期：不得超过签订合同之后的2个月\r\nLOT4电表的安装需要在2年内完全完成', '', '*  招标之前投标人资质预评估\r\r\r\n*  投标后，对报价进行评估，根据标书对报价的规定排出最低报价顺序\r\r\r\n*  得出报价排序后，对投标人资质进行正式评估，主要为财务能力状况，排除资质不符合的投标者\r\r\r\n*  剩下资质符合的投标人进行技术能力评估，评估包括如下内容：\r\r\r\n（a）评估投标人调动关键设备和人员履行合同的技术能力，（b）履约方法，\r\r\r\n（c）工作时间表，\r\r\r\n（d）供货来源\r\r\r\n（f）技术规格是否符合要求\r\r\r\n', '', '\r【报价最低者且通过资质评审技术能力符合的的投标者中标】\r\r\n4家中标，一家一个LOT，一家制造商可以授权多个投标人\r\r\n\r\r\r\r\n', '', '【投标保函】提供投标保函，投标有效期150天，投标保函需要在投标有效期结束后28天内有效，金额为293 300 ', '', '无国家限制；\r\r\r\r\r\r\r\r\r\r\n【资质要求】\r\r\r\r\r\r\r\r\r\r\n（a）资格\r\r\r\r\r\r\r\r\r\r\n（b）待决诉讼\r\r\r\r\r\r\r\r\r\r\n（c）财务状况\r\r\r\r\r\r\r\r\r\r\n具有1 500 000 ', '', '1.需要证明我司目前没有待决诉讼\r\r\n\r\r\n2.需要对应技术文件证书支持', '{4AD2C8F9B4AF4096A3EDC727AC2026C2C675BD0CC93442C09B990884D4324504}_表3：GNC项目投标文件列表.xlsx', '代理商投标', '否', '电力公司招标项目，政府对电力公司的决策影响不大', '', '代理付款流程：20%TT生产前预付，80%L/C出货前', '', '本次招标项目资金来源：BANQUE ISLAMIQUE DE DEVELOPPEMENT (BID)\r\r\n伊斯兰开发银行（IDB）\r\r\n金额：56 000 000 USD\r\r\n', '{4AD2C8F9B4AF4096A3EDC727AC2026C2108D268797C74834B1DDE2FC1083AA37}_伊斯兰开发银行简介.docx', '银河与电力公司、银河与代理之间、代理与电力公司之间关系良好\r\r\n代理公司目前经济状况良好', '', '银河与几内亚电力公司关系较好', '', '海兴与科陆为主要竞争对手', '', '银河作为代理的供货商供货，代理负责赢标。银河此前在此市场有较好的供货基础，电力公司对于银河产品和服务满意度较高', '', '1.投标样机准备\r\n\r\n2.价格准备', '', '苏宏2018-08-08 14:41:17', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('128', '{4BF3F09B-245A-4BED-BFAE-7EBF8950DBDB}', '61', 'INHE-0719', '2018-08-08 13:41:59', '0000-00-00 00:00:00', '2018-08-13 08:48:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080803/PLL', '建议不要使用PEA做代码', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.如此次立项能够通过，建议不提交偏差样机，尽量做出符合客户要求的样机，以免来回折腾，此市场对技术要求把关比较严格，此后客户有意向跟银河联合做秘鲁市场的认证，个人觉得这是一次能够进入秘鲁市场的好机会。                          2.此次样机为收费样机，为了不耽误后续事宜，希望能在8月25号之前交付样机。                                      3.目前谈的合作方式是：此项目样机如果进展顺利，会由客户去参加秘鲁国电的招标，我司授权给客户，但具体细节还在商榷。', '林丽君2018-08-09 17:40:57', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('129', '{F9B8A27B-6EBD-4575-AFDA-26996B5DF811}', '61', 'INHE-0722', '2018-08-08 16:50:44', '0000-00-00 00:00:00', '2018-10-22 11:44:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080804/MAE', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'MAE项目客户表示样机测试成功后将负责帮助银河完成认证，并承担认证费用，合作态度非常积极。且客户需求产品为公司现有产品，不需要投入较多研发，为进入墨西哥市场，希望公司同意立项！', '冯婷2018-10-17 17:00:57', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('130', '{12FF3EFC-1585-466C-A6DB-62A6AE01C616}', '60', 'INHE-0066', '2018-08-09 15:57:17', '0000-00-00 00:00:00', '2018-08-13 08:42:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080902/RTK', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户计划8月27日至31日来访公司详谈技术需求和合作方式，建议立项。', '邱洁2018-08-09 16:21:23', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('131', '{09E91FCF-A6ED-4CAA-B9C8-6902DFF4AC5B}', '66', 'INHE-0634', '2018-08-10 16:10:41', '0000-00-00 00:00:00', '2018-08-15 08:38:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081001/NBL', '', '2（T）/ESE/2018-2019(1 year)', '2018-09-25', '代号NBL', '价格条款：DDP仰光；付款方：ESE电力局；付款条件：在验收货物合格之后（若干）周内支付全款；交期：签署销售合同（若干）月后交付；质保：5年。', '', '缅甸文，暂不明确。', '', '', '', '缅甸文，暂不明确。', '', '缅甸文，暂不明确。', '', '', '', '代理商投标，银河供货', '', '', '', '', '', '', '', '1. 与电力公司关系比较熟络，可以获取较多内部信息；2. 公司规模不够大，运作人员较为年轻，操作比较不规范；3. 公司经济不宽裕，比较抠门；4. 与印度表厂SECURE之间有合作，对银河有所保留，做不到齐心协力，一个声音说话。', '', '', '', '主要竞争对手是科陆、EVER，和SECURE。自APE项目之后，相信吸引了更多中国和东南亚表厂觊觎。', '', '银河自APE项目后，较为熟悉当地环境和需求，且已经专门为缅甸市场研发了与标书要求完全匹配的防窃电智能电表。', '', '最新消息：阿尔法不愿意和银河继续合作，选择和SECURE合作投标。但是阿尔法为银河介绍了一家据说是实力不错的当地公司（有待继续沟通洽谈）。与此同时，收到另外一家缅甸公司关于相同招标项目的合作意向邮件，仍在判断斟酌中。因此，项目成功的关键第一点是与当地有实力的公司建立稳固健康的合作伙伴关系，否则连参与的资格都可能没有；第二点是电表程序不能再和APE一样屡次出问题。', '建议立项，立即着手准备样机制作，同时确定合作关系，制作投标文件。', '陈雁2018-08-10 17:54:46', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('132', '{8951A458-D948-4E38-A7EC-1157EEE12484}', '60', 'INHE-0712', '2018-08-14 15:17:08', '0000-00-00 00:00:00', '2018-08-16 09:41:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081402/IDB', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目不需开投标保函，中标后才需要提供样机做测试，因此前期投入较小。经客服部技术技术解析，存在两个偏差点，已与客户澄清，客户可接受偏差。另外这个代理手上有较多电表招标项目，可通过此项目正式建立合作关系。请审核并批复，谢谢。', '杨晓婷2018-08-14 16:50:09', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('133', '{96D9DD95-5FB4-4966-A019-DAE5754EF6C1}', '60', 'INHE-0729', '2018-08-15 16:18:07', '0000-00-00 00:00:00', '2018-08-20 16:21:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081501/CFD', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '吴成博2018-08-15 16:22:58', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('134', '{EA5DC8C0-A514-434E-96F7-A7BBC8B9439B}', '60', 'INHE-0088', '2018-08-16 17:11:14', '0000-00-00 00:00:00', '2018-08-22 13:45:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081602/STE', '', '/', null, '/', '/', '', '/', '', '/', '', '/', '', '/', '', '/', '', '银河直供', '/', '电力公司有电表直接采购权', '', '电力公司采购部门确认价格后提供采购单PO，卖方开立发票供电力公司财务部安排支付货款，正常3-5个工作日内完成付款', '', '属该国电力部下，资金正常，如有大型项目可能引入ADB或世界银行贷款', '', '/', '', '已联系到电力公司技术部门、采购及高层', '', 'EDMI印度工厂、斯里兰卡本地厂家等', '', '价格及服务响应', '', '价格支持', '国家电力公司，经济状况良好，一般采用直接采购，能接受50%预付T/T或即期LC, 目前主要从EDMI印度工厂采购，年需求3000三相表，10000单相表，客户无三相表库存急采200台-500台三相表，单相表也有合作意向但现有库存，要求提供各2台样机（运费由电力公司DHL账户）安排电力公司认证，技术规格建议按我司现有普通单相三相表规格，推广进入该市场，同时开拓其他产品业务。', '余冬纯2018-08-21 08:42:08', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('135', '{14DC1BAC-F718-4CFE-89E4-6EA7AA541FBF}', '61', 'INHE-0440', '2018-08-17 01:44:33', '0000-00-00 00:00:00', '2018-08-17 16:07:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081701/TTC', '', '不适用', null, '3年框架合同直接采购自动重合闸设备', '不适用', '', '不适用', '', '不适用', '', '不适用', '', '不适用', '', '不适用，直接采购本地生产，需提供建厂方案', '', '不适用，大小A投资，银河技术支持，提供SKD/CKD，电力公司/内线占股份', '不适用', '\"电力公司为国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算，有较多的债务需要偿还，最近收了很多欠款回来，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。\r\r\r\r\r\r\n\"						\r\r\n', '', '待确认，直接采购，一般是10%的预付，40%发货前，50%发货验收后，30天内TT支付', '', '\"电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，有自己的银行，每季度几百万美金的款项可以支付出来。', '', '\"代理商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。代理和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验。', '', '\"配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室测试工程师等。', '', '待确认，目前ITL直接跟评标委员会主席合作，评标委员会主席接到能源部部长的指示，鼓励本地建厂生产自动重合闸设备。', '', '跟着政府的政策走，经销商有计划投资其他配电物料的本地生产，有较好的政商客户关系，但缺乏专业的团队和经验，需要依靠我司的支持。', '', '\"提供符合本地情况的建厂方案，产品价格合理，技术支持到位，必要的资金和客户关系建设开销等。						\r\r\r\r\r\r\n', '\"建议立项，准备建厂方案，支持大小A建厂，争取3年框架合同和后续的翻单。', '汤伟2018-08-17 02:41:58', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('136', '{E631BA61-4683-4CB4-919C-D1ACD7E15016}', '61', 'INHE-0713', '2018-08-20 16:33:04', '0000-00-00 00:00:00', '2018-08-22 11:51:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082001/GDN', '', '项目运作阶段，暂无', '2018-08-24', 'PROJET D’AMELIORATION DE L’ACCES A L’ELECTRICITE EN GUINEE (PAAEG)几内亚电力供应改善项目Composante 1 : Renforcement et extension du réseau dans les régions sélectionnées et normalisation des branchements illégaux组成一：加强和扩大选定地区的电网和非法连接的标准化', '暂无', '', '暂无', '', '暂无', '', '暂无', '', '暂无', '', '【需要客户服务部提供技术资料协助】\r\r\r\r\n\r\r\r\r\n项目需求产品全部需要提供技术文档', '', '暂定：代理商投标', '非联合投标', '政府重视电力公司电力供应盖上项目，但政府不直接干涉电力公司采购决策', '', '暂无', '', '本次电力公司电力供应改善项目已经取得世界银行资金支持，针对此项目第一部分，即【组成一：加强和扩大选定地区的电网和非法连接的标准化】，世界银行投资7900万美元\r\n\r\n\r\n代理目前经济状况良好', '', '银河与电力公司，银河与代理，电力公司与代理之间关系较好。\r\n\r\n\r\n代理公司内部团队分工明确，与银河团结协作', '', '银河与代理关系较好，代理与电力公司之间关系较好', '', '海兴与科陆必然会参与到此次招标数额较大的竞争中，\r\n\r\n海兴的后台在电力公司高层，由于之前银河代理客户关系没有十分稳固，导致之前AOR项目因为与海兴的竞争进展不太顺利，但此次代理已努力将客户关系做充分。', '', '银河将作为代理的供货商参与投标，并且在项目运作阶段提供技术规格参考，大大增加了银河在此次招标工作中的优势。\r\n\r\n银河要给出足够专业且具有竞争力的技术规格，排除不必要的竞争对手。', '', '需要客户服务部给出技术自持，对于项目所需要的产品技术规格给出协助。', '', '苏宏2018-08-20 17:52:54', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('137', '{1B93FE1B-DF97-42BA-8130-1945C9E12583}', '61', 'INHE-0431', '2018-08-21 09:39:41', '0000-00-00 00:00:00', '2018-08-22 09:15:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082101/LMU', '', 'OAB-TD-4222', '2018-09-10', 'Procurement of Single Phase Smart Energy Meters（单相智能电表采购）', '1.付款可使用L/C（仅针对外国供应商）,但是价格做0.5%的调整（评估报价比我们实际报价高）\r\r\n2.电表质保为交货后一年。系统有三年的维护期。', '', '打分规则为DAP价格*技术评比分（有加分项也算在内）=评估报价。其中技术评比规则中有E=必备项,D=加分项,O=可选项', '', '整个项目（电表+集中器+系统）会统一授标（不会分标）。\r\n', '', '不需要投标保函，但是需要履约保函（整个合同金额的10%，在出具Letter of Acceptance21天内开出，由毛里求斯有点的银行开出，有效期至交期之后60天）', '', '五年智能表生产经验。IDIS证书，G3-PLC证书。', '', '', '', '银河投标', '', '', '', '', '', '电力公司运营状况良好，近几年都有5000万美金左右的赢利。同时电力公司归政府所有，毛里求斯政府运营状态也较好。整个项目的支付能力较好。', '', '此项目虽然是银河直投，但是有当地代理做为合作伙伴。当地代理的情况是当地的Dell,联想，HP的代理商，也是TTN项目的关联企业，在当地有十分良好的客户关系。据称有在电力公司CEB供货过IT设备。', '', '当地关系暂有代理处理。后期根据项目情况我们出差处理。', '', '电力公司使用的系统是海兴和EDMI的。电表供应商有Elster A220,A1350, A1500\r\nLandis & Gyr ZMG\r\nEDMI MK10E, MK10A,MK7C, MK7B, MK6E\r\nIskraemeco. ME162, ME172\r\nHexing HXE 100KP, HX', '', '银河的劣势是之前有投过几个项目都没有下文，且主要动手如EDMI和海兴有电表和系统的供货。但是造成之前状况的原因是我们一直没有人深耕这个市场，同时当时的代理情况也不是很有实力。此次合作伙伴是TTN项目的关联企业，据称在当地很有实力。而且已经让对方去对标书做一些简单的修改。同时要求延标。如果实现上述我们要求的更改则证明客户关系良好，且此次代理做为当地的操盘手，我们做支持，主要投入是样机，文档等，额外的支出不多。', '', '', '代理是TTN项目代理推荐的关联企业，实力很强，他们在当地做主要关系，我们做为厂商做支持，提供投标文档及样机，且最后我们直接投标所以项目可控性也较好（不需要投标保函，需履约保函）。综合以上建议公司立项。', '刘佩2018-08-21 14:14:54', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('138', '{85DD5A56-19C1-4D48-87F5-8C6ED0961422}', '61', 'INHE-0642', '2018-08-21 16:56:34', '0000-00-00 00:00:00', '2018-08-22 14:31:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082102/M15', '', 'ESC0061/ICB/G/FY2018-1', '2018-10-05', 'Supply and Delivery of Prepaid Meters and Meter Boxes. 电表采购和交付项目', '价格条款：CIF\r\n交期：授标后的8-12周内交货,\r\n违约赔偿金：每周0.2%，最高10%合同总金额\r\n付款条件：Preferably open account subject to negotiations，最好是赊销，以谈判为准', '', '1.	初步评标，确认标书的完整性#FE54`填妥并签署的投标书#FE54`委托书#FE54`投标保证金#FE54`提供证书,投标的有效性；合格国家的投标人。\r\n2.	技术评标\r\n3.	商务评标，投标价格#FE54`调整价格以纠正算术错误#FE54`因折扣而调整的价格#FE54`不符合和遗漏的调整#FE54`适用所有评价因素、评价和资格标准#FE54`和由于适用优惠幅度而作出的调整.\r\n\r\n技术符合的前提下，价低者胜。\r\n', '{85DD5A5619C14D4887F58C6ED0961422074E749A304748709C51373D9D483750}_表1：M15投标项目信息归纳表.doc', '1个LOT\r\n', '', '1.投标保函金额为MK1,000,000.00或者等值的银河担保或者支票。汇率以Reserve Bank of Malawi汇率为准。 \r\n2.授标后30天内提供履约保函，金额为合同总金额的10%\r\n', '', '(a)符合最低技术规格\r\n(b)过去两年每年至少供应30万部预付费电表，\r\n(c)在非洲至少有两项价值至少超过100万美元的类似合同的电表供应经验\r\n(c)遵守交货时间表', '', '技术资料需要客服协助评估', '', '银河投标', '', 'ESCOM为国有企业，政府直接控制ESCOM走向						\r\n', '', '提交商业发票后的45天内付款', '', '银河与ESCOM执行过多个项目,ESCOM资信良好,但效率低下', '', '无合作伙伴', '', '一线客户关系良好，主要客户关系涉及层面为电力公司内部决策层以及应用层即采购和用服部门，同时也和项目评审中起关键作用的技术评标委员会和IPC等建立了较有深度的关系。', '', '该项目主要竞争对手为海兴和科陆。科陆代理为山东机械进出口，其主要背景关系为前董事会主席以及有政府背景人士，科陆在该市场供货单相表8万台左右，市场口碑较差。海兴在本地市场代理为Joh Achelis，在M14项目中中标两个lot，竞争策略为低价竞争。', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 通过采购和技术内线影响评标团队成员，并推进一和二审评标小组成员和银河评标规则的运作\r\n3. 协同IPC成员稳固评标小组运作优势', '', '项目成功的关键位：运作技术澄清和技术评标规则，同时和PL达成一致的行动计划。需要的支持：商务支持。', '该项目需要提供电表和表箱样机，并且有技术不符合点，建议尽快评估需要澄清的技术参数并准备相关样机空运到M国市场。\r\n							\r\r\n', '潘正豪2018-08-21 17:04:49', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('139', '{F3133988-BB5C-42AB-902E-7A079B2DB464}', '61', 'INHE-0695', '2018-08-27 10:01:48', '0000-00-00 00:00:00', '2018-08-28 10:52:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082702/KAZ', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '预付15%-30%的款项，剩余直接由融资银行向银河支付', '', '客户希望通过我们从中国进出口银行融资，融资期限6年，每年五百万。\r\n还款期限8年，每年融资款项（500万）分6期共三年还清。\r\n', '', '', '', '', '', '', '', '', '', '', '', '卿于蓝2018-08-27 13:32:12', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('140', '{8814DCC3-B1B4-4A84-BD31-6A054B67A29C}', '61', 'INHE-0662', '2018-08-27 09:57:29', '0000-00-00 00:00:00', '2018-08-28 14:40:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082703/DOC', '', '2018/S 129-295079', '2018-10-26', 'ELMU-éMáSZ villamos fogyasztásmér?k beszerzése（ELM?-éMáSZ采购电表）', 'winner会跟ELMU签署一个2年的框架合同，价格条款为DDP，质保期为试运行后2年，另外60个月的防腐蚀保修。交期为订单确认后的20天,付款为发票后30天通过bank of European Union.\r\n', '{8814DCC3B1B44A84BD316A054B67A29C8442F4C2B3234363A3D51C033076BD50}_hirdetmeny.pdf', '标准一为反向比率，标准二为评分，分数为0-100。电表性能也是评估标准，比如电表是否能够检测强磁。\r\n', '{8814DCC3B1B44A84BD316A054B67A29C074E749A304748709C51373D9D483750}_RD_III_kotet_szerzodeses_feltetelek_fin.pdf', '一家几个lot\r\n', '{8814DCC3B1B44A84BD316A054B67A29C2B47EB25ABE84FF19C47768372BB342D}_RD_IV_kotet_muszaki_kovetelmenyek_fin.pdf', '无\r\n', '{8814DCC3B1B44A84BD316A054B67A29C1DD410FC292E4E1893AFBEF9F88431CD}_RD_IV_kotet_muszaki_leiras_fin.pdf', '电表供应商需要有MID证书和供货记录\r\n', '', '客服部提供报价以及实验室制作样机\r\n', '', '代理商投标,代理直采\r\n', 'N/A \r\n', '该投标项目为公开招标，第一轮为投标意向阶段，现为第二轮需要在网上提交资料，所有资料均需用匈牙利语。欧盟未提供援助资金。', '', '开票后30天 ，具体细节还在跟客户沟通\r\n', '', 'ELMU已经被EON收购，EON为世界最大的能源服务提供商之一，2017年的营业收入约为40亿欧元，净收入40亿。支付能力足够。						\r\n', '', '我们当地的合作伙伴为电力公司的供应商，了解当地电力市场，与电力公司的经理熟识，能够获取到电力公司的一些内部信息。MD和owner为合伙人，关系融洽。						\r\n', '', '目前尚未去到一线，客户关系主要依靠当地的合作伙伴。						\r\n', '', '目前已知主要对手为罗马尼亚的电表供应商AEM和ITRON。目前还在跟客户沟通历史价格，以便能报出合适的价格。						\r\n', '', '银河在此项目中作为电表供应商，要求资质相对较低，主要是产品质量，认证以及价格。该市场银河是新人，跟当地的了解市场的合作伙伴合作可以较快，较容易进入市场。由于是公开招标，竞争应该会较激烈。银河一方面在做好自己分内事的同时，需要跟合作伙伴一起做好客户关系。', '', '产品符合电力公司要求，有竞争力的价格', '该市场的电表市场较有潜力，电表需求量大。合作伙伴也有一定的实力，目前还处在磨合阶段，通过一起做项目可不断加强联络，培养信任，最终更好的开拓当地市场。而对于该项目，合作伙伴表示也较有信心。', '陈丽2018-08-27 10:12:45', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('141', '{42E0CCBA-6D81-43A0-87B2-8AF3B63B5D88}', '60', 'INHE-0760', '2018-08-28 15:29:47', '0000-00-00 00:00:00', '2018-08-30 08:57:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082803/WKC', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '郝健颖2018-08-29 09:15:13', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('142', '{20F0AA9C-C0BD-4EBF-B096-06E1D5538A35}', '61', 'INHE-0744', '2018-09-03 10:00:55', '0000-00-00 00:00:00', '2018-09-11 13:38:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090301/UDP', '请补充详细信息', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '主要竞争对手为法国Sagem集团（本地有工厂，是电力公司现有机械电表供货商之一）、华为&科陆（拥有强大的营销手段）、海兴（本地合资品牌Intech）、Siame（原来电力公司的子公司，后进行了私有化改制，目前是电力公司机械电表的主要供货商）', '', '竞争策略：\r\r\r\r\r\r\n第一线：SAIME作为突尼斯的老牌表厂，同时与突尼斯国家电力天然气公司有着很不一般的关系，可以重点开发其为代理，合作模式可以为我司提供散件进行本地组装，供应模块和系统，建立全面合作关系；\r\r\r\r\r\r\n优势：一旦建立起深度合作关系，将会实现对突尼斯电表市场的主导！\r\r\r\r\r\r\n\r\r\r\r\r\r\n第二线：继续开发GEEC及类似公司（除了GEEC目前还有2-3家有其他的公司，均与电力公司有一定的业务和合作关系），直接推动电力公司做试点，进入该市场。同时考虑到对后续市场的开发，推动代理进行本地建厂。\r\r\r\r\r\r\n优势：易于管控代理，同时能够在该市场站稳脚步后，能够推动代理稳步向周围其他阿拉伯国家进行市场开发\r\r\r\r\r\n	\r\n银河有劣势分析:\r\n优势:银河有丰富的产品线及系统解决方案，可以根据当地的实际情况给出最合合适的方案。我司的二代模块表的双芯片的安全性、M-BUS协议对气表的兼容、双向计量功能都是非常符合该市场的需求。同时我司在非洲地区有很多的成功案例（特别是法语区的摩洛哥和科特迪瓦），能够让客户比比较容易的详细我们。\r\n\r\n劣势：由于我司进入该市场较慢，主要竞争对手在', '', '', '考虑到突尼斯市场对本国企业的保护政策以及对后续市场的开发，在与电力公司推进试点项目开展以便我司能够有资格参加招标的同时，积极鼓动代理商进行本地建厂开拓市场。', '郑超波2018-09-06 14:19:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('143', '{79071774-4775-454B-A786-3F8C60A22DAE}', '60', 'INHE-0549', '2018-09-04 09:38:10', '0000-00-00 00:00:00', '2018-09-12 15:22:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090401/PRE', '', '01/dao/AOI/PREREC.2/EDG/2018 Lot 4', '2018-09-15', 'PREREC2', '业主给KAMA付款，KAMA给我们付款', '', '价低者得', '', '一家中标', '', '投标人开立', '', '我司需要提供厂家授权和技术资料', '', '客服部协助提供技术资料', '', '代理商投标', '', '政府/政治对决策影响不大', '', 'KAM付给我司', '', '伊斯兰发展银行出资', '', 'KAMA总经理与几内亚能源部和财政部长来往频繁，KAMA内部高管为我司代理。', '', '交流密切，对方对于我司上市需要的协助非常配合。', '', '海兴在电力公司关系做得比较好', '', '该项目技术要求简单，基本上可以采用KM现有产品投标，代理希望我司给一个优惠的价格中标。', '', '价格有竞争力', 'KAMA总经理在几内亚电力公司一直阻挠（要求换海兴）的情况下还是力保由我司供应KM的产品。去年找我司合作几内亚的招标项目时，由于二部已经和他们的代理合作了，我们拒绝了KAMA，对此，KAMA高管非常不满意。本次招标，KAMA又向我司发出了报价要求，如果我司再次拒绝的话，对于之后的合作以及一直打算在几内亚实施的带资金的EPC项目应该会有一定的影响。故而希望公司能够考虑与其在该项目上的合作。对于该招投标项目，有包括TAS、中水电和NCCIndia在内的五家公司通过了资格预审，KAMA与中水电合作。标书中没有地方说到一个厂家不能授权两家投标人投标。KAMA同意采用我们之前KM提供的样机投标，我司只需要提供：报价、技术资料和通过我们的合作伙伴KAMA授权中水电应答该招标项目。', '王秀明2018-09-11 09:19:03', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('144', '{E0D547A6-EC82-44E0-B4DD-A3150F48C99E}', '61', 'INHE-0695', '2018-09-04 16:39:00', '0000-00-00 00:00:00', '2018-09-07 08:49:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090402/NBT(旧)', '', '', null, '', '\r\n具体商务条款待正式开标后确定\r\n', '', '先技术后商务\r\n', '', '预计多家中标（试点项目），待正式版确定', '', '', '', 'MID资质+本地认证，本地认证针对无功计量项。\r\n本地认证可在中标后再进行。\r\n\r\n', '', '', '', '银河投标', '', '', '', '代理描述：立陶宛及波罗的海地区默认 付款条件为发货后30天付款，交期根据项目情况由4周-12周变化\r\n\r\n正式付款条件待正式开标获取商务文件后确定\r\n', '', '', '', '代理此前在代理 Actaris（Itron） 的产品，比较懂电表。\r\n认识电力公司对应的负责人，但尚未足够了解其之间关系。\r\n', '', '之前通过EGC项目，竞争对手Elgama的内线了解到一定的对方产品信息及智能电表产品报价', '', '本地表厂Elgama，Apator及ADD Grup. 海兴尚不确定。\r\n具体有意参加的表厂，待观察9月19日电力公司公召开的会议参与厂家确定。\r\n', '', '', '', '', '', '卿于蓝2018-09-04 16:53:45', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('145', '{F356B5C8-E908-4B9F-BA71-87E5B8E8EA7C}', '61', 'INHE-0578', '2018-09-06 16:58:54', '0000-00-00 00:00:00', '2018-09-10 13:44:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090601/COP', '', '48G/2018/19', '2018-09-25', 'The supply and delivery of three phase electrical power line telecommunication (PLT) prepayment meters供应及交付三相PLC通信预付费电表', '价格条款：DDP\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n付款主体：City of Cape Town\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n付款条件：无预付款，先交货后付款，每个月23~26号支付上个月20号前收到的发票。\r\r\n\r\r\n\r\r\n交期：本地生产需在合同签订后8周内交货，国外供货则需在12周内交货。\r\r\n\r\r\n\r\r\n质保：需对产品提供5年质保，质保期间发生的损坏需无偿补偿。\r\r\n\r\r\n\r\r\n违约：需按时交付货物，若延迟交货，则按照每周1%延迟交货的货值罚款，上限为全部延迟货值的10%。', '{F356B5C8E9084B9FBA7187E5B8E8EA7C8442F4C2B3234363A3D51C033076BD50}_City of Capetown Tender Docs.pdf', '1. 商务文件评估；2.价格评估；3. 样机测试；4.资质及评分。\r\n\r\n\r\n将按照80/20标准打分，80为资料、报价、样机，20为BBBEE资质等加分项打分。得分最高者中标。', '', '一个lot,得分最高者中标。', '', '无需开立保函。', '', '需为本地注册公司，需为CSD及开普敦系统注册公司，需具备BBBEE资质等。电表产品需提供相应的STS证书，测试报告等。对供货记录等无严苛要求。', '', '部分技术应答及技术资料需技术支持协助提供。', '', '银河授权代理商投标,NYC投标，银河做技术支持。', '', '开普敦市政内部决策，评分最高者中标。', '', '先交货，后付款。每个月23~26号支付上个月20号前收到的发票。', '', '开普敦为南非主要旅游城市，各项基本设施完善，财政运营状况较好。\r\n\r\n\r\nNYC作为银河在南非市场的主要客户，对于订单执行没有太大问题。', '', '优势：ESA项目在开普敦有供货，积累了一定的口碑；AUW展会每年在开普敦参展，积累了一定的人力资源。BBEEE资质具有较大优势。\r\n\r\n\r\n劣势：此前未参与此市政投标，对于内部流程，主要客户关系把握不够。', '', 'NYC掌握主要客户关系，银河与NYC一起参与。', '', '主要竞争对手为兰吉尔，CONLOG，海兴。兰吉尔及CONLOG在市政供货有着深厚的基础，海兴在价格方面占有一定优势。', '', '银河需在市政全面打开局面，大力参与到投标中，以更好摸清各市政招标、采购、决策流程，开始建立客户关系。此阶段主要协助NYC做好投标工作，一起进行客户关系拓展，做好后期的宣传等工作。', '', '技术需要符合（OFDM调制，CENELEC-A频段），样机需要符合，价格需要有竞争力；需要NYC在前线主导客户关系拓展。', '建议立项。', '覃湘君2018-09-06 17:26:25', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('146', '{10EE681C-F5F9-49DD-8F5F-7C83D7A5F39D}', '61', 'INHE-0725', '2018-09-07 10:23:08', '0000-00-00 00:00:00', '2018-09-11 13:39:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090701/IRL', '', 'IBEDC/MAP2018', '2018-09-13', 'PROCUREMENT OF METER ASSET PROVIDER (MAP) TO PROVIDE METERING SERVICES TO IBADAN ELECTRICITY DISTRIBUTION COMPANY PLC., (IBEDC)伊巴丹电力公司针对电表供应商（MAP）发起的电表及服务招标项目', '付款条件：该项目为融资项目，招标方付款方式为无预付款，后续电表安装后用户上缴电费而后按月支付，代理中标后会在当地银行抵押合同获取融资作为我方生产资金，我方作为供应商为其提供电表并与供应商签订合同，合同具体条款正在商讨中', '', '先技术后商务，招标方会首先查看保函，而后在当地时间9月13日上午11点进行技术评标，技术得分满分100分，大于或等于70分的投标方进入第二阶段商务评标；商务评标评审价格，价格低者为优，预计3-4家中标', '{10EE681CF5F949DD8F5F7C83D7A5F39D074E749A304748709C51373D9D483750}_评标规则.pdf', '3-4家中标', '', '我方本次为供应商，无需开立保函', '', '投标方需具备NG市场NERC(尼日利亚电力管理委员会）颁发的“No Objection”证书以证明他们符合今年四月份尼日利亚政府颁布的“MAP Regulation”的相关要求，目前尼日利亚已有65家公司已获得“No Objection”证书，具备该资质。但其他公司可以通过联合投标或是成为供应商的形式参与进来。', '{10EE681CF5F949DD8F5F7C83D7A5F39D03404677E4D44E9EB56B3D512B2AF9CC}_能参与尼日利亚本地电表招标公司名单.xlsx', '需要客服部协助评估技术要求，此外需要商务部门协助整理审核我方提供的资料', '', '代理投标', '非我方投标，我方做Supplier', '客户告知评标将由Ibadan电力公司内部进行，Ibadan在决策中扮演重要角色', '', '客户付款流程：该项目为融资项目，招标方付款方式为无预付款，后续电表安装后用户上缴电费而后按月支付，代理中标后会在当地银行抵押合同获取融资作为我方生产资金，我方作为供应商为其提供电表并与供应商签订合同，合同具体条款正在商讨中', '', '客户采取在当地银行融资手段支付我方货款，后续与客户具体洽谈付款细节，招标方Ibadan资金充足，如我方代理中标，招标方会提供正式的保证文件', '', '代理对于整个投标项目很有规划 ，而且主动提出融资方案（中标签订合同后从当地银行获取投资），同时该客户与招标方关系密切，与招标方Ibadan电力公司的副总经理，采购总监较为熟识，而且与负责评标中的两人关系较好（负责评标人数共五人）', '', 'IRL为我方老客户，之前多次进行订单及项目合作，我方与客户关系较好，客户对于操作融资项目也有一定经验，尤其是与本次投标项目的招标方关系较好，目前客户已经和两名评标内线提前联系，后续客户也会继续运作，争取更多支持。', '', 'NG市场的NERC(尼日利亚电力管理委员会）在今年将“No Objection”证书颁发给当地的65家电表供应商，证明其资质，目前NG市场的MAP投标项目只针对这65家公司开放，但其他公司可以通过联合投标或者以供应商的形式参与进来；从代理处获知竞争对手主要有Omniswift Nigeria Limited以及Carlin Concept International Nigeria Limited(海兴代理)等10家公司。', '', '代理与招标方关系较好，有利于后续我方中标；并且主动构思提出融资方案及切实的解决措施，对于融资项目也有一定的经验；代理融资同时也极大减轻了我方的风险；虽然该投标项目的时间较为紧张，但凭借代理的运作，以及我方积极配合，我方就会占据巨大优势。', '', '该投标项目时间较为紧张，不仅是对我们，对其他公司也都是严峻的考验，代理反馈当地许多竞争对手保函开立都遇到了困难（时间较为紧张），而客户在当地开保函极大节约了时间，只要后续我方做好相关文件准备，加上代理运作，中标可能性很大；需要公司支持以加快相关文件准备速度。', '该项目有以下几点优势：1.代理与招标方关系良好，可通过运作提高中标可能性；2.代理自行提出融资方案并对于融资项目有一定的经验，对于整个项目有规划，同时代理融资也大大降低了我方的资金风险；3.代理反馈该投标项目时间紧张，大多数竞争对手都遇到了保函开立时间不足的问题，而代理可在当地开立保函，节约了大量时间，只要后续文件准备充分，公司便可抢占先机；4.我们之前还未操作过NG市场MAP投标项目，本次参与投标项目也是为NG市场后续其他电力公司的MAP投标项目积累经验，有利于我方占据更多市场份额拿订单，结合以上优势，希望公司予以支持，谢谢！', '赵政洁2018-09-07 12:28:27', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('147', '{1A01B8AE-3207-43C9-A0F4-A954A8FDDABC}', '61', 'INHE-0440', '2018-09-09 16:52:34', '0000-00-00 00:00:00', '2018-09-11 13:39:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090901/TTL', '', 'PA/001/2018-19/NZN/G/31', '2018-09-19', 'SUPPLY OF METERS FOR NORTH ZONE REGIONS UNDERFRAMEWORK CONTRACT 框架合同供应电表给北区各地区', 'TANESCO付坦先令。国内付款条件为： (1)按分订单/LPO10%的金额，在30天内支付，需提供相对应的收据和银行担保后。(2)20%的合同金额，在发货时提供采购主体在本地工厂的验收报告后30天内支付。（3）70%的合同金额，收货后在提交付款申请和电力公司各地区仓库的验收证明后30天内支付。                                                        质保期限：自各地区接受货物起12个月。交期：接到分订单/LPO后2周内交货。违约：百分之0.001/天，未发货产品，最多10%。', '', '3年框架合同国内限制性招标，目前由ITL和EDMI两家厂商参与。先评估技术，然后评估商务，实际上一审是商务和技术一起评估。电力公司希望授标的价格为单相DDP 55美元左右，三相直通150美元左右，ITL和EDMI需参考授标价格报价。请参考附件评标流程。', '{1A01B8AE320743C9A0F4A954A8FDDABC074E749A304748709C51373D9D483750}_TANESCO Tender Evaluation Process (Updated).xlsx', '只允许本地厂商投标，目前符合资格要求的有ITL和EDMI,每个厂家最多分2个LOTS。', '', 'TL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，无质保保函，由ITL/Africarriers 负责所有的保函。', '', '过去三年（2015-2017）的财务报告，包含由总监签字的资产负债表和现金流声明,年平均营业额至少300，000，000先令。每月现金流至少50，000，000先令。至少2年供应/生产类似规模产品的经验。过去2年至少2个供应/生产类似规模产品的经验。', '', '非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。具体参考评标流程。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)按分订单/LPO10%的金额，在30天内支付，需提供相对应的收据和银行担保后。(2)20%的合同金额，在发货时提供采购主体在本地工厂的验收报告后30天内支付。（3）70%的合同金额，收货后在提交付款申请和电力公司各地区仓库的验收证明后30天内支付。                                                 本地供应商的付款，在提交每个阶段的资料后，30天内TT支付。客户想要运作成为LC付款。                                                ', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，有自己的银行，每季度3.5百万美金的款项可以支付出来。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是TB主席，电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者退休的配电副总，用服总监，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理等，TTN项目单相表FOB 41美元。EDMI主要是供三相分体式直通/CT/VT表，上次投标，三相直通DDP 310 美元，单相表FOB 45.26美元。威胜TF项目BS单相分体加表箱价格DDP 52 美元，FOB 41 美元左右，TTN项目FOB 36美元。科陆农电项目BS单相分体加表箱价格FOB 39 美元，LTA项目FOB 48 美元，TTN项目FOB 32.5美元。目前市场上主要的本地厂家为ITL和EDMI。海兴，威胜和科陆计划建厂。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签了批量SKD合同和安排付款，满足供货要求。3年框架合同，标书的技术规格，单相和三相直通和TTA一致,CT表1级，CT/VT 0.5级表和低压计量箱尽量按照技术规格做。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以在未来3-5年获得稳定的订单来源。', '', '产品报价符合市场形势，样机制作按时交付，技术支持和研发人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '汤伟2018-09-09 19:47:10', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('148', '{2FF88280-721C-42E5-8468-17732C364054}', '66', 'INHE-0579', '2018-09-10 17:19:47', '0000-00-00 00:00:00', '2018-09-12 15:35:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091001/BRT', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.KLK作为银河在布隆迪的经销商，将电表销售给电力公司。\r\r\r\n2.与KLK直接合作，风险较小。KLK支付方式为100%T/T发货前支付或L/C支付。\r\r\r\n3.技术规格为该市场之前的招标要求。客户只要求PLC通讯方式，已与其确认，提供银河PLC通讯方式的一体式代码表让电力公司检测。', '孙娜2018-09-11 14:59:31', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('149', '{4D419652-74BB-446E-9B85-016F9499CAA9}', '93', 'INHE-0762', '2018-09-10 16:59:18', '0000-00-00 00:00:00', '2018-09-12 15:35:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091002/DAO', '', '暂无（目前只收到项目草标，项目还未正式招标）', null, 'POUR LA FOURNITURE DE COMPTEURS D’ENERGIE ELECTRIQUE A PREPAIEMENT ET LEURS ACCESSOIRES', '交期：从下中标函开始五个月内送货到客户指定地点\r\r\r\r\n违约金：P = M x N / 1000 /  M为为交付货物的合同金额。N为延迟时间\r\r\r\r\n违约金上限不超过合同金额的10%\r\r\r\n\r\r\r\r\n付款方式：\r\r\r\n-预付款为30%合同金额，在授标后收到发票30天内支付\r\r\r\n-其余进度款将在收到发票后及时支付\r\r\r\n备注：由于目前获取标书为草标，付款方式可运作', '', '-不符合项扣分\r\r\n-折扣加分\r\r\n', '', '根据目前收集到的信息，水电局将邀标五家表厂，最终一家中标', '', '-在布隆迪境内银行存入200,000 Burundian Francs或其余货币同等资金\r\r\r\r\n-有效期：未中标者在投标失效后30天内退回，中标者直接转化为履约保函部分金额\r\r\r\r\n-无需开质保函', '{4D41965274BB446E9B85016F9499CAA91DD410FC292E4E1893AFBEF9F88431CD}_表1：AAOOI投标项目信息归纳表.doc', '\r\n\r\n-预付费电表需要有STS资质\r\n\r\n其余暂无要求', '', '-投标资料翻译（标书为法语，资料需要准备为法语提交）', '', '银河直接投标', 'N/A', '政府决策，该项目17年由Hexing中标但由于政治人物变更而废标，现重新发标由公开招标改为限制性招标', '', '暂未获取', '', '该项目为客户自筹资金，具体支付能力有待调研', '', 'N/A', '', '-目前已经与水电局局长在北京见面，并预约在布隆迪进行深入拜访推介\r\r\r\r\n-同时在水电局内部项目执行层面有潜在代理一名，其向银河反馈了项目草标以及废标前的项目评审报告', '', '该项目废标前的中标方为Hexing，附件为其标书评审报告', '{4D41965274BB446E9B85016F9499CAA9C8C3CDC70C5243B796247CC1ED7EC56E}_Evaluation report-power meters.docx', '-银河与项目正式招标前已经通过代理拿到草标，准备时间充分\r\r\n-银河已经与布水电局局长在北京见面建立良好关系\r\r\n-银河可以在正式发布标书前通过关系运作对标书进行一定程度的修改', '', '成功关系：\r\n-与客户协商到合适的付款条件以及相关技术条款的变更，了解到客户的预算\r\n\r\n需要支持：\r\n-由于标书为法语且提交项目资料为法语，需要安排法语组商务进行支持', '', '莫林睿2018-09-10 19:31:07', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('150', '{437B9D31-8C0D-4D61-AA93-2BCA04D5F813}', '61', 'INHE-0434', '2018-09-17 03:12:12', '0000-00-00 00:00:00', '2018-09-19 09:10:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091701/SRM08', '', '', null, '该项目还未正式招标，当前为立项需解析技术规格，项目预计下周（17号这周）招标。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1、SRM08招标项目EEU还在准备阶段，但预期下周（17号这周）招标，负责人EEU能源部门主管Abay将技术规格草稿给了我们，希望我方能下周二给予反馈和意见。\r\r\r\r\n2、SRM08项目被视为SRM07项目的备选方案，Abay告知其希望尽快完成对CMRI设备的采购，希望我方参与投标。\r\r\r\r\n3、Abay告知该项目会通过ICB招标。\r\r\r\r\n4、EEU内部在新总理上台后进行了洗牌，个人认为可以通过SRM08继续深入建立客户关系、明则全面支持EEU工作参与SRM08招标，暗则借SRM08机会加强客户关系为SRM07助力。', '钟云林2018-09-17 04:29:46', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('151', '{CE2BF04A-9A90-42E6-9F65-09C27D532B76}', '61', 'INHE-0578', '2018-09-18 02:38:44', '0000-00-00 00:00:00', '2018-09-19 09:08:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091801/KLM', '', 'S1/2018', '2018-10-12', 'Supply and delivery of STS prepaid electrical meters供应及运输STS预付费电表', '价格条款：DDP\r\r\n\r\r\n\r\r\n付款主体：Kouga Local Municipality\r\r\n\r\r\n\r\r\n付款条件：发货后，收到付款发票的30天内支付本地币\r\r\n\r\r\n\r\r\n交期：由厂商投标时明确，建议4~6周\r\r\n\r\r\n\r\r\n质保：电表安装日后12个月质保，质保期内的问题产品需免费更换\r\r\n\r\r\n\r\r\n违约：若实际交期与投标时明确交期严重不符，则视情况需每天支付受影响货物货值的10%，总合同金额的10%封顶。\r\n\r\n\r\n实际：银河与NYC直接交易，付款预计与ESA项目保持一致。', '{CE2BF04A9A9042E69F6509C27D532B768442F4C2B3234363A3D51C033076BD50}_TENDER DOC NOTICE 152 OF 2018 CONTRACT S1 of 2018 Prepaid Electrical Meters.pdf', '采用80/20 体制打分：价格80%占比，BBBEE资质等20%占比。', '', '3个lot，得分最高者中标。', '', '中标后，签订合同30天内需开立履约保函，由NYC开立。', '', '对公司财务数据、财报要求较为严格（NYC资质），本地化要求高，需达到≥70%。', '', '部分资料或许客服部协助制作，最晚10月9日完成所有资料制作。', '', 'NYC直接投标，银河作为厂家支持。', '', '由该市政自行决策。', '', '收到货物并收到对应发票的30天内支付；NYC对银河直接付款，付款流程预计于ESA项目保持一致。', '', '较好。', '', 'NYC在BBBEE资质和本地化生产资质方面具有较大优势，另外在ESKOM的供货也有一定优势。但目前在该市政并无太好人际关系。', '', '暂无。', '', '主要竞争对手为兰吉尔，垄断该市政多年，在南非市场的影响力很强，但价格偏高。', '', '1. 利用NYC的资质优势 + 价格竞争。（因为评估原则就是价格占80%比例，资质占20%）', '', '价格必须有竞争力，投标资料必须完备；需要商务支持。', '建议立项并立即开始投标工作（中秋假期、十一假期较长）。\r\n\r\n\r\n因现场工作饱和，项目组人员基本出差，因此需申请全方面商务支持。', '覃湘君2018-09-18 03:00:18', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('152', '{8967285C-A44E-4747-9ECA-6212429956D1}', '60', 'INHE-0549', '2018-09-19 23:21:45', '0000-00-00 00:00:00', '2018-09-25 14:06:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092001/EPS', '', '无', null, '无', '无', '', '无', '', '无', '', '无', '', '无', '', '无', '', '无', '无', '主要看技术是否符合，价格是否最优', '', '100%不可撤销的即期信用证', '', '改项目是客户带资金做的EPC项目，客户资金调动能力强。', '', '福雷斯特集团在刚果金做了很多年的项目了，对该国国情与内部人员应该比较熟悉。', '', '能源分支的CEO与我司在16年有过合作，现在也保持联系。', '', '他们希望我们给出FOB价格，没有提供目标价格，目前询了几家表厂了，最终通过比较质量和价格决定采用哪家的产品。', '', '由于之前有过合作，对方目前相应很积极，如果价格合适的话，相信我司可以拿下该项目，并打开刚果金和比利时的通道。', '', '关键在于价格，需要客服协助技术解析', '该项目是客户在刚果金电力公司带自己的资金做的一个在卢本巴希和马诺诺两个城市的电表供货与安装项目。目前客户已经和电力公司签了合同，合同上要安装和交付的电表是兰吉尔的表，但是客户希望在技术满足的前提下用另一家价格更有优势的厂家的产品。电力公司没有技术规范，所以客户只提供了兰吉尔电表的技术文件，电力公司没有系统，所以需要我司提供完整的售电方案。如果我司价格诱人，我相信客户一定会采用我司产品供货。', '王秀明2018-09-20 00:21:32', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('153', '{94CB7079-DB06-4AC1-8363-F385F3095E01}', '61', 'INHE-0440', '2018-09-20 05:24:06', '0000-00-00 00:00:00', '2018-09-25 14:04:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092002/TTM', '', 'PA/001/ 2018-19/DZN/G/ 34', '2018-10-03', 'Supply of Meters for Dar Es Salaam & Coast Zone under framework arrangement 框架合同供应电表给达市和海岸各地区', 'TANESCO付坦先令。国内付款条件为： (1)无预付款和发货款。（3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                        质保期限：接受货物起12个月，发货后18个月。交期：一年内交完各分订单/LPO的货。违约：百分之0.2/天，未发货产品，最多10%。\r\n', '', '框架合同国内限制性招标，目前由ITL和EDMI两家厂商参与。先评估技术，然后评估商务，实际上一审是商务和技术一起评估。电力公司希望授标的价格为单相DDP 55美元左右，三相直通160美元左右，ITL和EDMI需参考授标价格报价。', '', '只允许本地厂商投标，目前符合资格要求的有ITL和EDMI,每个厂家最多分3个LOTS。\r\r\n', '', 'ITL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '过去三年（2015-2017）的财务报告，供应/生产类似规模产品的经验,人员资质，设备和生产能力等。', '', '非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。客户想要运作成为LC付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，有自己的银行，每季度3.5百万美金的款项可以支付出来。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是TB主席，电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者退休的配电副总，用服总监，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理等，TTN项目单相表FOB 41美元。EDMI主要是供三相分体式直通/CT/VT表，上次投标，三相直通DDP 310 美元，单相表FOB 45.26美元。威胜TTN项目FOB 36美元。科陆农电项目BS单相分体加表箱TTN项目FOB 32.5美元。目前市场上主要的本地厂家为ITL和EDMI，国内限制招标方面可以一起合作应对以后海兴，威胜和科陆计划建厂。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签了批量SKD合同和安排付款，满足供货要求。框架合同，标书的技术规格为一体式单相和三相直通表，需要重新制样，TI项目供过一体式代码表和表箱给到电力公司。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以在未来2-3年获得稳定的订单来源。', '', '产品报价符合市场形势，样机制作按时交付，技术支持和研发人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '汤伟2018-09-20 06:30:18', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('154', '{7C4A9139-FE69-4143-AB80-0898454451C8}', '61', 'INHE-0593', '2018-09-21 05:50:22', '0000-00-00 00:00:00', '2018-09-26 09:42:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092101/BFC', '', 'APPEL D’OFFRES N° ………', '2018-11-01', 'POUR LA FOURNITURE DE COMPTEURS D’ENERGIE  ELECTRIQUE MONOBLOC A PREPAIEMENT  A LA SONABEL 为sonabel提供单三相一体式预付费电表', '交期是在签订履约服务条款之后的90天内。\r\r\r\r\r\r\n罚金条款：\r\r\r\r\r\r\n合同总金额1%/周的罚金。罚金若超过合同金额的5%将取消合同。\r\r\r\r\r\r\n标书草稿中没有体现结算方式\r\r\r\r\r\n参考BFN09/BFN10标书结算方式\r\r\r\r\r\n预付款：合同签订及收到供货商履约保函及付款请求后，电力公司支付合同总金额10%的预付款；\r\r\r\r\r\n装船：合同总金额80%交单后通过保兑的不可撤销的信用证结算；\r\r\r\r\r\n收货：剩下合同总金额的10%将在收货后的30天内结算，需要获得电力公司验收合格的报告。\r\r\r\r\n\r\r\r\r\n\r价格条款：TTC 电力公司仓库（TTC包括了DDP及DDP费用以外的卸货费等其它一切可能的杂费）\r\r\n\r\r\r\n质保为电表验收后12个月', '', '1.	在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。\r\n2.	接下来评技术部分，技术资料是否满足标书的技术规格 。\r\n3.	评财务部分。评完财务文件，价格最低者中标。\r\n', '', '一家中标，同一个投标商可以中多个lot，一家制造商可以同时授权多个投标商投标', '', '-	金额（汇率根据截标前14天,西非国家中央银行的汇率换算。）\r\n-	投标保函：金额待定\r\n-	货币要求西非法郎\r\n-	投标函应在投标有效期内均有效。\r\n', '', '对资质无特殊要求', '', '无', '', '建议为代理投标，银河作为供货商。', '无', 'sonabel为100%国家控股公司，政府对电力公司采购决策影响大。', '', '中标商提前缴纳合同对应的登记税及许可税后，电力公司开出信用证或付款。', '', '/', '', '老客户', '', '主要客户关系在于实验室，软件部及电力公司个别总监，目前招标委员会高层未涉及。', '', '电表方面主要对手为海兴，海兴在BFN主要推低价战略，具体可参考BFN06/BFN09/BFN10开标结果。建交后会有更多的竞争对手进驻该市场。', '', 'BFN03/BFN05执行，银河在BFN电力公司积累了一定的基础；代理非本国人，却能从98年开始每年都卖几万台机械表给BFN电力公司，近两年将银河电表及系统引进电力公司，代理在该市场有一定的实力及人脉。银河及代理加强合作及信任，中标可能性较大。', '', '银河与代理的密切合作；银河对电力公司招标文件技术规格的影响；代理客户关系', '建议立项，项目组成员建议为胡蝶，张柳芳。', '胡蝶2018-09-21 10:19:17', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('155', '{7B3508E6-C6C6-452B-BE79-3E7031098368}', '61', 'INHE-0654', '2018-09-21 09:31:44', '0000-00-00 00:00:00', '2018-09-21 09:55:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092103/PSA20', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1，代理只需要采购CIP提供给以前项目PSA10的电力公司，但由于PSA10项目当时的客户信息不是MESSEN,所以为了后面合同评审，需要重新走一个立项，命名为PSA20.2，CIP是试用给此前项目PSA10项目上的电表。', '李明2018-09-21 09:51:58', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('156', '{1BF65EE2-0BB6-4703-B304-480CFF9254E5}', '61', 'INHE-0500', '2018-09-24 10:40:29', '0000-00-00 00:00:00', '2018-09-29 10:19:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092401/BCA', '', '2850/18', '2018-10-12', 'The Supply of single(1) phase and three(3) phase split sts prepayment smart meters with open standard ofdm G3-PLC communication, and pole mounted meter boxes.供应单相和三相分体式智能电表，电表要求采用OFDM G3-PLC通讯，配备电线杆安装表箱', '标书价格条件：货交30天内见发票付款\r\r\r\r\n代理和银河之间付款条件：待协商，优先采用T/T预付+保兑信用证\r\r\r\r\n标书价格条款：DDP 电力公司仓库（不含VAT）\r\r\r\r\n银河对代理报价条款：CIF Gaborone\r\r\r\n交期要求：收到电力公司正式采购订单后16周内完成交付\r\r\r\n', '{1BF65EE20BB64703B304480CFF9254E58442F4C2B3234363A3D51C033076BD50}_general trender conditions.pdf', '分为三个评标阶段。\r\r\r\r\n第一个阶段：商务资料审核，详见商务部分第20页要求；\r\r\r\n第二个阶段：技术评审，可能会涉及到现场演示环节（因为已经供过BAP的分表业务，代理已经非常熟悉我们的电表，我们可以培训代理进行现场演示）；\r\n第三个阶段：价格评审\r\n\r\r\r\n\r\r\r\n', '', '电表一家中标，表箱可能分开另一家中标，也有可能电表和表箱都是一家中标', '', '代理投标，无需开立保函', '', '证书方面：厂商要求提供MID Module D证书；电表偏好 ALT证书，其次要求SLT证书。\r\r\n技其他条件同BEA项目。', '', '1.需要实验室协助按要求提供样机，要求10月6日前完成；\r\n2.需要客服工程师协助做技术解析，要求9月30日前完成；', '', '代理直接投标，银河做厂商支持', 'N/A', '此市场政府项目采购流程较规范，但同时负责电表的CSS Director部门，以及下属MEM部门在技术评审和推荐上起重要影响作用，在满足价格具有竞争力的前提下，只要MEM部门经理 MM关系打通，技术评审无异议，中标几率很大。\r\r\n', '', '代理直接投标，银河做厂商支持\r，代理和银河之间付款条件：待协商，优先采用T/T预付+保兑信用证\r\r', '', '最近的电力公司营收、利润、盈余能力请见附件', '{1BF65EE20BB64703B304480CFF9254E5108D268797C74834B1DDE2FC1083AA37}_2016-2017财年BPC财年汇报.pdf', '1.代理FFL是此市场唯一一家专业从事智能电表、水表的工程公司，银河通过此代理从2017年开始以缓慢供应商1000台分表业务的智能电表和全套管理系统，代理技术经验较为丰富；\r\r\r\r\n2.通过2016年出差以及近两年的关系运营，代理和CSS Director和MEM部门经理 \rMM取得了一定关系建设；\r\r\r\n\r\n3.代理公司老板年富力强，有冲劲和决心，配合度较好。', '', '1.CSS Director对银河有初步的了解。MEM部门经理 MM2016年出差见面多次，代理重点关注对象保持着不错的联络关系；\r\n2.代理在和电力公司管理层 COO方面近期也取得了联系。', '', '主要竞争对手：兰吉尔，此次电力公司招标规格经过初步分析，推测是按照兰吉尔E460 DIN导轨表的基础上进行了改良和修正，对银河来说增加了部分难度（样机和演示）\r\r\n备注：由于电力公司前期和海兴供货质量和服务的矛盾，以及南非海兴和其之前博茨瓦纳代理Actom的分裂，基本上此市场海兴的影响力可以暂时排除。', '', '1.通过前期2016年出差，基本上和代理结识了技术层面的主要负责人，并进行了DIN III、售电系统、CT表的严格测试，测试结果OK，售电系统的演示电力公司也基本满意，在电力公司内部的辨识度有了一定的积累；\r\r\r\r\n2.代理在近一年按照计划对MEM部门经理MM和管理层重要人物COO进行了多次公关和游说，积累了一定的客户关系；\r\r\r\r\n3.分表市场已供货的1000余台智能电表和系统，可以作为一个现场的供货凭证和经验参；\r\r\r\n劣势：\r\n1.代理的财务能力还不足，无法较大规模实施如本地组装厂的建立，增加说服力；\r\n2.技术层面的关系还有待进一步的加强。', '', '1.样机按时提交，并且基本保证按照标书技术规格提供；\r\n2.现场演示也是关键，需要提前给代理进行培训；', '1.BLD仅仅属于此市场新智能电表的重新招标采购  试点项目，后续整个市场会更换为新一代的智能电表，市场需求量在10万（保守数据）以上，我们需要抓住这个时机，在样机提交和演示环节做到满足电力公司的要求；\r\r\r\n2.客户关系层面的建设需要进一步推动代理，如必要李忠鹏10月出差南非可以直接过去此市场一次短差再次巩固和电力公司技术部门的关系；\r\r\r\n请公司审批！', '李忠鹏2018-09-25 22:08:41', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('157', '{A69F2252-AA97-4653-95A1-737B912D60A8}', '93', 'INHE-0762', '2018-09-25 03:24:45', '0000-00-00 00:00:00', '2018-09-29 10:18:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092501/SSP', '', '01 /G/18 8- - 19/I IC C B/EARP- - RESSP', '2018-11-08', 'Rwanda Energy Sector Strengthening Project（RESSP）', '付款条件：10%预付在签署合同后45天内付款，80%在收到要求的发货单据后信用证支付，10%尾款在签收后45天内支付；\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n交期：最早3个月到指定交货地点，最晚4个月到指定交货点；\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n违约金：0.5%合同金额/周', '{A69F2252AA97465395A1737B912D60A88442F4C2B3234363A3D51C033076BD50}_Bidding Document_Supply of Electrical Materials_13092018_看图王.pdf', '按照标书要求为技术+商务评分，技术标过后商务标价格最低者中标\r\n备注：代理反馈其不尽然为价格最低者中标，具体评标需要综合分', '', '改标书中包含两个LOT，我司只参与其中表计，表箱,CIU的提供', '', '投标保证金：10000美金。如不中标则在投标有效期失效后28天内退回，或收到投标方申请后退回；如中标则在收到签署的合同以及质保后退回；\r\r\r\r\r\r\r\r\n\r\r\r\r\r履约保函：10%的合同金额，需要在中标后28天内开具；\r\r\r保证金在供应商履约完成后28天内退回；\r\r\n开立行：仅接受地银行开具保函\r\n\r\n质保有效时间：货源地发货后18个月或者客户接受货物后12个月', '', '需要提交资质证书，公司宣传册，测试报告', '', '', '', '银河投标', '', '该项目采用政府借款', '', '付款条件：10%预付在签署合同后45天内付款，80%在收到要求的发货单据后信用证支付，10%尾款在签收后45天内支付；\r\r\r\r\r\r\r\r\r\r\r', '', '该项目为政府借款资金', '', '我司代理为个人佣金代理，与国电关系良好，能为我司获取到项目的预算，并影响评标决策。之前代理有大量参与国电项目招投标的经验，能获取到竞争对手的价格', '', '我司于9月份拜访EDCL采购总监，EUCL配电总监，与国电中高层关系已经初步建立', '', 'Hexing/Huawei', '', '-该项目付款方式安全，回款有保障\r\r\n-该项目为通过表计供应实现DA方案在国电内的推广，战略意义巨大\r\r\n-项目有代理运作，能影响到评审与决策', '', '-项目为简单的BS单相预付费表供应，不需要服务，价格上需要与Hexing竞争，需要公司在价格上给与一定得优惠力度\r\n同时前方会向公司反馈项目预算以及竞争对手的情况供公司决策', '卢旺达目前全国通电仅30%，而国电的计划是在2024年实现100%通电，其对电表，以及由电表逐步推广DA方案的需求属于不断递增的状态，我司之前给国电有过供货，口碑良好，现在需要借助机会尽快找准市场突破口，寻求双管齐下的机会', '莫林睿2018-09-25 14:16:43', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('158', '{BFDB2094-5172-4C2E-808E-0A5ED5E32B2C}', '61', 'INHE-0776', '2018-09-25 13:44:12', '0000-00-00 00:00:00', '2018-09-29 10:18:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092504/PAL', '急需技术支持', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '李玟2018-09-25 14:49:09', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('159', '{E5CCE472-4B21-4B34-BA1D-2AB8AB0A5C4C}', '60', 'INHE-0549', '2018-09-25 17:22:29', '0000-00-00 00:00:00', '2018-09-29 10:16:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092506/EPA', '', '05/SNEL/CEP/BOALI-1/TRV/2018', '2018-10-10', '采购（1）松戈和里本格的新柴油发电厂，电网（中压线路和中低压变电站）和低压电网设备#FE54`（2）两个中心的公共照明网络，（3）用来取代现有的发电机，柴油储罐和机电辅助设备#FE54`（4）电力公司商业办事处（每个中心一个办事处）        Acquisition de (1) nouvelles centrales thermiques diesel à Zongo et à Libenge, réseaux électriques (lignes MT et postes MT/BT) et réseaux électriques BT#FE54` (2) réseaux d’éclairage public dans les deux centres#FE54`(3) groupes électrogènes, cuves de stockage de gasoil et auxiliaires mécaniques et électriques, en remplacement de l’existant, et #FE54` (4) bureaux commerciau', '我们给客户提供FOB价格。客户付款方式为100%不可撤销的即期信用证						', '', '不接受技术不符点', '', '几个Lot是不可分割的', '', '不需要', '', '产品测试报告', '', '技术解析和断路器和表箱的测试报告', '', '代理商投标', '无', '标准国际招投标，政府/政策没有影响', '', '100%不可撤销的即期信用证						', '', '改项目是非洲开发银行融资的项目，客户资金调动能力强。			', '', '福雷斯特集团在刚果金做了很多年的项目了，对该国国情与内部人员应该比较熟悉。						\r\n', '', '能源分支的CEO与我司在16年有过合作，现在也保持联系。						\r\n', '', '他们希望我们给出FOB价格，没有提供竞争对手名单也没有提供参考和目标价格			', '', '由于之前有过合作，最近又经常交流，对方目前回应很积极，如果价格合适的话，相信我司可以拿下该项目，并打开刚果金和比利时的通道。						\r\r\r\n', '', '关键在于价格，需要客服协助技术解析								\r\n', '该项目是非洲开发银行融资的国际招投标项目，产品应该和EPS项目一样。我司仅需提供厂家授权、报价、技术应答表和产品测试报告。如果最后中标，我司将和比利时的福雷斯特集团签署合同并由其付款。参与该项目投标有利于我司巩固和加强和福雷斯特集团的合作，对于打开刚果金市场也有重要意义。', '王秀明2018-09-25 17:55:01', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('160', '{25ED5ECD-35F5-4C28-8C6D-885079133048}', '61', 'INHE-0440', '2018-09-25 16:57:22', '0000-00-00 00:00:00', '2018-09-29 10:16:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092507/TTW', '', 'PA/001/2018-19/WZN/G/30', '2018-10-04', 'SUPPLY OF METERS FOR WEST ZONE REGIONS 供应电表给西部各个地区', 'TANESCO付坦先令。国内付款条件为： (1)无预付款和发货款。（3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                        质保期限：接受货物起12个月，发货后18个月。交期：一年内交完各分订单/LPO的货。违约：百分之0.2/天，未发货产品，最多10%。\r', '', '框架合同国内限制性招标，目前由ITL和EDMI两家厂商参与。先评估技术，然后评估商务，实际上一审是商务和技术一起评估。电力公司希望授标的价格为单相DDP 55美元左右，三相直通160美元左右，ITL和EDMI需参考授标价格报价。', '', '只允许本地厂商投标，目前符合资格要求的有ITL和EDMI,每个厂家最多分2个LOTS，根据每个LOT价格来授标。\r\r', '', 'ITL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '过去三年（2015-2017）的财务报告，供应/生产类似规模产品的经验,人员资质，设备和生产能力等。', '', '图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，有自己的银行，每季度3.5百万美金的款项可以支付出来。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等。EDMI主要支持者是TB主席，电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Enginee等。威胜主要支持者退休的配电副总，用服总监，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理等，TTN项目单相表FOB 41美元。威胜TTN项目FOB 36美元。科陆农电项目BS单相分体加表箱TTN项目FOB 32.5美元。目前市场上主要的本地厂家为ITL和EDMI，国内限制招标方面可以一起合作应对以后海兴，威胜，思达和科陆等计划建厂。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签了批量SKD合同和安排付款，满足供货要求。标书的技术规格为一体式单相和三相直通表，和TTN，以及TTA项目的要求不同。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以在未来2-3年获得稳定的订单来源。', '', '产品规格和报价符合市场形势和提交样机。公司内部技术人员支持到位，必要的客户关系建设等。\r\r\r\r\n', '建议立项，支持ITL投标和争取订单。', '汤伟2018-09-25 18:05:12', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('161', '{75C92620-9A60-44EB-BFAC-E18BE1059CF6}', '60', 'INHE-0760', '2018-09-26 15:27:39', '0000-00-00 00:00:00', '2018-09-29 10:33:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092602/KLD', '', 'TD-M-SIPE-46770-KZ', '2018-11-01', '变电站现代化计量表计和AMI系统供货和安装项目                                                                  Поставка и установка современных приборов учета электроэнергии на подстанциях и подключение к АСКУЭ', '付款条件：预付20%DDP，货到付款60%DDP，项目完工付款10%DDP,移交投运付款10%DDP。\r\n交期：40周。', '{75C926209A6044EBBFACE18BE1059CF68442F4C2B3234363A3D51C033076BD50}_TD SI Meters FINAL - ENG 12092018.docx', '初审（主要审查标书内容是否有错误等）； 技术评审；商务价格评审。技术评审入围后，价格最优者中标。', '', '一家中标', '', '投标保函12 500 000哈萨克斯坦坚戈；    履约保函：合同总价的10%，       质保保函：合同总价的2%；   【保函对于币种、开立行无要求】', '', '财务数据：近三年每年的年收入不少于450万美元。公司五年年限；ISO9001资质', '', '投标保函、价格表、委托函、投标人资质、投标人项目业绩、设备性能表、', '', '银河投标', '', '政府关系有很大影响', '', '业主签署完工单和发票，银行汇款完成付款。', '', '项目资金由欧洲复兴开发银行提供贷款，客户有支付能力', '', '无', '', '', '', '竞争对手：当地最大的私有表厂Saiman有本地优势，该厂聘用的管理层有政府背景。', '', '竞争劣势：代理认为数量小，对EPC项目不感兴趣；银河尚未与该电力公司关键人物建立联系。', '', '需要强大的商务公关！', '', '郝健颖2018-09-28 13:36:16', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('162', '{89AB3596-18F3-448E-8D51-AD98DF9A77E1}', '60', 'INHE-0601', '2018-09-26 18:24:46', '0000-00-00 00:00:00', '2018-10-29 18:17:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092603/PTQ', '', '暂无', null, '泰国PEA Saiburi单相表项目', '目前项目正在发标前运作期，暂无得到商务条款', '', '综合投标方的价格和产品两方面打分，价格占40%权重，产品占60%权重。\r\n目前尚不满足的是TISI认证，这个代理正在申请进程中。\r\n', '', '最终一家供应商中标\r\n', '', '目前项目正在处于标前运作阶段，尚未能获得保函需求信息。\r\n根据上一次Pattaya项目的经验，不需要我司开具投标保函。\r\n', '', '关于投标资质相关要求有：当地TISI认证，ISO14001，ISO/IEC 17025 certificate，以及需要在PEA进行供应\r\r\n商登记注册\r\n', '', '2台样机需要在11月初之前准备好\r\n', '', '代理商投标\r\n', '', '从PEA之前的项目采购历史来看，采购决策过程较为独立，受政治影响小\r\n', '', 'T/T 预付款+发货前尾款方式\r\r\n', '', '从PEA之前的项目采购历史来看，支付能力足够覆盖给供应商的货款\r\n', '', '代理在当地电信运营商和电力公司客户关系强大，是PEA长期的电信产品供应商，代理为当地上市公司，管\r\r\n理规范，市场能力和项目执行能力都属于当地市场的第一梯队。\r\n', '', '和电力公司表计部门负责人能保持良好的沟通\r\n', '', '当时主要竞争对手为华立和长城开发，其中华立在当地市场运作历史长，长城开发也有成功的供货项目记录\r\n', '', '当时主要竞争对手为华立和长城开发，其中华立在当地市场运作历史长，长城开发也有成功的供货项目记录\r\n', '', '当时主要竞争对手为华立和长城开发，其中华立在当地市场运作历史长，长城开发也有成功的供货项目记录\r\n', '在该项目上，我司有很大机会。目前来看项目有两个关键点，一个是样机需要提前做好，另外是报价需要有竞争力。只有满足了这两点，就很有希望中标。', '常一琳2018-10-24 11:10:53', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('163', '{B31EC014-BE6B-454F-99FA-A84785806A9F}', '61', 'INHE-0578', '2018-09-27 02:54:43', '0000-00-00 00:00:00', '2018-09-29 10:09:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092701/KWM', '', 'MN44/2018', '2018-10-17', 'Supply and Delivery of Single and Three Phase Prepayment Meters for Three Years供应及运输单、三相预付费电表，三年期', '价格条款：DDP。银河与NYC之间FOB或CIF成交；\r\r\n\r\r\n\r\r\n付款主体：Kwadukuza Municipality#FE54`\r\r\n\r\r\n\r\r\n付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，市政在收到付款证明后30天内支付。银河与NYC直接预计采用ESA项目方式结算。\r\n\r\n\r\n交期、质保：未明确要求。', '', '商务文件评估 -- 性能评估 -- 价格评估 -- 资质评估。其中价格和资质占打分比重最多。', '', '1家中标。', '', '需开立保函，NYC开立。', '', '对公司经营范围，资质，财报有要求（NYC提供资料），银河仅负责技术部分，授权NYC投标。', '', '电表表型确认后相关图纸等或许技术部门提供；\r\n\r\n\r\nAMI系统或许提供一份方案。', '', '银河授权NYC投标。', '', '市政内部决策。', '', '银河与NYC直接交易，条款参考ESA项目。', '', '较好。', '', '1. 在跨祖鲁省通过ESA项目供应了不少DIN产品，有一定的口碑；\r\n\r\n\r\n2. NYC公司资质较优，具有一定竞争力。\r\n', '', '暂无。', '', '主要竞争对手为兰吉尔，CONLOG，都有电力公司有一定的客户关系。', '', '投标文件中需强调技术服务等，另外方案要精致。\r\r\n\r\r\n\r\r\n另外价格需要有竞争力，现在从某些项目来看，兰吉尔也在利用降价争取项目。', '', '1. 投标工作支持；\r\n\r\n\r\n2. 价格须有竞争力（尽量收集市场价格，让NYC确认目标价格）。', '1. 此项目为AMI系统和电表的综合项目，在德班省，市政条件不错，建议立项投标；\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n2. 该项目部分通信、尺寸等技术规格存在疑问，将在本周五参加标前会议后尽快反馈回公司。\r\r\r\n\r\r\r\n\r\r\r\n3. 建议李忠鹏主要负责该项目投标工作，覃湘君可在国庆后加入。\r\r\n\r\r\n', '覃湘君2018-09-27 03:23:47', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('164', '{4BC52D08-9919-4F7E-BF38-513C5E01DD50}', '61', 'INHE-0770', '2018-09-27 11:45:03', '0000-00-00 00:00:00', '2018-09-28 09:07:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092703/ONL', '', 'KE/SCM/2018/3', '2018-10-31', 'PROCUREMENT OF METER ASSET PROVIDER (MAP) TO PROVIDE METERING SERVICES TO THE KADUNA DISTRIBUTION COMPANY PLCKaduna电力公司基于电表供应商的招标采购项目', '付款条件：该项目为融资项目，招标方付款方式为无预付款，完成电表安装后用户上缴电费而后按月支付，代理想办法融资，我方作为供应商为其提供电表并与供应商签订合同，合同具体条款正在商讨中\r\n', '', '先资格审查（包括保函），再技术评审，最后商务评审。具体时间暂无。\r\n1. 电表技术规格符合、并符合最低30%的本地采购标准； 通过之后才可进入评分下面。\r\n2.投标人的信誉与经验（从投标的经验，资金实力和融资方案、主要人员资格和能力三个方面打分，每项20分，共分60分）\r\n3.交货及安装能力（从采购和供应能力、电表安装能力、技术工作计划、本地已有基础设施四个方面，共40分）\r\n', '', '共1个LOT，2-3家中标', '', '无，我司作为供应商，代理负责保函开立', '', '投标方需具备NG市场NERC(尼日利亚电力管理委员会）颁发的“No Objection”证书以证明他们符合今年四月份尼日利亚政府颁布的“MAP Regulation”的相关要求，目前尼日利亚已有65家公司已获得“No Objection”证书，具备该资质。但其他公司可以通过联合投标或是成为供应商的形式参与进来。\r\n', '', '需要客服部协助评估技术要求，此外需要商务部门协助整理审核我方提供的资料\r\n', '', '代理商投标\r\n', '无，我司作为供应商\r\n', '电力公司内部评标。', '', '该项目为融资项目，招标方付款方式为无预付款，完成电表安装后用户上缴电费而后按月支付，代理想办法融资，我方作为供应商为其提供电表并与供应商签订合同，合同具体条款正在商讨中\r\n', '', '电力公司要求投标公司提供长期融资计划，电表安装之后，按每月从用户收回的电费里面支付电表费用。目前客户正在寻找融资方案，暂未告知详细融资计划。\r\r\r\n', '', 'ONL客户与我司为初次合作，此前并未有过合作经历；客户与招标方KNEDC在2016年有合作经验。\r\r\n', '', '代理此前与KNEDC有合作，具备一定人际关系基础，可提前获取招标方信息便于我司准备。\r\n', '', '目前尼日利亚电力管理委员会NERC在今年给当地的65家电表供应商颁发了电表供“No Objection”证书，且投标项目只针对这65家公司开放，其他公司可以通过联合投标或者以供应商的形式参与进来；代理已告知总共15家MAP递交了意向书，但暂不知道具体竞争对手公司名称。\r\n', '', '代理与KNEDC此前有过合作，比较熟悉电力公司内部人际关系，有利于代理中与我司签单；代理自行承担投标保函开立，寻找融资方案和进行本地认证，减轻我司的商业风险和成本。\r\n但此次投标需要提供样机和本地认证，虽代理已经表示承担，但时间较为紧张。', '', '尽早提供样机给代理做测试和本地认证。\r\n', '1.代理此前与招标方有过合作，熟悉招标电力公司；\r\n2.代理自行承担保函开立，本地认证，对此项目积极程度较高，且在交流过程中配合度较高，回复及时；\r\n3.根据尼日利亚电力监管委员的2018年新规，该国电力公司电表采购只针对已授权的65家MAP公司。新规之后，目前除IRL项目外我司并未有参加其他招标项目，此次招标有利于在新规下打开尼日利亚市场，扩大与MAP公司的合作和了解，积累更多MAP项目投标经验。\r\n', '刘博2018-09-27 13:36:22', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('165', '{93129B1C-A948-4D6D-822C-7968AEAB9520}', '61', 'INHE-0578', '2018-09-27 14:22:40', '0000-00-00 00:00:00', '2018-09-29 10:34:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092706/ELM', '', 'EMLM 06/2019', '2018-10-24', 'Installation and Operation of Prepaid Meters, Bulk Meters and Vending System within Elias Motsoaledi Local Municipality for Period of Three Years在Elias Motsoaledi市政范围内安装、操作预付费电表，关口表及售电系统，为期3年', '价格条款：DDP\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n付款主体：Elias Motsoaledi市政\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n付款条件：市政倾向于投标者提供全套融资；但进入短名单可具体再协商付款条件，根据评分标准（80/20）来看，市政预算约为300万美元左右（实际可支付能力小于该预算）。', '', '分为3个阶段评估：商务评估及功能评估（需≥80%才能进入第二阶段评估），80/20评估（即价格+资质评分评估），供货现场参观、考察。', '', '1家中标（但会挑选约3家进入短名单协商）。', '', '无需开立。', '', '必须在南非本地注册CSD企业才可投标，对于本地化生产比例无明确要求，但比例越高倾向性越大（NYC满足所有投标资质要求）。', '', '1.需要一个完善的技术方案，包含售电系统加电表（该市政电力状况较好，布线规范，窃电担忧较少；在产品推荐上除了性能，成本控制也十分重要）。\r\r\r\n\r\r\r\n\r\r\r\n2. 对于项目团队资质有一定要求（CV方面和技术支持方面需要尤其注意）；\r\r\r\n\r\r\r\n\r\r\r\n3. 供货记录和用户证明尽量多提供（超过6个）；\r\r\r\n\r\r\r\n\r\r\r\n4. 培训计划和技术支持文件需尽量详细（需包含本地服务支持和技术转移计划）。\r\r\r\n\r\r\r\n\r\r\r\n文件最晚在10月17日完成。', '', 'NYC投标，银河支持。', '', '市政内部决策。', '', '预计会采用预付款+融资形式。\r\n\r\n\r\n银河与NYC之间进行结算；进入短名单后可具体协商。', '', '有一定的财务支付能力，但倾向于投标者提供融资，可利用手电系统收益分成回收货款。', '', 'NYC满足所有投标资质，在Limpopo省也有较多ESA项目产品供货，另外本地生产是一个较大优势。但在市政目前暂无售电系统供货，处于劣势。', '', '暂无。', '', '预计当前市政使用的后付费电表为兰吉尔和CONLOG的产品，这两家也将参与此市政投标，且在本地市政供货记录上存在较大优势。另外，兰吉尔现在为争取项目，价格较之前下调幅度较大。', '', '在该省有ESA项目供货；\r\n\r\n\r\n本地资质具有一定优势；价格 + 方案方面需提供较好融资。', '', '需收集更多该市政的信息（目前产品，主要问题，预期数量等）；投标方案需尽量完备。', '建议立项。目前由李忠鹏组织前期准备工作（商务、技术支持，需澄清问题，投标工作分配等），覃湘君在国庆后加入投标工作。', '覃湘君2018-09-27 15:01:48', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('166', '{FCB22F30-9601-44A9-BADD-F6D64CEB3725}', '61', 'INHE-0744', '2018-09-27 15:05:09', '0000-00-00 00:00:00', '2018-09-29 10:31:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092802/CNU', '请附上标书', '05/SNEL/CEPBOALI-1/TRV/2018', '2018-10-10', 'acquisition d equipements marches de conception fourniture montage d installation de un nouvelles centrales termiques diesel  热电站及其输配电网络的设计、设备供应及安装', '', '{FCB22F30960144A9BADDF6D64CEB37258442F4C2B3234363A3D51C033076BD50}_表1：CNU投标项目信息归纳表.doc', '', '{FCB22F30960144A9BADDF6D64CEB3725074E749A304748709C51373D9D483750}_2018刚果金标书.docx', '独家中标整个项目，一家制造商可授权多个投标人', '', '由代理商开具', '', '对设备部分，只提到需要提供设备的供货记录、资质证书、测试报告及用户证明', '', '', '', '代理商投标，代理直采', '', '政府贷款项目，主要由电力公司自主进行决策', '', '设备部分：\r\n30%预付款；\r\n60%在货物发出并给业主提供资料后45天支付；\r\n5%提供完工证明后45天支付；\r\n5%提供验收证明后45天支付；\r\n', '', '该项目由非洲开发银行贷款资金进行支付', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。中水一局在刚果金与能源部及电力公司有非常好的关系，多次中标亿美金级别的水电站建设及输变电线路							\r\r\n', '', '银河曾经给SNEL供过货，在SNEL有一定的供货记录。目前与业主无直接联系', '', '', '', '', '', '', '该项目采购数量虽然少，但是对我司来说风险低，由代理商直接国内进行采购；同时给予我司进入该市场的机会，对后续该市场的开发有非常积极的作用', '郑超波2018-09-28 15:23:08', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('167', '{62572EDD-223F-46AD-B06F-09D423C0D6AB}', '60', 'INHE-0769', '2018-09-28 16:21:26', '0000-00-00 00:00:00', '2018-09-30 18:59:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092803/JJP', '', 'JEP 6/2018    JEP 80/2018', '2018-10-08', 'Electronic Single Phase L.V. Meters 电子单相表                                                             Electronic Three Phase L.V. Meters 电子三相表', 'CFR到约旦亚卡巴港口，付款主体是JEPCO电力公司。付款方式是见单（运单，发票，由工程师签发和认证的原始付款证书）后支付合同总价值的80%，当货物到达JEPCO仓库或验收地点后，见发票副本和由工程师签发和认证的原始付款证书付余下的20%，时间不超过进港口60天内。交期要求是120天。质保期：货物到达目的地后20个月内或是自货物到达装货港口24个月内（以较早者为准）。如果出现延期，每周扣除延迟部分合同金额的0.5%，延期超过15周视为不回应。允许电力公司在中标时增加或减少25%的货物数量且保持单价不变', '', '', '', '允许多家中标，多家试点', '', '投标保函为合同金额的2%；中标后30天之内开出履约保函，金额与合同要求一致。（代理开投标保函，我们开履约保函）', '', '营业执照、过去五年的资产证明（包括利润和亏损表、资产负债表和审计师报告）、过去七年的类似产品的供货记录（工厂的实力和高效性比较重要）', '', '投标资料目前正在准备，最迟10.8号下午5点之前提交。', '', '银河投标', '', '主要在于电力公司自身的决策', '', '见单（运单，发票，由工程师签发和认证的原始付款证书）后支付合同总价值的80%，当货物到达JEPCO仓库或验收地点后，见发票副本和由工程师签发和认证的原始付款证书付余下的20%\r\n', '', '无具体信息', '', '合作伙伴之前是海兴的代理，为海兴拿过标，在各电力公司都有一定的关系和资源', '', '', '', '主要竞争对手是海兴和华立，都已完成试点，海兴采用的G3-PLC方案，提供HES+DCU+表计，华立采用华为的高速PLC方案，提供HES+DCU+表计，华为提供通信模块', '', '根据技术规范，产品以及技术要求差异的地方我们可以开发，从商务方面，我们目前的代理做过竞争对手海兴的合作伙伴，对海兴相对了解，海兴的试点情况是G3-PLC方案问题很严重，主要是DCU受变压器（馈线）影响导致无法与表计通信（将DCU安装在Substation下面，表计与DCU无法通信，但是将表计安装在substation之外的地方，通信没问题）；业务出差拜访了JEPCO，JEPCO对我们的预付费和防窃电功能都比较感兴趣，对我们现场演示的AMI集抄也比较满意。综合以上，该醒目银河值得参与。', '', '合作伙伴的运作，与合作伙伴以及客户共赢，客户满意的产品方案', '', '吴琼2018-09-29 15:26:38', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('168', '{29F8C406-B152-4BD6-B8DD-8C5A34095C6C}', '61', 'INHE-0642', '2018-10-06 05:04:14', '0000-00-00 00:00:00', '2018-10-08 11:13:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100601/M12-F1', '', 'ESC469/ICB/RT/G/FY2016-17', null, '', '待商议', '', 'N/A', '', 'N/A', '', 'N/A', '', 'N/A', '', 'N/A', '', 'N/A', 'N/A', 'ESCOM为国有企业，政府直接控制ESCOM走向						\r\n', '', '待沟通						\r\n', '', '银河与ESCOM执行过多个项目,ESCOM资信良好,但效率低下						\r\n', '', 'N/A', '', 'N/A', '', 'N/A', '', 'N/A', '', 'ESCOM库存电表空缺，急需直采来填充库存，因M12已经有供货项目，且电表口碑非常好，所以电力公司希望按M12项目的技术规格以及价格直采一万台电表以及表箱（数量待定）。由于电力公司对电表交期十分重视，希望公司在此项上提供支持，协调最快的交期，业务后续好反馈给电力公司，从而尽快促成该项目。								\r\n', 'ESCOM采购总监已经发邮件要求我司直采供货1000台电表以及等数量的表箱，目前已经和此人商讨了电表价格和技术规格（按M12项目执行），但具体的付款方式，运输方式，交期以及表箱数量还在协商当中。电力公司对交期十分看重，所以当务之急是给予电力公司一个满意的答复，后续再来完善相关事项。								\r\n', '潘正豪2018-10-06 17:04:54', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('169', '{C347CEC3-E513-4D36-855A-DE740C27E2CD}', '61', 'INHE-0432', '2018-10-07 16:39:11', '0000-00-00 00:00:00', '2018-10-10 10:49:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100701/EIA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '目前需要公司的支持是：提供银河【三表合一】方案。交付时间：10月10号前。对方收到后会交业主审核，若通过，将尽快安排厂商前往与中资企业、业主见面。                                                                              ', '谭东羊2018-10-07 17:27:25', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('170', '{3A6D43A2-40BD-426B-A8B0-2890F59EBF8D}', '61', 'INHE-0593', '2018-10-07 22:34:22', '0000-00-00 00:00:00', '2018-10-10 11:35:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100702/DEN', '', '/', null, '/', '讨论中。预计为多哥电力公司承担50台电表费用，我司提供路灯系统作为试点。试点成功后，有2000台三相GPRS电表/路灯系统安装及维护采购需求。建议电表付款方式为50%生产前TT预付+50%发货前TT付款。', '', '/', '', '/', '', '/', '', '/', '', '/', '', '银河直供', '/', '多哥国家电力公司为国有企业，政府影响力大。', '', '/', '', '/', '', '代理azon总部为多哥洛美，在当地有一定的实力及影响力。', '', '初次接触，客户关系一般，基本为无。', '', '主要为海兴，connect afrique，hexcell', '', '多哥电力公司主动邀约进行试点，对我司而言是个接近多哥电力公司，未来运作项目的机会。\r\r\r\n\r\r\r\n\r\r\r\n同时路灯系统在CDN有着成功的实施经验，有信心能在TN成功推广。', '', '1.试点前对各方的约束（电力公司，代理，银河），签订相应的试点协议，如电力公司承诺试点成功验收后多少台的采购量？系统采购等；\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n2.试点项目有效顺利执行；\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n3.代理对试点项目付出也很重要。', '支持立项。', '胡蝶2018-10-07 23:03:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('171', '{9D5E5FE8-AD17-4BFE-81F4-AA8787155B16}', '61', 'INHE-0642', '2018-10-07 23:39:42', '0000-00-00 00:00:00', '2018-10-10 10:49:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100704/M16(旧)', '', 'ESC0065/ICB/RT/G/FY2018-19', '2018-11-16', '为大型电力用户(最大需量客户)设计、制造、交付、安装和调试预付费电表项目[Designing, Manufacture, Delivery, Installation and Commission Prepaid Meters for Large Power Users(Maximum Demand Customers)]', 'N/A', '{9D5E5FE8AD174BFE81F4AA8787155B168442F4C2B3234363A3D51C033076BD50}_表1：M16投标项目信息归纳表.doc', '1.两阶段竞标，满足最低技术要求的厂家才能进入下一阶段的竞标。\r\n2.技术符合的情况下，报价最低取胜', '', '一家中标', '', 'N/A', '', '在某一国家执行类似项目的经验证明						\r\r\n', '', '1. 公司登记执照\r\n2. 设备说明书和详细规格\r\n3. 厂家授权\r\n4. 技术方案设计（需要考察马拉维市场的应用环境）				\r\r\n', '', '银河投标', 'N/A', 'ESCOM为国有企业，政府直接控制ESCOM走向', '', '待定', '', '银河与ESCOM执行过多个项目,ESCOM资信良好,但效率低下', '', 'N/A', '', '客户关系良好', '', '对手为海兴和科陆。海兴有当地代理在M国市场，但据说和电力公司的决策人员有小摩擦。科陆已经派了三个人来M国市场来支持M16项目（一个业务，一个产品经理，一个技术支持），但科陆在M国市场的质量口碑较差。', '', '银河在M国市场经营多时，有较好的客户关系和产品质量口碑，同时对M国市场现场应用环境以及客户痛点难点有长足的经验累积。具备以上各点优势的同时，银河需要结合自身的优势以及现场的环境，给出一份完善的技术解决方案。', '', '该项目为EPC项目，虽然银河在M国市场耕耘多时，但是建议公司派技术支持前往M国市场实地考察，结合过往经验，现场应用环境以及电力公司的需求做出完善的解决方案。', '建议公司立即派技术支持亦或是研发前往M国市场配合业务运作项目。', '潘正豪2018-10-07 23:55:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('172', '{2BF82DFC-F639-4F77-9A37-FCE4FDC4FF3D}', '93', 'INHE-0091', '2018-10-08 10:50:38', '0000-00-00 00:00:00', '2018-10-10 10:49:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100801/DAM', '', '69/2018', '2018-10-17', 'Supply of:? Medium voltage metering units? Low voltage metering units供应中压组合互感器及低压计量箱', '1）价格条款：CFR Aqaba Port,或者CPT-Amman Customs,或者CPT-IDECO Stores\r\r\r\r\n2) 付款主体： IDECO\r\r\r\r\n3）付款条件：\r\r\r\r\n   a. IDECO倾向于赊销，在IDECO收到货物并在IDECO仓库验收后一个月内支付；款项将在每个月的第一周支付\r\r\r\r\n   b. 如供应商坚持信用证付款，则信用证所有的费用由供应商承担，且信用证应是IDECO可接受的，货物抵达IDECO仓库并向银行提交IDECO的验收证明后1个月内支付款项\r\r\r\r\n4) 交期：要求2019年1月交付货物，交期从收到PO之日起按周表示\r\r\r\n5）质保：工厂发货日起15个月或产品应用在现场之日起12个月,哪个晚发生就以哪个为准\r\r\r\r\n6）延期交付罚款：标书中未具体规定\r\r\n', '{2BF82DFCF6394F779A37FCE4FDC4FF3D8442F4C2B3234363A3D51C033076BD50}_69 2018 Mutring Unit  f.pdf', '技术评标再商务评标', '', '					\r标书无披露						\r\r\r\n', '', '1.投标保函金额不少于投标报价的5%，有效期为截标日起至少120天\r\r\r\n2.履约保函金额为合同金额的10%，收到PO之日起30天内开立，有效期至买方收到最后一批货物之日起至少1年', '', '', '', '', '', '银河投标，代理拿佣金，代理开具投标保函', '', '', '', '', '', '良好。', '', '', '', '已离职的李成兵2018年9月曾拜访过IDECO，银河暂未建立客户关系。', '', '已要求代理提供相关市场信息，待代理反馈。\r', '', '', '', '1.该市场电力公司用的都是欧美厂家产品，根据今年以来的项目经验，银河在配电产品的报价偏高（高于欧美厂家）。希望此次报价能有竞争力。\r\r\n2.低压计量箱的投标资料需要研发/客服有力支持。', '属计量产品项目，银河强项，建议投标。', '林丽璇2018-10-08 11:12:02', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('173', '{76394A47-B591-43BC-B134-4E5CE79DBCE4}', '60', 'INHE-0769', '2018-10-08 16:32:26', '0000-00-00 00:00:00', '2018-10-09 16:43:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100806/PED', '', '', '2018-10-14', 'Single Phase Active Energy Static Meter Low Voltage(220V), 5/40Amp 2018 低压单相有功电能表', 'CIF(Lattakia port – Syria )和FOB（China Port）.付款主体：NEW MACHINARY. 付款方式（可选）：1.30%预付款+70%不可撤销保兑即期LC；2. 100%不可撤销保兑即期LC', '', '', '', '', '', '投标保函和履约保函均由代理开立', '', '要求有类似项目经验', '', '无', '', '代理商投标', '', '', '', '根据前面付款条件最终确认方式而定', '', '良好', '', '合作伙伴为目的国项目服务提供商，与电力公司关系良好，有一定的项目经验，为当地公司，对市场比较了解', '', '', '', '市场主要竞争对手是海兴，科陆，林洋，据另一代理的消息，之前的项目主要中标方式海兴和林洋，产品包括多功能表和单三相智能表', '', '', '', '价格和客户关系运作', '', '吴琼2018-10-09 09:49:32', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('174', '{3490C880-C2DE-4E4B-8347-7098C2355A21}', '61', 'INHE-0772', '2018-10-08 16:50:58', '0000-00-00 00:00:00', '2018-10-10 11:34:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100807/GBA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '优先正与代理运作直采，计划本月22带样机前往电力公司展示。后备计划：投标，希望加入公司产品的特殊参数，增加中标率。需公司支持技术解析，加快样机制作。', '张子琦2018-10-08 18:09:03', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('175', '{53DB1A4F-31A7-4F0C-B6F4-855530090207}', '61', 'INHE-0719', '2018-10-09 09:56:51', '0000-00-00 00:00:00', '2018-10-12 14:52:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100905/PLA', '', '013-2018-EO-L', '2018-10-20', 'Totalizadores Electrónicos Trifásicos Multifunción de clase 0.2s,三相多功能0.2s电子表项目招标', '付款条件（电力公司与代理公司）：在电力公司发出验收合格文件后的15天内，一次性付款 。                                                       （代理公司与银河）：超过20万美金，使用不可撤销的LC 付款。              交期：签订合同后90天内                                               违约条款：超过交期的每一天都会产生罚款，最高可达总金额的10%', '', '1.价格最低，价格因素占90%，2.交期占10%，最好为1-45天，其次是46-89天\r\n', '', '总分100，根据上述评标规则，取总分最高者中标', '', '代理开保函', '', '按照电力公司模板提交近8年的供货经验', '', '无，技术应答与PLL项目一致，客服已完成应答', '', '银河授权，代理投标', '', '', '', '', '', '', '', '1.代理公司在2015年与该电力公司已经开始合作，供过货，在该公司具有一定的人脉基础                                                                  2.代理公司大部分员工为工程师，技术力量较强。与欧洲三大通讯运营商之一的TELEFONICA公司是合作伙伴。据李明在一线出差反馈，代理公司的2017营业额达到了100万美元。', '', '暂无业务人员长期在一线，近期与代理公司一起参秘鲁展，完成PLL的样机。', '', '主要竞争对手为ELSTER,三相产品为A1800，\r\r\r\nHEXING,在利马当地有办事处，此前供货简单表，不带通讯功能，并参与当地配电项目，                                                              乾程，在当地也有办事处，华立，科陆等', '', '公司现有的三相四线CT接入式可更换通信模块多功能智能电表，0.2s与电力公司的标书要求有几处较大的技术不符点，此前的PLL样机提供了偏差样机，此次批量供货时建议尽量满足主要不符点。', '', '因此次投标价格占比较重，希望公司能给出较有竞争力的价格。', '据了解，CT表0.2s在该市场需求还是可以的，建议尽量满足技术要求，不仅是为了这个项目，也是为了之后能去做秘鲁的本地认证INACAL，希望公司各部门给予支持和合作，秘鲁市场的技术门槛较高，不同电力公司的要求也相应不一样，但市场潜力较大，这是一次较好的进入市场的机会。目前三相表认证只有ELSTER有，其他供应商都暂时没有，可以先参与投标，之后与代理一起做认证', '林丽君2018-10-10 09:45:39', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('176', '{D0E3ADD2-F2EB-4EC3-9DE8-CC05A697C927}', '61', 'INHE-0772', '2018-10-09 15:23:20', '0000-00-00 00:00:00', '2018-10-12 14:49:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100906/MLO', '', 'N18/135/ADN18/136/ADN18/137/AD', '2018-10-12', 'FOURNITURE DE COMPTEUR ELECTRONIQUE A PREPAIEMENT 预付费电表采购项目', '定向询价，代理报价，代理向银河直接采购。附件为原文件凭证', '{D0E3ADD2F2EB4EC39DE8CC05A697C9278442F4C2B3234363A3D51C033076BD50}_Demande de prix 2 000 compteurs.pdf', '价格最优', '{D0E3ADD2F2EB4EC39DE8CC05A697C927074E749A304748709C51373D9D483750}_Demande de prix 10 000 compteurs.pdf', '一家中标，授权一家', '{D0E3ADD2F2EB4EC39DE8CC05A697C9272B47EB25ABE84FF19C47768372BB342D}_demande de prix 13 000 compteurs.pdf', '无', '', '有中标记录。符合要求', '', '技术解析需技术部门提供\r\r\n', '', '电力公司定向询价，代理报价，代理向银河直接采购', 'NG', '定向询价，决定因素是价格\r\r\n', '', '100%TT发货前付清, 50%预付款，50%发货前付清\r\n', '', '客户付款情况良好', '', '代理今年中标1次，与电力公司关系好', '', '与代理合作多年', '', 'CONGLOG, HEXING, WASION,ULEE BY HOLLEY, ITRON, ZHONG CHENG, HEXCELL', '', '优：银河已有供货记录，代理实力强\r\r\n劣：同行竞争者多，价格战\r \n\r\n策略：经初步调研，比对旧市场调研记录，马里在战乱中逐渐恢复，市场潜力可期，当前代理的KOUMA家族在当地市场涉及多个产业，势力实力强大。自王子强离职后疏于现场维护，建议加强客户关系维护，预防代理反水。\r\n', '', '本次电力公司定向询价，预留时间非常紧，需内部有效率的配合。技术解析需技术部门提供', '电力公司在供应商库定向询价，代理直接报价，代理中标后再向银河直接采购，谨慎配合代理报价，保持与代理的良好合作。', '张子琦2018-10-09 20:20:55', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('177', '{AD149208-47A4-4E5E-8341-42F07C635142}', '60', 'INHE-0549', '2018-10-09 16:44:31', '0000-00-00 00:00:00', '2018-10-10 14:41:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100907/CAM', '', '18/135/AD；18/136/AD；18/137/AD', '2018-10-16', 'Acquisition de compteur à prépaiement', '该项目是2018年预算下的预付费电表采购项目，交期六十天', '', '如果我们的样机测试通过的话，我们会有更多的机会赢得该项目，因为他们与总经理关系融洽。当然价格要好点。', '', '一家制造商可以授权多个投标人', '', '无', '', '无', '', '厂家授权和原产地证明', '', '代理商投标', '无', '政府/政策对决策无影响，EDM是自主决策的', '', '30%TT预付款+出货前TT尾款', '', '该客户在广州有代理帮忙打钱，我们只需要做好货，他的代理会去工厂提货。', '', '该客户是前电力公司总经理的亲戚，今年也赢得了很多项目，本来这次不打算参与电表的投标，是电力公司的人让他参加的，与电力公司关系很好。', '', '该客户与断路器厂家有很多合作，对于我们的咨询也很耐心解答，希望与我们合作，并希望在下第一个单后来我司参观。', '', 'EDM一般都是给本地公司发询价函，并限制只用CONLOG, INEHMETER, WASION, HEXING, ULEE BY HOLLEY, ITRON, ZHONG CHENG和HEXCELL的电表。\r\r\n', '', '银河收到了该项目的几家询价，由于该公司最早提供相关信息和技术规范，且与中国的断路器厂家多有合作，在广州也有代理，直接付款提货，我们希望与其合作。虽然投标样机制作可能来不及，但是客户也说可以开标后再提供。', '', '希望公司给一个优惠的价格。', 'EDM用本年的预算给几家当地公司发了预付费电表的询价函，推荐询价的电表厂商有CONLOG, INEHMETER, WASION, HEXING, ULEE BY HOLLEY, ITRON, ZHONG CHENG和HEXCELL，价优者中标。该客户在中国广州有代理商且与电力公司总经理的关系很好，已经给中国的断路器厂家下了很多订单了，他希望我们给电表的出厂价，他的代理会付完尾款后去工厂提货。在下完第一个单后回来我司参观，以后还有很多合作机会。', '', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('178', '{08AE5EB2-70E1-4E1F-9AB7-12CB5396FAFC}', '61', 'INHE-0440', '2018-10-11 04:22:02', '0000-00-00 00:00:00', '2018-10-12 14:51:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101101/TTB', '', 'TENDER NO. PA/001/2018-19/LZN/G/28', '2018-10-18', 'SUPPLY OF METERS FOR LAKE ZONE REGIONS UNDER FRAMEWORK CONTRACT ARRANGEMENT 框架合同供应电表给湖区各地区', 'TANESCO付坦先令。国内付款条件为： (1)按分订单/LPO的合同金额，收货后在提交付款申请和电力公司各地区仓库的验收证明后30天内支付。                                                        质保期限：自各地区接受货物起12个月。交期：接到分订单/LPO后2周内交货。违约：百分之0.001/天，未发货产品，最多10%。', '{08AE5EB270E14E1F9AB712CB5396FAFC8442F4C2B3234363A3D51C033076BD50}_BIDDING DOCUMENT METERS G 28-2.pdf', '框架合同国内限制性招标，目前由ITL和EDMI两家厂商参与，有威胜和其他厂家搅局。先评估技术，然后评估商务，实际上一审是商务和技术一起评估。电力公司希望授标的价格为单相DDP 55美元左右，三相直通150美元左右，ITL和EDMI需参考授标价格报价。', '', '只允许本地厂商投标，目前符合资格要求的有ITL和EDMI,每个厂家最多分3个LOTS。\r\r\n', '', 'TL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，无质保保函，由ITL/Africarriers 负责所有的保函。', '', '过去三年（2015-2017）的财务报告，包含由总监签字的资产负债表和现金流声明,年平均营业额至少150，000，000先令。流动资产至少为投标价格的50%。至少1年供应/生产类似规模产品的经验。过去1年至少2个供应/生产类似规模产品的经验。', '', '=图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。具体参考评标流程。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： 100%的合同金额，收货后在提交付款申请和电力公司各地区仓库的验收证明后30天内支付。                                                 本地供应商的付款，在提交每个阶段的资料后，30天内TT支付。客户想要运作成为LC付款。\r\r\r\n', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，每季度3.5百万美金的款项可以支付出来。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。\r\n', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。\r\n', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是TB主席，电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者退休的配电副总，用服总监，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理等。目前市场上主要的本地厂家为ITL和EDMI。海兴，威胜和科陆计划建厂。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签了批量SKD合同和安排付款，满足供货要求。框架合同，标书的技术规格，单相和三相直通和TTA一致。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以获得稳定的订单来源。', '', '产品报价符合市场形势，给予客户技术和商务支持。技术支持人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '汤伟2018-10-11 05:17:34', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('179', '{A4138CDC-F6BF-479D-A769-4647F36A022E}', '61', 'INHE-0440', '2018-10-11 17:07:54', '0000-00-00 00:00:00', '2018-10-16 09:09:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101102/TTD', '', 'PA/001/2018-19/SZN/G/32', '2018-10-25', 'SUPPLY OF METERS FOR SOUTH ZONE REGIONS UNDER FRAMEWORK CONTRACT 框架合同供应电表给南部各地区', 'TANESCO付坦先令。国内付款条件为： (1)按分订单/LPO的合同金额，收货后在提交付款申请和电力公司各地区仓库的验收证明后30天内支付。                                                        质保期限：自各地区接受货物起12个月。交期：接到分订单/LPO后2周内交货。违约：百分之0.001/天，未发货产品，最多10%。', '', '框架合同国内限制性招标，目前由ITL和EDMI两家厂商参与，有威胜和其他厂家搅局。先评估技术，然后评估商务，实际上一审是商务和技术一起评估。电力公司希望授标的价格为单相DDP 55美元左右，三相直通150美元左右，ITL和EDMI需参考授标价格报价。', '', '只允许本地厂商投标，目前符合资格要求的有ITL和EDMI,一个厂家最多中2个LOTS。\r', '', 'TL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，无质保保函，由ITL/Africarriers 负责所有的保函。', '', '过去三年（2015-2017）的财务报告，包含由总监签字的资产负债表和现金流声明,年平均营业额至少300，000，000先令。流动资产至少为投标价格的50%。至少1年供应/生产类似规模产品的经验。过去1年至少2个供应/生产类似规模产品的经验。', '', '图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。具体参考评标流程。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： 100%的合同金额，收货后在提交付款申请和电力公司各地区仓库的验收证明后30天内支付。                                                 本地供应商的付款，在提交每个阶段的资料后，30天内TT支付。客户想要运作成为LC付款。\r', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，每季度3.5百万美金的款项可以支付出来。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。\r', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。\r', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是TB主席，电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者退休的配电副总，用服总监，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理等。目前市场上主要的本地厂家为ITL和EDMI。海兴，威胜和科陆计划建厂。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签了批量SKD合同和安排付款，满足供货要求。框架合同，标书的技术规格，单相和三相直通和TTA一致。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以获得稳定的订单来源。', '', '产品报价符合市场形势，给予客户技术和商务支持。技术支持人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '汤伟2018-10-11 21:06:30', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('181', '{C234E38B-8A22-4CCB-B15B-533D6C719B0E}', '61', 'INHE-0500', '2018-10-14 13:29:32', '0000-00-00 00:00:00', '2018-10-16 16:33:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101401/BVM', '', 'TENDER NO. BV730', '2018-10-26', 'SUPPLY, INSTALLATION AND MANAGEMENT OF A STS COMPLlANT PREPAYMENT ELECTRICALVENDING SYSTEM FOR A PERIOD ENDING 30 JUNE 2021   合同期三年，托管性质，供应、安装和管理全套STS标准的预付费售电系统。', '三年期框架供货协议；报价为DPP含VAT价格；付款主体：Breede Valley Municipality.；         交期：PO下达后8周内完成新售电系统的替换、数据迁移、第三方售电平台接入、培训、试运行和全运行；                        付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；               质保和违约：服务商和市政公司签订SLA服务协议，未能按照合同要求提供市政公司所需的服务要求，按照最高每月付款发票金额的5%进行罚款，市政公司保留暂停或者取消供应商合同资格的权利。\r\r\n', '', '第一阶段评审：售电系统功能性投标审核，需要100%满足标书所列的技术要求，直邮100%符合技术要求的供应商，才有资格进入到第二阶段的预合格评审，此项评审主要以商务条件、报价以及相关资质要求审核，总分要达到70%以上才能进入到第三阶段的现场实际操作演示；\r\r\n第三阶段：按照标书要求现场实操演示。', '', '一家服务商中标', '', '无需开立保函', '', '投标公司至少需要有3年以上的售电系统服务经验，10年以上公司资质评分10分；\r\r\r\r\n提供最近5年的审计财务报告；\r\r\r\r\n提供不少于3份相关售电系统用户供货记录；\r\r\r\r\n需要同时满足STS、IEC、NRS和市政 MSCOA标准要求，NRS和MSCOA标准需要澄清；\r\r\n需要NYC提供 南非NQF6和NQF7 施工人员资质证明文件。\r\r\n', '', '因为此系统招标项目是专业第三方咨询公司起草，技术要求非常细致，要求提供的技术文件资质非常高，请软件部负责指派一名软件工程师协助，谢谢！', '', '代理NYC直接投标，银河做厂商支持', 'N/A', '市政公司自行决定评标全流程，评标委员会由市政指定的技术代理+财务部成员+采购部成员+电力分支负责人组成，中标的最终价格需要参考财务部审批的年初预算\r\n', '', '付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；				\r\n', '', '由于时间关系，市政公司的财务能力待进一步调查和了解。但是项目中标后，需要服务商提供一份融资框架协议', '', 'NYC优势：BBBEE资质10分偏好优势；愿意在本地投入技术服务驻点（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案；ESA项目已在林波波省有大量供货，银河+NYC的知名度有一定提升。\r\r\r\r\r\nNYC劣势：第一次在次市政投标，暂无内部客户关系和支持，客户关系需要进一步的拓展。\r\r\r\r\n', '', '银河+NYC 第一次在次市政投标，暂无内部客户关系和支持，客户关系需要进一步的拓展。\r\r\r\n						\r\r\n', '', '主要竞争对手：                                                     1.过去三年合同期售电系统供应商为Ontec（实为Itron分离后的系统独家经销商），客户关系较好，电力公司熟悉其售电系统，本地有合作技术支持伙伴，并且市政公司90%的预付费电表为Itron所供；                                2.Conlog，此市政的电表供应商之一，本地有合作技术伙伴；                 3.海兴，之前投过此市政公司系统招标，对市政公司招标和价格方面有较深的经验，价格和系统功能扩展性有优势； 4.Syntell，南非本地较有实力的系统供应商，在南非有多个供货经验；\r\r\r\r\r\r\r\n4.其他本地系统公司，待进一步调查和了解。', '', '竞争优势：NYC优势：BBBEE资质10分偏好优势；愿意在本地投入技术驻点（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案。银河技术方案的符合，以及价格优势；\rESA项目已在此电力公司有供货，有一定知名度。\r\r\n竞争劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\r\n策略：供货记录的澄清，完成商务和技术的无偏差；和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好技术演示，一次性成功完成演示需求。						\r\r\r\n', '', '1.按照标书做对应的技术应答和完整投标资料；\r\n2.和NYC协商沟通报价，报价需要具有绝对的竞争力，并提供整套的融资方案；\r\n3.催促NYC尽早完成本地服务器的部署，和各方第三方售电平台做接口完成，以便到时需要提供现场实操演示。', '10月和11月市政投标非常密集，预计总共招标数量在30个左右，需要公司协助：\r\r                            1.东南非1组尽快招募一名业务协助李忠鹏和覃湘君跟进市政投标项目和中标项目的实施；\n\r\n2.需要软件部和客服部全力协助提供技术支持；\r\n3.BVM项目组成员：李忠鹏 覃湘君 刘博', '李忠鹏2018-10-14 15:03:34', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('182', '{4EC87D04-BA2F-4C7C-9D41-97EE5E7088D6}', '61', 'INHE-0500', '2018-10-15 03:28:40', '0000-00-00 00:00:00', '2018-10-16 16:33:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101501/CDE', '', 'CD 56/2018', '2018-11-07', 'SUPPLY AND DELIVERY OF SMART ENERGY METERS (TOU) AND SIM CHIP MODEMS供应多费率智能电表和配套的SIM卡模块', '价格条款：DDP。银河与NYC之间FOB或CIF成交；\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n付款主体：CENTLEC (SOC) Ltd；\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，市政在收到付款证明后30天内支付。银河与NYC直接预计采用ESA项目方式结算。\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n交期、质保：发货后12个月质保，正式PO下达后不晚于6周内交付。', '', '第一阶段：技术资料评审；\r\n第二阶段：商务资料评审；\r\n第三阶段：BEEEE资格和其他偏好资质评审；\r\n第四阶段：样机测试或者现场演示', '', '未限定中标公司数量', '', '无需开立保函', '', '1.提供最近3年审计财务报告；\r\n2.提供至少2个类似项目供货资质证明，3个及以上此项目评分满分；\r\n3.需要提供产品寿命测试报告、SABS证书和第三方形式测试报告', '', '1.需要客服部协助完成技术解析并推荐应标产品；\r\n2.需要实验室协助提供对应的样机。', '', '银河授权NYC投标。\r\n', 'N/A', '市政公司组织内部评标委员会（2个来自电力部门，1个来自采购，1个来自财务部门），评标委员会通过预中标名单，然后提交CFO做财务评审签字确认，最终由Municipality Manager签字通过。', '', '交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，市政在收到付款证明后30天内支付。银河与NYC直接预计采用ESA项目方式结算。\r\n', '', '良好，见附件2017年度市政报告', '', 'NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求。\r\r\r\nNYC劣势：第一次在次市政投标，无内部客户关系和支持。', '', '此市政对于银河也是新客户，第一次参与投标\r\n', '', '1.海兴：三年期供货智能电表和集抄系统，在市政公司内部关系牢靠；\r\r\n2.Itron：三年期供货智能电表和集抄系统，在市政公司内部关系牢靠；\r\n其他竞争对手信息如报价、产品质量问题待跟进和调查。\r\n', '', '竞争优势：NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求。\r\r\r\n竞争劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\r\r\n策略：样机技术问题的澄清；和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好样机，满足市政公司的技术要求\r\r\n', '', '1.和NYC一起拓展客户内部关系，CFO层面和电力部门技术层面；\r\n2.准备好样机，需要满足市政公司的要求。', '1.项目组成员：李忠鹏 覃湘君 张正', '李忠鹏2018-10-15 04:15:35', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('183', '{35AD9AE9-1868-4FA2-ADB3-625D97CA59BC}', '61', 'INHE-0744', '2018-10-15 09:44:01', '0000-00-00 00:00:00', '2018-10-16 16:33:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101502/CND', '', 'DAOR N°04/ SNEL/DG/DEQ/CDP/CPM/JMK/2018', '2018-12-14', '', 'La Rehabilitation et Modernisation de la centrale hydroelectrique de Zongo1, du poste elevateur 6,6/70 kV, du poste de dispersion HT et des installations de transport et reseaux de distribution associes. \r\r\r\nZongo1水电站、6.6/70 kV升压变电站、高压配电站、输电设施和配套的配电网络的修复与现代化改造\r\r', '{35AD9AE918684FA2ADB3625D97CA59BC8442F4C2B3234363A3D51C033076BD50}_DAO ZONGO 1招标文件-5个法中双语译文.zip', '见附件', '{35AD9AE918684FA2ADB3625D97CA59BC074E749A304748709C51373D9D483750}_CND投标项目信息归纳表.doc', '独家中标整个项目，一家制造商可授权多个投标人', '', '由代理商开具', '', '对设备部分，只提到需要提供设备的供货记录、资质证书、测试报告及用户证明', '', '厂家授权书', '', '代理投标，代理直采', '', '融资类项目，主要看承包商的实施能力及融资能力', '', '50% TT预付款； 45%TT发货前； 5%质保款（质保期一年）', '', '该项目由EPC承包商进行融资，然后通过项目收益进行偿还', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。中水一局在刚果金与能源部及电力公司有非常好的关系，多次中标亿美金级别的水电站建设及输变电线路', '', '曾经给SNEL供过货，在SNEL有一定的供货记录。目前与业主无直接联系；业务与代理的该市场的国家代理私人关系非常好', '', '本次招标属于限制性邀请招标，共有6家公司参与；其中我司代理在该市场实力非常强大。同时，海兴在当地派有驻守人员，也在尝试接触我司代理。', '', '', '', '需求前往当地，与代理相关高层领导建立良好关系，与代理技术人员做AMI、预付费收费系统等的技术交流\r\n', '该项目共涉及39400台预付费电表。由于刚果金电力公司现在都是通过这类EPC工程型式发标，设计对某个区域的电网综合改造，不对电表进行单独发标。代理商实力非常强大，大概率机会中标。该市场潜力巨大，\r值得公司投入一定的资源进行开发。\r\r\n', '郑超波2018-10-15 09:56:30', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('184', '{01686681-1D60-40AC-A416-565B4000001B}', '61', 'INHE-0578', '2018-10-16 14:13:25', '0000-00-00 00:00:00', '2018-10-17 17:30:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101601/COB', '', 'Bid No. 2300G', '2018-11-16', 'Supply and Delivery of Smart Meters供应及运输智能电表', '价格条款：DDP\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n付款主体：City Power Johannesburg (SOC) Ltd\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n付款条件：交货后收到发票的30天内支付本地币；银河与NYC之间交易，参照ESA项目模式。\r\r\r\n\r\r\r\n\r\r\r\n交期：需供应商投标时明确交期（在评估时按照提供的交期打分，4周及以下10分，5~6周7分，7~8周5分，超过8周1分）。因此最好提供4周以内交期（与NYC协商）\r\r\r\n\r\r\r\n\r\r\r\n质保：电表需提供文件说明使用寿命（15年及以上10分，10~14年7分......），其他质保条款未明确。\r\r\n\r\r\n\r\r\n违约：交期上违约的话，或按照延误部分货值的0.5%/天收取。', '', '本地化生产比例评估：≥50%才能进入下一阶段评估；\r\n功能性评估：≥75%才能进入下一阶段的价格等评估；\r\n采取90/10分评估标准：报价90%，BBBEE资质等10%。', '', '分标授予，最多4家中标。将取评分最高的前4名，然后进入到竞争性协商，最后由City Power 决定授予几家中标。', '', '无需开立保函。', '', '≥50%本地化生产比例，BBBEE资质要求,CSD注册登记，本地服务支持', '', '1.需要仔细进行技术解析并由技术支持人员提供详尽的技术支持资料（目前该市政使用海兴和Itron的HES系统，本次招标要求电表需与现有系统兼容）；\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n2.需尽快提出需澄清的点，业务需全力配合尽快完成澄清；\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n3.样机提交时间将与代理沟通，尽快完成沟通后申请（否则在收到招标方要求后无法及时提供）；\r\r\r\r\n', '', '银河授权NYC投标', '', 'City Power自行决策采购流程（客户关系十分重要）', '', '交货后收到发票的30天内支付本地币；银河与NYC之间交易，参照ESA项目模式。\r\r\r\r\n\r', '', '良好。', '', '代理NYC此前在2015年参与过City Power的招标，但后因City Power内部原因，Itron和海兴中标。但NYC与City Power内部人员一直保持联系。\r\n\r\n\r\nNYC的本地化比例和BBBEE资质是较大的优势。', '', '暂无，NYC有一定的客户关系。', '', '主要竞争对手为Itron，海兴（City Power当前使用两家的系统和电表，掌握了较好的客户关系），预计还将有CONLOG，ACTOM等参与竞争。', '', '优势：NYC一定的客户关系，对City Power内部情况较为了解；NYC的本地生产和BBBEE资质；\r\r\n\r\r\n\r\r\n劣势：电表需与Itron,海兴系统兼容；此前未有供货；', '', '1. 技术方面需要满足；\r\n\r\n\r\n2. 价格方面要有竞争力；\r\n\r\n\r\n3. 投标资料需完备；\r\n\r\n\r\n4. 需跟进NYC搞好客户关系，实时关注动态。', '建议立项并作为重点项目对待。', '覃湘君2018-10-16 14:34:59', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('185', '{959F7709-D2F8-4C08-AF05-5266737AE312}', '61', 'INHE-0719', '2018-10-16 15:53:43', '0000-00-00 00:00:00', '2018-10-17 09:48:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101602/PLB', '', 'LP-009-2018-EU', '2018-10-26', 'ADQUISICION DE MEDIDORES ELECTRONICOS TRIFASICOS MULTIFUNCION三相多功能电子表招标', '付款条件：货到客户仓库后15天内一次性TT付款                      （代理公司与银河）：20万美金以下，采取TT付款                    交期：签订合同后60天                                           罚款：超过交期的每一天都会产生罚款，最高可达合同总金额的10%', '', '1.首要条件是满足技术规格，如不满足，将不接受                    2.实行打分制，价格占80分，Pi =（ Om x PMP）/Oi\r\r\r\nPi-价格分数，Om-报价中最低的价格，PMP-最高的价格分数，Oi-价格，  3.交期占20分，交期少于41天，分数20,41-50天，分数10分，51-59天,分数5分\r\r\n\r\r\r\n', '', '一家中标，一家制造商只可授权一家投标', '', '代理开保函', '', '1.投标者必须在SEACE网站上注册                                  2.投标者年营业额要达到220246.27美元                                \r\r\n\r\r\r\n', '', '客服已完成技术应答', '', '银河授权，代理投标', '', '', '', '', '', '', '', '代理公司技术力量较强，大部分员工为工程师。代理公司的2017年营业额至少达到100万美元，与欧洲三大运营商公司之一的telefonica公司是合作伙伴。领导团队总体年纪在中年，是电力公司工程师出身，所以有一定人脉基础，内部团队关系较为融洽。', '', '暂无业务人员长期在一线', '', '主要竞争对手有乾程，（在秘鲁首都利马有办事处，主要销售电表，断路器，表箱，变压器等，海兴（6年前在当地市场开办办事处，已在当地部分电力公司开始AMI试点项目。', '', '1.公司现有产品与标书要求有几处较大技术不符点，例如电压不满足，同时标书中显示如不满足技术要求，将不接受。                        2.此电力公司要求如中标，在交货时需要同时提交产品的本地认证INACAL证书，因此代理建议先投标，同时进行认证事宜，因三相CT表的认证目前较少的公司持有，只有ENEL和HONEWELLY有0.2s和0.5s的产品\r\r\n', '', '1.技术方面的支持，经过与代理的反复沟通，代理表示有些技术不符点必须满足，例如电压3x57.7/100 - 3x220/380 - 3x277/480，（与PLA项目要求电压一致），否则会对中标造成较大阻碍                2.希望公司能给出较为有竞争力的价格\r\r\n', '秘鲁电力市场中，私人电力公司较多，也较为分散，不同的电力公司和电力局分管不同的电力区域，不互相干扰，因此不同的电力公司的技术需求趋向不同化，多样化。会需要公司能根据电力公司的技术需求进行相应变化，从而更有竞争力。', '林丽君2018-10-16 18:11:57', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('186', '{3037859C-5DA8-475C-B4D2-8E6B7780EF9F}', '93', 'INHE-0762', '2018-10-16 17:56:39', '0000-00-00 00:00:00', '2018-10-18 10:55:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101603/LPU', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '莫林睿2018-10-16 18:15:38', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('187', '{DF476D7E-29D1-49CC-B5D7-FD3FB2B88EB1}', '60', 'INHE-0088', '2018-10-17 09:10:29', '0000-00-00 00:00:00', '2018-10-31 09:01:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101701/TNB', '此市场AMI一期项目立项流程为MSM，后改为TNB，现为二期项目正式完成流程立项', 'Tender RFx 4000026097', '2018-11-16', 'PEMBEKALAN & PENGIRIMAN SMART METER FOR SMART BILLING PROJECT DEPLOYMENT PHASE 2', '价格条款：报价货币为马来西亚令吉，含到当地内陆仓库运费，进口关税，培训费用，其他杂费；如验货在海外工厂，须保函验货费用，3G模块产品，投标人报价及供货范围需包括3G模块以及sim卡安装人工费，sim卡由TNB提供，RF模块须含除芯片外的部件价格，包含天线等，Trilliant RF OSDI模组由TNB与Trilliant统一采购发货给中标方；\r\r\r\r\r\n付款主体：TNB\r\r\r\r\r\r\r\r\n付款条件：\r\r\r\r\r\r\r\r\n交期：授标后中标方有最多9个月的时间完成兼容；项目计划在2020年3月底之前完成全部150万台产品的采购和验收入库\r\r\r\r\r\r\r\r\n质保：\r\r\r\r\r\r\r\n违约条款：', '{DF476D7E29D149CCB5D7FD3FB2B88EB18442F4C2B3234363A3D51C033076BD50}_TENDER DOC.zip', '技术评审主要条件： \r\r\r\r\nTrilliant开出的兼容证书（包括RF和3G）： 50% \r\r\r\r\n同型号10万台供货记录：30% \r\r\r\r\n人力资源和组织实力：20% \r\r\r\r\n \r\r\r\r\n商务评审主要条件：  \r\r\r\r\n投标人股东权益为正； \r\r\r\r\n实收资本不少于130万元人民币； \r\r\r\r\n现金流为正及其他财务指标比例有要求，授信及银行存款余额有要求（马六甲项目DPM在这一点上出了问题，提供的财务报告流动资金不足）； \r\r\r\r\n要求投标人为注册在马来西亚公司； \r\r\r\r\n以上商务评审条件，DPM确认已经全部满足，并在马六甲项目后，在TNB相同的商务评审条件下中标四个项目，分别为5000台普通电子表供货，1650台CT表安装工程、UPS供货以及1000台线路测试设备供货（项目金额在80万人民币-400万人民币左右不等）； ', '', '此项目将为多家中标，原则上只要是通过技术评审和商务评审的投标人，在接受TNB给出采购价格、采购数量并能够按时或者提前完成与Trilliant兼容工作的前提下，都有机会获得订单，订单价格将由TNB根据价格开标、评标情况确定，不会像马六甲项目一样要求所有供应商必须接受最低价，同时TNB承诺，供应商完成与trilliant兼容工作后，兼容所发生的费用TNB将给供应商报销，如超过9个月，TNB将不负责此费用。', '', 'DPM负责', '', '证书要求：ISO9001,ISO17025；测试报告：NMI+KEMA/CNAS\r\r\n财务要求：\r\r\n投标人股东权益为正； \r\r\n实收资本不少于130万元人民币； \r\r\n现金流为正及其他财务指标比例有要求，授信及银行存款余额有要求（马六甲项目DPM在这一点上出了问题，提供的财务报告流动资金不足）； \r\r\n要求投标人为注册在马来西亚公司； \r\r\n以上商务评审条件，DPM确认已经全部满足，并在马六甲项目后，在TNB相同的商务评审条件下中标四个项目，分别为5000台普通电子表供货，1650台CT表安装工程、UPS供货以及1000台线路测试设备供货（项目金额在80万人民币-400万人民币左右不等）； \r\r\n供货记录：同型号10万台供货记录：30% ', '', '11月16日截标，计划11月5日完成草稿，11月8日完成终稿，投标文件与上个投标类似，文件准备主要进行修改及检查。', '', '代理商投标，银河作为制造商授权，整机出货', '/', 'TNB高层董事会成员除了董事会主席和首席执行官CEO之外，全部是新进人员，人员变更原因主要是政府换届，据Azhar介绍，由于董事会成员绝大多数都是新加入人员。预计在决策上会以TNB智能表项目团队意见为主', '', 'DPM以TT+LC方式与银河结算，报价由银河报给DPM，DPM增加佣金及必要税费并在后获得银河同意后报出', '', '电力公司为国家电力公司，由财政部直接拨款5年预算，TNB承担电表费用为用户更换电表，支付能力较好，无须最终用户负责，且已承诺不增长电费', '', '原任智能计量项目主管Mohandas已经调离，原任项目技术主管调任到防窃电部门任职，新任项目主管Ghous之前在采购部门工作，与DPM总经理Azhar关系较好（约见见面比较容易），智能计量项目新任技术主管是原项目团队成员，之前DPM就是通过她运作TNB给trilliant要求支持DPM进行兼容工作的正式函件，与Azhar也很熟悉；\r\r\r\n代理公司内部团队对表计投标较熟悉，也能协助文件制作，与表计测试部有直接交流，样机按当地惯例包装提交，主要采用电子投标方式', '', '2018年10月12日，王总监通过DPM与新项目主管Gaus见面', '', 'AMI第一阶段：总需求238000 RF表，SAGEMCOM未供货，未与任何厂家兼容合作\r\r\nEDMI已供货14000台型号MK7B，因表为240V，模块为4.5V, 设计阶段DC转换问题未进行长时间测试，现场安装后出现故障，因此TNB已要求EDMI退回电表重新供货。EDMI采用金属铭牌，后期TNB希望使用镭雕。\r\r\nHolley华立已供货11000台，基本采用Trilliant的设计，2月份开始拿到COI后启动6个月的兼容，华立在中国进行基本组装修调、在泰国工厂进行总装出货；\r\r\nSAGEMCOM 起初负责供货 GPRS 部分，但是原投标报价为2G模块，TNB要求3G模块，目前此部分还未供货，Trilliant也在建议TNB采用RF替代GPRS/3G供货。 SAGEMCOM 难以完成与 Trilliant 进行兼容，华立在今年三月启动与Trilliant兼容、五月已完成3G部分，3G模块兼容由Trilliant方面单独进行，需将电表及3G模块在完成TNB DLMS规范测试后寄到加拿大由Trilliant完成驱动开发。DPM 将与 TNB 洽谈，获得许可后可启动与Trilliant兼容', '', '预计主要竞争对手为\r\r\r\r\nL1: 已完成兼容：据说20%份额TNB承诺给EDMI HOLLEY 取决于报价，EDMI须修改验证；\r\r\r\r\nL2: 已完成STAGE1 硬件设计及DEMO：Krizik+SECURE，台湾TATUNG（www.tatung.com.tw 在泰国PILK项目上与trilliant RF模块完成的兼容）+VSD子公司 \r\r\r\r\nL3: 刚刚完成STAGE 1或设计中：MIM-开发 MISA-RELIN硬件设计阶段，DPM-银河\r\r\r\r\nL4: 有兴趣但未付费启动：L+G Honeywell\r\r\r\r\nL5: 威胜-Troy/SIMENS不是很积极，但威胜与Trilliant在墨西哥有兼容合作项目需求；Genus-无本地合作伙伴；\r\r\r\r\n\r\r\r\r\nTNB AMI项目第一期30万只智能表项目（马六甲项目），EDMI和华立（泰国分公司）中标，截止目前，EDMI仍然由于与TRilliant的兼容问题，未能开始正常供货，华立由于泰国工厂产能很小，交付也非常慢，因此如何满足TNB技术要求并快速供货是关键因素。须展示银河的研发实力和生产能力，同时催促Trilliant更多', '', '1.按评标规则，Trilliant兼容工作的完成度占比50%，影响交期及中标数量，2期的价格预计比1期低，且参与竞争供应商更多；', '1.技术评估：技术规格与上次招标相同：RF须与Trilliant兼容，3G模块须与Trilliant HES系统接入；\r\r\n2.商务模式：授权代理投标（招标要求本地公司电子投标且有当地文件要求）；我司与DPM签订合同，T/T预付+L/C结算；\r\r\n3.项目组成员：余冬纯、林丹敏、莫亚检（余冬纯出差期间左亚楠指导文件制作）\r\r\n4.项目代号：TNB（一期项目原立项代号：MSM，后改为TNB，现沿用代号TNB正式立项）', '余冬纯2018-10-19 14:49:50', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('188', '{8C3EF3C5-5E12-43C7-AB03-684CA72732E4}', '60', 'INHE-0769', '2018-10-17 09:15:06', '0000-00-00 00:00:00', '2018-10-31 09:02:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101702/MEW', '', '暂无，还未发标', null, '', '付款主体是MEW电力公司，付款分期支付。预计交期为一年，每3个月交25%的货。', '', '各方投标后，CTC会选取价格最低投标方，然后将技术规范给MEW进行评估，评估合格后，三个月按照MEW的要求制作样机然后提供给MEW进行测试，该样机制作涉及表计本身研发以及兼容工作，但兼容方面所需的信息和文件由MEW提供，不与zain和施耐德直接沟通；如果样机测试合格，将进行第一批次的正式生产，如果不合格，CTC再选择第二低价投标方进行此程序，以此类推；', '', '暂无', '', '投标保函为合同金额的2%；履约保函为合同金额的10%，有效期是一至一年半。', '', '在三个不同国家（无需是欧美国家）有过类似数量或是更大数量的供货经验。', '', '', '', '银河投标', '', '', '', '根据供货分期付款', '', '', '', 'UGCC整体实力较好，尤其是财务实力强劲；长期作为EPC承包商，消息获取渠道多样，现阶段与MEW其他项目也有交集部分，与科威特各政府部门有着诸多合作。MEW还未正式发标，UGCC已有草标。', '', '', '', '目前市场上能确定的竞争对手有Elster（与holleywell一起），iskara以及Siemens，Secure，另外还有一家沙特的公司。HES部分已确定由施耐德提供\r\r，通信方案确定为Cellular（4G Lte）通信，即表与HES系统直接Cellular通信，由zain负责整体方案，包括SIM卡，网络通信，网络协议以及网络安全等\r\r\n', '', '我们之前在科威特有成功实施试点项目，安装的模块表仍然还在现场运行。暂时来看，技术方面是没有太大问题的。而且上述投标产品是可以自由组合投标的，即可只投其中一款或是几款；商务方面，代理实力雄厚，对MEW相关部门的项目运作也比较熟悉，保函开立方面承诺到时候也可以协议帮忙。\r\r\n', '', '合作伙伴的运作，与合作伙伴以及客户共赢，提供给客户满意的产品方案', '', '吴琼2018-10-18 09:29:12', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('189', '{E6B38650-5EF3-4049-9D34-3849CB541CB1}', '61', 'INHE-0500', '2018-10-17 15:43:13', '0000-00-00 00:00:00', '2018-10-22 11:43:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101704/EMU', '', '11/2019/15', '2018-10-29', 'Appointment of service providers for supply and delivery of electricity meters for industrial, commercial and residential customers for a period of thirty six months on as and when required basis. 三年期框架招标供应涵盖普通居民用表、工商业用表', '报价条款：DDP报价，兰特币。\r\n银河对NYC报价：FOB Shenzhenn \r\n付款条件：交货后收到发票的30天内支付本地币。\r\nNYC对银河付款条件：同ESA项目。 \r\n资金来源：Emfuleni Local Municipality\r\n', '', '评标分为三个流程：1.技术资料评标，在总数为100分的技术评分的基础上才有资格进入到第二轮的价格评审；2.价格评审，按照BBBEE资质90/10的偏好打分，BBBEE最高资质有10分偏好；\r\r\n', '', '一家中标\r\r\n', '', '需要开立投标保函和履约保函，NYC开立\r\n', '', '1.注意报价申请时需包含CKD，SKD，成品报价三种报价。\r\n注意对照P57面强制性投标文件（整理出代理准备部分和银河准备部分），银河部分主要准备技术文件，稍晚JUNE会提供该市场常规投标文件供参考。\r\n', '', '1.注意报价申请时需包含CKD，SKD，成品报价三种报价。\r\n注意对照P57面强制性投标文件（整理出代理准备部分和银河准备部分），银河部分主要准备技术文件，稍晚JUNE会提供该市场常规投标文件供参考。\r\n', '', '代理NYC直接投标，银河作为厂家支持。\r\n', 'N/A', '市政公司自行决定评标全流程，评标委员会由市政指定的技术代理+财务部成员+采购部成员+电力分支负责人组成，中标的最终价格需要参考财务部审批的年初预算\r\n', '', '付款条件：交货后收到发票的30天内支付本地币。\r\nNYC对银河付款条件：同ESA项目。 \r\n资金来源：Emfuleni Local Municipality\r\n', '', '市政公司信息待进一步调查和跟进反馈', '', 'NYC优势：BBBEE资质10分偏好优势；本地工厂满足50%本地化生产（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案\r\r\nNYC劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\n', '', '此市政对于银河也是新客户，第一次参与投标\r\n', '', '市政公司信息待进一步调查和跟进反馈\r\n', '', '竞争优势：NYC优势：BBBEE资质10分偏好优势；本地工厂满足本地化生产要求（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案。银河技术方案的符合，以及价格优势；\r\r\n竞争劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\n策略：供货记录的澄清，完成商务和技术的无偏差；和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好技术演示，一次性成功完成演示需求。						\r\r\n', '', '1,样机满足市政公司要求；\r\n2.提供具有竞争力的报价；\r\n3，需要打通CFO和技术部门的客户关系。', '项目组成员：李忠鹏 覃湘君 吴艳', '李忠鹏2018-10-17 16:04:19', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('190', '{024BBC15-6CC8-4448-BF8F-2A5B9063EBD6}', '61', 'INHE-0593', '2018-10-17 22:43:25', '0000-00-00 00:00:00', '2018-10-31 09:02:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101706/BFD', '', '/', '2018-11-30', '/', '/', '', '/', '', '/', '', '方案准备中，暂未谈及具体的付款方式，电力公司高层需要拿到方案后进一步评估。', '', '/', '', '/', '', '银河及理AZon共同推动该项目', '/', 'BFN为100%国家控股企业，政府对电力公司决策影响大。', '', '金额较大款项需要提前报备国家财务部审批，同意后付出，一般是通过信用证。', '', '/', '', '代理Azon，老客户，近年有在科特迪瓦（布基纳法索邻国）建电表组装厂的规划。', '', 'BFN03订单执行，我们与BFN电力公司建立起了联系及熟悉起来，有一定的基础；\r\r\r\r\n\r\r\r\r\n\r\r\r\r\nBFN05/BFN07/BFN09/BFN10执行，在该市场上与代理之间的信任感陆续增强，有希望能在建厂项目上密切合作。', '', '主要的电表竞争着为Hexing，Itron，Clou，兰吉尔：建厂方面目前没有相关提案。', '', '联合SONABEL建厂，他们建厂，我们可提供设备（预收一定款项），电力公司承诺相关配件从银河采购。								\r\r\r\n', '', '银河及代理密切合作，电力公司相关领导层的推动', '支持立项，联合SONABEL建厂，他们建厂，我们可提供设备（预收一定款项），电力公司承诺相关配件从银河采购。', '胡蝶2018-10-22 05:39:41', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('191', '{78677453-9211-4F48-A78A-C3F40E4AD2F6}', '60', 'INHE-0549', '2018-10-18 21:48:03', '0000-00-00 00:00:00', '2018-10-31 09:02:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101801/EPB', '', '无', null, '无', '由福雷斯特集团付款，我们提供FOB与DDP详细价格，由他们选取最优方案。', '', '在最终客户电力公司技术认可的情况下，他们评价决定与哪家供应商合作。', '', '这是一个完整的标，他们在完成整体预算后决定商业模式。', '', '无', '', '无', '', '技术文件', '', '代理直采', '无', '无', '', '100%不可撤销的即期信用证						', '', '该项目是客户带资金做的EPC项目，客户资金调动能力强。						\r\r\n', '', '福雷斯特集团在刚果金做了很多年的项目了，对该国国情与电力公司内部人员应该比较熟悉。EPS项目也是其带资金做的项目。						\r\r\r\n', '', '能源分支的CEO与我司在16年有过合作，该项目也是他发来的询价。						\r\r\n', '', '他们希望我们给出有竞争力的价格，没有提供目标价格，最终通过比较技术和价格决定采用哪家的产品。						\r\r\r\r\n', '', '最近与该客户交流比较多，对方目前反应很积极，如果价格合适的话，相信客户会选择我司供货。						\r\r\r\r\n', '', '关键在于价格有竞争力，需要客服协助提供技术文档						\r\r\r\n', '这是福雷斯特集团带资金在刚果金做的一个EPC项目，需要我司提供电表、表箱、断路器、与电力公司现有系统直接通信的集中商业管理系统、与集中系统通信的十个售电点的系统以及现场技术支持。客户对技术方面没有特别要求，可直接使用公司现成产品。目前客户只要求我司提供报价和技术文件。', '王秀明2018-10-18 22:44:54', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('192', '{696D6FE9-B477-4925-A1C9-0607F67BD6C6}', '61', 'INHE-0432', '2018-10-19 01:36:17', '0000-00-00 00:00:00', '2018-10-30 17:34:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101901/SGT', '', '待确认', null, '待确认', '1.价格条款：DDP   \r\r\n2.付款主体：电力公司（HEDNO）\r\r\n3.付款条件： OA 120                                                     ', '', '1.初审：审核基本投标资料\r\r\n2.二审：技术评审，样机测试。此前项目是在样机评审因不满足要求而失败。\r\r\n3.终审：符合以上要求，报价最低。\r\r\n', '', '', '', '1.投标保函：总报价的2%\r\r\n2.履约保函：总合同金额的5%', '', '', '', '', '', '代理希望银河投标；但业务正在与其协商，希望代理直接投标。', '', '', '', '', '', '', '', '1.代理公司与电力公司已合作40多年，与电力公司有较深的客户关系。', '', '较弱', '', '1.主要竞争对手有立陶宛的Elgama，中国华立，中国三星，新加坡的EDMI和法国的SAGEMCOM，ITRON和LANDIS+GYR等。目前最大的竞争对手是HOLLEY，Elgama以及EDMI。华立在2011年给PPC通过招标供了5000台单相智能电子表，目前PPC对华立的产品比较满意。之前的SA项目，19000台单相简单智能表也是华立中标。\r\r\r\r\r\n2.EDMI联合IntracomTelecom在2014年给PPC供货45000台GSM/GPRS通讯智能电表。\r\r\r\r\r\n3.三相直通模块表最大竞争对手是ELGAMA；CT表为EDMI,LANDIS+GYR和ITRON。\r\r\r\r\r\n', '', '优势：\r\r\r\r\r\r\n1.经过此前的参展、对电力公司的拜访宣讲等，电力公司对银河的产品有较好的评价。\r\r\r\r\r\r\n2.代理有一定的客户关系积累，目前合作积极，希望与银河合作成功。\r\r\r\r\r\r\n\r\r\r\r\r\r\n劣势：\r\r\r\r\r\r\n1.公司产品技术硬伤、不符点较多，需要改进、调整，以满足技术要求。\r\r\r\r\r\r\n2.相关资质认证缺乏，需要投入一定资源获取相关必要的认证。\r\r\r\r\r\r\n3.目前与代理合作策略、与电力公司客户关系基础较弱，需要加强一线的代理及客户关系建设、竞争对手的客户关系、产品及资料的情报搜集。\r              \r\r\r\r\n4.价格竞争异常激烈，产品价格非常低。            \r\r\r\r\n', '', '1.解决技术上的难题；\r\r\r\n2.解决产品资质的认证问题。', '说明：\r\r\n1.进入希腊市场，必须要首先解决系统与表的通讯问题、及相关资质认证的问题。\r\r\n2.目前电力公司招标还未正式发布，基于与代理的沟通得知，电力公司即将招标，希望我们能解决此前遇到的技术难点、资质认证等问题，与代理一起合作竞标成功。招标的数量是根据电力公司的需求和规划而预测的。\r\r\n3.业务希望公司审批并同意立项，然后支持样机制作，解决此前遇到的技术难点，然后业务寄给代理，在一线的测试环境下进行测试，确保技术上符合招标要求。\r\r\r\n', '谭东羊2018-10-24 17:06:42', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('193', '{53556280-EC66-4313-A1A5-74FF62C62D93}', '61', 'INHE-0725', '2018-10-19 14:48:33', '0000-00-00 00:00:00', '2018-10-24 14:42:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101902/GLZ', '', 'BID No. GH-MOE-20279-GO-RFB', '2018-11-21', 'Supply and Installation of 25,000 No. Bulk Metering 供应和安装25000套大用户计量产品', 'CIP Tema Sea Port', '{53556280EC664313A1A574FF62C62D938442F4C2B3234363A3D51C033076BD50}_Payment Conditions.xlsx', '先技术，后商务，\r\r\r\r\r\r\r\n1.在技术评标过程中如果发现某一投标方的标书不符合完整性及一致性的要求，对于细节要求无法达到采购方的最低要求；无法达到在指定功能上采购方所提出的的最低要求（或最大要求，视情况而定），该投标方将会被取消资格；\r\r\r\r\r\r\n2.商务评标中采购方考核的因素主要为价格，项目实施进度，投标方资质。\r\n注：如在商务评标中，中标方以最低价中标，那么招标方有权增加其履约保函金额。', '{53556280EC664313A1A574FF62C62D93074E749A304748709C51373D9D483750}_Evaluation of Bids.docx', '待定', '', '需开立投标保函，保函金额为500,000美金，保函有效期至少为截标期后150天，同时保函必须在原始保函有效期的基础上延长28天。中标方在获得授标函后应开具履约保函，保函金额待定，保函开立方为银河。', '', '1.未被银行取消资格或拉黑（ITB4.4）\r\r\r\r\r\r\r\n2.2年内未出现合同违约的情况；\r\r\r\r\r\r\n3.正在进行中的诉讼案件涉案费用应不超过50%\r\r\r\r\r\r\n4.需提交5年内审计财报，要求a.资金流动比率不小于1；b.负债比率不超过0.6； c.流动资产与总资产的比率需大于0.1\r\r\r\r\n5.年最低营业额为36,500,000美金，并需证明其实际资产足以完成预估为4,500,000美金的项目；\r\r\r\n6.投标方需提供其在供应及安装LPU电表项目方面至少五年的经验；\r\n7.投标方需在过去五年内至少成功操作两个类似项目，每一项合同金额至少为1460万美元；', '{53556280EC664313A1A574FF62C62D9303404677E4D44E9EB56B3D512B2AF9CC}_Qualification Criteria.pdf', '需要客服部门及配电部评估技术要求，此外需要商务部门协助整理投标资料', '', '银河投标', '客户倾向于佣金模式', '待定', '', '详见附件', '{53556280EC664313A1A574FF62C62D93DC30B63FF962416CACC9A604CE6ABE1F}_Payment Conditions.xlsx', '世行融资项目', '', '客户本次为我方购买标书，对于该项目较为重视，客户与当地电力公司关系良好，多次介绍内部人员与我方沟通，在今年6月份也安排了我方与加纳能源部副部长的会面，代理当地客户关系良好，如公司同意立项，后续代理会进一步协助开发与这两个机构的客户关系。', '', 'PPA为我方老客户，之前与我方合作过招标项目，对于运作客户关系有一定的经验，客户与电力公司关系良好，之前也有将加纳能源部（招标方）介绍给我方认识，代理对于该项目较为积极，后续也会协助运作客户关系', '', '海兴，西门子，MPH（科陆），Alpha，华为等', '', '1.LPU项目是我方所擅长的项目，之前我方已错失JJN项目（系统标），拿下该项目对于后续市场的开发很有战略意义；2.我方代理与客户关系良好，并未我方购买标书，对于该项目较为重视；3.目前标书获取时间较晚，准备时间较少，需要公司配合。', '', '1.该项目对于技术方面要求较高，LPU项目为我方擅长项目，如能满足技术要求对于拿下整个项目有重大意义；2.目前准备时间较少，希望公司能给予支持。', '该投标项目有以下几点优势：1.我方已在当地市场运作过JJN项目，积累了一定的客户关系及项目经验；2.世行投资项目资金稳定，项目安全性高；3.该项目为LPU项目，正式我方所擅长的领域；4.我方与当地代理关系良好，且在当地积累了良好的客户关系，代理之前也多次介绍电力公司的工作人员给我们人数，同时在6月份安排了我方与加纳能源部副部长的会面。结合以上优势，向公司申请立项，希望公司予以支持和帮助。', '赵政洁2018-10-19 17:54:30', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('194', '{5C6AA16E-CBEA-4267-B8DC-0E4C51E087AE}', '61', 'INHE-0434', '2018-10-23 11:42:12', '0000-00-00 00:00:00', '2018-10-30 17:36:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102301/GLA', '', 'GH-MOE-20272-GO-RFB', '2018-11-27', 'SUPPLY AND INSTALLATION OF SMART METERING FOR PREPAYMENT CUSTOMERS IN THE TEMA SOUTH DISTRICT OF ECG 为预付费用户供货和安装智能计量设备', 'CIP Tema Sea Port', '{5C6AA16ECBEA4267B8DC0E4C51E087AE8442F4C2B3234363A3D51C033076BD50}_GLA项目付款方式和条件.docx', '', '', '待定。GLA项目只有一个LOT，通常为一家中标。', '', '1. 需开立投标保函，保函金额为500,000美金，保函有效期至少为截标期后150天，同时保函必须在原始保函有效期的基础上延长28天。\r\n2. 中标方在获得授标函后28天内应开具履约保函，履约保函金额为合同金额的10%，保函开立方为银河。', '{5C6AA16ECBEA4267B8DC0E4C51E087AE1DD410FC292E4E1893AFBEF9F88431CD}_GLA项目投标保函和履约保函要求.docx', '1.未被银行取消资格或拉黑（ITB4.4）\r\r\r\r\n2.2年内未出现合同违约的情况；\r\r\r\r\n3.正在进行中的诉讼案件涉案费用应不超过投标方净资产的50%\r\r\r\r\n4.需提交5年内审计财报，要求a.资金流动比率不小于1；b.负债比率不超过0.6； c.流动资产（营运成本）与总资产的比率需大于0.1\r\r\r\r\n5.过去5年的年均建设营业额最低不能少于为6500万美金，并需证明其实际资产足以完成预估为800万美金的项目；\r\r\r\r\n6.投标方需提供其在供应及安装智能电表项目方面至少五年的经验；\r\r\r\r\n7.投标方需在过去五年内至少成功操作两个类似项目，每一项合同金额至少为2600万美元；', '{5C6AA16ECBEA4267B8DC0E4C51E087AE03404677E4D44E9EB56B3D512B2AF9CC}_GLA项目投标资格要求.docx', '需要客户服务部提供技术解析并提供项目要求的投标文件（正在整理），此外需要商务部门协助准备商务方面的投标资料、申请投标样机、申请开立投标保函', '', '银河投标，代理倾向于佣金模式（代理可提供本地安装服务）', '', '待定', '', '同GLZ项目一样，可见附件', '{5C6AA16ECBEA4267B8DC0E4C51E087AEDC30B63FF962416CACC9A604CE6ABE1F}_GLA项目付款方式和条件.docx', '世行融资项目', '{5C6AA16ECBEA4267B8DC0E4C51E087AE108D268797C74834B1DDE2FC1083AA37}_GLA项目为世行项目.docx', '客户本次为我方购买了标书（同时也购买了GLZ标书/LPU项目），对于该项目较为重视，客户与当地电力公司关系良好，多次介绍内部人员与我方沟通，在今年6月份也安排了我方与加纳能源部副部长的会面，代理当地客户关系良好', '', '加纳市场此前已代理处理客户关系为主，从JJN项目开始银河开始和代理一起处理客户关系，目前仍以代理为主，GLZ项目和GLA项目将去一线加强客户关系', '', 'GLZ项目和GLA项目预估竞争对手有：海兴，西门子，MPH（科陆），Alpha，华为El Sewedy等。', '', '1. 首先自身准备好投标所需资料和样机；2. 去一线与代理一起经营客户关系，引导通过澄清给竞争对手埋雷同时修改对银河不利条款；3. 银河代理在当地有一定实力，其一直代理正泰产品，在能源部和电力公司有一定关系；4. 加纳在西非英语区影响力较大，经济相对而言不算很差，人口有3000万，电力公司对智能表和系统有需求；5. 本地竞争大，海兴、CLOU、El Sewedy早已进入该市场并批量供货；', '', '1. 投标资料和样机无问题；2. 报价具有竞争力；3. 客户关系到位；4. 需要技术和商务支持（投标资料方面）', '1. GLA项目为世行项目，资金和回款上有保障；\r\r\r\n2. 项目所需产品为公司熟悉产品，应标上不会太陌生；\r\r\r\n3. 银河本地代理有一定实力懂竞争和项目运作，认为该项目银河需要参与；\r\r\r\n4. 加纳在JJN（美国MCC项目）后陆续出了GLZ（世行LPU项目）和GLA（世行电表项目），认为值得争取；\r\n5. 投标资料需仔细、细心准备，谨防JJN投标文件问题再次出现（代理为JJN项目代理）；', '钟云林2018-10-23 14:47:08', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('195', '{BFF3B77E-795D-4A42-8097-72E3B9EA0274}', '60', 'INHE-0560', '2018-10-23 17:05:26', '0000-00-00 00:00:00', '2018-11-07 18:48:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102303/MEA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '乌克兰表计市场主要的国外供应商有摩尔多瓦的Add-Grup，Iskrasi, Itron，乌克兰本地市场的竞争对手是ооо《NIk》公司，Add-Grup公司未来几年的主要市场为保加利亚，在乌克兰的目标销量不多。                                 \r\r\nIskrasi,Itron两家公司从其在乌克兰市场的表计销售价格来看，其供应产品多为低端简单表，市场占有率稳定但不高。其国内表计制造商《NIk》公司经营范围很广，表计产品属于其一个分支，虽然有自己的表厂但几乎依靠国外进口表计供应其国内市场，产品价格普遍较低，属于中低端产品。由于其在国内基本保持低价竞争策略且产品质量表现不佳，因而产品质量为很多终端客户诟病，这为其余优质表计厂家提供了市场机遇。                                                  \r\r\n现阶段进入乌克兰市场的中国表计厂家主要为华立和浙江永泰隆两家，分别在去年有30-40万美金不等的销售业绩，且都为贴牌合作。从以上两家的销售额来看，该市场前景潜力巨大。', '', '优势：产品质量优良+丰富的OEM散件供货经验                              该市场我司除Goshen项目以外基本为空白，从了解到的情况来看，该市场表计实际需求量巨大，其国内现有多家电力相关企业在寻找优秀表计供应商进行贴牌合作。对银河来说，这是进入该市场的绝佳机会。除此之外，鉴于该国家的特殊地缘优势，该市场的顺利开拓或可成为我司打开东欧市场的敲门砖。              现阶段已明确客户需求表型及后续合作模式（OEM散件供货），年需求量约为50万台左右（单相35万，三相15万）。客户希望我司提供样机供其测试，测试通过后，将来访我司就后续订单展开谈判。', '', '1.研发支持，样机需最大限度符合客户技术需求，且按时提供。                                        2.具有竞争力的价格                                                                            3.产品性能稳定', '建议立项', '李美娇2018-10-31 11:14:28', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('196', '{16AB2CEA-8984-47B3-A945-240B20AC7A61}', '61', 'INHE-0500', '2018-10-24 12:41:28', '0000-00-00 00:00:00', '2018-10-30 17:37:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102402/ZCO', '', '协议性直采项目', '2018-10-26', 'N/A', '1.合同由银河方负责起草提供；\r\r\n2.付款条件：电表类：发货前T/T付清；系统类：初步计划建议按照年度收取；\r\r\n3.其他条款：按照银河标准销售合同签订。', '', 'N/A', '', 'N/A', '', 'N/A', '', 'N/A', '', '请客服部指派一名客服工程师定向服务此项目的技术规格制定和后续试点项目远程和现场技术支持。（考虑到后续需要出差，现场环境不好，男性工程师较好）', '', '协议性直采项目\r\r\n', 'N/A', '协议性直采项目\r\n', '', '付款条件：电表类：发货前T/T付清；系统类：初步计划建议按照年度收取\r\r\n项目经理发出项目的清单采购，财务部负责付款。', '', '良好', '', '银河直接和ECONET协商性供货，无其他中间合作伙伴', '', 'N/A', '', '银河直接和ECONET协商性供货，无其他中间合作伙伴和竞争厂商\r\r\n', '', '1.银河已在此市场供货多年，包括ZCO客户对银河认知度非常高，双方合作的诚意大；\r\n2.ZSM项目银河虽然没有中标，但是通过ZCO项目，银河可能成为第一个在ZEC市场进行智能电表试点的厂商，凭借当前电力公司内部的关系和ECONET的实力，完全有可能通过ZCO项目扩大到全国和ZETDC的大范围合作。', '', '1.银河提供全套的技术方案和定向的技术支持人员，保证试点项目快速执行完毕，设定目标：12月20日之前完后电表现场的安装和系统初步试运行；\r\n2.公司方面给与对项目的前期报价支持，需要考虑到试点项目的特殊性，具体单独在报价申请里汇报。', '李忠鹏认为此次ZCO对于银河在ZEC市场的智能电表项目，无论从合作伙伴（ECONET），还是从市场容量，或是竞争角度看，以及未来和通讯运行商布局NB-IOT业务，都是一个良好和有潜力的发展项目，希望公司能提供定向的技术支持，协助李忠鹏推进和完成这个项目。', '李忠鹏2018-10-24 13:31:01', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('197', '{CEE95A26-1095-4893-B697-47F1B7F3A0D1}', '93', 'INHE-0789', '2018-10-26 18:43:31', '0000-00-00 00:00:00', '2018-10-30 17:32:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102603/MCT', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '林凤兰2018-10-26 19:21:04', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('198', '{2463ACFD-2500-4BFB-A1E8-C7F3D361816D}', '66', 'INHE-0628', '2018-10-29 11:31:21', '0000-00-00 00:00:00', '2018-10-30 17:38:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102904/SLE', '', 'EDSA/AfDB/DIST/ICB/02/REH/09/18', '2018-11-08', 'Supply, Installation and Commissioning of Split Prepaid Meters, Service Connections and Accessories分体式预付费电表、服务安装和配件的供应安装和调试', 'CIP，预付款20%，发货后70%，完工证明5%，验收后5%。', '', '根据样机和文件评审投标人的设计、安装和项目管理能力。', '', '一家中标', '', '20万美元', '', '近三年营业额超过1500万美元，有超过3个8百万美元的合同', '', '需要电缆和绝缘穿刺线夹的样品和Type Test', '', '银河投标（代理想采用联合体方式投标，但资质不符合）', '', '电力局评标还需ADB参与决策', '', '不可撤销信用证，预付款20%，发货后70%，完工证明5%，验收后5%。			', '', '未知', '', '代理在电力部执行过若干水表项目，并称和电力部长有关系，可安排会见关键人物', '', '', '', '目前只有Conlog的分体预付费电表，通讯方式为cable', '{2463ACFD25004BFBA1E8C7F3D361816DC8C3CDC70C5243B796247CC1ED7EC56E}_产品图.png', '银河接入太晚，技术规格很可能为conlog起草，但根据客服解析，门槛不高。目前主要是时间紧急，制作样机和外购配件与报告来不及，要求代理延期（可能有2周）。', '', '提交符合标书的样机、电缆、穿刺绝缘夹样品和Type Test，需制作和外购。', '从电力局公布数据看，塞拉利昂预付费电表市场只有3万台在用，电力局援助资金充裕，建议尝试投标了解市场情况。', '刘元豪2018-10-29 12:15:52', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('199', '{92529695-3187-4B3B-8F6A-A5CDDD2B91BA}', '60', 'INHE-0781', '2018-10-30 13:45:41', '0000-00-00 00:00:00', '2018-11-07 18:27:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018103003/DSC\r\n', '', 'IFT-02/2018', '2018-11-27', 'Supply and installation of smart pre-payment meters in DESCO area在DESCO区域供应和安装智能预付费电表', '付款条件：\r\r\n一、国外供货\r\r\n无预付款\r\r\n1.60%（仅指货物价格）：货物装运后，通过供应商指定银行、不可撤销的L/C支付\r\r\n并以提交装船文件为前提（Shipping document）\r\r\n\r\r\n2. 10%（仅指货物价格）： 验收入库30天内 \r\r\n并以买方货物验收证明为前提(Acceptance certificate，运送至交付点后的14天内开具此证明)\r\r\n\r\r\n3. 20%合同价格： after installation and commissioning安装全部智能预付费表，调试集抄系统\r\r\n并以买方临时验收证明为前提(Provisional Acceptance certificate)\r\r\n\r\r\n4. 10%合同价格 ：完全安装电表并开通预付费抄表系统\r\r\n并以买方最终验收证明为前提(Final acceptance certificate，30天内开具此证明)\r\r\n\r\r\n国外产生的费用按美金支付，付款不得超过收到发票后的45天\r\r\n国内产生的费用按孟加拉当地币Taka支付，本币付款不得超过30天\r\r\n\r\r\n二、孟加拉本国供货\r\r\n无预付款\r\r\n1.70%（仅', '{9252969531874B3B8F6AA5CDDD2B91BA8442F4C2B3234363A3D51C033076BD50}_payment term.rar', '先资格预审，招标方会至少提前30个日历日通知去做样品和抄表系统的演示，演示会作为技术评审的一部分技术评审，通过技术评审的投标人进入价格评审，开价格标，低价中标。\r\n', '', '1个Lot 1家中标\r\n', '', '一、投标保函\r\r\n1.金额：455,000 USD \r\r\n2.投标有效期150天+28天，即2019年5月24日\r\r\n3.是否转开：是\r\r\n\r\r\n二、履约保函：合同价格的10%\r\r\n', '{9252969531874B3B8F6AA5CDDD2B91BA1DD410FC292E4E1893AFBEF9F88431CD}_tender security 1.JPG', '1.	过去5年内最多3个合同合计供应/供应&安装单相预付费/智能预付费电表90,000台，三相预付费/智能预付费表10,000台；合同金额达到800万美元。\r\n2.投标截止日倒推过去5年内至少有在2家电力公司（一家是投标者本国以外的公司）实施预付费电表/智能电表的供货经验。\r\n3.投标人要证明可以满足供应30万台智能预付费电表的产能。\r\n4.提交过去三年财务报表，要求净资产为正数。\r\n5.过去3年内平均年营业额最少达到2000万美元。\r\n6.1780万美元流动资产。\r\r\n', '', '待出具完整的投标文件清单（需客服部、实验室等的协助）；截标日为2018.11.27\r\r\r\r\r\n', '', '联合投标\r\r\n', '主投方银河。按照规定单独投标需要当地有分公司，在没有分公司的情况下必须有一家当地代理，而且这个项目包含安装部分，所以按照以前的协议我们选择JV投标。银河提供表计等产品，代理提供安装。', '电力部对采购决策有较大影响。\r\n', '', '付款条件：\r\r\r\n一、国外供货\r\r\r\n无预付款\r\r\r\n1.60%（仅指货物价格）：货物装运后，通过供应商指定银行、不可撤销的L/C支付\r\r\r\n并以提交装船文件为前提（Shipping document）\r\r\r\n\r\r\r\n2. 10%（仅指货物价格）： 验收入库30天内 \r\r\r\n并以买方货物验收证明为前提(Acceptance certificate，运送至交付点后的14天内开具此证明)\r\r\r\n\r\r\r\n3. 20%合同价格： after installation and commissioning安装全部智能预付费表，调试集抄系统\r\r\r\n并以买方临时验收证明为前提(Provisional Acceptance certificate)\r\r\r\n\r\r\r\n4. 10%合同价格 ：完全安装电表并开通预付费抄表系统\r\r\r\n并以买方最终验收证明为前提(Final acceptance certificate，30天内开具此证明)\r\r\r\n\r\r\r\n国外产生的费用按美金支付，付款不得超过收到发票后的45天\r\r\r\n国内产生的费用按孟加拉当地币Taka支付，本币付款不得超过30天\r\r\r\n\r\r\r\n二、孟加拉本国供', '{9252969531874B3B8F6AA5CDDD2B91BADC30B63FF962416CACC9A604CE6ABE1F}_tenderer experience 1.JPG', 'GOB项目，有资金支付\r\n', '', '合作代理与电力部以及电力公司有较好关系，有助于投标运作，赢得中标。\r\n', '', '关系良好\r\n', '', '海兴，威胜，科陆，思达等常见对手，加上该项目对资质经验和财务要求不高，可以预见会有很多新的大小厂家进来。\r\n', '', '较好的付款条件，良好的政府/电力公司关系。\r\n', '', '关键仍在价格，另外这个要上集抄，从以往项目实施来看复杂程度增加很多，需要技术上提供足够支持。另外在报价策略上也需要做一些支持。中标后本地实施，需要的办事处/项目办公室设立支持。\r\n', '建议投标。\r\n', '李启坦2018-11-05 14:47:14', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('200', '{B859F563-6AF7-4F64-8624-200D50A37CAA}', '61', 'INHE-0772', '2018-11-01 15:22:16', '0000-00-00 00:00:00', '2018-11-06 09:22:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110101/SAS', '', '', '2018-11-09', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '技术支持：电表的技术解析，软件的技术解析。    商务支持：提供交货记录，协助部分解决方案文书的编辑', '该项目没有确切技术规格，需要针对安装环境先技术解析后根据推荐软硬件报价。德国公司风格偏好实用，计划性强的方案。该客户的业务广泛，与我司是第一次合作，若能够使之眼前一亮。我司有大机会进入客户在欧洲的项目。但时间紧张，建议部门之间的沟通要及时充足。					\r\r\r\r\n', '张子琦2018-11-02 09:03:16', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('201', '{F49675CD-A53D-450E-B1FE-D788001F6DB3}', '61', 'INHE-0578', '2018-11-02 11:36:55', '0000-00-00 00:00:00', '2018-11-06 09:30:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110201/ESK', '', 'DD6689/TX', '2018-11-28', 'THE MANUFACTURE AND SUPPLY EX-WORKS OF ESTIMATED QUANTITIES OF SPLIT PREPAYMENT METERS ON AN “AS AND WHEN” REQUIRED BASIS TO KWAZULU NATAL AND EASTERN CAPE REGIONAL DISTRIBUTION CENTRES FOR A PERIOD OF SIX (6) MONTHS.按需向夸祖鲁省及东开普敦省生产及供应预付费分体式电表，为期6个月。', '价格条款：EXW，但报价单要求从EXW到DDP（银河向NYC报价FOB即可）。\r\n\r\n\r\n付款主体：ESKOM\r\n\r\n\r\n付款条件：收到发票后30天内付款（NYC向银河付款，参考ESA项目）\r\n\r\n\r\n交期：按需交货，ESKOM向厂家下达PO，按照要求交货。\r\n\r\n\r\n质保：5年质保，', '{F49675CDA53D450EB1FED788001F6DB38442F4C2B3234363A3D51C033076BD50}_Split Prepayment Meters - Invitation to tender.pdf', '4个过程：\r\r\r\n\r\r\r\n1.基础资质及文件评估；\r\r\r\n2.功能性评估：\r\r\r\n*技术应答、技术资料、风险管控及技术支持。 \r\r\r\n*电表和相关软件样机测试（如有）\r\r\r\n*功能性评估达到85%才能进入下一阶段评估。\r\r\r\n3.价格评估\r\r\r\n4.倾向性评估（PPPFA及BBBEE资质打分）\r\r\n', '{F49675CDA53D450EB1FED788001F6DB3074E749A304748709C51373D9D483750}_Split Meters - Supply Contract.pdf', '按照评标规则评估，ESKOM挑选短名单，后期进入合同协商阶段，不一定是得分最高者/价格最低者中标。\r\r\r\n可以一家或多家中标（倾向于多家分标）。\r\r\r\n就目前情况来看，是因为ESA项目合同已到期，新项目还未开始，但KZN区域有需求，因此自行提出招标，需求产品与EST项目相同。\r\r\n\r\r\n\r\r\n一家制造商只能授权一个投标人。', '', '由代理NYC开立。', '', '本地要求：本地化生产至少达到70%，黑人持股至少占到51%，BBBEE资质要求,CSD& National Treasury注册登记，本地服务支持。\r\n\r\n\r\n其他：供货记录等等。', '', '资料基本可参考EST项目资料。主要难点在于样机制作（DIN V暂时还未开模出来，需要手板制作）；业务将和代理尽量去澄清样机问题（EST项目已提交给ESKOM总部，是否可以不用提供给KZN区域）。', '', '银河授权代理NYC投标。', '', 'ESKOM全程内部决策。', '', 'ESKOM向NYC付款，NYC向银河付款，付款方式参考ESA项目。', '', '良好。NYC方面有中信保支持，对我司信誉极好。', '', '1.在整个ESKOM有超过40万台的供货，在KZN区域提供了几次的培训和技术支持。\r\r\r\n\r\r\r\n\r\r\r\n2. EST项目已参与投标且目前评估结果反馈均良好（未出最终评估结果）。\r\r\r\n\r\r\r\n\r\r\r\n3. 本地化工厂满足本地生产比例，黑人女性100%控股公司等。', '', 'NYC一线关系较好。', '', '主要竞争对手还是兰吉尔（ESA项目NYC与兰吉尔供货）；CONLOG基地在KZN区域，且在5月AUW就发布了针对EST项目的DIN产品，此次招标CONLOG势在必得。', '', '1.在整个ESKOM有超过40万台的供货，在KZN区域提供了几次的培训和技术支持。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n2. EST项目已参与投标且目前评估结果反馈均良好（未出最终评估结果）。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n3. 本地化工厂满足本地生产比例，黑人女性100%控股公司等。\r\n\r\n\r\n银河目前根据NYC反馈，EST评估占据比较好的优势，因此此次KZN区域针对EST项目产品的项目也必须全力争取到；并需紧密结合EST项目的进展。', '', '主要需要技术规格书输出要精准，样机制作要迅速且满足要求。', '此项目即为重要，建议立项并尽快准备样机等工作。', '覃湘君2018-11-02 12:30:01', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('202', '{F35FA3CF-0F65-4779-BA9D-1A30A115698E}', '61', 'INHE-0578', '2018-11-02 13:52:41', '0000-00-00 00:00:00', '2018-11-06 09:39:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110202/ESI', '', 'CORP 4572', '2018-11-29', 'Pre - Qualification of the suppliers for single and three phase single rate meters 单三相单费率电表供应商资格预审', '此项目为标前资质审核招标，主要在于审核产品、资质等，因此未明确招标数量、年限，也未要求提供价格。参考历史ESKOM项目：\r\n\r\n\r\n价格条款：EXW，但报价单要求从EXW到DDP（银河向NYC报价FOB即可）。\r\n\r\n\r\n付款主体：ESKOM\r\n\r\n\r\n付款条件：收到发票后30天内付款（NYC向银河付款，参考ESA项目）\r\n\r\n\r\n交期：按需交货，ESKOM向厂家下达PO，按照要求交货。\r\n\r\n\r\n质保：5年质保', '{F35FA3CF0F654779BA9D1A30A115698E8442F4C2B3234363A3D51C033076BD50}_Pre-qualification CORP4572.pdf', '1.基础资质及文件评估；\r\r\r\r\n2.功能性评估：\r\r\r\r\n* 技术应答、技术资料、风险管控及技术支持 60%，通过后再进行样机测试；且在该阶段评估中将进行投标者现场考察。\r\r\r\r\n* 电表和相关软件（如有）40%，历时2个月。\r\r\r\r\n* 功能性评估达到85%才能进入下一阶段评估。', '', '按照评标规则评估，ESKOM挑选短名单，后期进入合同协商阶段，不一定是得分最高者/价格最低者中标。\r\r\n可以一家或多家中标（倾向于多家分标）。\r\r\n此项目为标前资质审核招标，主要在于审核产品、资质。\r\n\r\n\r\n一家制造商只能授权一个投标人。', '', '暂未要求。', '', '本地化生产至少达到70%，黑人持股至少占到51%，BBBEE资质要求,CSD& National Treasury注册登记，本地服务支持', '', '技术：\r\n1.技术应答表较为详细，需明确应答画册、操作手册、测试报告中对应的内容且有格式要求。\r\n2.需提供详细图纸，图尺寸、安装及爆炸图\r\n3.测试报告要求为ILAC列出的机构出具；且需提供Regulatory Compliance Certificate (RCC) certification证书以证明测试报告适用于南非的情境。\r\n4.需提供生命周期测试报告（Full details of accelerated life-cycle testing (type of tests performed) shall also be submitted with a tender.）。且如果EKSOM判定该报告不足的话，需要根据EKSOM的要求再做一次测试。\r\n5.所有电表在批量发货前都要在SANAS 认证的机构做测试（All meters shall be tested at a South African National Accreditation System (SANAS) accredited test facility.）。\r\n\r\n\r\n商务：\r\n供货记录和用户证明需要按照', '', '银河授权代理NYC投标', '', 'ESKOM内部决策', '', 'ESKOM向NYC付款，NYC向银河付款，付款方式参考ESA项目。【该项目为资格预审，无合同无付款条款。】', '', '良好', '', '1.在整个ESKOM有超过40万台的供货，在KZN区域提供了几次的培训和技术支持。\r\n\r\n\r\n2. EST项目已参与投标且目前评估结果反馈均良好（未出最终评估结果）。\r\n\r\n\r\n3. 本地化工厂满足本地生产比例，黑人女性100%控股公司等。', '', '代理NYC具有较好的客户关系。', '', '主要竞争对手为兰吉尔（有历史供货），CONLOG（在南非市政供货），海兴，科陆（新近投入办公室及建厂等）', '', '1. 有供货基础，有客户关系；\r\n\r\n\r\n2. 此次为资格预审，必须争取有利的技术规格等，并为后续项目打基础。', '', '1. 与代理NYC沟通并澄清有利技术规格；\r\r\n\r\r\n\r\r\n2.技术资料准确及完善；\r\n\r\r\n\r\n\r\n3. 商务沟通等工作。', '重要，建议立项并作为项目组重点项目跟进。', '覃湘君2018-11-02 14:03:45', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('203', '{E1F1011E-27FE-476A-88DE-1320BF06BD15}', '61', 'INHE-0500', '2018-11-02 15:46:31', '0000-00-00 00:00:00', '2018-11-06 10:01:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110203/LLM', '', 'TENDER NO: 48/2018', '2018-11-14', '表号：48/2018，三年框架合同下按照市政公司规定的最低和最高库存数量按需提供 单相和三相预付费智能电表（非双绞线通讯）TENDER NO: 48/2018: TENDER FOR THE SUPPLY AND DELIVERY OF PRE-PAID METERS WITHOUT COMMUNICATION WIRES FOR A THREE (3) YEAR PERIOD ON AN AS AND WHEN REQUIRED BASIS AS DETERMINED BY THE MINIMUM AND MAXIMUM INVENTORY LEVELS OF THE MUNICIPAL STORES.', '价格条款：DDP。银河与NYC之间FOB或CIF成交；\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n付款主体：LESEDI LOCAL MUNICIPALITY；\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，市政在收到付款证明后30天内支付。银河与NYC直接预计采用ESA项目方式结算。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n交期、质保：发货后12个月质保，正式PO下达后不晚于3周内交付。\r\r\r\r\n', '', '第一轮：技术评标，只有满足至少60%的评分才能进入到第二轮商务评标；\r\r\r\r\r\r\n第二轮：商务评标，BBBEE等级，本地化比例和报价比例；\r\r\r\r\r\n第三轮：进入到短名单者需要做样机演示，演示成功后根据前两轮的综合评分确定中标者，未规定一名或多名厂商中标。', '', '规定一名或多名厂商中标。\r\n', '', '无需投标保函，本地公司才有资质投标', '', '电表供货经验五年以上满分，至少三年经验', '', '客服部根据技术需求输出技术规格书，时间较急', '', 'NYC投标，银河做厂商支持', 'N/A', '市政公司组织内部评标委员会（2个来自电力部门，1个来自采购，1个来自财务部门），评标委员会通过预中标名单，然后提交CFO做财务评审签字确认，最终由Municipality Manager签字通过。\r\r\n', '', '交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，市政在收到付款证明后30天内支付。银河与NYC直接预计采用ESA项目方式结算。\r\n', '', '第一次投此市政招标，市政公司的财务能力需要进一步调查', '', 'NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求。\r\nNYC劣势：第一次在次市政投标，无内部客户关系和支持。\r\n', '', '暂无客户关系，需拓展', '', '主要为Conlog和兰吉尔，Common Base电表、兰吉尔Cashpower和conlog双绞线、PLC代码表为主，关于竞争对手的技术问题有待进一步了解', '', '竞争优势：NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求。\r\r\n竞争劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\n策略：样机技术问题的澄清；和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好样机，满足市政公司的技术要求\r\r\n', '', '1.和NYC一起拓展客户内部关系，CFO层面和电力部门技术层面；\r\n2.准备好样机，需要满足市政公司的要求。\r\n', '1.项目组成员：李忠鹏 覃湘君\r\r\n', '李忠鹏2018-11-02 16:29:43', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('204', '{2FB00A87-8BDE-4D5A-856F-43D2C4791267}', '93', 'INHE-0789', '2018-11-02 15:44:50', '0000-00-00 00:00:00', '2018-11-06 09:51:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110204/LCA', '', '4A430/EP/004', '2018-11-26', 'Supply and Delivery of Transformers, Conductors, Pre/Post Payment Meters, Tools and Equipment for Liberia Electricity Corporation 为利比里亚电力公司供应和交付变压器，导体，售前/后付款仪表，工具和设备招标项目', '1. 价格条款：CIP LEC Bushrod Depot United Nations Drive Bushrod Island Monrovia, Liberia. 2. 付款主体：MCA-Libeira 利比里亚千年挑战账户 3. 付款条款：（1）预付款：合同价格的10％应在合同签订后三十（30）天内支付，并在提交可接受的索赔，和等值金额的银行担保函后支付。保函使用招标文件中要求的表格或者其他招标方可接受的表格，担保有效期需超过货物交付日期。（2）装运后：合同价格的40％应在提交装运凭证（提单+保险）后三十（30）天内支付。 （3）交付和验收：合同价格的五十（50）％应在收到货物后三十（30）天内，提交买方出具的货物接收函后支付。 4. 交期：最早交货期是合同生效日期起30天，最迟交货期是合同生效日期起60天内。 5. 质保：质保期目的地接收货物之日起12个月或工厂出货之日起18个月。 6.违约条款：违约金额为合同金额的0.5%每周，最大不超过合同金额的10%。\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n', '{2FB00A878BDE4D5A856F43D2C47912678442F4C2B3234363A3D51C033076BD50}_BD - ELECTRICAL_EQUIPMENT_5 LOTS.pdf', '选择技术应答最相符的情况下价格最好的供应商。', '', '可一家中多个LOT', '', '1. 投标保函： LOT 1变压器金额为$5,000.00,LOT 2电表金额为$3,000.00,利比里亚当地银行开立，有效期是截标日起148天。 2. 履约保函：金额为合同金额的10%，接到中标函之日起14天内开出。', '', '1.	投标人过去5年内必须完成至少一个合同，lot 1变压器的金额125000美金，lot 2电表的金额75000美金。\r\n2.	过去5年内无不履约记录。\r\n', '', '待技术澄清，后续发出分工明细表', '', '待定，代理筛选中', '', '尚不明确', '', '在通过潜在代理核实中', '', '市场调查持续进行中', '', '代理资格筛选中', '', '代理资格筛选中', '', '通过网络搜索和潜在代理做调查', '', '银河在利比里亚市场未供过电气产品，该项目并非电力公司直接招标，我司可借此项目建立良好的客户关系，利于后续电力公司有招标项目更有胜算。', '', '技术应答，样机对中标影响大，需要客服部门尽快完成技术解析，出样机技术规格，尽快完成样机。', '', '林凤兰2018-11-02 17:48:45', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('205', '{829592E0-746F-4544-A4FE-16D880374A62}', '61', 'INHE-0722', '2018-11-02 20:13:12', '0000-00-00 00:00:00', '2018-11-07 18:34:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110205/HRA', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '招标系统为EEH自己的招标系统，政府影响较小', '', '', '', '', '', '', '', '', '', '海兴，当地合作伙伴为Equipos Industriales S.A.de C.V.(洪都拉斯电力行业实力强大的经销商，经销多种电力器材，十标九中)。 EEH2017年开始计划部署智能电表，2018年年初两次电表招标，2月：10万台，3月：17万台，都由海兴中标', '', '优势：1.2018年年底招标还未开始，在招标前电力公司向银河咨询预付费方案说明电力公司内部存在分歧，不愿意海兴一家独大，正式银河向电力公司展示银河的时机。2.根据目前标书及技术规格情况，商务条款和技术条款海兴都未有较多运作，机会较多。                                                                  劣势：海兴已有大批量供货，海兴代理实力强，客户关系比银河强，目前海兴圆表单两三项都有                                                                                                                         策略：                                                              1.据调查，EEH同时也在推广AMI系统。2018年11月7号前向EEH提供银河ANSI表的预付费+AMI方案                                  ', '', '技术：1.2018年11月7日前，提供专业的ANSI表的预付费+AMI方案--客服提供  2.研究技术规格，运作银河ANSI表技术规格--研发提供  3.研究商务要求，运作商务条款--业务负责', 'EEH为银河在洪都拉斯唯一大型用户，拥有180万用户，目前已安装27万台智能电表，市场潜力大，无特殊认证要求，门槛低，供应商单一，机会多。希望公司同意立项！', '冯婷2018-11-02 21:17:38', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('206', '{8CBAF280-5709-463E-B617-A735DC409CBF}', '61', 'INHE-0500', '2018-11-03 03:11:20', '0000-00-00 00:00:00', '2018-11-07 18:40:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110301/NML', '', 'NLM/FIN/OVS/10/2018', '2018-11-09', 'TENDER NUMBER:NLM/FIN/OVS/10/2018:On-line Vending System and Third Party Vending招标号：提供为期三年包含设计、安装、运行、管理和维护等服务为一体的STS售电系统和第三方售电平台托管框架合同。', '报价条款：含VAT报价，兰特币。\r\r\r\r\n银河对NYC报价：按照电表数量或者售电佣金进行报价 \r\r\r\n付款条件：每月度完成当月服务后开具发票后30天内完成付款：本地币。\r\r\r\r\nNYC对银河付款条件：待商谈 \r\r\r\n三年期托管合同，硬件和软件在合同期内由中标者自行承担质保\r\r\r\n', '', '1.基础评估：公司资质、税务等基础资料；\r\r\n2.技术评估\r\r\n3.商务及评标倾向性评估：BBBEE资质，价格等因素。采取80/20分评估标准。\r\r\n', '', '一家中标', '', '无需开立投标保函，中标后30天内需要开立履约保函，由NYC开立', '', 'CSD注册企业，BBBEE证书等级，本地化商业活动证明等；\r\n供货记录：至少三个，五个以上此项评分满分', '', '1.截标日期11月9日（周五），需要软件部协助在11月6日输出技术规格解析文件和协助制作部分应标技术文件，以便在11月6日开始申请报价', '', '代理NYC投标，银河做厂商授权和支持', 'N/A', '1.投标评审由市政公司评标委员会负责（一名ICT系统工程师，一名预付费电表工程师，两名来自财务和采购的成员）；此项评标采购和技术层面各占50%；\r\n2.初审合格后的名单主要由CFO层面根据各方提供的报价方案，做商务评估，给出中标建议；\r\n3.提交中标推荐公司给市政管理委员会签字确认。', '', '每月度完成当月服务后开具发票后30天内完成付款：本地币。\r\r\n中标后，每月度应完成的服务在SLA服务协议里面做进一步说明。一般主要包含直接售电点的报表相关工作整理和输出，第三方售电收入转入到市政公司的账户和相关报表凭证整理和输出，以及其他有关月度收入和故障处理的事项凭证。', '', '市政公司的财务能力和收入能力有待进一步了解', '', 'NYC优势：BBBEE资质10分偏好优势；ESA项目的执行积累了一定的财力和实力，可以提供更优的融资方案；\r\r\r\r\nNYC劣势：第一次在次市政投标，无内部客户关系和支持。', '', '第一次在次市政投标，暂无内部客户关系和支持，需要开拓技术层面和CFO等核心层面的客户关系						\r\r\r\n', '', '暂无此市政公司当前使用系统和电表供应商的信息，待进一步了解						\r\r\n', '', '竞争优势：NYC优势：BBBEE资质10分偏好优势；ESA项目积累了一定的财力和实力，可以提供更优的融资方案；银河售电系统的供货记录和经验。\r\r\r\n竞争劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\r\n策略：和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；提前准备好系统的测试工作，满足市政公司的技术要求\r\r\r\n', '', '1.截标日期11月9日（周五），需要软件部协助在11月6日输出技术规格解析文件和协助制作部分应标技术文件，以便在11月6日开始申请报价						\r\n', '项目组成员：覃湘君 李忠鹏 刘佩', '李忠鹏2018-11-03 03:36:18', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('207', '{40065491-2515-4E23-82C6-8569D29D2C99}', '61', 'INHE-0725', '2018-11-06 08:59:28', '0000-00-00 00:00:00', '2018-11-07 18:14:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110603/EKO', '', 'EKEDP/MAP/001/2018', '2018-11-19', 'Procurement of Meter Asset Provider Services针对电表供应商发起的电表及服务招标项目', '付款条件：该项目为融资项目，招标方付款方式为无预付款，后续电表安装后用户上缴电费而后按月支付，代理中标后会在当地银行抵押合同获取融资作为我方生产资金，我方作为供应商为其提供电表并与供应商签订合同', '', '先技术后商务，招标方会首先查看保函，而后在当地时间11月19日下午2点进行技术评标，技术得分满分100分，大于或等于70分的投标方进入第二阶段商务评标；商务评标评审价格，价格低者为优，预计一家中标', '{4006549125154E2382C68569D29D2C99074E749A304748709C51373D9D483750}_评标规则.png', '1个lot，预计一家中标', '', '我方本次为供应商，无需开立保函', '', '投标方需具备NG市场NERC(尼日利亚电力管理委员会）颁发的“No Objection”证书以证明他们符合今年四月份尼日利亚政府颁布的“MAP Regulation”的相关要求，目前尼日利亚已有95家公司已获得“No Objection”证书，具备该资质。但其他公司可以通过联合投标或是成为供应商的形式参与进来。', '{4006549125154E2382C68569D29D2C9903404677E4D44E9EB56B3D512B2AF9CC}_MAP客户档案信息汇总_20181027.xlsx', '需要客服部协助评估技术要求，此外需要商务部门协助整理审核我方提供的资料', '', '代理投标', '代理投标', '客户告知评标将由EKO电力公司内部进行，EKO在决策中扮演重要角色', '', '客户付款流程：该项目为融资项目，招标方付款方式为无预付款，后续电表安装后用户上缴电费而后按月支付，代理中标后会在当地银行抵押合同获取融资作为我方生产资金，我方作为供应商为其提供电表并与供应商签订合同', '', '客户采取在当地银行融资手段支付我方货款，后续与客户具体洽谈付款细节，如我方代理中标，招标方会提供正式的保证文件（Bank Guarantee)', '', '代理对于整个投标项目很有规划 ，之前也与IRL客户就Ibadan及Kaduna电力公司展开了合作，对于处理客户关系较为擅长，而且提出融资方案（中标签订合同后从当地银行获取投资），同时该客户与招标方关系密切，与招标方的Mr Adeoye(Technical Director)较为熟识。', '', 'IRL为我方老客户，之前多次进行订单及项目合作，我方与客户关系较好，客户对于操作融资项目，处理客户关系也有一定经验，尤其是与本次投标项目的招标方关系较好，后续客户也会继续运作，推动代理EKO拓宽客户关系，发展评标内线。', '', 'NG市场的NERC(尼日利亚电力管理委员会）在今年将“No Objection”证书颁发给当地的95家电表供应商，证明其资质，目前NG市场的MAP投标项目只针对这95家公司开放，但其他公司可以通过联合投标或者以供应商的形式参与进来，代理告知本次竞争对手主要有Cresthill(在本地采购电表），Mojec, Saburd等公司。', '', '双方之前多次进行订单及项目合作，针对当地MAP招标项目已经就Ibadan及Kaduna电力公司展开了合作，合作经验丰富；代理与招标方的Mr Adeoye(Technical Director)建立了联系，目前暂无评标内线，业务后续需推动代理尽快拓宽客户关系；代理对于融资项目以及客户关系处理也有一定的经验；代理融资同时也极大减轻了我方的风险。虽然该投标项目的时间较为紧张，但凭借代理的运作，以及我方积极配合，我方就会占据巨大优势。', '', '该投标项目时间较为紧张，客户在当地开保函极大节约了时间，只要后续我方做好相关文件准备，加上代理运作，中标可能性很大；需要公司支持以加快相关文件准备速度，同时保证文件质量；本次招标项目技术规格较为详细，需客服部协助解析，推荐适合表型。', '该项目有以下几点优势：1.代理与招标方关系良好，可通过运作提高中标可能性；2.代理自行提出融资方案并对于融资项目有一定的经验，对于整个项目有规划，同时代理融资也大大降低了我方的资金风险；3.代理可在当地开立保函，节约了大量时间，只要后续文件准备充分，公司便可抢占先机；4.之前也与IRL客户就Ibadan及Kaduna电力公司展开了合作，双方合作经验丰富，并且IRL客户对于发展客户关系经验丰富，参与该项目竞争有利于我方占据更多市场份额，结合以上优势，希望公司予以支持，谢谢！', '赵政洁2018-11-06 11:26:20', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('208', '{BEF546BA-B87C-48B4-8A96-8D413120BC6C}', '61', 'INHE-0722', '2018-11-12 14:02:18', '0000-00-00 00:00:00', '2018-11-14 16:50:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111201/ENB', '', '', null, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'TELEFONICA提出的合作步骤：1.先签署NDA保密协议   2.购买样机进行测试（西班牙进行测试）  3.银河提供NB-IOT项目报价   4.在智利进行试点项目                                                目前TELEFONICA已发送NDA协议，等待银河进行审核签署。签署NDA之后再告诉银河项目信息。Telefonica是世界大型的电信公司之一，实力雄厚，在拉美地区有广泛的业务，是很好的合作伙伴，此次智利试点项目可为银河争取接下来的10万台NB-IOT项目，并与telefonica将业务扩展至拉美其他国家。', '冯婷2018-11-12 17:12:38', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('209', '{80373372-DF2B-4EEF-9DD9-737F430F0292}', '61', 'INHE-0578', '2018-11-13 13:37:12', '0000-00-00 00:00:00', '2018-11-16 11:03:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111301/STM', '', 'B/SM 28/19', '2018-12-14', 'APPOINTING OF EXPERIENCED SERVICE PROVIDER TO READ METERS REMOTELY, VIA AUTOMATED METER READING (AMR) SYSTEM AND MANAGE METERING SERVICES FOR LARGE POWER USERS AND SMALL SCALE EMBEDDED GENERATION CONSUMERS.指定有经验的服务供应商通过自动抄表（AMR）系统远程抄表，并为大用户和小规模嵌入式发电用户提供管理、抄表服务。', '价格条款：托管型项目，按月收费；按每台表每月费用收费。\r\r\r\r\r\r\r\r\n付款主体：电力公司（资金来源与电力公司及国家财务部）。\r\r\r\r\r\r\r\r\n付款条件：电力公司收到有效发票后30天内支付本地币。\r\r\r\n交期：未明确。\r\n质保和违约：发货后18个月质保。', '', '两步评估：\r\r\r\n技术和资质文件符合要求进入下一步评分；\r\r\r\r\n价格评分（80%）+BBBEE（20%）', '', '一家中标，三年期框架协议。', '', '无需开立保函，若需开立由代理NYC开立', '', '1.投标公司财报（本地代理NYC）\r\r\n2.历史AMR系统项目执行至少需要3个，并需提供用户证明；\r\r\n3.对项目实施人员资质也有具体要求（项目经理，电表专员，系统软件工程师等等）\r\n4. 要求有本地至少2名专员随时提供协助。', '', '需根据解析情况提供对应项目技术方案--软件部/技术支持；', '', '银河授权本地代理NYC投标', '', '电力公司内部决策', '', '银河与代理之间结算；电力公司与代理之间：每月收到发票后30天内支付本地币。', '', '较好。', '', '此项目处于西开普敦省，属于农业地区，较为偏远。目前暂无客户关系。计划与代理在11.20日强制性标前会议时在本地进行一定的现场考察，收集更多资料。', '', '暂无客户关系。', '', '此项目处于西开普敦省，属于农业地区，较为偏远；人口约为16万，家庭数量约为4.5万~5万户。标书中明确列明中压、低压用户数量。此项目处于西开普敦省，属于农业地区，较为偏远。目前暂无客户关系。计划与代理在11.20日强制性标前会议时在本地进行一定的现场考察，收集更多资料。	\r\r\n					\r\r\r\n预计主要难点在于更多现场信息的收集，以及细化的报价；此前与代理均未在该市场进行过软件类项目，尤其是此类完全托管的项目，系统方案、报价方面难度都比较大。', '', '\r\r\r\r\n预计主要难点在于更多现场信息的收集，以及细化的报价；此前与代理均未在该市场进行过软件类项目，尤其是此类完全托管的项目，系统方案、报价方面难度都比较大。但是，目前项目组需要尽力抓住每一个软件类及系统类的项目，争取尽早在该市场实现软件类销售的突破。托管类项目一旦做成，市场情况、项目情况、收益都是对以后发展极为有利的。						\r\r\r\r\n', '', '技术规格较为宽泛，需要沟通的较多；且需根据解析提供完善的系统技术方案。投标资料需要按照标书具体要求妥善准备。需要现场人员与代理配合尽量在标前会议时沟通解析提出的问题并进行适当现场考察并反馈情况。', '建议立项。李忠鹏/刘佩作为现场对接投标组长，刘博主要负责投标任务，覃湘君做商务方面协助。', '覃湘君2018-11-13 14:32:40', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('210', '{B3D20EB8-8B5B-43E9-BB8A-BEB1F10F8516}', '61', 'INHE-0500', '2018-11-13 14:17:06', '0000-00-00 00:00:00', '2018-11-16 10:36:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111302/EMF', '', '11/2019/22', '2018-12-04', 'Request for Proposal for the Provision and Administration of an electricity Prepaid Vending System of Emfuleni Local Municipality for a period of Thirty Six（36）MonthsRFQ：三年期框架性供应合同，安装、运行和托管维护全套STS售电系统，含市政公司直属售电网络和平台，第三方售电网络和平台，以及和市政公司现有Billing系统、财务管理系统等兼容服务', '价格条款：DDP\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\n付款主体：Emfuleni Local Municipality 市政\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\n付款条件：中标后按照标书要求和南非市政标准服务合同（GCC和SGC条款），协商签订SLA（软件服务协议），市政公司在每月底收到服务商提交的月度服务验收完后的发票后。30天内付款。\r\r\r\r\r\n\r\r\r\r\r\n交期：90天内完后全部的售电系统安装、调试、接口、运行等工作；\r\r\r\r\r\r\n\r\r\r\r\r\n质保和违约：售电系统的硬件设备由中标者自行提供和维护，不存在质保期。软件方面需要和市政公司签订SLA协议（软件服务协议），具体的质保和服务需要协商确定。\r\r\r\r\r\n\r\r\r\r\r\n', '', '分为3个阶段评估：\r\r\n第一阶段：基础商务资料预审(公司注册信息，税务证明，审计财务证明，市政公司标准表格资质证明文件）；\r\r\n第二阶段：技术评审，按照标书的标准表格，至少满足60%的评分才可进入第三轮评审；\r\n第三阶段：BBBEE资质和价格评审（按照90/10的比例分批）', '', '一家中标', '', '投标无需开立保函，中标后需要开履约保函，保函由代理NYC开立', '', '必须在南非本地注册CSD企业才可投标，需要提供近期三年的财务审计报告，需要至少提供三个售电系统的用户证明', '', '需要客服部和软件部协助提供：全套软件的实施方案+项目实施进度表+硬件方面的配置推荐', '', 'NYC投标，银河做OEM支持', 'N/A', '市政公司内部评标委员会做评审和初步决议（此评审委员会主要以采购和技术部为主），最终授标决议由市政CFO决议，CFO为核心关键人物', '', '中标后按照标书要求和南非市政标准服务合同（GCC和SGC条款），协商签订SLA（软件服务协议），市政公司在每月底收到服务商提交的月度服务验收完后的发票后。30天内付款。\r', '', '市政公司月度电费收入：25,000,000 R以上不含VAT，其余的财务信息需要进一步的调查和了解', '', '代理NYC满足商务方面的所有投标资质，技术层面银河的售电系统基本满足绝大部分要求，劣势在于第一投标此市政，NYC无客户基础\r\r\r\n', '', '暂无客户关系', '', '当前此市政公司的售电系统为：Syntel公司的售电系统，另外LPU AMR系统为兰吉尔所供，Syntel和兰吉尔初步推测在次市政公司有较强的客户关系，另外Actom、Cigicell、Ontec、海兴，为当前项目的主要竞争对手', '', '优势：NYC本地化的资质，BBBEE资质满分，一定的融资实力；银河方面供货资质和技术规格基本满分。\r\n劣势：市政公司无客户关系；市政公司的主要问题和需求了解不足；竞争对手的当前进展、客户关系和其他问题了解信息不够。', '', '1.客户关系拓展；\r\n2.提交具有竞争力的技术方案和报价；', '此项目需要申请商务支持，协助投标资料制作', '李忠鹏2018-11-13 14:56:42', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('211', '{84C7CD61-DB2D-4AD5-9CA1-A4C21B3D3517}', '61', 'INHE-0793', '2018-12-14 14:12:06', '0000-00-00 00:00:00', '2018-12-25 20:52:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111303/SEP', '请业务深入了解合作方情况，调研市场晶振个特点和合作方市场竞争策略。不建议盲目推进。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '政府决策对其无影响', '', '发货前100%即期不可撤销L/C.', '', '客户财报为：目前总资产47万人民币，负债12万人民币，上一年度利润8万人民币，现金流结余5.6万人民币.然后其可借贷款项可达100万人民币以上（其亲属处）。', '', '该客户在印度本土社交网络较好，与多家电力公司均有联系，代理主站团队经验丰富（其2012年进入电表行业，业已有6年经验)，老板性格好，配合度高，能力目前无法判断，公司经济实力中等（其目前总资产47万人民币），该公司无政治实力，其内部关系据其反馈较为融洽。', '', '目前关系程度为B（合作意向较浓可成功概率高），与其负责人沟通融洽。', '', '目前该客户主要采购印度本土一家名为Crystal品牌的电表，这家电表公司是典型的小作坊(无自身品牌网页),据客户反馈，这家电表厂只有不到80人的规模，生产产品只有两种：单相和三相BS安装一体式智能电表，并无解决方案可以提供。其产品价格较低廉，产品类型单一，和电力公司没有从属关系，市场规模只局限在新德里和周边地区。', '', '银河成功供应这一万台电表及争取该客户所有订单的希望很大，但是因为印度市场价格普遍低下，而且该客户规模也有限，所以可获利润会比较小。但是也不失为新市场立足的一个起点。优势：容易成单，可以初步打下立足点。劣势：利润小，风险略高（可人为控制）。做法：积极跟进，做完相关认证，即可发货成单。附客户与其本地厂商的供货记录', '{84C7CD61DB2D4AD59CA1A4C21B3D3517B79221563C224206B274FD7CD6B16366}_Detail of Projects-31-10-2018.xlsx', '该项目成功关键在于适当让利（印度市场经济比较低迷，中间商也多，很难卖出高价），需要的支持：公司样机和价格支持。', '印度市场和中国市场的显著特点都是电表用量极大，为了给公司创造更大的利润，个人觉得可以先从一些小的经销商处打开缺口，楔进一个起点，而后再和大的电力公司取得直接联系，处理投标等大项目。目前这个经销商的合作意愿较为浓厚，虽然需求量不是很大，却也不失为作为基础的可能，以便进行联合投标。故而恳请领导批准，以便尽快送样机给客户进行相关认证，以便我司产品更快更好的进入印度市场。', '辛方腾2018-12-14 18:14:13', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('212', '{1F015999-AEE3-4F6E-B41F-51BB20E0390B}', '61', 'INHE-0500', '2018-11-13 15:19:50', '0000-00-00 00:00:00', '2018-11-15 09:07:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111304/EDU', '', 'EDUMT18/2018/19', '2018-11-20', 'Electricity Vending Service for 3-Year Period三年期框架性供应合同，安装、运行和托管维护全套STS售电系统，含市政公司直属售电网络和平台，第三方售电网络和平台，以及和市政公司现有Billing系统、财务管理系统等兼容服务', '价格条款：DDP\r\r\n\r\r\n付款主体：eDumbe Local Municipality市政\r\r\n\r\r\n付款条件：中标后按照标书要求和南非市政标准服务合同（GCC和SGC条款），协商签订SLA（软件服务协议），市政公司在每月底收到服务商提交的月度服务验收完后的发票后。30天内付款。\r\r\n\r\r\n交期：90天内完后全部的售电系统安装、调试、接口、运行等工作；\r\r\n\r\r\n质保和违约：售电系统的硬件设备由中标者自行提供和维护，不存在质保期。软件方面需要和市政公司签订SLA协议（软件服务协议），具体的质保和服务需要协商确定。\r\r\n', '', '分为3个阶段评估：\r\r\r\r\n第一阶段：基础商务资料预审(公司注册信息，税务证明，审计财务证明，市政公司标准表格资质证明文件）；\r\r\r\r\n第二阶段：技术评审，按照标书的标准表格，至少满足45%的评分才可进入第三轮评审；\r\r\r\r\n第三阶段：BBBEE资质和价格评审（按照90/10的比例分批）\r\r\r\r\n', '', '一家中标', '', '投标无需开立保函，中标后需要开履约保函，保函由代理NYC开立\r\n', '', '必须在南非本地注册CSD企业才可投标，需要提供近期三年的财务审计报告，需要至少提供三个售电系统的用户证明\r\n', '', '需要客服部和软件部协助提供：全套软件的实施方案+项目实施进度表+硬件方面的配置推荐\r\n', '', 'NYC投标，银河做OEM支持\r\n', 'N/A', '市政公司内部评标委员会做评审和初步决议（此评审委员会主要以采购和技术部为主），最终授标决议由市政CFO决议，CFO为核心关键人物\r\n', '', '中标后按照标书要求和南非市政标准服务合同（GCC和SGC条款），协商签订SLA（软件服务协议），市政公司在每月底收到服务商提交的月度服务验收完后的发票后。30天内付款。\r\n', '', '待跟进调查', '', '代理NYC满足商务方面的所有投标资质，技术层面银河的售电系统基本满足绝大部分要求，劣势在于第一投标此市政，NYC无客户基础\r\n', '', '暂无客户关系\r\n', '', '当前此市政公司使用的是海兴的售电系统，按照海兴的售电系统报价策略，预计对于价格要求相对较低，海兴的代理有待进一步跟进了解', '', '优势：NYC本地化的资质，BBBEE资质满分，一定的融资实力；银河方面供货资质和技术规格基本满分。\r\n劣势：市政公司无客户关系；市政公司的主要问题和需求了解不足；竞争对手的当前进展、客户关系和其他问题了解信息不够。\r\n', '', '1.客户关系拓展；\r\n2.提交具有竞争力的技术方案和报价；\r\n', '此项目需要申请商务支持，协助投标资料制作', '李忠鹏2018-11-13 15:35:21', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('213', '{6A0B2A29-61F2-405B-94A8-1DD9492BE3CD}', '61', 'INHE-0593', '2018-11-13 16:54:24', '0000-00-00 00:00:00', '2018-11-16 10:47:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111305/SBA', '', 'N°133/18/SBEE/DG/PRMP/DPGS du 31/10/2018', '2018-12-18', 'SBEE采购电气设备招投标', '交期：\r\r\n合同签订后的6-7个月\r\r\r\r\n超过最迟交期后每周罚款合同总金额的0.5%\r\r\r\r\n当罚款金额达到5%时取消订单\r\r\r\n\r\r\r\n标书要求DDP SBEE电力公司仓库 Cotonou (Bénin)\r\r\n\r备注：我司与代理结算可按照CIF cotonou（Beni\r\r\r\n\r\r\n预付款：合同签订后收到等额的买方认可的履约保函后60天内付款合同总金额30%，TT支付\r\r\r\r\n初步验收后：产品交付后，在收到验货报告，合同复印件及相应的发票后，电力公司通过TT支付65%的款项\r\r\r\r\n终极验收后：收货后一年（一般是质保期过后），电力公司会对电表进行最终验收，收到最终验收函，合同复印件及相应的发票后，电力公司通过TT支付5%的款项\r\r\r\r\n', '', '1. 要符合招标文件的要求；\r\n2.价格最低者中标\r\n', '', '一个投标商可以投多个lot，但是只能中一个lot', '', 'Lot1/Lot4:各20 000 000FCFA\r\nLot2/Lot3：各30 000 000FCFA\r\n截标日后90天有效\r\n', '', '一般要求', '', '断路器需要我司供货商提供厂家授权，授权代理公司投标', '', '代理商投标，银河作为供货商', '非联合投标', 'SBEE为国企，政府意志对SBEE决定影响大。', '', 'BN电力公司付款需要内部层层审核；代理付款较为容易', '', '此次招标资金为贝宁电力公司自有预算\r\r\r\n\r\r\r\n\r\r\r\n银河与代理结算，代理财务状况较为稳定					\r\r\r\n						\r\r\n', '', '该国为代理老家，尽管如此，代理多次表示该国一切都不正常，电力公司更是无赖。但是代理还是对该国项目十分上心，积极参与投标竞争。', '', '银河目前暂无人前往过该国运作项目及接触电力公司。', '', '该国有较多中国厂商涉足，已知海兴，科陆在该市场均供过货，最近的中标商为longi，竞争较为激烈。', '', '支持代理用两家公司投标，增加中标率；', '', '强有力的客户关系；投标文件及样机及时交付。', '支持立项，BN市场要拿到订单。', '胡蝶2018-11-14 09:02:20', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('214', '{7DF86CB6-450E-44CC-BF5C-2D7BCFEC2BAB}', '61', 'INHE-0772', '2018-11-19 16:28:59', '0000-00-00 00:00:00', '2018-11-23 10:42:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111901/SBS', '请补充项目本身信息，如截标时间，允许几家中标等', 'EDSA/AfDB/DIST/ICB/02/REH/09/18', '2018/11/29', 'Rehabilitation and Extension of Bo/Kenema Distribution System', '代理中标后，跟银河采购。采购合同与代理谈判', '', '符合技术标准的最低价中标', '', '投标人不允许围标，但不限制制造商授权投标人', '', '20万美金，代理出保函', '', '代理用自己的资质', '', '', '', '代理投标', '', '中标后，代理需对电力公司，能源部分利', '', '中标结果提交到非洲发展银行审核，非发行授权银行放款支付给投标人', '', '本项目是塞拉利昂向非洲发展银行的贷款。', '', '合作代理是山钢集团当地运作团队的总经理，目前有修桥修路的项目在执行。', '', '一线是代理在运作', '', '当前据介绍：竞争对手是塞内加尔（海兴），一家英国公司和conlog。', '', '劣势：标前无运作，得知消息比较晚，代理对电表不专业。 优势：代理关系较好，银河的专业程度。代理财力优，可以自行解决保函。', '', '提供技术资料、样机制作和授权资料。', '代理当地关系较好，希望银河支持授权他投标，自能解决保函事宜。代理承诺中标后向银河采购。我司向代理及时提供技术资料，样机和授权即可。 请公司支持！', '张子琦2018-11-20 17:21:34', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('215', '{1BF56867-1D8F-4263-A63D-130ACC9448B7}', '60', 'INHE-0088', '2018-11-20 10:15:30', '0000-00-00 00:00:00', '2018-11-23 10:52:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112001/EDS', '', '', '', '', '', '', '价格、技术规格、技术方案', '', '', '', '', '', '', '', '', '', '代理直采', '', '价格、技术规格、技术方案；电力公司资金准备', '', '', '', '', '', 'Electricaldealer为私人企业，成立于2000年，员工约20人，在洪都拉斯从事电力设计，电气自动化系统，交钥匙工程，采购原材料交付给建筑公司。David此前是施耐德员工。8年前开始接触绿色能源（太阳能、风能、地热等）表计电力设计项目，与国家电力公司ENEE内部技术及商务人员有联系，与洪都拉斯另一1.8万用户私人电力公司RECO也有联系。', '', '我司洪都拉斯目前客户情况：\r\r\r\nA.FU05客户：UTILA私人电力公司，已供货PLC预付费代码表（FM2S圆表及DIN单相3线表）\r\r\r\nB.IAGSA，ENEE收费系统公司，希望进行代理合作\r\r\r\nC.LR-GROUP，以色列公司，原定已与ENEE签订合同，后因国会否决未落实项目\r\r\r\nD.Electrical dealer，私人企业，希望进行代理合作', '', '电力公司使用系统：\r\r\r\r\nElster-Energyaxis；Landys-Comand center\r\r\r\r\n当地私人直接采购项目市场价格：GE单相FM2S CL320多功能表USD260，三相16S USD270,LEVITON 单相200A GPRS多功能表USD590，NEXUS 三相9S GPRS多功能表USD965，\r\r\r\r\n一般投标价格：普通圆表单相表价格将接近15-18美金。整机散件关税：15%\r\r\r\n普通表主要竞争对手为中国厂家：海兴/威胜', '', '价格和方案优势', '', '技术支持、样机、方案、价格', '1. 项目代号：EDS；\r\r\r\r\r\r\r\r\r\r\r\r\r\n2. 多年来洪都拉斯市场国家电力公司都因经营不善、电力不足长期停电、采购停滞，经过私有化改造后开始投入圆表采购，目前主要是普通圆表，现希望通过预付费系统和电表采购以解决欠费及窃电问题；\r\r\r\r\r\r\r\r\r\r\n3. 11月20日当地上午10点，代理将与电力公司技术部门会议并演示我司产品方案，确认最终技术规格要求，需要我司准备样机4台，代理愿意购买样机，负责预付费系统演示；\r\r\r\r\r\n\r4. 当地电力公司资金支付能力较不稳定，建议通过经销商合作。\r\r\r\r同时普通表的招标采购经常因价格竞争及无法提供其他表型无法参与（FM16S/12S），如能将我司预付费系统和电表运作进电力公司，是较好的市场突破机会。\r\r\n需要申请收费样机，因此须申请立项，技术规格将由代理与电力公司确认。', '余冬纯2018-11-20 11:25:40', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('216', '{572E23A8-D281-4BEA-A5A3-66BFD61ED457}', '97', 'INHE-0549', '2018-11-20 14:01:04', '0000-00-00 00:00:00', '2018-11-27 09:24:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112002/PCB', '', 'AOI-02/CGP/PEPERN/18、AOI-03/CGP/PEPERN/18、AOI-04/CGP/PEPERN/18', '20181212', '农村，城郊和城市电气化项目（PEPERN），包括三个招标：Extension, densification et Renforcement des réseaux de distribution（扩大，密集和加强配电网）、Construction des lignes de liaison HTA et Electrification Rurale（高压输电线路建设与农村电气化）和Création d’un poste de répartition HTA/HTA Niamey EST（建设尼亚美东部调度站）。', '尼日尔农村，城郊和城市电气化项目（PEPERN）预算总额约为七千万美元其中由非洲发展基金提供2,030万美元贷款并拨款3960万美元，由尼日利亚信托基金提供的超过一千万美元的贷款。20%预付款（要有相同金额的银行担保），每月分期付款以及尾款。对于那个配电线的项目：60％放在工地库存价值将在出示证明文件后付给承包商。对于每个标：每个批次的执行期限为14个月，如果单个投标者获得多个批次，则不能合并这些期限。', '', '每个标的评标将按批次进行。将按照客户最有利的组合授标（分批次或批次组合）。将授标给有能力执行合同且价格最低者。', '', '每个标的评标将按批次进行。将按照客户最有利的组合授标（分批或批次组合）。', '', '投标保函：第一个标三个批次一共约20万美元；第二个标四个批次一共约30万美元；第三个标约10万美元。履约保函和质保金都是合同金额的5%。履约保函在最终验收28天后释放，质保金在临时验收时释放一半，在最终验收时可换成保函。', '', '建筑活动的最低平均年营业额约为2964万美元，相当于在过去三年内正在进行或已完成的合同所收到的法定付款总额。投标人必须证明其可以获得约486万美元融资。近五年内作为承包商，分包商或主承包商的建筑合同经验。在过去五年内作为承包商，分包商或主承包商已经完成或基本完成至少两份最低价值为1151万美元的建筑合同且至少有建设调度站，地下和空中配电线路的建筑经验。项目主要负责人要有至少两个类似项目的经验并且会说法语。投标人要有30个低压展开滑轮、30个高压展开滑轮、7个放线车和50个地下电缆牵引辊。', '', '裸露和绝缘高压和低压电缆、高压和低压设备、支撑（电线杆）、配电变压器、空气开关、DHP、开关单元#FE54`TUR、高压绝缘子及其配件的厂家授权。', '', '联合投标', '项目涉及现场施工，且我们有些资质（项目主要负责人员都要会说法语）不符合标书要求，而KAMA有丰富的EPC项目经验并且有会说法语的项目负责人员。', '无国家或地区优惠。', '', '项目经理按照项目进度提出申请，业主按照贷款协议让银行付款。', '', '非洲开发银行总干事和尼日利亚共和国驻科特迪瓦大使于2017年3月10日签署了贷款和捐赠协议。', '', 'KAMA经验丰富，总经理人很好，内部团队融洽。', '', '尼日尔代理和本项目负责人关系很好，只要我们的价格有优势且资料做得好，有把握让我们中标。', '', '竞争对手主要是国际工程公司。', '', '银河去年在尼日尔投过两个预付费电表的标，都没有中标，而且尼日尔是内陆国家，运输成本高也是一大劣势。本项目预计使46000家庭受益，如果中标将有利于银河更加了解尼日尔及尼日尔电力公司，从而扩展尼日尔业务。', '', '关键在于投标文件的准备和报价策略，有可能的话最好出差去尼日尔见见电力公司的高层，做做品牌和产品推广。', '该项目是非洲发展基金和尼日利亚信托基金融资项目，总体目标是提高尼日尔八个地区人口的电力供应率。由于涉及施工且有些资质不符合要求，我们打算和KAMA公司合作，银河做主投标人，具体分工中标之后分配。根据配电部的技术解析，我们能提供变压器、SF6开关柜、负荷开关、低压断路器箱和低压配电盘。尼日尔每年有几百台变压器的采购需求，如果中标有利于我们在该市场开拓业务。', '王秀明2018-11-22 10:14:07', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('217', '{17212410-E9F7-4A34-93F6-C43EF8D4F55E}', '61', 'INHE-0578', '2018-11-21 09:28:42', '0000-00-00 00:00:00', '2018-11-23 11:03:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112101/ESB', '', 'PTATEN 2438', '2018年12月13日', 'Supply of Split Meters for a period of 6 months (Limpopo, Mpumalanha and Gauteng)6个月分体式电表供货（林波波，姆普马兰加，豪登省三省）', '价格条款：EXW，但报价单要求从EXW到DDP（银河向NYC报价FOB即可）。付款主体：ESKOM付款条件：收到发票后30天内付款（NYC向银河付款，参考ESA项目）交期：按需交货，ESKOM向厂家下达PO，按照要求交货。质保：5年质保', '', '4个过程：1.基本要求评估（样机尺寸，基本资料等）；2.强制投标资料评估；3. 预审资质评估；4. 本地化比例评估（70%）；5. 功能性评估（按要求测试样机）；6. 财务评估；7. 价格及倾向性评估8. 客观评估', '', '按照评标规则评估，ESKOM挑选短名单，后期进入合同协商阶段，不一定是得分最高者/价格最低者中标。可以一家或多家中标。', '', '无要求，若需则由代理NYC开立。', '', '本地要求：本地化生产至少达到70%，黑人持股至少占到51%，BBBEE资质要求,CSD& National Treasury注册登记，本地服务支持。其他：供货记录等等。', '', '基本可参考ESK项目制作。同样产品，同样要求，不同大区招标。', '', '银河授权代理NYC投标。', '', '大区内部决策。', '', 'ESKOM向NYC付款，NYC向银河付款，付款方式参考ESA项目', '', '良好。NYC方面有中信保支持，对我司信誉极好。\r\n', '', '1.在整个ESKOM有超过40万台的供货，此次招标的三个大区均有较多供货记录且反响较好。\r\r\n\r\r\n\r\r\n2. EST项目已参与投标且目前评估结果反馈均良好（未出最终评估结果）。\r\r\n\r\r\n\r\r\n3. 本地化工厂满足本地生产比例，黑人女性100%控股公司等。', '', 'NYC一线关系较好。', '', '主要竞争对手还是兰吉尔（ESA项目NYC与兰吉尔供货）；CONLOG基地在KZN区域，且在5月AUW就发布了针对EST项目的DIN产品，预计CONLOIG会发力争取。', '', '处于较好的竞争态势，不过兰吉尔和CONLOG已发布了成熟的DIN产品。', '', '需按时提交样机（同EST项目）。\r\n虽然招标方属于ESKOM管辖，但ESKOM今年已逐步分散管理，尤其是几个大省，财务状况甚至比本部要好一些，因此在目前EST项目本部未开始采购的情况下，各大区自行发起招标。已多次与代理NYC沟通，经过多方交涉，针对各大区招标必须要按要求提供样机，不要依赖总部；如此多方争取对我们更为有利。', '建议立项并立即开始翻单样机制作，争取在12.10日完成样机验收由客户带走。', '覃湘君2018-11-21 11:28:31', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('218', '{7C334070-102A-48A2-B898-6F0D5CD95569}', '61', 'INHE-0713', '2018-11-22 14:43:43', '0000-00-00 00:00:00', '2018-11-28 10:03:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112201/GEB', '', '尚未发标', '未明确', '暂无', '暂无', '', '暂无', '', '暂无', '', '暂无', '', '暂无', '', '暂无', '', '预计，银河作为供货商，授权代理投标', '暂无', '项目资金来源：非洲发展基金的980万美元赠款和1130万美元贷款以及非洲开发银行集团的过渡支助基金提供的700万美元贷款\r\r\n\r\r\n政府政治对决策影响不大', '', '预计，与代理沟通付款方式为：20% TT生产前预付，80%L/C出货前', '', '电力公司项目资金来源：非洲发展基金的980万美元赠款和1130万美元贷款以及非洲开发银行集团的过渡支助基金提供的700万美元贷款\r\r\n\r\n\r\n代理目前财务状况良好', '', '电力公司在今年7月份来中国进行GS01验货，验货团队对于银河评价较好，GS01供货产品已到电力公司，将计划下一步装表以及软件实施。\r\n\r\n\r\n代理与电力公司有较强关系，此项目代理从9月份就和银河商量运作技术规格，与银河与电力公司关系融洽。', '', '项目负责人对于银河较为满意，且此项目负责人与GS01项目负责人为同一人，此人在GS01验货期间对银河印象好。\r\n\r\n\r\n代理与项目负责人以及电力公司内部有较好的关系。', '', '对手：此前GS01项目因为运作过内置断路器电表，排除了国内竞争对手，如科陆海兴。但现有消息，海兴也在积极运作此市场，相比海兴也对此款产品有所准备。\r\n\r\n目前银河为此市场唯一中国供货厂家，银河代理与电力公司关系良好。此前，此市场的表与系统皆为Itron产品。', '', '状态和形式：代理与银河从8月份就开始密切关注此标发标情况，积极对此标的客户关系以及技术规格进行运作，多次讨论应该运作哪一款表型。\r\r\n\r\r\n\r\r\n目前计划精细再次运作GS01技术规格，排除不必要的中国竞争对手，但同时搜集更多海兴等潜在竞争对手的信息。', '', '1.技术规格运作，需要客服部技术支持根据GS01项目产品细节，进一步完善此次项目技术规格运作。\r\r\n\r\r\r\n2.开标后可能需要实验室提供样机支持 \r\r\n\r\r\n3.投标过程中可能需要的商务支持', '暂无', '苏宏2018-11-23 08:42:54', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('220', '{6777B521-1415-4729-A255-FF714C2FE17B}', '60', 'INHE-0601', '2018-11-23 10:48:36', '0000-00-00 00:00:00', '2018-11-27 08:56:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112302/PTM', '', '暂无', '', '泰国PEA Saiburi单相表项目', '目前项目正在发标前运作阶段，从代理处获得了TOR的草案文档。该TOR草案主要涉及简单单相表的技术规格，暂无获得商务条款。', '', '综合投标方的价格和产品两方面打分，价格占40%权重，产品占60%权重。目前尚不满足的是TISI认证，这个代理正在申请进程中。', '', '最终一家供应商中标', '', '目前项目正在处于标前运作阶段，尚未能获得保函需求信息。根据上一次Pattaya项目的经验，不需要我司开具投标保函。', '', '关于投标资质相关要求有：当地TISI认证，ISO14001，ISO/IEC 17025 certificate，以及需要在PEA进行供应商登记注册', '', '3台样机需要在截标前准备好，和投标文档一起递交给电力公司。目前预期时间：12月下旬发标，1月上旬截标。', '', '代理商投标', '', '从PEA之前的项目采购历史来看，采购决策过程较为独立，受政治影响小', '', '预计为即期信用证\r\n', '', '从PEA之前的项目采购历史来看，支付能力足够覆盖给供应商的货款\r\n', '', '代理在当地电信运营商和电力公司客户关系强大，是PEA长期的电信产品供应商，代理为当地上市公司，管\r\n理规范，市场能力和项目执行能力都属于当地市场的第一梯队。\r\n', '', '和电力公司表计部门负责人能保持良好的沟通\r\r\n', '', '当时主要竞争对手为华立和长城开发以及当地表厂Precise，其中华立在当地市场运作历史长，长城开发也有\r成功的供货项目记录\r\r\n', '', '当地市场价格和商务竞争比较激烈，需要在商务报价上能够尽可能有优势。项目劣势是TISI认证尚未完成，\r需要加快认证进度', '', '项目成功关键：价格上需要有竞争力；需要的支持：能够按时做好满足PEA技术要求的样机。\r\n', '在该项目上，我司有较大的竞争机会。目前看项目有两个关键点，一个是样机需要按时按技术要求完成，另外\r\r\r\r\r\r\r\r\r\n是报价需要有竞争力。只有满足了这两点，就很有实现突破。此外，电力公司TOR文档中描述了窃电事件告警的几种情\r\r\r\r\r况，制作样机需要考虑到这几种情况。目前来看，现有的简单单相表不能实现其中的零火线互换检测，需要对现有机型进行一定的研发和定制。根\r\r\r\r\r据和技术支持的沟通，SK12项目的单相表机型(五个端子)，或许可以作为一个备选的样机方案。\r\r\r\r\r\r\r\r\n', '常一琳2018-11-23 10:59:26', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('221', '{1312DD1B-37C1-43F6-8C6E-B5D4E641DD55}', '61', 'INHE-0713', '2018-11-23 14:19:37', '0000-00-00 00:00:00', '2018-11-27 08:43:21', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112303/SEN', '', '软件直采项目 无', '软件直采项目 无', '软件直采项目 无', '软件直采项目 无', '', '软件直采项目 无', '', '软件直采项目 无', '', '软件直采项目 无', '', '软件直采项目 无', '', '软件直采项目 无', '', '软件直采项目 无', '软件直采项目 无', '电力公司内部决策，直接采购，政府/政治对决策没有影响', '', '签订验收证明之后的30天内，支付开发费用的100%', '', '客户支付能量良好', '', '银河与代理、电力公司之间，关系良好；\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n代理与电力公司、银河之间，关系良好；\r\r\r\r\n\r\r\r\r\n三方合作已久，关系融洽。\r\n', '', '银河客户关系良好', '', '竞争对手为海兴，科陆，威盛等众多中国厂家。\r\n\r\n\r\n目前银河在客户关系和市场占有量上都有绝对优势。', '', '尽快完成商务协议签订，根据客户已经通过的开发计划进行实施，尽快完成此功能开发，满足客户需求，维护客户关系。', '', '需要软件部门，评估提供全套方案报价（包含电子签名设备报价），在签订协议后派出技术人员按照客户已经同意的方案实施此项目。', '暂无', '苏宏2018-11-23 15:17:10', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('223', '{EA54F0C9-4199-41B6-A51D-5548929A05AD}', '61', 'INHE-0721', '2018-11-26 16:22:26', '0000-00-00 00:00:00', '2018-11-30 08:48:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112602/NCU', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '尼加拉瓜市场目前竞争对手较少，且电力市场属于刚使用智能电表，未建立起明确的电表规范，加之近年尼加拉瓜国家电气化项目实施，将大量采购电表。该代理有意向购买样机，做认证试点项目，试点通过后，可参与2019年投标及当地国内直采项目。此时是进入该市场最合适的时机，望公司支持。', '胡云义2018-11-26 16:38:00', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('224', '{D74343D2-F1F4-4656-8115-6FB165C9BF40}', '61', 'INHE-0440', '2018-11-26 20:24:27', '0000-00-00 00:00:00', '2018-11-30 09:45:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112603/TTF', '', 'TENDER No. PA/001/2018-19/CZN/G/45-A', '2018-12-05', 'SUPPLY OF METERS FOR CENTRAL ZONE UNDER FRAMEWORK CONTRACT  框架合同供应电表给中部各地区', 'TANESCO付坦先令。价格条款为DDP, 付款主体为TANESCO。国内付款条件为： (1)按分订单/LPO的合同金额，10%在签订合同后30天内支付，需提供简单收据和银行担保；20%的合同金额在交货前提供发货文件证明后支付后30天内支付；70%的合同金额在收到电力公司的验收证明后60天内支付。                                                        质保期限：自各地区接受货物起36个月。交期：接到分订单/LPO后3周内交货。违约：百分之0.2/天，未发货产品，最多10%。', '', '框架合同国内限制性招标，目前由ITL和EDMI两家厂商参与，有威胜和科陆其他厂家搅局。先评估技术，然后评估商务，实际上一审是商务和技术一起评估。电力公司希望授标的价格为单相DDP 55美元左右，三相直通150美元左右，ITL和EDMI需参考授标价格报价。', '', '只允许本地厂商投标，目前符合资格要求的有ITL和EDMI,每个厂家最多分2个LOTS，允许授标给3个厂家。', '', 'ITL/Africarriers 准备投标保函2百万坦先令，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '过去三年（2015-2017）的财务报告，包含由总监签字的资产负债表和现金流声明,年平均营业额至少150，000，000先令。流动资产至少为投标价格的150%。至少3年供应/生产类似规模产品的经验。过去5年至少2个供应/生产类似规模产品的经验。', '', '图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)按分订单/LPO的合同金额，10%在签订合同后30天内支付，需提供简单收据和银行担保；20%的合同金额在交货前提供发货文件证明后支付后30天内支付；70%的合同金额在收到电力公司的验收证明后60天内支付。      客户想要运作成为LC付款。\r', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，目前在和银行沟通融资的事情。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。\r', '', '配电副总，TB主席，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。\r', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是配电副总，电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者退休的配电副总，用服总监，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，实验室经理和采购部经理等。目前市场上主要的本地厂家为ITL和EDMI。海兴，威胜和科陆计划建厂。', '', '本地限制性招标，电力公司主要开放给ITL和EDMI,ITL目前已经和我司签了批量SKD合同和安排付款，满足供货要求。框架合同，标书的技术规格，单相和三相直通和TTA一致。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率大，可以获得稳定的订单来源。', '', '产品报价符合市场形势，给予客户技术和商务支持。技术支持人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '汤伟2018-11-26 22:56:32', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('225', '{863F75AE-110C-4EB7-B56A-A01EEF1E791A}', '61', 'INHE-0770', '2018-11-26 23:37:52', '0000-00-00 00:00:00', '2018-11-30 12:51:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112701/BOP', '', '2927/18', '11月30日', 'Supply of MD meters供应MD电表', '标书要求电表费用和培训及首次软件安装费用分开报价，未提及具体价格条款要求，此项目代理投标，代理与银河的付款方式和价格条款待协商，优先考虑T/T预付+保兑信用证交期要求：收到电力公司正式采购订单后16周内完成交付', '', '分为三个评标阶段：1、基本资格要求审核（商务及资质文件）；2、技术评估（供货能力和技术规格评估）3、财务评估（投标价格竞争力）', '', '一家中标', '', '代理负责开立保函', '', '对公司年限、财务数据、供货记录无明确要求，需要提供型式测试报告，ISO证书', '', '资料需要在28日之前做好发给代理。', '', '代理直接投标，银河做厂商支持', 'N/A', '2017年初电力公司进行了组织架构更换，CEO、COO、CFO和配电总监全部外聘为德国白人管理，评标流程趋向正规，但是目前中低层的评标技术委员会还是由各部门经理黑人掌握，对技术评标和样机测试起了很大的促进作用，银河和代理的公关应主要放在评标技术人员身上						\r\n', '', '代理直接投标，银河做厂商支持，代理和银河之间付款条件：待协商，优先采用T/T预付+保兑信用证\r\n', '', '', '', '1.代理FFL是此市场唯一一家专业从事智能电表、水表的工程公司，技术经验丰富；银河通过此代理从2017年开始供应1000台分表业务的智能电表和全套管理系统；\r\r\n2.代理和CSS Director和MEM部门经理 MM取得了一定关系建设；\r\r\n3.代理公司老板年富力强，有冲劲和决心，配合度较好。\"						\r\r\n', '', '1.代理重点关注对象保持着不错的联络关系；\r\r\r\n2.代理在和电力公司管理层 COO方面近期也取得了联系。\r\r\n', '', '主要竞争对手：兰吉尔；由于电力公司前期和海兴供货质量和服务的矛盾，以及南非海兴和其之前博茨瓦纳代理Actom的分裂，基本上此市场海兴的影响力可以暂时排除。\r\r\r\n', '', '1.通过了解，代理主要结识了技术层面的主要负责人，并进行了DIN III、售电系统、CT表的严格测试，测试结果OK，售电系统的演示电力公司也基本满意，在电力公司内部的辨识度有了一定的积累；\r\r\r\n2.代理在近一年按照计划对MEM部门经理MM和管理层重要人物COO进行了多次公关和游说，积累了一定的客户关系；\r\r\r\n3.分表市场已供货的1000余台智能电表和系统，可以作为一个现场的供货凭证和经验参；\r\r\r\n劣势：\r\r\r\n1.代理的财务能力还不足，无法较大规模实施如本地组装厂的建立，增加说服力；\r\r\r\n2.技术层面的关系还有待进一步的加强。\r\r\n', '', '按时提交样机并做好样机演示', '1.根据之前此市场业务了解，整个市场会更换为新一代的智能电表，市场需求量在10万（保守数据）以上，潜力巨大，我们需要抓住这个时机，在样机提交和演示环节做到满足电力公司的要求；\r\r\n2.客户关系层面的建设需要进一步推动代理。\r\n请公司审批。', '刘博2018-11-27 16:23:28', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('226', '{8B44C7AF-1733-46A4-8CCA-0CA52659DA56}', '61', 'INHE-0770', '2018-11-28 23:57:43', '0000-00-00 00:00:00', '2018-12-25 20:58:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112901/MPP', '请业务加强市场调查和项目运作，规避完全不符合资质的情况投标。', 'CEB/IFB/2018/66', '2018年12月10日', 'Procurement of Single & Three Phase Smart Energy Meters单三相智能电表采购', '贸易条款为DDP客户电表实验室；国外公司：付现交单；国内公司：提交发票后30天付款质保：12个月整批货物在签发验收函后14周内交货', '', '分为三个阶段：1.资格审查；2.供货记录、样机、认证、供货记录等资料审核；3.技术评标', '', '一个Lot，一家中标', '', '代理投标，负责开立保函', '', '至少5年供货经验并提供供货记录ISO9001', '', '1.供货记录；2.MID的EC型式测试报告以上最迟提交到业务的时间为12月8日', '', '代理投标，银河供货给代理', 'N/A', '代理直接投标，我们与代理签订合同，代理付款给银河', '', '我们与代理签订销售合同，代理付款给银河，付款方式待协商', '', '电力公司运营状况良好，近几年都有5000万美金左右的赢利。同时电力公司归政府所有，毛里求斯政府运营状态也较好。整个项目的支付能力较好。\r\n', '', '凭借20多年的经验，在银行、资本市场、医疗保健、保险和制造业拥有庞大的客户群。\r\r\n', '', '当地关系暂由代理处理，后续根据项目情况出差建立电力公司客户关系。', '', '电力公司使用的系统是海兴和EDMI的。电表供应商有Elster A220,A1350, A1500\r\r\nLandis & Gyr ZMG\r\r\nEDMI MK10E, MK10A,MK7C, MK7B, MK6E\r\r\nIskraemeco. ME162, ME172\r\r\nHexing HXE 100KP, HX\r\n', '', '银河的劣势是之前有投过几个项目都没有下文，且主要动手如EDMI和海兴有电表和系统的供货。\r\n此次合作伙伴是TTN项目的关联企业，据称在当地很有实力。同时要求延期提交样机。如果实现上述我们要求的更改则证明客户关系良好，且此次代理做为当地的操盘手，我们做支持，主要投入是样机，文档等。', '', '在规定时间内提交样机和投标资料，并通过投标检验代理实力。\r\r\n', '代理是TTN项目代理推荐的关联企业，实力很强，他们在当地做主要关系，我们做为厂商做支持，提供投标文档及样机，不需要投标保函，需履约保函。综合以上建议公司立项。\r\r\n', '刘博2018-11-29 21:51:29', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('227', '{B0A381AE-4225-4E05-94C9-77F63287FCCE}', '61', 'INHE-0654', '2018-11-29 09:39:43', '0000-00-00 00:00:00', '2018-12-07 18:38:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112902/ADF', '', '7000001803', '2018/12/21', '134-能量计量仪表ELEC T1 T2 T3(134-medidores de energia elec T1 T2 T3)', '付款条件:  供应商交货后30天内      交期：在签订合同的60天后交付', '', '内部私下评标', '', '商务+技术', '', '代理负责，银河授权代理投标', '', '', '', '', '', '代理商投标，银河无资质直接投标，投标者需要持有当地公司的营业执照或者分公司。', '', '', '', '', '', '', '', '代理商与电力公司高层关系良好，掌握一定的技术，即使代理商有一定的关系，但是代理商资金实力以及团队数量较海兴当地的团队相比差之一大截，主攻当地市场银河是要借助代理商的这层关系，投入商务以及技术的力量才能与竞争对手抗衡。', '', '', '', '目前仅海兴一家竞争对手，随着市场的开放化，会有更多竞争对手进来。', '', '银河产品在价格上与竞争对手相比无优势，只能在产品性能方面上与竞争对手抗衡。', '', '1，项目的运作，此次招标电力公司指定了要符合海兴产品型号的规格，但CT表海兴也并未取得当地的INTI认证，业务建议参与投标，提供样机给电力公司测试，用产品说话，需要技术支持严控把关，推荐合适产品。2，按时交付样机，并且尽可能做到无偏差。', '1，竞争对手的CT表，目前尚未做当地的INTI的认证，代理建议先参与投标，提供样机，并且代理愿意付钱做认证，了解到认证价格高于五万美金以上。2，该电力公司的招标是议标的形式，主要靠商务的运作+技术，存在分标情况。3，技术规格附件较多，共计五份文件都是西班牙语的，业务还在翻译进行中，确定合适产品参与投标，由于流程审批有一定时间，先走立项评审，技术规格随后附上。', '李明2018-11-30 17:00:56', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('228', '{2621E36B-C8EF-4C95-9C53-E724C3E5A039}', '66', 'INHE-0634', '2018-11-29 14:23:22', '0000-00-00 00:00:00', '2018-12-04 08:56:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112904/KNT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '本项目原来使用的表计是施耐德，现客户有意要换供应商，正与众多表厂联系要求报价。建议立项，争取合作。', '陈雁2018-11-29 15:04:15', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('229', '{FA2677A8-BC6B-41AE-8317-AE52DEC2FAEA}', '60', 'INHE-0601', '2018-12-04 15:05:53', '0000-00-00 00:00:00', '2018-12-19 20:37:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120401/ETA', '', '', '', '老挝EDL单相表和三相表采购项目', '样机采购为100% TT。后续批量供货预计为30% TT+70% LC。', '', '该项目为电力公司直接采购，不经过投标过程。但是需要经过样机测试和商务报价流程。', '', '第一期采购项目的40万台电表由几家合格电表厂家共同供货', '', '', '', '', '', '测试样机需要2台简单单相表和2台简单三相直通表，要求尽快完成样机制作。', '', '直销（直接采购）', '', '政治因素对采购决策影响不大', '', '样机采购为100% TT。后续批量供货预计为30% TT+70% LC。', '', 'EDL为国家电力公司，支付能力足够覆盖给供应商的货款', '', 'BCI是老挝国家电力公司EDL的工程承包商和项目咨询公司，和EDL有长期的合作关系和商业往来。BCI为Interlink在老挝电力行业项目的合作伙伴公司。\r\r\r\r\n', '', '', '', '老挝市场，主要竞争对手为宁波三星，Itron 和 EDMI。', '', 'Itron和EDMI在当地市场经营多年，但产品价格偏高。而宁波三星的单相表当地报价为22美元\r\r。\r\r\r\n在同等技术规格上，我司可以报出有竞争力的报价，来突破这个新市场。\r\r\r\r\r\n', '', '商务报价需要有竞争力；测试样机制作需要尽快。\r\r\r\n', '在该项目和老挝这个新市场，我司有很大的竞争机会。\r\r\n首先，我司现有产品即可满足电力公司技术要求，不需要投入研发资源进行定制开发。我司单相表和三相表的产品技术规格已经通过了电力公司的审核和确认。\r\r\n其次，我司在产品商务报价上具有很强的竞争力。\r\r\n最后，本地代理公司的客户关系过硬，敢于投入，对拿到项目很有信心和把握，愿意承担样机所有相关费用。\r\r\n	\r\r\n', '常一琳2018-12-11 17:45:40', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('230', '{73197833-8330-4CD8-A374-A8C1046D94B6}', '66', 'INHE-0634', '2018-12-05 09:19:32', '0000-00-00 00:00:00', '2019-06-25 14:42:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120502/VIC', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '智利当地认证：subtel (针对RF的认证)，SEC（针对电表的认证），认证相对简单，需要1-2个月时间，智利当地代理表示他们自己会花钱去做。友讯达表示其没有海外电表经验，而其公司高层很重视本项目当地代理，才寻找银河协助共同执行。友讯达反馈曾经找过海兴和威盛，这两家都没有LoraWAN的电表。总的来看，如果公司有现成产品，本项目周期短，效益高，值得参与，建议立项。', '陈雁2018-12-05 10:48:10', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('231', '{E392CA24-0FD4-41D7-A0D6-D409B3AC836A}', '61', 'INHE-0500', '2018-12-06 01:53:05', '0000-00-00 00:00:00', '2018-12-07 18:29:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120601/KWA', '', '161/2018', '2018年12月27日 南非当前时间12点', 'Supply, installation and management of a STS compliant prepayment electricity vending system for a period of three years.三年期框架采购合同：1.供应、安装和维护托管性质的STS售电系统；2.供应、安装和维护项目实施所涉及的硬件部分；3.负责和当前市政公司使用的第三方系统做接口。', '三年期框架供货协议；报价为DPP含VAT价格；付款主体：KwaDukuza Local Municipality (KLM)；                                               交期：60天内完成新售电系统的替换、数据迁移、第三方售电平台接入、培训、试运行和全运行；                                                   付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；             质保和违约：服务商和市政公司签订SLA服务协议，系统涉及的硬件和软件满足36个月质保。', '', '评标分为四个流程：1.基础资料评审：购买标书和参加标前会议的凭证、市政招标政府固定的固定格式表格（CSD证书等）；2.技术资料评标，100%满足标书中的强制性条件表格A，70&满足技术标书中的技术应答表；3.价格评审，按照BBBEE资质80/20的偏好打分，BBBEE最高资质有20分偏好；4.演示评审：技术评审和价格评审的合格服务商进入到短名单，进行现场系统演示，最终决定中标服务商。', '', '一家中标', '', '投标无需开立保函，中标后需要开立履约保函', '', '1.投标公司需提供ISO90001-2015证书，强制性条件；2.投标公司需要提供和Munsoft系统（账单系统和财务管理系统）已成功交互接口的证明文件，强制性条件；3.投标公司需要提供至少一份来自其他市政公司关于投标公司售电系统满足mSCOA标准的证明文件，强制性条件；4.投标公司需要提供南非本地PCI证书（Payment Card Industry Certificate），强制性条件；5.投标公司需要至少提供三名主要软件工程师资质证明文件，至少本科学历，3到5年的类似项目工作经验；和至少四名客服工程师资质证明文件，至少A+资质，3到5年类似项目工作经验；6.类似供货项目的实施经验：8年以上经验满分20分，4至7年15分，1到3年10分；7.有7*24*365售电系统服务中心的实施经验，至少5年以上的操作经验；', '', '1.商务支持：协助技术解析申请、协助业务和国内客服人员的技术澄清、需要协助完成标书资料（银河部门）。12月21日完成；2.技术支持：提供按照标书技术应答表和强制性条件中所列举的技术方案，12月15日完成。', '', '代理NYC投标，银河做技术支持', 'N/A', '市政公司自行决定评标全流程，评标委员会由市政指定的技术代理+财务部成员+采购部成员+电力分支负责人组成，中标的最终价格需要参考财务部审批的年初预算\r\n', '', '付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；				\r\n', '', '需跟进调查，取得相关信息\r\r\n', '', 'NYC优势：BBBEE资质20分偏好优势；愿意在本地投入客服中心（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案\r\r\r\r\r\r\nNYC劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\r\r\r\r\n', '', '第一次在次市政投标，无内部客户关系和支持。\r\r\r\r\r\n						\r\r\n', '', '售电系统的供应商，需跟进调查，取得相关信息\r\r\n						\r\r\n', '', 'NYC优势：1.BBBEE资质20分偏好优势；2.愿意在本地投入客服中心（强制性要求）；3.积累了一定的财力和实力，可以提供更优的融资方案\r\r\r\r；\r\r\r\r\r\nNYC劣势：1.第一次在次市政投标，无内部客户关系和支持。\r\r\r\r\r2.\r此次招标技术规格部分有被竞争对手严重运作的嫌疑，如Munsoft证书、PCI证书等，需要向市政公司提出澄清，否则无法满足强制性条件。\r\r\r\n竞争策略：此市政公司为KZN省主要的地区性市政公司之一，经济条件较好，需要联合NYC积极投标，澄清主要不符点，同时积极拜访市政公司核心成员（采购，电力部门工程师和CFO层面）开拓客户关系				\r\r\r\r\r\n', '', '1.主要强制性商务和技术不符点的澄清，争取有利的条件；\r\r\n2.和NYC组织对市政公司CFO、电力分支部门负责人进行联系公关，确立合作意向和支持；                   3.提前准备好技术演示，一次性成功完成演示需求。					', '需要申请商务协助和技术协助。李忠鹏负责现场澄清和报价等准备。联合NYC调整竞争策略，在下周计划拜访此市政项目技术负责人和采购人员。', '李忠鹏2018-12-06 03:33:47', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('232', '{06710E6E-CF6D-4F7C-9C2E-394F4CAB8AE7}', '66', 'JXINHE-2559', '2018-12-06 22:08:58', '0000-00-00 00:00:00', '2019-01-04 08:28:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120603/PMT', '', 'NO. NOR-90-2018', '2019年1月11日', 'NDTC自有电站的计量系统采购', '标书要求：提交发票或付款申请内的60天，采购方付款。实际合作：中标后，代理直接向我司采购。', '{06710E6ECF6D4F7C9C2E394F4CAB8AE78442F4C2B3234363A3D51C033076BD50}_7.Section IV-Part-I-General Conditions of Contract.docx', '无特殊要求IB32', '{06710E6ECF6D4F7C9C2E394F4CAB8AE7074E749A304748709C51373D9D483750}_4.Section I- Instructions to Bidders.docx', '最低价中标，IB34一家制造商只可授权参加一个投标人 ITB4', '{06710E6ECF6D4F7C9C2E394F4CAB8AE72B47EB25ABE84FF19C47768372BB342D}_4.Section I- Instructions to Bidders.docx', '投标保函无特殊要求见IB19；投标保函金额不少于总报价金额的2%；代理负责开具投标保函履约保函金额', '{06710E6ECF6D4F7C9C2E394F4CAB8AE71DD410FC292E4E1893AFBEF9F88431CD}_5. Section II-  Bidding Data and appendices (2).docx', '1.同类产品供货金额320,000美元2.同类产品五年生产经验3.同类产品至少与投标数量相同的生产能力及供货经验4.截标期前，三年内正常营业，年平均营业额不少于320，000美元，现金流不少于256，000美元5.三份用户证明，至少一份是生产国以外的6.产品型式测试报告7.违约金额不得多于年平均营业额和现金流的25%，否则被取消投标资格如上要求，详见文档IB6', '{06710E6ECF6D4F7C9C2E394F4CAB8AE703404677E4D44E9EB56B3D512B2AF9CC}_5. Section II-  Bidding Data and appendices (2).docx', '1月7日必须完成标书制作并寄出至巴基斯坦拉合尔。', '{06710E6ECF6D4F7C9C2E394F4CAB8AE7C675BD0CC93442C09B990884D4324504}_PMT项目标书.rar', '银河直接投标，授权代理作为独家代理购买标书，向业主递交投标文件。', '', '代理和采购方关系良好。', '', '收到供应商发票或收款要求的60天付款，16.Terms of Payment', '{06710E6ECF6D4F7C9C2E394F4CAB8AE7DC30B63FF962416CACC9A604CE6ABE1F}_7.Section IV-Part-I-General Conditions of Contract.docx', '正在了解中。', '', '合作伙伴财力雄厚，集团公司，长期从事能源行业，包括石油，航空，保险等行业。曾实地拜访其位于国家首都城市的两处公司，团队专业，老板50岁左右，拥有一定的政治资源。', '', '合作伙伴承诺安排我们和业主的执行董事见面，以证明其良好的商务资源。', '', '正在了解中。', '', '项目为巴基斯坦少有的国际性招标，巴国输配电公司发出高精度CT表的招标，由于关注国际企业较少，当地的当地表厂又缺乏相应的技术和生产能力，我司可凭借自身的技术优势在当地代理的配合下，拿下项目。附客服部出具的产品技术解析。', '{06710E6ECF6D4F7C9C2E394F4CAB8AE7B79221563C224206B274FD7CD6B16366}_PMT-28-202-2012三相四线经CTPT接入多功能表技术规格书.docx', '项目时间较紧，需在1月7日前完成标书的制作，收到代理分享市场信息后，需要公司提供最优的报价支持。', '巴基斯坦市场由于价格和本地招标壁垒原因，一直未能实现向电力公司的批量供货，希望通过该项目，进入该国市场，打开局面。', '淦永妍2019-01-03 14:52:45', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('233', '{91AD9822-6B4D-4AB8-AA6F-C0814E7EE8A0}', '61', 'INHE-0744', '2018-12-10 15:31:36', '0000-00-00 00:00:00', '2018-12-10 15:31:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121001/CNT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '郑超波2018-12-10 15:36:59', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('234', '{BA61B591-76AF-43CE-9C4D-647B81796E9D}', '61', 'INHE-0432', '2018-12-11 03:57:19', '0000-00-00 00:00:00', '2018-12-19 20:42:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121103/ELT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.技术难点：单相直通表要求有功计量0.5。此前招标也是这个要求。                                   2.资质难点：需要MID认证。', '\r\r\r\r\n1.目前项目初期，需要公司提供/运作银河技术规格，然后制样、送样测试；     2.样机测试通过后，我们将与合作伙伴一起，与AIO商讨具体的商务细节，推动与AIO签署联合建厂方案合同、本地生产方案合同。AIO主导建厂，银河供货。                                                     3.最后协助AIO本地建厂、运作本地电表订单', '谭东羊2018-12-11 04:23:02', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('235', '{97722953-B73D-4F36-B36C-FAF456B3D990}', '93', 'INHE-0811', '2018-12-12 17:17:53', '0000-00-00 00:00:00', '2018-12-13 11:44:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121204/SCE', '', 'AO：F_DSTA_058', '', 'Acquisition de compteurs d’énergie électriques电表供应项目', '价格条款：直接投标人DDP报价（我们给代理报FOB或者CIF报价）；           付款条款：直接投标人交付之后支付60%合同额，40%合同尾款临时验收之后支付（我们与代理签订另外的付款协议，按照银河要求的付款方式进行谈判）；     交期：供货服务开工令颁发之日起30-60天之内交付；                      质保：质保期限临时验收之后2年，维修和更换期限不超过30天              违约条款：除非是提前预知需要延期，否则交货期满之日起，每天产生合同金额1/1000的罚款，延期交付罚款不超过合同额的10%', '', '1，	标书资料完整性（商务、技术、财务）                            2，	交货时间表符合要求（开工令下达之日起30至60天之内交货）         3，	投标人近三年（2015/2016/2017）财务状况                       4，	投标人近三年（2015/2016/2017）至少一个类似的合同项目及竣工证明', '', '唯一标段', '', '投标保函： 金额1000000FCFA（约1727美元），有效期自标书失效之日起28天 开立行资质：不可撤销的信用证，或者财政部长批准的银行机构出具的银行担保，或财政部批准的授权开具保函的机构，或银行支票履约保函金额是合同额的5%开立资质：财政部长批准的银行、保险公司或者其他财务机构（保函由代理自行准备）', '', '1, 公司提供无破产证明，签字人授权书                                2, ARMP2017年的证明                                                3, 投标人近三年（2015/2016/2017）财务状况                           4, 投标人近三年（2015/2016/2017）至少一个类似的合同项目及竣工证明', '', '交标时间2018年12月26日', '', '代理商投标', '无', '达喀尔自治港口政府项目，自有预算出资', '', '中标人交付之后，提交发票及付款申请，提交之后业主于45天之内支付', '', '达喀尔港口预算项目，为政府自筹资金', '', '代理在当地注册公司，与业主有过多次项目合作，在当地有施工安装队伍及技术人员', '', '代理代表银河投标，且代理运作与业主的关系', '', '该项目会优先选择当地或者西非经盟的企业，海兴在当地有注册公司，极有可能参加，还有当地一些代理商代表中国公司参加', '', '由于该项目倾向本地供应商，参加投标的中国或印度供应商少；而本地供应商里除了海兴（在当地有分公司）可以与银河竞争，其余表厂机会较小。\r\n\r\n我方通过代理商投标，规避了付款的相关风险，代理运作客户关系可以对项目进行推动运作', '', '需要总部商务组支持准备法语投标资料\r\r\n该项目请以银河标记的名义授权给代理投标，因为需要近三年类似的项目业绩', '', '宁桃美2018-12-13 09:45:53', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('236', '{33AB52A2-B232-441D-AA70-D87EFDB38C2A}', '61', 'INHE-0744', '2018-12-13 23:48:10', '0000-00-00 00:00:00', '2018-12-19 20:21:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121401/UDZ', '', '2018D/3736', '2019年1月16日', 'COMPTEUR STATIQUE TRIPHASE COMMUNICANT A BRANCHEMENT SUR REDUCTEURS DE MESURE经互感器接入的三相静态通讯电能表', '付款条件：信用证付款（标书未说明是即期还是远期）交期：合同签署后3个月内；如延期，每个工作日罚款合同金额的0.2%，最高到5%', '', '符合技术条款的前提下，低价中标，本地企业优先中标', '', '独家中标', '', '投标保函： 13000第纳尔（约4400美金），有效期120天；履约保函：合同金额的5%，需要转开', '', '只能是电表制造商能够投标', '', '', '', '银河投标，代理负责关系维护和运作中标', '', '', '', '', '', '', '', '', '', '代理有5家可以供选择，目前比较倾向于选择的代理为英利（太阳能）的突尼斯代理公司。该公司与电力公司高层有较好的关系', '', '标书中明确说明，本地制造企业有优势，其中本地主要竞争对手有：\r\r\r\r\r\r\n1、法国Sagem集团：本地有工厂，是电力公司现有机械电表供货商之一）；\r\r\r\r\n2、海兴（本地合资品牌Intech）；\r\r\r\n3、Siame公司，原电力公司的电表制造厂，后私有化了，是现在电力公司电表额主要供货商；\r\r\r\r\r\n\r\n\r\n除本地企业外，主要竞争对手还包括：\r\n-华为&科陆；\r\n-兰吉尔；\r\n-Itron', '', '', '', '- 价格；\r\n- 代理的客户关系', '突尼斯是一个战略市场，不仅仅市场容量大，其影响力还辐射到周边多个国家；如果本次投标能够中标，不仅仅能够推动银河在马格里布区域市场的拓展，还能以此为跳板，进军欧洲高端市场！', '郑超波2018-12-14 11:57:18', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('237', '{BE0CEDCB-0DD3-4C80-9124-EDD65EFD8B8B}', '61', 'INHE-0431', '2018-12-14 10:00:43', '0000-00-00 00:00:00', '2018-12-19 20:16:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121402/POR', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户是主做道路和电力（偏住宅等实体类）的小总包商，总部位于葡萄牙，业务遍布葡萄牙，加纳，安哥拉等地，此次具体项目所在地为安哥拉。项目为简单的直接采购供货（CIF LUANDA)，首批订单为3500台，整体订单为35000台左右。建议立项。', '刘佩2018-12-14 10:09:58', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('238', '{949F749B-1795-4A27-8DEA-0A01844E0FBC}', '61', 'INHE-0432', '2018-12-17 05:24:25', '0000-00-00 00:00:00', '2018-12-19 20:28:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121701/MBP', '', 'KP1/9A.3/OT/03/18-19', '2019年1月9号', '11KV开关柜供货招标', '1.发货：DDP到KPLC仓库（含税）2.付款：在供应商满意交付并提交相关文件后的30天后起，KPLC开始支付。3.交期：在提供PO和合同的5个月内完成交货', '', '', '', '1.商务评审：1）检查投标者所提交的文件是否符合要求；2）财务要求（流动比率及偿付能力）是否满足电力公司要求；     年营业额至少是投标总金额的75%2.技术评审：技术应答表是否满足技术规格要求；是否有偏差3.财务评审：1）比较多家报价，价格最低者中标；2）考虑投标方提交的信息调查问卷表填写的的信息，包括投标者的能够经营的最大价值及本地股东占比（本地优先原则）', '', '投标保函：873,000 KES，折算约8730美金。                              履约保函金额：合同金额的10%，开立时间:拿到中标函的14天内开立', '', '1.标书要求：此招标仅对当地制造商或当地代理商/当地授权供应商开放； 2.本地保护：1）本地生产/组装优先；2）本地公司中肯尼亚人的股东占比至少51%以上优先', '', '1.投标者财务要求：a）KPLC的可接受比率如下： - i）流动比率，即流动资产/流动负债大于等于1； ii）偿付能力比率，即资产/债务比率，达到至少1； iii）上一财年的营业额，即十二个月至少为总投标价值的75％；3.生产商提供有效的ISO9001证书；完全满足测试要求的测试报告4.关于产品资料，相关测试报告及证书需要制造商提供技术规格标书要求生产商资质如下：1.生产商需要提供QAP质量管控计划文件，如有；2.生产商经验:要求至少10年以上从事12kv的室外开关柜制造经验；3.供货记录：生产商需要提供过去5年的供货记录，过去5年内海外销售超过至少500台；需要提供至少4个以上海外客户的用户推荐函；4.以前在KPLC有过不良质量的生产商将不予考虑；', '', '待定：若IAC自己投，则无法享受本地保护的15%的优惠，因为IAC的大股东是深圳银河而非肯尼亚人。需要公司评审后给意见。', '', '', '', '', '', '', '', '', '', '', '', '这个产品领域的竞争对手已知的有ABB，西门子，英国的Lucy Electric等公司常年给KPLC供货。', '', '', '', '', '1.请公司评审我们是否可以做，并且在技术、资质上满足要求。                                         2.投标方式待评审后再定：看是IAC自己投（国内厂商给授权）；还是要和本地企业联合投标。', '谭东羊2018-12-17 15:24:32', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('239', '{C3081E99-1B26-4D7C-925B-95ED6881DC5E}', '61', 'INHE-0695', '2018-12-17 10:06:16', '0000-00-00 00:00:00', '2018-12-17 11:27:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121702/SLV02', '', '', '2019.1.30', '', '当前为技术资格预选阶段，商务文件只会提供给通过了技术资格预选的投标方，因此暂且未知商务条款。', '', '技术评标测试流程如分验收测试及功能测试验收测试包括：1. 计量测试2. 技术参数核对3. 本地/远程 调试测试4. 短期长期通信测试功能测试流程及测试项详见附件。', '{C3081E991B264D7C925B95ED6881DC5E074E749A304748709C51373D9D483750}_funk?né testy IMS elm.sk.en.docx', '1在技术评标完成且通过后，电力公司会采取在线竞价模式进行评选。最终会选出两家供应商签订合同。', '', '代理投标，资格预选阶段无该要求', '', 'N/A，商务文件暂未提供。', '', '1.MID证书2.质保要求3.原材料符合欧盟REACH标准声明4.本地计量局认证报告（代理申请）5.符合斯洛伐克政府法规《关于计量设备可访问性合格评定程序》的协议（代理申请）6.符合斯洛伐克政府法规《关于计量设备可访问性合格评定程序》的声明（代理申请）7.电表所采用的通信协议说明文档（符合IEC-62056-6-2）8.上位机软件9.操作手册10.保修证明', '', '代理投标', '', '暂且未知\r\r\n', '', '暂且未知\r\r\n', '', '信用良好，据查其年报，无诉讼及违法情况。，财报见附件（双语版）\r\n', '{C3081E991B264D7C925B95ED6881DC5E108D268797C74834B1DDE2FC1083AA37}_Vyrocna sprava a uctovna zavierka 2017 SSD.pdf', '代理跟电力公司有多重业务往来（电池，电表，互感器等），客户关系不错。\r\n其公司为家族企业，在东欧各国均有生意往来，公司老总在斯洛伐克政界有一定影响力。\r\n其熟悉投标运作规则，此前在同斯洛文尼亚的Iskraemeco合作。\r\n', '', '客户关系为代理运营，银河尚未深入一线。\r\n', '', '1. 三星-主攻基本款（Basic）电表，对应技术规格中 1、2类电表。客户关系佳。其代理为本地的售电公司（斯洛伐克本地发输配售电环节已拆分），同时也有发电业务，财力较强。\r\r\n2. ADD Grup-主攻进阶款（Advanced）电表，对应技术规格中3、4、7类电表。客户关系尚可，其代理为此前SLV项目代理，实力尚可，有一定客户关系，但财力一般。\r\r\n3. EMH-主攻特殊款（Special）电表，对应技术规格5、6、8类电表。客户关系未知，产品质量好。\r\r\n4. 海兴-客户关系未知。只在本地进行登记了单相表，尚未开始参与招标。\r\r\n5. Iskraemeco-其同代理关系一般。 其他情况未知。\r\r\n6. Mikroelectronika-波黑表厂，在东欧地区有一定知名度。主攻特殊款（Special）电表。\r\r\n', '', '1.新市场需积极参与，熟悉技术规格，同时争取竞争机会，加强同电力公司的客情建设。参与了才能够了解内部情况，以至于争取后续的竞标机会。\r\r\r\r\r\n\r\r\r\r\r\n2.明年该市场将开始大规模的单相智能电表招标，三家电力公司技术规格相似（只在部分功能上有细微差异）提前熟悉技术规格，便于后续MID证书出来后，直接参与至两外两家电力公司的单相表招标中。\r\r\r\r\r\n', '', '1.希望公司能安排客服仔细研究提供的技术规格，了解我们的二代模块表及一带模块表是否满足，若不满足，是否可以作部分功能修改？\r\r\r\r\n\r\r\r\n2.此外，业务正在着手翻译该市场具有代表性的电表操作手册（ADD Grup的NP73E/NP71E，稍后将会提\r\r\n供给客服，望客服能够给出指导性意见，我们的电表跟竞争对手的电表相比，在功能上有何优劣势？\r\r\r\r\r\n\r\r\n', '', '卿于蓝2018-12-17 11:24:42', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('240', '{BCC9298C-F7CB-47DE-8918-FFFD74B2D89C}', '61', 'INHE-0695', '2018-12-17 11:45:47', '0000-00-00 00:00:00', '2018-12-19 20:51:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121703/SSD', '', '', '1月30日', '', '当前为技术资格预选阶段，商务文件只会提供给通过了技术资格预选的投标方，因此暂且未知商务条款。', '', '技术评标测试流程分验收测试及功能测试验收测试包括：1. 计量测试2. 技术参数核对3. 本地/远程 调试测试4. 短期/长期通信测试功能测试流程及测试项详见附件。', '{BCC9298CF7CB47DE8918FFFD74B2D89C074E749A304748709C51373D9D483750}_funkcne testy IMS elm.docx', '1在技术评标完成且通过后，电力公司会采取在线竞价模式进行评选。最终会选出两家供应商签订合同。', '', '代理投标，资格预选阶段无该要求', '', 'N/A，商务文件暂未提供。', '', '1.MID证书2.质保要求3.原材料符合欧盟REACH标准声明4.本地计量局认证报告（代理申请）5.符合斯洛伐克政府法规《关于计量设备可访问性合格评定程序》的协议（代理申请）6.符合斯洛伐克政府法规《关于计量设备可访问性合格评定程序》的声明（代理申请）7.电表所采用的通信协议说明文档（符合IEC-62056-6-2）8.上位机软件9.操作手册10.保修证明11. 代理授权书', '', '代理投标', '', '暂且未知', '', '暂且未知\r\r\n						\r\r\n', '', '信用良好，据查其年报，无诉讼及违法情况。，财报见附件（双语版）', '{BCC9298CF7CB47DE8918FFFD74B2D89C108D268797C74834B1DDE2FC1083AA37}_Vyrocna sprava a uctovna zavierka 2017 SSD.pdf', '代理跟电力公司有多重业务往来（电池，电表，互感器等），客户关系不错。\r\r\n其公司为家族企业，在东欧各国均有生意往来，公司老总在斯洛伐克政界有一定影响力。\r\r\n其熟悉投标运作规则，此前在同斯洛文尼亚的Iskraemeco合作。\r\r\n', '', '客户关系为代理运营，银河尚未深入一线。\r', '', '1. 三星主攻基本款（Basic）电表，对应技术规格中 1、2类电表。客户关系佳。其代理为本地的售电公司（斯洛伐克本地发输配售电环节已拆分），同时也有发电业务，财力较强。\r\r\r\r\n2. ADD Grup主攻进阶款（Advanced）电表，对应技术规格中3、4、7类电表。客户关系尚可，其代理为此前SLV项目代理，实力尚可，有一定客户关系，但财力一般。\r\r\r\r\n3. EMH主攻特殊款（Special）电表，对应技术规格5、6、8类电表。客户关系未知，产品质量好。\r\r\r\r\n4. 海兴客户关系未知。只在本地进行登记了单相表，尚未开始参与招标。\r\r\r\r\n5. Iskraemeco其同代理关系一般。 其他情况未知。\r\r\r\r\n6. Mikroelectronika波黑表厂，在东欧地区有一定知名度。主攻特殊款（Special）电表。\r', '', '1.新市场需积极参与，熟悉技术规格，同时争取竞争机会，加强同电力公司的客情建设。参与了才能够了解内部情况，以至于争取后续的竞标机会。\r\r\n\r\r\n2.明年该市场将开始大规模的单相智能电表招标，三家电力公司技术规格相似（只在部分功能上有细微差异）提前熟悉技术规格，便于后续MID证书出来后，直接参与至两外两家电力公司的单相表招标中。\r', '', '1.希望公司能安排客服仔细研究提供的技术规格，了解我们的二代模块表及一带模块表是否满足，若不满足，是否可以作部分功能修改？\r\r\n\r\r\n2.此外，业务正在着手翻译该市场具有代表性的电表操作手册（ADD Grup的NP73E/NP71E，稍后将会提\r\r\n供给客服，望客服能够给出指导性意见，我们的电表跟竞争对手的电表相比，在功能上有何优劣势？\r\r\n\r', '', '卿于蓝2018-12-17 17:06:09', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('241', '{274BF5E8-E4C8-4918-A693-169EBB5E467F}', '66', 'INHE-0628', '2018-12-18 17:08:57', '0000-00-00 00:00:00', '2018-12-25 15:09:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121801/SLG', '', 'MOE/EDSA/VFCS/ICB./0002/2018', '2018年12月14日', 'VENDOR FINANCING OF CONSIGNMENT STOCK OF SINGLE AND THREE PHASE STS SPLIT PRE-PAID ELECTRICITY METERS AND ASSOCIATED SYSTEMS AND ACCESSORIES分销商融资的单相和三相STS分体预付费电表及相关系统及配件', '电力局给Delta公司DDP，Delta给银河是不可撤销保兑信用证', '', '', '', '3个lot,但未限制几家中标', '', '代理公司开立', '', '15年供货经验，此点银河不符，需要代理运作', '', '已经截标，代理将替换样机和加入文件', '', '代理投标，从银河直采', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '代理对高层关系运作，银河在技术上提供及时有效的支持。', '该国至少还有100万台以上的需求，代理有一定实力且愿意投入，并且其公司直接投标参与，承诺给银河的结算条款（不可撤销保兑信用证）也较有利。银河相对风险较小，建议给予代理支持，推进SLG项目。', '刘元豪2018-12-18 18:13:27', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('242', '{1B55C811-3A10-4BE7-B4EE-08998B8185C4}', '66', 'INHE-0774', '2018-12-24 14:41:31', '0000-00-00 00:00:00', '2018-12-27 18:28:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018122401/IDE', '', 'IDECO 26/2018', '2019年1月30日当地时间下午两点', '供应 （400V L-L),三相直通式智能电表，AMI系统和安装支持 Supply of:(400V L-L),Smart Three Phase Direct Electronic Meter,(10)100A,Multi Tarrif(4Tarrifs), Class 1 KWH, Class 2 KVARH, 4-wire Direct Connection with AMI solution and supporting team', '1. 价格条款：CPT IDECO Stores2. 付款主体：IDECO3. 付款条件：（1）收货验收后两周内付款5%；（2）电表运行第一年结束后付款5%；（3）电表运行第二年结束后付款5%；（3）电表运行第三年结束后付款10%；（4）电表运行第4年结束后付款10%；（5）电表运行第5年结束后付款10%；（6）运行第6年结束后付款10%；（7）运行第7年结束后付款10%；（8）运行第8年结束后付款10%；（9）运行第9年结束后付款10%；（10）运行第10年结束后付款15%。4.质   保：工厂发出算起15个月，或者电表安装使用之日起12个月5.交   期：根据合同，标书暂未明确具体时间注：付款方式可以和电力公司协商，但是同意标书中的付款方式的Bidder会被优先考虑', '{1B55C8113A104BE7B4EE08998B8185C48442F4C2B3234363A3D51C033076BD50}_Tender No IDECO 62 2018.pdf', '评标因素：1.和标书相符度；2.交货期；3.服务和配件等', '', '一个LOT', '', '1.投标保函：开立方：厂商； 金额：投标总额的5%； 有效期：截标日起120天； 开立行资质： 约旦的银行；2.履约保函：开立方：厂商； 金额：投标总额的10%；   有效期：订单签订之日起16个月； 开立行资质：约旦的银行', '', 'DLMS', '', '标书中规定的测试报告（包含电表寿命约20年，主板，LCD，表盖端盖，继电器等）', '', '银河投标', '', '', '', '（1）收货验收后两周内付款5%；（2）电表运行第一年结束后付款5%；（3）电表运行第二年结束后付款5%；（3）电表运行第三年结束后付款10%；（4）电表运行第4年结束后付款10%；（5）电表运行第5年结束后付款10%；（6）运行第6年结束后付款10%；（7）运行第7年结束后付款10%；（8）运行第8年结束后付款10%；（9）运行第9年结束后付款10%；（10）运行第10年结束后付款15%。	付款方式供应商可和采购方商议，同意标书上的付款方式将会被优先考虑\r\r\r\n', '', '', '', '合作伙伴公司：（1）成立于2002年，在约旦主要经营机电产品，包括：电缆和通信电缆，负载开关和隔离器，柴油发电机，输电变压器，LV&MV 开关设备，测试设备，电缆接头，电表和水表，防爆材料等。服务电力公司，水和矿产资源主管部门，机电承包商和终端用户；\r\r\n（2）获得ISO9001:2008认证；\r\r\n（3）电表中标记录： 标号：IDECO6/2004  采购公司：IDECO，表商：ISKRAMECO 产品：3相电表 合同金额：7005 欧元\r\r\n                   标号：IDECO15/2008 采购公司：IDECO，表商：MEMF      产品：3相电表 合同金额：89000美元					，老板有30多年行业经验。	\r\r\n', '', '', '', '1. 2015年9月 JEPCO电力公司的600台三相多功能表的标 兰吉尔中标\r\n2. 2015年11月 JEPCO 7万台三相表和6000台单相表的表 华立中标\r\n\r\n', '', '劣势：第一次和这个代理合作，代理底细不是很清楚；代理要求我们开投标保函；标书规定的付款条件较差，检测要求和验收流程严格。\r\n优势：我们在此市场有较多投标经验；可以联系以前合作的代理作为备选\r\n\r\n', '', '', '客户已解析生成样机技术规格书，推荐三相四线直接接入式可更换通信模块多费率智能电表，客服的意见是电表偏差不大；\r\n现在的代理不愿意开投标保函，银河比较被动\r\n', '何森华2018-12-26 14:10:28', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('243', '{FC970DA3-CEB7-498E-8FC8-6BD7D7C36DB0}', '61', 'INHE-0722', '2018-12-25 15:33:35', '0000-00-00 00:00:00', '2018-12-27 18:10:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018122501/HRC', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '该项目目前未有确定规格，且现场电力部署十分混乱，偷电窃电严重，客户正在列出技术需求，并希望由我司给出具体的规格及方案。2019年1月7日，客户将拜访我司，需要现场做预付费及集抄演示，具体技术需求，另将OA发出。', '希望公司同意立项！', '冯婷2018-12-25 16:38:35', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('244', '{59C3A8E7-A017-4DDE-902D-C35A05A297EF}', '66', 'INHE-0579', '2018-12-28 13:40:11', '0000-00-00 00:00:00', '2019-01-03 09:21:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018122801/IEG', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '项目为直接采购，代理在筛选供应商阶段。已与代理沟通交流确定表型，最终端客户接受我司方案，现代理拟采购样机进行测试。\r\n\r\n申请立项。', '孙娜2018-12-28 15:48:37', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('245', '{9CB461D8-F0B9-4C1D-9922-287DBF0EC01F}', '66', 'INHE-0774', '2019-01-02 15:57:46', '0000-00-00 00:00:00', '2019-01-08 08:52:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019010201/EVN', '', '11-12/2018', '2019-01-31', 'THROUGH NEGOTIATED PROCEDURE WITH PRIOR PUBLICATION OF NOTICE FOR AWARDINGFRAME WORK AGREEMENT FOR PUBLIC PROCUREMENT OFCOMPLETE ELECTRONIC THREE-PHASE METERS FOR DIRECT CONNECTION(公开采购直接接入式三相电表)', '（1）价格条款：DDP at the location of EVN Macedonia AD, Skopje 或DAP（2）付款方式：卖家发货，提交发票和验收合格证明后30天内履行付款义务  	（3）付款主体：资金来源EVN Macedonia融资（4）交    期：未明确，供应商提交		（5）质    保：未明确，供应商提交', '{9CB461D8F0B94C1D9922287DBF0EC01F8442F4C2B3234363A3D51C033076BD50}_Tender documentation 11-12-2018 （Updated).pdf', '最低价中标', '', '1 lot,一家制造商只能授权一个投标人', '', '不要求投标保函（不履行投标义务的投标人列入黑名单Negative reference）', '', '（1）Type Approve(EU)，欧洲的形式测试报告 （2）EN ISO9001 （3）供货记录 （4）财报', '', '（1）Type Approve(EU)，欧洲的形式测试报告 （2）EN ISO9001 （3）供货记录 （4）财报', '', '银河投标（标书直接从电力公司获得，还没找到合适的代理，暂时由银河直接投标，如果有合适的代理可以考虑联合投标）', '', '采购分两步：\r\r\n第一步，提交参与要求（包含样机和标书中规定的资料）\r\r\n通过资格预审，评出至少三家合格的候选公司\r\r\n第一阶段合格的公司会受到进入第二步提交报价的邀请，然后再通过最低价决定最后与其签订合同的公司\r\r\n\r\r\n\r\r\n\r\r\n\r\r\n\r\r\n', '', '卖家发货，提交发票和验收合格证明后30天内履行付款义务', '', '', '', '', '', '', '', '', '', '劣势：在当地市场没有投过标，银河在欧洲市场还是初步探索阶段，竞争对手情况，市场情况，价格水平不是很清楚；资质证书是否符合要求（ISO EN 9001,Type approval(EU))；目前没有合适代理\r\r\r\n优势：大部分商务条款和技术规格应该能满足，可以银河自己投标；不需要开保函；\r\r\r\n\r\r\r\n', '', '标书要求的资质证书和准确的价格，第一阶段是资格预审，电力公司从中选出符合要求的候选公司进入报价阶段', '技术规格要求不是很严苛，不要求开投标保函，值得尝试。同时，尽快找一个实力雄厚的代理，可以考虑联合投标，由代理参与运作和项目跟进。', '何森华2019-01-03 11:13:35', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('246', '{067ADE6F-0BE4-4AC6-AAC4-58FD1343343C}', '66', 'INHE-0634', '2019-01-09 17:25:04', '0000-00-00 00:00:00', '2019-01-15 08:48:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019010901/SOP', '', '26(T)/ ESE/ 18-19 (1 Year)', '2019年2月4日', '26(T)/ ESE/ 18-19 (1 Year)', 'DDP Mandalay & DDP Yangon ；(付款条件仍需沟通洽谈)；质保期5年；交期：10% 60天内；90%120天内。', '', '流程分别为：标书审核+样机测试+价格对比；通过标书审核和样机测试后，价低者胜。', '', '价低者胜，不限制几家中标。', '', '投标保函：≥报价总额的1%', '', '无特别要求。', '', '需要独立第三方实验室出具的型式测试报告以及DLMS证书', '', '代理投标，银河供货', '', '', '', '待定', '', '', '', '本代理公司做的项目主要是边境电力设备项目，在本招标方ESE中有过供货经验。与我联系的项目负责人信息及时，相应态度积极，思路清晰，是个精干之人。更多情况有待进一步了解。', '', '', '', '主要竞争对手为中国厂商，华立、科陆、青岛乾程以及许多国际市场上的新面孔。', '', '银河有过供货经验，电力局熟悉了解我司产品和服务，此为我方优势；但是本项目最关键还是价格，电力局的要求非常清晰，在电力局实验室测试发现不了产品瑕疵的情况下，选择价格最便宜的供应商。', '', '拿出最有竞争力的价格', '本项目合作方目前有2家，ICT以及NBL项目合作过的KMN，最终选择与谁合作有待进一步考察商榷。在投标资料和样机上银河问题不大，中标的希望明确可见，建议立项，抓紧着手安排投标事宜，争取占有本市场。', '陈雁2019-01-10 08:44:14', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('247', '{993F4C1B-FEDC-4B7A-A7F3-1152E29ABDD4}', '60', 'INHE-0680', '2019-01-10 15:14:44', '0000-00-00 00:00:00', '2019-02-27 18:11:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011001/POS', '', '190222146491403', '2019年3月15日', 'POS', 'DDP,赊销，货物接收后3个月内付清100%，交货期为签合同后2个月内', '{993F4C1BFEDC4B7AA7F31152E29ABDD48442F4C2B3234363A3D51C033076BD50}_POS 招标通知.pdf', '价格，技术，投标资质', '', '1家', '', '1）银河提供投标保证金（现金或转账）：金额 4000 USD等值当地货币 （预计退回需要3-6个月）或银河提供投标保证金（保函）：金额 4000 USD， 有效期:截标后30天。2）截标前上存扫描件和原件交给招标方；3）履约保证金：合同金额2%；', '', '1）公司营业执照2）章程3）17-18年同类型产品,三相直通模块表（GSM模块），三相CT表（GSM模块）供货合同2个，总金额不少于40万USD和用户证明4）过去两年经审计过的财报5）授权投标证明6）无关系申明7）检测证明8）投标申请函9）授权盛燕签字投标文件证明10）投标保证金：  4000USD', '', '截标前上存所有投标文件电子档,所有投标文件需要俄语', '', '银河投标', '', '电力公司总经理决定', '', '按合同接收货物后3个月内付100%', '', '电价0.07元/度，收益偏低', '', '', '', '银河已经和业主建立客户关系', '', '海兴2018年供货数量和价格：\r\r\r\n   \r\r\r\n   a) 三相直通表HXE 310（DDP价格：84.62USD/台），\r\r\r\n   b) CT表 HXF 300 3х5(7.5)A 380V（DDP价格：86.24USD/台）\r\r\n', '', '电力公司总经理协助银河中标', '', '按时提交样机，提交投标保证金，派客服人员前往协助测试，', '1）POS项目之前未通过，现在再次重新立项\r；\r\r\n2）DDP条款下的赊销控制风险，分批发货，收到上一批货款后再发下一批货物；\r\r\r\n3）POS不再申请样机，直接使用EOS制作的样机投标。\r\r\n\r\r\r\n\r\r\r\n\r\r\r\n\r\r\r\n', '陈嘉豪2019-02-26 16:00:31', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('248', '{49B88925-524C-43EC-813C-872C0CF6BDFA}', '61', 'INHE-0593', '2019-01-11 11:35:13', '0000-00-00 00:00:00', '2019-01-15 09:04:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011101/SBB', '', 'PP2-COM-SE-05', '2019/2/18', 'MCC（千禧年发展组织）为SBEE（贝宁国家电力公司）用户采购及安装智能通信电表项目', '交期：合同签订后的85-105天超过最迟交期后每周罚款合同总金额的0.5%当罚款金额达到5%时取消订单付款：预付款：合同签订后收到等额的买方认可的履约保函后付款合同总金额10%装船时：收到相关文件后，支付合同金额60%实施： 项目产品整体投入使用后，支付合同金额25%验收：项目被MCA-贝宁验收后，支付尾款5%', '', '1. 要符合招标文件的要求；2.价格最低者中标', '', '一家中标', '', '投标保函：15000 USD 截标日后148天有效履约保函：收到授标函14天内开出履约保函，履约保函金额未提及，货物验收后，履约保函金额可以降低至订单总金额的5%；整体项目验收后28天内，履约保函将会退回给供货商。', '', '常规要求', '', '需要商务组协助投标资料制作', '', '讨论中，建议银河授权代理SGE投标', '无', '美国政府影响大', '', '代理付款银河流程较为简单，双方协商付款方式即可', '', '此次招标资金来源为MCC 银河与代理结算，代理财务状况较为稳定', '', '该国为代理老家，尽管如此，代理多次表示该国一切都不正常，电力公司更是无赖。但是代理还是对该国项目十分上心，积极参与投标竞争。						\r\n', '', '银河目前暂无人前往过该国运作项目及接触电力公司。', '', '该国有较多中国厂商及法国厂商涉足，已知海兴，科陆在该市场均供过货，竞争非常激烈。', '', '支持代理投标，参与到BN当地的竞争。', '', '强有力的客户关系；投标文件准确，美观；对项目中的产品需要理解正确。', '支持立项，BN市场要努力拿单。', '胡蝶2019-01-11 14:06:29', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('249', '{E0BCA216-315E-4B63-B178-A472E988B355}', '61', 'INHE-0776', '2019-01-11 17:08:29', '0000-00-00 00:00:00', '2019-01-14 10:32:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011102/PAW', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '我公司现未在巴拿马市场有供货记录，此项目为巴拿马电力公司ENSA的选择性私标项目，两家代理都想获取我司报价参与此次私标，如果项目能成功，对后面同代理的合作和了解并进入该国市场具有开山作用。', '李玟2019-01-11 18:36:24', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('250', '{0A73DBF3-0DF0-4B77-91B5-C9CA4B4AD0CB}', '61', 'INHE-0381', '2019-01-15 14:30:51', '0000-00-00 00:00:00', '2019-01-28 10:38:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011501/GNE', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '需要研发-软件事业部的支持，对此接口进行开发和服务。', '1.此需求是针对电力公司现有后付费系统以及预付费系统（银河SVA）做接口，便于电力公司管理所有的用户。需要软件事业部的支持。\r\r\r\r\r\r\r\r\r\r\n2.GN市场2015年银河实施了smartvend、agent、messenger系统，但是预付费用户并不多，用户抵触性较大，随后2年电力公司主要是安装库存的20万只电表，并未采购新电表。3.GNC中标81000台电表；接下来该市场有20万台的电表招投标；2019年10月，法国控股公司VEOLIA将结束电力公司的经营权，将由EDG电力公司自己营运。目前该软件接口的需求是个很好的契机，可以再次去接触电力公司并经营客户关系。\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n', '张柳芳2019-01-16 18:03:42', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('251', '{54167DB8-380E-4FEC-AF16-78E408473D9C}', '60', 'INHE-0535', '2019-01-15 17:30:17', '0000-00-00 00:00:00', '2019-01-28 10:46:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011502/JBV', 'JBV', 'XXX/PR/JBVNL/2018-19', '2019.02.07 16:00IST', 'Engineering, Design, Supply, Installation and O&M Support for 60 months of AMI System including AMI Software Applications, RF Canopy & Smart Meters for 3.5 Lakh (approx.) Consumers in Ranchi District of JBVNL, Jharkhand (INDIA)AMI系统的工程，设计，供应，安装和60个月的O&M支持，包括AMI软件应用程序，RF canopy和印度Jharkhand邦的JBVNL电力公司下的Ranchi地区的35万台智能电表。', '价格条款：FOR(含GST)付款主体：JBVNL付款条款：1）产品和设备：10%预付款；60%货到付款；20%HES数据抄读成功后付款；5%用户数据报告提交，及阶段性验收证明开立后付款；5%项目完工证明后付款。2）设计服务：10%预付款；90%设计验收后付款；3）安装服务：10%预付款；80%相应工作量完成后付款；5%运营验收后付款；5%项目完工验收后付款；4）运维和设备管理服务：每季度末25%。交期：2年执行期分4个阶段执行，60个月运维期', '{54167DB8380E4FECAF1678E408473D9C8442F4C2B3234363A3D51C033076BD50}_Terms of payment.pdf', '技术标通过后，开价格标；', '', '1家中标，1个lot', '', '此标为本地招标，保函由银河当地合作伙伴开立', '', '财务资质：过去5年财务报告显示长期盈利性；过去3年最小平均营业额INR1943million/USD28Million#FE54`现金流 INR194Million#FE54`技术资质：承包商，供应商或JV要求：制造或供应电表至少10年；至少1种电表满足IS16444标准；过去3年在印度有表计维修处；有印度NABL认证实验室；有ISO9001:2008证书或CMMI Level 3证书；过去7年制造或供应至少110万只电表，其中至少30万台三相全电流电表，2.5万台LTCT或HTCT表；过去7年在电力公司制造或供应至少18万只AMR/AMI表，其中投标人至少安装和调试3.6万台AMI/AMR表，上述项目合同需要包括MDAS或HES应用安装；过去7年成功为电力公司至少362000个智能计量节点供应安装和调试符合IPV4/V6通讯协议（包括NIC，网络元件和相应软件如HES,NMS）的RF Mesh基础设施，并成功运行至少1年，RF mesh技术兼容至少2家制造商的表；', '{54167DB8380E4FECAF1678E408473D9C03404677E4D44E9EB56B3D512B2AF9CC}_Evaluation & Qualification Criteria.pdf', '财务资料，技术资料（证书，合同，用户证明，供货记录等）；业务将会与客户沟通申请延标，视延标情况提交投标资料', '', '代理商投标（本地招标）', '', '地方电力公司自主招标，不受政府决策影响', '', '待与客户商议投标策略及合作细节', '', '', '', '', '', '由于该招标已发出，银河在该市场的代理可协助在标书问题澄清及评标环节协助银河或客户；', '', '由于是本地招标，竞争对手多是本地企业', '', '本地招标，银河必须通过本地企业进行投标；\r\r\n但该项目涉及智能电表和HES软件，可与客户绑定；\r\n代理有良好关系可协助中标；', '', '需要支持：符合IS标准的RF通讯模块表；\r\r\r\r\nRF Band: 865-867 \r\rMHz for sub-GHz c\r\rards (subject to WPC/DOT compliance)\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\nRF Standard\r\r\r\r\r\r\r：IEEE 802.15.4g\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\n', '与客户的详细合作方式尚未确定，可申请延标，延标过程中确定如何合作；\r\n无样机要求，但需要至少一种产品满足IS16444标准，可尝试澄清修改为投标人在规定时间内获取并提交认证证书；', '左亚楠2019-01-15 19:28:25', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('252', '{817628A6-713C-4365-86AD-3284EC19F0A2}', '60', 'INHE-0535', '2019-01-15 19:29:14', '0000-00-00 00:00:00', '2019-01-28 10:54:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011503/UPD', 'UPD', '', '招标通知尚未发出', '', '付款条款：UP电力公司开立一个2个月账单额的不可撤销的循环信用证(账单额由投标人提供)。信用证金额将根据投标人提出的修改后的帐单额予以提高，在2个月预估账单金额有效期届满时自动更新。信用证开办费和续签费将由投标人承担。交期：分2阶段执行：项目执行期：LOI后6个月动员期包括BIS证书，12个月部署期；FMS服务期：7年服务期，经双方同意，可继续延长2年。', '', '技术标通过后（75分以上）开财务标；技术标评标期间分数达40分的投标人要求向电力公司做方案演示；价格排名L1的投标人最多供应2个电力公司；', '', '', '', '', '', '可单独投标或联合投标；联合投标伙伴最好为智能电表或预付费电表的OEM。财务资质：过去5年内盈利最好的3年的年平均营业额达INR500crores/USD70million#FE54`过去3年流动资产达INR10crores/USD1.5million#FE54`技术资质：过去3年内在印度或全球电力公司成功实施至少5万用户基础的智能/预付费计量解决方案；过去3年内在印度或全球电力公司有5万用户的安装和FMS服务经验；投标人需经营过一个超过2年的25万用户基础上的计量和账单系统；ISO9001#FE54`BIS认证；提供投标人制造工厂的测试设备详细信息及设备修调证书；', '', '', '', '银河投标或联合投标', '', '', '', '', '', '', '', '', '', '代理与UP邦交流较深，参与此标的草标拟写过程，可适当采取银河对标书要求的建议', '', 'Genus, Seucre及本地诸多小企业，Hexing等', '', 'UP邦希望聘请代理为该项目的评标方，如果银河确认参与投标，代理可在该项目评标中提供相应协助；\r\n各种产品的BIS认证依然要尽快进行并拿到证书；', '', '需要支持：产品准备', '该项目产品要求GSM/RF/3G/4G通讯；\r\r\r\r\n系统标另外单独招，要求此项目的表计产品可与电力公司另外招标的HES/MDM兼容；\r\r\r\r\n表计可在智能预付费，后付费，净计量模式下工作，至少每天发送一次电表每小时的数据给电力公司的HES/MDM/billing系统，可远程通断电。\r\r\r\n\r\r\r\n但目前此招标通知尚未正式发出，只有草标，如何投标，与谁投标尚不确定，银河可先做产品方面的准备。\r\n电力公司循环信用证付款方式可与代理商议修改或发澄清函给UP电力公司尝试修改。', '左亚楠2019-01-15 21:30:03', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('253', '{456894F8-10EE-458B-951E-4793D0A52BCB}', '66', 'INHE-0774', '2019-01-18 13:48:54', '0000-00-00 00:00:00', '2019-01-28 11:13:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011801/HRV', '', 'DD-V-48/18-D2', '未定（还未发标，代理预计19年3月份发标）', 'OPEN PUBLIC PROCUREMENT PROCEDUREDocumentation on the purchase of goodsOne phase and three phase electronic meter with GPRS COMMUNICATION (公共采购程序-关于采购单相和三相GPRS通信电能表的文件)', '（1）价格条款：DDP Warehouses Distribution areas of HEP ODS （2）交期：订单生效起45天内（3）付款条件：客户收到发票起60天内付款，如截止日期之后付款，供应商有权从第61天开始到付款日按6%的年利率计算利息。（4）质保至少3年，电表寿命至少16年', '{456894F810EE458B951E4793D0A52BCB8442F4C2B3234363A3D51C033076BD50}_DON_Jednofazna_i_trofazna_elektronicka_kombi_brojila_ EN.pdf', '最具经济优势原则', '', '一个LOT', '', '（1）投标保函：1,579,000.00克罗地亚库纳(约213000欧元)，不小于offer期限（4个月）（2）履约保函：合同生效5天内提供不少于合同金额10%的履约保函，期限至少比合约期限（24个月）长30天（3）质保保函：履约保函到期前10天内，提供合同金额10%的质保保函', '', '（1）需提供欧盟实验室出具的形式测试报告（type tests and approval issued by Croatian State office for metrology, based on the test peformed by any certified laboratory (They prefer to have test performed in EU laboratories)（2）满足标书中规定金额的供货记录', '', 'ESDP(European Single Procurement Documentation Form)', '', '银河投标（暂定）', '', '', '', '客户收到发票起60天内付款，如截止日期之后付款，供应商有权从第61天开始到付款日按6%的年利率计算利息。', '', '项目预算约700万欧元（52.650.000,00 克罗地亚库纳）', '', '目前联系的代理刚开了自己的一个咨询公司，跟电力公司电表部门负责人有关系，可以私下联系获取一些信息；可以帮我们和RIZ建立联系讨论合作', '', '', '', '对手：Iskraemeco(2017年安装了45000台PLC,GPRS通信智能电表)，L&G and RIZ（本土表厂，得到电力公司HEP支持，但是技术落后）；大概2015年的时候中兴投过标，价格最低，但是项目后来取消了', '', '代理建议和RIZ合作，电力公司HEP支持RIZ，但是RIZ没有新的电表技术，研发比较落后，如果RIZ要继续和电力公司合作的话，需要发展技术，现在RIZ没有研发实力，代理可以建立银河和RIZ的联系。\r\r\r\n我们的难点在于语言障碍（标书全是克罗地亚语，投标文件要求克罗地亚语），满足4款表的证书要求，也需要一个积极配合的合作方及时提供准确有效的市场信息，代理投标银河配合会更容易\r\r\r\n\r\r\r\n', '', '需提供欧盟实验室出具的形式测试报告（type tests and approval issued by Croatian State office for metrology, based on the test peformed by any certified laboratory (They prefer to have test performed in EU laboratories)', '克罗地亚用电用户230万，欧盟倡议的智能电表部署成本-效益分析结果是Positive,政府也支持，希望2030年前为所有用户安装智能电表，目前正处于初步阶段，可以作为银河打入欧洲市场的一个突破口。建议和克罗地亚本土公司RIZ一起探讨合作的可能性，这样成功的几率比较大', '何森华2019-01-24 18:43:00', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('254', '{96270AE6-9A60-4947-A346-3430D686B539}', '60', 'INHE-0790', '2019-01-22 08:53:00', '0000-00-00 00:00:00', '2019-01-28 11:05:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012201/MGM', '', '-', '-', '-', '本项目为私人项目，无标书。', '', '-', '', '-', '', '-', '', '-', '', '-', '', '-', '-', '此项目为阿曼最大商场Grand Mall的采购项目。非电力公司项目。', '', '待定', '', '-', '', '-', '', 'Abdelhamied Nashabat，是银河老代理，16年和18年都有合作过的项目。', '', '-', '', '跟据之前出差的结果，目前，整个阿曼的市场需求大概在100万到120万左右，用以替换以前的老表，并且目前大部分还是机械表，约占70%。此私人项目可以为银河以后在该市场的发展与竞争建立基础和摸清状况。并且客户表示表型与我们18年报价的表型相差不大，契合度高。\r\n								\r\n', '', '此项目是私人项目。运作和报价很重要；另外配合态度也很关键，我们需要及时回复并提供技术支持。', '此项目是阿曼客户的一个私人项目，为阿曼最大的商场提供三相表、CT表和配套预付费软件以及方案。由银河一个老代理发来需求。2018年10月份银河就三相表跟客户报过价（参考OMH项目）。后来因客户18年预算问题项目叫停，本次新增CT表需求，第二次找银河询价。代理与商场管理高层关系比较密切，运作的空间非常大，且需求表与银河产品契合度高，可以尝试立项竞争。\r\n', '莫亚检2019-01-22 09:30:28', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('255', '{E50A5879-68AC-45A3-974A-F96EF7ABFB52}', '61', 'INHE-0500', '2019-01-22 14:15:56', '0000-00-00 00:00:00', '2019-01-28 11:35:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012202/LTM', '', 'LTLM2018-19/BTO01', '2019年1月31日', 'APPOINTMENT OF A SERVICE PROVIDER FOR THE PROVISION OF ACOMPLETE TURNKEY REVENUE ENHANCEMENT SERVICE, ONLINE ANDREAL TIME ELECTRICITY VENDING, REVENUE PROTECTION, ICT BACKENDAND METERING AT LEKWA-TEEMANE LOCAL MUNICIPALITY FOR THEPERIOD OF 36 MONTHS.委任一名服务商提供全套保障市政收入交钥匙项目，项目涵盖在线售电和管理、收入保障管理、后端信息通讯技术，合同周期36个月', '三年期框架供货协议；报价为DPP含VAT价格；付款主体：Lekwa-Teemane Local Municipality；                                                    交期：60天内完成新系统的替换、数据迁移、第三方平台接入、培训、试运行和全运行；                                                          付款条款：服务供应商在每月度完成收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；                 质保和违约：服务商和市政公司签订SLA服务协议，系统涉及的硬件和软件满足36个月质保。', '', '评标分为四个流程：1.基础资料评审：购买标书和参加标前会议的凭证、市政招标政府固定的固定格式表格（CSD证书等）；2.技术资料评标，100%满足标书中的Work Flow Management System，80&满足技术标书中售电和集抄系统；3.价格评审，按照BBBEE资质90/10的偏好打分，BBBEE最高资质有10分偏好；4.演示评审：技术评审和价格评审的合格服务商进入到短名单，进行现场系统演示，最终决定中标服务商。', '', '一家系统服务商中标', '', '投标无需开立保函，中标后由投标人开立履约保函', '', '投标人至少5年以上相关ICT系统的研发和销售经验，至少有50名ICT软件类研发人员；', '', '需要客服部协助尽快完成技术解析，尤其是标书中第一步部分关于Work Flow Management的解析工作，并提供对应的系统解决方案和项目实施方案', '', '代理NYC投标，银河做厂商支持', 'N/A', '市政公司自行决定评标全流程，评标委员会由财务部成员+采购部成员+电力分支负责人组成，中标的最终价格需要参考财务部CFO审批\r\r\n', '', '付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；\r\n', '', '市政公司2017年年度电费收入：68 987 805 兰特\r\r\r\r\r\n市政公司2017年水费收入：49 597 629 兰特\r\r\r\r\n', '', 'NYC优势：BBBEE资质10分偏好优势；愿意在本地投入运维客服中心（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案\rNYC劣势：第一次在次市政投标，无内部客户关系和支持。\r\r\r\r\n', '', '新市政公司客户，第一次投标，暂无客户关系，需要在此次投标完成后春节过去现场后拜访客户，拓展客服关系', '', '暂无竞争对手信息，有待跟进了解', '', 'NYC优势：1.BBBEE资质10分偏好优势；2.愿意在本地投入运维客服中心（强制性要求）；3.积累了一定的财力和实力，可以提供更优的融资方案；\r             NYC劣势：1.第一次在次市政投标，无内部客户关系和支持。2.关于标书要求的工作流程管理系统，需要软件部进行评审是否有对应的应标系统，如没有需要评估开发周期和难度。                                                     \r\r\r\r\r\n竞争策略：1.节后业务到现场需要适时拜访此市政公司，进一步了解竞争对手状况、市政公司实际需求和其他相关商务和技术问题，并未演示做准备，同时得到市政公司客户关系的支持；\r\r\r\r\r2.公司技术支持需要针对招标要求细致评估所需系统平台，提前做好演示的准备。\r\r\n\r\r\n', '', '1.公司技术评审，有合适的应标系统平台；\r\n2.业务现场的客户关系拓展', '此项目不同于之前此市场的售电系统招标，涵盖智能预付费电表和水表+工作流程管理平台+集抄平台+售电平台+账单管理平台的EPC项目，为银河在此市场推进和扩大系统类EPC项目具有很好的标杆性作用，希望软件部和客服部大力支持提供完整和技术方案和提前做好演示准备。', '李忠鹏2019-01-22 15:29:20', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('256', '{7DB31E83-57AC-421A-8D07-3E4E9E18C4FF}', '61', 'INHE-0793', '2019-01-23 10:37:26', '0000-00-00 00:00:00', '2019-01-28 11:44:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012302/PUM\r\n', '瑞典市场Vattenfall电力公司投标项目', 'ND-Av-02405', '2019/3/1', 'Projekt for Utrullning av Matare AMR  采购电表及AMR集抄系统的招标项目', '瑞典电力公司价格条款为30%TT预付款，50%合同期间内货到付款，20%尾款在合同完结偿付。我司的付款主体为Trilliant,其将采购我司电表，付款条件方面目前议定是30%TT预付款，70%不可撤销即期保兑信用证。交期无限制，该项为权重计分项，由我司提供交期时间，视交期不同，得分不同。质保也遵守上述条约。例如：小于两个月为3分，2-3个月之间为2分，3-4个月之间为1分，超过四个月为零分。质保期限同理。违约条款最主要的是质量方面，如出现问题，将被取消供货资格并视情节严重度按合同总金额进行比例赔偿。', '{7DB31E8357AC421A8D073E4E9E18C4FF8442F4C2B3234363A3D51C033076BD50}_A.1 - General Tender Directions (5).pdf', '项目评标规则较复杂，分为两个Package,每个Package分四个部分，由所有的技术，商务，价格，物流，安装，售后，服务等条款以权重计分。总分2000分，由两个Package合并计算，得分最高者胜出，详情请看标书。因我司直接合作方为Trilliant,所以评标方面将由Trilliant制作策略，我司协助。', '', 'Vattenfall会视情况选择供应商，或一家，或几家合并，暂无定数，分数最高者胜出。', '', '该项由代理开出，无需我司处理。', '', '该项由代理处理。', '', '投标资料要求技术应答表，商务文件等，最迟需2月20日提交', '', '代理商投标，银河作为二级供应商。', '非联合投标\r\n', '政府对该电力公司的项目可能会视政策变化而进行干预，该干预有100%的影响力，会直接导致该项目中止或取消，因为该电力公司为政府全资。但据目前情形，瑞典政府换表政策是大势所趋，正常情况下不会出现政府强行干预。\r\r\n', '', '因为我司直接客户为代理（Trilliant）,目前议定是30%TT预付款，70%不可撤销即期保兑信用证。后期可以视情况再争取更好条款。\r\n', '', 'Trilliant支付能力较好（我司已和该公司有过合作），合作可信度较高。\r\r\n', '', 'Trilliant是全球知名公司，在多个国家都有设立分部，本项目直接联系人Par在北欧已经营多年，和当地大电力公司Vattenfall,EON,EllEVIO都有非常密切的关系。因为之前与我司有过合作，所以此人能力，可信度，能调动的资源都值得肯定。综合来看，我司本次项目的合作伙伴PAR竞争力较强，赢面较大。\r\n', '', '该客户和我司已有合作，业务方面本人在联系上后一直有持续交流，目前关系较融洽。', '', '该市场的可能对手有AIDON，ITRON，Landis+Gyr等等很多，因为项目很大，而且是欧洲，所以竞争必然十分激烈。其中AIDON方面我司有过接触，其业务在北欧扎根已久，而且与各大电力公司也有联系，值得重视。其他公司已是我司老对手，可以根据实际情况制定相应策略。\r\n', '', '银河在该项目中优势有：1，不需直接投标，绕开准入门槛。2，代理实力强，靠谱，且关系尚佳。3，一代单相模块表已通过MID认证，可以参标。劣势：1，一代三相模块表和CT表尚未通过MID认证，需加紧推进。2，部分资质未达标。3，时值春节，中间有大量时间无法运作项目。综上所述，两相权衡，我司优大于劣，该项目利益可观，也符合公司发展观，值得奋力一搏。业务将持续跟进，协调能调动的资源，尽己所能，希望公司给予支持。\r\r\n', '', '该项目成功关键在于：1，合适的报价，因为该项目权重计分的比重最大的就在价格部分（公司可视欧洲市场情况适当调整价格）。2，技术部门的充分支持。3，公司经济投入（很可能要尽快去瑞典出差）。4，后期竞标运作中的公司技术，商务等支持。\r\n', '我司公司的发展方向一直倾向于欧洲，这也是世界一流大企的发展战略，经营多年后，目前我司欧洲市场，尤其是北欧部分的基础已较为成熟；目前该项目，金主资金雄厚，有钱；伙伴靠谱，有能力；我司实力，足够。故而业务建议可以抓住机会，竭尽全力，奋手一搏，抓住一切机会为公司创造价值，并楔进欧洲一个角，融化欧洲市场这整座冰山。\r\n', '辛方腾2019-01-23 14:59:43', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('257', '{2B53F0BC-D278-4404-ACD8-61E4F509ED36}', '61', 'INHE-0719', '2019-01-23 13:31:59', '0000-00-00 00:00:00', '2019-01-28 11:54:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012304/PLD', '三相直通表建议价格过低，请和客户重新沟通，建议调价110美元以上。具体价格，请申请公司审批。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.秘鲁市场是南美重要贸易口岸之一，业务认为可以先从试点做起，一步步地进入市场，此试点项目已经跟电力公司，跟代理都沟通过，双方都比较满意，是公司来说是个好机会，立项通过后，业务也会加紧执行，尽快收好预付款，然后开始备料生产。                                                   2.此项目建议价格不高，是因为进入该市场的电表，认证费用较高，代理需要承担比较多的责任和费用，且该市场的竞争比较激烈，经过反复沟通，双方目标都是一致的，力求先打开市场，多占据市场份额。             3.客户要求质保两年，出具质保函，并注明会提供售后服务和质保，（此市场一般要求质保都为2-3年），业务建议可以同意。                                                                    4.代理方有一份采购单，需要签字盖章，业务已经看过，无特殊要求，此后会发出来。		\r\r\r\n\r\r\r\n               ', '林丽君2019-01-26 09:55:58', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('258', '{18341A1B-E004-4F1F-8523-572FD245FBC9}', '61', 'INHE-0500', '2019-01-25 11:09:49', '0000-00-00 00:00:00', '2019-01-26 17:42:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012501/MLM', '', '1/2/2/2018-19', '2019年2月15日 12AM SA时间', 'Online Vending System and Third Party Vending for a period of Three Years三年期框架招标，STS在线预付费售电和第三方售电系统', '三年期框架供货协议；报价为DPP含VAT价格；付款主体：Moqhaka Local Municipality；         交期：PO下达后3个月内完成新售电系统的替换、数据迁移、第三方售电平台接入、培训、试运行和全运行；                        付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；               质保和违约：服务商和市政公司签订SLA服务协议，关于具体的违约和服务故障处罚需要待中标和市政公司协商确认。', '', '第一阶段评审：售电系统功能性投标审核，需要至少70%满足标书所列的技术要求，才有资格进入到第二阶段的预合格评审，此项评审主要以商务条件、报价以及相关资质要求审核；第三阶段：按照标书要求现场实操演示。', '', '一家系统服务商中标', '', '无需开立投标保函，中标后需要开立履约保函和收入保险凭证', '', '1.投标人需要是南非本地BBBEE资质的企业，并且和市政有至少1一年的业务往来，超过5年以上业务往来经验基础评分才为满分，依次递减；2.投标人至少有一名客户现场服务的项目经理，超过8名以上的项目经理基础评分为满分，依次递减，需要提供CV和现场服务用户证明；3.投标人需要有STS售电系统证书以及和其他市政公司现有账单系统或其他第三方接口证明文件；4.需要至少在市政公司所在省份设有客服服务支持点。', '', '1.需要客服和软件部同事提供完整涵盖标书技术要求的 技术方案+技术应标表+项目实施计划表（Microsoft Projector格式），以及需要澄清的问题点；2.需要申请商务协助完整商务和技术投标资料的审核和整合。', '', '代理NYC直接投标，银河做服务支持', 'N/A ', '市政公司自行决定评标全流程，评标委员会由市政指定的技术代理+财务部成员+采购部成员+电力分支负责人组成，中标的最终价格需要参考财务部审批的年初预算\r\n', '', '付款条款：服务供应商在每月度完成电费收入统计确认并提交相关凭证后提交月度含税发票给市政公司，市政公司在收到发票的30天内完成付款；				\r\n', '', '2017年电费总计收入255 592 385兰特，2017年配电侧收入损失为 38 582 954兰特，配电线损约15.5%。按照预付费用户35%的比例电费收入折合估算，2017年的预付费电费收入为：9千万兰特。\r\r\r\n', '', 'NYC优势：此项目合同金额预估在2千万兰特以上，NYC有BBBEE资质20分偏好优势；愿意在本地投入技术服务驻点（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案；李忠鹏在2018年11月和NYC一起拜访了此市政公司电力负责人，银河+NYC的知名度有一定提升。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\nNYC劣势：人员资源有限，业务人员客户管理和项目经验不足，需要银河年后尽快安排现场协助和组织客户关系突击。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n', '', '李忠鹏在2018年11月和NYC一起拜访了此市政公司电力部门负责人，做了电表、集抄和售电系统方面的展示，初步结识了相关团队负责人，需要借助此项目加强和客户的沟通和关系的深入', '', '1.当前市政公司的电表主要使用Conlog和兰吉尔，售电系统为Syntell供应，海兴有对此市政做过宣讲和公关，暂时未进入供货范畴；\r\n2.此市政公司为白人管辖，政策透明度较高，但在供应商方面较为偏袒当地白人企业。', '', '银河+NYC优势：此项目合同金额预估在2千万兰特以上，NYC有BBBEE资质20分偏好优势；愿意在本地投入技术服务驻点（强制性要求）；积累了一定的财力和实力，可以提供更优的融资方案；李忠鹏在2018年11月和NYC一起拜访了此市政公司电力负责人，客户关系和银河+NYC的知名度有一定积累；此市政公司为自由州省用户数量和经济发展水平较高的市政，管理和评标透明度相对较高，且离NYC距离不远，沟通和拜访较为方便\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n						\r\r\r\r\r\n', '', '1.精准提供应标资料，年后技术演示提前做好规划；\r\n2.业务在年后需要组织NYC突击市政公司客户关系，得到认可和支持。', 'STS售电系统招标，技术规格基本满足，请领导评审！', '李忠鹏2019-01-25 11:50:33', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('259', '{262065F3-302E-4E6D-8474-1413626B208A}', '60', 'INHE-0781', '2019-01-26 17:01:47', '0000-00-00 00:00:00', '2019-02-26 16:56:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012602/PDC', '', '87.106.315.00.00.256.2019.1105', '2019.3.4', 'DESIGN, SUPPLY, INSTALLATION, TESTING &COMMISSIONING OF ADVANCED METERING INFRASTRUCTURE (AMI) WITH SMART METERING SYSTEM ON TURNKEY BASIS基于交钥匙工程的智能计量系统的先进计量基础设施 (AMI) 的设计、供应、安装、检测和调试。', '1.10% 预付款（an advance payment against receipt of invoice and an irrevocable unconditional advance payment security for the equivalent amount made out in favor of the Employer.）2.20%发货并交单后45天内支付 （shall be paid through LC upon submission of documents. The payment shall be made within forty-five (45) days after receipt of invoice.）3.10%应在提交由买方验收正面支撑的发票后45天内以信用证的方式支付50%根据工程进度分10期付款，每次5%（具体见付款条款2-1，2-2）4.5%签发完工证明后45天内付款；5.5%收到运行接收证明后45天内付款', '{262065F3302E4E6D84741413626B208A8442F4C2B3234363A3D51C033076BD50}_付款条款.rar', '先做资格预审，之后至少提前15天通知做系统演示，至少挂15台表，演示会作为技术评标的一部分。技术评审合格后方开始评商务标，低价者中标。', '', '1个LOT，1家中标', '', '1.投标保函金额750,000USD,有效期180天+28天；2.履约保函：10%合同金额，质保期到期+28天；3.预付款保函：中标通知下达后28天内按预付款全额开保函。', '', '1. 投标人在最近5年内的仲裁数不超过3次。2. 投标人应在当地有代理.3. 一般要求：     a) 若是JVCA，投标人或RF网络供应商，应在两个或以上国家中至少有在3个电力公司成功建立RF通信网络的经验，并在过去5年中至少涵盖100万个端点/智能电表（累计）。 在这些合同中，至少有一份合同的合同金额最少为2000万美元，电表至少为10万台。    b) 若是JVCA，投标人或RF网络供应商，应在过去5年内有在两个或更多国家/地区中成功连接至少3个不同厂商电表的网络接口卡（NIC）/ RF模块/芯片（基于RF）的经验。    c) MDMS供应商应至少有3个来自电力公司/客户的证明，以证明供应商正被使用的MDMS至少100万台表（累计），并且已超过2年。 （至少2个参考证书应来自其它国家）    d) MDMS vendor shall be named in the list of Gartner: Magic Quadrant for Meter Data Management Products for minimum 1 year within last 5 years. M', '', '', '', '联合投标', '此项目必须要求有本地代理，而且收款周期长，流程复杂，需要有代理合作分担风险。此外，对MDMS的资质要求很高，可能需要引进符合资质的合作伙伴。', '此项目资金来源于政府基金和电力公司自有资金，电力部具有很大的影响力。', '', '见第四项付款条件', '', '此项目主要来源于政府资金和电力公司自有资金，孟加拉国政局稳定，经济持续快速增长，电力需求稳步提升，资金来源有保障。', '', '代理在电力公司和电力部有着良好的客户关系，MD个人能力也很强，有着良好的项目运作能力。', '', '银河在业主那已有合作项目，已具备一定的客户关系。', '', '海兴、科陆、思达等常见对手，此外因此项目对软件系统要求很高，而且内部消息系统这一块的预算有300万美金，业主方比较倾向于采购欧美厂家的系统，因此估计会有很多表厂与系统厂商合作投标。', '', '1.银河拥有孟加拉第一个大规模智能表项目的中标、供货经验；也有大规模RF表和系统的供货、实施经验；\r\n2.代理在政府和电力公司具有良好的关系。', '', '1.需要与代理尽快达成商务合作协议，以便尽快开始项目运作；\r\r\n2.对软件系统的要求很多，需要技术部门集中精干力量，对照标书要求一项项过，务必确保我们能提供合适产品。', '此项目要求复杂，条款苛刻，但项目最终有85万台的规模，体量庞大，建议还是尽量努力争取。', '李启坦2019-02-12 20:23:36', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('260', '{09FAB089-37F4-4626-9122-162B768C4165}', '66', 'INHE-0634', '2019-02-11 15:28:46', '0000-00-00 00:00:00', '2019-02-18 13:52:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021102/RMY', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Sipromad Group这家公司是马达加斯加最大的财团，实力较强，已经为马达加斯加电力局近期的电表招标项目（5万台预付费电表+5千台预付费电表）起草好了一份技术规格文件，本周五会递交电力局，我要求其将技术规格先发给我司做适当修改，客户表示必须明确双方之间的合作关系,签订MOU后才能进一步透露更多信息，客户的要求也是情有可原。该客户知道我们曾经出现在马达加斯加，与一家叫vision madagascar有过合作。电力局计划是在这两个月内就要发标，我们需要动作迅速，尽快决定是否与Sipromad Group合作运作马达加斯加最新项目。如果公司内部没有冲突，建议立项。', '陈雁2019-02-11 15:52:30', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('261', '{5FA97344-E465-46E9-9600-B88E6D7EEA3C}', '61', 'INHE-0772', '2019-02-13 00:28:12', '0000-00-00 00:00:00', '2019-02-18 13:44:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021302/GBB', '', '', '2019.02.26', 'RFQ FOR THE PROCUREMENT OF GPS HANDHELD DEVICES AND DATABASE DESIGN FOR CUSTOMER AND ASSET INFORMATION 手持GPS终端采购与客户与资产信息数据库设计 询价单', '交期：签约后四周内；付款条件：20%签约款，设备运输后付40 20% payment upon Contract signature,40% payment upon delivery of equipment and 50% of tasks executed andFinal 20% payment upon satisfactory completion of assignment', '', '议标', '', '', '', '不需要', '', '无要求，相关供货记录和项目验收文件作为参考文件', '', 'Submission of Quotations shall be made at the Project Management Unit Office, Emporium 3 Building, on/before February 26th, 2019 at 12:00 Noon. 2019年2月26日中午12点前到EMPORIUM 3号楼 项目管理单元办公室报价。', '', '银河直供，直接参与议标', '', 'NAWEC对决定并监督采购', '', '电力公司评审结果提交到世行审批，同意后，电力公司与供应商签合同，电力公司向世行提交付款申请，世行审批，同意后付款。', '', '', '', '电力公司内部主导该项目评审的为：商务主管Tijan，IT主管Edrisa，IT经理Ebrima 支持银河，另外世行项目组负责人Jallow中立，采购经理Mariama与代理关系亲近。', '', '一线关系与电力公司直接对接，关系较深。项目负责人是张子琦，本项目决策关键是IT部经理Ebrima，对他有多次公关记录，这个项目的文件于1月16号已经提供，另一项目的标书最新版也于2月12晚提供。', '', '正在了解短名单', '', '优势：客户关系到位，中国制造价格优势。劣势：数据库硬件如服务器的后期维护是难点。风险点：当前客户管理系统规划不符合逻辑，对后期执行有较大风险。机遇：我司有较多的项目经验，可给客户提供专业意见。应对办法：安排软件技术支持到现场与客户技术对接，协助客户做好规划，提供确实有效得解决方案和产品，准确报价。', '', '\"优胜核心：合理的价格，有类似项目经验及技术文档质量。报价截至时间为2月26日中午，该客户偏好齐全技术规格文件资料和项目经验记录越多越好。手持终端部分需公司提供报价。数据库设计需望客服部提供\r\r\r技术支持完成文档解析；如有大量技术文档需翻译，则需要商务支持文档翻译。\"								\r\n', '本项目是有世行提供资金的直采项目，邀请少数供应商进行议价直采。综合考虑价格与电力公司的意见选定最终供应商。对后续系统项目有影响。手持终端部分问题不大，数据库设计部分需客服部评估。', '张子琦2019-02-13 11:22:07', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('262', '{56CCF71B-F992-40D5-92E4-2903C56EEEFA}', '61', 'INHE-0431', '2019-02-14 17:58:15', '0000-00-00 00:00:00', '2019-02-18 14:45:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021404/SBM', '', '30/18/19', '2019年3月1日 12点（南非时间）', 'SUPPLY, INSTALLATION AND MANAGEMENT OF A STS COMPLIANT PREPAYMENT ELECTRICITY VENDING SYSTEM FOR THE PERIOD 01 JULY 2019 TO 30 JUNE 2022. 供应、安装STS售电管理软件（为期三年，2019年7月1日至2022年6月30日）', '1.合同内容：三年供应，安装STS信电软件，包括三年期的管理，运维，第三方售电管理，培训等服务2.交期：签署合同后21天内执行完毕3.付款: 供应商提供发票给市政公司后，市政公司收到发票后30天内付款4.质保：SLA服务协议会和合同一起签署，标书并未完全明示违约责任，只提到如果供应商无法按时完成，市政公司有权利终止合同', '', '1.功能评分共计14项（主要是系统功能，实施方案及证书相关），需要得满分才可进入资格评审#FE54`2.资格评审阶段最低得分要求是80/100分#FE54`3.B-BBEE企业享受额外政策（正常报价占比80%，B-BBEE情况占比20%，代理可享受最高等级B-BBEE得分）', '', '一家中标', '', '无投标保函，中标后提交履约保函', '', '1.B-BBEE资质企业享受额外优惠2.除上述功能评分的14分（主要是系统功能，实施方案和相关证书）是必须要满足的，其它的都是打分制，最低得分要求是80/100（主要是市政供货记录，历史年限等）', '', '完整的技术方案+实施方案+相关要求的证书', '', '代理NYC投标，银河支持', '不适用', '市政公司自行决定', '', '供应商按月提供相关凭证，市政公司在收到发票后30天内付款', '', '目前管理19，000用户，年度收款额在12，000，000兰特左右', '', '优势：NYC从2018年下半年起在市政上投入有很大加强，且已经中标过几个小的市政，在2019年会和代理一起加强市政方面投入\r\r\r\r\n\r\r\r劣势：NYC人员还是较少，已经在增添人员中\r\r\n', '', '目前以NYC为主，2019年Evans出差会更多直接主导', '', '目前使用厂商名称未在标书中明确，后续会和代理核查清楚', '', '优势：NYC在BBBEE资质和本地服务方面有很大优势，Evans在2019年会更多在现场和代理一起做战拜访并做为客情关系\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n劣势：目前NYC在市政的执行项目较少，而很多市政打分都是很看重市政供货记录，201\r\r\r\r\r9年会加强运作，争取多中标，多执行，改善现状\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r', '', '1.优良的投标资料（主要是技术方面）\r\n2.客情关系方面Evans马上出差会在一线加强公关同时和代理一起准备展示\r\n\r\n', 'STS售电系统招标，潜力很大。中标会对其它市政都有良性影响，建议三星立项。', '刘佩2019-02-15 09:31:27', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('263', '{9BCB0F70-9A75-4FA9-95E2-B45EFFB4441D}', '61', 'INHE-0500', '2019-02-15 11:12:37', '0000-00-00 00:00:00', '2019-02-18 11:50:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021501/CDL', '', 'CD59/ 2019', '2019年3月6日南非本地时间11点', 'CD59/ 2019 – CENTLEC (SOC) LTD, A MUNICIPAL ENTITY DISTRIBUTING ELECTRICITY IN MANGAUNG METRO AND OTHER MUNICIPALITIES INVITE BIDDERS TO BID FOR THE SUPPLY AND DELIVERY OF DATA CONCENTRATOR UNITS, ELECTRONIC ENERGY (PREPAYMENT) METERS WITH REMOTE METER READING CAPABILITIES AND CUSTOMER INTERFACE UNITS AS DETAILED IN THE SPECIFICATION BELOW FOR A PERIOD OF THIRTY SIX (36) MONTHS IN CENTLEC AREAS OF SUPPLY三年框架合同，低压普通居民用户单相和三相分体式智能电表和集中器招标', '价格条款：DDP。银河与NYC之间FOB或CIF成交；付款主体：CENTLEC (SOC) Ltd；付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，市政在收到付款证明后30天内支付。银河与NYC结算方式待协商确定。交期、质保：发货后12个月质保，正式PO下达后不晚于6周内交付。', '', '第一阶段：技术资料评审；第二阶段：商务资料评审；第三阶段：BEEEE资格和其他偏好资质评审；第四阶段：样机测试', '', '未限制中标厂商数量，按照惯例，最多三家厂商分表', '', '无需开立投标保函，需要开立履约保函', '', '1.投标公司类似项目供货经验至少1年，满3年总评分满分20；2.在市政管辖区域有本地办公室或者工厂或者服务中心，评分项10分；3.提供ISO9001证书，评分项15分；                                     4.提供至少2个类似项目供货资质证明，3个及以上此项目评分满分；5.需要提供产品寿命测试报告、SABS证书和第三方形式测试报告；6.提供集中器和其他厂商电表兼容成功证明，以及和其他AMR服务商兼容成功证明。', '', '1.需要商务组协助投标资料的制作（除报价外）；2.需要客服协助技术解析和样机规格输出；3.需要研发和实验室配合样机制作和兼容测试。', '', '银河授权NYC投标。', 'N/A', '市政公司组织内部评标委员会（2个来自电力部门，1个来自采购，1个来自财务部门），评标委员会通过预中标名单，最终由Municipality CFO签字通过。\r\r\r\r\n', '', '交货后由电力公司项目负责工程师验收，发布验收合格证后14天内供应商提供付款发票，负责工程师收到发票后14天内出具付款证明，需由CFO签字确认，市政在收到付款证明后30天内支付。\r\r\r\n', '', '2017年年度电费收入为22亿兰特，其中预付费电费收入为7亿兰特，中大型商业工业后付费电费收入为15亿兰特，年度线损10.77%，总计线损金额为1.7亿兰特。技术线损金额为1.1亿兰特，非技术线损金额为6千万兰特；\r', '', 'NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求；NYC在2016年通过ESA DIN表给该市政公司供过1000台电表，在市政公司管理层有一定客户关系。\r\r\r\r\nNYC劣势：技术部门暂无客户关系，需要拓展；市政公司对NYC和银河的公司和产品舒适度较低。\r\r\r\r\r\n', '', 'NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求；NYC在2016年通过ESA DIN表给该市政公司供过1000台电表，在市政公司管理层有一定客户关系。\r\r\r\r\r\nNYC劣势：技术部门暂无客户关系，需要拓展；市政公司对NYC和银河的公司和产品舒适度较低。\r\r\r', '', '电表类主要供应商：兰吉尔，Conlog和海兴\r\r\n售电系统供应商：海兴\r\r\n集抄系统供应商：AURECON Group和Jagertech（PTY）LTD\r\n', '', 'NYC优势：BBBEE资质10分偏好优势；积累了一定的财力和实力，可以提供更优的融资方案；本地工厂满足50%以上的本地生产要求；NYC在2016年通过ESA DIN表给该市政公司供过1000台电表，在市政公司管理层有一定客户关系。\r\r\r\r\r\nNYC劣势：技术部门暂无客户关系，需要拓展；市政公司对NYC和银河的公司和产品舒适度较低。\r\r\r', '', '1.和NYC一起拓展客户内部关系，CFO层面和电力部门技术层面；\r\n2.准备好样机，需要满足市政公司的要求。\r\n', '重要目标市政客户之一，三年期智能电表招标。', '李忠鹏2019-02-15 11:45:41', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('264', '{51AE7243-8981-4546-A833-C5E7076CDB23}', '60', 'INHE-0535', '2019-02-18 00:49:59', '0000-00-00 00:00:00', '2019-02-26 09:28:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021802/JPY', 'JPY', 'EESL/06/ICB-Smart Meters-Pan India/Phase 3/181901035 dated 21-Jan-2019.', '2019.02.27', 'International Competitive Bidding (ICB) for Procurement of 5 million Smart Meters for Pan India.为泛印度采购五百万智能电表的国际竞标。', '付款计划：(收到相关单据后30天内付款。)a) 供应阶段：以下材料抵达指定地点/仓库后支付60%（EESL在收到投标人Tax invoice 和在指定交付地点收到所有要求的经EESL EIC(Engineer-in-charge)/授权代表签字盖章的文件后30天内付款）：1. 提交DLMS标准符合验收，APIs, 数据交换信息和配置图表，测试步骤和型式测试报告。2. 订单验收3. 必要的合同履约保函提交4. PDI报告和物料交付许可证（MDCC）b) 兼容和运行阶段：（兼容和测试案例及用户验收测试成功运行后，MDMS生成一个报告证明电表与HES和MDMS的兼容和运行）：1. 剩余30%凭电表与smart vend解决方案兼容和运行后支付。款项在电表与backend 系统成功兼容3个月后的30天内支付。2. 万一兼容延迟（不是由于供应商的责任），此30%款项在电表供应6个月后的30天内支付（条件是其他批次都没有硬件问题出现）c) 质保阶段：剩余10%款项在EESL运行验收后凭提交的TAX invoice支付(SLA report/EESL项目主管签署的验收报告。付款计划如下)。Year', '{51AE724389814546A833C5E7076CDB238442F4C2B3234363A3D51C033076BD50}_1506.pdf', '1. 先开技术标，技术标通过的厂家才开其价格标；（投标人至少投50%）2. 按价格3家分：L1 最少50%， L2 30%， L3 20%，', '', '按价格3家分：L1 最少50%， L2 30%， L3 20%，', '', '1.投标保函：Rs. 142,400,000 / USD 2,225,000有效期至技术标开标(2018/04/12  IST14:30)后225天；2.履约保函：中标通知给出后 28天后开立，合同价值10%有效期7年：交付期1年+质保期5.5/5年+3个月索赔期+3个月动员/测试期以上由此项目代理JPM负责保函开立', '', '1.为商业个体；可形成联合体，联合体主投标人必须是智能电表或电子元器件制造商；NSIC联合体和PSU政府性质企业除外2. 年平均营业额USD33million(2015-2017)3. 投标人应制造和供应智能/普通电表或其他电子设备至少3年4. 过去5年累计供货500,000只电表', '', '可沿用JPM项目投标资料，更新部分资料抬头，时间；重新申请签字授权；更新产品画册等，最迟2019.02.25提交', '', '联合投标，代理主投', '代理主投，负责全部投标文件整理和电子投标，直接与电力公司签订供货合同，收取项目付款，给银河开立对应供货范围的信用证；处理与电力公司的商务和其它复杂关系；负责产品安装、测试调试以及售后服务和维修；开立相应的投标保函，和履约保函或质保保函等。银河负责提供资质和技术上的投标文件；中标后给代理供货；提供进行本地制造/装配所需的技术支持；提供相关技术资料和产品宣传资料等', '招标方自主决策采购', '', '电力公司直接付款给供应商：收货后30天内支付60%；与系统兼容后30天支付30%；余下10%验收后5年内每年2%。\r\r\n代理直接与电力公司签订供货合同，从电力公司直接收取项目付款；代理下订单给银河，代理给银河开立对应供货范围的信用证；							\r\r\n', '', '资金直接来源于政府办公室，资金有保障', '', '电力公司客户关系需进一步打理', '', '银河有客户渠道协助在截标前获取价格信息', '', 'Hexing+Palmohan,Genus, L&G,L&T,HPL等', '', '采用JPM项目竞投策略，但将以L2或L3为目标，非L1，以便留有之后匹配L1的价格空间', '', '价格信息；电力公司关系处理。', '该项目与JPM项目要求一致，可沿用JPM项目投标资料，更新部分资料抬头，时间；重新申请签字授权；更新产品画册等，最迟2019.02.25提交。', '左亚楠2019-02-18 13:45:53', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('265', '{52F1A019-6998-418D-B089-22BA3DD67A71}', '66', 'JXINHE-2559', '2019-02-18 15:19:20', '0000-00-00 00:00:00', '2019-02-20 10:40:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021805/PVT', '', 'ADB-PDEIP II-Tranche1-AMI Project-IESCO Package 1', '2019/03/07', 'Design, supply, installation, commissioning of an Advanced Metering Infrastructure Project in Rawalpindi circle, Customer Information System and New Billing System for Islamabad Electric Supply Company (IESCO)伊斯兰堡电力公司下拉瓦尔品地地区新账单系统，用户信息系统，先进计量体系项目的设计，供应，安装和执行。', 'CIP Regional Store Bakra Mandi, Rawalpindi （详见标书P37）付款主体：伊斯兰堡电力公司付款条件：业主收到预付费保函后，支付合同总金额的10%作为预付款。         发货后，通过信用证方式支付合同总金额的45%。         安装后，通过信用证方式支付合同总金额的25%。         颁发运营认可证书后，通过信用证方式支付合同总金额的10%。         一年内项目执行无误并颁发运营认可证书后，通过直接支付流程，支付合同总金额的10%。（详见标书P401）', '', '先技术评标，技术评标通过后进行价格评标。详见标书要求P45', '', '一家投标联合体中标，中标后，联合体内的表厂平均供应电表。一家表厂只能加入一个投标团队。详见标书P288和36', '', '待和总包以及投标联合体确认。', '', '财务数据：过年三年内，年平均营业额不少于8000万美元，投标团队内的一方满足要求金额的25%即可。详见标书P50供货纪录：1.至少在三个不同国家，设计并执行集成AMI解决方案，电表计量点数量至少为20万；        2.有在至少三个不同国家执行过AMI通讯项目的经验；       3.证实具备执行过包含至少20万台电表的定制类AMI软件方案；       4.有在至少一个亚洲国家供应过35万台静态表的经验；详见标书P52资质证书：ISO9001 详见标书P53测试报告：签订合同后的六个月内递交产品型式测试报告。详见标书P293', '', '1.技术应答表，产品的技术描述，生产和交货计划等。详见标书P2932.证明满足以上商务要求的商务文件。', '', '银河作为表计分包商加入以成都长城开发主导的投标联合体，现阶段双方正在签订合作保密协议，成都长城开发承诺待双方签订保密协议后，将披露项目投标联合体的相关信息，如总包和各投标人的相关信息，中标后，银河将和投标联合体签订购销合同。', '由于我司不满足标书的部分商务和技术要求，现与深开发合作，加入其组成的团队联合体。中标后，供应电表，集中器和用户显示单元，配合主包执行项目。', '项目为巴基斯坦当地第一次执行大型AMI项目，新政府对项目的决策影响较大。', '', '国际性招标，如上述第4项中的付款条件描述内容。', '', '项目由亚洲开发银行筹款，款项已到伊斯兰堡电力公司账户，电力公司的财务能力待调查。', '', '此次我司和成都长城开发合作投标，据其联络人称，其当地合作伙伴实力强劲，已成功配合他们将项目的截标期延至3月7日。其母公司深开发作为国内唯一一家满足标书要求拥有单一AMI合同金额超过4000万的厂商，拥有良好的技术实力。', '{52F1A0196998418DB08922BA3DD67A71D18C251E4D454BA8A05CF92EE9AFCB77}_深开发在乌兹别克斯坦执行的AMI项目情况.jpg', '通过VT项目期间的工作，拥有一批当地的代理，可以通过他们及时了解项目的最新进展,但不合作投标。', '', '兰吉尔+林洋，北方电子+矩华+科陆+积成；CMEC+海兴；西门子；中兴+浩宁达；中电装+华为+许继；', '', '通过和成都长城开发的合作，通过标书对投标联合体的商务资质要求，双方精诚合作，提供有竞争的投标方案，力争中标。在合作过程当中，要警惕合作伙伴终止合作的可能，并注意对自身敏感信息的保护。', '', '完善技术方案的提供和有竞争力的投标方案。', '通过VT项目的运作，了解了项目的要求和当地的投标规则。通过和成都长城开发的合作，可以成功通过投标对商务资格的审核。在合作过程中，加强对投标联合体包括成都长城开发的了解，密切合作关系，精诚合作力求中标，合作过程中需要加强商务把控，以降低合作的风险。', '淦永妍2019-02-19 16:32:01', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('266', '{F66BFC46-8299-453D-870D-4389B72C10F7}', '61', 'INHE-0725', '2019-02-20 10:13:16', '0000-00-00 00:00:00', '2019-02-25 14:06:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2019022001/ACO', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '赵政洁2019-02-20 11:26:03', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('267', '{292A5F14-51C0-4A1F-8A63-E46A0382FDBB}', '61', 'INHE-0431', '2019-02-25 09:42:13', '0000-00-00 00:00:00', '2019-02-26 10:45:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019022502/NWA', '', 'REA/SUPLS/17-18/00233', '2019年3月22日', 'LOT 1: Supply and Delivery of Bulk Energy Meters with GPRS /GSM Modems, Master Mode and Meter Boxes供应关口表，GPRS/GSM模块，主站模块和表箱 LOT 2:  Supply and Delivery of   Metering Units 供应电表LOT 3:  Supply and Delivery of Prepaid KVA Meters and Round CTs.供应KVA电表和圆CT', '1.收货见发票后30天付款，付款货币为本地币（乌干达先令）#FE54` 2.质保1年，要求保证使用寿命为10年#FE54`3. 计划代理投标，且按公司标准30%下单前+70%发货前进行谈判', '', '1.商务预审 2.技术评审 3.综合评比', '', '无要求', '', '代理开保函', '', '2017、16、15年平均年销售额为55万美金且在过去四年内至少成功执行过超过一个金额为55万美金的项目', '', '正常的商务文书，具体请参考招标文件', '', '代理商投标', '', '电力公司隶属于能源部，但是这种金额不大的项目基本不会受能源部影响，主要是电力公司内部决策。', '', '收货后确认付款时由资方（欧洲银行）付款给中标者/供应商', '', '欧洲援助资金', '', '1.与代理一起合作过UNW项目，据内线消息我们被做为中标方推荐给资方（欧洲银行）审核中，所以代理有一定的关系#FE54` 2.在UNW项目中代理已支付2万美金的银行保函费用（由于国内无法开立，代理在当地通过私人银行开立，所以费用较高）和近3万美金的公关费用(FAT公关费），已经尽他们最大努力在配合工作中', '', '业主的ED和技术要员关系较熟，且在UNW项目时有过承诺', '', '待代理提供中', '', '优势：代理较配合工作且和ED熟识，在UNW项目中也已经公关过一部分\r\n\r\n劣势：LPU产品在乌干达无供货记录，CONLOG和海兴都有成功经验', '', '1.提供优秀的投标文档和有竞争力的价格（具体投标价格和代理及内线沟通中）#FE54`2.代理和我们自己两条线同时推动项目评估,出差时可能会有一些公关费用产生', '计量箱等LPU产品目前在整个乌干达只有Elster, Conlog和海兴供过货。这是一个良好的契机让乌干达认识到银河也有很好的LPU产品，同时对UNW及后续项目的评估还有国电UMEME的LPU的推广都有积极作用，综合建议三星立项。', '刘佩2019-02-25 10:32:53', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('268', '{D9331E35-8D15-4A8C-BF63-DFAB0166B740}', '61', 'INHE-0772', '2019-03-03 23:32:29', '0000-00-00 00:00:00', '2019-03-06 11:27:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2019030301/GBC', '', 'GM-NAWEC-72939-GO-RFB', '2019-3-28', 'Electricity Restoration and Modernization Project 电力复兴与现代化项目', '(i)	10% Advance Payment: Ten (10) percent of the Contract Price shall be paid within thirty (30) days of signing of the Contract against a simple receipt and a bank guarantee for the equivalent amount and in the form provided in the bidding document or another form acceptable to the Purchaser.(ii)	80% On Delivery: Eighty (80) percent of the Contract Price shall be paid on receipt of the Goods and upon submission of the documents specified in GCC Clause 13.(iii)	10% On Acceptance: The remaining t', '', '（a）交货时间表。N / A（b）付款时间表的偏差。N / A（c）主要更换部件，强制性备件和服务的费用。N / A（d）买方所在国家/地区的供应中提供的设备备件和售后服务的可用性。N / A（e）生命周期成本。N / A  （f）设备的性能和生产率：N / A.', '', '每一个标段允许一家中标，允许一个厂家同时中标多个标段。               （a）对招标文件作出实质性回应#FE54` 和（b）评估成本最低。', '', '10%合同金额履约保函，投标保函120天。Lot 1: US$1,600.Lot 2: US$14,600.Lot 3: US$2,300.Lot 4: US$1,000.', '', '要求200万美金年营业额，每个lot要求对应标的物在过去三年内有5个类似项目', '', '测试台厂家授权书，技术应答资料，测试报告，产品证书，产品宣传单页，公司介绍，供货记录', '', '银河投标', '', '招标方是电力公司，业主负责评标，世行审核提交最终结果。政府部门不干预世界银行招标', '', '电力公司将评审结果提交世行审批，审批通过后世行通知付款，电力公司内部流程审批付款，电力公司通知银行付款，银行付款。', '', '世界银行提供项目资金', '', '合作代理与电力公司关系很好，负责当地的利益分配。', '', '一线有银河业务', '', '海兴，兰吉尔，itron，conlog等，海兴是本项目最大的竞争对手，过去2年有供货记录。该市场一贯是低价中标，本次海兴的低价策略难以避免。', '', '优势：银河当地客户关系较好，在运作澄清要求提交样机。劣势：海兴在西非世行关系较好，我们的文件和样机都不能有漏洞。策略：业务员前往一线进行实时监督控场。', '', '文件涉及软硬件和外协厂家，文件制作和样机准备的需要及时完成。前期在国内与商务技术人员一起准备投标资料，计划在3月中旬前往一线为了实时监督对手动向和控场。', '一线的客情经营不错，在评标小组内半数关键决策人支持银河。但是海兴的营销手段直接暴力，如海兴派营销人员前往现场影响评标小组对我司的不利。打铁需要自身硬，澄清阶段运作样机测试，要求自身样机达标，投标文件质量达标。该市场是英国殖民地，也讲究所谓“民主”不能够出现漏洞被对手抓住。', '张子琦2019-03-04 00:12:04', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('269', '{228C69E3-FABF-40E7-8934-BE6A61CCEA2E}', '66', 'JXINHE-2559', '2019-03-11 14:40:52', '0000-00-00 00:00:00', '2019-03-12 18:04:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031101/EDP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'EDM新任主席上任，宣布大规模启用智能电表以减少因窃电带来的损失，EDM现偏向直接与供应商交易。通过前期的项目的工作和努力，和电力公司相关人员建立了良好关系，现恳请公司给予支持，力争拿下该项目。', '淦永妍2019-03-11 15:55:27', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('270', '{E67E0DA9-686A-47C0-B4EF-8FF8C586C532}', '66', 'INHE-0774', '2019-03-14 10:19:17', '0000-00-00 00:00:00', '2019-03-21 11:37:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031403/LIT', '', '2019/S 044-101544', '2019/04/04', '智能计量基础设施采购(Procurement of Smart Metering Infrastructure)', '价格条款，付款主体，交期，质保和违约条款等商务条款在通过资格预审后的标书中才会保函。付款条件：收到发票后30天内（日历天）', '{E67E0DA9686A47C0B4EF8FF8C586C5328442F4C2B3234363A3D51C033076BD50}_Special Tender Conditions for Call for Tenders (STC).pdf', '采购委员根据附件7的标准和要求对投标人提交的资料打分，分数按从高到低进行排序，前6位的投标人被选中进入下轮投标。最高分为22分。被选中的6家有资格参与下一轮投标，根据标书的要求提交资料和样机，并进行competitive Dialogue,回答电力公司的问题。采购委员会最终选出最具经济优势的投标公司，在签订合同前，选中的公司需要展示证明之前提供的方案，展示成功后才能签订合同。', '{E67E0DA9686A47C0B4EF8FF8C586C532074E749A304748709C51373D9D483750}_Annex No. 7 to the STC_Qualifications-Based Selection.XLSX', '1 个Lot', '', '通过资格预审后的标书中才有要求', '', '最低要求：1.供应商在最近三个财政年度内所有经营活动的平均年收入不低于18,000,000欧元（不含增值税）；2. 供应商在最近三个财政年度内来自智能计量基础设施安装和开发的平均年收入不低于9,000,000欧元(不含增值税）；3.供应商在最近5年内已经执行或正在执行的一份合同中，共供60万台智能电表（带CE Mark）；4.供应商在最近5年内执行的或正在执行的一份合同中，包含智能计量信息系统，读取和处理智能电表数据，合同金额不少于300万欧元（不含增值税）；5.供应商在最近5年内执行的或正在执行的一份合同中，项目安装智能计量信息系统收集和处理智能电表数据，且包含不低于DLMS/COSEM security Suite 0版本或相关安全方案； 6.供应商需指定1名项目经理，1名智能电网/智能计量方案架构师，1名商业分析师，1名信息系统分析员，1名测试主管，1名质保专家，1名智能计量专家，1名信息安全专家，具体要求见标书附件5；7.供应商信息安全管理需符合ISO27001信息安全管理标准。8.供货记录表；9.证书：DLMS/COSEM,MID证书，符合IDIS标准。', '{E67E0DA9686A47C0B4EF8FF8C586C53203404677E4D44E9EB56B3D512B2AF9CC}_Annex No. 5 to the STC_Qualification requirements.xlsx', '1.供货记录；2.ESPD文件；3.相关技术人员资料。', '{E67E0DA9686A47C0B4EF8FF8C586C532C675BD0CC93442C09B990884D4324504}_Special Tender Conditions for Call for Tenders (STC).pdf', '联合投标（和Cuculus合作，银河主投）', '德国软件开发公司Cuculus从去年就开始跟进此项目，也参加了电力公司2018年9月19日针对此项目的一个会议，他们对欧洲采购流程比较清楚，而且他们的系统应该会更接近电力公司的要求。可以由Cuculus负责系统软件部分，银河负责电表部分。暂按银河主投参与资格审核阶段。', '', '', '', '', '', '', '', '', '', '', '2018年9月19日参加电力公司的会议的公司有海兴，深圳开发，华为三家中国电表公司，也有Landis+Gyr, Iskraemeco,EDMI,ITRON,Honeywell,Kamstrup,ADD Grup，ZIV等欧美电表公司，还有做软件开发，通信方案的公司。在立陶宛，摩尔多瓦公司ADD Grup2016年参与过一个试点项目，安装了4000个PRIME PLC 电表；2017年3月，立陶宛电表公司Elgama宣布和ESO签了一个价值500万欧元的GPRS智能电表供应合同。', '{E67E0DA9686A47C0B4EF8FF8C586C532C8C3CDC70C5243B796247CC1ED7EC56E}_2. atendees list of 09.19 event (those who agreed with publication).pdf', '策略：和欧洲软件公司联合投标，可以弥补我们软件产品的不足，同时应该发挥银河电表硬件方面成本，研发，生产的优势，在价格方面和欧洲品牌竞争。\r\r\r\n劣势：没有欧洲市场的项目经验，对欧洲国家的采购程序不熟\r；MID证书和IDIS证书\r\r\n\r\r\r\n', '', '1.资格预审的资料能准备齐全，符合要求；2.MID证书（现阶段不需提供，中标后提供）；3. Competitive Dialogue部分需要技术人员能够专业的回答电力公司的问题', '此项目还在资格预审阶段（流程：资格审核资料提交---打分选出6家---提交样机和方案---Competitive Dialogue(会议问答)---选出最具经济优势供应商---演示证明方案可行性（PoC）---签订合同），应准备完备符合要求的资料，务必通过资格预审拿到下一阶段投标资格；最好能和Cuculus达成合作，联合参与投标。', '何森华2019-03-14 16:35:49', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('271', '{6B1FC499-36F0-4C14-AAD9-35461CCB7745}', '60', 'INHE-0781', '2019-03-14 10:24:33', '0000-00-00 00:00:00', '2019-03-18 16:01:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031404/NCO', '', 'NESCO/SMP/Purchase/42', '2019.03.25', 'Supply, Installation, Testing & Commissioning of Smart Pre-Payment Meter with Related Services on Turn Key Basis for NESCO Ltd.', '70%：L/C，提供货运单据后10%：L/C，业主出具验收证书后10%：L/C，安装和调试预付费系统后，提交文件（如临时验收证书，系统发票等）后支付10%：L/C，安装以及成功调试预付费系统后，出具最终验收证书后支付软件和网络：30%：安装所有软件后30%：安装、测试和调试后，出具临时报告后支付30%：对整个现场操作监控6个月后由工程师确认其性能后支付10%：交付后45天内，提交相关文件后在提交发票或供应商付款请求以及业主接受请求后60（六十）天内，付款需结清', '', '1）资格预审：审查Tender Submission Letter(Form PG4-1), 不更改格式，填写完整；审查投标方是否加入某个专业/贸易组织；审查投标方的纳税资格；审查投标方未破产；审查投标方是否为准入国家；审查投标方的被授权证明（签署投标文件）；审查投标保证金和保函；通过资格预审才能进入技术评标2）评技术标审查原产地声明；审查技术文件以及Specification Submission Sheet(Form PG4-4)#FE54`审查技术文件、资质文件等；审查技术文件，应覆盖招标产品范围。发布澄清3）评商务标审查报价表，逐项检查计算错误，根据折扣调整报价等只将由招标人列出的零部件和工具纳入评标范围影响评标的因素：对交付和完工时间表偏差调整；主要替换部件、必备零部件和服务的成本比价：选出最低价；若最低价出现平局，则通过比较过往表现（如交货期，货物质量，投诉历史等）决定中标者；若出现平局且都无与业主的过往交易，则进入后资格预审决定。4）资格后审', '', '一个LOT，一家中标', '', '投标保函 金额：USD 340,000.00， 有效期：150+28天，应为不可撤销的银行保函履约保函 为合同金额10%，有效期为完工后三年+28天', '', '1.投标人在最近5年内的仲裁数不超过3次。2.投标人必须合法注册，并有至少十（10）年在电力公司开展类似于招投标业务的经验。（十年运营资质）一般经验：3.至少有5年的电力公司交钥匙工程项目管理经验，AMI与通信网络和电力公司的硬件、软件、电表、DCU、HES、MDMS集成(兼容)的经验。4. 在智能电表部署的智能计量/ AMI交钥匙项目领域，投标人至少在近60个月（5年）内与两家电力公司有一般项目经验。 须提交至少两份用户证明。5. 投标人须提供DCU /模块化DCU和HES系统，该系统应能够与至少其他两个厂家的电表进行连接和兼容，以确保其互操作性(互操作性必须从任何两个(投标人本身除外)的初步技术响应投标人处得到确认)；对于MDMS，投标人必须确保所提供的MDMS至少能够兼容两百万台电表， 但是，所有这些智能电表都应具有互操作性，并符合DLMS / COSEM标准。6.投标人至少应在近60个月（五年）内，为两家电力公司提供智能电表/预付费电表。须提供证书，证明其所供电表具有互操作性，并符合DLMS / COSEM标准。7. 厂商应在近60个月（五年）内有在单个合同里成功供应至少50,', '', 'CMMI 3级认证，需在截标日（现为3.25，预计至少延至4.20）前拿到。', '', '联合投标', '此项目为包含安装、调试和后续维护的交钥匙工程，因我们暂不具备这些能力，必须具有一个本地机构承担这些职责，同时替我们承担收款风险。因此必须以JV形式投标。因标书明确要求主投标人必须是电表厂商或者系统厂商，因此银河将作为主投标人。', 'NESCO新从BPDB分离出去还不久，能源部和BPDB对NESCO具有比较大的影响力。', '', '见上述付款条件', '', 'GOB项目，资金支付有保障。\r\n', '', '合作代理与电力部以及电力公司有较好关系，有助于投标运作，赢得中标。', '', '因NESCO属于新成立公司，客户关系尚待建立', '', '海兴、科陆、威盛、林洋等老对手。需要注意在近期招标项目中，海兴、科陆屡屡爆出超低价。\r\n', '', '较好的付款条件，良好的政府/电力公司关系，包含MDMS和HES系统，有利于通过技术手段排除竞争对手。\r\r', '', '此项目包含MDMS和HES，技术难度高，同时在演示阶段需要做与另外两家投标人样机的互操作性演示，难度大大增加。需要我们的技术人员仔细分析标书要求，做好技术方案。同时，因此项目是NESCO第一个智能表项目，而且直接关系到能否将自己的系统打入NESCO从而在后续项目中获得先发优势，可以预见竞争将非常激烈，在价格上也需要得到公司的大力支持。\r\n', '此项目作为NESCO第一个智能预付费表项目，而且包含MDMS和HES，不仅项目本身体量不小，而且关系到是否能将我们的系统打入NESCO从而在将来以百万级的需求中获得先机，意义远超项目本身。因此，这个项目属于我们该竭尽全力去争取的项目。', '李启坦2019-03-14 12:49:13', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('272', '{2821849C-2F1A-4F23-92D0-BB97D77FC6AB}', '61', 'INHE-0642', '2019-03-15 16:17:20', '0000-00-00 00:00:00', '2019-03-18 15:26:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031501/M16', '项目代号为M16。', 'ESC 00063/ICB/RT/G/FY2018-19', '2019年3月13日招标，4月15日当地时间下午2点截标', 'TENDER FOR DESIGNING- MANUFACTURING, DELIVERY, INSTALLATION AND COMMISSIONING OF PREPAID METERS FOR MAXIMUM DEMAND CUSTOMERS BY INTERNATIONAL COMPETITIVE BIDDING (ICB) (RESTRICTED TENDER)  最大需量预付费表设计供货安装调试项目', '价格条款：CIF\r\n交期：20周内,\r\n违约赔偿金：每周0.5%，最高5%合同总金额\r\n付款条件：目前只看到有标明的结算方式为：项目完成工且开具发票后60天内付款。', '', '1.	初步评标，确认标书的完整性#FE54`填妥并签署的投标书#FE54`委托书#FE54`投标保证金#FE54`提供证书,投标的有效性；合格国家的投标人；确认投标人已接受GCC和SCC中规定的所有条款和条件。\r\n2.	技术评标\r\n3.	商务评标，投标价格#FE54`调整价格以纠正算术错误#FE54`因折扣而调整的价格#FE54`不符合和遗漏的调整#FE54`适用所有评价因素、评价和资格标准#FE54`和由于适用优惠幅度而作出的调整，\r\n技术符合的前提下，价低者胜，对于技术阶段将失败的投标人，不应公开财务提案\r\n', '', '1个LOT，一家中标\r\r\n', '', '1.投标保函金额为MK10,000,000.00或者等值的银河担保或者支票。汇率以开标当天Reserve Bank of Malawi的汇率为准。\r\r\r\n2.授标后30天内提供履约保函，金额为合同总金额的10%\r\r\r\n', '', '（a)符合最低技术规格\r\n(b)厂家授权书\r\n(c) 设计类似解决方案的经验证明\r\n(d)遵守交货时间表\r\n(e) 40周的项目实施计划', '', '技术资料需要客服协助评估', '', '银河投标', '', 'ESCOM为国有企业，政府直接控制ESCOM走向', '', '提交商业发票后的45天内付款', '', '银河与ESCOM执行过多个项目,ESCOM资信良好,但效率低下', '', '无合作伙伴', '', '一线客户关系良好，主要客户关系涉及层面为电力公司内部决策层以及应用层即采购和用服部门，同时也和项目评审中起关键作用的技术评标委员会和IPC等建立了较有深度的关系。', '', '该项目主要竞争对手为海兴和科陆，科陆在该市场供货过MD表箱，断路器以及电操，由于之前项目事项，和电力公司关系较为紧张。海兴未进入M国市场，之前投标的项目均由于其代理John Achilis代理，据说此代理和PL有纷争，到目前为止，未有供货记录。', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 通过采购和技术内线影响评标团队成员，并推进一和二审评标小组成员和银河评标规则的运作\r\n3. 协同IPC成员稳固评标小组运作优势', '', '项目成功的关键位：运作技术澄清和技术评标规则，同时和PL达成一致的行动计划。需要的支持：商务支持。								\r\n', ' 该项目需要提供样机，但投标时间很短（一个月），建议尽快评估技术参数并准备相关样机空运到M国市场。\r\r\n', '潘正豪2019-03-15 19:51:53', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('273', '{9C36F02C-38EC-49BB-93CD-0D28E4EC3B8D}', '61', 'INHE-0695', '2019-03-20 14:30:20', '0000-00-00 00:00:00', '2019-03-25 15:52:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032001/NBT', '', '2019/S 044-101544', '2019.04.04', 'Ismaniosios apskaitos infrastruktura (SMI)Smart Metering Infrastucture智能表计基础设施', '\r\r\r\r\r\r\r1.【付款条件】标书文件规定，在双方签订验收转让证书(Acceptance of transfer Certificate)后，买方将在收到发票的30天内付款。(采用电子发票)\r\r\r\r\r\n2. 【采购方】为业主母公司Lithuanian Energy旗下的UAB Verslo Aptarnavimo Centras(负责集团采购招标，人力资源管理)', '', '预审评标：\r\r\r\r\r\r\r\r\r\r\n1. 针对ESPD的审查，需投标方填写并ESPD(欧洲单一采购文件)的相关内容\r\r\r\r\r\r\n2.\r\r 针对年报，供货记录的审查\r\r\r\r\n3. 针对【a.电表供货】【b.表计系统供货】【c.过往收入】\r\r\r\r\r进行评分量化考核\r，针对【a】【b】两项，投标方需分别各提供两个供货记录（20分）。针对【c】项，需提供\r三年财报（2分）\r，评分机制请查看附件。\r\r\n\r\r\r\r\n【招标时间流程】\r\r\r\r\r\r\r\r\r\r\n1. 2019\r\r\r\r\r\r\n年 第\r\r\r\r\n一季度-第二季度:资格预审阶段\r\r\r\r\r\r\r\r\r\r\n2. 2019\r\r\r\r\n年第二季\r\r\r\r\r\r\n度:通过预审(6家\r\r\r\r\n总包)，发布技术规格\r\r\r\r\r\r\r\r\r\r\n3. 2019年第三季度:提交初始版项目建议书\r\r\r\r\r\r\r\r\r\n4. 2019年第四季度:提交\r\r\r\r\n最终版项目建议书\r\r\r\r\r\r\r\r\r\r\n5. 2020年第一季度:POC验证\r\r\r\r\r\r\r\r\r\r\n6. 2020年3月：中标方签订协议\r\r\r\r\r\r\r\r\r\r\n7. 2020年第三季度：开始大规模部署电表\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n', '{9C36F02C38EC49BB93CD0D28E4EC3B8D074E749A304748709C51373D9D483750}_评分机制.xlsx', '1.该项目未进行LOT区分。\r\r\r\r\r\r\r\r\r\n2.制造商可同时独立投标及作为分包商参与其他投标人的投标。但若作为主投标人或JV投标，则不能一标多投。\r\r\r\r\r\r\r\n3.在通过资质预审后，招标方会按照评分，选出排名前六的投标商进行竞争性对话。', '', '1. 当前为资格预审阶段，无需提交投标保函。\r\n2. 但后期若正式投标，则需要提交投标/履约保函。\r\n', '', '【财务数据要求】（银河满足）\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n1. 过去三年的年均收入大于一千八百万欧元(18,000,000 Euro)\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n2. 过去三年来自于智能表计相关的收入大于九百万欧元（9,000,000 Euro）\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\n【供货记录】\r\r\r\r\r\r\r\r\r\r\r\r\n1. 针对【电表】\r,过去5年内，参与了至少一个供货智能电表数量大于60万台\r\r\r\r\r\n的合同。\r此处电表需要带有CE认证（MID）\r\r\r\r\r\r\r\r\r\n2. 针对【系统】，过去5年内，至少参与了一个智能电表系统供应合同。且该系统的价值不低于300万欧元。\r\r\r\r\r\r\r\r\r\n3. \r\r\r\r\r\n过去5年内，至少在一个项目内实施了DLMS/COSEM Security Suite 0.\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\n【人员】\r\r\r\n\r\r\r1. 需推荐一组专家成员团，详细名单及要求请见附件。\r\r\r\r\r\n\r\r\r\n\r\n\r【证书】\r\n需至少具有ISO 27001', '{9C36F02C38EC49BB93CD0D28E4EC3B8D03404677E4D44E9EB56B3D512B2AF9CC}_供货, 财务, 人员要求.xlsx', '\r\r\n\r\r\n【商务部】\r\r\n1.协助整理CDN项目，肯尼亚项目供货记录，需按照标书提供的模板进行详细填写。\r\r\r\r\r\r\n2.协助进行ESPD(欧洲单一招标文件)的填写。\r\r\r\r\r\n3.提供过去三年的财报\r\r\r\r\r\n4.授权函\r\r\r\n5.', '', '跟合作伙伴初步确定，银河作为投标方，合作伙伴INTRASOFT作为Sub-Supplier参与', '', '本次采购决策涉及到三方：\r\r\r\r\r\r\r\r\r\r\r\r\n1.【UAB Verslo Aptarnavimo Centras】其负责Lithuanian Energy整个集团公司的采购，主要评判商务及资质部分。\r\r\r\r\r\r\r\r\n\r\r\r\n2.【Energijos Skirstymo Operatorius A\r\r\nB】本次采购的业主，\r\r\r\r【智能表计部门】和【智能电网部门】将会是直接利益相关方，影响技术评标。\r\r\r\n3.【AF Mercados】 业主聘用的西\r\r\n班牙公司，主要负责本次招标的顾问监理。其直接参与评标的可能性不大，但会在标准规范制定方面有一定影响力。', '', '预选阶段，未披露', '', '\r\r\r1.该次招标为非欧盟拨款项目。\r\r\r\n\r\r\r\r2.据ESO 2018年年报显示:\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n  a.收入增长1.9%，达到624M 欧元\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n  b.净利润下降26.6%, 为56.9M 欧元 (下降原因为电力成本增加，电力零售价格增加)\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n  c. 税息折旧及摊销前利润(EBITDA) 下降12.6%，为122.4M\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n  d. 调整后的税息折旧及摊销前利润(EBITDA)增长12.3%，为169.5M\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n  e. 总资产增长24.6%， 达到1467M.\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r3.ESO内部在2018年出现超预算的情况，故该次招标挪到2019开始。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n4. 立陶宛国家风险较低，且2017年标准普尔针对立陶宛中长期借款信用评级为A-', '', '主要竞投合作伙伴： INTRASOFT（希腊），希腊的软件开发商，有跟SAP, ORACLE, IBM的合作经验。 在官网查询及通过阅读其年报，了解到该集团公司2017年年收入为1亿七千一百六十万欧元。从2013至今，其参与运营HEDNO本地的一个AMR运营系统及电表安装项目。该项目总额为两千两百二十万欧元。(网查其2015年年报核实该项目金额属实)\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\nNBT项目招标方针对供货记录有一条要求，即为投标方在过去5年内需有参与过一个项目，该项目中智能表计系统的总价值大于300万欧元。银河在此处的供货记录会有不符点，通过与INTRASOFT合作，可以借用其运营该项目的经验资质来满足，此外，INTRASFOT本身就是\r\r\r\r\r\r\r\n南欧地区较大的一家系统软件供应商，业务遍布全球。\r\r\r\r\r\r\r\n\r\r\r\r\r\r\n与我方对接的联系人Dimitris G. Mitsainas, 网查其领英可得知，其在智能电网领域有20多年的从业经验，懂技术也懂项目管理运作。经与其交流发现其对中国及欧洲的表计玩家十分清楚，并且在我们同其接触前，也对该立陶宛项目有所了解。\r\r\r\r\r\r\r\n\r\r', '', '1.较弱，2018年欧洲展时，通过代理关系，将电力公司表计【表计部门】同【智能电网部门】的负责人邀请至我们展台进行展示沟通，向其展示了我们的产品方案及银河在CDN的经验。其对银河评价为中性。\r\r\n\r\r\n\r\r\n我方已知的对该次技术评标会有影响的相关人员为：\r\r\n1. 【Evaldas Zibaitis】智能表计部门负责人，本次招标利益相关最大部门\r\r\n2. 【Mindaugas Vysniauskas】智能电网部门负责人。', '', '1. 【林洋+Elgama】 林洋收购了立陶宛本地表厂Elgama，并在此前2017年的智能电表招标中中标 简单表。该项目必定会参与。\r\r\r\r\r\r\r\r\r\r\n2. 【深开发】\r\r\r\r\r\r\r\r\r\n深开发在前期十分关注该次招标项目，在最初的技术规格要求中，其满足NB-IoT的要求及eUICC的要求。\r\r\r\r\r\r\r\n3. 【威盛】\r\r\r\r\r\r\r\n威盛中标此前ESO的简单表项目。\r\r\r\r\r\r\n4. 【炬华+捷克表厂Logarex】\r\r\r\n5. 【海兴】\r\r\r\n6. 【其他传统欧美表厂\r】\r\r\nItron, Landis+Gyr, ADD, Inskraemeco, Apator\r\r\n\r\r\n', '{9C36F02C38EC49BB93CD0D28E4EC3B8DC8C3CDC70C5243B796247CC1ED7EC56E}_NBT项目 标前会议参与名单.xlsx', '该项目于2018年9月发布了初版招标技术规格，要求NB-IoT通信技术及eUICC.电表符合DLMS/COSEM协议，并需保证在交付时满足IDIS Package 2的要求。\r\n而后，项目出现长时间停滞，电力公司内部意见出现变化(由于2018年超预算，NB-IoT新技术不成熟及成本相对较高等因素)。电力公司取消对此前通信方式的限制。\r\n在2018底-2019年初，ESO选择西班牙公司AF Mercados作为该项目的顾问监理。\r\n\r\n立陶宛此前进行过部分智能电表招标，但大部分均为简单表，成本较低，在EGC项目与本地模块厂商打交道了解到，中国厂商在此前简单表的招标中占居较前地位，价格低。\r\n\r\n当前招标要求在财务，技术上均有降低。银河可采取多种方式参与其中。\r\nA. 作为总包参与\r\nB. 作为分包参与\r\nC. 作为OEM厂商寻找潜在中标方\r\n\r\n除开CE认证(MID)及人员资质，银河的参与难度较初期下降较多。但若按照评分表进行评估，银河的综合评分(满分22分)相较于其他潜在的参加者(文档：', '', '1. 加快公司MID认证\r\r\r\r\n2. 熟悉欧洲投标流程\r\n3. 业务自身提高控局能力', '该项目于2018年9月立项，因完成评审后无法更新信息，故重新立项。', '卿于蓝2019-03-21 10:38:20', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('274', '{A1D41ED6-107C-44F3-9BE9-59FCF7006339}', '61', 'INHE-0381', '2019-03-25 18:30:28', '0000-00-00 00:00:00', '2019-03-26 15:44:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032501/CDN-EPT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'CDN电力公司的接线管理软件此前由一家当地供应商做开发，但是开发、调试工作持续了一\r\n年，仍然有很大的BUG，导致CDN的《给所有人通电》项目严重受影响。 因此，电力公司最\r\n终决定让我司来开发接线管理软件。但是由于项目的压力，希望开发和调试工作能在12月底\r\n之前完成，因为年底电力公司也需向能源部、国家做报告。所以交期要求的也很着急。 因\r\n此，电力公司希望我们尽快派工程师过去当面讨论需求，并在当地完成开发、调试工作。\r\n附件中是简单的需求文档，详细的需求文档电力公司将于这两天发过来。 已与电力公司邮\r\n件确认以下两点：\r\n1. 另外收取适当开发费用。\r\n2. 开发出来的软件所有权归我司，源代码归我司。', '张柳芳2019-03-26 15:41:25', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('275', '{C91E7787-D4B2-40EC-8C03-0FA504445761}', '66', 'INHE-0579', '2019-03-26 10:01:54', '0000-00-00 00:00:00', '2019-03-27 16:34:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032601/TGP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.该项目为直接采购项目，目前华为和正泰也在参与此项目，我们需注意报价策略。\r\r\r\r\n2.PPA类型的项目性质决定该项目与国际性的金融机构合作，项目资金来源以及资金回收均有保障。\r\r\r\n3.目前客户满意我们的服务，希望银河提供完整的技术方案和报价方案，以供项目的基金技术委员会评定。', '孙娜2019-03-26 11:04:47', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('276', '{B43E7D85-A206-4F53-B5E9-6D24B92D10B1}', '61', 'INHE-0713', '2019-03-28 15:17:46', '0000-00-00 00:00:00', '2019-03-29 13:27:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032803/GNF', '', '无（限制性招标无标号）', '2019年4月20日', 'GNF', '限制性招投标，电力公司只发了技术规格，无其他条款', '', '限制性招投标，电力公司只发了技术规格，无其他条款\r\r\r\n\r\r\r\n主要测样机和评价格', '', '限制性招投标，电力公司只发了技术规格，无其他条款\r\r\n\r\r\n主要测样机和评价格', '', '限制性招投标，电力公司只发了技术规格，无其他条款', '', '限制性招投标，电力公司只发了技术规格，无其他条款', '', '需要根据AOR已有投标资料以及目前新的技术规格整理出一份新的针对银河授权代理投标的资料。\r\r\n\r\r\n\r\r\n＊投标技术资料\r\r\n\r\r\n\r\r\n＊授权投标商务资料\r\n', '', '代理商投标', '无', '政府／政治对采购决策影响不大，目前主要竞争对手依然是中国厂商。', '', '招标方：几内亚电力公司\r\r\n\r\r\n\r\r\n付款流程：限制性招标，暂无此项内容\r\r', '', '电力公司２０１６年，２０１７年未有招标，从２０１８开始陆续恢复招标，且很多招标项目均有世行，非发行支持，判断电力公司目前支付能力良好。\r\n\r\n\r\n代理支付能力良好', '', '此次限制性招标对比前几次招标，主要竞争对手大同小异，从２０１８年评标过程分析：银河代理与电力公司关系良好；\r\n\r\n\r\n银河与代理、电力公司之间关系良好。', '', '银河曾派出技术服务团队以及业务对该市场的合作提供服务，电力公司对银河印象良好。', '', '本次限制性招标主要竞争对手为海兴，代理已吸取AOR经验，打通电力公司高层关系与海兴对抗。', '', '银河将作为代理的供货商参与投标。\r\r\r\r\r\n\r\r\r\r\r\n此次限制性招标技术规格与AOR技术规格十分相近，非常有利于银河准备投标资料与投标样机。\r需要银河尽快完成出投标样机与投标资料的注备工作。\r\r\r\r\n\r\r\n\r\r\r同时，目前代理已成为此标断路器供货商，所有投标方只能在规定的三家公司采购断路器，代理在本次投标中具有优势。\r\r\n\r\r\r\r\r\n另一方面，此市场历史招标均看重价格，多次标名符合技术要求与资质的情况下，低价中标\r\n\r\n', '', '（１）价格支持\r\r\n\r\r\n\r\r\n（２）商务支持协助资料准备\r\r\n\r\r\n\r\r\n（３）客服部支持协助技术解析以及跟进样机制作、验收\r\r\n\r\r\n\r\r\n（４）实验室支持，样机制作时间较紧，需要尽快完成样机', '', '苏宏2019-03-28 17:45:14', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('277', '{2259DDBF-C98D-4D29-8329-FC9C72A2090E}', '0', 'INHE-0770', '2019-03-28 16:05:14', '0000-00-00 00:00:00', '2019-04-24 13:29:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032804/EPU', '', 'ET-EEP-85726-GO-RFB', '2019年4月30日', '单相电子式电表和微型断路器供货Supply of Single Phase Electronic Energy Meters and Miniature Circuit Breakers', '价格条款：CIP Modjo Dry Port（实际交货到EEU仓库，等同于DDP EEU Main Warehouse in Addis Ababa (Gofa Store)） \r\n合同付款方式：10%预付款+交货时80%信用证+10%签完验收后30天内\r\n', '', '评标分三个阶段，\r\n1、投标资料评审；包括证书、认证、技术投标文件、授权函、质保期、售后服务保证函等标书要求提供的资料，检查投标文件完成性，评审通过进入下一阶段；\r\n2、技术评标：详细评审技术文件是否符合标书技术规格要求； \r\n3、投标人的供货和项目执行经验、用户证明、财务报表等证明文件；价格评标\r\n另外，此项目由IDA出资，EEP的评标委员会在技术评标之后需要将结果报给IDA审批，审批之后通过之后才进入价格评标；\r\n', '', '一个lot，一家中标；\r\n', '', '投标保函： 40,000 USD\r\n履约保函：10%的合同金额，有效期至质保期结束\r\n', '', '如果投标人为生产商：\r\n1、从2013年10月1日起，在过去连续五（5）年内，最低年平均营业额为392万美元，正在进行或已完成项目都计算在内。\r\n至少5年类似供货经验且从2013年10月1日起至少两次供货合同价格在200万美金以上\r\n', '', '1、需要商务组协助保函开立，提供证明银河投标资质类文件（财报、供货记录等）\r\n2、可能被要求提供指定的9家认证机构或实验室的型式测试报告\r\n', '', '银河投标', '无', '评标委员会对投标人进行资质和技术进行评标之后，基于入围的投标人提交报告给资方，资方进行审批后才可尽行价格评标；\r\n', '', '根据电力公司和资方的融资协议，货款由电力公司向银行提出申请，银行直接付款给卖方\r\n', '', '资方为：国际复兴开发银行International Bank for Reconstruction and Development 或者是 或者国际发展协会the International\r\nDevelopment Association (IDA)，根据电力公司与资方的融资协议，融资总额为2亿美金，资金由银行在电力公司申请下直接付给卖方；\r\n', '', 'ZGB(Zolil Global Business)，该公司于2003年成立，位于埃塞俄比亚，主要和政府部门(EEPCO，后分成两部分EEPO和EEU)合作，有成功向电力公司销售过输电变压器，开关设备，保险丝的案例。注册资本11万人民币左右。SRM04项目投标代理。\r\n', '', '电力公司客户关系主要由代理经营\r\n', '', '竞争对手以中国厂商为主；\r\n', '', '竞争策略：通过代理做好客户关系，将技术规格澄清为银河具有竞争力的规格\r\n', '', '成功关键：\r\n1、标书的技术规格表达不清晰，且与行业内习惯表达方式不一样，有被别的厂家运作的痕迹；\r\n技术规格需要澄清成为银河可以满足的技术方案，否则在技术评标中将会处于劣势；\r\n需要的支持：\r\n技术支持协助技术解析及技术规格澄清；\r\n代理做通客户关系，成功的将技术规格澄清成为银河可满足的且具有竞争力的规格；\r\n', '主要难点在于技术规格的澄清，需要将标书规格澄清为对银河有利的规格；\r\r\n客户关系需要代理打通，需要选择与电力公司关系好的代理；', '刘博2019-03-28 16:31:58', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('278', '{8CA9822D-6554-4733-92E9-A35AC27EB6E0}', '61', 'INHE-0440', '2019-03-28 19:09:05', '0000-00-00 00:00:00', '2019-04-02 18:24:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032901/TTE', '', 'PA/001/2018-19/HQ/G/92', '2019-4-17', 'SUPPLY OF METERING MATERIALS UNDER FRAMEWORK CONTRACT 框架合同供货计量材料', '电力公司对国内供应商付坦先令，对国际供应商支付美元或其他可自由兑换的货币。和本地的合作伙伴一起，争取运作成交货后30-60天付款。具体付款条件为：签订合同30天内，TT或LC支付10%预付款， 需提交相同金额的预付款保函。40%的合同金额在发货前通过不可撤销和保兑的信用证支付。50%的合同金额在到货验收后30天内，通过不可撤销的信用证支付。 质保期限：自接受货物起12个月，发货后18个月。', '', '先评估技术，然后评估商务，实际上是商务和技术一起评估。', '', '最低价中标，一家最多中标2个LOT,制造商自己投标，同时也授权本地的经销商投标。', '', 'LOT 1 提供投标保证声明  \r\r\r\nlot 2 提供TZS 50,000,000.00 或等额可自由转换货币的保函              lot 3 提供TZS 15,000,000.00 或等额可自由转换货币的保函             lot 4 提供TZS 35,000,000.00 或等额可自由转换货币的保函\r\r\r\n有效期为投标有效期后28天，国外开立的保函，需要本地知名银行当地转开。  履约保函为中标合同金额的10%，供货后可以降低到2%的质保保函，质保为验收后12个月。', '', '请参考标书第58页，Tender Data Sheet, 13.3 (b)，10年制造和供货经验，过去3年至少3个类似的供货合同。', '{8CA9822D6554473392E9A35AC27EB6E003404677E4D44E9EB56B3D512B2AF9CC}_TENDERING DOCUMENT G 92 METERING MATERIALS.pdf', 'LOT 1, LOT2, LOT 4 的11KV和33KV计量箱，需要厂家授权和提供投标的技术资料。非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告等，4月10日前提交。', '', '银河投标；银河直供', '', '电力公司为国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算，有较多的债务需要偿还，最近收了很多欠款回来，整体朝好的方向发展。合作伙伴在本地有较好的经济实力和客户关系。', '', '安标书要求提交付款资料给合同经理，然后跟催电力公司的财务部门执行付款，目前电力公司付款比较及时，资料没问题，一般在30天内付款到位。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，主要依赖银行的信用支持，支付信用证问题不大。', '', '合作伙伴可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。合作伙伴的老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验经理和实验室测试工程师等。', '', '公开招标，预计电表厂商如EDMI，WASION，CLOU，HEXING等都会参与。由于采购的计量物料种类多，本地也会很多有实力的经销商也会参与投标。电力公司内部的派系林立，投标者都有各自的人脉，主要还是靠有没有核心客户支持，从而影响授标的进度和结果。目前银河自己和本地的合作伙伴一起积累了较好的人脉资源，和内部的核心客户有利益往来，支持我们去投标。', '', '合作伙伴和电力公司，以及政府的关系较好，银河也有自己的内线人员，在市场上有较好的积累。国际公开招标，允许美元付款，银河的CT表目前在技术上应该满足客户的要求（具体需要技术解析确认），11KV和33KV的计量设备数量较多，如果技术满足，对于配电来说也是不错的机会，卷线铅封和铠装电缆/电流互感器，如果能找到合适的国内合作伙伴，也可以考虑参与，重点可以投电表和计量箱。整体资料过关，产品技术符合，报价合理，利用现有的客户关系去争取项目。', '', '资料过关，产品报价符合市场形势，样机制作按时交付，商务和技术支持人员响应到位，必要的客户关系建设开销等。', '建议立项，抓紧准备文件和样机投标，同时考虑支持本地的ITL一起参与投标，重点投标产品为CT表和11KV/33KV计量箱。', '汤伟2019-03-29 01:37:54', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('279', '{9D993259-BE50-45B7-97B5-A30DD508D1DE}', '66', 'INHE-0628', '2019-03-29 10:56:34', '0000-00-00 00:00:00', '2019-04-01 17:58:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032903/PRU', '', '无标号', '4月12日', 'Proyecto Piloto Medición Inteligente Luz del Sur', '招标方和付款方都是Tecsur,4月12日为文件提交截止日期，4月19日为样机递交截止日期，4月13日-4月24日为评标期和授标期，6月22日为软件交付截止日，7月22日为硬件到达电力局仓库的截止日。\r\n付款条件是到货后90天付款，考虑电力局直接为银河开具用信用证或由代理为银河开具信用证', '{9D993259BE5045B797B5A30DD508D1DE8442F4C2B3234363A3D51C033076BD50}_MDC_201900321 ENG - Proyecto Piloto Medición Inteligente Luz del Sur.pd', '主要根据附件技术应答和样机评标', '{9D993259BE5045B797B5A30DD508D1DE074E749A304748709C51373D9D483750}_Requirements Compliance Smart Metering Luz del Sur_20190321-ENG.XLSX', '未写明几家中标，也未写明可授权几家，电力局邀请的是银河表计、海兴、科陆以及青岛乾程等厂家。', '', '标书未提及保函，电力局一个月前邀请了部分生厂商，现在正式发标又邀请了银河', '', '一个月前已经提交过供货记录，此次只要求提交公司相关文件，未设置具体资质门槛，电力局认可银河。此次主要是提交技术和报价。', '', '4月12日', '', '直接投标，如付款条件无法做到信用证，则考虑代理投标', '', '', '', '到货后90天', '', '', '', '', '', '', '', '', '', '', '', '1.需要提供样机，产品功能有偏差，样机递交截止日期太紧（4月19日）\r\r\r\n2.电力局要求递交当地认证（需银河电表做形式批准），考虑协商电力局在供货时再提供', '此项目是本国第一个智能电表正式招标，表计最多约4500台，还包含AMI软件。本项目试运行后，该国从2020-2023年要开始120万台的智能电表更换，如果银河的软件被使用，那么在未来项目中将占有很大优势。该国认证门槛很低，且大量使用中国产品，应该是南美门槛相对低的国家，海兴、科陆、三星、青岛乾程都在此设分支机构来开拓南美。', '刘元豪2019-03-29 20:33:26', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('280', '{F5E7D3A1-690D-4AAD-9D8D-865A305CBF04}', '60', 'INHE-0434', '2019-03-29 16:06:24', '0000-00-00 00:00:00', '2019-04-01 18:18:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032905/NFA', '', 'SM4104374', '2019年6月26日，上午9点30分', 'Energie Propre et Efficacité Energétique', '1. DDU条款，货送电力公司分区仓库，报价不含税\r\r\n2. 分临时验收后付款，和最终验收后付款。采用信用证付款，世行资金。		\r33. 交期为4个月。\n				\r\n\n', '{F5E7D3A1690D4AAD9D8D865A305CBF048442F4C2B3234363A3D51C033076BD50}_AO SM 4 104 374 AMI. Partie 1 Pages 0-123.pdf', '先技术，后商务。评标委员会：1. 先评行政文件如供货记录，授信额度，财报等；2. 再评技术文件如技术应答表，操作手册，图纸等，挂网测样机；3. 评价格', '{F5E7D3A1690D4AAD9D8D865A305CBF04074E749A304748709C51373D9D483750}_AO SM 4 104 374 AMI. Partie 2 Pages 124-249.pdf', 'NFA有两个LOT，每个LOT都是1家中标。无规定同一个公司不能同时中LOT1跟LOT2', '{F5E7D3A1690D4AAD9D8D865A305CBF042B47EB25ABE84FF19C47768372BB342D}_AO SM 4 104 374 AMI. Partie 3 Pages 250-502.pdf', 'LOT1投标保函：约11万美金，LOT2投标保函：约5.5万美金。履约保函为合同金额的3%。', '{F5E7D3A1690D4AAD9D8D865A305CBF041DD410FC292E4E1893AFBEF9F88431CD}_AO SM 4 104 374 AMI. Partie 4 Pages 503-504 AAO.pdf', '1. 对公司年限暂未发现有要求；\r\n2. 3年财报，流动比率大于等于1，负债比率小于等于0.9\r\n3. 过去3年年均营业额必须超过1500美金\r\n4. 需要ISO27001证书\r\n', '{F5E7D3A1690D4AAD9D8D865A305CBF0403404677E4D44E9EB56B3D512B2AF9CC}_2019年3月25日 NFA非正式标书（法语）.docx', '暂时未发现', '{F5E7D3A1690D4AAD9D8D865A305CBF04C675BD0CC93442C09B990884D4324504}_AO SM 4 104 374 AMI. Partie 4 Pages 503-504 AAO-EN(1).docx', '银河投标，与代理合作模式为佣金代理，代理要求合同金额7%作为佣金', '', 'CEO最终拍板，CEO由国王直接任命，电力公司无董事会', '', '分临时验收后付款，和最终验收后付款。采用信用证付款。世行资金。', '', '世行项目，资金无问题。NF2电力公司付款无问题。', '', '1. 从电力公司内部提前拿到标书，与电力公司CEO有一定关系，安排与前项目经理见面。\r\n2. 近期与中国中车CRRC参与了一个大型电车招标，对招投标项目操作熟悉，知晓项目运作。\r\n3. 老板50来岁，但有激情，性格外向。宝马730Li代步，有一栋7层办公楼，知道的有两块地。\r\n4. 按其所说，在银行，政府部门都有一定关系，但还未验证。', '', '未与电力公司内部建立合作关系，因NF7/NF8问题，电力公司内部对银河有一定看法，所以正通过新代理扭转', '', '西门子，Itron，兰吉尔，科陆，Alster。科陆在电力公司的关系为NF8项目负责人。新代理告知电力公司喜欢西门子，认为他们在系统兼容这块很专业。', '', '1. 台面功夫做好即弄清标书要求，准备对应投标资料\r\r\n2. 客户关系层面获得评标团队支持，让评标团队成员指导投标资料的准备，获得CEO的支持。\r\r\n3. 优势：NF2，NF7供货，新代理有一定人脉，懂投标项目运作。\r\r\n4. 劣势：NF7产品交期导致电力公司认为银河产品交付存在问题。前代理背后抹黑，阻挠。', '', '1. 投标资料跟样机准备无误\r\n2. 价格\r\n3. 电力公司内部支持', '1. NF市场电力公司计划用智能表更换机械表，上AMI集抄系统，NFA项目为第一阶段，表计主要为CT表。\r\r\r\n2. 第二阶段将更换居民用户电表，计划3年更换100万台。\r\r\r\n3. NFA项目潜力大，望公司同意立项，提供全力支持。', '钟云林2019-03-29 17:56:08', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('281', '{178053BE-7F7B-4F6F-9F4F-93D09AC3CB0B}', '61', 'INHE-0432', '2019-04-02 14:38:13', '0000-00-00 00:00:00', '2019-04-03 16:53:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040201/ITR', '', '19PROC004670914', '5月20号', '单、三相智能电表及通讯模块供应', '电力公司是在代理商交货后第二个月的24号，支付代理商货款；代理商则在收到货款后10天内支付银河。自交货日期起，30+24+10=64天。', '', '1.先在电子投标网站上传投标资料\r\n2.同时向电力公司提交纸质投标资料\r\n3.一审：技术评审、投标资料评审\r\n4.通过一审后，再比较每个投标人对应的单三相电表报价总额（电表+模块），每个LOT（电表+模块）总价最低者中标。', '', '单相电表+模块授标1家中标人；三相电表+模块授标1家中标人；一家制造商只可授权1家投标人。', '', '1.投标保函：投标人总报价的2%\r\n2.履约保函：中标价的5%\r\n均由代理开保函', '', '1.单三相电表MID认证（依据欧盟2014/32/EE规定）及测试报告\r\r\r\n2.2-150kHz下不受高频对称电流影响的测试认证证书，即谐波失真的实验CENELEC CLC/TR 50579或EN 50470，测试由EN ISO/IS0 17025认证的实验室出具。\r\r\r\n3.电表CE认证声明（依据Directive 2014/30/EU),模块CE声明（依据Directive 2014/53/EE/(RED)\r\r\r\n4.电表模块符合Directive 2014/53/EE认证的证书\r\r\r\n5.承诺将提供ZFA-F驱动，对接电力工公司的AMM/MDM系统（Sagecome)\r\r\r\n6.单、三相表供货记录：过去5年里，每种表至少2万台，且每种表至少有5000台是已经接入了集抄系统；通讯模块，至少已供货5000台且用作集抄系统。\r\r\r\n7.ISO90001认证、DLMS认证等。', '', '需要商务部协助做投标资料、技术支持部门做技术接线、需要研发部门制作样机。', '', '代理商投标', '', '1.需要电子投标网站上传资料，网上可以看到各家的投标资料。所以资料评审，透明度高。', '', '', '', '', '', '1.INTRASOFT对电力公司客户关系较强，与Intracom同为竞争对手。2015年的集抄项目本来是Intracom低价中标，但最终被intrasoft废标了。\r\r\n', '', '', '', '三星、华立已成功低价中标并供货；海兴科陆将会参与；', '', '1.优势：代理商实力较强；电力公司对银河产品印象较好；\r\r\n2.劣势：代理商对价格要求很低，银河不一定能满足；银河无谐波失真实验的测试认证；\r\r\n3.策略：\r\r\n1）与代理商再商量价格事宜，达成双方可接受的共识；\r\r\n2）公司需要做谐波失真的测试认证，保证资料、资质符合要求。', '', '1.需要公司提供相关的资质证书；\r\n2.需要提供满足技术要求的样机；\r\n3.最终与代理商就价格达成共识', '希望公司支持。项目组成员希望调用卿于蓝一起参加。', '谭东羊2019-04-02 15:27:04', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('282', '{44D1A328-7B9E-41DC-A73C-7399409994C7}', '61', 'INHE-0840', '2019-04-03 16:35:59', '0000-00-00 00:00:00', '2019-04-09 17:45:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040301/MKE', '', 'OAB-TD-4281', '2019年4月30日 13：30 (GMT+4)', 'Procurement of Single Phase Smart Meters with 2 Elements for Energy Measurement', '报价条款：DDP报价，本地币。\r\r\n银河对EDS报价：FOB Shenzhen\r\r\n付款条件：交货后收到发票的30天内支付本地币。\r\r\nEDS对银河付款条件：另行协商。 \r\r\n资金来源：Central Electricity Board\r\r\n交期和违约：获得中标书后的14周内交货，每延误一周按合同金额的2%计算违约金，10%封顶\r\r\n质保：30天包退换，保修期1年。要求电表使用寿命15年\r\r\n', '{44D1A3287B9E41DCA73C7399409994C78442F4C2B3234363A3D51C033076BD50}_OAB-TD-4281 (IFB154) - Procurement of Single Phase Smart Meters with two elements for Energy Measurement.pdf', '1. 功能性评估完成后进入价格和资质评估\r\n2. 评分公式：Price A=实际DAT价格*最高分/技术得分\r\n', '', '得分最高者中标，一家中标，1家一个LOT\r\n', '', '无开立保函要求\r\n', '', '1. 具有五年以上制造及供应智能电表经验\r\n2. 提供近五年来与大型公共事业单位的订单合同清单\r\n3. ISO9001证书\r\n', '', '1. 需提供最新的财务报表等证明公司有能力执行合同\r\n2. 第三方测试报告\r\n3. MID认证的EC/EU证书及各类相关证书\r\n4. 提供电表安装、程序指令及管理等所有相关文件的软硬拷贝\r\n（都需要在截标日之前提交）\r\n', '', '代理商投标（此标为网上电子公开投标，代理已提前注册）', '不适用', 'CEB电力公司自有资金，拥有自主决策权\r\n', '', '交货后收到发票的30天内支付本地币\r\n', '', '采购支出约1800万美元，财报见附件\r\n', '{44D1A3287B9E41DCA73C7399409994C7108D268797C74834B1DDE2FC1083AA37}_16_Financial Statements.pdf', '1999年成立，为企业和政府部门提供电力电信设备及解决方案，今年二月份投中过CEB电缆的标，合同约151486.78美元\r\r\n', '', '业主关系主要由代理处理', '', '对手主要是海兴与EDMI，目前CEB已经在使用这两家公司提供的MDC和MDM系统，与电力公司CEB的关系密切，他们电表产品质量过硬，但价格偏高，且这次的小额项目预计他们不会参与', '', '通过代理EDS投标，此代理有获得过至少两次CEB的标的经验，竞价方面有较大把握与优势，经以前合作过的当地其他代理了解到，银河的产品质量和价格在当地也有优势，同时代理的配合积极性较高，配合度较好，愿意出样机费，只是因首次合作，需观望后续的配合及更深入的了解，看是否有与电力公司进一步公关意愿', '', '符合要求的样机能按时按质完成，代理商持续对电力公司的公关协助', '', '冯敏杰2019-04-04 18:38:05', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('283', '{F59F8F19-7413-47BD-96F0-02771C2100D1}', '66', 'INHE-0774', '2019-04-04 08:37:37', '0000-00-00 00:00:00', '2019-04-09 17:44:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040403/SDE', '', 'RO14506181, P11- PAAS 2019', '2019-05-06 当地时间15:00', 'ELECTRICAL ENERGY CONTROLS（电能控制）', '所有投标文件为罗马尼亚语，且部分文件无法下载，需要注册系统，系统注册很困难。所以暂时无法判断资格预审阶段的招标文件是否包含价格条款，付款条件，交期等重要信息；AEM要求和我们签保密协议，然后派人来公司评估我们资质，才能确定联合投标。标书AEM会翻译成英文发给我们。 ', '{F59F8F19741347BD96F002771C2100D18442F4C2B3234363A3D51C033076BD50}_Inhemeter NDA_AEM_EN_190329.doc', '价格85%+质保15%', '', '共6个Lot:\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n1. IDSpecto system-compatible meters---32464 PCS（预算：约201242欧元）\r\r\r \r\r\r\n2. Single phase meter\r\r----264000PCS\r （预算：约1835776欧元）\r\r\r\n3. Argus DC system compatible meter\r---14060PCS\r\r（预算：约324150欧元）\r\r\r\n4. Turtle TS2-compatible meter\r\r---4020PCS\r （预算：311850欧元）\r\r\r\n5. Argus compatible multiplexer(多路转接器）\r\r\r--40PCS（预算：12764欧元）\r\r\r\n6. Sunplat AMI compatible meter---150PCS\r\r\r（预算6051欧）\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r第一阶段合同采购数量可能减半\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n', '{F59F8F19741347BD96F002771C2100D12B47EB25ABE84FF19C47768372BB342D}_FisaDate_DF1043221.pdf', '1. 投标保函Participation Gurantee:43000 RON(约9045欧元，占单相表预算的0.4927%），保函有效期至少为投标截止日起120天，投标截止日前5日内开立。\r\n2. 履约保函：合同金额5%，合同签订之后5个工作日内开立。\r\r\n\r\r\r\n\r\r\r\n\r\n\r\n', '', '1. 财务：2015,2016,2017年度平均营业额大于430000RON(904462欧元）\r\n2. 供货：最近三年相同或相似产品供货总额不小于4300000RON（904462欧元）\r\n3. 证书：MID证书。ISO9001：2008\r\n\r\n\r\n\r\n', '', 'ESPD form(欧盟单一采购文件)，需要填写，并提供相关支持文件', '', '联合投标', '罗马尼亚电表厂AEM邀请我们参与联合投标，AEM主投，银河负责单相表。投标资料要做成罗马尼亚文，银河直接投标难度很大，而且我们不熟悉当地法规政策，跟当地公司联合投标胜算稍大。', '', '', '资格预审阶段，标书暂未明确付款流程', '', '', '', 'AEM是罗马尼亚本土领先的生产电表，气表和计量箱等产品的公司，也有AMR抄表系统。2015年给意大利供了15万台气表，在罗马尼亚给Enel生产PLC电表。主要市场是欧洲、中东、拉丁美洲。2016年销售额为7300万欧元，有1400名员工。', '', '', '', '主要竞争对手有ADD Grup(摩尔多瓦)，Energobit SA（罗马尼亚）,EATON ELECTRIC SRL（罗马尼亚）, Electromagnetic S.A（罗马尼亚） 等 ', '', '银河要参与此项目投标只能跟当地公司合作，AEM是当地最大的电表公司，如果能达成合作，中标的概率会比较大，而且我们也可以借此了解整个罗马尼亚市场情况。此项目招标的单相表我们有MID证书，迈过了CE认证的门槛。我们的劣势在于不清楚当地市场，投标资料是当地语翻译需要时间，招标平台的注册比较麻烦，很难自己直接投标，处于比较被动的位置。', '', '尽快和AEM确认合作关系，通过AEM的评审，签订合作协议。现需签保密协议', 'AEM要求我们尽快签保密协议，然后派团队来银河考察，他们已经在把标书翻译成英文，英文版的技术资料已发，需要客服尽快解析，确定表型，看是否有偏差。同时，准备接待AEM来公司考察，充分展现银河实力，为两公司长远合作奠定基础。', '何森华2019-04-04 13:35:57', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('284', '{EF1BDB85-59E4-442D-9E47-96B4E7A31F6B}', '66', 'INHE-0634', '2019-04-04 14:59:47', '0000-00-00 00:00:00', '2019-04-09 17:32:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040404/HOM', '', 'W-08/MCDC/2019', '2019年4月30日', 'Water Meter With Automated Meter Reading(AMR)system And AMR Based Water Meter', '100%合同货款在100%货物抵达MCDC仓库后支付；标书中未明确交期，需投标人在投标文件中主动提议明确；标书中未明确质保要求。代理商直接投标，银河供货，代理商给银河的支付方式可协商100%TT或者100%不可撤销的LC支付。', '{EF1BDB8559E4442D9E4796B4E7A31F6B8442F4C2B3234363A3D51C033076BD50}_W-08_MCDC_2019.pdf', '标书中未明确打分规则，但是有提到说每家的投标报价在4月30日递交样机的时候会立即公布。', '{EF1BDB8559E4442D9E4796B4E7A31F6B074E749A304748709C51373D9D483750}_Water Meter Tender (MM to EN).xlsx', '标书中未明确中标规则', '', '投标保函为缅甸币5000000 MMK，折合美元约3329 USD，开立行为缅甸国家银河MEB', '', '标书中未明确限定', '', '产品画册、GTP、AMR系统操作手册', '', '代理投标，银河供货', '', '', '', '全部货物入仓库后支付100%货款', '', '', '', '', '', '', '', '', '', '', '', '需要及时递交样机并在截标期前到MCDC做展示（MCDC希望投标人能做展示，以便他们更好的判断并作出选择）', '项目机会很好，建议立项，积极准备争取拿下。', '陈雁2019-04-04 15:32:04', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('285', '{F4EBFB0D-431A-4FB5-B952-67712E91620B}', '61', 'INHE-0776', '2019-04-04 10:37:25', '0000-00-00 00:00:00', '2019-04-09 17:33:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040405/PRU', '', 'N°0019628', '投标资料截止日：2019/4/12；递交样机截止日：2019/4/19；评审和发布中标：2019/4/13-4/24', '为智能测量系统供应电表，集中器和MDC / HES	SUMINISTRO DE MEDIDORES, CONCENTRADORES Y MDC/HES PARA SISTEMAS DE MEDICIóN INTELIGENTE', '价格条款：CIF Callao(卡亚俄（秘鲁西部港市）)或 DDP (Pasaje Calango N°158, San Juan de Miraflores, Lima)\r\r\n付款方：Tecsur S.A\r\r\r\r\n付款条件：如银河直投，到货后90天内支票支付（正在澄清是否可以开立信用证中）；如授权代理投标，代理向我方开立信用证或TT付款。\r\r\r\r\n交期: 6.22交付MDC/HES软件产品；7.22交付电表和集中器产品\r\r\r\r\n质保：2年', '', '1.供应产品（电表，集中器，MDC/HES）符合要求的程度：\r\r\r\r\r\r\n2.对实施智能电表试点项目所需服务的满足程度。\r\r\r\r\r\r\n3.投标人对遵守基础设施标准的承诺。\r\r\r\r\r\r\n4.质量保证和风险管理水平。\r\r\r\r\r\r\n5.投标人对可能的复杂部署方案是否在提案中提供了替代性技术方案。\r\r\r\r\r\r\n6.投标人在秘鲁本地和国际上的业务能力。\r\r\r\r\r\r\n7.参考国际同等项目。\r\r\r\r\r\r\n8.是否存在详细说明所提供产品和服务的技术文档。\r\r\r\r\r\r\n9.技术提案的清晰度和完整性。 \r\r', '', '两家表厂中标，可授权多个代理，共两个lot,但一个厂家只能中1个', '', '无投标保函要求；收到中标函后8个工作日内交付履约保函,金额为合同总金额的20%，如果没有在期限内交付保函且没有沟通，中标函将被取消。', '', '邀请四家表厂（银河、青岛乾程、科陆和海兴）参与技术议标，相关文件无强制要求，只做评估。', '', '需要客服部：提供相关技术应答；技术不符点及不符点处理建议；提供样机（4.19给出样机或于4.12前提供交样时间）；准备认证相关文件，落实认证所需时间。', '', '代理商投标', '', '此项目为电力公司自有资金支持，电力公司有完全决定权。', '', '到货后90天内支票支付。', '', '客户占秘鲁配电市场30%份额，效益好，支付能力较强。', '', '代理拥有一定的电力公司内部客户关系，但不算太强；代理老板四十多岁性格较好交流积极，业务能力较强，在电力和建筑承包行业有多年的经验，。', '', '此电力公司此前向银河采购过小规模试点样机进行测试，现认可银河产品，故邀请我方参与议标。通过代理拥有一定但不是太强的客户关系。', '', '目前知道另外三家竞争对手中乾程出现集中器事故，竞争力不强，故银河的中标机会较大。', '', '优势：我司产品质量优异，技术上基本满足要求，得到电力公司认可，\r\r\n劣势：无该市场产品强制要求的认证证书；客户关系不强；缺乏百分百把握能够赢得此议标。\r\r\n如何做：加强同代理关系，先让其维护客户关系为客户提供部分技术支持；尽快完成该市场强制认证；派业务在当地经营客户关系。', '', '客服和研发部门给出技术解析及不符点处理建议，尽快提供相关样机；后续客服在交货前支持完成相关认证提交证书，业务必要时候出差。', '', '李玟2019-04-04 18:17:26', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('286', '{213A8599-CB06-4C15-83EC-5385B363B6CB}', '61', 'INHE-0431', '2019-04-08 10:28:45', '0000-00-00 00:00:00', '2019-04-09 01:29:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040801/CYB', '请提供准确的技术规格以及标书（商务条件）和电力公司项目背景调查，规避对方就是替竞争对手做调查，花点钱买样机。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.波兰是中等收入国家，人均GDP12000USD，整个国家有5家电力公司，1300万用户，且正在往智能电表切换#FE54`2.CYB客户本来是做ICT设备起家，也做IoT,据称和电力公司关系良好，但是和哪一家或几家以及具体关系如何需要在后期合作沟通中逐步了解（目前对方也在边考核我们边透露更多信息）#FE54`3.CYB客户的计划是把表厂提供的电表和系统整合到他们的系统中去，然后打包成一个Smart Home的概念推到电力公司去。据他反馈目前已有电力公司明确表示有兴趣并让他们提供展示（Proof of Concept)的，所以他们才找到我们且要求先采购样机用于展示给电力公司#FE54`4.已经和CYB客户电话沟通过两次，客户有一定的诚意，且愿意花400美金买两个样机。沟通中他们也比较透明和开放，且提到目前的备选是银河和思达#FE54`5.目前计划是a.提供样机给CYB客户测试并整合到他们的系统中#FE54`b.利用CYB现有的电力公司客户资源和他们一起进行公关销售#FE54`c.从CYB入手开发波兰市场（同步也会了解电力公司和其它潜在代理的更多详情）同时寻找其它开拓。     ', '刘佩2019-04-08 14:25:16', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('287', '{E8520D7B-D223-414E-A2CE-E2CE1C22E2FC}', '61', 'INHE-0381', '2019-04-09 17:42:18', '0000-00-00 00:00:00', '2019-04-11 14:23:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040901/PLF', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.客户原本需要一个快速接线系统，以前立项为PLE。后客户经过评估，决定使用原有的营销系统做一些接线用户的管理。银河开发接口和现场使用的接线APP。2.黄总在2019年3月份出差的时候，已经跟客户多次讨论该需求。现客户希望提供一个技术方案和报价。', '张柳芳2019-04-09 18:18:16', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('288', '{245883E2-EE6E-46EA-9221-229B6FA1BF2B}', '66', 'JXINHE-2559', '2019-04-16 17:46:41', '0000-00-00 00:00:00', '2019-04-18 10:00:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041602/MSL', '', 'III10-PERIP/2019', '2019-06-11', 'Procurement for Supply & Installation of the Equipment for EDM Meter Laboratory/EDM电表实验室设备的供应和安装的采购项目', '预付款：收到付款申请和银行保函后，在签订合同的45天内，支付30%的合同款 \r\r\n装船：收到整套海运文件后的45天内，支付装船货物的合同款的30%\r\r\n安装：所有设备在EDM实验室成功安装和运作后的45天内，支付合同款的30%\r\r\n完工：采购方签发完工证书后45天内的支付合同款的10%。', '{245883E2EE6E46EA9221229B6FA1BF2B8442F4C2B3234363A3D51C033076BD50}_MSL项目--完整标书.pdf', '技术和价格标综合评定后，最低价中标。', '{245883E2EE6E46EA9221229B6FA1BF2B074E749A304748709C51373D9D483750}_MSL项目--标书摘要.docx', '一个包，一家中标', '', '投标保函：金额1万美元，有效期120天（投标有效期）+28天=148天\r\n履约保函：合同金额的10%，完工证书签发日期的一年后失效\r\n', '', '过去五年内执行过两个类似的电表实验室的项目\r\r\r\r\r\r\n提供由iLAC认证的实验室颁发的校准证书\r\r\r\r\r\n财务要求\r\r\r：\r\r\n过去五年经审计过的财务报告，若联合体投标，每一方都需满足要求\r\r\r\r\n过去五年年均最小营业额即类似累计在建或完工项目的共计收款金额为50万美元，若联合体投标，各方联合满足本要求\r\r\r\n经验和技术能力：\r\r\n投标人拥有至少五年供应和安装类似产品和服务的经验，若联合体投标，供货、安装和服务提供商应满足该要求。\r\r\n过去三年内，投标人拥有至少两个类似的合同经验，且供货范围和数量与本项目齐平。若联合体投标，供货、安装和服务提供商应满足该要求。\r\r\n投标人应提供纸质文件证明其在过去五年内提供过类似产品的安装和服务的经验。若联合体投标，各方联合满足本要求\r\r\n', '', '需找到合适的生产商按标书要求提供标书资料和产品报价等，全套文本需在5月10日前准备妥当。', '', '银河投标', '非联合体投标', '招标方评标，向世行推荐中标人，世行批准后即确定中标人。', '', '投标人向业主提出付款申请，业主向投标人支付货款。', '', '项目为世界银行筹款项目，电力公司付款流程细节待确定。', '', '暂不考虑与当地合作伙伴合作投标。', '', '通过MLG项目运作，和业主的相关人员建立了一定的关系，可加深与他们的关系，获得他们的支持，独立运作。', '', '科陆，科陆与我司前代理VBC合作，供应了50万台左右的单相电表给业主，但由于其电表的品质和服务问题，导致电力公司对科陆的能力感到质疑。', '', '择优选择合作伙伴提供有利的报价，通过利用已建立的人脉关系，获取项目决策层的支持，力争拿下项目。', '', '1.有竞争力的报价方案\r\n2.优质的合作伙伴提供产品的报价，服务和投标工作的配合', '通过MLG,MCT和EDP项目，熟悉了业主的项目相关人员并建立了一定的关系、对内部的评标工作流程有了一定的了解，我认为在获得优质供应商有竞争力的报价和服务的基础上，积极和项目决策接触，以寻求的支持，从而拿下项目。', '淦永妍2019-04-16 22:34:23', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('289', '{E6B6C31C-7A00-44B1-BEF9-B9A4F227AE34}', '171', 'INHE-0772', '2019-04-16 23:03:35', '0000-00-00 00:00:00', '2020-09-30 11:47:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041701/GBD', '', 'GM-NAWEC-88924-CW-RFB', '2020.11.06', 'Construction of 30kV line Laminkoto-Diabugu-Batapa with distribution network and secondary substations for Sami and Sandu districts villages 建设Sami and Sandu 村庄得配电网和二次变电站及从Laminkoto-Diabugu-Batapa的30KV线路项目', '中标后再议', '', '符合技术要求的最低价投标人', '', '1家中标', '', 'NA', '', 'NA', '', '技术应答文件，厂家授权', '', '授权投标', 'NA', '电力公司作为业主负责项目评标', '', 'NA', '', '支付能力强，项目资金非电力公司自身资金，是世界银行提供的无息远期贷款保证项目货款安全，付款流程由世界银行监督，不允许拖欠款项和挪用款项。', '', '冈比亚代理与电力公司内部高层关系密切，在冈比亚当地具有影响力。代理要求特变电工在电表部分向银河采购。特变在冈比亚的政府高层以及电力公司一把手的客情关系深，客情建设多年。', '', '业务和特变国际市场部的副总多年朋友，冈比亚的代理是副总介绍的。', '', '本项目是EPC项目，电表为其中一部分。特变的内部有专门的采购公司，目前同时向银河与海兴发起询价。', '', '优势：银河一线客情关系较深。劣势：项目限制，没有高压线路项目经验，项目范围上暂时也没有能力。银河当前无法直接投标。只能授权投标。特变的在公开竞投项目中价格比较高，这个项目原为特变的议标项目，因IMF限制冈比亚的贷款，后转为世行融资项目，在客情上有较深运作。目前了解到的竞争对手是印度公司，特变价格没有优势。特变目前的策略是通过技术评标把对手淘汰出去，价格上也申请了公司特批要求低价。状态：冈比亚代理可以协调特变中标后向银河采购，银河报价保持价格与市场水平相平，同步要求特变和银河签署标前合作协议，已发起审批流程。如有机会支持其他厂家，不违反标书条款下，计划授权多家投标。', '', '及时提供投标文件即可', '优势：银河一线客情关系较深。劣势：项目限制，银河无法投标。只能授权投标。特变的在国际竞投项目中价格一直比较高，这个项目原为特变的议标项目，因IMF限制冈比亚的贷款，后转为世行融资项目，特变在客情上有较深运作。目前了解到的竞争对手是印度公司，特变价格没有优势。特变目前的策略是通过技术评标把对手淘汰出去，价格上也申请了公司特批要求低价。加上客情建设，政府和电力公司高层拿了几年好处费，客情上会卖特变面子。中标几率相对其他投标人高，故支持特变投标。		\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n', '张子琦(Miranda)2020-09-29 10:15:30', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('290', '{943D1FCC-A1F8-4A94-958C-9ED070C7D291}', '61', 'INHE-0819', '2019-04-17 06:56:33', '0000-00-00 00:00:00', '2019-04-18 09:48:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041702/DMC', '项目背景：马达加斯加电力公司需要采购STS系统，前期电力公司总经理来访银河有过沟通，之后方案跟系统总监确认，现在准备签合同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '付为2019-04-17 07:31:41', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('291', '{8DC74F2A-1344-452A-8121-BC9725AFF329}', '61', 'INHE-0805', '2019-04-18 10:36:05', '0000-00-00 00:00:00', '2019-04-30 17:24:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041801/ECI', '项目代号为ECI。已安装要求附上代理对产品规格要求，请求立项通过！', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '由于项目主要需求2相3线表公司需要进行开模研发，代理商同意出资资助研发。约定的合作模式是代理出一部分研发费用，同时银河与代理约定一个销量值，在规定时间内代理的销量达到这个范围，银河可以退还该笔研发费用。所以需要研发部门对这个项目进行研究，协助业务给代理发一个达成合作的报价以及方案设计。 双方达成合作后需要先进行试点和认证，完成后可凭借代理母公司国企背景，参与全国性的电力公司采购招标。 已附上样机规格需求！', '翁达2019-04-28 14:32:29', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('292', '{A05EE175-DCBA-4787-A09C-CF4C16D4F1FB}', '61', 'INHE-0500', '2019-04-18 13:25:03', '0000-00-00 00:00:00', '2019-04-22 18:08:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041802/LEC', '', 'LEC/P0-899/2018/19', '2019年4月25日', 'Tender for supply of automatic meter reading针对约新增1000台LPU用户，设计、试运行和交付智能自动抄表系统（AMR）系统招标项目', '价格条款：当地币或者国际通用货币报价，DDP条款报价；\r\n付款主体：莱索托国家电力公司，具体支付方式未明确；\r\n交期：未明确，根据代理反馈，要求2个月内完成；\r\n质保：终身质保，签订服务水平协议；\r\n代理和银河付款方式：T/T。', '', '1.商务评审优先，评审OK后进入到技术评审；\r\r\n2.技术评审，评分规则未明确，技术评审后占比85%；\r\r\n3.价格评审：占比20%。', '', '一家中标', '', '投标保函：代理开立\r\n履约保函：未明确，最终如要求开立由代理负责', '', '1.最近10年财务审计报告（已要求澄清，问题不大）；\r\n2.提供至少3个类似项目实施证明；', '', '1.商务资料业务小组自行完成；\r\n2.技术资料由客服协助完成。最晚提交时间4月19日。', '', '代理直接投标', 'N/A', '1.政治影响为主，决策层主要在董事会最终话语权（董事会主席和CEO）', '', '标书未明确，待进一步了解', '', '暂无相关信息，待进一步了解', '', '1.代理公司老板为当前LEC董事会主席的妻弟，主要依靠内部关系取得电力公司项目；\r\n2.代理老板约40岁，联系积极，信息获取较快，思路清晰，沟通较为畅通。', '', '暂无业主层面的客户关系，待后续中标后拓展', '', '主要竞争对手：兰吉尔、Conlog、海兴和EDMI\r\r\n1.兰吉尔和Conlog南非团队直接投标；\r\n2.海兴和EDMI在当地有合作代理投标，合作代理的实力暂未相关信息了解。\r\n', '', '1.银河合作代理电力公司高层力量较强（待最终核实），代理反馈积极，策略沟通和执行较为顺畅；\r\r\r\n\r2.银河在南非Eskom和部分市政的供货记录以及其他市场的供货记录优势，已发给代理和其内线，据其内线反馈对银河的供货资质非常满意；\r\n3.银河对电力公司层面无客户关系和详细信息了解，信息的反馈来源为代理；\r\r\r\r\n4.此市场相对封闭，竞争不充分，在核实代理实力的基础上，进入短名单问题不大，下一步在进入短名单后需要派遣业务人员到现场或者要求LEC管理人员来访银河或者CDN，促进和巩固客户关系，拿下项目。', '', '1.及时提供完整的投标资料，并配合代理完成投标工作；\r\n2.和代理内线确认最终的投标报价和内部利益分配；', '东南非1组新市场投标项目，代理内部高层政治实力据目前信息了解可以初步证实，业务正在和代理做策略沟通，请公司支持。', '李忠鹏2019-04-18 14:07:47', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('293', '{1C896E5D-D58C-4022-8878-46C87210F1DD}', '61', 'INHE-0432', '2019-04-22 16:08:01', '0000-00-00 00:00:00', '2019-04-24 15:51:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019042201/KAR', '', 'KP1/9A.3/OT/14/18-19', '2019年5月21号', '自动重合器供应9FOR THE SUPPLY OF 11KV & 33KV AUTORECLOSER', '1.交期要求：\r\r\n11kv 自动重合器：2019年12月交货20台；2020年3月交货25台；2020年6月交货20台；\r\r\n33KV自动重合器：2019年10年交货30台；2019年12月交货30台；2020年3月交货20台；2020年6月交货22台；\r\r\n2.价格：DDP含税\r\r\n3.付款：在满意交付后，递交发票及相关要求文件起的30天内付款            4.在交货到电力公司仓库起1年的质保有效期', '', '1.初始评审：核查是否提交标书所要求的资料；\r\r\n2.技术评审：核查投标者提供的技术资料，看是否满足技术规格；\r\r\n3.财务评审：核查投标方保函的真实性；报价单等相关资料\r\r\n综合评审，最低价格且满足技术要求者中标\r\r\r\n', '', '1.综合评审，最低价格且满足技术要求者中标\r\r\n2.一家厂商，可以授权多个代理商投标                                     3.两个LOT，分开授标。但标书没说明是否可以授标给1家或者不同的2家。', '', '投标保函：\r\n11kv 自动重合器；保函金额：481,650 KSH\r\n33 kv 自动重合器#FE54`保函金额：901,800 KSH\r\n履约保函：10%的合同金额；在收到中标通知的14天内提交。\r\n', '', '本地优惠政策：\r\n1.只有在肯尼亚完全生产的制成品或在肯尼亚进行组装才会享受优先采购；\r\n2.肯尼亚本地企业需要有肯尼亚人时股东，且肯尼亚人占有的股东份额大于51%；\r\n供货记录：\r\n1.生产上要求：至少有15年的生产自动离合器的经验；\r\n2.在过去5年海外销售至少1500台自动离合器；\r\n3.海外供货记录需要包括：买方名称，年份，数量及买方联系方式；\r\n4.至少提供4份客户推荐函Letters of Customer Satisfaction；\r\n\r\n资质文件：\r\n1.投标人应提交至少4个类似产品供货的客户的联系方式及地址；及用户证明表明按期执行合同；\r\n2.产品型测证书及相关报告及实验室资质证书IEC17025；\r\n3. 需要提供Certificate of Routine Test Reports\r\n4.国外厂商提供ISO 9001证书（Certified as a true copy of the original together with the tender bid）\r\n4.本地厂商直接投标需要提供KEBS证书', '', '需要国内商务组协助跟进保函、协助跟进智能配网及公司采购资源部，获取供应商资料、报价等。', '', '深圳银河、IAC均可直接投标；', '', '', '', '', '', '', '', '代理表示全力支持此项目。业务更希望以IAC名义投标并拿下。', '', '较好。', '', '详见开标结果', '', '竞争策略：\r\r\n1.深圳银河、IAC均直接投标。\r\r\n2.优选合作伙伴、技术资料、报价以珠海智能配网公司为主；但如果其合作厂商无法满足技术要求，或者最终总体价格过高，则需要公司采购资源部同时寻找其他厂商；业务也会在一线寻找合适的厂商，推荐给采购资源部负责联络；最终综合对比，最终选择最合适的厂商投标。\r\r\n3.最终投标报价：利润不能加太高，否则本生就不是我们的主营业务，如果价格过高，则没有任何优势。\r\r\n\r\r\n竞争优势：负责该项目的客户关系与我方较好，本地代理合作伙伴也全力支持；\r\r\n竞争劣势：银河不是生产厂商，需要外协厂商合作；最终投标价格相对厂商直接投标，可能没优势。\r\r\n', '', '1.需要珠海配网公司全力支持，选择最符合要求的厂商合作（技术满足，价格有竞争力）\r\r\n2.需要深圳银河开2张投标保函：一份是给深圳银河自己投标，一份是给IAC投标。\r\r\n\r\r\n3.外协厂商的资料、报价信息等，需要商务组协助跟进\r\r\n', '\r\r\n上次中标人信息，业务核实后反馈。项目金额不大，但值得银河，尤其IAC去做。希望公司给与及时支持。', '谭东羊2019-04-22 18:41:44', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('294', '{98587AA8-014A-4BF2-BA04-0CCB6876414A}', '61', 'INHE-0381', '2019-04-24 16:40:36', '0000-00-00 00:00:00', '2019-04-28 14:40:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2019042401/GNG', '', '暂无', '暂未放标', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '现需要客服部的技术支持。', '目前已收到技术规格，现立项。需要对技术规格认真解析，并增加一些技术门槛。', '张柳芳2019-04-24 17:14:45', '03', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('295', '{B5E771C8-3064-4AD5-A579-5AC3C48A371C}', '61', 'INHE-0500', '2019-04-26 05:12:39', '0000-00-00 00:00:00', '2019-04-28 16:16:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019042601/DXE', '', 'DX771', '2019年6月19日南非时间上午10点2019年5月10日标前强制性会议上午9点', 'REQUEST FOR PROPOSAL (RFP) FOR The manufacture and supply of the smart prepayment system on an “as and when required” basis for Distribution Division.ESKOM关于智能分体式电表和集抄管理系统的5年框架性招标Bid Number标号: DX7711.Single Phase Smart Meter + CIU单相智能分体式电表: 884 000台2.Three Phase Smart Meter + CIU三相智能分体式电表: 816 000台3.Data Concentrator集中器:             56 666台Head End Systems集抄系统:            Minimum 2至少两套集抄系统', '报价方式：\r\n1.电气化工程报价（Electrification）: estimated quantities will be 200?000 ~ 300?000 meters per year or 1 M ~ 1.5M meters over 5 year period.\r\n2.非电气化工程报价（Non-Electrification）: estimated quantities will be 60000-100000 meters per year or 300?000 - 500?000 meters over 5 year period.\r\n报价条款：DDP报价，兰特币。\r\n银河对NYC报价：FOB Shenzhenn \r\n付款条件：交货后收到发票的30天内支付本地币。\r\nNYC对银河付款条件：同ESA项目。 \r\n资金来源：National Treasury\r\n', '{B5E771C830644AD5A5795AC3C48A371C8442F4C2B3234363A3D51C033076BD50}_1.1 RFP Smart Meter Final Part 1 (2).pdf', '1.基础评估\r\n2.强制投标文件评估\r\n3.资质预审评估\r\n4.本地化生产比例评估\r\n5.产品功能性评估\r\n6.财务评估\r\n7.价格及倾向性评估\r\n其他\r\n', '{B5E771C830644AD5A5795AC3C48A371C074E749A304748709C51373D9D483750}_1.2 RFP Smart Meter Final Part 2.pdf', '按照评标规则评估，根据报价采取80/20或者90/10评分标准；ESKOM挑选短名单，后期进入合同协商阶段。\r\n?HES系统：得分最高者中标，ESKOM已有一家HES供应商，至少再授标2家供应商。\r\n智能电表：至少2家、至多5家中标。\r\n', '{B5E771C830644AD5A5795AC3C48A371C2B47EB25ABE84FF19C47768372BB342D}_Annexures F2, F3 & F4.xls', '投标无需保函，中标后需开立履约保函，由NYC开立', '{B5E771C830644AD5A5795AC3C48A371C1DD410FC292E4E1893AFBEF9F88431CD}_Annexure G -Tax compliance questionnaire for foreign suppliers.pdf', '智能电表本地化生产至少达到50%，黑人持股至少占到51%，BBBEE资质要求,CSD& National Treasury注册登记，本地服务支持\r\r\r\n黑人持股至少占到51%，CSD注册企业，BBBEE证书等级等\r\r\n最近两年的审计财务报告\r\n', '{B5E771C830644AD5A5795AC3C48A371C03404677E4D44E9EB56B3D512B2AF9CC}_C0 SC3 Contract cover pages Rev1.pdf', '1.需要客服和研发仔细研读标书的技术规格和资料，要求在5月6日前提供需要澄清的或者不符项；\r\n2.需要客服协助提供标书重点要求的技术资料；\r\n3.商务部分由业务内部完成，建议最终的投标资料申请商务组长复核。', '{B5E771C830644AD5A5795AC3C48A371CC675BD0CC93442C09B990884D4324504}_C1 1 SC3 Offer Acceptance (3 Rev1.pdf', 'NYC直接投标，银河作为厂商支持', 'N/A', '1.高层政府/政治关系在授标中占据主导作用；\r\n2.ESKOM评标团队中技术层面在初审阶段占据主导作用。', '', '银河对NYC报价：FOB Shenzhenn \r\n付款条件：交货后收到发票的30天内支付本地币。\r\nNYC对银河付款条件：同ESA项目。 \r\n资金来源：National Treasury\r\n', '', '待进一步分析ESKOM年度财务报告', '', '银河合作代理NYC\r\r\n政府/ESKOM层面关系：PBF，DTI，以及ESKOM COO等层面有一定客户关系，但在技术层面无客户关系，采购层面有一定内部关系；\r\r\n代理公司管理层面：经营目标明确，管理层稳定，竞争策略上行动力较强，愿意和银河一起组织客户和市场关系进攻；\r\n代理公司财力层面：当前受到EST项目影响，代理银行贷款审批暂无通过，资金流上有一定压力。', '', '政府层面：从EST竞标开始和代理接触了DTI，PBF等执政党和国家工信部等高官；\r\nESKOM层面：暂无实际的客户关系；', '', '1.Voltex，EST中标公司之一，现总统下属企业，政治影响力和财力最强，电表主要依靠中国表厂，EST是思达供货，ESI的供货表厂暂无信息反馈；\r\n2.兰吉尔，ESA和EST中标公司之一，技术规格的主要幕后制定者，在ESKOM内部技术层面和南非国家标准委员会，STS，SABS都有很强影响力；\r\n3.Conlog，背后依靠国资委部长，ESKOM内部技术影响力较强；\r\n4.ACTOM，依靠本地强大的印度裔政治力量，加上雄厚的资金实力，背后为海兴支持。', '', '1.NYC BBBEE Level 1和本地工厂通过了SABS 70%本地化政策审核，满足招标入门门槛；\r\r\n2.NYC在执政党PBF、DTI以及现在财政部副部长的部分资源支持，客户关系还在进一步拓展加深；\r\n3.需要适当联合本地政治影响力较强的公司如Voltex等，寻求背靠背合作；\r\n4.技术资料需要尽快完成评估，设法完成技术澄清，保证技术方面100%符合；', '', '1.技术资料需要尽早完成评审，并提交技术澄清，保证技术层面100%符合；\r\n2.借助EST当前的竞争态势，加快跟进NYC在执政党、工信部和财政部的客户关系和影响力；\r\n3.寻求和Voltex等公司的背靠背合作。', '1.DXE项目极为重要，业务已提前申请客服精干力量进行技术解析和技术资料协助，需要公司全力的技术支持，同时已和NYC协商成立内部投标小组，负责全部客户关系和商务事宜沟通；', '李忠鹏2019-04-26 06:01:39', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('296', '{7EE85679-37E5-4A8F-A42B-D3841D862E77}', '61', 'INHE-0431', '2019-04-26 21:03:31', '0000-00-00 00:00:00', '2019-04-29 15:16:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2019042602/TEB', '', '暂未招标', '暂未招标', '暂未招标', '暂未招标', '', '暂未招标', '', '一家中标', '', '暂未招标', '', '1.不少于五年的生产经验：2.生产国外有三年供货经验 ，订单不少于5万台', '', '和UNW一样', '', '银河直投', '无', '中国政府对招标方特变电工应该影响不大，但是乌干达业主(农网）应该可以有一定影响', '', '暂未招标', '', '招标方是总包商，招电表不是常规操作。据新闻和内线所说特变是带着口行的资金做的这个项目，所以资金问题不大', '', '计划和UNW内线合作，他们已经帮助我们在UNW项目中进入合同谈判阶段。他们是农网的技术中层人员，和ED有良好关系', '', '特变电工的关系一般，只和他们乌干达办室处有一定联系。但是和业主关系不错', '', '因为是国内二次招标，所以国内的主要竞争对手应该都会参与，包括不限于 海兴，科陆，三星，矩华等', '', '劣势：1.特变电工作为国内大型EPC总包有自己的内部流程，国内二次公开招标，且不低于5家报价是最低要求；2.总承包商特变电工无良好关系，仅认识乌干达项目部的相关人员；3.国内的其它供应商，如矩华和三星据称和特变电工关系良好；4.他们的报价比我们低（参考UNW开标结果）#FE54`\r\r\r\n优势：1.和最终用户（农网）关系很好#FE54`2.UNW项目有良好的参考意义（标书技术部分是完全一样的）', '', '关键：1.通过内线做足农网的关系让他们一票否决其它人，且强烈推荐我们做为候选人#FE54`2.通过乌干达项目部的相关人员关系了解并配合通过他们总部的标准采购流程；所需支持：1.可能需要围标（具体看项目进展再汇报）', '这个项目是我们较少参与的国内二次招标。总承包商关系一般，乌干达项目部对于总部采购基本无话语标。所以计划从业主（农网）入手。利用他们推荐我们中标。我们的优势就是在UNW合作中与业主建议的良好关系。', '刘佩2019-04-26 23:10:54', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('297', '{46C3198E-89DD-4B5E-BBE6-EA59B0C1BC8A}', '61', 'INHE-0654', '2019-05-05 15:54:53', '0000-00-00 00:00:00', '2019-05-09 13:52:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050503/BGL', '', 'Lp1463-18/Lp1465-18', '2019/05/21', 'Adquisicion de Medidores Electronicos de Conexion Directa/Indirecta 直接/间接接入式的电子仪表', '授权代理投标，付款方式：预付款（具体百分比可谈）+远期不可撤销的90/120天信用证。', '{46C3198E89DD4B5EBBE6EA59B0C1BC8A8442F4C2B3234363A3D51C033076BD50}_ANDE Mono 2019[1].pdf', '先测技术部分，电力公司实验室先测试技术部分。', '', '', '', '代理负责开保函。', '', '', '', '投标资料需要西语版，业务已经准备完。', '', '代理投标。', '', '', '', '', '', '', '', '', '', '代理公司的售电系统在该电力公司使用，并且多年关系，可见还是有一定的客户关系在，并且巴拉圭与阿根廷之间相互影响，巴拉圭电表有自己的当地认证，但是该国认可阿根廷的IRAM/INTI认证，固电力公司接受投标，认证可以在中标后做即可。', '', '目前中国厂家有海兴和科陆，电力公司人反馈海兴供货的产品出现过问题，但看科陆关系较好，并且4月份电力公司技术人员刚刚来访深圳并且参观科陆工厂。', '', '整体来看，首先项目情况是很靠谱的，并且代理也靠谱，做事认真严谨，会做商务关系，银河的优势就我目前来看只能从产品上来说话，并且加上目前在阿根廷EDENOR电力公司银河中标，并且是AMI实施项目，这个是有一定的影响力，但是产品认知度和熟悉度以及服务来看肯定不如竞争对手，但终归还是要去参与，否则南美市场的状态会一直停歇不前，并且是其他竞争对手在AMI项目上也无很大的经验，无具体的成功案例市场，所以我认为当下有项目来了，银河应当参与。', '', '1，样机交付的及时。2，技术资料提供准确无误，尤其软件ＡＭＩ的资料。', '１，代理公司是真真切切的只做电表和软件业务，虽说没有对该项目百分之百的把握，但是还是希望较大，而且对于电力公司来说多一个选择也是好的。２，该国家只有这一家电力公司，并且是软件ＡＭＩ交付项目，值得参与。３，技术应答部分未翻译，之前与客服部高工当面核对过，银河都符合满足，附件先附加上，待立项通过发起样机申请是会附上翻译好的技术规格。', '李明2019-05-05 18:30:59', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('298', '{39E6C45B-B317-48D5-B913-C9378C137FEE}', '60', 'INHE-0790', '2019-05-05 16:39:57', '0000-00-00 00:00:00', '2019-05-07 12:48:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050504/JIC', '', '直采项目', '无', '无', '30% TT预付款，40%签订合同后一个月支付，30%尾款发货前支付。价格条款FOB HK或FOB Shenzhen。', '', '无', '', '无', '', '无', '', '无', '', '无', '', '无', '无', '无', '', '30% TT预付款，40%签订合同后一个月支付，30%尾款发货前支付。价格条款FOB HK或FOB Shenzhen。						\r\r\n', '', '支付能力良好。', '', '主要负责私人直采项目，年龄50岁左右，性格谨慎，公司规模较小。', '', '银河老客户，订单从JES01一直做到现在的JES11。', '', '主要是负责当地一些商场及民居的电表直采项目，也参加电力公司的招标项目。需求产品多数为银河现有产品。', '', '银河老客户，一直是在我们公司买的电表，包括之前他们有派工程师到银河接受培训，订单都是直接下给我们，且多为银河现有产品。', '', '由于主要涉及到表计程序修改，因此成功关键需要研发部门的鼎力相助和业务对客户的积极配合。', '', '莫亚检2019-05-05 19:39:21', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('299', '{B6EDCC4B-3FE3-40B2-B6BE-5D47673273FB}', '61', 'INHE-0805', '2019-05-06 13:37:52', '0000-00-00 00:00:00', '2019-05-09 13:50:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050601/CME', '项目代号CME, 请批准立项', 'INVITACIóN A COTIZAR EHUI-SC-042-2019', '2019/05/09', '', '授权代理投标，付款方式为30%预付款T/T 以及70%尾款 T/T', '{B6EDCC4B3FE340B2B6BE5D47673273FB8442F4C2B3234363A3D51C033076BD50}_EHUI-SC-042-2019 TERMINOS DE REFERENCIA.pdf', '针对投标公司产品、财务以及经营状况进行打分（代理提供）', '{B6EDCC4B3FE340B2B6BE5D47673273FB074E749A304748709C51373D9D483750}_EHU投标项目信息归纳表.doc', '可一家独中或者由电力公司分标', '{B6EDCC4B3FE340B2B6BE5D47673273FB2B47EB25ABE84FF19C47768372BB342D}_EHU投标项目信息归纳表.doc', '由代理开具保函', '{B6EDCC4B3FE340B2B6BE5D47673273FB1DD410FC292E4E1893AFBEF9F88431CD}_EHU投标项目信息归纳表.doc', '5年经营资质以及相关财务证明', '{B6EDCC4B3FE340B2B6BE5D47673273FB03404677E4D44E9EB56B3D512B2AF9CC}_EHU投标项目信息归纳表.doc', '借鉴往期投标商务资料，需尽快准备大计量箱的技术性资料，需本周提交', '{B6EDCC4B3FE340B2B6BE5D47673273FBC675BD0CC93442C09B990884D4324504}_CME项目投标文件列表.xlsx', '代理商投标', '', '', '', 'ELECTROHUILA', '', '电力公司财务状况良好，代理公司也有足够的支付能力', '', '哥伦比亚合作多年代理，对我司产品熟悉度高，与该电力公司有较好的客户关系', '', '代理与电力公司关系良好，银河也曾供应过上百台CT表给该电力公司，品牌形象良好', '', '有另外两家竞争对手，海兴以及哥伦比亚本土企业excelec', '', '相比于其他两个对手银河没有本地服务团队，需做好客情跟踪', '', '需要银河尽快确认大计量箱的方案以及相关技术文档准备', '哥伦比亚市场AMI计划第一单投标，项目的电力公司ELECTROHUILA是银河在哥伦比亚最重要的几个客户之一。此项目如果中标电力公司将整体迁移使用银河系统，对于未来5年持续拿单有重大影响意义.', '翁达2019-05-06 18:32:37', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('300', '{9332AF12-0380-4CB3-B2EF-AEE6307E7AB7}', '60', 'INHE-0560', '2019-05-06 09:28:03', '0000-00-00 00:00:00', '2019-05-09 14:00:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050602/EMH', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户已经涉猎在电力能源行业涉猎多年，与电力公司关系较为密切。每年与电力公司都有稳定的订单，由于其之前销售的是德国仪表，价格方面一直处于不利的竞争地位。客户希望通过与我司的合作，帮助其降低成本，提高表计市场份额，并提出我司可使用自己的品牌入驻当地市场。', '', '', '', '当前乌克兰有31个州电力公司，全部实行了私有化。各个州的电力公司在采购电力相关设备时都有其自主权，因此其表计市场呈现百家争鸣之态，不同的表计供应商分别与其中一些电力公司展开合作。目前其国内做的比较大的几家表计供应商有摩尔多瓦的Add-Grup，Iskrasi, Itron，乌克兰本地市场的竞争对手是ооо《NIk》公司，MEA客户，Goshen客户，Add-Grup公司未来几年的主要市场为保加利亚，在乌克兰的目标销量不多。                                 \r\r\r\r\r\r\nIskrasi,Itron两家公司从其在乌克兰市场的表计销售价格来看，其供应产品多为低端简单表，市场占有率稳定但不高。其国内表计制造商《NIk》公司经营范围很广，表计产品属于其一个分支，虽然有自己的表厂但几乎依靠国外进口表计供应其国内市场，产品价格普遍较低，属于中低端产品。由于其在国内基本保持低价竞争策略且产品质量表现不佳，因而产品质量为很多终端客户诟病，这为其余优质表计厂家提供了市场机遇。                                                  ', '', '竞争策略：客户目前希望拿到我司常规产品进行测试，测试通过后，开始在电力公司进行小批量试点并同步进行认证工作。我司常规产品必须能在前期通过客户实验室的测试，这是开展后面合作的基础和敲门砖。                            劣势：EMH项目客户同意使用我司自己的品牌，合作进展顺利的话，后续面对的一个问题就是Goshen客户及MEA客户都会知晓我司与EMH进行合作，几家公司之间有可能相互压价，对我司形成不利局面。', '', '成功关键：样机测试通过                                                                                 需要的支持：客户样机测试期间，我司及时的技术支持协助。', '建议立项', '李美娇2019-05-06 16:47:12', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('301', '{939909D9-E396-416A-BF39-66997937BAB9}', '61', 'INHE-0721', '2019-05-16 15:16:22', '0000-00-00 00:00:00', '2019-05-16 15:16:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019051602/UKA', '', 'Nr. 52323', '2019.06.03', 'SUMINISTRO DE MEDIDORES BáSICOS INTELIGENTES Y EL SOFTWARE ASOCIADO, TRABAJANDO EN UNA SOLUCIóN AMI (ADVANCED METERING INFRAESTRUCTURE)#FE54` Y EL SERVICIO DE CONSULTORíA Y MANTENIMIENTO CORRESPONDIENTE 提供智能基本仪表和相关软件，使用AMI（高级计量基础设施）解决方案#FE54` 以及相应的咨询和维护服务', '授权代理投标，', '', '商务文件符合要求，样机的技术符合标书要求，报价低者中标。', '', '一家中标', '', '投标保函（不低于20万USD,代理开立）', '', '1.实施过AMI项目，每个项目测量点超过5万个；2.供货记录（招标产品数量的两倍）', '', '商务组协助制作商务文件（厂商资质文件，供货记录，3年质保函，技术支持承诺函及其他标书中要求的资料）；技术支持协助提供该项目投标所需技术文件（完成技术解析、推荐表型，技术应答，提供认证证书、报告等标书中要求的技术资料）', '', '代理投标', '', 'UTE是国有电力公司，招标方拥有绝对的采购决策权', '', '1.只有样机试点测试通过，才同意继续采购；2.item1和item3货交付款；3.AMI软件在试点测试通过后付款；4.item2.3AMI软件咨询服务30%+50%+20%', '', 'UTE电力公司信誉较好，支付能力较好', '', '此次授权的是ADD市场的代理投标，代理商靠谱，在该电力公司有一定的商务关系。该代理的业务经理曾任职于UTE电力公司，且与该电力公司保持良好的关系，获取信息及时有效。', '', '代理在电力公司有一定的商务关系', '', '目前该市场主要的竞争对手有海兴，科陆，开发，此前一直都是开发中标，且供货。', '', '劣势：此前未在该市场供货，与电力公司未建立直接的客户关系； 优势：代理在电力公司有一定的商务关系；AMI项目实施经验较丰富，投标产品供货记录良好', '', '样机技术符合招标要求，价格合理，投标商务及技术文件准确、精致、有竞争力。 需要商务组及技术部门提供相应支持，协助完成投标资料的制作以及样机制作，顺利参与投标。', '该市场竞争对手角逐激烈，且开发在该市场已有代理，中标并供货。但此次招标数量可观，且在近几年有持续的产品及软件需求。该市场有计划在2018~2021这四年间完成智能电表全国范围覆盖，市场前景较大。业务建议公司给予相关支持，参与此次投标！', '胡云义2019-05-16 18:14:07', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('302', '{7B7155EB-BC77-4AB6-8C66-1BFC3914066D}', '61', 'INHE-0776', '2019-05-20 16:43:14', '0000-00-00 00:00:00', '2019-05-24 09:30:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019052001/PRH', '', 'LICITACIóN PúBLICA N ° 001-2019-HDNA-1', '2019.5.22', 'HIDRANDINA S.A.公司采购为发电站，大客户及配电变电站使用的三相电子多功能电表CONTRATACIóN DE BIENES“ADQUISICIóN DE MEDIDORES TRIFáSICOS ELECTRóNICOS MULTIFUNCIóN PARA SUBESTACIONES DE POTENCIA, PUNTOS DE COMPRA, CENTRALES DE GENERACION, CLIENTES MAYORES Y SUBESTACIONES DE DISTRIBUCIóN, PARA LA EMPRESA HIDRANDINA S.A.”', '价格DDP条款；电力公司使用财政预算付款；\r\r\r\r\r\n交期：\r\r\r\r\n第一次交付40％，90天交货\r，检验合格后15天内付款\r；\r\r\r\r\n第二次交付30％ 120天交货\r，检验合格后15天内付款；\r\r\r\r\n\r第三次交付30％ 150天交货\r，检验合格后15天内付款。\r\r\r\n质保：至少五年。\r\r\n代理对银河付款方式初步商议为30%预付款，70%信用证。', '', '1.价格因素占90分。计算公式为：得分数=最低报价*最高分数/报价；\r\r\r\r\r\n2.交期因素占5分。计算公式为：第一批交货时间为80-83日历日得5分，84-86日历日得3分，87-89日历日得1分；\r\r\r\n3.质保因素占5分。计算公式为承诺质保时间为5-6年得1分，6-7年得3分，大于7年得5分。', '', '一家制造商只能授权一个代理', '', '履约保函，为合同金额的百分之十（10％）；零部件保函，相当于合同金额的百分之十（10％）。', '', '投标人必须要有制造商的独家授权，且在市场内有向电力公司销售0.2S级电表和A级电表达到80万美金的累计销售额。', '', '技术应答表和相关证书；5月21日前；客服已提前基本提供完成。', '', '代理商投标', '不采用', '技术报价评标，无过多政府干涉。', '', '每批交货现场检验合格后10天内开出确认书，15天内银行付款。', '', '电力公司年销售额2.8亿美金，除去采购物料设备外的净利润约3000千万美金；代理公司年销售额200万美金。', '', '我司业务曾与电力公司利马区商务经理见面，代理做事细致，客户关系较强，内部团结融洽。', '', '', '', '目前已知竞争对手有PROCETRADI S.A.C.代理威胜；TECH INDUSTRIAS GLOBALES S.R.L. 代理EMH；', '', '此项目为Distriluz今年CT表采购的第一批，后续还有约6000台采购计划；银河产品过关，价格拥有竞争力，有合适且参与意愿强烈的代理；我们能够通过较好的价格参与竞投。', '', '有竞争力的价格支持。', '积极参与，争取中标。', '李玟2019-05-21 10:42:27', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('303', '{35B8C4AA-5E4F-40FC-88B2-396D2DD62C92}', '61', 'INHE-0725', '2019-05-27 16:51:13', '0000-00-00 00:00:00', '2019-06-05 09:12:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019052702/IEL', '', '待定', '预计今年9-10月份', '暂无，项目主要招标单三相预付费IC卡表并包括后续电表安装维护', '【价格条款】：DDP AEDC仓库\r\r\n【付款主体】：AEDC\r\r\n【付款条件】：\r\r\n1）10%-15%预付款\r\r\n2）完成验收后支付50%货款\r\r\n3）完成安装后支付30%货款\r\r\n4）剩余5%-10%货款作为抵押款在质保期结束后支付（如想提前拿回抵押款可开具保函，保函金额可与招标方协商，本地表厂一般为提前取回抵押款会提供为期一年的保函，针对后续质保期则会提供电表质保证书；\r\r\n注：有时招标方在完成电表验收后即支付80%货款，具体付款条件可与招标方协商；\r\r\n【交期】：收到中标函后四个月完成货物交付\r\r\n【质保】：一般为三年\r\r\n【违约条款】：无特殊要求\r\n\r\n代理商对银河的付款方式：暂未确定，业务正与代理洽谈争取对我方有利的付款方式。', '', '先技术评标，后商务评标，技术满足，价格低者优先。', '', '一家中标', '', '待定', '', '要求投标方满足40%本地化生产（本地有表厂合作或建厂），无公司年限，财务数据，供货记录要求；\r\r\n资质证书及测试报告：要求获取五年内国际或埃及国内测试就出具的质量检测报告；EEHC颁布的表计通过测试的证书；Ntra证书（军方企业出具，主要关于产品安全方面）；E-Finance，Fawry出具的证书（电表需能兼容E-Finance，Fawry的账单系统）\r\r\n详情请见附件：【埃及市场标书一般性商务条款】', '{35B8C4AA5E4F40FC88B2396D2DD62C9203404677E4D44E9EB56B3D512B2AF9CC}_埃及市场标书一般性商务条款.docx', '暂无，业务后续会基于项目情况和公司提出申请，目前需要提供样机完成EEHC电表测试，后续采购资格参与投标，【EEHC表计测试详细要求】如附件', '{35B8C4AA5E4F40FC88B2396D2DD62C92C675BD0CC93442C09B990884D4324504}_EEHC表计测试详细要求.docx', '代理商投标，银河为代理商供电表SKD散件（CIF亚历山大港）', '代理商投标', '招标方AEDC可决定中标方，电力行业主管部门EEHC虽然负责对中标结果的核查，但不影响中标结果。\r\n评标委员会由招标方技术主管及财务主管指定，一般为3-5人，其中一人为财务人员，剩余为技术工程师，财务人员对于电表售电方面会有较多要求，如在技术要求初步满足本地普遍技术规格情况下，财务人员的决策力相对较高', '', '签订采购合同10天内支付10%-15%预付款；\r\r\n电表完成验收后支付50%货款；\r\r\n电表完成安装欧支付30%货款；\r\r\n5%-10%货款作为抵押款在质保期结束后支付（本地表厂一般为提前取回抵押款会开具有效期为一年的保函，针对剩余保质期则出具电表质保证书）\r\r\n\r\r\n注：有时招标方完成电表验收后即支付80%货款，具体付款方式可与招标方协商。\r\n\r\n与合作伙伴的付款条件：暂未确定，业务正在与代理洽谈为我方争取有利付款条件。', '', '招标方（AEDC）经济实力待核实，业务在本地了解到埃及市场包括AEDC在内的九家电力公司统一采用上述付款方式，并且在过往项目的执行过程中，电力公司支付货款这一环节暂未出现拖欠或拒绝支付的现象。', '', '合作伙伴Energy-Lux对于本地市场情况较为熟悉，老板Hatem曾经以项目经理的职位在El Sewedy工作了20多年，而后在四年前成立新公司Energy-lux，主营LED，防火报警设备及中压设备等产品；与军方做过项目，有一定的客户关系；同时与EEHC的副主席，表计部门技术总监，项目总监较为熟识，同时与本地电力公司尤其是AEDC以及North Cairo电力公司有较强的客户关系。\r\r\r\n注：Energy-Lux公司介绍请见附件', '{35B8C4AA5E4F40FC88B2396D2DD62C92D18C251E4D454BA8A05CF92EE9AFCB77}_Energy-Lux 公司介绍.pdf', '经过开发，目前我方通过代理与EEHC的副主席，表计部门技术总监，项目总监建立了联系，同时自行开发了EEHC内线：表计测试工程师及表计测试委员会三把手）\r\n同时代理与North Cairo以及Alexander的领导层较为熟识。', '{35B8C4AA5E4F40FC88B2396D2DD62C92829EEF953ECA4F9B96CB5DED652FA321}_银河国际埃及市场客户档案—电力公司客户档案.xls', '目前该市场针对预付费电表招标项目主要有六个玩家：\r\r\r\n1.AOI：下辖Electronic Factory及Benha Electronics，合作伙伴为三星（单相预付费IC卡表），海兴（三相预付费IC卡表）；\r\r\r\n2.El Sewedy：下辖Iskra及Electrometer两家表厂，Iskra目前主要和威胜合作（威胜做贴牌）；\r\r\r\n3.Global Tronics：与法国Sagemcom合作，技术最强；\r\r\r\n4.El Massara(Factory 45):与ADD合作；\r\r\r\n5.ESMC：于2014年左右与科陆合作，科陆投资建厂并控股90%，之前没有订单，今年据内线告知其从South Delta电力公司获取了10万台预付费电表订单；\r\r\n6.Gamma International Egypt：原与ADD合作，现暂未确定合作伙伴。\r\r\r\n注：竞争对手具体情况请查收附件：埃及市场竞争对手分析', '{35B8C4AA5E4F40FC88B2396D2DD62C92C8C3CDC70C5243B796247CC1ED7EC56E}_埃及市场竞争对手分析.pdf', '优势：\r\r\n1.本地开发代理客户关系较好，经济实力较强，愿意采购工厂设备；\r\r\n2.我方通过代理与EEHC高层建立了联系，通过业务自行发展了中层客户关系：EEHC表计测试委员会三把手，表计测试工程师；\r\r\n3.埃及市场10年的3000万-4000万表计采购计划从去年刚刚开始（其中预付费电表为主流），市场需求较为旺盛；同时仅有较少数量的表计厂商打入当地市场，竞争压力相对较小；\r\r\n4.鉴于埃及市场优越地理位置，在埃及建厂便于拓展周边市场电表业务。\r\r\n劣势：\r\r\n1.我方产品暂未通过EEHC测试；\r\r\n2.本地现有六个玩家实力较为强劲。\r\r\n3.暂无在本地建厂\r\r\n\r\r\n注：详细情况请见埃及市场竞争SWOT分析', '{35B8C4AA5E4F40FC88B2396D2DD62C92B79221563C224206B274FD7CD6B16366}_埃及市场竞争SWOT分析.docx', '目前埃及市场预付费电表需求量较大，智能电表在未来三年内会迎来井喷，如能基于一个预付费电表招标项目打开埃及市场，完成本地建厂，则对于后续埃及市场乃至埃及周边市场的开拓都有重要的意义。\r\r\r\n现阶段希望公司协助解析预付费IC卡表（读卡器，卡，电表，系统）的技术规格，并针对建厂报价提供支持，后续业务在本地建厂方面取得突破后会向公司申请样机，完成本地市场准入工作。', '针对该项目我方有以下几点优势：\r\r\n1.代理在本地的客户关系及经济实力较好，有采购工厂设备意愿，便于推进本地建厂；\r\r\n2.同时代理在EEHC及电力公司的客户关系以及业务自行发展的内线可为我方竞标保驾护航；\r\r\n只要我方基于此项目完成本地建厂，完成EEHC的表计准入测试并能获取电表订单，那么该市场的未来大有可期。\r\r\n此项目属于市场开拓战略性项目，但因项目信息暂不完整，因此业务自行评级四星。', '赵政洁2019-05-30 13:37:53', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('304', '{D3803758-6984-49CE-A240-A09C2840150C}', '61', 'INHE-0431', '2019-05-30 20:53:04', '0000-00-00 00:00:00', '2019-06-03 09:39:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019053001/TLS', '', 'RFP/ICB/CBS/IT/001', '2019年6月21日', '供应预付费售电系统（PROVISION OF PRE-PAID AND POST-PAID VENDING SOLUTION）', '付款条件：交货后见Invoice付款（The procedures to be followed in applying for certification and making payments shall be as follows:\r\r\na) Payment shall be made in the currencies specified in the Price schedules.\r\r\nb) Requests for payment shall be made in writing accompanied by an invoice describing, as appropriate, the goods delivered and services performed.\r\r\nc) Invoices shall show a description of goods and/or services, quantities, unit prices and total amounts.\r\r\nd) Documentation, including packing lists,', '', '技术占比70%，商务占比30%。具体如下：\r\nThe evaluation will be based on technical and financial criteria. The weighting of technical proposal will be 70% and the financial proposal 30%.\r\r\nThe following items will make up the technical evaluation:\r\r\n1. Compliance to specifications – Prerequisite and mandatory\r\r\n2. Functional Requirements 30%\r\r\n3. Non Functional requirements 10%\r\r\n3. Assessed Lifecycle costs 05%\r\r\n40 Option B. Section III. Bid Data Sheet\r\r\n4. Risk rating 10%\r\r\n5. Rating of demonstration 25%\r\r\n6. R', '', '一家中标', '', '投标保函：报价2%(The amount of Bid Security shall be 2% of the Bid Value)\r\r\n履约保函：合同金额10%(Amount of performance security: Ten percent (10%) of the contract price.)', '', '1.至少三年系统提供经验\r\n2.至少三家用户证明', '', 'a. Sound financial position.\r\r\r\n4RFP-Prepayment and Time of Use Vending System\r\r\r\nb. Experience in the design, supply, installation, commissioning and maintenance of Time of Use and Prepayment Vending systems in a utility environment.\r\r\r\nc. Demonstrated support capability.\r\r\r\nd. Proven experience in the installation and application for all types of equipment and software to be imported to Uganda for the Project,\r\r\r\ne. Verifiable reference sites.\r\r\nf.技术应答表', '', '银河投标', '', 'UMEME是私营企业。政府对招标有一定的话语权，但是不大', '', '付款条件：交货后见Invoice付款（The procedures to be followed in applying for certification and making payments shall be as follows:\r\na) Payment shall be made in the currencies specified in the Price schedules.\r\nb) Requests for payment shall be made in writing accompanied by an invoice describing, as appropriate, the goods delivered and services performed.\r\nc) Invoices shall show a description of goods and/or services, quantities, unit prices and total amounts.\r\nd) Documentation, including packing lists, ins', '', 'UMEME是乌干达配电市场占比超过97%的电力公司。是乌干达证券交易所和内罗毕证券交易所两地上市的公司。截止至2018年12月，UMEME的公司总资产约为6.7亿美金。2018年税后收益为3600万美金。							\r\r\n', '', '合作伙伴与董事会主席公关很好。与基层IT经理关系较好。', '', '一线业务与所有相关的人员都有一定的接触。重点接触的是IT经理和采购以及董事会', '', '主要对手为海兴（已经有一个LPU的系统在使用中）和Conlog(现在系统供应商）。但是电力公司对于两家都不是特别满意，所以才有此次招标。其余参与人员有:INDRA,CHINT,VORTEX等', '', '优势:TLU项目和UNW项目客户对于我们的电表整体是较为满意的。一线客户关系也都是业务自已处理有一定的控场能力。\r\n劣势：UNW暂未供货，且没有系统在电力公司使用中', '', '1.良好的产品方案，特别是与海兴和CONLOG相对比的不可替代的竞争优势', '项目潜力很大，且对于电表业务，甚至把控整个电力公司的电表相关业务都有很大的促进作用，建议4星立项。', '刘佩2019-05-30 21:27:27', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('305', '{6B6FB1DE-6698-4DBB-AD30-88E065D2CED2}', '61', 'INHE-0593', '2019-05-31 06:25:29', '0000-00-00 00:00:00', '2019-06-03 09:34:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2019053101/CMB', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '同意立项', '胡蝶2019-05-31 06:35:52', '01', '★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('306', '{BCFE3D04-AF37-4737-894B-796E088FF699}', '61', 'INHE-0381', '2019-05-31 17:51:55', '0000-00-00 00:00:00', '2019-06-19 18:25:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019053103/MTM', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 电表功能需要满足。需要需要制作电表样机和软件演示。下单前客户会来深圳参观。\r\r\r\n2. 电表价格需要合理。', '1.据韩国公司SIE已经拿到项目，无须再经过招投标。主要想找厂家进行OEM供货。 2.SIE此前已给缅甸电力公司供货，此前与一家浙江厂家合作，但后来因回扣问题，双方合作关系取消。 3.SIE通过一家香港公司找国内厂家。目前来说，是个项目机会，但是不排除，SIE通过香港公司在找多家厂家报价供货。', '张柳芳2019-06-03 14:44:43', '03', '★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('307', '{60A755E7-A977-493E-93E3-4C6E39FA8740}', '61', 'INHE-0840', '2019-06-05 04:07:50', '0000-00-00 00:00:00', '2019-06-12 09:48:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019060501/EER', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '冯敏杰2019-06-06 16:05:56', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('308', '{65132C49-B18F-4FEE-BD5D-E7EC1E57E7DF}', '61', 'INHE-0500', '2019-06-05 05:44:48', '0000-00-00 00:00:00', '2019-06-06 08:46:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2019060503/COC', '', 'TENDER NO: 368G/2018/19', '2019年7月1日当地时间10AM', 'TENDER NO: 368G/2018/19DESCRIPTION: SUPPLY AND DELIVERY OF ELECTRICITY METERSCONTRACT PERIOD: TWO YEARS FROM DATE OF COMMENCEMENT关于智能LPU电表2年框架性合同招标', '价格条款：DDP市政公司仓库 不含VAT。银河与NYC之间FOB或CIF成交；付款主体：City of Cape Town Metropolitan Municipality；付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后30天内供应商提供付款发票，市政在收到付款证明后30天内支付。银河与NYC结算方式待协商确定。交期、质保：发货后18个月质保，正式PO下达后不晚于12周内交付。						\r\r\r\r\n', '{65132C49B18F4FEEBD5DE7EC1E57E7DF8442F4C2B3234363A3D51C033076BD50}_City of Capetown Tender Docs.pdf', '第一阶段：技术资料评审；第二阶段：商务资料评审；第三阶段：BEEEE资格和其他偏好资质评审；第四阶段：样机测试						\r\n', '', '未明确和限制中标厂商数量					\r\r\n', '', '无需开立投标保函，需要开立履约保函						\r\n', '', '公司年限：无明确要求；\r\n公司财务数据：最近三年审计财务报告；\r\n供货记录：无明确要求；\r\n资质证书：需要提交第三方形式测试报告和寿命测试报告。', '', '1.需要商务组协助投标资料的制作（除报价外）；2.需要客服协助技术解析和样机规格输出；3.需要研发和实验室配合部分样机制作。						\r\r\r\n', '', '银河授权NYC投标。', 'N/A', '市政公司组织内部评标委员会（2个来自电力部门，1个来自采购，1个来自财务部门），评标委员会通过预中标名单，最终由Municipality CFO签字通过。此市政公司技术部门负责人的作用非常大，由其负责做样机测试和技术评审，并最终推荐中标名单。\r\r\n						\r\r\n', '', '交货后由电力公司项目负责工程师验收，发布验收合格证后30天内供应商提供付款发票，市政在收到付款证明后30天内支付\r\n', '', '白人管理，财务状况良好，待业务提供2018年度市政公司财报数据。', '', '1.代理NYC BBBEE资质占最终评标10分偏好优势；                          2.本地工厂满足50%以上的本地生产要求；\r\r\r\r\r\r\n\r3.NYC管理经营目标明确，策略清晰且执行力相对效率较高，和银河的发展战略和市政竞争策略相符。\r\r\r\n', '', '技术部门暂无客户关系，需要拓展；市政公司对NYC和银河的公司和产品熟悉程度较低。						\r\r\r\n', '', 'LPU电表类主要供应商：兰吉尔、Itron和Elster，直接投标无合作代理，产品技术在市政公司内部影响力很深，在市政公司供货多年技术性垄断影响力大。\r\r\n						\r\r\n', '', '1.NYC本地工厂和BBBEE资质满足基本门槛和相对优势条件；\r\n2.NYC和银河已在西开普省STE市政供货智能电表，可以利用STE市政的供货案例说服和扩大市政公司对NYC和银河产品的信任度；\r\n3.加快和NYC一起拜访此市政公司做技术层面交流和宣讲，提升市政公司对银河和NYC公司和产品方案的认知度，拓展技术层面的客户关系；\r\n4.寻求本地潜在合作伙伴如Voltex、Ontec等合作机会，借助第三方代理的实力拓展该市政项目。', '', '1.尽快完成技术解析和样机准备，在技术层面尽可能做到满足标书要求；\r\n2.推动和NYC对市政公司的技术拜访和熟悉，加深技术层面对银河产品的认识；\r\n3.推动本地第三方合作代理，借助第三方合作代理的资源开拓该市政业务。', '8大大都市市政公司中用户数量最多的潜在客户，市政公司信誉度、产品价格和付款条件较好，请公司支持。', '李忠鹏2019-06-05 06:22:39', '02', '★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('309', '{6CA8705A-08B9-46B4-925B-664A48BC1012}', '60', 'INHE-0680', '2019-06-06 21:23:02', '0000-00-00 00:00:00', '2019-07-02 08:56:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2019060602/EOS', '', '8608272', '10:00 a.m, 28.07.2019(当地时间 GMT+6)', 'Oshelectro Rehabilitation Project and Vostokelectro Rehabilitation Project', '1. DAP，包含运输费，装卸费和保险费；不包含关税和其他税费，不包含增值税\r\r\r\r\n（增值税应由被授予的供应商支付，并应在ECEPP价格表和ECEPP投标表格中单独填写。）\r\r增值税应由被授予的供应商支付，并应在ECEPP价格表和ECEPP投标表格中单独填写）\r\r\r\r\n\r\r\r\r\n2. 供应商承担所有的税费，印花税，证书费等。\r\r\r\n\r\r\r\r\n3.调价：如果招标方在投标有效期过去28天还未发出中标函，合同价格应调整为：从原来的投标有效期的截止日期和发出中标函的日期按比例和计算的基础上每年提高外国成本的1.73%,每年为当地的成本增加7%。评标不考虑上述因素，以投标价格为准。英文如右所示。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n4.折扣。Letter of Tender （d）那里需要填写提供的折扣及产生折扣的方法。（中标最低价为总价+折扣，见评标规则）\r\r\r\n', '{6CA8705A08B946B4925B664A48BC10128442F4C2B3234363A3D51C033076BD50}_表1：EOS项目投标信息归纳表.xlsx', '1）价格最低，在没有显著的技术偏差，投标资质偏差的情况下。\r\r\n2）合同数量增减幅度为15%.', '', '2家采购主体:\r\r\n奥什电力:lot1 - lot2\r\r\n东方电力：lot3 - lot4', '', '1.金额\r\r\nOshelectro:               Vostokelectro:\r\r\nLOT 1: 34500欧元           LOT 3: 58000欧元\r\r\nLOT 2： 6000 欧元          LOT 4： 8500欧元\r\r\n2. 方式及有效期\r\r\n直开，有文本；有效期：投标有效期+28天【The tender security shall be valid for 28 days beyond the original validity period of the Tender, or beyond any period of extension if requested under ITT 18.2 】\r\r\n3. 关于扫描件和正本\r\r\n投标保函须有银行的抬头和签名；\r\r\n正本需在截标日3天前寄达电力公司；\r\r\n扫描件作为电子投标一部分上传，并且邮寄正本的回执的扫描件也要上传（包含寄件的时间和日期，以及正确的电力公司的地址信息）。\r\n\r\r\n\r\n\r\n\r\n1.收到中标函28天内开具履约保函，金额为合同总金额的5%；货币为欧元或买方接受的其他可自由转换', '', '1.过去三年没有未履行合同的历史，投标人和联合体成员不得有一致的诉讼或仲裁历史；\r\n2.所有未决诉讼案的总额不得超过招标人净资产的25%。\r\n3.历史财务表现：过去三年的资产负债表\r\n4.过去3年年均营业额：\r\n   Lot1 385万欧元   Lot2 171万欧元   Lot3 650万欧元  Lot4 246万欧元\r\n5.财务资源：\r\n  现金流要求 Lot1 45万欧元  Lot2 7.2万欧元  Lot3 72.5万欧元  Lot4 10.5万欧元\r\n6.过去5年至少执行过3个与招标产品相类似的合同，每一个的合同金额至少是：\r\n   Lot 1 93.5万欧元  Lot 2 15.5万欧元  Lot3 157.5万欧元  Lot 4 22.5万欧元\r\n7. 10年生产经验（Experience in the production of metering devices for at   least 10 years）Annex 11 P303\r\n8. A、电表&集中器&表箱服务寿命/断路器服务寿命/LCD亮度显示寿命不少于20年 （average service life: ', '', '1.过去三年没有未履行合同的历史，投标人和联合体成员不得有一致的诉讼或仲裁历史；\r\r\n\r\r\n2.所有未决诉讼案的总额不得超过招标人净资产的25%。\r\r\n\r\r\n3. 10年生产经验（Experience in the production of metering devices for at   least 10 years）Annex 11 P303\r\r\n\r\r\n4. A、电表&集中器&表箱服务寿命/断路器服务寿命/LCD亮度显示寿命不少于20年 （average service life: not less than 20 years.Brightness for at least?20years. Mandatory）\r\r\n   B、CT的服务寿命为不少于25年。\r\r\n\r\r\n5.投标文件需要同时提供英语版和俄语版。\r\n\r\n6.电子投标，无需纸质版。\r\n7.投标参与人需注册ECEPP,并通过ECEPP上传投标文件。', '', '银河投标，代理商根据银河需要其协助的工作，具体项目具体付款', '', '', '', '\r\r\n1. 付款（欧元结算）\r\r\nA、第一批货\r\r\n（1）预付款：合同签订后三十(30)天内，并且以买方可接受的形式提交索赔和银行保函后支付合同金额的百分之十，直至货物交付；\r\r\n\r\r\n（2）装运时:卖方提交相关海运单据后，买方以卖方为受益人，在其所在国的银行开立以卖方为受益人的不可撤销的保兑信用证，支付所装运货物合同价格的80%\r\r\n\r\r\n（3）验收:收到货物后，买方应在收到货物后三十(30)天内支付合同金额的百分之十，并出具相应的验收证书。\r\r\n\r\r\nB、第二批货\r\r\n（1）装运时:卖方提交相关海运单据后，买方以卖方为受益人，在其所在国的银行开立以卖方为受益人的不可撤销的保兑信用证，支付所装运货物合同价格的80%\r\r\n\r\r\n（2）验收:收到货物后，买方应在收到货物后三十(30)天内支付合同金额的百分之十，并出具相应的验收证书。\r\r\n\r\r\n2. 账户\r\r\n供应商应指定最多3(3)个账户，并在收到中标函后28天内通知买方。买方应仅通过指定账户向供应商支付款项。\r\r\n\r\r\n3. 延期付款\r\r\n买方应向供应商支付利息的付款延迟期为60天。利息为0.1%。\r\r\n', '', '1）据电力公司透露，因为是贷款项目，可以100%免除增值税，50%免除关税。', '', '当前代理实力偏弱，选择某些工作需要代理在当地协助的一起合作，按具体工作结算费用，比如代理协助办理电表当地认证。', '', '与奥什电力高层关系不错，在价格接近的情况下，奥什电力会偏向选择银河。\r\r\r\n\r\r\r\n\r与东方电力总经理认识，一起吃过饭，对方会考虑支持银河。\r\r\n', '', '三星，海兴，华立', '', '1.查找竞争对手过去三年是否有未履行合同的历史；\r\r\r\r\n\r\r\r\r\n2.查找竞争对手的未决诉讼案；\r\r\n\r\r\r\n\r3.查找竞争对手的资质不符合点；\r\r\r\n\r\r\r\n\r4.查找竞争对手技术不符合点；\r\r\n\r\r\n', '', '价格接近最低，按要求提交所有投标资料和提交样机并通过测试。', '之前吉尔吉斯市场最大的问题是采购预算低并且中标价格低，收款风险大，没保障。本次招标没有列出采购预算，价格没有限制；资金来自欧洲复兴银行贷款，收款有保障。', '陈嘉豪2019-06-06 22:06:45', '04', '★★★★★', null);
INSERT INTO `crs_tabledata1533` VALUES ('310', '{5B85E239-4242-4685-BF7C-DD44970B78CD}', '61', 'INHE-0593', '2019-06-12 14:25:44', '0000-00-00 00:00:00', '2019-06-27 10:15:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2019061201/SBC', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.从试点谈判进程及具体的协议内容看来，该试点项目来之不易；\r\r\n2.试点协议涉及到主服务器，备份服务器及smart agent供货安装调试；尽管目前我们没有拿到代理给电力公司的报价单，但可以结合以往经验估计从金额比率上看主备服务器供货占订单金额较大比率（参考之前BFN03代理主备服务器供货额约为48万欧元），代理一般会找其欧洲供货商采购，Smart agent占比较小比率（我司给代理的报价为10万欧元）；\r\r\n3.贝宁电力公司信誉很差，贪污腐败严重。去年代理表示贝宁电力公司差他很多钱不付；今年我们前往贝宁，碰上代理找贝宁电力公司催债，约2万人民币的货款，贝宁电力公司也迟迟不付。这一点需要知悉。\r\r\n4.建议立项，代理与电力公司结算，银河与代理结算。试点努力在今年年底完成试点项目，明年年初验收收款；\r\r\n5.建议试点时银河提供1名软件工程师及1名业务在贝宁现场1-2个月的服务支持，与代理协商需要代理承担二人食宿（或至少是住宿）；\r\r\n\r\r\n\r\r\n\r\r\n\r\r\n', '胡蝶2019-06-25 17:41:55', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('311', '{4AD0B269-F547-404D-866B-AA3CE59977B9}', '66', 'JXINHE-2559', '2019-06-14 11:41:54', '0000-00-00 00:00:00', '2019-06-17 09:28:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019061401/SRP', '', 'DD2/P&D/ICB/2014/055/D', '2019年7月10日', 'Supply & Delivery of CT Operated Programmable Meters 3Phase 4Wire with remote reading facilities/带远程功能的CT接入式三相四线供货和运输', '见海运提单支付合同金额的85%，交货后CEB总经理或授权代表签发证明后支付剩余货款。', '{4AD0B269F547404D866BAA3CE59977B98442F4C2B3234363A3D51C033076BD50}_SRP项目标书-技术版.pdf', '技术满足的情况下，最低价中标。', '', '一家中标。', '', '400万斯里兰卡卢比，约合2.26万美元，保函到期日2019年12月11日', '', '十年从业经验，产品型式测试报告。', '', '基本的投标资料，7月1日准备妥当。', '', '银河投标，授权代理负责当地投标工作如购买标书，开具保函等。', '非联合投标。', '国际性招标，较为公平。', '', '见海运提单支付合同金额的85%，交货后CEB总经理或授权代表签发证明后支付剩余货款。', '', '业主为国家电力公司--锡兰电力公司，财务能力待调查。', '', '代理公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。2017-2018年度年营业额为1,298,228,524卢比，约为735.9万美元；2016-2017年度营业额为1,151,017,236卢比，约为652.5万美元。详见附件中的财务报表。', '', '待与客户建立关系。', '', '海兴，微星，三星等。', '', '凭借完善的技术方案，有竞争力的报价，督促并和代理共同运作。', '', '有竞争力的报价', '斯里兰卡市场由于有十年从业经验的要求，在没有合适代理的协助下并没有贸然介入。我们将于今年12月份满足该要求，出项目出结果的时间接近，当前合作的代理公司规模良好，凭借他与业主的关系，在代理的努力下，凭借完善的技术方案，有竞争力的报价，通过本项目进入该国市场。', '淦永妍2019-06-14 14:00:49', '', '', null);
INSERT INTO `crs_tabledata1533` VALUES ('312', '{CBBFC80C-C133-45FA-8E34-80AAD685F9F2}', '61', 'INHE-0843', '2019-06-17 12:52:55', '0000-00-00 00:00:00', '2019-06-24 15:40:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019061701/EDA\r\n', '', '暂无', '暂无', '暂无', '代理目前承诺会按照30%-50%预付款，尾款LC支付。细节还需与代理确认。\r\n', '', '样机通过测试之后，价格优先，技术次之\r\n', '', '一家中标；但代理表示会运作电力公司进行分标\r\n', '', '代理负责开立保函\r\n', '', '目前是标书前期运作阶段，具体要求待发标后确认\r\n', '', '目前是标书前期运作阶段，具体要求待发标后确认\r\n', '', '代理投标', '', '电力局直接决定中标结果\r\n', '', '目前是标书前期运作阶段，具体要求待发标后确认\r\n', '', '代理与ElecGalapagos关系良好，内线靠谱，代理与该电力公司已有多个合作项目，支付情况良好。\r\n', '', '代理在厄瓜多尔电力行业经营了15年，与电力局有密切的关系，内线靠谱已合作多年，帮助代理取得了多个采购项目中标。针对此次合作项目，代理已提供给我们多个竞争对手的重要内部资料。\r\n', '', '暂未与电力公司建立客情\r\n', '', '厄瓜多尔电表市场主要竞争对手为海兴。两相表项目海兴中标价为17至24美金，价格偏低，但质量不佳，在其他电力局项目执行过程中曾出现问题。海兴产品具体信息请见附件。本次AMI项目海兴也会参加竞投；同时南京微星电力也已提交方案及报价。\r\r\n', '', 'Strengths:\r\r\r\r\r\n*代理合作意愿强烈，在电力公司内部有合作多年且十分可靠的内线，可以帮助银河运作项目\r\r\r\r\r\n*代理对竞投标项目运作有丰富经验，是十几年来都是电力公司的稳定供应商，中标过多个项目\r\r\r\r\r\n\r\r\r\r\r\nWeaknesses: \r\r\r\r\r\n*我司目前没有两相三线表产品，需要研发做样机\r\r\r\r\r\n*我司目前ANSI单相三线RF通讯圆表还未通过产品测试\r\n*价格\r\r\r\r\r\n*当前银河暂时没有直接与电力公司建立客情\r\r\r\r\r\n\r\r\r\r\r\nOpportunities：\r\r\r\r\r\n* 本次招标是厄瓜多尔国内首个AMI项目，可以由此进军该国智能电表市场，占领先期优势\r\r\r\r\r\n* 如中标，本项目的两相表还可以在美洲其他国家销售\r\r\r\r\r\n* 该市场的贪污腐败严重，具有运作机会和空间\r\r\r\r\r\n\r\r\r\r\r\nThreats：\r\r\r\r\r\n* 代理主营业务是中高压输变电设备和材料，电表项目经验不足，是否能有效运作和控场有待考察；我司需做多手准备\r\r\r\r\r\n* 标书原则上要求一家中标，代理表示会根据银河能够竞投的产品去与电力局协商分标，但无十足把握能说服；代理和电力局的关系有待考验\r\r\r\r\r\n* 当前没有现成两相表产品\r\r\r\r\r\n* 一线无业务人员控场\r\r\r\r\r\n\r\r\r\r\r\n策略：\r\r\r\r\r\n1. 考验代理能力：根据银河能够参投的产品，让他说服电力局分标\r\r\r\r\r\n2. 内部技术解析后，以AMI系统为优先产品，提供银河能够参投的最优方案\r\r\r\r\r\n3. 样机：手板样机\r\r\r\r\r\n4. 样机和系统测试阶段运作，淘汰其他竞争对手\r\r\r\r\r\n5. 业务前往一线控场，检查代理实力同时发展其他代理，直接与电力局建立客情\r\r\r\r\r\n', '', '技术支持对产品规格进行解析；研发人员确认新产品研发的可能性\r\n', '此项目将会是厄瓜多尔国内第一个AMI项目（目前厄瓜多尔只有抄表系统，全国无AMI），如中标，可通过此项目进军厄瓜多尔智能电表市场，占领先期优势，对我们来说是十分难得的有利机会。代理在厄瓜多尔电力行业经营了15年，有丰富的竞投标经验，曾中标多个电力局设备/材料采购项目，在电力局有合作多年的靠谱的内线，代理已经把技术参数、竞争对手内部资料都发给了我们。现在厄瓜多尔正在向智能电表过渡，今后该国将以两相表为基础大规模部署AMI方案，每年招标数量20至30万台，一般三年左右会有全国性的大型招标数量可达上百万，市场前景和未来订单量可观。\r\r\n', '刘畑杏2019-06-17 14:43:56', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('313', '{A97D27B5-CDF2-4E72-8970-9D05625D4CA6}', '60', 'INHE-0868', '2019-06-21 13:26:04', '0000-00-00 00:00:00', '2019-06-21 13:26:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062103/SRA', '', 'DD2/P&D/ICB/2019/009/D', '2019.07.10', 'Supply & Delivery of CT Operated Programmable Meters 3Phase 4Wire with remote reading facilities   供应及运送CT三相四线电能表（带通讯模块）', '付款方：CEB                                                     付款条件：85%LC见海运提单，15%客户验收后付款。（LC非保兑，若需保兑相关费用均由受益人承担）                                          交期：LC后2个月                                                  质保：60 months（after original FOB dispatch date)，前两年免费更换，两年后质保期内免费维修或更换', '', '价格最低。本地优惠，即符合要求本地生产工厂有20%优惠。外商出口价格按（CIF+20%），当地企业，非当地生产的进口商品按（EXW+20%）参与比价\r\n', '', '一家中标\r\n', '', '投标保函：LKR400,000 到2019年12月11日，Sri Lanka 银行开立或保兑。代理可开保函，需签授权并有授权人和两名公证人签字。    履约保函：10%合同额，必须供货方开，Sri Lanka银行开立或保兑，最终发货日期后六十天有效\r\n', '', 'ISO9001：2008或最新的质量保证认证，符合ISO/IEC：17025：2005的实验室测试并提交测试报告。投标文件中也需要。 10年生产经验证明（代理表示只差几个月，如果产品满足要求也可以中标）\r\n', '', 'PCA表格，authorization letter （授权代理购以银河名义买标书） 2019.6.27                                                       Notarized power of attorney （若需授权代理已银河名义开立投标保函）2019.6.27                        其他标书要求资料 2019.7.1', '', '联合投标', '银河主投，可通过代理购买标书，开立投标保函节约操作时间，易于在当地处理投标事务，信息收集。              银河负责准备投标资料，样机及产品的生产和供应；代理负责当地的投标工作包括当地PCA注册,购买标书，开立投标保函,递交投标文件等\r\r\n', 'CEB是当地最大电力公司，电表的招投标信息主要由其发布\r\n', '', '直接开具信用证付款\r\n', '', '斯里兰卡最大的国家电力公司，管理整个国家的发电，输电，配电业务。是当地电表主要招标单位。2015年报如附件\r\n', '{A97D27B5CDF24E7289709D05625D4CA6108D268797C74834B1DDE2FC1083AA37}_1531992515CEB-Annual_Report_2015_(English).pdf', '有23年较丰富的投标经验，与招标方已有多次成功合作。代理公司财报见附件', '{A97D27B5CDF24E7289709D05625D4CA6D18C251E4D454BA8A05CF92EE9AFCB77}_Rotax Pvt Ltd财务报表.pdf', '初次合作', '', '海兴在当地有较多业务', '', '之前有对当地项目进行分析，产品大致符合需求，但没有实际项目进展。现在资质基本符合，可通过这次机会进入当地市场。', '', '投标资料和样机及时提供                                                                             PC端模块及配件，PC软件等可能需外购产品的供应支持                                                      产品与客户要求的匹配\r\n', '', '庄钦2019-06-21 13:44:20', '', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('314', '{6DD2F281-AD83-481A-A11E-4391E0CB1331}', '60', 'INHE-0535', '2019-06-21 09:11:28', '0000-00-00 00:00:00', '2019-06-24 09:37:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062104/LVT', 'LVT', 'ADB-SPDEIP -Tranche1-AMI Project-LESCO Package 1.2', '2019-07-18#FE54` 11:00 AM 巴基斯坦标准时', 'Design, supply, installation, commissioning of an Advanced Metering Infrastructure project in Second and Fifth Circle, customer information system, and billing system for Lahore Electric Supply Company Limited (LESCO)LESCO地区第二和第五区域的AMI，用户信息系统，账单系统的设计，供应，安装，调试。', '价格条款：CIP Lahore；\r\r\r\r\r\n付款主体：LESCO电力公司(ADB融资)；\r\r\r\r\r\n付款条款：1）预付款：收到预付款保函后，支付总合同额15%的预付款；\r\r\r\r\n2）硬件部分：\r\r\r\r\n交货后支付硬件部分合同额的40%；\r\r\r\r\n安装后支付硬件部分合同额的20%；\r\r\r\r\n验收后支付硬件部分合同额的15%；\r\r\r\r\n验收后连续满意运行1年后支付余下10%；\r\r\r\r\n3）软件部分：\r\r\r\r\n交货后支付软件部分合同额的30%；\r\r\r\n安装后支付软件部分合同额的30%；\r\r\r\n验收后支付软件部分合同额的15%；\r\r\r\n验收后连续满意运行1年后支付余下10%；\r\r\r\n4）培训：\r\r\r\n培训计划开始时支付培训服务费的35%；\r\r\r\n培训服务结束支付40%；\r\r\r\n培训课程结束验收证明后支付10%；\r\r\n\r\r\n交期：36个月。迟交按每天0.1%罚款，上限100天。\r\r\n\r\r\n质保：3-5年。质保期结束后还有后质保期：表计和计量设备10年，通讯设备和系统5年，表箱3年。\r\r\n\r\r\n总包商直接投标，与银河付款方式在谈。', '{6DD2F281AD83481AA11E4391E0CB13318442F4C2B3234363A3D51C033076BD50}_payment terms.pdf', '技术标通过后，再评入选厂家的价格标；\r\r\n所有报价币种统一按截标当日的巴基斯坦国家银行汇率按巴基斯坦卢比评标，最低价中标；\r\r\n', '', '发布中标通知后90天内，及签订合同前，中标人需进行POC。 POC结束后5天内，通过电力公司验收且签发POC验收证明后，才会签订合同。\r\r\n', '', '买方开立。投标保函$3million,有效期180天+93天以上；\r\n履约保函10%合同额，不会随项目完成进度递减，且在项目结束2年后释放。\r\n预付款保函：与预付款等额，可根据付款里程碑递减。', '', '主投/联合体去年累计营业额$100million,其中至少一个合同额为$40million以上；$18million现金流；相关产品过去2年累计年产能100万只；过去5年内参加过至少一个类似项目；至少在3个国家实施过20万以上计量点的AMI项目；至少在一个亚洲国家供过35万以上电表；1个账单系统项目经验；至少在3个不同电力公司实施过100万以上用户的账单系统，CIS系统与AMI系统兼容的项目', '{6DD2F281AD83481AA11E4391E0CB133103404677E4D44E9EB56B3D512B2AF9CC}_3. Section III EQC.pdf', '2019.07.10之前完成投标资料。主要负责银河作为表计相关产品供应商的资质文件', '', '代理投标，银河直供', '', '', '', '业主直接付款给承包方/中标方', '', 'ADB贷款，用于支付承包方货款。', '', '电力公司关系良好，项目投标经验丰富，熟悉巴基斯坦市场', '', '尚未与业主（LESCO）建立直接关系', '', '了解中', '', '银河主要负责表计部分供货，且将是AMT的唯一表计供货商。总包商负责项目执行，安装，软件，服务等。\r\n需要尽快协商与总包之间的付款条款，签订合作协议，保证银河作为表计产品唯一供应商的地位。', '', '前期与总包的合作条款（付款方式，订单数量，报价）；后期产品支持；', '', '左亚楠2019-06-21 18:40:13', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('315', '{2908446D-8791-4455-AF50-7B2086CB66B4}', '61', 'INHE-0853', '2019-07-18 11:00:00', '0000-00-00 00:00:00', '2020-06-18 12:15:43', 'unchecked', 'n', 'n', '', '1', 'lxdj20190718/DFN', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '目前我司正在推进DEN路灯系统试点项目，若能一并实施DFN售电系统试点项目，可减少试点项目的人力资源投入节约时间和成本。', '胡亚婵2019-07-18 15:51:53', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('316', '{0D975BA3-41B6-41F5-A581-BDDE03BF8509}', '60', 'INHE-0781', '2019-06-25 03:00:27', '0000-00-00 00:00:00', '2019-06-27 17:35:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062502/PDD', '', '328209', '2019.07.04', 'Procurement of 11kV Metering Unit CT Ratio 60/5 100/5 and 150/5采购11kV计量单位CT 比例60/5 100/5和150/5', '使用当地币结算，无预付款，到货并验收合格后支付95%，终验合格后支付5%尾款。\r\n由代理直接投标，银河作为供货方。代理中标后开信用证给银河，银河收到信用证后生产，发货后交单收全部货款。', '{0D975BA341B641F5A581BDDE03BF85098442F4C2B3234363A3D51C033076BD50}_Payment term.jpg', '先审核资质，通过者做技术演示和应答，之后做财务评审和价格对比，低价者中标。', '{0D975BA341B641F5A581BDDE03BF8509074E749A304748709C51373D9D483750}_Evaluation process.jpg', '一个LOT，一家中标', '', '1.投标保函金额850,000BDT,有效期2019.09.01~2019.12.31；2.履约保函：10%合同金额，质保期到期+28天。', '', '（a）投标人应具有至少05（五）年的电力产品及相关服务的供应经验；\r（b\r\r\r\r\r\n）在过去5年内投标产品或类似产品的供货记录中，不多于两个合同相加的总金额应至少有250,00,000.00塔卡；（c）货物的最低供\r\r\r\n应和/或生产能力是：\r（i）11kv室内型单相电流互感器：2000个/年；\r（ii）11kv室内型单相电压互感器：2000个/年；\r（iii）110 /√3V，三相，4线，3元件，5安培固态可编程电能表：600个/年。\r制造商必须提供文件证据以支持生产能力。（d）流动资产不少于3000万塔卡；\r\r\r\n（e）电能表，CT,PT需要提供国际著名实验室出具的形式测试报告（KEMA,CESI,CPRI,MID，SGS等）', '{0D975BA341B641F5A581BDDE03BF850903404677E4D44E9EB56B3D512B2AF9CC}_Criteria.rar', '电子标，所有文件需提供电子档，所需文件见附件。', '{0D975BA341B641F5A581BDDE03BF8509C675BD0CC93442C09B990884D4324504}_Criteria 3.jpg', '代理投标，银河仅供货', '', '此项目资金来源于电力公司自有资金，同时项目不大，主要是电力公司自行决策。\r\r\n', '', '见付款条款', '', '此项目主要来源于电力公司自有资金，近年孟加拉国政局稳定，经济持续快速增长，电力需求稳步提升，电力公司资金来源有保障。\r\r\n', '', '代理在DPDC有着良好的客户关系，过往在DPDC也有成功案例，相关各个环节都比较熟悉。', '', '银河在业主那已有合作项目，已具备一定的客户关系。', '', '此项目使用本地币结算，同时商务、技术要求都不高，因此主要均为当地厂家投标，我们常见的对手如海兴、思达这些厂家主要以供货方的形式出现。', '', '1.银河能提供完整的解决方案，会具有一定的成本优势；\r\r\r\n2.代理在电力公司具有良好的关系；\r\r\n3.银河需要开拓一些新业务来作为新的增长点。', '', '1.按要求准时提交相关资料（因为电子标，仅需提供标书资料电子档即可）；\r\n2.给出一个有竞争力的价格。', '尽管此项目的截标期时间已很近，但因为投标资料仅需提交电子档，现阶段不用样机，也不需要负责投标保函，所以还是具备可行性的。此项目尽管数额不大，但如果成功则能为我们LPU在孟加拉的应用开辟出一条道路，具有比较大的战略意义，因此个人建议公司予以重视，同意立项。', '李启坦2019-06-25 10:32:46', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('317', '{5D8557EA-D430-4E54-AD9C-03636B4A3102}', '66', 'JXINHE-2559', '2019-06-25 14:48:07', '0000-00-00 00:00:00', '2019-06-27 17:27:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062504/GPR', '', '503902', '7月15日', 'THREE PHASE MAX INDICATING ELECTRONIC METERS FOR CONNECTION THROUGH CURRENT TRANSFORMER TO THE LOW VOLTAGE GRID AND COMMUNICATION UNIT (MODEM). (503902) 电流互感器接入式低压电网的三相最大指示电子表和通讯模块单元', '标书为希腊文，待翻译完成后提供。', '', '标书为希腊文，待翻译完成后提供。						\r\n', '', '标书为希腊文，待翻译完成后提供。						\r\n', '', '标书为希腊文，待翻译完成后提供。						\r\n', '', '标书为希腊文，待翻译完成后提供。						\r\n', '', '7月10日', '', '代理商投标', '', '', '', '待与代理沟通', '', '待调查', '', '合作伙伴对电表行业有一定的了解，相关情况待代理反馈', '', '尚未和该电力公司建立有效联系', '', '主要竞争对手为华立，三星，威胜，EDMI，其中华立，三星和EDMI有向HEDNO供过货，活动积极。\r\n', '', '代理对电表行业有一定的了解和经验，在项目截标前完成标书和样机准备工作，凭借代理的资源和经验，共同合作争取项目。', '', '符合要求的产品和有竞争力的报价。', '在开发欧洲市场初期找到当前的代理和项目，经过前期了解，代理对电表行业和竞标流程有一定的了解，客服部正在解析项目的技术资料，预计本周内出结果。由于项目需要准备样机，现申请立项，恳请领导支持！', '淦永妍2019-06-26 15:06:31', '', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('318', '{B67B30F5-64CA-4D8D-9516-C5FF086F0EB5}', '66', 'JXINHE-2559', '2019-06-26 14:20:15', '0000-00-00 00:00:00', '2019-06-27 17:23:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062602/GPT', '', '503904', '7月22日', 'ELECTRONIC MEDIUM VOLTAGE METERS AND COMMUNICATION UNIT (MODEM)电子中压表带通讯单元', '标书为希腊文，待翻译完成后提供。', '', '标书为希腊文，待翻译完成后提供。', '', '标书为希腊文，待翻译完成后提供。\r\n', '', '标书为希腊文，待翻译完成后提供。', '', '标书为希腊文，待翻译完成后提供。', '', '7月15日', '', '代理商投标', '', '', '', '待与代理沟通', '', '待调查', '', '代理为电力公司的MDM系统提供商，对当地的电表行业有一定的了解，在电力公司有一定的人脉资源。', '', '尚未与电力公司建立有效联系', '', '华立，三星，威胜，EDMI，其中华立、三星和EDMI有当地供货经验，活动积极。', '', '代理作为电力公司的MDM系统提供商，对当地的电表行业有一定的了解，在电力公司有一定的人脉资源，凭借代理上述优势，双方共同合作争取项目。', '', '符合要求的产品和竞争力的报价', '在开发欧洲市场前期找到当前的代理，经前期了解，代理为电力公司的MDM系统供应商，对电表行业和竞标流程有一定的了解。投标的技术资料已交客服部同事解析，由于项目时间紧张，需准备样机，现申请立项，恳请领导支持。', '淦永妍2019-06-26 14:36:30', '', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('319', '{8B1F63E0-124F-4090-93F4-B7049BC85B93}', '61', 'INHE-0642', '2019-06-26 16:30:19', '0000-00-00 00:00:00', '2019-07-09 18:58:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062603/BAC', '请核实是否延标；是否有靠谱的合作方。', 'TENDER NO. 3503/19', '2019年6月19日招标，7月12日当地时间上午10点截标', 'Supply & delivery of single phase burget energy meter and wall base for single phase meter bec to gaborone and francistown warehouse （供货&交付单相电能表以及供单相电能表使用的表箱到电力公司在Gabornone和Francistwon的仓库中）', '价格条款：DDP\r\r\n交期：未明确\r\r\n违约赔偿金：未明确\r\r\n付款条件：未明确', '{8B1F63E0124F409093F4B7049BC85B938442F4C2B3234363A3D51C033076BD50}_3503-19 BEC Meter  Wall Base.docx', '1.	先评标技术和商务\r\n2.	再开价格', '', '1个LOT', '', '未明确						\r\n', '', '(a) 过去五年内执行过相关产品项目的经验：需要提供三个项目的PO的副本以及针对工程发出的发票\r\n(b)提供公司组织架构（代理提供）\r\n(c) 至少有一辆可由叉车卸货的货车(自有或租用)。(请提供蓝皮书或卡车租赁协议复印件)。与本供货和交付相关的所有设备/机械和车辆清单。（代理提供）\r\n(d) 办公空间，在商业环境中进行商业活动。(请提交租赁协议或所有权证明)。（代理提供）\r\n(e) 证明有能力在合理的短时间内从金融机构为该特定项目获得资金。(请提供现有资金证明、与第三方资助者的现有信贷安排、与融资人的协议，以及/或与金融机构的任何现有信贷安排)。（代理提供）\r\n(f) 投标人披露制造商的信函,制造商背书函，确认与投标人的关系 (本地厂商=10分，独家经销商=10分，指定代理商=10分，指定经销商=10分，指定零售商= 5分)', '', '技术资料需要客服协助评估', '', '代理投标', '', '', '', '协商中，和代理初定的付款方式为签订合同后40%T/T，发货前60%即期L/C', '', '电力公司支付能力良好，博茨瓦纳的经济较好，拖欠款项的事情较少。', '', '首次合作，对行业较为了解，和电力公司BPC有过几次项目来往。\r\r\n', '', '代理客户关系较强', '', '该项目主要竞争对手为海兴，此项目之前海兴供货的项目，单价为37美金一个，附件为海兴供货电表', '{8B1F63E0124F409093F4B7049BC85B93C8C3CDC70C5243B796247CC1ED7EC56E}_bc6a44b3-3340-4c2f-9fef-dc738be4c7da.jpg', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 推动代理去运作采购和技术内线影响评标团队成员，', '', '项目成功的关键位：推动代理控场以及价格优势。需要的支持：商务和技术支持。', '\" 该项目需要提供样机，但投标时间很短（一个月），建议尽快评估技术参数并准备相关样机，一旦供应商预审资格合格，则需要提供样机\n\"								\r\n', '潘正豪2019-06-27 02:05:41', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('320', '{F66C5262-5C2E-40A1-9045-A102A311FDC8}', '60', 'INHE-0535', '2019-06-30 21:08:47', '0000-00-00 00:00:00', '2019-07-03 09:10:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2019063001/MTC', 'MTC', '7000013028 MSETCL/CE/AC&I/IEM/T-02 /2019-20', '2019.07.08', 'Supply 500 No’s of DLMS Compliant Interface Energy Meters (5/15 mins.) & 25 Numbers of Common Meter Reading Instrument.500台符合DLMS的IEM电表（5/15分钟）和25台CMRI的供应', '价格条款：EXW.\r\r\r\n付款主体：MSETCL.\r\r\r\n付款条款：1）无预付款；\r\r\r\n          2）80%到货支付；\r\r\r\n          3）20%在成功运行6个月后支付；\r\r\r\n交期：中标通知后3个月内交付。\r\r\n质保：供应日期后7年。\r\r\n代理商对银河付款方式：L/C。\r\r\n						\r\r\n', '{F66C52625C2E40A19045A102A311FDC88442F4C2B3234363A3D51C033076BD50}_Terms of Payment.pdf', '技术标+价格标。通过技术评标的投标人，才被允许开其价格标。价格标按\r\r\r\n报价总净价比较。\r						\r\r\n', '', '通过技术标且价格最低的投标人中标。一家中标						\r\n', '', '投标保函：合同额1%，有效期为开标后8个月；\r\r\r\r\n履约保函：合同额10%，有效期为开标后180天+30天；\r\r\r\r\n代理商开立。					\r\r\n', '', '1.印度本地注册公司，GST,PAN证书，偿付能力证书等；\r\r\n2.制造商提供MAF，且有制造IEM电表(CT表)的经验，能力，制造测试生产设备，人员等；\r\r\n3.向电力公司供应至少50台IEM电表的供货记录；\r\r\n4.KEMA/NABL或ILAC认证实验室出具的型式测试报告。', '{F66C52625C2E40A19045A102A311FDC803404677E4D44E9EB56B3D512B2AF9CC}_EQR.pdf', '制造商授权，供货记录，KEMA测试报告；最迟7月5号提交。', '', '代理商投标', '', 'MSETCL自主采购，评标。', '', '业主按照合同规定的准则和条件向承包商支付履行合同规定的工程费用。所有在合同期间支付的款项仅为受款人。最后付款应在合同规定的全部工程完成和承包商履行完合同的所有责任时支付。业主应按照付款时间表在到期时逐步付款。业主应在收到承包商帐单/发票之日起45天内支付款项，条件是与发票一起提交的文件各方面均已完成。\r\r\r\n', '', '', '', 'BlueOcean在MSETCL有相关变电站监控等实施执行经验。团队投标经验丰富。有现场执行如电表安装等长期合作伙伴。电力公司内部有较好渠道。\r\r\r\n', '', '尚未与MSETCL建立直接关系。主要在与合作伙伴直接接洽。', '', '了解中。', '', '制造商授权合作伙伴投标，利用合作伙伴在MSETCL电力公司积累的经验和渠道。', '', 'CT表有一些偏差，如以下方面，后期需要技术支持：\r\r\r\n1.CT表的无功等级需要达到0.2S；\r\r\r\n2.CT表的无功电量没有针对欠压如平均RMS电压<97%及过压如平均RMS电压>103%事件分开进行存储#FE54`\r\r\r\n3.当给电表下发时间提前或者滞后命令时，12个时间组要同时提前或者滞后5分钟#FE54`\r\r\n4.CT表的时钟精度要求小于10s/month#FE54`\r\r\n5.对不同欠压情况做对应的标识如\"*\",\"Z\"#FE54`\r\n6.电流规格为1A和5A电表的脉冲常数分别为20000imp/Wh和4000imp/Wh。', '投标文件主要提供制造商授权，推荐产品画册和操作手册，KEMA测试报告及CT表供货记录。', '左亚楠2019-07-01 11:52:51', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('321', '{24693089-0394-43C3-9728-4E6610C9BF29}', '60', 'INHE-0434', '2019-07-04 18:50:57', '0000-00-00 00:00:00', '2019-07-09 09:10:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070408/CBM', '', '19/107/AD', '2019年7月13日', 'Acquisition de compteur a prepaiement', '该项目是2019年预算下的预付费电表采购项目，交期60天', '', '同CAM01。如果我们的样机测试通过的话，我们会有更多的机会赢得该项目。', '', '一家中标', '', '无', '', '无', '', '厂家授权，原产地证明，技术应答表', '', '代理商投标，同CAM01', '无', 'EDM自主决策，同CAM01', '', '代理倾向信用证', '', 'CAM01代理最终也支付了尾款提货', '', '该客户是前电力公司总经理的亲戚，19年上半年达成了CAM01订单', '', '同类型项目，暂时以代理为主', '', 'EDM一般都是给本地公司发询价函，并限制只用银河，威胜，海兴，Itron，ZHONG CHENG和HEXCELL的电表', '', '基于CAM01项目，代理以及银河双方希望在CBM项目上达成合作。代理将指导银河报价。', '', '公司给予具有竞争力的价格，CBM项目需包含代理佣金', 'EDM用本年的预算给几家当地公司发了预付费电表的询价函，推荐询价的电表厂商有银河，威胜，海兴，Itron，ZHONG CHENG和HEXCELL，价优者中标。该客户在中国广州有dialing且与电力公司总经理的关系很好，已经给中国的断路器 厂家下了很多订单。建议公司在CBM项目给予具有竞争力的价格。					\r\n', '钟云林2019-07-04 20:19:12', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('322', '{3E9D9114-F572-47D1-8C7A-96679446C4F9}', '61', 'INHE-0772', '2019-07-08 13:44:36', '0000-00-00 00:00:00', '2019-11-18 15:29:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070805/MLF', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'MLF属于试点项目，金额较小，后续试点扩大会变成类似CDN的接线系统项目。目前试点阶段涉及内容均为新增财务报表，但是财务数据敏感，对电力公司营收报告的唯一体现。当前的接口数据和售电报表被电力公司财务部分多次投诉，建议软件部认真对待客户需求。', '张子琦2019-11-14 08:42:48', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('323', '{E4A35B82-6407-4EB9-9397-B37AAC1B49CA}', '60', 'INHE-0781', '2019-07-09 02:15:30', '0000-00-00 00:00:00', '2019-07-10 15:43:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070901/BPP', '', '27.11.0000.304.19.265.19 dt. 30/06/2019', '2019.8.22', 'Supply of Single Phase & Three Phase Solid State CTS Smart Pre-payment Meter with modem under Existing unified Pre-payment System for New Connection.提供带用于在现有Unified预付费系统下进行新连接的通讯模块的单相和三相固态CTS智能预付费电表。', '电力公司对代理：无预付款；\r\r\r\r\r\r\r\r\n70%收到发货单据后支付；\r\r\r\r\r\r\r\r\r\n30%到货验收合格后30天支付。\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n代理对银河：\r\r\r\r\r\r\n代理开据100%不可撤销L/C，银河发货后提供单据收取全部货款。', '{E4A35B8264074EB99397B37AAC1B49CA8442F4C2B3234363A3D51C033076BD50}_Payment term.jpg', '先做资质审核，然后做技术演示，进行技术评标，最后开价格标，低价中标。', '', '一个LOT,一家中标', '', '投标保函由代理开给电力公司；如中标，则银河以代理为受益方，提供供货金额10%的履约保函于代理，有效期需覆盖收到到货验收合格后3年+28天。', '', '1.过去5年内仲裁次数不超过3次；\r\r\n2.至少3年以上投标产品的供货经验；\r\r\n3.在过去5年内，不超过两个合同的情况下，类似投标产品的供货金额需不少于180万美元；\r\r\n4.最小年供应量/产能不小于两倍标书需求量（10万单相表，1万三相表）；\r\r\n5.流动资产不少于供货金额的150%。\r\n6.单三相表均需提供国际权威实验室测试报告（KEMA,SABS,MID等）', '{E4A35B8264074EB99397B37AAC1B49CA03404677E4D44E9EB56B3D512B2AF9CC}_qualification criteria 1.png', '', '', '代理商投标', '', '能源部对项目有一定影响力，主要由BPDB内部高层决策。', '', '电力公司对代理商：无预付款；\r\r\r\r\r\n70%收到发货单据后支付；\r\r\r\r\r\r\n30%到货验收合格后30天支付。\r\r\r\r\r\n', '', 'BPDB预算收入下的现金外汇，支付有保证。', '', '代理在能源部及BPDB均有良好的关系，其刚刚在BPDB中了一个5.4万台GPRS表项目，此项目把握较大。', '', '银河在BPDB有着良好的供货记录，有近50万台表正在运行，有着一定的客户关系。', '', '此项目资质要求不高，竞争激励，主要还是拼价格。上一个项目由林洋供货，代理以第二低价中标，通过运作排除了最低价格科陆。', '', 'IEEL在BPDB关系深厚，我们优先还是要与他们合作才有较大机率成功。由于他们已与林洋合作成功一次，尽管相比林洋我们具有更丰富的海外经验，但此项目资质要求不高，因此说服代理的关键还是在于我们需要提供一个比林洋更有竞争力的价格。', '', '单相表需使用Johnson，Germany继电器；三相表需使用Gruner，Germany继电器，通讯模块需使用4G模块。', '此项目价格竞争将相当惨烈，但我们在BPDB已太久没有项目，需要赶紧拿到一个项目，从而重新建构与BPDB的关系。因此，建议公司同意立项。', '李启坦2019-07-09 09:04:55', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('324', '{E207D812-A909-413B-958A-4D716E0C0FB6}', '61', 'INHE-0654', '2019-07-09 09:18:17', '0000-00-00 00:00:00', '2019-07-10 15:37:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070903/ADG', '', '7000001942', '', 'Medidores integrados de Energia 综合能量计量仪表', '交期：交货后三十天之内付款（电力公司付款条件）', '', '内部私下评标', '', '技术和价格综合评估，在技术都过关的情况下，取价格最低（技术部分会有评分）', '', '代理负责开保函', '', '', '', '', '', '代理商投标', '', '', '', '', '', '电力公司的2019年上半年的财报可见附件，资质以及付款能力较好。', '{E207D812A909413B958A4D716E0C0FB6108D268797C74834B1DDE2FC1083AA37}_2019-FirstQ-EarningsRelease.pdf', '代理商与电力公司关系良好，并且有一定的技术能力。', '', '', '', '竞争对手主要是海兴，本次可能科陆也会参加。海兴的产品型号为：HXEP-12，科陆的试点产品为：CL710K22(BS安装）', '', '银河的产品技术以及服务能力已经被电力公司接受，并且通过ADD项目供货，电力公司目前认可银河，后续需要一线深耕市场拓展客户关系。', '', '代理阿根廷当地认证的是单相BS模块表，如本次继续只用BS模块表与海兴竞争，价格会惨败，本次计划采用BS和DIN两种产品投标，海兴一直是用DIN导轨表，主要是因为电力公司实际上更倾向于DIN安装，需要公司提供DIN表的样机，提前给到市场做测试以及认证。', '1，目前还没有收到正式的截标日期，EDENOR所有的招标都是邀标，目前代理公司收到了邀请参加。2，技术规格与ADD技术参数一致，目前还未有最新的技术规格拿到，电力公司内部说并未更改。3，DIN型号未做当地认证，公司也并未有合适的KEMA认证，并且电力公司要求产品要带有显示屏，业务建议采用DIN-3.5这款产品，也请丁总和宋总给予建议，是采用DIN-3.5还是公司新款DIN-5应标？4，业务先立项，待有其他资料拿到后，再及时反馈。', '李明2019-07-09 14:48:52', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('325', '{9954FFFE-7199-40AA-87D6-8C4DFA844CD5}', '61', 'INHE-0593', '2019-07-09 09:56:14', '0000-00-00 00:00:00', '2019-07-10 15:34:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070904/PDA', '', '', '', 'Projet de Développement des Connexions à l’Electricité（PDCEL）电力连接发展项目（PDCEL）', 'SONABEL自有资金，布基纳法索国家财政支持，项目受益者，资助机构（AFD，亚洲开发银行，世界银行，欧盟等），SONABEL的技术合作伙伴和商务合作伙伴，商业银行的融资，感兴趣制造商/供货商的融资', '', '', '', '通过直接协商的方式，每个lot将和相关的供货商签订采购合同，预计每个lot选择三个供货商。这些供货商需要拥有在非洲特别是布基纳法索和其邻国的用户证明。供应商的选择将由SONABEL提出，并由能源部长提交部长理事会通过。', '', '', '', '供货商需要拥有在非洲特别是布基纳法索和其邻国的用户证明', '', '', '', '待定，目前建议银河直接参与项目。由于是融资项目，故电力公司的资信状况评估十分重要，此处提供电力公司SONABEL近年的财报，以供评估。', '', 'sonabel为100%国家控股公司，政府对电力公司采购决策影响大。备注：布基纳法索将于2020年进行总统大选，现任总统Kabore有意参选寻求连任。', '', '', '', '', '', '我司与代理AZON合作在BFN市场打下了一定的基础，AZON与今年退休的总经理是几十年的密友，此前azon主要是经营总经理和商务总监DCC，DCC表示“AZON在BFN市场有很多关系，项目成功不仅在于电力公司，也需要超出电力公司之外的一些决定因素”。但是仍有以下情况需要反应：\r\r\r\n1.个人感觉代理与新任总经理关系一般；\r\r\r\n2.个人感觉代理信息滞后，有几次都是需要我提醒代理，代理才了解当地的情况，但是代理了解情况之后，会第一时间与我司分享（如此前BFC项目技术规格运作及标书草稿分享）；\r\r\r\n3.代理精力不如从前；', '', '', '', '海兴，Itron，及今年来有一些中国厂商出现在BFN，如小城科技，东方电气，Clou；也有ISKRA等欧洲厂商前往BFN电力公司进行了产品推广。竞争形势较为激烈。（此前BFN一个太阳能发电站项目，共有70多家购买了标书，最终参加投标的约有40家）', '{9954FFFE719940AA87D68C4DFA844CD5C8C3CDC70C5243B796247CC1ED7EC56E}_SONABEL近年财报.zip', '银河在BFN当地有一定的基础，但电力公司核心客户关系尤其是必不可少的利益分配这一块需要加强。', '{9954FFFE719940AA87D68C4DFA844CD5B79221563C224206B274FD7CD6B16366}_BFN电力公司最新介绍20190619.pdf', '电力公司/能源部客情的进一步经验与建设；对BFN政局变动及时了解；融资能力；代理关系的处理；', '支持立项', '胡蝶2019-07-09 14:21:30', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('326', '{84A4F384-279D-4AD6-9962-19F9D539AC3A}', '61', 'INHE-0593', '2019-07-11 13:56:32', '0000-00-00 00:00:00', '2019-07-15 10:21:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071101/ABE', '', '', '20190722', 'Demande de consultation fournisseurs de compteurs 电表供货商咨询', '', '', '1.每一个收到农电询标函的当地公司，在7月22号至少准备3份不同电表厂商的技术规格及商务报价，原产地证明及样机，提交给农电；\r\r\n2.截标后15天内，农电会测试提交的样机及样机与ALIOTH系统是否兼容，同时会给供货商进行提问，测试通过及提问通过后，农电做出最终选择。', '', '一家电表厂商可以提供资料/样机给多家当地公司参与询标。不限制一家电表厂商中多个LOT，重点在于报价，样机测试，能否通过ALIOTH系统对电表进行管理。', '', '无要求', '', '无要求', '', '', '', 'BFN当地两家收到农电询标函的公司分别拿银河资料及样机进行相应询标lot的投标，银河报价包含代理azon佣金。', '', '', '', '', '', '', '', '', '', '农电在今年年初进行了改革，随后我开始关注农电，几次前往农电咨询项目，认识了个别工程师。后期需要进一步深化农电客户关系，可以考虑让国电高层为我们引见农电高层。', '', '竞争较为激烈。一些公司觉得既然难以敲开国电大门，就先从农电开始。此前被废除的试点项目，就有7家公司前往了现场；而且这次询标，农电有意吸引多家公司参与。（5000多台表，分为4个lot，每个lot分别发给一家或者多家当地的公司，每家收到询标的公司，至少需要提交3家电表厂家的资料报价及样机）', '', '策略：我司授权两家当地公司分别进行投标，我司报价包括代理AZON佣金。\r\r\r\n优势：1.BFN市场上我司有一定的基础；2.国电背书；\r\r\r\n劣势：1.项目金额不大，但是涉及的人员多（两家当地公司，代理，代理合作伙伴REXEL，国电介绍人），由于商务报价是农电考虑的一个重要因素，故各个环节利润空间的控制很重要；2.由于预计涉及到的电表厂商多，担心银河资料报价样机泄密，被同行掌握，影响其它重点项目；3.7月22号需要提交资料及样机，时间紧张，考虑申请先提交资料，后期补样机。4.样机能否与AlIOTH集抄系统兼容。', '', '农电客户关系的深入建设；各方利润的控制（如我与代理AZON沟通佣金比率，AZON主动提出他不会要太高的佣金，要以中标为目的）；及时提交资料及样机；', '支持立项，开始我司在BFN农电的业务。', '胡蝶2019-07-12 10:01:39', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('327', '{FBDC30EF-B8A6-4B21-8E66-EF0998356CB8}', '66', 'INHE-0634', '2019-07-12 13:35:57', '0000-00-00 00:00:00', '2019-07-17 08:53:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071201/MMR', '', '69（T）/ESE/2018-2019(1 Year)', '2019年8月19日', '（项目名称为缅文）（中文大意为：单相两线智能电表供应）', '缅文，仍在翻译中。', '', '仰光Test lab对样机测试；通过样机测试的投标人技术资料将被ESE审核，由DyCE决定技术方案是否通过；通过前面2轮审核以后的投标人之间进行价格比较，价低者得。', '', '缅文，仍在翻译中。', '', '缅文，仍在翻译中。', '', '缅文，仍在翻译中。', '', '与NBL相同，需要TYPE TEST，DLMS等报告。所有投标资料均需要在截标日当天递交。', '', '银河供货，本地合作伙伴KMN投标。', '', '', '', '100%到货且验收合格以后，30天内付款。', '', '', '', '合作伙伴KMN与电力局的业务往来密切，人脉资源丰富，仅6月份内就接连中了5个标，其中一个是建立变电站的交钥匙工程项目，价值一亿四千万美元。项目经验丰富，财力雄厚。老板KMN为人和善重视诚信，可靠度较高，且做事井井有条，思路清晰。', '', '银河与KMN合作过NBL项目，虽然失败但是互相之间建立了一定的默契度和信任度。银河与电力局的关系较浅，没有过多的往来，与某些关键人物的关系处于“我认识你，你不认识我”的程度，需要进一步巩固。', '', '竞争对手除了本地公司的人脉关系较量以外，更主要的是来自中国的表厂，如科陆，青岛乾程，许继，华立，正泰，海兴等。这些表厂的价格均比我们低很多，投标报价的时候要慎重。', '', '银河在APE的时候供应了高峰设计的技术方面完全符合要求的表计，但需注意，APE项目表计是没有任何报告和证书的，如仍采用简单表方案，【价格】方面最有竞争力，证书将是最大短板。今时今日的电力局不会让我们轻易地在证书方面蒙混过关。', '', '符合要求的样机+证书报告+极富竞争力的报价', '建议立项，重视样机证书和报价，争取中标。', '陈雁2019-07-12 15:37:54', '04', '★★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('328', '{6053EFE7-259B-4629-A01D-4B81DA7048F7}', '60', 'INHE-0560', '2019-07-12 13:44:33', '0000-00-00 00:00:00', '2019-07-16 17:35:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071203/BAT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户在蒙古有多年运作招投标项目的经验，且多次中标（最近的一次中标项目为4月份的机床项目），有较为雄厚的社会关系与商务履历。', '', '', '', '目前当地\r市场的电表有思达、华立、正泰及俄罗斯厂家的电表，都是简单电表。思达于2003年中过一次世行投资的标，2014年也进行过小范围的AMI试点，但据客户反映试点效果有待考量，该项目并未在蒙古大范围推广。华立及部分俄罗斯厂家在蒙古市场的产品都以简单表为主，订单量不大但稳定。正泰主要以海外EPC工程总包的形式进入当地市场，承揽变电站及输电线项目，其中包含少部分电表项目。以上几家在电表市场基本都处于在有项目，有发展，但目前发展后劲不足状态。此次招标项目是我司依靠该代理的社会关系及人脉中标该项目并同步推广我司预付费产品及系统进入当地的良机。', '', '竞争策略：与该代理合作，中标智能电表项目并同步推广我司预付费产品及方案。                                                            优势：功能完善的预付费电表产品+成熟的AMI系统。                     劣势：                                                          1.与其他竞争对手相比，我司对当地的安装环境及电网状态实际判断经验不足2.我司已报出首轮报价，客户表示价格较高。                                                          ', '', '1：7月20日之前提供给客户推广我司产品所需的样机，帮助客户抓住机会，提前运作关系。                       2：强劲的技术演示团队。                                                                           3：有竞争力的价格。                                                  ', '建议立项', '李美娇2019-07-12 16:19:00', '03', '★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('330', '{9176F1E6-0C52-40B4-BF68-DFB215EFD00F}', '61', 'INHE-0500', '2019-07-12 22:25:07', '0000-00-00 00:00:00', '2019-07-16 17:29:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071205/EOR', '', 'CORP 4832', '2019年9月10日 GMT +2 10AM', 'Turnkey project services for a total system replacement of existing online vending system (OVS) maintenance & support for a period of 4 years关于在线售电系统的整体替换和运维交钥匙项目，合同周期：4年', '价格条款：DDP本地交付，采用本地货币兰特支付；\r\n付款主体：ESKOM；\r\n付款条件：此项目分为Project Phase (18 Months)和Contract Phase (42 Months)，暂未看到结算相关内容、本次招标也未提供合同部分的文件；Eskom常规是授标前邀请短名单供应商协商合同具体条款；参考其他市政售电系统付款条件。\r\n交期：合同签订日起6个月内\r\n质保：4年\r\n代理和银河之间的交易方式：代理直接投标，银河与NYC直接结算；具体结算按项目协商。\r\n', '{9176F1E60C5240B4BF68DFB215EFD00F8442F4C2B3234363A3D51C033076BD50}_Annexure K - Pricing Schedule.xlsx', '1. 投标评估：所有强制投标文件按要求提交；\r\n2. Gatekeeper 评估：不满足则直接出局；\r\n3. 功能性评估：技术评估 【70%】+ 项目管理评估（含供货记录等验证）【30%】；功能评估≥80%才可进入下一阶段；\r\n4. 价格评估 & BBBEE评估 （必须是BBBEE 1 ~4级内）\r\n', '{9176F1E60C5240B4BF68DFB215EFD00F074E749A304748709C51373D9D483750}_RFP - Online Vending System.pdf', '1家中标。不一定是价格最低中标、也不一定是分数最高中标，Eskom保留选择与供应商协商的权利。\r\n', '{9176F1E60C5240B4BF68DFB215EFD00F2B47EB25ABE84FF19C47768372BB342D}_Eskom - Standard Conditions of Tender.pdf', '无需开立投保保函\r\n', '', '至少最近两年审计财务报告；\r\n需要提供供货记录。\r\n', '', '需要谌总和软件部大力协助，1. 技术评估要求十分细致\r\n及严格，应答表有10多个表格需逐项应答并需提供对应文件；\r\n2. 技术应答表和报价单中涉及到项目方案制定、相关服务、培训等等内容，需仔细阅读并标注，以便高效、精准应标；尤其是表格“#1.3 SLA Acceptance”\r\n', '', '代理直接投标，银河作为厂商支持', 'N/A', '1.高层政府/政治关系（尤其是国企部和财政部）在授标中占据主导作用；\r\n2.ESKOM评标团队中技术层面在初审阶段占据主导作用。						\r\n', '', '银河对NYC报价：FOB Shenzhenn \r\n付款条件：交货后收到发票的30天内支付本地币。\r\nNYC对银河付款条件：同ESA项目。 \r\n资金来源：National Treasury\r\n', '', '待进一步分析ESKOM年度财务报告						\r\n', '', '银河合作代理NYC\r\n政府/ESKOM层面关系：通过近期郭总和NYC一起现场客户关系推动，在政府高层（总统府、财务政部层面）有较大突破，NYC本身在ESKOM COO等层面有一定客户关系，但在技术层面无客户关系，采购层面有一定内部关系；\r\n代理公司管理层面：经营目标明确，管理层稳定，竞争策略上行动力较强，愿意和银河一起组织客户和市场关系进攻；\r\n代理公司财力层面：当前受到EST项目影响，代理银行贷款审批暂无通过，资金流上有一定压力。						\r\n', '', '银河合作代理NYC\r\n政府/ESKOM层面关系：通过近期郭总和NYC一起现场客户关系推动，在政府高层（总统府、财务政部层面）有较大突破，NYC本身在ESKOM COO等层面有一定客户关系，但在技术层面无客户关系，采购层面有一定内部关系；\r\n代理公司管理层面：经营目标明确，管理层稳定，竞争策略上行动力较强，愿意和银河一起组织客户和市场关系进攻；\r\n代理公司财力层面：当前受到EST项目影响，代理银行贷款审批暂无通过，资金流上有一定压力。						\r\n						\r\n', '', '主要竞争对手和当前竞争局势：\r\n1.Itron（Ontec），当前EKSOM的售电系统供应商，在ESKOM售电领域经营超过15年，技术运作占主导作用，ESKOM内部客户关系牢靠；\r\n2.其他主要售电系统竞争对手：Landis&Gyr、Conlog、EOH、Cigcell，这四家公司在南非市场售电项目经验丰富、公司规模较大，背后有较大政治后台背书；\r\n3.和NYC处于同一层级的竞争对手：海兴、Syntell、Contour、 Sandulela Technologies，目前仅在市政和分表领域的售电市场有一定份额，有较强的的综合实力和合作代理运作。\r\n', '', '1.NYC BBBEE Level 2资质和本地工厂通过了工信部指定SABS认证 70%本地化政策审核，可以视作是本地客户服务支持点；\r\n2.通过EST近期郭总和NYC在现场的客户关系拓展，已在政府层面政治（财政部和国企部）关系有了较大的突破，需要持续跟进政府层面的高层支持和合作；\r\n3.银河的供货资质和系统经验满足标书要求；					\r\n4.技术层面目前发现有较多Itron、兰吉尔系统的运作点，需要尽快澄清和提供支撑技术方案和文件，并准备好后期演示工作。\r\n', '', '1.通过EST近期郭总和NYC在现场的客户关系拓展，已在政府层面政治（财政部和国企部）关系有了较大的突破，需要持续跟进政府层面的高层支持和合作；\r\n2.技术层面目前发现有较多Itron、兰吉尔系统的运作点，需要尽快澄清，同时需要软件部和谌总这边大力支持，提供支撑技术方案和文件，并需要软件部评估和准备好后期演示工作。\r\n', '售电系统管理用户数量巨大，超过500万台STS预付费代码表，后期可能还有STS预付费水表接入，涉及到后期运维，项目金额巨大；\r\n鉴于ESKOM历史售电供应商Itron南非业务调整，在政治力量上面当前其代理Ontec已大大削弱，此项目势必会在本地大型系统公司之间激烈竞争。\r\n', '李忠鹏2019-07-12 22:33:45', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('331', '{024DCCE8-EDE3-4BBC-8DA4-4258F7A5D4B0}', '61', 'INHE-0819', '2019-07-16 21:30:26', '0000-00-00 00:00:00', '2019-08-14 13:46:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071604/MDA', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '付为2019-07-17 13:08:57', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('332', '{6A6A06E8-2C12-49CE-8D52-F9B7E92CB867}', '61', 'INHE-0819', '2019-07-17 00:33:57', '0000-00-00 00:00:00', '2019-08-14 13:45:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071701/MDB', '按公司意见，三部参与，二部退出此项目', '', '', '', '目前标书还未公布，业务拿到了标书的技术规格部分。电力公司总经理和技术总监透漏说商务条款和以往的标基本上是一样的，故可参考RMY的商务部分。', '', '未确定', '', '', '', '未确定', '', '', '', '', '', '银河投标', '', '', '', '未确定', '', '已向电力公司商务总监提出要求，估计今明两天会给出2018年以及2019年最新的收益资料。', '', '', '', '目前业务已经和电力公司总经理，技术总监，商务总监，以及融资项目经理建立了良好的客户关系，上述人物是项目关键人物。业务经过和总经理四次正式和非正式的接触，有比较大的把握将总经理发展成“代理”角色；正是由于总经理的协调，技术和商务总监积极参与到了AMI+LPU方案的编写中，给业务提供了很多有用的信息。另外，融资项目经理也在频繁接触中，目前，业务正在积极通过其在世行以及非发行的关系寻找资金。（DMC项目也是其从世行找的资金）', '', '', '', '策略：1，银河已经向JIRAMA供过约5万台预付费表，业务可以运作技术规格（技术总监在给业务DMC03技术规格的时候也建议银河提供更优的技术规格）2，通过对接JIRAMA融资项目经理，为项目寻找资金。由于之前供货十分顺利，对于融资方来说也是一颗定心丸。3，通过拉总经理入局，使其成为我们的‘代理’，进而让整个决策链为银河拿单服务。                   优势: 1，此前为JIRAMA供过5万台预付费表，反响很好，为之后的项目打下了基础。2，目前客情关系发展顺利，可控性较高。                       劣势： 1，之前没有深耕电力公司客户关系，对代理依赖过大，可控性差。2，没有将银河AMI+LPU方案植入JIRAMA。', '', '关键：是否有能够找到资金（世行，非发行等），或者银河能提供最优的商务条款（价格和付款条件）。         需要的支持：希望参考RMY项目的信息，为DMC03找到更优商务方案。', '业务认为DMC03是银河在MD市场化被动为主动的契机。商务和技术上我们已经有经验，融资渠道也在拓展，加上良好的客情关系，银河有把握这个单。', '付为2019-07-17 13:11:48', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('333', '{7783AAC7-23AF-47AB-A5D0-CD806F9205A8}', '60', 'INHE-0790', '2019-07-17 11:11:03', '0000-00-00 00:00:00', '2019-07-22 15:51:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071702/JOD', '', 'Call off contract NO. (23/2019)', '2019年8月21日', '2年随需订单--供应单相智能电表/Two years call - off contract for supply of Smart Single phase.', '价格条款C&F电力公司仓库或CFR阿卡巴港，IDECO付款条件open account 或 不可撤销承兑信用证。目前与代理合作方式未定，因此付款主体待定。交期下单后90天内交货', '', '先评技术，测试样机，再评商务部分。', '', '标书说明不排除多家中标', '', '投标保函金额不低于最高替代价格的5%，货币为美金，有效期120天，从截标日起算。\r\n履约保函为合同金额10%，美金，有效期15个月，从下单日起算\r\n\r\n', '', '标书中规定了部分零件的一些供应商。型式测试报告，电表和LCD寿命测试报告(20年),电池寿命测试报告，继电器测试报告与DLMS证书，过去5年供货记录', '', '继电器测试报告，投标授权书', '', '目前合作方式还没有最终决定。', '', '此电力公司为私营电力公司，非政府企业，项目资金是电力公司自己筹资。因此政府影响力相对小。', '', '验收并交单后一个月内全额支付', '', '良好', '', '合作伙伴owner在另一家电力公司主管表计部门工作了近20年后自己成立了公司，主要业务是为电力公司提供电气设备和解决方案。在电力公司的关系良好。', '', '', '', '市场的主要竞争对手是华立和海兴。当地现有的表计多数由华立供应，预计超过30万台表，产品包括单三相智能电表，目前华立经营得比较深，产品在当地没有很大的问题。', '', '目前约旦表计已华立的电表为主，电力公司有意引进多家。代理在当地关系良好，这是我们进入当地市场的一个机会。劣势是华立已在当地经营多年，表计的价格也比较低，而我们在当地耕耘较浅。', '', '客户关系建设，具有竞争力的价格以及技术支持。', '', '莫亚检2019-07-18 17:33:59', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('334', '{A2FFD634-B31B-4C95-81D0-4079024D3D40}', '66', 'INHE-0774', '2019-07-23 10:00:49', '0000-00-00 00:00:00', '2019-07-29 17:43:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072301/ETS', '', 'RO14493260 Cap B2 pos 30 SD-TR SUD 2019', '2019年8月19日 当地时间下午3点', '电表-用于执行计量任务                                                                               Electricity meters - for carrying out the measurement activity', '价格条款：DDP 客户仓库\r\n付款条件：交货后60天内（通常90天内）\r\n交期：标书无说明，通常签订合同后30-60天交货，分批次发货\r\n质保：最低5年，质保是评标考虑因素', '{A2FFD634B31B4C9581D04079024D3D408442F4C2B3234363A3D51C033076BD50}_FisaDate_DF1043221-EN.docx', '85%价格+15%质保（最低5年，10年满分）', '', '最优价中标，投标人需要参投所有LOT', '', '投标保函：Lot 1 = 21,000.00 lei,(约4519欧元) \r\r\r\nLot 2 = 8,000.00 lei, （约1721欧元）\r\r\r\nLot 3 = 20.000.00 lei, （约4304欧元）\r\r\r\nLot 4 = 11.000.00 lei. （约2367欧元）\r\n\r 有效期：截标期开始100天\r\r\n\r\n\r\n', '', '证书：MID证书/EN ISO9001/2015\r\r\r\r\r\r\r\r\n供货记录：过去三年一个合同或多个合同中，同类型电表供货价值分别不低于Lot 1:2,100,000 Lei#FE54`Lot 2:800,000 Lei#FE54` Lot 3:2,000,000 Lei#FE54`Lot 4:1,100,000 Lei。\r\r\r\r\r\r\r\n\r财务数据：\r\r\r\r\r\r\r\n\r对于每个Lot,要求供应商过去三年的营业额分别不少于Lot 1:2,100,000 Lei#FE54`Lot 2:800,000 Lei#FE54` Lot 3:2,000,000 Lei#FE54`Lot 4:1,100,000 Lei。\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n						\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n', '', '', '', '联合投标（最终投标方式还在和代理确认中）', '代理主投', '', '', '交货后60天', '', '', '', '', '', '', '', '该市场同行有：AEM(罗马尼亚）/ ADD（摩尔多瓦）/Luna(土耳其）/宁波三星等；', '', '竞争策略：低价策略，先争取通过代理做进市场，获取欧洲市场供货记录，再参与其它项目； 劣势：不了解当地相关采购法律法规、语言不通。', '', '价格支持', '我们简单表没有MID证书，没法用简单表投Lot 1, 用一代单相模块表投Lot 1可能没有价格优势；Lot 2 是带无功计量功能的表，需要由罗马尼亚计量局BRML出具的认证,认证周期4-12个月，每款表费用大约2000欧，我们不具备参投条件；Lot 4是三相智能电表，我们未取得MID证书，因此暂时无法参投。因此，建议只参与LOT 3，由代理主投，其他Lot代理会找其他的供应商。', '何森华2019-07-25 19:02:08', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('335', '{CD44AFAF-4A04-4BBC-9087-C0187E1B5A30}', '61', 'INHE-0431', '2019-07-22 14:34:52', '0000-00-00 00:00:00', '2019-07-24 17:00:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072302/UDL', '', 'UEDCL/SUPLS/2019/10161', '2019年8月8日', 'Supply of 2000 pre-payment energy meters   供应2000台预付费电表', '付款：交货后30天内见发票付款\r\r\n质保：12个月', '{CD44AFAF4A044BBC9087C0187E1B5A308442F4C2B3234363A3D51C033076BD50}_SBD supply of 2000 pre-payment meters for replacement of faulty meters.docx', '先技术评标，再商务评标，然后是总评。各项占比标书未明示', '', '一家中标', '', 'UGX.8,000,000 (Uganda Shillings Eight Million only). 由代理开立', '', 'The 	Bidder 	shall 	submit 	with 	its 	bid 	the 	following 	additional documents/requirements:  \r\r\nBid security \r\r\nRegistered Powers of Attorney for local suppliers and Notarised for foreign suppliers. \r\r\nUganda National Bureau of Standards (UNBS) Certification \r\r\nBidders shall submit a sample of the meter offered together with their bid. Failure to submit a sample shall lead to disqualification of the bid. \r\r\nManufacturer’s acceptance letter allowing UEDCL to carry out Factory Acceptance Tests ', '', '', '', '代理商投标', '', '政府部分，政府应该有一定影响力。但是单子很小，估计不会有政府人员过问。', '', '付款：交货后30天内见发票付款\r\n质保：12个月						\r\n', '', 'UEDCL为国家配电公司。财务状况较好', '', 'PSI为之前在UNW项目合作过的代理。此次项目是他们强烈想参与的。且他们自己负责保函，公关。我们只提供相关资料和样机。', '', '因为配电业务99%是由UMEME操作，所以之前银河一线业务未在UEDCL投入过多精力，只有一些官方拜访。', '', '原来的供应商为CONLOG。与电力公司关系很好。此次标书也是对CONLOG有利的。但是因为代理十分想投，且表明他们的关系也很好。', '', '因为项目不大，所以银河做为辅助方，提供相关资料，由代理做主要活动。', '', '', '综上，建议立项。', '刘佩2019-07-23 14:25:46', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('336', '{00C6D016-0326-4455-B2FC-8FE3CD9C3714}', '60', 'INHE-0868', '2019-07-24 09:30:47', '0000-00-00 00:00:00', '2019-07-26 10:48:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072401/PAP', '', 'RFP-SEP-2019-033', 'August 19, 2019', 'Sustainable Energy for Pakistan (SEP) Project “Implementation of Open-Architecture Based Advanced Metering Infrastructure (AMI) System”巴基斯坦可持续能源项目（SEP）“基于开放架构的高级计量基础设施（AMI）系统的实施”', '价格条款：DAP+清关费用.\r\r\r\n付款主体：Tetra Tech.\r\r\r\n付款条款：1）无预付款；\r\r\r\n          2）75%收到运输文件及相关认证文件后支付；\r\r\r\n          3）25%在所有电表成功安装运行，被认可后支付；\r\r\r\n交期：中标通知后120天内完成20%电表及HES交付，150天内完成50%电表交付，210天内完成交付。\r\r\r\n质保：在投标资料中有供方提出。\r\r\r\n代理商对银河付款方式：取得订单后开 L/C。', '', '评分制，技术标(60)+价格标(40)。技术标45分以上才有资格评价格标 Evaluation Criteria - Smart Meters                      Points\r\r\nProduct Functionality (Technical)                          60\r\r\na.Past Track Record                                         5\r\r\nb.Compliance with Technical Specifications/Requirements    30\r\r\nc.Compliance with Functional Specifications/Requirements   15\r\r\nd.Compliance with Delivery & Installation Schedule          5\r\r\ne.Capacity/Capability of providing AMR Services & Support   5\r\r\nPrice proposal', '', '得分最高者中标。一家中标', '', '无保函要求', '', '1.公司信息，包含注册名称，业务类型地址及主要公司成员电话，地址及身份 2.公司简要介绍及与此表技术要求相似的供货和服务证明（格式如标书）     3.公司及子公司的非政府企业证明                                     4.标书附件C的签字(代理提供）                                      5.授权联络人的电话和邮箱地址                                       6.境外投标商的本地代表联系信息                                     7.注册DUNS码（投标金额大于30，000美金，代理提供）                 8.KEMA/CESI/UL的测试报告                                         9.支持服务提供说明（含质保,技术支持,授权服务点合理库存)', '', '制造商授权，供货记录，KEMA测试报告，交期计划表和支持服务说明；8月5号提交。', '', '代理商投标', '', 'Tetra Tech自主评标。', '', '业主通过支票或电汇在收到运输文件及相关认证和业主承认文件后付款75%，尾款在所有产品安装调试，运行并由业主承认后付清', '', '', '', '主营软件方案，与当地公共部门和电力企业都有过合作（MDM，AMI都有涉及）。', '{00C6D01603264455B2FC8FE3CD9C3714D18C251E4D454BA8A05CF92EE9AFCB77}_InfoTech Utility Solutions.pdf', '初次合作', '', '主要竞争对手是Iskraemco', '', '授权合作伙伴投标，利用其在当地的渠道以及自身产品经验。', '', '关键需要电表及HES符合要求', '此项目投标阶段不需要保函或样机。 投标文件主要提供制造商授权，KEMA测试报告，相关供货记录，交期计划和支持服务的相关说明（含质保方案）。', '庄钦2019-07-25 10:12:06', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('337', '{72B1DBA5-DA35-4DA8-A551-9F2BB5948052}', '60', 'INHE-0868', '2019-07-25 16:37:58', '0000-00-00 00:00:00', '2019-07-30 17:01:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072504/LAP', '', 'DD1/P*D/ICB/2019/006/B', '2019.08.21', 'Supply and Delivery of 5(40) A, 3ph, Direct Connected Static Energy Meters (PPM), with Modem 供应5（40）A，三相直通电表，带通讯模块', '价格条款：FOB+清关+内陆运费（见Appendix-VI-A）\r\r\n付款主体：CEB.\r\r\n付款条款：1）CEB开立LC；\r\r\n          2）85%见货运单据支付；\r\r\n          3）15%在客户验收后支付；\r\r\n交期：LC后两个月内完成电表，模块配件及软件总量的50%，四个月内完成全部交货。\r\r\n质保：5years（from the date of FOB dispatch to the purchaser)，前两年免费更换，两年后质保期内免费维修或更换\r\r\n备注：L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。', '{72B1DBA5DA354DA8A5519F2BB59480528442F4C2B3234363A3D51C033076BD50}_ENG-DD1-P&D-ICB-2019-006-B.pdf', '根据投标方企业性质及归属地，判定实际评标价格（见P8，11.2）', '', '通过技术标且价格最低的投标人中标。一家中标						', '', '投标保函：LKR 750,000，有效期至2019-12-19，银河授权代理提供；保函上只体现代理名字，代理多次以这种形式为制造商开立投标保函，确认业主认可此方式。\r\r\r\r\n履约保函：10%合同额，必须供货方开，Sri Lanka银行开立或保兑， LOA14天内开立，最后批次发货后六十天有效', '', '1. ISO9001：2008或最新的质量保证认证，                            2.符合ISO/IEC：17025：2005的实验室认证                            3. 测试并提交测试报告（要求见技术部分11/21 Clause6.3）             4. 10年生产经验证明，近七年供货记录（技术部分11/21，Clause6.2）.    5. Ofgem certification or other equivalent certification issued by an independent electricity regdlating institution certifying a minimum service life shall be provided with the offer. (标书技术部分13/21，Clause8.1）', '', '购买标书和投标保函的授权文件（PCA，letter of Authorization,power of attorney)，8月1号提供；                                        供货记录，测试报告，ofgem certification 最迟8月9号提交。', '', '银河投标，授权当地代理购买标书，开立投标保函。', '', 'CEB自主采购，评标。', '', '业主签合同后开立信用证，见货运单据支付85%货款，业主验收后，释放验收凭证付清尾款', '', 'CEB为当地最大电力公司，电表招标主要都通过CEB执行', '', 'Rotax成立55年，由23年投标经验，200多名员工。多次在电力设备邻域中标CEB项目。比较了解CEB的运作流程', '{72B1DBA5DA354DA8A5519F2BB5948052D18C251E4D454BA8A05CF92EE9AFCB77}_Rotax Pvt Ltd财务报表.pdf', '尚未与CEB建立直接关系。\r\n', '', '主要对手是宁波三星，合作伙伴为当地代理Powersol Lanka,最近两年电表项目中标较多。深开发，华立，瑞银，海兴也在持续投标', '', '利用合作伙伴在CEB电力公司积累的经验和渠道，了解以往类似项目中标情况。', '', '样品能及时，满足要求地提供。 相关测试报告，资质认证符合要求。', '1.标书要求十年资质，我司还差五个月。与两家代理确认，其CEB评标工程师沟通，可以操作；且CEB评标流程都是四个月以上，届时我司年限已满；另调查以往开标结果已有先例（南京微星microstar，调查成立于2009年2月，在2018年就已经在投标，虽未中标，但已经入围公布了其价格标）                                                 2.L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。  3.购买标书和投标保函均可授权代理操作完成。', '庄钦2019-07-29 09:20:04', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('338', '{2EB66FDD-304E-4AFD-B068-466EAEABE11A}', '60', 'INHE-0868', '2019-07-25 17:04:10', '0000-00-00 00:00:00', '2019-07-29 17:38:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072505/LAQ', '', 'DD1/P*D/ICB/2019/007/B', '2019.08.21', 'Supply & Delivery of 10(100) A Direct Connected Programmable Static Energy Meters (PPM) with Modem 供应10（100）A，三相直通可编程电表，带通讯模块', '价格条款：FOB+清关+内陆运输（见APPENDIX-VI-A）\r\r\n付款主体：CEB.\r\r\n付款条款：1）CEB开立LC；\r\r\n          2）85%见货运单据支付；\r\r\n          3）15%在客户验收后支付；\r\r\n交期：LC后两个月内完成电表，模块配件及软件总量的50%，四个月内完成全部交货。\r\r\n质保：5years（from the date of FOB dispatch to the purchaser)，前两年免费更换，两年后质保期内免费维修或更换\r\r\n备注：L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。\r\r\n', '{2EB66FDD304E4AFDB068466EAEABE11A8442F4C2B3234363A3D51C033076BD50}_ENG-DD1-P&D-ICB-2019-007-B.pdf', '根据投标方企业性质及归属地，判定实际评标价格（见P7，11.2）\r\n', '', '通过技术标且价格最低的投标人中标。一家中标	', '', '投标保函：LKR 750,000，有效期至2019-12-19，银河授权代理提供；保函上只体现代理名字，代理多次以这种形式为制造商开立投标保函，确认业主认可此方式。\r\r\r\n履约保函：10%合同额，必须供货方开，Sri Lanka银行开立或保兑， LOA14天内开立，最后批次发货后六十天有效						\r\n', '', '1. ISO9001：2008或最新的质量保证认证，                            2.符合ISO/IEC：17025：2005的实验室认证                            3. 测试并提交测试报告（要求见技术部分11/21 Clause6.3）             4. 10年生产经验证明，近七年供货记录（技术部分11/21，Clause6.2）.    5. Ofgem certification or other equivalent certification issued by an independent electricity regdlating institution certifying a minimum service life shall be provided with the offer. (标书技术部分13/21，Clause8.1）', '', '购买标书和投标保函的授权文件（PCA，letter of Authorization,power of attorney)，8月1号提供；                                        供货记录，测试报告，ofgem certification 最迟8月9号提交。', '', '银河投标，授权当地代理购买标书，开立投标保函。', '', 'CEB自主采购，评标。', '', '业主签合同后开立信用证，见货运单据支付85%货款，业主验收后，释放验收凭证付清尾款\r\n', '', 'CEB为当地最大电力公司，电表招标主要都通过CEB执行\r\n', '', 'Rotax成立55年，由23年投标经验，200多名员工。多次在电力设备邻域中标CEB项目。比较了解CEB的运作流程\r\n', '{2EB66FDD304E4AFDB068466EAEABE11AD18C251E4D454BA8A05CF92EE9AFCB77}_Rotax Pvt Ltd财务报表.pdf', '尚未与CEB建立直接关系。\r\r\n', '', '主要对手是宁波三星，合作伙伴为当地代理Powersol Lanka,最近两年电表项目中标较多。深开发，华立，瑞银，海兴也在持续投标\r\n', '', '利用合作伙伴在CEB电力公司积累的经验和渠道，了解以往类似项目中标情况。', '', '样品能及时，满足要求地提供。 相关测试报告，资质认证符合要求。\r\n', '1.标书要求十年资质，我司还差五个月。与两家代理确认，其CEB评标工程师沟通，可以操作；且CEB评标流程都是四个月以上，届时我司年限已满；另调查以往开标结果已有先例（南京微星microstar，调查成立于2009年2月，在2018年就已经在投标，虽未中标，但已经入围公布了其价格标）                                                 2.L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。  3.购买标书和投标保函均可授权代理操作完成。', '庄钦2019-07-29 09:22:24', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('339', '{2C028D7A-D8FA-45FA-9C1F-6C0DF8DAD336}', '61', 'INHE-0843', '2019-07-26 16:11:58', '0000-00-00 00:00:00', '2019-09-09 08:56:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072601/EGA', '', '', '', '', '签订合同后10天内100% T/T', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '已经与代理确认两相三线表可用三相四线表来改，BS安装方式。代理希望购买我们的样机帮助我们做当地认证SAE，用于后续的项目投标。', '刘畑杏2019-09-05 19:45:31', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('340', '{F8B35215-84CA-48B5-BE72-33B2092EDDDC}', '60', 'INHE-0535', '2019-07-29 11:01:31', '0000-00-00 00:00:00', '2019-08-01 13:43:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072901/BOD', 'BOD', 'MMC/T-NSC-03/0219', '2019.08.05', 'Supply, installation and FMS activity for 5 years for LT AC Single Phase10-60A Smart (Postpaid/Prepaid) Static Energy Meter with Enclosure as per IS16444-2015 amended upto date with communication technology (GSM/GPRS / 3G / 4G / PLC / NB-IOT / 6LoWPAN LPRF/LoRa) in IPDS towns of Maharashtra of MSEDCL.在马哈拉施特邦的10个指定城镇供应，安装和运维5年共约40万只符合IS16444标准的LT AC单相智能电表（10-60A）和表箱（通讯为 GSM/GPRS / 3G / 4G / PLC / NB-IOT / 6LoWPAN LPRF/LoRa)。', '付款主体：MSEDCL\r\r\r\r\r\n付款条件：\r\r\r\r\r\n1）供货部分：50%到货支付；40%安装且从billing系统返回数据后支付；10%项目期结束后（5年后）支付；\r\r\r\r\r\n2）安装部分：90%安装后且从billing系统返回数据后支付；10%项目期结束后（5年后）支付；\r\r\r\r\r\n3）FMS部分：按月服务费费用支付；\r\r\r\r\r\n交期：交货和安装期10个月，FMS运维期5年；\r\r\r\n违约条款：每周按约定批次价值的0.5%或最多10%合同额罚款；\r\r\r\r\n质保：供货之日起5.5年\r\r\r\n代理商对银河付款条款：LC，在谈。', '{F8B3521584CA48B5BE7233B2092EDDDC8442F4C2B3234363A3D51C033076BD50}_Smart Meter Tender RFP dt. 03-07-2019.pdf', '电子投标；\r\r\n1.先开技术-商务标，通过后再开候选人的价格标；\r\r\n2.开完价格标后，选出最低价，并组织逆向招标：报价高于最低价5%之内的投标人会被要求是否按L1价格供货，若同意，则可授标。但最低价L1将有优先选择心仪的供货城镇的权利。', '', '10个城镇分给3家中标，L1-60% 24万，L2-30% 12万， L3-10% 4万；\r\r\n但最低价L1将有优先选择心仪的供货城镇的权利；余下城镇再分配给L2,L3；', '{F8B3521584CA48B5BE7233B2092EDDDC2B47EB25ABE84FF19C47768372BB342D}_Annexure IX-List of town wise requirement of smart meters.pdf', '投标保函：Rs. 1,60,58,000/USD229,400；有效期180+90天，印度卢比开立；汇票或银行保函形式；\r\n履约保函：中标通知后14天内提交10% 合同额/USD2,294,000，印度卢比开立；银行保函形式；\r\n由主投方开立。', '', '1.投标人需为原始表厂，或系统兼容商（AMI解决方案供应商，OEM授权商），或表厂和系统兼容商的联合体；\r\n2.主投需为印度本地注册的公司；\r\n3.主投需在MSEDCL电子投标网站注册；\r\n4.联合体成员过去3年需累计有Rs.100Cr./USD14.3Million的年平均营业额；其中系统供应商过去3年每年营业额需达Rs.20Cr./USD2.9Million；\r\n5.主投代表各成员在投标期间及合同通知行期间负责合同项下所有可交付货物；\r\n6.IS13779证书，IS0 9001，ISO14000，或其他同等IEC国际标准证书；\r\n7.过去3年有50万电表供货记录，其中20万需要是过去一年内的供货，并提交供货记录证明；\r\n8.NABL实验室或同等国际标准实验室证书；\r\n9.R&D证书或同等国际标准证书（已与客户确认，ISO9001和ISO27001有研发字样，及我司高新企业证书可一同作为R&D证书资质）', '{F8B3521584CA48B5BE7233B2092EDDDC03404677E4D44E9EB56B3D512B2AF9CC}_QR－Smart Meter Tender RFP dt. 03-07-2019.pdf', '银河作为联合体成员（电表制造商身份）需负责的投标资料部分，如生产资质，供货记录，财务资质，R&D资质，电表和HES技术资料等。\r\n', '', '联合投标', '原因：本地招标，标书规定主投需要是印度本地注册公司；主投需要开立保函，给银河开立货款信用证；\r\r\r\n主投：还未确定，在谈。计划本周出差落实主投（投资方）人选。\r\r\r\n双方全责：主投代表联合体向电力公司负责合同项下所有可交付项目；开立投标保函和履约保函；给银河开立信用证；\r\r\n         联合体成员银河负责单相电表供货，并提供所需的技术支持如培训，系统兼容等。\r\r\n         分包商为BlueOcean，负责表箱的本地采购，电表和表箱安装，系统兼容和本地执行运维。', 'MSEDCL自主采购，评标（IT部分负责评标）', '', 'MSEDCL根据各里程碑付款条款，在IT部门验收完成且受到发票后45天内直接付款给主投', '', '电力公司项目预算 Rs. 160.58 Crores / USD 22,940,000', '', '项目主要代理为BlueOcean，不作为主投，而作为项目分包商负责表箱的本地采购，电表和表箱安装，系统兼容和本地执行运维。有现成的本地执行团队。\r\r\r\r\r\r\n老板Ashutosh亲自参与项目的运作，项目初期曾带我们去MSEDCL拜访，并与内部渠道团队见面讨论。BlueOcean在MSEDCL有其他项目经验，因此与IT部门熟络。标书中一些原始不利条款如各成员都必须在印度本地注册，IS13779证书，NABL实验室，本地R&D证书等经建议已在近期修正为只有主投需在本地注册，同等国际标准证书等。\r\n\r\rBlueOcean已询的本地一家成立15年的单相表箱厂家报价Rs.90/USD1.3，包含表箱开模费，但届时需要银河作为设计方提供表箱图纸。', '', 'BlueOcean老板Ashutosh亲自参与项目的运作，项目初期曾带我们去MSEDCL拜访，并与内部渠道团队见面讨论。\r\r\r\n', '', 'Genus+Kalkeitech；\r\r\r\nHPL+Avon；\r\r\nAnchor+Panosonic；\r\n全部为本地公司', '', '电力公司一个计量点（包含表，通讯，安装，运维）的预算：Rs.4012/USD 57.3 (含18%GST)；\r\r\nBlueOcean会采用Trilliant的HES，Trilliant报价每表约$2.5；\r\r\n努力中标为优先目的，因此银河也将提供自己的HES报价参考，如果Trilliant因价格原因做不下来，银河HES可以作为备选；\r\n综合成本和系统，可能采用GPRS通讯；\r\r\n鉴于主要竞争对手Genus在EESL和其他项目中的报价不会低于Rs.2300/$32,最终报价将参考JPM价格水平，确保能入围前三，后期再根据逆向招标价格调整最终授标价。\r\r\n', '', '由于修正版的招标文件等待时间较长，且主投人选尚未确定，且截标期在即，投标期较短，需要尽快准备投标文件。', '1.BlueOcean为项目执行的SI分包商和项目主要运作渠道方，但因自身银行保函额度不足，无法作为主投开立保函；\r\r\n需要引入另外可以开立保函的主投，潜在主投将在本周出差时见面，洽谈，确认；可能要签署三方合作协议；\r\r\r\n2.由于投标时间短，考虑到已延标2次，且之前因为主投未确认下来，一直未立项；但无论主投是谁，银河联合体成员身份及对主投的诉求（开立保函，开立信用证）不变，因此建议先立项，以便及时准备投标文件；同时会尽力争取再次延期；\r\r\r\n3.由于不填写合同相对方，立项申请表不能提交，因此合同相对方先输入BlueOcean，以便完成立项申请流程。', '左亚楠2019-07-31 15:35:25', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('341', '{9CA7CB3F-9C1E-48C2-A630-677EA536ACC4}', '61', 'INHE-0885', '2019-07-30 13:26:21', '0000-00-00 00:00:00', '2019-08-02 16:48:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019073003/BWC', '', '3532/19', '2019 08/21', '在博茨瓦纳建立一家制造工厂，为博茨瓦纳电力公司制造，供应和交付最大需求和分体式智能电表Establishment of a manufacturing plant located in Botswana for the manufacture, supply and delivery of maximum demand and split smart meters to Botswana Power Corporation', '还在EOI阶段', '', '还在EOI阶段\r\n', '', '还在EOI阶段\r\n', '', '还在EOI阶段\r\r\n', '', '如附件', '{9CA7CB3F9C1E48C2A630677EA536ACC403404677E4D44E9EB56B3D512B2AF9CC}_EOI BPC.pdf', '还在EOI阶段\r\r\r\r\n', '', '代理商直接投标，银河提供技术和方案，后续提供SKD散件', '代理商的合作伙伴Alamz直接投标\r\r\r\n', '还在EOI阶段\r\r', '', '还在EOI阶段\r\r', '', '电力公司财务状况良好', '', 'FACTORFAST METERING (PTY) LTD有当地的合作伙伴Almaz，Alamz是本次项目的主投方，提供土地、资金、仓库、政府关系。Almaz有自己的本地电子组装工厂，为博茨瓦纳政府供应笔记本电脑。', '', 'Almaz作为本次项目的主投方，在当地政府有牢靠的政府关系，根据反馈Almaz称能直接了解到当地政府的需求。', '', '目前有竞争对手Conolog、海兴、Itron、兰吉尔。BPC不喜欢海兴。BPC后续会在2-3个公司内采购电表，每家公司的采购比例后续分配，', '{9CA7CB3F9C1E48C2A630677EA536ACC4C8C3CDC70C5243B796247CC1ED7EC56E}_博茨瓦纳市场竞争对手.PNG', '银河的优势在于银河有丰富的建厂经验，代理商的合作伙伴Almaz已经在本地建厂组装电子设备，具备良好的市场经验和政府关系，了解本地政策，与此同时该公司还在BPC和电表业务上均有涉猎。现代理反馈即使最终投标未成功，但本地政策要求BPC也要购买建厂的公司30%的仓储商品。附件为Almaz公司简介。      劣势是银河在本地并没有供货记录，对我们来说基本上是一个新的市场。所以在电力公司层面把控度不高。   ', '{9CA7CB3F9C1E48C2A630677EA536ACC4B79221563C224206B274FD7CD6B16366}_Almaz Company Profile.pdf', '项目成功的关键在于与客户共进退，同时推动代理的合作伙伴，尽快落实建厂。    银河需要现场支持客户，了解市场情况，促成中标。    \r\n需要的支持：商务和技术支持。', '这个项目可以作为我们进入博茨瓦纳市场的一个重要开端，建厂仅是一个开始，关键点在于我们基于这个工厂以后在博茨瓦纳市场取得更多的项目和订单。', '潘健康2019-08-01 13:39:49', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('342', '{D849E361-64CA-4F28-8911-925DC1F967CC}', '66', 'JXINHE-2559', '2019-08-02 11:52:35', '0000-00-00 00:00:00', '2019-08-06 08:43:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080201/GPZ', '', '503901', '2019/09/16', 'REQ_Smart Single & Three Phase Low Voltage Meters- (503901)LV单三相表表带通讯模块', '价格条款，付款主体，付款条件，交期和违约条款，待代理翻译整理后提供。质保期：五年。初步商定合作方式为：代理投标，我司作为厂商授权其投标', '', '待代理翻译整理后提供。', '', '待代理翻译整理后提供。', '', '待代理翻译整理后提供。', '', '待代理翻译整理后提供。\r\n', '', '投标文件需在9月1日前准备妥当。', '', '授权代理商投标', '', '', '', '待与代理商确认。', '', '待调查', '', '代理商曾为电力公司做过一项目，拥有有一定的人脉关系，团队工作高效，给我司的回复及时。', '', '尚未与电力公司建立有效联系。', '', '华立、三星、威胜、EDMI在当地市场活动积极，华立、三星和EDMI成功供货。', '', '利用代理的人脉关系，收集市场信息，制定有竞争力的投标策略，初次进入该市场，对该市场的了解较少。', '', '符合的技术方案和有竞争力的报价', '经过这段时间的开发工作，找到当前的代理，代理作为政府部门、公用企业、部队项目的供应商，拥有一定的政治资源和人脉关系。经过沟通，代理合作愿意强烈，愿意出资购买样机以参加投标，并表明智能表项目在希腊市场前景广阔，希望可以开展广泛的合作。我计划双方通力合作，力争拿下项目后，共同开拓希腊市场。', '淦永妍2019-08-02 14:07:44', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('343', '{E01B80BE-B636-44D3-BDC9-96569ABF5842}', '66', 'INHE-0628', '2019-08-05 10:07:26', '0000-00-00 00:00:00', '2019-08-08 10:06:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080501/POL', '', '428 / DU / PS / A / WL / 2019', '2019/8/22', '', '价格条款： DAP\r\r\n\r\r\n付款主体： PGE\r\r\n\r\r\n付款条件：，业主收到货后根据含VAT的发票给供应商付款，30天以内完成。代理称波兰的情况都是这样，业主信用好，而且属于欧盟采购，没有坏账风险。\r\r\n\r\r\n交期：从8-50周都有供应计划，详见右侧附件交期计划表\r\n\r\n\r\n质保违约：篇幅很长在不同情况下有不同的惩罚，见右侧附件Formal requirements', '{E01B80BEB63644D3BDC996569ABF58428442F4C2B3234363A3D51C033076BD50}_Formal requirements.docx', '详见附件Formal Requirements\r\n要求文件必须全部符合，在此基础上价格低中标。', '{E01B80BEB63644D3BDC996569ABF5842074E749A304748709C51373D9D483750}_交期计划表.docx', '共3个Lot\r\r,每家都可以投3个Lot。Lot 1无资质，Lot 3数量太小，建议投Lot2\r\r\n1.3-phase profile registration, 9 976 pcs\r\r\r\r\n2.CT and CT/VT special static meters, 3-phase profile registration,               10 670 pcs\r\r\r\r\n\r3.CT/VT four-quadrant 3-phase profile registration, 274 pcs\r\r\r\n', '', '投标保函Bid bond\r要和投标文件有效期保持一样，也即递交标书后60天，如需还应根据业主要求延期，保函货币只能用当地货币兹罗提。\r\r\nTask No. 2 - 136 000.00 PLN (in words: one hundred thirty six thousand zlotys)\r\r\r\r\n', '{E01B80BEB63644D3BDC996569ABF58421DD410FC292E4E1893AFBEF9F88431CD}_REQUIREMENTS CONCERNING BIDDERS, BID BOND.docx', '附件为Pozyton提取翻译的资质要求文件', '{E01B80BEB63644D3BDC996569ABF584203404677E4D44E9EB56B3D512B2AF9CC}_Info_Inhemeter.docx', '需商务组协助准备商务文件', '', '银河直接投标', '', '政府对采购一般不干涉，主要由业主进行决定', '', '', '{E01B80BEB63644D3BDC996569ABF5842DC30B63FF962416CACC9A604CE6ABE1F}_Payment for delivery.docx', '', '', 'Pozyton在当波兰有自己的表厂，也曾经向PGE供过货，但规模较小，价格偏高，因此寻求与银河合作。欧洲企业的运作并非是类似非洲的上层打招呼，评标做手脚。是长期的技术影响和品牌信任的建立，所有产品真的要经过严格测试，提交的报告也会逐项核对，另外投标要用波兰语。Pozyton有投标经验，而且是波兰的测试实验室，因此在技术上可以得到较好的支持。', '', '暂未见到过业主', '', '目前竞争对手都是欧洲企业，如Apator,Landis&Gyr,Elegama(林洋收购的立陶宛公司)，价格从177-216不等。', '', '电力局的供应商一直很稳定，新的供应商一定会经过严格的样机测试。银河最好的方式还是通过经得起考验的产品和好的价格去吸引客户。已知宁波三星和思达都是通过长期的本地运作，带领工程师在电力局做实验、演示等获得客户信任，以得到供货机会。', '', '项目需要样机、开立保函、邮寄，剩余准备时间太少，目前延期并未得到业主回应。以波兰语投标，客户还需时间帮助银河翻译文件和软件语言。', '欧洲目前可投的项目只有CT表，希望公司遇到这样的机会可以尽快尝试。', '刘元豪2019-08-06 09:54:06', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('344', '{5BD6B1D9-9EB8-4C30-B1CF-F518F4B84024}', '61', 'INHE-0772', '2019-08-08 09:54:41', '0000-00-00 00:00:00', '2019-08-12 13:51:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080802/MAA', '', 'APPEL D“OFFRES NO: 01/2019/DPEC', '2019.09.16当地时间早上9点整', 'PROJET DE REHABILITATION D“OUVRAGES DE DISTRIBUTION ET DE DEVELOPPEMENT DE L“EFFICACITE COMMERCIALE (PDEC) PAR LA SONABEL AU BURKINA FASO布基纳法索国家电力公司电网升级和电力商业发展项目', '价格条款：DDP\r\n付款主体：西非发展银行针对项目专用付款账号\r\n付款条件：公对公T/T#FE54` 收到银行履约保函后付30%预付款，提单交付后付40%，货到电力公司仓库后付30%\r\n交期：最晚120天\r\n违约条款：合同总金额1%/周的罚金。罚金若超过合同金额的5%将取消合同。', '{5BD6B1D99EB84C30B1CFF518F4B840248442F4C2B3234363A3D51C033076BD50}_原法文标书分解.zip', '符合技术要求的最低价中标', '', '允许多家制造商中标', '', '投标保函：LOT1要求8千万西非法郎，Lot2 要求1千万西非法郎。有效期120+28天。\r\n履约保函：5%合同总金额', '', '2016.2017.2018三年公司财报\r\r\n至少5年的单三相表生产经验（国家机构或国际检验机构提供）\r\r\n过去5年的供货记录，最少提供2份数量2万台以上与标书要求相似的电表供货记录，并提供相应的履约证明或合同副本\r\r\n提供至少在3个国家（原产国以外的国家）实现最低5年销售，项目执行良好的客户证明文件', '', '1.保函 9月7日\r\n2.财务证明 9月7日\r\n3.投标文件 9月7日', '', '银河直投', '技术评标由电力公司执行。技术评标后进行商务评审。业主的影响力仅在技术评标部分。', '技术评标由电力公司执行。技术评标后进行商务评审。业主的影响力仅在技术评标部分。\r\n', '', '电力公司请款-西非发展银行审批-银行付款', '', '西非发展银行对该项目借款，其属世界银行旗下\r\r\r\r\n', '', '老客户：Azon\r\n内部关系：前总经理退休，现剩余DCC，该项目的决策权在DCC能力之外。新总经的关系情况不明。以往评标组成员有一定关系。\r\n', '', '主要客户关系在于实验室，软件部及电力公司个别总监，目前招标委员会高层未涉及。需业务前往一线再建客情', '', '对手：海兴，科陆\r\n对手合作伙伴：电力公司内线和当地代理\r\n对手市场地位：海兴中过7万台电表\r\n科陆代理是当地基建承包商，刚刚中标农电项目（内含电表）', '', 'S：我们有多次历史中标，有4套系统在电力公司内部，了解市场和电力公司，有客情历史。代理对当地评标情况较为熟悉。\r\r\r\r\n\r\r\r\r\r\nW：客情关系不稳定，电力公司内关系主要为中下层。银河新旧员工交接，历史项目情况需时间整理。评标组成员关系无。\r\r\r\r\r\n\r\r\r\r\r\nO：电力公司的高层更替，大家的竞争起跑线一样。\r\r\r\r\r\n\r\r\r\r\r\nT: 1.电力公司内部的人员更换，对手的当地代理实力强刚刚中标。2.项目大的情况下，海兴和科陆采取价格血拼。3.同时内部Azon的信任危机，因本次合作为项目佣金制度，代理存在支持多家厂家的可能。4.技术不符点澄清', '', '1.业务前往一线控场，专心建立客情。\r\n2.其他部门的协助： 商务，技术，业务，财务需分工明确密切合作。保函事宜和投标文件越早完成越好\r\n3.人手协助', '本项目原为BFC项目，因标书内容和项目运作方式放生改变，重新走立项流程。								\r\r\n', '张子琦2019-08-08 19:17:09', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('345', '{F8E0BA8E-1F01-4400-8DD4-CED684FC8EF2}', '61', 'INHE-0865', '2019-08-09 09:43:44', '0000-00-00 00:00:00', '2019-08-12 13:45:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080902/CDZ', '', 'N°13/GS2E/2019', '2019/9/13', 'Mise en ?uvre d’un HES/MDM COMPTEURS EAU ET ELECTRICITE  水电HES/MDM系统', '交期条款（交期，违约金等）:由投标方提供（见AO  13 GS2E 2019 HES_MDM tableau de conformité V Lecture中cadrede réponse的planning条款）；如果违约，每天扣除合同总金额的0.2%，最多扣总金额的8%。报价条款 ：DDP Abidjan。交货地点：阿比让。标书结算方式：协商确定。\r\r\n', '', '评投标文件是否满足技术要求。\r\r\n', '', '招标方不一定选取价格最低方作为中标方，也可以一家都不选。\r\r\n', '', '无\r\n', '', '无', '', '相关技术和商务资料需2019/9/1前提供。', '', '银河直接投标', '无', ' 招标方自主决策。', '', '标书没有明确指出。根据以往该市场经验，签订合同后，收到发票后的60天内支付，先交付后付款，100%后TT。', '', '较强', '', '我们在电力公司有一定的客户关系基础；代理Azon在电力公司客户关系较好,但是在水务公司的关系待核实。', '', '银河与该市场的电力公司CIE和GS2E有中基层客户关系，以及个别高层客户关系。', '', '本次受邀的竞争对手有：ATOS Worldgrid#FE54` SAGEMCOM#FE54` SIEMENS#FE54`TRILLIANT#FE54`ITRON#FE54`MILTEL#FE54`LAISON#FE54`SUMITOMO#FE54`HUAWEY#FE54`HEXING', '', '优势：银河在当地实施多个系统，软件实力在当地颇受好评，AMI系统已在当地运行实施。劣势：该系统暂无接入水表的经验。', '', '客情关系和技术水平为项目成功关键。 支持：技术/商务支持此次投标。', '', '蔡慧2019-08-09 17:20:01', '04', '★★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('346', '{BDC246CE-C8AA-4D8F-95CA-80F7C2562947}', '66', 'INHE-0634', '2019-08-13 14:29:16', '0000-00-00 00:00:00', '2019-08-16 17:35:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019081301/URV ', '', '', '2019年8月21日', '掌机以及系统的供应兼容和培训', '待核实 ', '', '待核实', '', '一家中标', '', '待核实 （代理负责）', '', '无特殊要求', '', '应答表/图纸/画册等基本资料即可', '', '银河授权代理投标', '', '', '', '', '', '', '', '合作伙伴的关系脉络较为成熟，如果成功投出，中标机会比较大', '', '', '', '待核实 ', '', '与软件部黄总提前沟通确认过，此项目不需要样机，技术要求基本都能满足，建议尝试，提供资料和报价即可。', '', '及时完成需求文件并提供合适的报价 （应答表需要法语，需商务组协助）', '建议立项，提供相应投标需求资料并提供合适的报价。银河与代理之间的结算可以进一步沟通确认。', '陈雁2019-08-13 14:47:52', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('347', '{92DE3449-2447-48AF-85C2-F5DD39D8F093}', '61', 'INHE-0725', '2019-08-14 05:44:52', '0000-00-00 00:00:00', '2019-08-20 17:07:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2019081401/MNP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '上方980台电表业务已完成洽谈。尼日利亚微网项目目前面临井喷，市场需求较大，经业务在本地调研，本地较多的微网运营商都对银河产品的质量较为认可。基于本地良好的客户关系及客户基础，微网项目大有可为。\r\r\r\n业务计划针对本地所有微网业务只立一个项目以简化工作流程，因是直采项目，无需较多支持，自评三星。', '赵政洁2019-08-14 15:07:52', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('348', '{627157B0-F038-4E47-8483-44B022F99271}', '61', 'INHE-0440', '2019-08-14 09:14:10', '0000-00-00 00:00:00', '2019-08-20 17:03:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019081402/TTY', '', 'SMZ/F0120/G/2018~2019/01', '2019/9/12', 'Supply of Electricity of Energy Meters 供应智能电表', '价格条款：CIF Zanzibar Seaport 付款主体：Ministry ofLand, Housing, Water and Energy (MLHWE) /Zanzibar Electricity Corporation (ZECO) 付款条件：无预付款，无发货款，100%合同金额，提交付款申请和验收证明后在30天内支付。交期：签合同后3个月内交货。质保：验收后12个月。违约：支付未发货产品值的0.2%/天,最高赔付10%的合同金额。', '', '国际招标，无本地优惠条款，一家制造商可以中标三个LOT,或选每个LOT最低价中标，标书中未明确说明，投标人可以选择投任何完整的LOT或者整合不同的LOT一起投标，评标流程和TANESCO类似，分两个阶段，阶段一主要是技术评审，阶段二主要是商务评审，要提供有效的营业执照，保函，授权函，反腐申明，财务资质证明和供货经验证明等。', '', '只允许厂商投标，一家制造商可以中标3个LOT，或者选每个LOT最低价中标，标书中未明确说明。', '', 'ITL投标开保函，有效期：投标有效期后30天，即150天，保函金额2%的投标报价，需本地知名银行开出，履约保函合同金额的10%，介绍银行保函和支票。', '', '过去三年电表供货记录，认可的营业执照，VAT,TIN等证书，有效的签字授权，提供资料证明是电表制造商，律师认证测试报告，过去三年的财务数据等。', '', '图纸和装箱信息，技术应答表，画册，型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL投标，ITL中标后，从银河采购SKD或整机', '', 'ZECO属桑岛能源部管辖，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际金融机构/援助，评标流程和TANESCO类似。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。\"', '', '付款主要跟进用服的合同经理和财务（1）无预付款(2)无发货款（3）100%的合同金额，提交付款申请和验收证明后30天内支付。我司主要和ITL签合同和付款，100% 3-6个的远期信用证支付。', '', 'ZECO资金主要来自政府预算和国际金融机构，国际援助资金和银行贷款等。代理商/经销商公司较大，目前现金流不大好，开信用证问题不大，有偿还能力。', '', '代理商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。ZECO方面关系还需要积累，目前主要是和电表部经理，商务总监和采购总监联系。代理和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好。', '', 'ZECO商务总监，电表部经理，部分工程师，需继续拓展和积累等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI本地的代理商Comfix&Engineer，建有电表组装厂。CLOU本地的代理商Bahdela,价格很低，电表厂也已经完工。海兴和CONLOG的坦桑代理ACHELIS合做，价格和我司持平。威胜自己投资的电表厂也已经完工，价格和科陆持平。目前我司的单相表价格和EDMI持平，三相表价格低于EDMI，但高于威胜和科陆。', '', 'ZECO项目，要求厂家投标，ITL直接投标，我司提供相关技术资料支持，ITL中标后，从银河采购电表，我司按照ZECO技术规格ODM供货给ITL。目前银河的本地合作伙伴ITL有如下优势：1，在坦桑大陆供货资质较好。2，有一定的经济实力。3，此前有投过一次标，有一定经验。桑岛作为坦桑的一部分也值得开拓。', '', '推荐/设计合适的产品，报价符合市场形势，技术/商务支持到位，必要的客户关系建设等。', '目前我司和ITL合作较好，ITL本身有志于周边市场开拓和发展，此标订单数量虽然不多，但值得去做。建议立项，准备文件，支持ITL投标，打开桑岛市场。', '汤伟2019-08-14 15:41:23', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('349', '{E22C2777-402F-4CC5-B9D6-23613C1B5CE8}', '66', 'INHE-0634', '2019-08-21 15:50:41', '0000-00-00 00:00:00', '2019-08-23 19:17:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2019082102/YGN', '', '23（T）/YESC/2018-2019(1-Year)', '2019年9月16日', '缅文翻译中', '缅文翻译中', '', '样机测试+投标文件审核+价格共3轮评审，通过样机和投标文件审核后才有机会开价格，价低者胜。', '', '在通过技术标评审的投标人之中选择最低报价，无其他限制。', '', '缅文翻译中', '', '无特别要求', '', '型式测试报告+DLMS报告', '', '银河授权代理投标', '/', '/', '', '通过验收且纳税以后，电力局在30天内安排付款', '', '按照以往项目经验，YESC采购预算已经到位，没有支付障碍。', '', 'KMN自身财力雄厚，做了几十年电力部的项目，经验丰富，人脉广阔。已经合作过NBL和MMR项目，积累了较好的默契度和信任度。另外，代理的总部与本次招标方YESC同在仰光市区，代理反馈其与YESC之间的关系更为密切。', '', '银河业务相对熟悉仰光实验室情况，需透过KMN的资源巩固加深彼此联系，有助于及时获取内部信息并采取积极有效的措施控制局面。', '', '电表对手主要是一度垄断YESC电力局订单的EVER电表和蜂拥而至的诸多中国表厂，如科陆、青岛乾程、海兴、威盛、许继、正泰等。', '', '银河通过APE/NBL和MMR等项目有了匹配市场需求的技术方案，应该努力在技术评审中排除竞争对手，才能不陷入价格战的恶性竞争。（最好的技术运作时间点是在一个月之前知道有项目即将发出还没正式发出的时候，电力局很欢迎厂商前去做技术交流和经验分享。）', '', 'YESC和实验室是邻居关系，对样机的测试要求可能会相对认真，银河需要递交符合要求的样机；参与竞争的低价策略中国表厂较多，银河需要根据竞争态势做出合适的报价方案；为避免陷入价格胶着战，迫切需要强化商务运作，剔除劣质低价扰乱市场秩序的竞争对手。\r\r\r\n', '建议立项，强化商务运作，争取中标。', '陈雁2019-08-23 10:42:56', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('350', '{F976ACA7-064E-49F8-80A5-F151B71E8477}', '61', 'INHE-0843', '2019-08-23 17:03:19', '0000-00-00 00:00:00', '2019-08-27 16:18:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019082303/MXP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '圆表尽快完成测试；公司给予价格上的支持', '墨西哥市场等待多年，终于迎来自由竞争的局面，公司为进军墨西哥市场已投入了大量人力物力，此时正是进入市场的好时机。希望公司给予大力支持。', '刘畑杏2019-08-23 17:09:31', '04', '★★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('351', '{3BD5FCD4-03E4-413F-BEB6-751C124D1BAA}', '66', 'INHE-0579', '2019-09-03 09:45:33', '0000-00-00 00:00:00', '2019-09-04 16:11:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090301/TUS', '', '2019D3746', '2019年12月25日', 'SMART GRID DE LA STEG – ETAPE IFOURNITURE ET MISE EN OEUVRE D’UNE INFRASTRUCTURE DE COMPTAGE AVANCEE (AMI)ET D’UN SYSTEME DE GESTION INTEGREE DE LA CLIENTELE智能表计项目第一步-AMI的供应、实施以及集成用户管理系统', 'a.价格条款为CIP Tunis\r\r\nb.付款主体为STEG。该项目由AFD法国开发署银行资助。\r\nc.设备和工程的保修期为自临时验收之日起12个月。在保修期内，中标人有义务在最长30天内自费更换任何声称不合规或有缺陷的设备。如果超过30天，所有额外费用将由中标人承担。\r\n直到质保过期后，承包商仍有义务进行任何维修，修改或调整以及满足合同条件所需的任何调整，并更换认为有缺陷的供货产品的任何部分。    \r\n', '{3BD5FCD403E4413FBEB6751C124D1BAA8442F4C2B3234363A3D51C033076BD50}_DAO AMI Sfax Fourniture et services - v6.6.1.pdf', '技术评分比重占70%，商务部分占30%。\r\r\n看行政文件的符合度、对资质标准（整体理解、组织、财务和供货经验能力）的评分大于等于14/20、技术符合度和评分、价格最低者中标。', '', '一个投标人可以中几批，但是第一批的中标人不能中第二至第四批；第二至第四批中标人最多中两批，如果两个批次被授予同一个投标人而另一个批次没有被授予，由于投标人的报价加权总额比另外两批中标人为该批次提供的报价高，因此该批次可能会分配给另外两批的中标人。第一二三四批的授标将考虑上述评标规则和特定的折扣，电力公司将根据授予批次的加权总额选择最有利的解决方案。电力公司将考虑每批的最低价格和投标人在其投标资料中提供的每批折扣金额和计算方法。\r\n', '', '投标保函金额：Lot1 四十万第纳尔、Lot234六十万第纳尔、lot5三十万第纳尔、lot6五十万第纳尔。投标有效期后28天。突尼斯银行开出。\r\n履约保函：合同总金额的5%。', '', '财务要求：a）流动资金比率≥1.1（流动资产）/（短期债务）≥1.1）\r\r\r\nb）债务比率≤80％（总负债）×100 /（总资产）≤80％）年平均营业额至少为：\r\r\r\nLot 1：1000万欧元\r\r\r\nLot 2,3和4：只投其中一个Lot要求2千万欧元，如果投两个或三个Lot，则需4000万欧元\r\r\r\nLot 5：1000万欧元\r\r\r\nLot 6：1500万欧元\r\r\r\n如果投标人投多个Lot，则累积上述门限。 ', '{3BD5FCD403E4413FBEB6751C124D1BAA03404677E4D44E9EB56B3D512B2AF9CC}_联合体资质要求.docx', '1.RF通讯模块Wi-Sun证书；\r\n2. G3-PLC的FCC和CENELEC-A两个频段的证书；\r\n3. 外购产品的相关资料。', '', '银河和其他表厂联合投标', '1.联合投标的原因：标书要求两家电表厂和一家电表厂联合投标。\r\n2.主投标人：银河。\r\n3. 双方大致的职责：银河负责整和第二家电表厂的电表以及一家气表厂的气表，进行测试演示。开立保函。\r\n第二家电表厂和气表厂的职责包括提供样机进行集成测试，联合资质进行投标。', '该项目为法国开发署银行资助的项目，因此法国的公司投标会有优势。', '', 'Lot2、3、4：付款方式和条件只有双方验证POC和试点后才适用。中标人只有满足了试点阶段的要求后才能要求POC和试点阶段的付款，只有满足了斯法克斯推广的要求才能要求第三阶段的付款。发票的支付将根据部署的进度对外国中标人以国际货币支付，对本地投标人以突尼斯第纳尔支付。\r\r\r\r\r\r\r\r\n预付款：在提前取得预付款之前，持有人必须提供个人和联合担保，以保证在STEG第一次请求时偿还全部预付款。a.对于工程类型预付款为第一个12个月工作计划总额的10%。\r\r\r\r b.对于设备类产品预付款为10%。项目款的20%将在成功完成POC和试点阶段后支付（基于电力公司提供PV），80%在第三阶段支付（其中15%在安装好30%第三阶段要安装的低压电表和气表后支付、20%在安装好70%第三阶段要安装的低压电表和气表并在通信链中调制后支付、15%在在安装好90%第三阶段要安装的低压电表和气表并在通信链中调制后支付、30%在完成第三阶段时付款，包括安装和调制好第三阶段全部电表和宣布临时验收（基于双方签署的PV）。', '', '该项目为法国开发署银行AFD资助。STEG向AFD贷款1.2亿欧元。', '{3BD5FCD403E4413FBEB6751C124D1BAA108D268797C74834B1DDE2FC1083AA37}_STEG贷款成功.docx', '1.联合体成员还在筛选中。目标为欧洲电表厂和气表厂。因为欧洲出口突尼斯零关税。\r\r\n2.当地代理ICE有一定的STEG项目投标经验，且中标多次。ICE老板做事稳重，在公司内部有自己的关系渠道，邀请了UDZ项目评标技术委员会主席和我们进餐。提前帮我们拿到了新版的技术和商务草稿。', '', '通过代理已与关键评标人员建立联系。', '', '竞争对手情况见附件。因为标书要求两家电表厂合作，因此竞争对手也是我们的潜在合作方。', '{3BD5FCD403E4413FBEB6751C124D1BAAC8C3CDC70C5243B796247CC1ED7EC56E}_TUS项目市场潜在合作方20190712.xlsx', '投标策略：与欧洲表厂合作参加Lot2-Lot5。\r\r\n优势：1.如技术过关，银河的价格优势将会有特别大的几率中标。\r\r\n     2.代理可以在截标前让他们关系帮我们审核技术文件。\r\r\n     3.市场现有的玩家情况已经了解。信息渠道已经建立。\r\r\n劣势：1. 突尼斯从中国采购需承担30%的关税。\r\r\n      2.银河较晚进入该市场，该市场的通讯技术要求是被其他厂家多年运作的结果。', '', '成功关键为技术部分。和第二家电表厂的电表以及一家气表厂的产品进行通讯集成。\r\r\n需要的支持：\r1.标书要求的证书要求。\r 2.样机通讯的测试支持。 3. 标书要求的通讯频段，如RF频段和G3-PLC双频段。 4.商务资质的满足需要重新开立用户证明。', '申请立项。', '孙娜2019-09-03 11:11:43', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('352', '{708B6F91-7B26-43B7-A53E-549E1800B9E8}', '61', 'INHE-0876', '2019-09-04 16:25:42', '0000-00-00 00:00:00', '2019-09-09 18:41:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090402/MEE', '', 'ICB No: Enc.26/EDM/2019', '2019年10月22日14：00', 'MEE 莫桑比克电力公司Energy for everyone总项目中预付费电表部分', '1.价格条款，标书为CIP MAPUTO等总计16个城市.2.付款主体：世界银行 3.交期 3-13个月 4.质保，交付后一年                      见右侧附件项目信息归纳表', '{708B6F917B2643B7A53E549E1800B9E88442F4C2B3234363A3D51C033076BD50}_EDM 20190903 投标项目信息归纳表-邓彧.doc', '见右侧标书 SECTION Ⅲ EVALUATION AND QUALIFICATION CRITERIA', '{708B6F917B2643B7A53E549E1800B9E8074E749A304748709C51373D9D483750}_Bid Document - Package F - Supply of 300,000 Energy Meters.zip', '允许制造商投多个lot, 不允许制造商授权多家代理投标', '', 'Lot 1 – Southern Region – 75.000,00 USD Lot 2 – Central Region – 60.000,00 USD Lot 3 – Nothern Region – 70.000,00 USD Region – 70.000,00 USD 见项目信息归纳表', '', '1. 过去5年财务状况； 2. 过去5年制造商应每年营业额不低于800万USD； 3. 要求10年制造经验；4. 7年内产品的实验报告； 见附件标书3.1 Postqualification Requirements ', '', '2019年9月20日', '', '暂定直投', '', '世行出资，业主决策', '', '10% 预付 （签署后30天内）\r\r\r\n80% FOB （交货后）\r\r\r\n10% 签收后30天  见标书P105-106', '', '世行出资', '', '', '', '', '', '目前HX 直采（赊销）2年赎期 按季度付款  \r\r\n科陆代理模式（VBC和华为）\r 目前系统采用华为的\n\r\n', '', '优势： 曾经批量供货，质量客户认可； 目前电力公司对华为系统不太满意，可以作为切入口；\r科陆质量有瑕疵，客户有抱怨；\r\r\n\r劣势：我司无当地固定合作人，HX长期深耕此市场，电力公司各层面及决策点客户关系强于我司\n\r\r\r\n', '', '合规答标；完善技术方案；有竞争力的价格；', '', '邓彧2019-09-04 19:11:34', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('353', '{68CCB80A-4ECA-4B99-BA7C-E9B178CEBEC4}', '75', 'INHE-0432', '2019-09-05 03:12:57', '0000-00-00 00:00:00', '2019-09-09 18:39:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090502/KLA', '', 'KP1/9A.3/RT/02/19-20', '2019年9月9号，中国时间下午3点以前。', '本地厂商电表供货，限制性招标（电力公司定向且单独邀请投标人参与投标）', '\r\n1.价格条款：DDP含16%VAT\r\n2.付款：货到且被电力公司测试、满意收货后，由供应商提供发票等资料，电力公司在收到资料后的30天起，开始付款。\r\n3.交期：要求有库存，随时可交付。\r\n', '', '1.商务评审投标资料。\r\n2技术评审\r\n3.财务评审。\r\n综合评审价格最低者中标。', '', '各家根据自己库存数量获得合同。', '', '投标保函：无。履约保函：合同金额的10%。', '', '1.IAC的注册资质文件。2.提供IAC年报。3.提供本地KEBS产品认证及测试报告。', '', '无', '', '银河IAC直接投标。', '', '此次由采购部主导，最终由MD/CEO、董事会通过决策。', '', '同历史订单。', '', '电力公司财务状况及支付能力较2017，2018年有所改善。', '', '很好', '', '很好', '', '参与投标的竞争对手：海兴、科陆代理工厂、思达代理工厂、Smart Metering（科陆供散件）。', '', '竞争策略：\r\r\r\n1.IAC按客户引导，填写库存数量：9万台。\r\r\r\n2.报价按客户建议，先与KF03报价一致。后续若客户要求，再与客户谈判并微调价格。\r\r\r\n3.交期：先按照获得订单后1-2个月内可以交付完毕的情况应标。', '', '1.确保9月9号前将投标资料上传至招标网站。', '1.由IAC戴萍与张贝兰协作，单独完成标书制作。标书资料将由OA单独发出。\r\r\n2.本项目为IAC额外订单，业务会全力以赴拿下。', '谭东羊2019-09-05 03:55:29', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('354', '{B366C0B3-17DA-4A42-A31B-097678C44417}', '60', 'INHE-0868', '2019-09-06 10:58:52', '0000-00-00 00:00:00', '2019-09-10 13:46:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090602/LAK', '', 'DD4/P*D/ICB/2019/007/B', '2019.10.09', 'Supply and Delivery of Programmable Static Energy Meter 10 (100)A - Direct Connected Three Phase 4 wire with Remote Disconnection and Reconnection facility, with cellular based GSM & GPRS, 3G, 4G and Radio Frequency (RF) Communication Facility 供应10（100）A，三相四线直通可编程电表，带继电器，模块通讯功能', '价格条款：FOB+清关+内陆运输（见APPENDIX-VI-A）\r\n付款主体：CEB.\r\n付款条款：1）CEB开立LC；\r\n          2）85%见货运单据支付；\r\n          3）15%在客户验收后支付；\r\n交期：LC后两个月内\r\n质保：5years（from the date of FOB dispatch to the purchaser)，前两年免费更换，两年后质保期内免费维修或更换\r\n备注：L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。\r\n', '{B366C0B317DA4A42A31B097678C444178442F4C2B3234363A3D51C033076BD50}_Eng-DD4-P&D-ICB-2019-007-B Programmable Meters.pdf', '根据投标方企业性质及归属地，判定实际评标价格（见P7，11.2）', '', '通过技术标且价格最低的投标人中标。一家中标', '', '投标保函：LKR 750,000，有效期至2020-02-06，银河授权代理提供；保函上只体现代理名字，代理多次以这种形式为制造商开立投标保函，确认业主认可此方式。\r\n履约保函：10%合同额，必须供货方开，Sri Lanka银行开立或保兑， LOA14天内开立，最后批次发货后六十天有效						', '', '1. ISO9001：2008或最新的质量保证认证，                            2.符合ISO/IEC：17025：2005的实验室认证                            3. 测试并提交测试报告（要求见技术部分11/21 Clause6.3）             4. 10年生产经验证明，近七年供货记录（技术部分11/21，Clause6.2）.    5. Ofgem certification or other equivalent certification issued by an independent electricity regdlating institution certifying a minimum service life shall be provided with the offer. (标书技术部分13/21，Clause8.1）', '', '由于国庆放假，10.9日截标，投标资料及投标样机需在9.23日前提供', '', '银河投标，授权当地代理购买标书，开立投标保函。', '', 'CEB自主采购，评标。', '', '业主签合同后开立信用证，见货运单据支付85%货款，业主验收后，释放验收凭证付清尾款', '', 'CEB为当地最大电力公司，电表招标主要都通过CEB执行', '', 'Rotax成立55年，由23年投标经验，200多名员工。多次在电力设备邻域中标CEB项目。比较了解CEB的运作流程。在之前合作项目中表现很专业，购买标书和开立投标保函的支持也比较到位', '', '已经参与LAP，LAQ项目，与业主有初步接触\r\r\n', '', '主要对手是宁波三星，合作伙伴为当地代理Powersol Lanka,最近两年电表项目中标较多。Genus，华立，瑞银，海兴，Secure也在持续投标', '', '利用合作伙伴在CEB电力公司积累的经验和渠道，了解以往类似项目中标情况。已有成功报价经验，业主对我们价格及产品外观质量初步印象不错', '', '样品能及时，满足要求地提供。 相关测试报告，资质认证符合要求。', '1.已有LAP和LAQ项目经验（是同一家电力公司招标，还处于评标阶段），已经大致摸清主要竞争对手及其价格情况。　2.与代理合作方式，如代理购买标书和开立投标保函已经确认可行，代理合作性较好，实力在当地也不错。　　　　　　　　　　　　　　　　', '庄钦2019-09-06 14:05:53', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('355', '{D30B45B7-35CA-4E6C-A870-69700848FA3C}', '61', 'INHE-0642', '2019-09-09 05:49:25', '0000-00-00 00:00:00', '2019-09-11 15:05:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090902/SRM11', '代号为SRE。', 'No: HI-TECH/P/B00002/2019', '2019年9月20日早上10点半', 'Energy meter upgrading, software purchase(Configuration software, system software’s), field test with necessary accessories, test machine for functional test, enclosure for meter and training & technology cooperation’s    Procurement No: HI-TECH/P/B00002/2019 电能表升级、软件采购(配置软件、系统软件)、现场测试必要的配件、供货产品功能测试机、电能表外壳、培训技术合作等\"', '价格条款：FOB\r\r\n违约赔偿金：每周0.1%，最高10%合同总金额\r\r\n付款条件：三选一，如下：\r\r\n5a, \r\r\n1. 签订合同后支付T/T 10%总金额\r\r\n2. 成功测试现场电表后T/T支付15%总金额\r\r\n3. 所有升级方案，培训和机器抵达供货场地后的4个月内，T/T支付30%\r\r\n4. 所有数目的智能电表整合，测试以及交付到用户收中后的6个月内，T/T支付45%\r\r\n\r\r\n5b,\r\r\n1. 签订合同后支付T/T 20%总金额\r\r\n2. 成功测试现场电表后T/T支付15%总金额\r\r\n3. 所有升级方案，培训和机器抵达供货场地后的4个月内，T/T支付30%\r\r\n4. 所有数目的智能电表整合，测试以及交付到用户手中后的6个月内，T/T支付35%\r\r\n\r\r\n5c, \r\r\n1. 签订合同后支付T/T 0%总金额\r\r\n2. 成功测试现场电表后T/T支付0%总金额\r\r\n3. 所有升级方案，培训和机器抵达供货场地后的4个月内，T/T支付30%\r\r\n4. 所有数目的智能电表整合，测试以及交付到用户收中后的6个月内，T/T支付70%					\r\r\r\n', '{D30B45B735CA4E6CA87069700848FA3C8442F4C2B3234363A3D51C033076BD50}_表1：SRM国投标项目信息归纳表.doc', '先技术再报价						\r\n', '', '3个Part,未指明有几个Lot(猜测是一个Lot)						\r\n', '', '\"1. 要求在commercial bank of Ethiopia 或者知名银行，按投标总价的2%金额开立保函。投标保函应在投标有效期结束后28天内有效\n2.授标后30天内提供履约保函，金额为合同总金额的10%\"						\r\n', '', '', '', '技术资料需要客服协助评估						\r\n', '', '银河投标', '', '国企，政府直接控制走向						\r\n', '', '提交商业发票后的30天内付款						\r\n', '', 'EAR客户反馈，此客户的支付能力一般，有拖欠款项的可能性						\r\n', '', '暂无						\r\n', '', '\"一线客户关系一般，主要依靠Hi tech内部员工进行运作。此人对Hi tech公司了解很深且具备一定的人脉关系。\n\"						\r\n', '', '该项目主要竞争对手将会是中国厂家						\r\n', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\n2. 推动代理同步运作客户关系，同时把控评标团队，实施竞标策略\n3. 获取招标预算，报出合适价格\"						\r\n', '', '项目成功的关键位：运作技术评标；低价竞争								\r\n', '请风控评估下付款条件，如果可行，需尽快延标（已经和代理沟通延标事宜，表示可以延标一个月）								\r\n', '潘正豪2019-09-09 15:57:39', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('356', '{735A5743-10D0-49DC-BE0D-0E81E18F8C2C}', '61', 'INHE-0381', '2019-09-09 10:40:07', '0000-00-00 00:00:00', '2019-09-11 16:26:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090906/MAF', '', '031/2019', '2019.09.23', 'Pour une fourniture de materiel de distribution a la SONABELSONABEL配电设备采购', '电力公司支付，有以下2种付款方式：\r\r\r\r\n方案一：20%预付款+80%货到付款\r\r\r\r\n方案二：20%预付款+60%已确认且不可撤销的信用证+20%赊销\r\r\r\r\n\r\r\n授权代理投标，银河与代理SGE之间的结算方式为：20%预付+80%远期信用证', '{735A574310D049DCBE0D0E81E18F8C2C8442F4C2B3234363A3D51C033076BD50}_MAF投标项目信息归纳表(1).doc', '1.	在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。\r\n2.	接下来评技术部分，技术资料是否满足标书的技术规格 。\r\n3.	评财务部分。评完财务文件，价格最低者中标\r\n', '', '在技术评估满足的投标商中，报价最低者将中标', '', '代理开立保函', '', '代理投标', '', '1.商务组提供投标资料：可参考MAA项目资料，需要补充CT表的技术资料。希望9.16号可以完成。17号寄出。\r\r\n2实验室提供样机：可参考MAA的样机，需要补充CT表样机。希望9月16号可以完成。', '', '代理商投标', '', '\"技术评标由电力公司执行。技术评标后进行商务评审。业主的影响力仅在技术评标部分。\r\n\"						\r\n', '', '', '', '', '', '\"老客户：Azon\r\r\n内部关系：前总经理退休，现剩余DCC，该项目的决策权在DCC能力之外。新总经的关系情况不明。以往评标组成员有一定关系。\r\r\n\"						\r\r\n', '', '主要客户关系在于实验室，软件部及电力公司个别总监，目前招标委员会高层未涉及。', '', '\"对手：海兴，科陆\r\r\n对手合作伙伴：电力公司内线和当地代理\r\n海兴中标BFN06,8万台电表。\r\n科陆代理是当地基建承包商，刚刚中标农电项目（内含电表）\"', '', '1.我们有多次历史中标，有4套系统在电力公司内部，了解市场和电力公司，有客情历史。代理对当地评标情况较为熟悉。\r\r\r\n2.截标时间紧急，无法开立保函，只能授权代理投标。\r\r\r\n', '', '1. 需要实验室制作样机\r\n2. 需要商务协助制作投标资料', '1.BFN市场电力公司自有资金紧急招投标。银河自己投标保函开立时间不足，授权代理投标，由代理开立保函。2.标书规格与MAA（原BFC规格一样）：CDN的技术规格+ TTA的尺寸，需要澄清。3.需要样机，时间较急。资料和样机可参考MAA项目。', '张柳芳2019-09-09 18:34:28', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('357', '{4A4B96B3-0F16-42BE-86B2-D1E7F3794D75}', '61', 'INHE-0381', '2019-09-09 18:35:13', '0000-00-00 00:00:00', '2019-09-11 16:24:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090906/MAH', '', '038/2019', '2019.09.20', 'Pour la fourniture de materiel de distribution pour la phase pilote du projet de developpement des conexions a l\'electricite (PDCEL) de la SONABEL  SONABEL关于电力接线发展的试点配电设备采购', '电力公司支付，付款方式：20%预付款+80%货到付款\r\r\n\r\r\n授权代理投标，银河与代理SGE之间的结算方式为：20%预付+80%远期信用证', '{4A4B96B30F1642BE86B2D1E7F3794D758442F4C2B3234363A3D51C033076BD50}_MAH 技术规格- 《与MAA一样》.docx', '1.	在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。\r\n2.	接下来评技术部分，技术资料是否满足标书的技术规格 。\r\n3.	评财务部分。评完财务文件，价格最低者中标\r\n', '', '在技术评估满足的投标商中，报价最低者将中标', '', '代理开立保函', '', '代理投标', '', '1.商务组提供投标资料：可参考MAA项目资料，需要补充CT表的技术资料。希望9.16号可以完成。17号寄出。\r\n2实验室提供样机：可参考MAA的样机，需要补充CT表样机。希望9月16号可以完成。', '', '代理商投标', '', '\"技术评标由电力公司执行。技术评标后进行商务评审。业主的影响力仅在技术评标部分。\r\n\"						\r\n', '', '', '', '', '', '\"老客户：Azon\r\n内部关系：前总经理退休，现剩余DCC，该项目的决策权在DCC能力之外。新总经的关系情况不明。以往评标组成员有一定关系。\r\n\"						\r\n', '', '主要客户关系在于实验室，软件部及电力公司个别总监，目前招标委员会高层未涉及。', '', '\"对手：海兴，科陆\r\n对手合作伙伴：电力公司内线和当地代理\r\n海兴中标BFN06,8万台电表。\r\n科陆代理是当地基建承包商，刚刚中标农电项目（内含电表）\"', '', '1.我们有多次历史中标，有4套系统在电力公司内部，了解市场和电力公司，有客情历史。代理对当地评标情况较为熟悉。张子琦在现场已经经营了一定的客户关系。\r\r\n2.截标时间紧急，无法开立保函，只能授权代理投标。\r\r\n', '', '1. 需要实验室制作样机\r\n2. 需要商务协助制作投标资料', '1.BFN市场电力公司自有资金紧急招投标。9月6号才发出标书。银河自己投标保函开立时间不足，授权代理投标，由代理开立保函。2.此项目是BFN市场的人人接线项目，标书规格与MAA、MAF（原BFC规格一样）：CDN的技术规格+TTA的尺寸，需要澄清。3.需要样机，时间较急。资料和样机可参考MAA项目。 ', '张柳芳2019-09-10 11:10:07', '03', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('358', '{E43D2B7B-8CAE-412A-8C34-D415F4AC67E4}', '66', 'INHE-0634', '2019-09-12 18:13:02', '0000-00-00 00:00:00', '2019-09-16 17:54:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091201/GTM', '', 'N° AO 97 168 - E', '2019年10月11日', 'DOSSIER D’APPEL D’OFFRES OUVERT INTERNATIONALN° AO 97 168 - EOBJET: Fourniture de Compteurs pour travaux de basculement des compteurs conventionnels en compteurs prépaiement', '【付款条件】：电力局给出的付款条件是赊销50个月账期，现代理财团的CEO正在与各家银行谈判争取融资，目前已经有了可能可行的方案，因此代理提出要求银河开始准备投标工作，制作样机和投标文件等。融资计划能否成功将在中标通知发出前得到确认，如果融资计划不成功，代理担保可以运作废标。银河与代理之间的付款方式为：30%预付款+70%保兑不可撤销的即期信用证。【交期】：30天。（在做工作中，争取延长）', '', '技术通过以后的最低价中标', '', '未明确规定，通常是一家中标（总报价最低）', '', '代理开立投标保函168百万ARIARY本地币', '', '后续补充', '', '普通全套投标资料，无特殊要求，截标期前递交（正在运作延标1个月）', '', '银河授权代理投标', '', '电力局总经理是代理财团CEO的老朋友，家族关系往来密切；电表项目评标测试报告撰写人（无直接决策权，但有较大决策影响力）Heroique与代理关系熟络。补充：Heroique将在下周与代理来银河参加RMY项目的FAT验货，他明说了此次来访不去工厂，希望多在深圳吃喝游玩和购物。此人需要特别关照打点，巩固关系，可帮助我们GTM项目中有较为顺利的进展。', '', '', '', '电力局无付款能力，需获取银行资金支持。', '', '合作伙伴在此电力局屡屡中标，还帮助我们使用非常规手段中标RMY，实力不错。代理年轻精干有野心，做事效率高，配合度极好。', '', '与代理关系较好，与电力局关系需要通过项目执行进一步加深巩固，绑定三方关系。', '', '竞争对手主要是海兴、华为和中兴。', '', '【优势】：银河代理有能力运作融资，将不可行项目变为可行；银河代理能力较强，信息及时准确且可控局。【劣势】：技术门槛不高，方案需要注意成本控制，报价方案需要有竞争力。', '', '1.融资支持要到位；2. 样机和投标文件不可有严重偏差和瑕疵，尽量做好，减少人情债，提升代理对我司信任度，形成正向循环；3. 报价要注意竞争对手的报价水平，不可高于对手。', '建议立项，积极运作控局，争取成单。', '陈雁2019-09-12 20:01:03', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('359', '{7551ACC2-48CD-48E0-9223-C4E4E7F3D91E}', '61', 'INHE-0642', '2019-09-17 18:50:06', '0000-00-00 00:00:00', '2019-10-25 10:24:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091701/SRD', '', 'RFB No: Lot 4, WB EEU-UEAP /04/2019-2020', '2018年9月11日招标，10月28日当地时间下午2点截标', 'Supply of single phase Energy Meters (KWH Meters), 电能表供货项目', '海外供货：\r\r\n1. 预付款:合同签订后三十(30)天内支付合同金额的百分之二十，并在收到货物并以招标文件中提供的形式或买方可接受的另一种形式提交同等金额的索赔和银行保函后支付。\r\r\n2. 装运时:在提交GCC第12条规定的单据后，应通过电汇或以供应商为受益人的不可撤销信用证支付装运货物合同价格的70%。\r\r\n3. 最终验收:收到货物后，买方出具验收合格证明，并在收到货物后三十(30)天内支付合同价款的百分之十。最终验收合格证书将在收到临时验收合格证书后12个月发给供应商。\r\r\n\r\r\n部分本地币的付款方式：\r\r\n1. 预付款:合同签订后三十(30)天内支付合同金额的百分之二十，并在收到货物并以招标文件中提供的形式或买方可接受的另一种形式提交同等金额的索赔和银行保函后支付。\r\r\n2. 交货时:在收到货物后的三十(30)天内支付合同价格的百分之八十(80)，并在买方提出索赔后的三十(30)天内支付合同价格的百分之八十(80)，索赔要求须有买方出具的证明，证明货物已经交货，其他所有合同服务已经完成。最终验收合格证书将在收到临时验收合格证书后12个月发给供应商。\r\r\n', '{7551ACC248CD48E09223C4E4E7F3D91E8442F4C2B3234363A3D51C033076BD50}_Lot 4 (2019-2020) - Procurement of Energy Meters -September 2, 2019.doc', '先价格后技术						\r\n', '{7551ACC248CD48E09223C4E4E7F3D91E074E749A304748709C51373D9D483750}_表1：SRD投标项目信息归纳表.doc', '1个Lot', '', '投标保函\r\r\n1. 投标保函开立金额：USD 720,000 (United States Dollars Seven hundred Twenty Thousands)\r\r\n2. 投标保证金应由信誉良好的银行提供无条件的银行担保，并必须由埃塞俄比亚商业银行提供反担保，有效期在原投标有效期后28(28)天\r\r\n3. 投标有效期为自开标之日起90(90)天。投标保证金的有效期为投标有效期满后28天。\r\r\n\r\r\n履约保函\r\r\n1. 10%的投标总价，履约保函为无条件银行保函，由埃塞俄比亚商业银行进行反担保，并按合同价款的比例以合同支付货币计价。\r\r\n2. 履约保证金在交货完成后，以及为支付供应商在本合同项下的履约义务(包括保证义务)而临时接受的货物时，将降低至5%。', '', '财务能力：\r\r\n1. 由外部审计师出具的投标方最新资产负债表的正式核证副本应附在投标书后面\r\r\n2. 至少在过去五(5)年内提交经审计的资产负债表或(如投标人所在国法律没有要求)买方可接受的其他财务报表，以证明投标人当前财务状况的稳健及其预期的长期盈利能力。\r\r\n3.投标人的年平均最低成交额必须是投标价格的1.5倍，计算方法为过去5年(5年)内收到的已核证付款总额。\r\r\n4. 投标人的最低资产(总资产，减去总负债)必须与投标价格或(The Bidder must have a minimum worth (total assets, less total liabilities) of equivalent to the bid price or)\r\r\n5. 投标人必须证明，其拥有或拥有足够的流动资产、未支配的实物资产、信贷额度和其他财务手段，以满足预计的四(4)个月的供应现金流，扣除投标人对其他合同的承诺。\r\r\n\r\r\n技术和经验：\r\r\n1. 投标人应已作为类似拟议货物和相关服务的制造商开展业务。相似性应基于物理尺寸、复杂性、方法/技术或第四节投标表格中描述的其他特征。\r\r\n2. 投标', '', '技术资料需要客服协助评估', '', '银河投标', '', '国企，政府直接控制走向						\r\n', '', '最晚提交商业发票后的60天内付款\r\n', '', '世行资助项目，付款无障碍\r\n', '', '合作伙伴Rayman PLC, 该公司和我司在埃塞有建厂业务，本身也和EEU建立的较为深远的联系						\r\n', '', '一线客户关系一般，主要依靠RAYMAN PLC进行运作，业务会尽快前往一线协助代理运作\r\n', '', '此埃塞项目主要竞争对手还是中国厂家\r\n', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 推动代理同步运作客户关系，同时把控评标团队，实施竞标策略\r\n3. 获取招标预算以及历史报价，报出合适价格\r\n', '', '项目成功的关键位：低价竞争，客户关系把控', '1.该项目为单相后付费简单表的供货项目（电表要求IP54,端子排IP33；RS232或者USB口，红外口，LED屏幕，锂电池等比较简单的参数），保函开立需要本地银行反担保，保函金额较高（USD 720,000.00）。之前项目海兴中标的价格较低（上次中标\r的价格为6.4美金每台）。2. 需要立即开始技术和商务的解析，同时业务将第一时间前往埃塞与客户一起进行项目运作。\r\r\r\r\r\r\r\r\r\n3. 该项目有15%价格优惠的本地保护政策（A margin of domestic preference : 15% (fifteen percent)，本地优惠15%），需要风控同事评估下JV合作的可行性。', '潘正豪2019-09-18 19:04:42', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('360', '{63ACC4F8-782C-A97F-F212-5ED3B866B0DB}', '61', 'INHE-0500', '2019-09-18 04:14:04', '0000-00-00 00:00:00', '2019-09-19 14:24:16', 'unchecked', 'n', 'n', '', '1', 'CPM', '', '', '', '2355G', 'Supply and Delivery of Bulk Metering Units\n\n供应 地缆线安装式11kV中压组合计量装置（含电压和电流组合互感器、SF6断路器、RMU环网柜和相关组件以及配件）', '', '价格条款：DDP市政公司仓库 不含VAT。银河与NYC之间FOB或CIF成交；付款主体：City Power；付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后30天内供应商提供付款发票，市政在收到付款证明后30天内支付。银河与NYC结算方式待协商确定。交期、质保：按照南非政府CIDB标准合同规定质保，一般为自交付日起24个月，正式PO下达后不晚于10周内交付。						\n\n\n\n\n\n						\n\n\n\n\n\n', '{63ACC4F8782CA97FF2125ED3B866B0DB074E749A304748709C51373D9D483750}_2355G - SUPPLY AND DELIVERY OF BULK METERING UNITS - TENDER DOCUMENT.pdf', '第一阶段：基础门槛资料评审，主要以市政常规要求提供的公司资质、财务资质、政府文件资质等；\n第二阶段：技术性评审，按照标书所列技术规格要求，需最低满足80%技术门槛要求；\n第三阶段：BBBEE资质评审。', '', '三家供应商分标，根据最终技术评分和BBBEE资质确定分配比例', '', '无需开立投标保函，执行合同阶段需要开立履约保函，由代理NYC负责', '', '1.厂商提供ISO9001和ISO14001证书；\n\n\n\n2.过去三年的审计财务报告；\n\n\n\n3.南非本地CIDB Registration particulars资质证书；\n\n\n4.一定数量的供货证明；\n\n\n5.技术资质证书要求较多：\n\n基于SANS standard 1029的形式测试报告\n\n基于SANS standard 1874的环网柜形式测试报告和工厂测试报告\n\n基于NRS 030的电压互感器测试报告\n\nAF-BFLR测试报告', '', '1.需要商务组同事主导协助投标文件整理、相关技术资料翻译和最终投标资料编译、打印和发送到现场；2.需要配电同事协助技术解析和相关技术应答表、资质证书提供；', '代理NYC投标，银河授标并提供相关技术资料', 'N/A', '', '市政公司组织内部评标委员会（2个来自电力部门，1个来自采购，1个来自财务部门），评标委员会通过预中标名单，最终决定权根据当权政治党派的利益进行确认，市政公司内部的技术评审一般仅作为推荐参考，最终授标决定权在于政党利益代表市政CEO和CFO。\n\n						\n\n						\n\n', '', '交货后由电力公司项目负责工程师验收，发布验收合格证后30天内供应商提供付款发票，市政在收到付款证明后30天内支付\n						\n', '', '8大市政之一，处于全国经济中心，市政公司财务能力雄厚。详情可见市政2018年财务报表', '', '1.代理NYC BBBEE资质占最终评标10分偏好优势；                            2.代理和市政公司CEO关系良好，多次会见有意向协助NYC；\n\n\n\n3.NYC管理经营目标明确，策略清晰且执行力相对效率较高，和银河的发展战略和市政竞争策略相符。\n\n\n\n						\n\n\n\n', '', '代理和市政公司CEO关系良好，多次会见有意向协助NYC；代理在财务部层面有利益合伙人可以中高层政治推动项目的进展。银河和NYC在技术部门暂无客户关系，需要拓展；市政公司对NYC和银河的公司和产品熟悉程度较低。						\n\n\n\n\n						\n\n\n\n\n', '', 'Actom：市政公司老牌主要供应商，本地有工厂，公司规模大，市场占有率高，品牌知名度高，市政公司内部中高层关系牢靠，产品价格具有竞争力；\n\nPMT：市政公司老牌主要供应商，本地有工厂，公司规模大，市场占有率高，品牌知名度高，市政公司内部中高层关系牢靠，产品价格具有竞争力；\nABB SA：知名厂商，本地无工厂，产品信任度高，有较强的的本地合作代理，价格最高。', '', '优势：NYC和市政公司CEO的客户关系，毕竟大都市市政公司最终评比需要依靠强大的政治实力；财务部长的中间游说人关系，一定程度上可以拉拢更改层此的政治靠山；NYC的BBBEE资质有助于最终评审优势；价格控制到合理报价具有竞争力。\n\n\n劣势：第一次投标市政该类型产品，对市场的价格和营销策略有待进一步了解；暂无全套本地产品资质，需要找替代认证资质。', '1.尽快完成技术解析和投标资料准备，资质方面需要想办法找到替代资质；\n\n\n\n\n\n2.推动和NYC和市政CEO的游说，支持NYC成为三个供应商之一；\n\n\n\n\n\n3.推动财长中间人的政治关系推动。								\n\n\n\n\n\n', '李忠鹏2019-09-18 15:55:50', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('361', '{58B7B43B-73EF-4965-B00D-18B70DC79B7C}', '61', 'INHE-0500', '2019-09-19 02:45:30', '0000-00-00 00:00:00', '2019-09-20 16:31:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091901/CPJ', '', '2351 G', '2019年10月17日 GMT+2 11AM', 'REQUEST FOR BID FOR SUPPLY, DELIVERY AND OFF-LOADING OF SINGLE & THREE PHASE PRE-PAID METERS关于单相和三相预付费电表的公开招标', '价格条款：DDP市政公司仓库 不含VAT。                               银河与NYC之间FOB或CIF成交；                                      付款主体：City Power；                                            付款条件：交货后由电力公司项目负责工程师验收，发布验收合格证后30天内供应商提供付款发票，市政在收到付款证明后30天内支付。银河与NYC结算方式待协商确定。交期、质保：按照南非政府标准合同规定质保，一般为自交付日起24个月，正式PO下达后不晚于8周内交付				\r\r\r\r\r\r\r\r\r\r\r\r\n', '', '评标门槛：1.满足本地生产70%以及第三方机构认证；2.提供满足标书技术规格的完整技术应答表，并100%满足；3.至少满足75%的标书提供的评分表。\r\r\r\n\r\r\r\n无实质性不符。', '', '无明确几家中标，按照历史市政公司类似项目中标经验，一般2到3家分标。\r\n', '', '无需开立投标保函，执行合同阶段需要开立履约保函，由代理NYC负责						\r\n', '', '1.BBBEE资质1-4级满足投标门槛；\r\n2.ISO9001和ISO140001资质（可以理解为厂商提供）；\r\n3.提供相关产品的STS证书；\r\n4.提供相关产品的形式测试报告，满足标书技术要求；', '', '1.此标需要提供的投标资料并不多，建议投标的整体进度把握由覃湘君主导，此标势在必得；\r\n2.客服部尽快完成技术解析，并开始样机制作以备后续急需样机。', '', '代理NYC投标，银河作为厂商支持', 'N/A', '市政公司组织内部评标委员会（2个来自电力部门，1个来自采购，1个来自财务部门），评标委员会通过预中标名单，最终决定权根据当权政治党派的利益进行确认，市政公司内部的技术评审一般仅作为推荐参考，最终授标决定权在于政党利益代表市政CEO和CFO。', '', '交货后由电力公司项目负责工程师验收，发布验收合格证后30天内供应商提供付款发票，市政在收到付款证明后30天内支付。', '', '8大市政之一，处于全国经济中心，市政公司财务能力雄厚。详情可见市政2018年财务报表						\r\n', '', '1.代理NYC BBBEE资质占最终评标10分偏好优势；               \r\r\r\r\n2.本地工厂有70%本地化生产资质文件；                               3.代理和市政公司CEO关系良好，多次会见有意向协助NYC；\r\r\r\r\r\r\r\r\n4.NYC管理经营目标明确，策略清晰且执行力相对效率较高，和银河的发展战略和市政竞争策略相符。\r', '', '代理和市政公司CEO关系良好，多次会见有意向协助NYC；代理在财务部层面有利益合伙人可以中高层政治推动项目的进展。银河和NYC在技术部门暂无客户关系，需要拓展；市政公司对NYC和银河的公司和产品熟悉程度较低。		', '', '兰吉尔：市政公司老牌供应商，供应了从普通居民代码表到LPU电表的全种类，产品品牌承认度高，在市政公司客户关系牢固；\r\r\r\n海兴：历史上依靠实力较强的代理替换了Iron供应超过15万台BS单相和三相模块表和集抄系统，但历史合作代理关系已改朝换代实力不如以前，本地工厂无法满足可以找到突破点；\r\r\nConlog：一直寻求机会供应商该市政公司，政治关系一般；\r\r\nElster：和市政公司的政党DA关系密切，合作的代理深得DA政党支持，但无本地工厂。', '', '优势：\r\r\r\r\r\r\r\r\n1.代理NYC BBBEE资质占最终评标10分偏好优势，本地妇女控制企业，在同等满足最终技术评审时可获得更大的份额；               \r\r\r\r\r\r\r\r\r\r\n2.代理NYC本地工厂有70%本地化生产资质文件；                               \r\r\r\n3.代理和市政公司CEO关系良好，多次会见有意向协助NYC；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n4.NYC管理经营目标明确，策略清晰且执行力相对效率较高，和银河的发展战略和市政竞争策略相符。\r\n\r\n劣势：\r\n1.技术部门客户关系薄弱，技术信息和测试进展需要先打通中层技术负责人；\r\n2.NYC在CEO的客户关系有待验证，是否真正可以如CDE市政CEO一样，保障NYC入围的机会，有待和NYC进一步验证。', '', '1.及早准确准备投标资料，要求在国庆放假前完成；\r\r\n2.提前准备投标样机，要求最晚在10月20日前完成两款样机准备后续急需样机；\r\r\n3.跟进NYC一起验证CEO的客户关系真假。', '1.此项目和NYC的沟通后是势在必得，至少需要分得50%的授标份额，及早准确准备投标资料，要求在国庆放假前完成；\r\r\r\r\n2.提前准备投标样机，要求最晚在10月20日前完成两款样机准备后续急需样机；\r\r\r\r\n3.跟进NYC一起验证CEO的客户关系真假。\r\r\r\n', '李忠鹏2019-09-19 03:26:52', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('362', '{6351546C-B997-4543-BCAF-04736E82130D}', '66', 'INHE-0774', '2019-09-19 10:48:04', '0000-00-00 00:00:00', '2019-09-20 16:30:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091902/BAL', '', 'PEA WB-RPP01/2019', '2019年10月2日 12:00 PM', 'Electricity Sector Performance ImprovementProject (ESPIP)电力部门绩效改善项目', '价格条款：CIP\r\r\n付款主体：代理\r\r\n付款条件：电力公司付款方式：\r\n（1）10%预付款在合同签订后30天内支付；（2）70%通过不可撤销的保兑信用证在提交货运单据的时候支付；（3）20% 在客户验收后30天内支付\r\r\n质保：2年\r\r\n交期：90天\r\r\n代理对银河的付款方式：在谈中\r\r\n\r\r\n\r\r\n\r\r\n', '{6351546CB9974543BCAF04736E82130D8442F4C2B3234363A3D51C033076BD50}_RPP Bid Document final version .pdf', '', '', '一个LOT，一家中标，一家制造商只能授权一个投标人', '', '投标保函：150,000美元 有效期118天（从投标截止日算起）\r\r\n履约保函：合同金额10%\r\r\n\r\r\n', '', '财务：过去三年财报 流动比率>=1.0  负债比率<=0.90\r\r\n过去三年年平均营业额至少1500万美元；\r\n供货记录：过去5年的AMR/MDM软件实施和兼容经验\r\r\n证书：1. ISO-9001：2008#FE54`  2. CMMI, Capability Maturity Model Integration- Certificates level 3 (or similar) for software development and/or services\r\r\n\r\n\r\n', '', '', '', '代理商投标', '', '', '', '（1）10%预付款在合同签订后30天内支付；（2）70%通过不可撤销的保兑信用证在提交货运单据的时候支付；（3）20% 在客户验收后30天内支付\r\r\n\r\r\n\r\r\n\r\r\n\r\r\n						\r\r\n', '', '世行融资项目，融资金额：1400万美元', '', '代理是约旦拥有30多年经验的集成商和通讯服务/设备提供商，在约旦，沙特，阿曼，卡塔尔有分公司，是诺基亚在巴勒斯坦的分销商，有一定的资源和经济实力。', '', '', '', '主要竞争对手是霍尼韦尔，在当地有多年预付费电表供货经验，且价格有竞争力', '', '优势：标书技术规格参照了银河的预付费电表编写，放了银河模块表图片作为参考；\r\n劣势：准备时间太短\r\n\r\n', '', '合适的方案和有竞争力的价格', '代理开保函，代理投标，银河做供应商。争取投标', '何森华2019-09-19 13:47:23', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('363', '{EB8C01A5-6A2A-4045-9F9F-52D9FEC51141}', '61', 'INHE-0721', '2019-09-19 10:44:00', '0000-00-00 00:00:00', '2019-09-27 09:57:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091903/ECA', '', 'No. 41300719C1', '2019.10.1', 'SERVICIO LLAVE EN MANO PARA CONSTRUCCIóN DE PROYECTOS DE ASEGURAMIENTO DE LA RED, SUMINISTRO DEL SISTEMA DE MEDIDA AMI, INSTALACIóN Y OPERACIóN POR 6 MESES 建设电网保障交钥匙项目，提供AMI测量系统，安装和运维', '授权代理投标', '', '符合投标资质审查，商务文件及技术文件完整合格，低价方案中标', '', '标书允许两家中标，电力公司倾向一家中标', '', '投标保函：报价10%（代理开立）', '', '1.供货记录：提供安装超过100万智能电表证书2.兼容证明：至少兼容过三个其他品牌的电表', '', '商务组协助配合制作、提供商务文件（厂商资质文件，供货记录及其他标书中要求商务的资料）；技术支持协助提供该项目投标所需技术文件（完成技术解析、推荐表型，技术应答表，提供认证证书、报告等标书中要求的技术资料，如图纸等）						\r\r\n', '', '代理和本地工程承包商JV投标', '', '					\r\n招标方拥有绝对的采购决策权						\r\r\n', '', 'ECA电力公司签订商业信托合同，供货：按月进度结算承包商；系统安装及运维服务：提交满意服务，即付款，付款期限最长为三十（30）个日历日，自提交和接受发票之日起计算。\r\r\r\n', '', 'ECA电力公司信誉较好，支付能力中等，但此项目已获得当地公共财政部门的担保的商业信托。', '', '此次授权的是PSA市场的代理投标，代理商与银河合作多年，在该电力公司有一定的商务关系，与该电力公司保持良好的关系，获取信息及时有效。						\r\r\n', '', '代理依托当地与ECA有项目合作的商业合作伙伴，与该电力公司取得一定的客户关系。', '', '目前该市场主要的竞争对手有海兴，西门子（威胜），Honeywell（Huawei）,elester等.					\r\r\n', '', '优势：针对欧美老牌厂商，价格上有优势；针对中国厂家，我司拥有电表、通讯（模块），系统一体化的产品及服务及良好的供货记录；代理在电力公司有一定的商务关系. 劣势：美洲EPC工程投标经验缺乏，门门道道还需要去挖掘；加强本地技术服务', '', '投标商务及技术文件准确、精致、报价有竞争力。 需要商务组及技术部门提供相应支持，协助完成投标资料的制作以及样机制作，顺利参与投标。', '此次招标为EPC工程项目，数量不是很多，但该电力公司计划2020到2030间完成智能电表全范围覆盖，每年约有十万台智能电表的更换需求。项目潜力大，且在近几年有持续的产品及抄表和售电软件需求。业务建议公司给予相关支持，参与此次投标！\r\r\n', '胡云义2019-09-19 18:13:58', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('364', '{99BCEEB0-15F2-419F-BB76-58E2393EBB3E}', '61', 'INHE-0843', '2019-09-19 16:15:41', '0000-00-00 00:00:00', '2019-09-20 00:25:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091904/EXA			', '', 'BID2-RSND-EECS-AU-BI-002', '2019-10-28', 'PROVISIóN, INSTALACIóN E INTEGRACIóN DE MEDIDORES PARA REDUCCIóN DE PéRDIDAS NO TéCNICAS供应、安装和集成智能电表，以减少非技术损失', '代理投标，目前承诺会按照30%-50%预付款，尾款LC支付。', '', '价格优先，技术次之', '', '2个LOTS。标书未写明几家中标，代理会争取银河能够参与LOT2 IEC表。', '', '代理负责开立保函', '', '1. 公司年限：10年；\r\r\n2. 至少有一个电表项目成功运作1年以上；有3个以上在执行的合同；IEC供表数量40万台以上；在至少2个国家的至少5个电力公司运作过成果的AMI项目，AMI项目合同至少5个；\r\r\n3. 财务数据：具备此次项目预算50%以上的财力（此标总预算US$9.225.000,00），其中LOT1占40%，LOT2占10%。偿债能力指数:总资产/总负债> 1.00；负债指数:总负债/净资产<1.5\r\r\n', '', '/', '', '代理商投标', '/', '电力局直接决定中标结果', '', '1. 货物到港后支付50%；\r\n2. 产品安装调试完成后支付25%；\r\n3. 系统安装调试完成后支付10%；\r\n4. 培训结束后支付10%；\r\n5. 验收合格后支付5%\r\n', '', '资金来源：美洲发展银行（BID）', '', '代理在厄瓜多尔电力行业经营了20年，与电力局有密切的关系，内线靠谱已合作多年，帮助代理取得了多个采购项目中标。针对此次合作项目，代理已提供给我们多个竞争对手的重要内部资料。', '', '暂未与电力公司建立客情', '', '本次智能电表+系统招标的主要竞争对手为ITRON、Honeywell、兰吉尔等。目前除银河外，尚无其他中国厂家参投此标。', '', 'Strengths:\r\n*代理合作意愿强烈，在电力公司内部有合作多年且十分可靠的内线，可以帮助银河运作为只参投LOT2的IEC电表；\r\n*代理对竞投标项目运作有丰富经验，十几年来都是电力公司的稳定供应商，中标过多个项目（ANSI+IEC）\r\n\r\nWeaknesses: \r\n*我司目前没有两相表产品，需要研发做样机。\r\n*价格\r\n*当前银河暂时没有直接与电力公司建立客情\r\n\r\nOpportunities：\r\n* 本次招标是厄瓜多尔今年国内最大的AMI项目\r\n* 厄瓜多尔目前正在推广AMI智能电表，如火如荼，现在是进入厄瓜多尔智能电表市场的时机\r\n* 该市场的关系运作门槛低，具有运作机会和空间\r\n\r\nThreats：\r\n* 代理以往运作的项目都是简单表项目，智能电表和系统项目经验不足，是否能有效运作和控场有待考察；\r\n* 标书没有写明是否一家中标，代理表示会说服电力局让银河能够只参投IEC的LOT；代理和电力局的关系有待考验\r\n* 当前没有现成两相表产品\r\n* 一线无业务人员控场\r\n\r\n策略：\r\n1. 考验代理能力：根据银河能够参投的产品，让他说服电力局两家中标\r\n2. 内部技术解析后，以AMI系统为优先产品，提供银河能够参投的最优方案\r\n3. 样机：样机数量还待确认；但研发需研究三相表改两相表的技术可行性方案\r\n4. 业务前往一线控场，检查代理实力同时发展其他代理，直接与电力局建立客情\r\n', '', '技术支持对产品规格进行解析；研发人员确认三相表改两相表的技术可行性方案', '现在厄瓜多尔正在向智能电表过渡，今后该国将大规模部署AMI方案，每年招标数量20-30万台，一般三年左右会有全国性的大型招标数量可达上百万，市场前景和未来订单量可观。代理在厄瓜多尔电力行业经营了20年，有丰富的竞投标经验，曾中标多个电力局设备/材料采购项目，在电力局有合作多年的靠谱的内线。银河可通过此项目在智能电表推行之初就进入厄瓜多尔市场。', '刘畑杏2019-09-19 16:22:14', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('365', '{22E4424A-1BCC-498D-8B9A-E9DD6582015E}', '61', 'INHE-0721', '2019-09-19 15:57:14', '0000-00-00 00:00:00', '2019-09-27 09:53:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091905/ACN', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'CODESAN被ENEL收购，在哥伦比亚属于比较大型的电力公司，用户数达到350万，且未来有较大的智能电表更换需求。此次试点订单中标，但根据ENEL的采购要求，CODENSA电力公司会对第一次供货商进行验厂检查（验厂费用电力公司自行承担），这将是银河成为ENEL供应商的一大起点。Enel电力公司在美洲地区许多大型电力公司都有控股，若银河能成为Enel认可的供应商，加上银河的优质的服务力度，这将成为后续订单的保证。交期45天，还望公司支持！', '胡云义2019-09-19 18:25:23', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('366', '{F65558CD-5FD6-445B-9B3D-564E1D729C87}', '61', 'INHE-0843', '2019-10-05 05:24:15', '0000-00-00 00:00:00', '2019-11-08 10:03:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2019100501/MIC', '', '', '', '', '价格条款：CIP Mexico City International Airport, Mexico. By air.\r\n付款条件：30%在签订合同10天内T/T支付，70%余款发货前5天内T/T支付\r\n交期：收到合同金额的30%T/T预付款后50天内完成生产\r\n质保：12个月\r\n', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 慧联确认模组频段及透传功能性能；\r\n2. 慧联进行现场技术支持，对产品进行完整的组网调试；\r\n3. 银河与慧联对RF集中器进行调试\"								\r\r\n', 'MX市场正在大力部署智能电网，但目前CFE电力局还没有确定全国性的通讯方案提供商。此次试点CFE将根据各个厂家的表现确认未来5-10年的RF通讯方案提供商；同时PROTECSA也在极力帮助银河及慧联推广产品，希望双方能够联手掌控MX的电表通讯市场。按目前情况来看，慧联的对手基本都是国际大牌，与这些品牌同台竞争，对于扩大慧联的品牌影响力是重要的机会，对于银河表计来说也具有战略性意义。', '刘畑杏2019-11-04 16:17:05', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('367', '{7221781B-BAB5-40A4-963F-69ADA9A61BB5}', '60', 'INHE-0560', '2019-10-08 14:52:34', '0000-00-00 00:00:00', '2019-10-09 17:30:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019100801/IFB', '', 'G-ICB-A-162-1；G-ICB-A-162-2', '2019.10.23(代理正在申请延标）', '第二能源部门项目:Second Energy Sector Project', '报价： CIP条款条件\r\r\r\r\r\n付款方式：20%预付款，30%发货支付，20%货物验收支付，30%系统验收支付\r\r\r\r\r\n交期：90天-120天', '', '评标流程：\r\r\n1）交期、声明对付款条件的接受、运营和质保声明\r\r\n2）技术评估：技术应答符合性，电表IEC测试报告， DLMS证书，厂家授权\r\r\n3）价格评审：低价中标\r\r\n4）后资格审查：财务指标、供货经验、团队人员资质\r\r\n\r\r\n', '', '中标规则：低价中标，上下浮动10%\r\n', '', '投标保函要求：\r\r\n1）标1投标保函：\r\r\n金额：USD72,000.00#FE54` 保函有效期：2019年10月23日+120天投标有效期+28天\r\r\n只接受银行保函；未提及直开转开#FE54` 标书中有保函文本；若是JV投标，保函需体现JV名称\r\r\n\r\r\n2）标2投标保函：\r\r\n金额：USD58,000#FE54` 保函有效期：2019年10月23日+120天投标有效期+28天\r\r\n只接受银行保函；未提及直开转开；标书中有保函文本；若是JV投标，保函需体现JV名称\r\r\n', '', '资质要求\r\r\n1）供货经验最大的不符点：\r\r\nA. 投标方在MDM系统实施合同中作为主承包商、分包商或管理承包商的角色，该项目在过去5年中至少有5个客户\r\r\n---满足5个；WZT01, CDN, ST20为SmartAMI系统，包含MDM系统，但合同中没有清晰写明MDM系统\r\r\nB. 投标方过去五年内，至少为5个客户供应过AMR和MDM系统\r\r\n---不满足5个；WZT01, CDN, ST20为SmartAMI系统，即AMR&MDM，其他市场的合同写的是SmartView\r\r\nC. 投标方在MDM和billing系统一体化合同下作为主承包商、分包商或管理承包商的经验，项目在过去5年中至少有5个客户\r\r\n---不满足。需寻找合作伙伴\r\r\n\r\r\n2）财务指标：总负债/总资产比例小于90%， 年平均营业额大于5百万美金，现金流大于1百万美金\r\r\n---满足；财务数据要求不高，国内厂商科陆、海兴也满足。\r\r\n3）人员经验满足\r\r\n4）证书要求：\r\r\nCMMI证书：暂时不满足，预计11月初完成认证，需跟催客服部加快进度。\r\r\n电表IEC测试报告：须由国际计量法制组织OIML，或亚太法定计量论', '', '需商务组协助准备投标文件，10月20日之前提供；若延标成功，则可相应推后。', '', '参与方式待定（目前有2家当地公司有合作意向，一家为BAT项目客户（答应申请延标，并邀请我司去当地电力公司演示并推广产品），另一家为新客户（10月10日抵达我司，将就此项目合作方式与我司展开谈判）', '就目前沟通的情况来看，考虑到JV投标在付款及保函开立格式方面的限制，双方暂未考虑联合投标的方式。拟采用授权代理投标或银河直接投标代理拿佣金的方式，具体细则，与客户进行谈判后可明晰。（视谈判情况，后续可能会更换合作代理）', '此标招标方为蒙古国能源部，政府拥有决策权。', '', '付款方式：20%预付款，30%发货支付，20%货物验收支付，30%系统验收支付\r\r\r', '', '招标方为蒙古国能源部，且已经拿到了世行的贷款，支付能力良好。', '', 'IFB项目客户成立于1994年，多年以来活跃在发电，工程，电力设备安装等领域，已成功运作60多个大型项目。在政府能源部门有其强劲内部关系，因此，该客户积极寻找合适的表计供应商，以寻求中标机会。', '', '蒙古国为新市场，与该客户为首次合作，初步接触来看，客户合作诚意及配合度较高。', '', '蒙古国市场的竞争对手主要有思达（2012年曾在当地供货并进行试点），但效果不太理想，因此后续该项目并未大范围在蒙古推广。                   正泰（在当地有成立分公司，主要供老式简单表，其主要重心还是断路器）及俄罗斯部分小厂家（以经销为主，其产品相对较为老式）。以上竞争对手，就目前了解到的信息来看，在蒙古，此类庞大的表计+系统类的项目不多，有较大的市场空间。', '', '竞争策略：价格具有竞争力+代理关系运作+产品可靠                     优势#FE54`                                                           A:对于此类表计+系统招投标项目我司经验丰富；                       B:产品优质可靠性高；                                             C:代理与政府关系紧密                                             劣势：                                                           A：我司部分资质不符，如无CMMI证书，暂时不满足，预计11月初完成认证   B： 投标方过去五年内，至少为5个客户供应过AMR和MDM系统\r\r\r\r\r\r\r\r\n---不满足5个；WZT01, CDN, ST20为SmartAMI系统，即AMR&MDM，其他市场的合同写的是SmartView\r\r\r\r\r\r\r\r\nC.投标方在MDM和billing系统一体化合同下作为主承包商、分包商或管理承包商的经验，项目在过去5年中至少有5个客户                           \r\r\r\r\r\r\r\r\n---不满足。需寻找合作伙伴', '', '关键：1.成功延标争取时间拿CMMI证书 2.价格具有竞争力 3.代理运作                                       支持：商务支持+研发按时提供样机', '建议立项', '李美娇2019-10-08 17:30:40', '03', '★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('368', '{CDC8C411-D888-4428-82A9-B7B58F76EABB}', '60', 'INHE-0560', '2019-10-15 16:01:26', '0000-00-00 00:00:00', '2019-10-15 16:01:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019100801/IFB（2个标）-新', '', 'G-ICB-A-162-1；G-ICB-A-162-2', '2019.10.23(代理正在申请延标）', '第二能源部门项目:Second Energy Sector Project', '报价： CIP条款条件\r\n付款方式：20%预付款，30%发货支付，20%货物验收支付，30%系统验收支付\r\n交期：90天-120天', '', '评标流程：\r\n1）交期、声明对付款条件的接受、运营和质保声明\r\n2）技术评估：技术应答符合性，电表IEC测试报告， DLMS证书，厂家授权\r\n3）价格评审：低价中标\r\n4）后资格审查：财务指标、供货经验、团队人员资质\r\n\r\n', '', '中标规则：低价中标，上下浮动10%\r\n', '', '投标保函要求：\r\n1）标1投标保函：\r\n金额：USD72,000.00#FE54` 保函有效期：2019年10月23日+120天投标有效期+28天\r\n只接受银行保函；未提及直开转开#FE54` 标书中有保函文本；若是JV投标，保函需体现JV名称\r\n\r\n2）标2投标保函：\r\n金额：USD58,000#FE54` 保函有效期：2019年10月23日+120天投标有效期+28天\r\n只接受银行保函；未提及直开转开；标书中有保函文本；若是JV投标，保函需体现JV名称\r\n', '', '资质要求\r\n1）供货经验最大的不符点：\r\nA. 投标方在MDM系统实施合同中作为主承包商、分包商或管理承包商的角色，该项目在过去5年中至少有5个客户\r\n---满足5个；WZT01, CDN, ST20为SmartAMI系统，包含MDM系统，但合同中没有清晰写明MDM系统\r\nB. 投标方过去五年内，至少为5个客户供应过AMR和MDM系统\r\n---不满足5个；WZT01, CDN, ST20为SmartAMI系统，即AMR&MDM，其他市场的合同写的是SmartView\r\nC. 投标方在MDM和billing系统一体化合同下作为主承包商、分包商或管理承包商的经验，项目在过去5年中至少有5个客户\r\n---不满足。需寻找合作伙伴\r\n\r\n2）财务指标：总负债/总资产比例小于90%， 年平均营业额大于5百万美金，现金流大于1百万美金\r\n---满足；财务数据要求不高，国内厂商科陆、海兴也满足。\r\n3）人员经验满足\r\n4）证书要求：\r\nCMMI证书：暂时不满足，预计11月初完成认证，需跟催客服部加快进度。\r\n电表IEC测试报告：须由国际计量法制组织OIML，或亚太法定计量论', '', '需商务组协助准备投标文件，10月20日之前提供；若延标成功，则可相应推后。', '', '从与两个代理目前沟通的情况来看，其资质都不完全符合招标要求的投标资质，但代理可以在当地协助运作此项目。因此将由银河直接作为投标人参与投标，与两个代理的具体合作模式根据后续谈判及合作协议确定。', '银河直接作为投标人参与投标', '此标招标方为蒙古国能源部，政府拥有决策权。', '', '付款方式：20%预付款，30%发货支付，20%货物验收支付，30%系统验收支付', '', '招标方为蒙古国能源部，且已经拿到了世行的贷款，支付能力良好。', '', 'IFB项目客户成立于1994年，多年以来活跃在发电，工程，电力设备安装等领域，已成功运作60多个大型项目。在政府能源部门有其强劲内部关系，因此，该客户积极寻找合适的表计供应商，以寻求中标机会。', '', '蒙古国为新市场，与该客户为首次合作，初步接触来看，客户合作诚意及配合度较高。', '', '蒙古国市场的竞争对手主要有思达（2012年曾在当地供货并进行试点），但效果不太理想，因此后续该项目并未大范围在蒙古推广。                   正泰（在当地有成立分公司，主要供老式简单表，其主要重心还是断路器）及俄罗斯部分小厂家（以经销为主，其产品相对较为老式）。以上竞争对手，就目前了解到的信息来看，在蒙古，此类庞大的表计+系统类的项目不多，有较大的市场空间。', '', '竞争策略：价格具有竞争力+代理关系运作+产品可靠                     优势#FE54`                                                           A:对于此类表计+系统招投标项目我司经验丰富；                       B:产品优质可靠性高；                                             C:代理与政府关系紧密                                             劣势：                                                           A：我司部分资质不符，如无CMMI证书，暂时不满足，预计11月初完成认证   B： 投标方过去五年内，至少为5个客户供应过AMR和MDM系统\r\n---不满足5个；WZT01, CDN, ST20为SmartAMI系统，即AMR&MDM，其他市场的合同写的是SmartView\r\nC.投标方在MDM和billing系统一体化合同下作为主承包商、分包商或管理承包商的经验，项目在过去5年中至少有5个客户                           \r\n---不满足。需寻找合作伙伴', '', '关键：1.成功延标争取时间拿CMMI证书 2.价格具有竞争力 3.代理运作                                       支持：商务支持+研发按时提供样机', '建议立项', '李美娇2019-10-15 16:25:21', '03', '★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('369', '{F75D5307-6A53-4CF2-9F20-9CD53A99C95B}', '75', 'INHE-0432', '2019-10-15 17:25:53', '0000-00-00 00:00:00', '2019-10-21 09:47:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019101501/KE04', '', '尚未发标', '尚未发标', '大用户计量箱项目供货', '1.价格条款：该项目将是本地工厂招标，价格条款：DDP含税；付款条件：交货至电力公司指定仓库且电力公司测试通过后，30天起提交付款资料，开始启动付款流程。\r\n2.付款主体：肯尼亚电力公司', '', '目前尚未发标，但一般是技术评审（样机+技术资料）、商务评审（供货记录等），综合评标，最低者中标。', '', '目前尚未发标。业务可以运作。', '', '目前尚未发标。', '', 'KE03项目中，要求大用户供货记录为15万台以上。', '', '', '', 'IAC直接投标。', '', '', '', '同PY02\\KF02\\KF03项目', '', '', '', '代理有较强客户关系。', '', '较好。', '', '1.最大竞争对手：海兴。其已控制大用户计量箱系统，且已供货约6000套。\r\n2.最大的难点在于：若银河中标，银河电表需要与海兴系统兼容。因为电力公司明确表示，不希望因为几百台，再重新使用另外1个大用户系统。\r\n3.银河CT表兼容海兴系统：一方面需要公司考虑、衡量，是否同意开放协议给海兴；另一方面，需要海兴方面配合。\r\n4.代理反馈：KE02项目中，与海兴一起分标的厂商IET，本来是与ABB合作采购计量箱的，但最终海兴不配合做系统兼容，最后ABB只能采购海兴的计量箱供货。', '', '策略：\r\r\n1.需要提前准备制样、做认证，获取投标资格。\r\r\n2.通过客户关系运作，与海兴分标。\r\r\n劣势：\r\r\n1.目前系统有海兴掌控，我们的电表产品需要与其系统兼容。\r\r\n2.本次项目数量、及未来需求数量有限，需要公司给与建议、评估。', '', '', '请公司综合评估是否参与此项目。', '谭东羊2019-10-15 18:06:18', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('370', '{8E869EAA-9DF2-4E49-9FA9-D7483AC5A61B}', '66', 'INHE-0634', '2019-10-16 08:54:52', '0000-00-00 00:00:00', '2019-10-21 09:45:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2019101601/HAS', '', 'SL-EDSA-130229-GO-RFB', '2019年11月18日（此日期为延期后）', 'Supply and Installation of Bulk Supply Metering and STS Split Prepayment Meters', '付款方式：CIP条款，预付10%，发货后45天付80%，完工后45天付5%，验收通过后45天付5%。（完整标书请见右侧附件）', '{8E869EAA9DF24E499FA9D7483AC5A61B8442F4C2B3234363A3D51C033076BD50}_RfB_Supply__Installation_of_Bulk_Metering__Prepayment_Meters_draft_Rev_WB (2).docx', '资质审核，投标文件和样品审核；通过上述审核的投标人中最低价者胜出。', '', '一家中标', '', '投标保函：9万美元，效期119+28天；履约保函为合同金额的10%。', '', '无不履约记录，资金状况良好（2015-2017年财报），过去3年内类似项目年销售总额达540万美元，过去5年内执行过至少2个类似项目（项目金额不少于360万美元）。', '', '详细技术方案，相关设计图纸，型式测试报告等。', '', '银河直接投标', '', '世界银行监督，评标过程相对公平。', '', '付款方式：CIP条款，预付10%，发货后45天付80%，完工后45天付5%，验收通过后45天付5%。						\r\n', '', '', '', '暂无合作代理。', '', 'SLE项目中，刘元豪曾经直接接触过一些来自电力局的相关负责人，将基于其基础继续建立关系，获取更多信息。', '', '主要竞争对手为科陆，已中标SLE项目。', '', '优势：1. 该项目有世界银行资金支持和全程监督，相对规范；2. 从SLE项目中了解到，银河报价和科陆报价差距微小，竞争力较高。如何做：该项目内容较为复杂，需要公司投入较多的精力和技术支持，在一个月时间内迅速反馈。', '', '1. 需要有EPC项目经验的技术人员与业务和商务全力配合，组成专业团队，快速完成投标方案和样机。2. 需要寻找合适的本地代理，协助获得及时的澄清沟通，并获取尽可能多的竞争局势信息，以供我们及时做出调整。', '建议立项，积极参与，争取中标。', '陈雁2019-10-16 10:55:21', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('373', '{2BE7EF58-B837-4AD0-B517-B0E283A4399B}', '61', 'INHE-0885', '2019-10-17 05:20:20', '0000-00-00 00:00:00', '2019-11-19 04:34:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019101701/BWU', '代理商不靠谱，屡次投标无下文。请提高立项命中率。', '3599/19', '2019 10/30', 'SUPPLY AND DELIVERY OF METERING UNITS AND ACCESSORIES计量单元和配件的供应和交付', '1. 此项目适用于博茨瓦纳政府公用事业单位付款条款：在货物抵达之后14天内全额付款。\r\n2.中标14天内签署合同', '{2BE7EF58B8374AD0B517B0E283A4399B8442F4C2B3234363A3D51C033076BD50}_BWU标书文件.pdf', '先评标商务和资质（有打分规则详见附件），再评技术标', '{2BE7EF58B8374AD0B517B0E283A4399B074E749A304748709C51373D9D483750}_BMU评标流程.pdf', '1个Lot', '', '电力公司没有要求', '', '(1)符合最低技术规格\r\r\n(2)过去5年至少有3份类似的合同，用户证明\r\r\n(3)投标者是民资企业\r\r\n(4)产品测试报告\r\r\n(5)产品概要图纸\r\r\n(6)权威机构的产品认证证明\r\r\n', '', '1. 用户证明文件\r\r\n2. 产品测试报告\r\r\n3. 产品概要图\r\r\n4. 权威机构的产品认证证明\r\r\n5. 厂家授权信', '', '代理商直接投标', '代理商直接投标', 'BPC是国企，政府决定其走向', '', '电力公司在货物抵达后的14天内全额付款', '', '电力公司财务状况良好', '', 'FACTORFAST METERING (PTY) LTD主营电力设备相关业务，在电力公司有一定的客户关系，熟悉博茨瓦纳招投标流程。\r\n', '', '一线客户关系一般，代理商有一定的客户关系', '', '主要竞争对手是一家南非的工厂（低价竞争）和中国工厂', '', '1.熟络标书，完整提交投标文件\r\n2.此先开商务标，后开技术标。通过商务标的结果，有针对性的在技术标上打击竞争对手。\r\n3.根据历史报价得出合适价格', '', '项目成功的关键：有针对性的对竞争对手进行打击，报适当的价格', '该项目为互感器项目，前期投入甚微。BPC电力公司评标时间沉长，如有消息业务可以第一时间前往博茨瓦纳市场于代理一起进行项目运作。', '潘健康2019-10-17 07:38:45', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('374', '{6CB53CA9-B0EA-47A2-AF28-A849EC13A1A9}', '61', 'INHE-0772', '2019-10-22 10:38:10', '0000-00-00 00:00:00', '2019-10-23 17:09:14', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102201/SLA', '', 'SL-EDSA-130229-GO-RFB', '2019-11-18', 'Supply and Installation of Bulk Supply Metering and STS Split Prepayment Meters', '1）产品部分：10%预付款（开立预付款保函后支付），提交发货资料后45天支付80%，完工证明后45天支付5%，验收证明后45天支付5%；\r\r\r\n2）设计部分：10%预付款（开立预付款保函后），90%验收后45天支付\r\r\r\n3）安装部分：10%预付款（开立预付款保函后，可随安装工作减少而相应降低预付款保函金额），安装工作量的80%将在下个月支付（提交申请及相关文件后45天内），完工证明后45天支付5%，验收证明后支付5%；\r', '', '资质审核，投标文件和样品审核；通过上述审核的投标人中最低价者胜出。', '', '1家中标', '', '投标保函：9万美元，效期119+28天；预付款保函和履约保函为合同金额的10%。\r\n', '', '无不履约记录，资金状况良好（2015-2017年财报），过去3年内类似项目年销售总额达540万美元，过去5年内执行过至少2个类似项目（项目金额不少于360万美元）。', '', '标前勘探需要技术人员一同前往参加，以便做出合适要求的技术方案，工程量单，项目电表安装和AMI安装实施执行计划，相关设计图纸，型式测试报告等。', '', '银河投标 （联合体的资质要求高，代理不符合）', '', '电力公司作为业主负责项目评标', '', '3.供货付款方式：10%预付+80%发货后45天内凭单支付+5%凭完工证明45天内支付+5%凭运行验收证明45天内支付。设计费的付款方式为：10%预付+90%设计验收后45天内支付；安装部分的付款方式：10%预付 + 80%上月进度完成情况有业主证明45天支付 +5%月度完工证明45天支付 +5%月度运行验收证明45天内支付。', '', '支付能力强，项目资金非电力公司自身资金，是世界银行提供的无息远期贷款保证项目货款安全，付款流程由世界银行监督，不允许拖欠款项和挪用款项。\r\n', '', '合作伙伴在当地有一定EPC项目经验和人脉，能够协助找到合适分包商。\r\n', '', '目前没有电力公司层面的关系，此前有过SLE项目交涉，对银河不陌生，客情需要前往一线建立。\r\n', '', '科陆/海兴', '', '优势：1. 该项目有世界银行资金支持和全程监督，相对规范；2.从SLE项目中了解到电力公司层面事评标的核心，科陆当前订单未执行，各方势力未完全定局。还有机会。3.本次对财务资质和项目资质要求较高，可以淘汰多数小厂家避开价格竞争。如何做：该EPC项目内容较为复杂，需要公司投入较多的精力和技术支持，在一个月时间内迅速反馈。', '', '1. 需要有配电EPC项目经验的技术人员和商务全力配合，组成专业团队，快速完成投标方案和样机。2. 需要寻找合适的本地分包商，做出合理准确安装报价。3. 标前澄清会非常重要：现场勘探需银河电网公司技术协助以同前往。 4 保函及时开出', 'EPC项目产品方案报价都复杂，技术方案和报价准确是本次赢标关键，更是对银河的EPC项目竞标考验，本项目的合同金额高达4千万美金，同时除了EPC项目经验和AMI项目经验外，财报情况均有较高要求，小厂家无法参与，不是价格战，利润好。加上SLE的报告分析，当地各大电表厂家的势力分散没有定局，我认为本项目值得争取。', '张子琦2019-10-22 11:00:39', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('375', '{28F828C3-3863-4DF7-8963-876F9A499518}', '61', 'INHE-0642', '2019-10-22 20:40:53', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', 'lxdj2019102202/SRS', '', 'RFB No: Lot 4, WB EEU-UEAP /04/2019-2020', '2019年8月20日招标，延标至11月14日当地时间下午2点截标', 'Supply of single phase Energy Meters (KWH Meters), 电能表供货项目', '海外供货：\r\n1. 预付款:合同签订后三十(30)天内支付合同金额的百分之二十，并在收到货物并以招标文件中提供的形式或买方可接受的另一种形式提交同等金额的索赔和银行保函后支付。\r\n2. 装运时:在提交GCC第12条规定的单据后，应通过电汇或以供应商为受益人的不可撤销信用证支付装运货物合同价格的70%。\r\n3. 最终验收:收到货物后，买方出具验收合格证明，并在收到货物后三十(30)天内支付合同价款的百分之十。最终验收合格证书将在收到临时验收合格证书后12个月发给供应商。\r\n\r\n部分本地币的付款方式：\r\n1. 预付款:合同签订后三十(30)天内支付合同金额的百分之二十，并在收到货物并以招标文件中提供的形式或买方可接受的另一种形式提交同等金额的索赔和银行保函后支付。\r\n2. 交货时:在收到货物后的三十(30)天内支付合同价格的百分之八十(80)，并在买方提出索赔后的三十(30)天内支付合同价格的百分之八十(80)，索赔要求须有买方出具的证明，证明货物已经交货，其他所有合同服务已经完成。最终验收合格证书将在收到临时验收合格证书后12个月发给供应商。						\r\r\n', '{28F828C338634DF78963876F9A4995188442F4C2B3234363A3D51C033076BD50}_Lot 4 (2019-2020) - Procurement of Energy Meters -September 2, 2019.doc', '先技术后价格						\r\r\n', '{28F828C338634DF78963876F9A499518074E749A304748709C51373D9D483750}_延标通知.jpg', '1个LOT', '', '投标保函\r\n1. 投标保函开立金额：已澄清为USD 150,000 (United States Dollars One hundred Fifity Thousand)\r\n2. 投标保证金应由信誉良好的银行提供无条件的银行担保，并必须由埃塞俄比亚商业银行提供反担保，有效期在原投标有效期后28(28)天\r\n3. 投标有效期为自开标之日起90(90)天。投标保证金的有效期为投标有效期满后28天。\r\n\r\n履约保函\r\n1. 10%的投标总价，履约保函为无条件银行保函，由埃塞俄比亚商业银行进行反担保，并按合同价款的比例以合同支付货币计价。\r\n2. 履约保证金在交货完成后，以及为支付供应商在本合同项下的履约义务(包括保证义务)而临时接受的货物时，将降低至5%。\r\n', '', '财务能力：\r\n1. 由外部审计师出具的投标方最新资产负债表的正式核证副本应附在投标书后面\r\n2. 至少在过去五(5)年内提交经审计的资产负债表或(如投标人所在国法律没有要求)买方可接受的其他财务报表，以证明投标人当前财务状况的稳健及其预期的长期盈利能力。\r\n3.投标人的年平均最低成交额必须是投标价格的1.5倍，计算方法为过去5年(5年)内收到的已核证付款总额。\r\n4. 投标人的最低资产(总资产，减去总负债)必须与投标价格或(The Bidder must have a minimum worth (total assets, less total liabilities) of equivalent to the bid price or)\r\n5. 投标人必须证明，其拥有或拥有足够的流动资产、未支配的实物资产、信贷额度和其他财务手段，以满足预计的四(4)个月的供应现金流，扣除投标人对其他合同的承诺。\r\n\r\n技术和经验：\r\n1. 投标人应已作为类似拟议货物和相关服务的制造商开展业务。相似性应基于物理尺寸、复杂性、方法/技术或第四节投标表格中描述的其他特征。\r\n2. 投标人应提供至少两(2', '', '技术资料需要客服协助评估', '', '建议银河投标', '国企，政府直接控制走向						\r\n', '最晚提交商业发票后的60天内付款						\r\n', '', '世行资助项目，付款无障碍', '', '世行资助项目，付款无障碍', '', '合作伙伴Rayman PLC, 该公司和我司在埃塞有建厂业务，本身也和EEU建立的较为深远的联系	\r\r\r\r\n', '', '此埃塞项目主要竞争对手还是中国厂家（海兴，许继仪表），且竞争对手主要采用低价竞争策略\r\r\r\n', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 推动代理同步运作客户关系，同时把控评标团队，实施竞标策略\r\n3. 获取竞争对手信息并结合历史报价，报出合适价格\r\n', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 推动代理同步运作客户关系，同时把控评标团队，实施竞标策略\r\n3. 获取竞争对手信息并结合历史报价，报出合适价格\r\r\n', '', '项目成功的关键位：低价竞争，客户关系把控\r\r\n						\r\n', '该项目为代码表的供货项目，历史价格较低（海兴中标的价格为6.4美金每台；许继仪表之前中标价格为DDP 8美金），如有需要，业务可以第一时间前往埃塞与客户一起进行项目运作。埃塞政府计划2025年内给1000万用户安装上电表，所以埃塞市场近年内代码表招标将会是主流，希望公司能够通过此次SRS项目为后续代码表项目打下基础，并同步推广智能表。\r\r\r\n', '潘正豪2019-10-22 21:04:06', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('376', '{DC0E0C9A-CA0C-48A8-B81E-DC0391EBB37A}', '66', 'JXINHE-2559', '2019-10-23 08:58:48', '0000-00-00 00:00:00', '2019-10-23 17:02:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102301/PCN', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '项目为私人直采项目,对产品无特殊技术要求,采用我司已有参数.项目历经三年,终于落地,因巴基斯坦国家外汇管制,客户同以100%即期信用证支付电表和CIU部分的货款,以100%TT预付的方式支付软件部分的货款.恳请领导批准以成单.', '淦永妍2019-10-23 09:09:19', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('377', '{A4974C44-FF87-41CA-8AD1-2CDE39D22630}', '61', 'INHE-0744', '2019-10-23 17:14:59', '0000-00-00 00:00:00', '2019-10-25 10:17:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102303/GNH', '', '02/AOI/CLSG/EDG/2019', '当地时间2019年11月25日上午10时', 'Fourniture de compteurs à prépaiement采购预付费电表', '几内亚电力公司Electricité de Guinée (EDG)获得非洲发展基金 (FAD)的捐赠，用于采购2000台预付费电表\r\r\r\r\n付款条件：20%的预付款（由银行100%做出担保，有效期截至交货日），在收到FOB的全套单证时付60%，拿到临时验收证明后的30天内付15%，完成最终验收时付最后的5%（临时验收时，若出具同等金额的保函，可直接支付该5%）\r\r\r\r\n交期：自合同生效之日起6个月，贸易术语为CIP（项目目的地Conakry交货），\r\r\r\r\n质保期：12个月\r\r\r\r\n若未能在规定时间内完成所有服务，则需每天支付千分之二的延期罚款，该罚款的上限为合同金额的5%\r\r\r\r\n', '{A4974C44FF8741CA8AD12CDE39D226308442F4C2B3234363A3D51C033076BD50}_GNH标书.doc', '必须遵守非洲发展银行的采购规则', '', '独家中标，一家制造商仅能授权一个投标人', '', '投标保函：递交投标文件时，也应附上金额相当于4500欧元的投标保函\r\n履约保函：为银行保函，金额为合同金额的10%，采购方应在供货方履行完所有义务后的28天内返还履约保函\r\n', '', '最近5年的财报\r\n最近5年的年平均营业额不得低于31.5万欧元\r\n融资能力（包括现金流，不动产，信用额度）\r\n最近5年内至少已经在2个体量、复杂程度、技术及其他层面与此次项目类似的市场供货，令客户满意，且每个市场的供货金额不得低于17万欧元\r\n', '', '制造商授权书、样机、报价单、电表及表箱技术规格', '', '代理商投标', '', '', '', '20%的预付款（由银行100%做出担保，有效期截至交货日），在收到FOB的全套单证时付60%，拿到临时验收证明后的30天内付15%，完成最终验收时付最后的5%（临时验收时，若出具同等金额的保函，可直接支付该5%）\r\n', '', '非洲发展银行支付', '', '合作伙伴是公司在西非法语区多年的代理，多次成功中标有关项目，具备较强的实力', '', '银河与客户基本没有直接关系，都是通过代理进行接触', '', 'GN市场中，其熟悉的主要竞争对手都在参与该项目的投标：海兴、科陆、思达、威胜等', '', '根据非发行的采购规则，在符合技术标书的前提下，低价中标。所以，在该项目中，公司应该采用具有成本优势的产品参与投标，同时重视样机的制造，做到样机完全符合标书要求。同时积极与客户进行技术交流，争取影响客户的样机测试流程。', '', '', '该项目虽然睡觉较少，但是后续在该市场会有非发行及法国开发署的大量项目，可以通过该项目做一些积累。同时，由于该市场之前以前都是由代理主导一切，银河自己并没有直接接触电力公司，导致银河处处受制于代理，甚至连部分信息的真伪都无法识别。银河的业务可以通过该项目机会能够直接接触电力公司，不仅仅可以直接参与该项目的竞投，还能跟踪公司在该市场前面的项目GNC、GND、GNE和GNF', '郑超波2019-10-23 18:31:12', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('378', '{640BDF94-67C2-4586-AFFA-358B8502771C}', '60', 'INHE-0680', '2019-10-24 00:50:08', '0000-00-00 00:00:00', '2019-10-28 17:32:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102401/TAK', '', '', '', '', '20%预付款，发货后有6个月宽限期，剩下的80%在7-18个月付清，没有利率或没有银行利息，而且也没有信用证。\r\r\n关于付款条款：\r\n这是一个重要因数，但不是必要满足的条件。因为这个付款条件是目前他们收到海兴、三星、思达提供的最优的付款条件，他们最终选择哪家合作还会考虑其他因素。总承包商比较强势,实力强大，并且已有海兴、三星、思达等供应商候选人。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '采购自己来自欧洲复兴银行', '', '总承包商是当地比较有实力的公司，总承包商情况介绍：\r\r\n在年轻的塔吉克斯坦的能源发展历史中，占据了举足轻重的地位，因为在当时的塔吉克装配部门水电蒙太奇的工程师和工人的帮助下竖立了大型项目，现在已成为塔吉克市场能源设施建设的领先公司。 公司技术和人员的潜力不仅可以在能源领域，而且可以在其他行业中实施任何复杂的项目。\r\r\n\r\r\n业务模块：\r\r\n1.EPC工程：包含电气设备的设计，完工，交付，安装和调试等全方位工作。\r\r\n2.建筑工程：包含水电站，工业园，大厦，管道，灌溉等等。\r\r\n3.工程设计：具有自己的设计院，包含工业，电力，社会和行政设施的建筑行业的综合设计和各种调查；具有研究，设计，计算和分析性质的工程工作的完整清单；\r\r\n项目可行性研究；开发设计和估算文件等等。\r\r\n4.物流运输：可以接运输货物重量最重达到250吨的订单。\r\r\n\r\r\n成功执行的典型项目：\r\r\n1.Nurek水电站，Sangtuda水电站1，HYATT REGENCY HOTEL和SOZIDANIE商业中心，ZARNISOR矿场 ，杜尚别国际机场#FE54`\r\r\n2.Vakhdat变电站 110 / 10kV，国家图', '', '不认识', '', '海兴、三星、思达', '', '塔吉克斯坦的项目，采购产品和数量约为（20万台表（后付费）、包含单三相，集中器，断路器，表箱，电流互感器，系统等等），已经联系上当地的合作伙伴（总承包商），目前正在对接，他们从10间表厂里面选供应商，目前已经否掉了7间供应商，剩下3间（海兴、三星、思达），这3家的表和集中器PLC-G3 办的都是FCC频段的，我们的也是办的FCC。\r\r\r\r\n\r\r\r\r\n\r\r\n\r\r\r\r\n目前对方已经同意接受我们进入候选供应商申请，对方要求填写附件表格，并附上相关证明文件，对方要求我们尽快提交申请，因为对方预计在11月初选定合作供应商。如果申请通过后，对方会发采购产品和数量明细向我们申请报价。\r\r\r\r\n', '{640BDF9467C24586AFFA358B8502771CB79221563C224206B274FD7CD6B16366}_服务器和硬件技术要求.zip', '分析采购产品技术要求，确认投标产品', '', '陈嘉豪2019-10-24 01:07:50', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('379', '{F60D8F1E-E5AC-4E54-893A-A85E91197F44}', '60', 'INHE-0781', '2019-11-04 03:47:03', '0000-00-00 00:00:00', '2019-11-07 10:37:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019110401/DSO', '', 'IFT 01/19', '2019.12.9', 'Supply and installation of smart pre-payment meters in DESCO area在DESCO区域供应和安装智能预付费电表', '一、价格条款（美元或当地币报价均可）\r\r\nFOB报价： 运输、保险、货物独立报价\r\r\nCIF报价：进入买方国家\r\r\n当地运输、保险、运输至终点的其他费用\r\r\n现场作业、安装费用，包括测试和服务费\r\r\n必要的零部件费用\r\r\n二、付款条件：国外供货\r\r\n1.10%预付款：合同签署后28天内，供货方同时需提供预付款保函。\r\r\n2.60%：货物装运后，通过供应商指定银行、不可撤销的L/C支付（仅指货物价格）\r\r\n3.20%： on installation and commissioning安装和开通至少25000台智能预付费表后，可以申请相应电表货值的20%金额；\r\r\n4.10% after final acceptance of successful installation and commissioning of 100% prepaid metering syste完全安装和开通预付费抄表系统并收到最终验收证明。\r\r\n孟加拉本国供货\r\r\n1.10%预付款，合同签署后28天内，供货方同时需提供预付款保函\r\r\n1.70%：收到货物，并开具货物验收证明后支付（仅指货物价格）\r\r\n2.20%', '{F60D8F1EE5AC4E54893AA85E91197F448442F4C2B3234363A3D51C033076BD50}_Payment term.rar', '先资格预审，招标方会至少提前30个日历日通知去做样品和抄表系统的演示，演示会作为技术评审的一部分技术评审，通过技术评审的投标人进入价格评审，开价格标，低价中标。', '', '1个Lot 1家中标', '', '\"一、投标保函\n1.金额：455,000 USD \n2.投标有效期150天+28天，即2019年5月24日\n3.是否转开：是\n3.待与DESCO确认是否由我司自行开立\n\n二、履约保函：合同价格的10%\"						\r\n', '{F60D8F1EE5AC4E54893AA85E91197F441DD410FC292E4E1893AFBEF9F88431CD}_tender security.rar', '1.	过去5年内最多3个合同合计供应/供应&安装单相预付费/智能预付费电表90,000台，三相预付费/智能预付费表10,000台；合同金额达到800万美元。2.	投标截止日倒推过去5年内至少有在2家电力公司（一家是投标者本国以外的公司）实施预付费电表/智能电表的供货经验。3.	投标人要证明可以满足供应30万台智能预付费电表的产能。4.	提交过去三年财务报表，要求净资产为正数。5.	过去3年内平均年营业额最少达到2000万美元。6.	1780万美元流动资产。', '', '待整理标书信息；截标日为2019.12.9\r\r\n', '', '联合投标', '代理主投，银河负责供货和技术支持，代理负责电表安装和维护，以及市场工作', '能源部对项目有决定性作用', '', '见上述付款条件', '', '', '', '合作代理与能源部以及电力公司有较好关系，有助于投标运作，进入技术及商务阶段。', '', '关系良好', '', '1.海兴\r\r\r\r\r\n2.杭州炬华及代理 Vicar  International.\r\r\r\r\r\n3.深圳思达及代理 Oculin Tech Bd. Ltd，后台是能源部长\r\r\r\r\r\n4.威盛及代理 Global Marketing  Services Bangladesh\r\r\r\r\r\n5.江苏林洋及代理ERA Construction Ejab Rabeya’s Heritage, Dhaka.\r\r\r\r\r\n6.许继\r\r\r\r\n7.宁波三星\r\r\r\r\n8.长城开发（深科技） ', '', '优势是我们是当地第一家大规模实施智能表项目的中国厂商，经验丰富；劣势是我们在DESCO没有真正做过项目，与电力公司的利益关系尚未建立，缺乏流畅的信息渠道，处于被动跟随状态。', '', '这边获得项目的关键仍在价格，另外这个要上集抄，从以往项目实施来看复杂程度增加很多，需要技术上提供足够支持。', '据了解，本次电力公司的采购意愿很强，项目应该会真正执行下去。而我们在DESCO一直没有项目，迫切需要实现零的突破，因此建议参加。', '李启坦2019-11-04 04:52:24', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('380', '{08317901-B77C-4008-8082-317AB8BAD028}', '60', 'INHE-0868', '2019-11-06 09:40:07', '0000-00-00 00:00:00', '2019-11-12 11:05:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2019110601/LDC', '', 'DD3/P*D/ICB/2019/048/D', '2019.12.4', 'SUPPLY AND DELIVERY OF DIRECT CONNECTED STATIC ENERGY METERS 5(40)A – CLASS 1 WITH MODEM 供应5（40）A，三相直通电表，带通讯模块，精度等级一级', '价格条款：FOB+海运费+清关运输\r\r\n付款主体：CEB.\r\r\n付款条款：1）CEB开立LC；\r\r\n          2）85%见货运单据支付；\r\r\n          3）15%在客户验收后支付；\r\r\n交期：LC后两个月内完成交货。\r\r\n质保：5years（from the date of FOB dispatch to the purchaser)，前两年免费更换，两年后质保期内免费维修或更换\r\r\n备注：L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。', '{08317901B77C40088082317AB8BAD0288442F4C2B3234363A3D51C033076BD50}_标书Eng-DD3-PnD-2019-048 Direct Connected Static  Energy Meters.pdf', '根据投标方企业性质及归属地，判定实际评标价格（见P8，11.2）\r\n', '', '通过技术标且价格最低的投标人中标。一家中标						\r\n', '', '投标保函：LKR 450,000，有效期至2020-4-1，银河授权代理提供；\r\n履约保函：10%合同额，必须供货方开，Sri Lanka银行开立或保兑，LOA14天内开立，最后批次发货后六十天有效\r\n', '', '1. ISO9001：2008或最新的质量保证认证，                            2.符合ISO/IEC：17025：2005的实验室认证                            3. 测试并提交测试报告（要求见技术部分11/21 Clause6.3）             4. 10年生产经验证明，近七年供货记录（技术部分11/21，Clause6.2）.    5. Ofgem certification or other equivalent certification issued by an independent electricity regdlating institution certifying a minimum service life shall be provided with the offer. (标书技术部分13/21，Clause8.1）                                         6.10KV绝缘耐压测试报告 \r\r\n', '', '购买标书和投标保函的授权文件（power of attorney)，11月27号提供；    10KV绝缘耐压测试报告 最迟11月27号提交。', '', '银河投标', '', 'CEB自主采购，评标。', '', '业主签合同后开立信用证，见货运单据支付85%货款，业主验收后，释放验收凭证付清尾款\r\n', '', 'CEB为当地最大电力公司，电表招标主要都通过CEB执行，\r\n', '{08317901B77C40088082317AB8BAD028108D268797C74834B1DDE2FC1083AA37}_CEB-Annual_Report_2016.pdf', 'Rotax成立55年，由23年投标经验，200多名员工。多次在电力设备邻域中标CEB项目。比较了解CEB的运作流程\r\n', '{08317901B77C40088082317AB8BAD028D18C251E4D454BA8A05CF92EE9AFCB77}_Rotax Pvt Ltd - Company Profile 2018 - LQ.PDF', '已与该分部工程师初步联系\r\n', '', '主要对手是宁波三星，华立，海兴,最近两年电表项目中标较多。微星，深开发，瑞银，secure也在持续投标\r\n', '', '利用合作伙伴在CEB电力公司积累的经验和渠道，了解以往类似项目中标情况。通过其他分部的投标项目，了解评标流程和关注的要点，可有针对性准备\r\n', '', '样品能及时，满足要求地提供。 相关测试报告，资质认证符合要求。\r\n', '1.通过之前项目经验，了解该市场价格形势，产品需求和投标文件要求，同时对竞争对手情况也有所了解。           2.L/C为Peoples Bank of Sri Lanka开立的非保兑LC，已评估可以接受。                                     3.购买标书和投标保函由代理操作完成。减少我方前期投入。                                                4.投标样机在投标结果公布后可退回。                                                                 5.该市场已投项目仍在评标中，目前进展顺利，此项目技术规格及要求与之前项目基本相同，资料准备工作量不大。\r\r\r\r\n', '庄钦2019-11-06 13:37:24', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('381', '{65EC2C80-525F-4C1B-8293-B8A783B96D31}', '60', 'INHE-0868', '2019-11-06 10:07:49', '0000-00-00 00:00:00', '2019-11-12 11:04:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2019110602/LCT', '', 'DD3/P*D/ICB/2019/063/D', '2019.12.4', 'SUPPLY AND DELIVERY OF STATIC METER 3 PHASE 4 WIRE – CT OPERATED WITH MODEM 供应三相四线CT表，带模块', '价格条款：FOB+海运费+清关运输\r\r\n付款主体：CEB.\r\r\n付款条款：1）CEB开立LC；\r\r\n          2）85%见货运单据支付；\r\r\n          3）15%在客户验收后支付；\r\r\n交期：LC后两个月内完成交货。\r\r\n质保：5years（from the date of FOB dispatch to the purchaser)，前两年免费更换，两年后质保期内免费维修或更换\r\r\n备注：L/C为Peoples Bank of Sri Lanka开立的非保兑LC，可接受保兑要求，但费用由受益人承担。该银行为国营银行。\r\r\n						', '{65EC2C80525F4C1B8293B8A783B96D318442F4C2B3234363A3D51C033076BD50}_标书Eng-DD3-PnD-2019-063 (1)Static Meter 3 phase 4 wire.pdf', '根据投标方企业性质及归属地，判定实际评标价格（见P8，11.2）\r\n', '', '通过技术标且价格最低的投标人中标。一家中标						\r\n', '', '投标保函：LKR 200,000，有效期至2020-4-1，银河授权代理提供；\r\n履约保函：10%合同额，必须供货方开，Sri Lanka银行开立或保兑，LOA14天内开立，最后批次发货后六十天有效', '', '1. ISO9001：2008或最新的质量保证认证，                            2.符合ISO/IEC：17025：2005的实验室认证                            3. 测试并提交测试报告（要求见技术部分11/21 Clause6.3）             4. 10年生产经验证明，近七年供货记录（技术部分11/21，Clause6.2）.   5. Ofgem certification or other equivalent certification issued by an independent electricity regdlating institution certifying a minimum service life shall be provided with the offer. (标书技术部分13/21，Clause8.1）                                         6.10KV绝缘耐压测试报告 ', '', '购买标书和投标保函的授权文件（power of attorney)，11月27号提供；    10KV绝缘耐压测试报告 最迟11月27号提交。', '', '银河投标', '', 'CEB自主采购，评标。', '', '业主签合同后开立信用证，见货运单据支付85%货款，业主验收后，释放验收凭证付清尾款\r\n', '', 'CEB为当地最大电力公司，电表招标主要都通过CEB执行，', '{65EC2C80525F4C1B8293B8A783B96D31108D268797C74834B1DDE2FC1083AA37}_CEB-Annual_Report_2016.pdf', 'Rotax成立55年，由23年投标经验，200多名员工。多次在电力设备邻域中标CEB项目。比较了解CEB的运作流程', '{65EC2C80525F4C1B8293B8A783B96D31D18C251E4D454BA8A05CF92EE9AFCB77}_Rotax Pvt Ltd - Company Profile 2018 - LQ.PDF', '已与该分部工程师初步联系', '', '主要对手是宁波三星，华立，海兴,最近两年电表项目中标较多。微星，深开发，瑞银，secure也在持续投标', '', '利用合作伙伴在CEB电力公司积累的经验和渠道，了解以往类似项目中标情况。通过其他分部的投标项目，了解评标流程和关注的要点，可有针对性准备\r\n', '', '样品能及时，满足要求地提供。 相关测试报告，资质认证符合要求。', '1.通过之前项目经验，了解该市场价格形势，产品需求和投标文件要求，同时对竞争对手情况也有所了解。           2.L/C为Peoples Bank of Sri Lanka开立的非保兑LC，已评估可以接受。                                     3.购买标书和投标保函由代理操作完成。减少我方前期投入。                                                4.投标样机在投标结果公布后可退回。 \r\r\n', '庄钦2019-11-06 13:35:07', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('382', '{B41B1B07-B070-4E4D-A16D-D433E3EFDADC}', '60', 'INHE-0781', '2019-11-11 03:22:07', '0000-00-00 00:00:00', '2019-11-18 15:33:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111101/PCT', '', '', '', '', '客户直接投标，我们仅供货并提供电表部分相应资质文件。', '', '先做资质预审，过后做技术演示，最后开商务标，低价中标', '', '一家中标', '', '客户自行承担', '', 'CT表需具备KEMA报告', '', '暂无', '', '客户自行投标', '', '项目不到，由电力公司自行决定', '', '客户直接对我们付款，50% T/T预付款，50% T/T款到发货。', '', '电力公司用户稳定增长，效益逐年提高，支付能力有保证。', '', '客户在电力公司具有良好关系，已获得多个类似项目', '', '与客户有良好合作关系', '', '这个市场当前主要是Secure占主导优势', '', '此项目不大，但在我们暂时不具备直接参与Metering Unit的情况下，先通过CT表打入进去，从而与电力公司相关部门逐步建立起业务关系，对我们后续大用户计量设备的开拓还是具备一定的战略意义的。', '', '', '我们已有类似CT表的开发经验，研发投入可控。技术演示及样机生产这一块的费用都会由客户承担，而我们也不需要参与投标工作，仅需提供相应的授权及资质文件，因此我们的投入并不会太高，而一旦成功可以开拓一块新业务，市场需求也具备一定的规模，因此建议参加。', '李启坦2019-11-12 13:42:23', '00', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('383', '{985C68F9-44B1-4653-B20F-CC2009FBF768}', '60', 'INHE-0881', '2019-11-13 10:02:24', '0000-00-00 00:00:00', '2019-11-18 15:27:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111301/FDE', '三相表的PLN技术规格，客户目前还在翻译成英文，后续会补交。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '王鹏钦2019-11-13 11:38:02', '', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('384', '{4747ED1E-8B53-4DB3-882F-0D2875919944}', '61', 'INHE-0431', '2019-11-15 14:32:30', '0000-00-00 00:00:00', '2019-11-18 15:24:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111503/UNX', '', 'REA-AfDB/SUPLS/18-19/00655', '2019年12月23日', 'Supply of connection materials, ready-boards and Pre-paid metres to intensify the last mile connections for new customers near to the existing grid in project áreas under( Lots 1-7)为区域1-7内现有电网附近的新客户提供最后一英里连接所需的连接材料，接电箱(ready board)和预付费电表', '价格：CIP Kampala\r\r\n付款：20%签署合同并提供保函后30天内+80%收货验收合格后30天内\r\r\n质保：交货后12个月\r\r\n交期：180天', '', '主要分为：技术评估和商务评估。综合得分最高者中标。', '', '标书写明供应商可以投一个或多个Lot.但是代理反馈一般不会所有的Lot都给一家公司，所以线缆的Lot建议以其它公司名义投标。', '', '投标保函：Lot 9A: USD110,000/Lot 9B:USD125,000/Lot 9C:USD 35,000\r\r\r\n履约保函:合同金额10%\r\r\n预付款保函：合同金额20%', '', '主要是供货记录的要求。5年类有超过3个类似项目，且金额超过标准要求。Lot 9A – 3,770,000USD/Lot 9B - 4,285,000USD/Lot 9C - 1,200,000USD\r\r\n', '', 'Lot9A和Lot9C主要是技术应答以及相关图纸。\r\nLot9B基本所有资料都要外协（如果以其它公司名义投标）', '', '银河投标', '', '政府对决策有较大影响，因为农电是国家单位。资金也是受国家批准后才能从国外银行领取的。', '', '付款：20%签署合同并提供保函后30天内+80%收货验收合格后30天内。农电的付款除了农电内部审核，还需要资助银行及乌干达政府审核。\r\r\n					\r\r\n', '', '资助资金已到位。', '', 'UNX和合作伙伴也是UNW的合作伙伴。年龄50左右。本身就是电力公司中层，作为评标小组成员参与过很多项目的评标。经验很足。但是经济实力较差。', '', '项目负责人和采购在过去的二年里一直有持续接触。通过UNW项目还会进一步拉近关系。', '', '之前大批量供过货的是宁波三星。但是因为质量问题，他们被农电拉黑（没出正式文件，但是宁波三星自己也知道，且直接没有参与UNW项目）。主要竞争对手参考UNW项目应该是海兴和思达，以及科陆。', '', '银河优势：1.银河是在项目所在国家待的时间最多的厂商，基本没有之一。从项目直接负责人和技术人员到上层政府关系都有布局#FE54` 2.我们的代理也是上次UNW中标的合作代理，有较多的经验且经过UNW项目的洗礼，与农电的关系也更好。 \r\r\n\r\r\n银河挑战：1.据说农电的评标团队会进行大更新，大部分人需要重新拉拢；2.UNW项目的中标价格是公开信息，此次报价会有很大难度。维持UNW报价的话，价格排名极有可能很差。降价又不利于UNW和TLU项目的执行（UNW本来就比TLU低）\r\r\n\r\r\n', '', '1.对代理的公关的支持。据内线了解此次评标团队会大换，所以所有的人员需要重新公关；\r\r\n2.价格方面会和代理以及内线商议出最好的方案，到时需要公司审核通过；\r\r\n3.样品及UNW和TLU试订单执行顺利可以极大地促进UNX项目。如果执行不顺利的话，UNX肯定也无法成功\r\n4.如何制定新的评标规则让我们的价格劣势不要太劣也需要公司商务及技术的支持', '建议公司5星立项。', '刘佩2019-11-15 18:26:10', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('385', '{0953B49A-E2B0-4798-BF55-686D4873454B}', '61', 'INHE-0744', '2019-11-18 04:28:39', '0000-00-00 00:00:00', '2019-11-19 16:38:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111801/GNI', '', 'N゜AOI/04/PRERTDC/2019', '2019年12月13日当地时间上午10时', 'Projet de Réhabilitation et d\'Extension des Réseaux de Transport et de Distribution de Conakry （简称PRERTDC） 科纳克里输配电网改造扩建项目', '资金来源：Agence Fran?aise de Développement法国发展署\r\n以几内亚法郎或欧元支付\r\n付款方式：合同签署后的30天内付10%的预付款；装船时以确认且不可撤销的信用证支付合同金额的80%；验收后的30天内支付合同金额的10%。\r\n若超过60天才付款，则应支付利息\r\n交期：80-180天内交至电力公司仓库\r\n若未能如期交货，则每晚一周罚款0.5%，最多可罚款合同金额的10%\r\n质保期：360天\r\n买方收货后若发现产品有缺陷，则可通知卖方，而卖方应在30天内进行修复或换货\r\n', '{0953B49AE2B04798BF55686D4873454B8442F4C2B3234363A3D51C033076BD50}_CGN 1206 DAO compteurs_28-10-2019 vf.pdf', '在满足技术规格通过资格后审的情况下，价低者中标\r\n', '', '独家中标，一家制造商只能授权一个投标\r\n', '', '投标保函：与投标文件一起递交金额为100000欧元的投标保函\r\n履约保函：在收到中标通知的28天内提供履约保函，为银行保函，金额为合同金额的10%；买方将在卖方履行完所有义务后的28天内归还该保函。\r\n', '', '应在电子式电能表和电表箱的制造领域拥有至少10年的经验；\r\n年营业额不低于1000万欧元（用最近5年正在进行中或已完成的项目所收到的总金额除以5）；\r\n从2014年1月1日截止到投标日，以供应商的名义在至少4个相似市场供货，每个市场的供货量均不低于1百万欧元；\r\n在上述规定的供货经验中，至少有2个是提供了表计设备（电表或表箱），数量应大于等于30000件；\r\n提供在有效期内的ISO9001质量认证证书。\r\n', '', '整套投标资料\r\n', '', '银河直投，代理负责运作', '', '', '', '付款方式：合同签署后的30天内付10%的预付款；装船时以确认且不可撤销的信用证支付合同金额的80%；验收后的30天内支付合同金额的10%。\r\n', '', '资金来源：Agence Fran?aise de Développement法国发展署\r\n', '', '目前银河在该市场无直接关系；\r\n代理已经在该市场开发多年，有一定的客户关系，同时也为公司获取了部分订单', '', '', '', '目前共有10多家公司购买标书，国内主要竞争对手都参与了该标', '', '1、准备完全符合标书要求的样机和投标资料；\r\n2、根据开标结果，联合代理及关系运作样机测试流程和方法，争取将比银河价格低胡厂家全部测出局；\r\n3、寻求其他厂家的投标资料，从资料上踢掉部分竞争对手；\r\n4、良好的客户关系。\r\n', '', '1、完全符合标书要求的样机；\r\n2、较低合适的价格；\r\n3、良好的客户关系。\r\n', '该标是由法国开发署提供的资金的国际招标。该标的数量在法语区国家算是较大的投标，各竞争对手都会参与其中，竞争激烈。需要首先准备好自己的投标资料和样机，然后联合代理进行运作。', '郑超波2019-11-18 05:03:16', '03', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('386', '{B9C5A83A-E428-4DEE-A4A6-B41A8B4C48D3}', '60', 'INHE-0535', '2019-11-19 13:38:50', '0000-00-00 00:00:00', '2019-11-21 08:50:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111902/EESL-4', 'GEE', 'EESL/06/ICB-Smart Meters-Pan India/Phase-4/192007014', '2019-11-24', 'Procurement of 5 Million Smart Meters for Pan India为泛印度采购5百万智能电表', '价格条款：\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n本地厂家EXW（不含GST），国外厂家CIP（不含关税）；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\nGST和关税由EESL报销（与清关有关的税费只会报销给外国厂家，不会报销给本地厂家）；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n国外厂家必须用USD报价，EESL仅用USD与国外厂家结算；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n付款主体：ADB融资，但付款和项目执行监管由EESL全权负责；\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n付款条件：\r收到相关单据后30天内付款。                               a)供应阶段：以下材料抵达指定地点/仓库后支付60%（EESL在收到投标人的发票和在指定交付地点收到所有要求的经EESL EIC(Engineer-in-charge)/授权代表签字盖章的文件后30天内付款）：1.提交DLMS标准符合验收，APIs, 数据交换信息和配置图表，测试步骤和型式测试报告。2. 订单验收 3. 必要的合同履约保函提交4. PDI报告和物料交付许可证（MDCC）        ', '{B9C5A83AE4284DEEA4A6B41A8B4C48D38442F4C2B3234363A3D51C033076BD50}_Payment terms and LD－EESL-Phase 4-3.pdf', '按照国内投标人和国外投标人分为2组，国内投标人适用本地10%优惠：\r\r\na.国内投标人组/本地制造：按不含GST的EXW印度卢比价格评标。\r\r\n但会按含GST的价格签署合同，GST最终会由EESL进行补偿；但投标人由国内市场购买或进口的基本材料或部件所支付或应缴的所有关税和税款，由投标人自己负责。\r\r\nb.国外投标人组/国外制造进口：按不含关税的CIP美元价格评标。\r\r\nEESL会在发票等证据提交后支付所发货物的100%关税；但港口支付装卸费、佣金或任何其他附带费用由投标人自己负责；\r\r\n每组选出组内最低价，两组最低价再进行相互比较。如果最终的最低价出自国内投标人组，那么该国内组最低价投标人中标；如果最终的最低价出自国外投标人组，那么将在该国外投标人最低报价基础上另加10%CIP价，再与国内组最低价进行比较，两者中最低者中标。\r\r\n不同货币进行评比时，会统一按截标前一天的RBI卖出汇率转换成印度卢比进行比较。\r\r\n', '', '每个包一家中标。', '', '投标保函：每个包USD29万；\r\r\r\n履约保函：10%合同额，有效期7年。每个包约USD200万；\r\n由合作伙伴开立。\r\n\r\r\n\r\r\n', '', 'a.单个投标人或联合体（不超过3个成员）投标：联合体无论是主投还是联合体成员，只能参与一个联合体投标；\r\r\nb.投标文件，投标保函，履约保函，标书费用等由主投提交和开立；\r\r\nc.主投必须为表厂，有NABL实验室；外国厂家无NABL实验室需声明其在项目期间能够在印度当地提供质保和更换服务；\r\r\nd.主投过去3年累计供货40万只电表；\r\r\ne.外国投标人要声明有本地代理负责售后，并要提供本地代理地址和3个以上中高层人员的身份信息；\r\r\nf.投标人过去3年至少2年是盈利的；\r\r\ng.投标人电表业务年平均营业额过去3年达INR 146cr./USD20.9million#FE54` 如果是联合体，每一个成员都需要至少满足10%（一个lot）；\r\r\nh.投标人要有任一产品的BIS证书，或者BIS申请证明文件；\r\r\ni.投标人过去3年累计3个类似供货合同额达INR 164cr./USD27.9million(一个lot)#FE54`\r\r\n', '{B9C5A83AE4284DEEA4A6B41A8B4C48D303404677E4D44E9EB56B3D512B2AF9CC}_2019-10-24 Amendment No 5.pdf', '可参考JPM,JPY项目投标资料，但部分资质文件及时间需要更新', '', '联合投标。投标方案1：EESL允许同一个联合体主投及非主投互换，投不同的包（待确认）；共投3个包，其中2个包由INHE主投，以美元报价，直接从中国供货； 1个包由Genus主投，以印度卢比报价，INHE供SKD（修调校验后的PCBA）给Genus；投标方案2：EESL不允许同一个联合体主投及非主投互换，投不同的包（待确认）；共投3个包，其中要么3个包全由INHE主投，以美元报价，直接从中国供货； 要么3个包全由Genus主投，以印度卢比报价，INHE供SKD（修调校验后的PCBA）给Genus；', '联合投标原因：无论上述哪种投标方式，保函全由GENUS代表联合体开立；\r\n双方大致权责：\r\n根据招标要求，GENUS作为联合体成员会被命名为外国主投INHEMETER的本地代理，执行所有售后服务。GENUS应当为备品提供合适的库存场地，且提供售后团队接受INHEMETER的质保相关的培训。相关成本除质保范围内的备品备件外由GENUS承担，其中由GENUS生产供货给EESL的、采用双方联合品牌的成品由GENUS承担零配件成本，银河仅对供货给GENUS的部件质量负责。由GENUS生产制造过程导致的售后问题由GENUS负责。\r\n\r\nINHE提供0.5%备品给GENUS，以履行质保义务。并向GENUS售后团队提供质保相关的技术培训如坏表维修。银河直接生产供货给EESL的成品由银河全权负责，而由GENUS生产供货给EESL的、采用双方联合品牌的成品，银河仅对供货给GENUS的部件质量负责。属于银河产品设计问题导致的售后问题，由银河负责。\r\n\r\n任何一方因未履行其义务而直接导致项目被撤销或取消，且让另一方由此遭受损失，那么一方应赔偿另一方由此产生的经济损失。\r\n\r\n', 'EESL自主决策采购', '', 'EESL直接付款给中标者：收货后30天内支付60%；与系统兼容后30天支付30%；余下10%验收后5年内每年2%。\r\r\n', '', 'ADB融资', '', '1.目前仍在通过代理运作允许外国投标人以OEM形式在印度当地设厂完成部分交货（此条件为拉融资方进来开立保函、融资等的前提条件），如此条件能够运作下来，银河将以自己名义参投2-3个包（分别由不同的融资方提供融资）；   2.如果此条件无法运作下来，将和Genus确定合作关系，投标方式如11.中所述。以Genus作为主要合作伙伴以联合体形式参投2-3个包；                  3.与Genus的合作从目前洽谈的情况来看，主要存在两个问题，一个是结算条件上，对方坚持40%的尾款的议付（LC可以下单时就开出）要放到电表安装完毕并现场调试成功之后；另一个问题是对方在承担开立保函、为结算开立LC、履行质保义务这些工作的前提下，要在我司报价基础上加价30%，这个加价幅度偏高，考虑到这次的竞标要和其他中国厂家竞争CIF美元价格，按这个加价幅度，最终报价未必会有竞争力；如前面资质运作不成功，上述两个条件需要和Genus再次进行洽谈\r\r\r\r\n', '', '业主方面关系主要通过代理在做；\r\n同时EESL 的现在位MD即将离职，由新人代替。', '', '国内竞争对手：海兴，通过海兴印尼工厂投标和供货，本地代理Palmohan。在EESL-2项目中采用3G方案，成本较银河偏高；已邀请EESL人员验厂，业主关系工作做的较好。但因为海兴在国际市场名声不是很好，EESL也了解到其在印尼供货项目出现过质量问题，因此对海兴的供货产品仍抱有疑虑态度。\r\r\n本地竞争对手：genus power, L&T, HPL等。各家都是本地电表招标项目常客，与EESL都有各自良好的关系渠道，其中Genus因为在EESL-1项目中正在供货，相较其他竞争对手，EESL对Genus更为满意。但最终决定中标与否，仍是价格因素。', '', '如15和17中所述。', '', '1.剔除掉报价异常低的投标人（通常为小表厂或没有产品和技术乱报价的投标人，需要在技术标评标期间剔除资格）；\r\n2.有竞争力的报价。', '1.由于目前仍在通过代理运作允许外国投标人以OEM形式支持融资方参与投标，并且根据代理反馈，近期会有新的修正发布，因此该标需要再次申请延标。如此条件能够运作下来，银河将和融资方联合投标，并作为主投投2-3个包，融资方开立全部保函；同时可从价格上支持Genus Innovation自己投标，背后由银河供SKD。\r\n2.如上述条件不能运作，将按照和GENUS已洽谈的合作方式，进行联合投标。', '左亚楠2019-11-19 17:01:37', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('387', '{72FD9F35-A83D-4A9D-8DDC-76423428A4AF}', '61', 'INHE-0911', '2019-11-27 15:14:20', '0000-00-00 00:00:00', '2019-11-29 10:34:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112702/ZUP', '', 'UEDCL/SUPLS/2019-20/10161', '16th December 2019 at 11:00am', 'Supply of 2000 pre-payment energy meters2000台预付费电表的供货 （替换问题电表）', '标书要求：本地币结算，100% 在验收合格之后、收到发票后30天内支付。\r\r\r\n银河与代理之间：美元结算，具体结算方式待确认【将争取至少生产前预付款，发货前尾款的结算方式】。\r\r\r\n交期和违约金：2个月内交货；每周对应金额的1%，最高总值的110%。\r\r\r\n质保：供货后12个月/发货后18个月。30天内维修/替换故障表。', '', 'TCS评标法：技术和商务符合条件下，最低价中标。\r\r\n17th -20th December 2019评标，27th Dec, 2019公示中标（10天）\r\r\n', '', '1个包，1家中标', '', '4,000,000  UGX，乌干达本地银行开立 【代理开投标保函】，有效期为到l 30th June 2020。签订合同后21天内开立履约保函，合同金额的5%；乌干达本地银行开立【代理开立】\r\r\n', '', '1. 需提交UNBS认证证书\r\r\r\n2. 签字授权需公证，乌干达本地签字授权要注册登记\r\r\r\r\r\r\r\n3. 需提交愿意接受FAT的声明\r\r\r\r\r\r\r\n4. 愿意接受合同条款的声明\r\r\r\r\r\r\r\n5. 经审计的过去3年的财报（2016,17,18）                               6.DIN表，5(100)A，要能远程拉合闸（具备AMI功能），预付费、后付费可切换，要有USB形式的VTC口（P80，6.10）\r\r\r\r\r\r\n7. 电表有具体尺寸要求，15年寿命\r\r\r\r\r\r\r\n', '', '技术资料需客服部协助', '', '代理商投标', 'N/A', '电力公司故障表更换，电力公司内部决策为重', '', '标书：本地币结算，100% 在验收合格之后、收到发票后30天内支付', '', '电力公司OK。代理资金执行2000套表的订单OK.', '', '有经验，有实力。已合作过UNW和UNX项目。', '', '有一定的客户关系。', '', 'CONLOG，宁波三星，海兴在乌干达市场均有大批量供货，有一定的客户关系、项目执行基础。预计会是中国厂商之间的竞争，但此项目数量较少，竞争预计不会过于激烈。', '', '银河UNW项目有一款PLC电表获得了UNBS认证\r\n银河有UNW和TLU项目中标基础，有本地合作代理\r\n', '', '价格最低者中标：需代理反馈价格建议，需公司支持报价。技术和商务条款要做到符合标书要求。需提供符合要求的样机。', '本地代理有较好的客户关系，项目经验丰富。项目要求不是特别复杂，建议立项。', '付文涛2019-11-27 16:22:43', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('388', '{A3A54638-258F-4219-8495-FBCB821C8E4A}', '61', 'INHE-0853', '2019-11-28 18:30:33', '0000-00-00 00:00:00', '2019-12-03 16:10:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112801/DGN', '请先做内部技术评审。如果可以采用已有方案，投标；否，放弃。', 'AOO N032/DED/PRMP/DG/CEET/2019', '2019年12月17日', 'ACQUISITION D ENSEMBLE DE REGROUPEMENT DE COMPTEURS PROTEGES (ERCP)采购一批保护电表的组装套件', '若收款方是多哥本地的，将通过银行转账付款；如果收款人是其他地方的，则将通过不可撤销的确认信用证付款。1.预付款：合同总金额30%的预付款，在电力公司收到供货商发货通知单后，根据付款请求与银行进行结算；2.临时验收：合同总金额65%，提供CCAG第12条规定的文件并获得电力公司开具的临时验收单后，在提出付款要求的60天内进行结算；3.剩下合同总金额的5%于质保结束后支付。', '', '1.在详细评标之前，先评估是否每份投标资料是否签字，并附有投标保函。\r\n2.接下来评技术部分，技术资料是否满足标书的技术规格。\r\n3.评财务部分。评完财务文件，价格最低者中标。', '', '一个LOT，一家中标\r\n', '', '1.投标保函：6 000 000 FCFA无开立行资质要求。\r\n汇率采用截标前十天的BCEAO的汇率, 保函在截标后28天内有效\r\n2.履约保函：在中标签合同20天内，中标者需要开合同总金额的5%的履约保函。\r\n', '', '1.财务能力：\r\r\n提供财务能力证明（财务流动性可用性），以证明投标人可以使用至少为投标人竞标报价的0.5倍的信贷额度。\r\r\n最近三（03）年的年均营业额至少等于竞标者的竞标报价的0.5倍。必须提供最近三年（2016、2017和2018）的认证财务报表。\r\r\n2.技术能力和经验：\r\r\n制造商的授权书，法语的技术应答表，产品使用说明书，使用标书第四部分的表格模板；\r\r\n样品测试报告；\r\r\n3.供货经验：\r\r\n候选人还必须提供过去五（05）年内完成（01）类似合同的证明。\r\r\n', '', '商务资料+技术资料， 12月15日\r\n', '', '代理商投标', '', '为了寻求必要的资金支持，CEET在2000年9月进行了私有化，由里昂自来水公司和魁北克国际水利公司买段经营20年，继续从事在多哥的电力生产，分配和销售。本次招标为电力公司自筹资金，满足年度的采购需求，且分析本次评标规则，取决于产品及投标资料是否严格符合标书要求及低价胜出。政府/政治对客户决定过程影响不大。\r\n', '', '', '', '', '', '代理公司总部为多哥洛美，在当地有一定的实力及影响力。但实际在当地客户关系不强。因此前几次投标都未成功，目前洽谈的路灯系统试点项目还未签定试点协议。代理正努力地运作想用我司的smartvend替换电力公司旧的售电系统，目前也还未有实质性进展。\r\n', '', '此前DDN与DCN为代理投标与银河直接投标，均未中标。客户关系主要靠代理，且代理非常忌讳我司直接与电力公司联系，业务人员因本年度有个DEN路灯软件试点项目还在洽谈，接触过配电总监及IT总监。', '', '思达/海兴通过本地代理商中过标。\r\n', '', '', '', '项目成功关键：仔细检查标书要求，按照标书要求，在规定的时间内准备标书文件，维持和代理之间的即时沟通-充分考虑自己的价格和竞争对手的价格，所有符合条件的厂家中，取投投标价格最低中标。\r\n需要的支持：准备商务资料和技术资料过程中对接部门的支持', '', '胡亚婵2019-11-28 18:44:52', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('389', '{2F0A3E12-640B-4B4B-8847-06AB59C26316}', '66', 'INHE-0634', '2019-11-29 11:00:47', '0000-00-00 00:00:00', '2019-12-02 09:43:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112903/RLJ', '', 'AOI/BIENS/PASEC II/2019-01', '2019年12月24日', 'Projet d’Appui au Secteur de l’Energie aux Comores (Financement supplémentaire)科摩罗能源部门支助项目(补充资金)', '标书翻译中，待核实。银河和代理之间的付款方式为：100%保兑即期信用证。', '', '仅审核投标资料。', '', '1家中标。', '', '标书翻译中，待核实', '', '标书翻译中，待核实', '', '标书翻译中，待核实\r\n', '', '银河供货，授权银河马达加斯加代理使用银河产品投标。马达代理与科摩罗本地代理组成合作关系参与竞标。', '', '', '', '标书翻译中，待核实\r\n', '', '非洲开发银行贷款。', '', '马达代理在当地的合作伙伴与科摩罗电力局有密切人脉关系。', '', '', '', '核实情况中。', '', '凭借代理的人脉关系网络运作项目，争取中标。', '', '项目成功的关键在于内部关系，代理表示他已经具备，需要我方支持提供符合标书要求的完整的投标资料。', '建议立项。', '陈雁2019-11-29 11:33:14', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('390', '{F4EA1D0C-DF00-4F04-9211-B6D4C24A10AA}', '61', 'INHE-0440', '2019-11-29 11:28:50', '0000-00-00 00:00:00', '2019-12-03 09:14:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112904/TTX', '', 'TENDER NO. PA/001/2019-20/DZN/G/02', '12月10日', 'SUPPLY OF METERS FOR DSM & COAST ZONE UNDERFRAMEWORK ARRANGEMENT 框架合同供应电表给达市和海岸各地区', 'TANESCO付坦先令。国内付款条件为： (1)无预付款和发货款。（3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                                         质保期限：接受货物起12个月，发货后18个月。交期：一年内交完各分订单/LPO的货。违约：百分之0.2/天，未发货产品，最多10%。\r', '{F4EA1D0CDF004F049211B6D4C24A10AA8442F4C2B3234363A3D51C033076BD50}_BIDDING  DOC METER G.02 Latest one.pdf', '框架合同国内限制性招标，只允许本地厂商参与。先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。\r\r\n', '', '只允许本地厂商投标，目前有8家工厂，每个厂家最多分3个LOTS，一个LOT可以分给不止一家厂家。', '', 'ITL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '供应/生产类似规模产品的经验,人员资质，设备和生产能力等。', '', '技术应答表，非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。最迟12月4日提供。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，目前银河融资额度为5百万美元。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU，STAR等，EDMI主要支持者是电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者电表部经理，采购经理，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，高级配电经理，实验室工程师等。STAR目前客户关系较弱，直接做本地的市场，代理商还有待确认。EDMI主要是供单相，三相分体式直通/CT/VT表。海兴目前暂无中标记录。威胜和CLOU主要供货单三相直通表，本地价格可以做到EXW 40 USD。目前市场上主要的本地厂家为ITL，EDMI，WASION, CLOU, 其中ITL，EDMI,WASION和CLOU四家可以合作。', '', '本地限制性招标，电力公司主要开放给ITL，EDMI,CLOU和WASION,STAR, HEXING等。ITL目前已经和我司签了批量SKD合同，满足供货要求。框架合同，标书的技术规格为分体式单相和三相直通表和LV250A计量箱，其中LV250A计量箱需要制样和提供给ITL投标。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率较大，可以在未来3年获得较稳定的订单来源。', '', '产品报价符合市场形势，样机制作按时交付，技术支持，商务和研发人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '汤伟2019-11-29 16:51:52', '03', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('391', '{33E0637F-6A22-4794-A5D2-FEF8D7B2BD4E}', '61', 'INHE-0819', '2019-12-03 10:28:19', '0000-00-00 00:00:00', '2019-12-05 09:54:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120302/NFB', '', 'SM4107353', '2020年2月12日', 'DOURNITURE DES COMPTEURS ENERGIE ELECTRIQUE STATIQUES EVOLUTIFS DESTINE AUX CLIENTS DE BASSE TENSION', '1,DDU条款，地区部仓库交货。2，电力公司自有资金。3，分五次交货，每次交货临时验收之后TT或信用证付93%，最终验收TT付.4,第一批货交期为四个月，剩余的四批货每三个月交付一次。', '{33E0637F6A224794A5D2FEF8D7B2BD4E8442F4C2B3234363A3D51C033076BD50}_AO SM 4 107 353 Compteurs BT Statiques.pdf', '先技术后商务', '', '一家中标', '', '投标保函月26万美金，履约保函为合同金额的3%', '', '1，无公司年限要求。2，要求至少两次类似供货经验。', '', '本地形式认证需要MID证书', '', '银河直投', '', '配电部主导决策，CEO拍板', '', '临时验收后采用信用证或TT付款93%，最终验收后TT付7%。培训款项在培训完并签发最终PV后100%TT付款.', '', '', '', '', '', '', '', '科陆、海兴、中兴。科陆客户关系在配电部负责人SBAAI，通过他中了NF8。', '', '优势：NF2、NF7供货及服务经验。 劣势：NF7交付未如期，客户关系需要修复。   1，认证准备投标资料以及样机。2，拉拢配电部负责人SBAAI及其手下FATIMA。', '', '1，投标资料样机无误。2，产品价格 。3，配电部大佬的支持。', '1，是NF8后续项目，用于低压用户，需求一样。2，项目预算2300万欧，潜力巨大。3，明年还有类似需求和体量的标发出。', '付为2019-12-03 11:14:46', '04', '★★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('392', '{7F65AC9A-0E79-4667-BAF1-98698929CB22}', '61', 'INHE-0853', '2019-12-04 15:32:15', '0000-00-00 00:00:00', '2019-12-09 09:45:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120401/CMN', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '喀麦隆是我司还未进入的市场， Eneo拥有超过973250客户。该预审是电力公司为2020年的2万台电表的限制性招标做准备，且未来电力公司计划换掉所有的旧电表，若能获得投标资格直接与电力公司合作，未来可期。\r\r\r\r\r\r\n', '胡亚婵2019-12-04 15:46:00', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('393', '{0536486F-D230-4C40-937A-1EC99EEACA66}', '61', 'INHE-0654', '2019-12-05 11:35:51', '0000-00-00 00:00:00', '2019-12-09 09:53:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120503/EPE', '', 'S.C. N°: 69321-2019', '1月20日', 'Adquisición de Sistema de Telemedición con Telegestión del tipo AMI.', '交期：12个月；付款条件：货到之后三十天内付款（按批次付款）；', '{0536486FD2304C40937A1EC99EEACA668442F4C2B3234363A3D51C033076BD50}_licitacion de EPEC.pdf', '商务资料的审核+样机的测试+价格', '', '1家中标', '', '代理开立保函', '', '', '', '全部资料要求西班牙语', '', '代理商投标', '', '公共招标（EPEC是国有电力公司，采用低价中标模式，中标之前需要通过试点的测试）', '', '', '', '电力公司的采购资金来源：内部资金+科尔多瓦政府的资金；代理商能调动的资金状况不明朗，如中标需要找银行融资；', '', '目前西班牙CIRCUITO和科陆，兰吉尔在预付费试点的项目中已经测试通过（电力公司反馈海兴并未通过）；目前对科陆的产品和系统都较为满意，11月初科陆的西语区负责人和工程师在EPEC支持试点，科陆的代理商也是该地区的，有较好的客户关系。', '', '待加强', '', '科陆的代理商：Conectar；海兴：Hexing TSI S .A. 兰吉尔：STOREY', '', '目前银河的产品已经在EPEC开始做试点（11月签署的试点合同），代理与内部的技术副经理关系较好，通过他的关系，EPEC才接受银河的试点。', '', '单相表的产品要支持有功和无功计量，并且要求四象限有功和无功的计量（Q1，Q2，Q3，Q4）一定要满足的，目前了解到银河的单相表只有组合无功，并没有单独分开计量（技术规格要求的，并且其他厂家均满足）；价格需要有一定的竞争力（与科陆）', '1，该电力公司的首个AMI项目，本次招标数量共计约5万台，对于南美的市场来说均算数量较多的标；2，银河在该市场有基础，并且有给EDENOR第一大电力公司供货的记录，可以作为推动点；3，EPEC属于区域电力公司，归政府管辖，重视客户关系和价格，海兴是当地团队在推动，科陆目前也主要依附于本地的代理商，相比之下银河也具有一定的竞争力；4，建议参与，技术规格正在整理翻译，除开有功无功需要分开计量的必要规格，其余的在此前与代理核对过，无特殊要求。', '李明2019-12-05 14:24:56', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('394', '{F938D3AB-4B88-4E2D-9CCC-D768ACAF81B7}', '61', 'INHE-0772', '2019-12-05 15:32:24', '0000-00-00 00:00:00', '2019-12-09 09:51:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120504/MLD', '', 'DEMANDE DE PRIX N19/154/AD', '2019.12.16', 'FOURNITURE DE COMPTEUR ELECTRONIQUE A PREPAIEMENT STS 230 VOLTS 5/60A ISAGP 预付费STS 230V 5/60A 电表采购项目', '代理投标，100%TT发货前付清, 50%预付款，50%发货前付清\r\n', '', '无 询价函的评标规则删除\r\n', '', '无限制，两个lot，无限制', '', '无', '', '无', '', '样机，技术文件', '', '代理商投标', '', '电力公司自有资金，电力公司决策', '', '', '', '', '', '代理今年多次中标，与电力公司关系好', '', '高层更换，目前无直接客户关系', '', 'CONGLOG, HEXING, WASION， ITRON, ZHONG CHENG, HEXCELL\r\n', '', '马里当前局势不稳定，电力公司搞成更换频繁，电力公司其付款条件较差，以当地定向询价为准，当前策略以配合代理投标为准。', '', '1. 提供技术应答标技术规格与以前项目一样，没有变更，文书资料可参考旧项目。2 样机制作，样机提交时间由代理协商延后。', '马里当前局势不稳定，电力公司搞成更换频繁，电力公司其付款条件较差，拖欠当地代理货款是常态。招标方式以当地定向询价为准，当前策略以配合代理投标为准。\r\r\n', '张子琦2019-12-05 17:49:38', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('395', '{6A729323-861E-4F78-A7DE-526831294174}', '60', 'INHE-0881', '2019-12-09 15:58:36', '0000-00-00 00:00:00', '2019-12-12 14:53:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120901/GMS', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '王鹏钦2019-12-09 17:25:24', '', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('396', '{8822B3BD-CA79-4C0F-B7F5-1C824ECAF472}', '61', 'INHE-0432', '2019-12-12 18:02:53', '0000-00-00 00:00:00', '2019-12-16 16:26:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2019121206/KCB', '', 'KP1/9A.3/OT/18/19-20', '2020年1月8号', 'FOR THE SUPPLY OF CIRCUIT BREAKERS, SWITCHBOARD PAELS, 11KV METERING PANELS 产品供货：11KV空气开关柜，31.5KA的计量面板，66KV的断路器。', '价格：DDP\r\n付款条件：满意交付后30天。', '', '一审：商务评审；二审：技术评审；三审：财务。', '', '1.11KV（31.5KA）计量面板：按不同的LOT来评审，一个厂商只能中1个LOT。价格最低者，数量最多。\r\n2.66KV断路器、11KV开关柜，最低价者中标。', '', '投标保函：\r\nLOT A：\r\n66KV CIRCUIT BREAKER 3PH SF6 OUTDOOR，62,231.00，KSH\r\n11KV METERING BREAKER PANEL (31.5KA)，1,106,469，KSH\r\n11KV 13 PANEL SWITCHBOARD 1500A (31.5KA)，1,300,000.00，KSH\r\nLOT B：\r\n11KV METERING BREAKER PANEL (31.5KA)，737,649，KSH\r\nLOT C:\r\n11KV METERING BREAKER PANEL (31.5KA)，516,352，KSH\r\n评标规则要求：投标保函为本地银行出具。\r\n投标保函有效期：投标截止日期后30天\r\n\r\n质保：\r\n1.断路器：5年\r\r\r\r\n2.开关柜：5年\r\r\r\r\n3.计量面板:5年\r\n\r\n履约保函：需要。但具体比例标书未明确。', '', '\r\n1.提交招标文件日期后的十八（18）个日历月内报告的财务报表。\r\n2.提供4份分用户证明\r\n3. ISO9001或者肯尼亚当地KEBS认证', '', '由珠海配网提供技术支持。', '', '此标只面向厂商，或者厂商授权的本地企业/代理投标。一个厂商可以直接投标，或者，可以授权【任意】数量的本地企业/代理投标。经与珠海配网商量，由IAC参与直接投标。', 'N/A', '电力公司自行采购：评标委员会+MD为关键决策链。', '', '', '', '', '', '竞争对手信息、以往招标情况需要业务获取。', '', '配网产品业务此前没有深入经营，此次是个较好的机会，做深采购和配网部门的客户关系。', '', '', '', '竞争策略：1.需要找到合适的供应商配合支持珠海配网；2.价格合适。3.业务做好客情建设。', '', '1.需要找到合适的供应商配合支持、需要深圳总部替IAC开保函。2.业务做好采购及评标委员会的客情建设。3.业务拿到以往招标信息供珠海配网参考。', '1.由IAC投标。2.考虑目前与代理合作状况，建议业务自己做客户关系、竞标。', '谭东羊2019-12-12 18:57:54', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('397', '{5035A0C1-24DD-4570-97D9-51D616662327}', '61', 'INHE-0381', '2019-12-16 15:05:38', '0000-00-00 00:00:00', '2019-12-18 11:34:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019121604/CNV', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.技术支持提供技术协助。', '1.项目背景：该项目主要是Voltalia从2019年初开始做起的项目，属于离网招投标项目，需要带资金融资，主要有4个欧洲公司入围该项目。2020年1月份要提交资料，Voltalia在寻找合作的技术供应商。该项目给3个城市做项目，每个城市约15万人口，预计每个城市有15K的电表需求。需要银河提供售电、集抄、数据集成、以及服务方案。11月欧洲展拜访过该客户，项目比较靠谱。2.合作方式：Voltalia出资金，银河出技术方案。附件相关的方案已经获得客户认可。现需要提供报价。 ', '张柳芳2019-12-16 16:04:05', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('398', '{74E03E8F-993D-47C5-B4EE-D4E28AA1E927}', '61', 'INHE-0911', '2019-12-17 09:02:16', '0000-00-00 00:00:00', '2019-12-18 18:05:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2019121701/URB', '', 'REA-ERTIII/SPLS/18-19/00559', '17th Jan. 2020  11:00am', 'ENERGY FOR RURAL TRANSFORMATION PHASE III乌干达第3期乡村转型电能领域产品采购 需要Ready Board 20000个及相关产品', '标书要求：美元结算，预付30%，剩下70%货物完成后采购方承兑日60天内付款    交期和违约金：5个月不晚于6个月交货：违约金每周1%，最多5% GCC27.1       质保：两年质保证明（P82）（GCC28.3 p16），90天内维修/替换故障表。P117    ', '', '评标时间：2020年1月17号11点05\r\n评分标准（P83）：以下3项低于80分则失去商业评估资格。\r\n1.提交的技术文件 20分\r\n2.仪表箱等产品技术评估 60分\r\n3.市场经验 20分', '', '1个包多家中标（最多9家中标，可多中）\r\n', '', '供应商应在合同授予通知发出后28天内，按照合同金额的10%，币种为美元，为合同的履行提供履约担保。GCC18.3 P115\r\n', '', '1.3年财报。P40\r\r\r\n2.经验技术能力证书：6年内2份合约详细价格及货物，送货单，客户评价P40\r\r\r\n3.在Uganda相似热带地区产品使用6年的文档证明P40\r\r\r\n4.需UNBS证书\r\r\r\n5.备品货物需有5有效使用期（不包括ready Board）（ITB16.4）\r\r\n6.授权书必须在Uganda注册服务局注册的地方公证（ITB20.2）\r\r\n7.需提交愿意接受FAT的声明\r\r\n8.Ready boards和其他相关产品制作的图纸及技术资料细节要发给标方确认，才可生产。P82\r\r\n9.ready board, softwood board, copper earth rod, earth wire,meter ox and load wire需提供两年质保证明，如损坏供应商负责更换。P82', '', '投标资料需客服部协助', '', '银河投标', 'N/A', '乡村改造第3期工程，投标公开性大，公司内部决策为重。', '', '30%预付款，70%承兑日60天内付款（银行担保）。', '', '电力公司OK，且已经有过合作。', '', '有经验有实力，可打好本地关系，且已经合作过UNX及UNW项目。', '', '有一定的客户关系。', '', 'CONLOG，宁波三星，海兴在乌干达市场均有供货，有一定客户关系，项目执行基础。此项目为公开招标，公开性大。乌干达农电是乌干达除了UMEME之外的另一家配电公司，主要负责农村电力电气化的相关项目', '', '市场较为成熟，银河UNW项目有一款PLC电表获得了UNBS认证\r\n银河有UNW和TLU项目中标基础，有本地合作代理\r\n', '', '需代理反馈价格建议；需公司给出支持报价；商务及技术条款要做到符合客户要求。同时后期审厂及样品检验需要重视。', '本地代理有较好的客户关系，且项目经验丰富，同时我们也基本满足其要求。建议立项。', '付文涛2019-12-17 09:46:48', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('399', '{7009D05A-D1AF-4873-B399-D74C91632511}', '61', 'INHE-0853', '2019-12-20 09:00:31', '0000-00-00 00:00:00', '2020-01-06 10:38:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2019122001/EDN', '', '', '2020年1月7号', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '提供有竞争力的报价与严格符合标书技术规格的电表产品技术资料', '', '商务协助翻译技术文件，准备厂家授权书#FE54`技术支持协助技术解析，推荐对应产品型号提供技术资料。', '喀麦隆是我司还未进入的市场，我们正努力的突破该市场寻求机会，此前为ENEO喀麦隆电力公司2020年限制性招标资格准备了样机，项目代号CMN。现在\r从代理处获取到喀麦隆电力发展公司EDC正在做电表招标，由非洲发展银行出资，厂家授权代理投标，合作方式为提供FOB报价给代理。值得一试。								\r\r\r\n', '胡亚婵2019-12-22 07:24:37', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('400', '{7BB61572-F523-403F-8668-1C6611661C1A}', '66', 'INHE-0634', '2019-12-29 04:18:07', '0000-00-00 00:00:00', '2020-01-06 12:37:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019122901/TLR', '', 'N° _016_/19/AON/PIC2_OFID', '2020年1月14日', 'FOURNITURE ET LIVRAISON DE COMPTEURS D’ELECTRICITE INTELLIGENTSA SYSTEME PREPAIEMENT ET ACCESSOIRES POUR ELECTRIFICATIONRURALE', '代理对银河的付款方式：30%TT预付+70%保兑即期LC', '', '审核投标资料和报价单，价低者中', '', '1家', '', '', '', '', '', '', '', '银河供货，代理投标', '', '', '', '', '', '该项目已经获得当地融资贷款机构的资金支持，电力局付款OK。代理家大业大，付款能力也OK。', '', '合作伙伴在当地的控制力较大，业务范围相当广泛，影响力辐射到马达及其周边的国家如毛里求斯等地，其CEO与政府各部门高官和领导人等保持持续友好往来关系。与我们电表生意直接相关的是子公司GT的总经理Remy,年轻但是聪明，做事效率很高；集团的CEO Mr Yias继承家族企业,已近古稀，但仍然相当活跃，野心勃勃，今年10月还受法国总统邀请出席峰会。右侧附合照，摄于Mr Yias办公室内。', '{7BB61572F523403F86681C6611661C1AD18C251E4D454BA8A05CF92EE9AFCB77}_与代理的合照-子公司GT总经理Remy-总部集团CEO Mr Yias-陈雁-黄总（从左至右）.jpg', '', '', '最大竞争对手是海兴（技术和价格）', '', '通过RMY项目已经逐步熟悉该市场情况，应继续积累，努力扩大市场份额和影响力。', '', '1. 银河及时递交投标资料和报价方案，需特别注意对法语资料的审核，确保准确性，尽量减少现场修修改改；2. 代理客户关系的铺垫和把控', 'TLR项目采购数量虽然不大，但对于长久的市场耕耘来说也是前进的垫脚石，另注意到技术规格中有对AMI系统的需求，更是一个很好的着力点。建议立项。', '陈雁2019-12-29 04:57:08', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('401', '{C79C69CE-AFBC-4BBD-9F13-D268092F58B8}', '60', 'INHE-0868', '2019-12-30 17:47:43', '0000-00-00 00:00:00', '2020-01-07 14:12:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2019123001/AFH', '', 'NPA-DABS-G-2685-ICB', '2020.1.11', 'Procurement of Single and Three phase digital Meters 采购单相和三相数字式电表', '价格条款：DDP\r\r\n付款主体：Public FUNDS（政府资金）.\r\r\n付款条款：1）DABS开立保兑LC；\r\r\n          2）80%见货运单据支付；\r\r\n          3）20%在业主发出接受证明30天内支付；\r\r\n交期：单相表：接收通知后三个月内完成电表50000台交货，其余三个月内完成，共六个月；三相表：接收通知三个月内完成交货\r\r\n质保：5year\r\r\n备注：交货违约每周0.5%货款，最高10%。				  代理付款方式：从第三国，30%预付款+70%发货前 TT 或由银河接受的银行开出LC', '{C79C69CEAFBC4BBD9F13D268092F58B88442F4C2B3234363A3D51C033076BD50}_标书MeterS SBD.doc', '先评价格再根据资质和技术文件符合选择最低价中标（见P26，Section3）', '', '一家中标						', '', '投标保函：USD 111,000，有效期投标有效期后28天(120+28)，代理提供；\r\r\n履约保函： 6% of the total contract amount and valid for (contract Period + Warranty Period+28 days)，代理提供', '', '1. 制造商授权函（标书格式，P46）                                     2. 要求材料（标书P65清单，P67 5.1，5.5，5.6）.                       3. 资产证明（P27 a)                                                 4. 技术经验资质（P27 b)                                              5. 业务量要求（P28 c）                                                      ', '', '', '', '联合投标', '代理主投，代理负责开立所有保函，银河提供产品，用到银河技术和商务资质', 'DABS自主采购，评标。', '', '见货运单据支付80%货款，业主收货后，业主发出接收认证后三十天付尾款', '', '“Public Funds”是指根据政府预算拨给采购实体的任何货币资源，或法定机构和公司产生的收入或发展伙伴通过政府处置采购实体所获得的补助金和信贷。电力公司全部股权归政府部门所有', '{C79C69CEAFBC4BBD9F13D268092F58B8108D268797C74834B1DDE2FC1083AA37}_DABS report.pdf', '电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。', '', '尚未与DABS建立直接关系。', '', '思达，科陆。思达已在该市场供货近50万支表，科陆多次参加投标，暂未供货', '', '利用合作伙伴在DABS电力公司的人脉关系和渠道。', '', '相关测试报告，资质认证符合要求，市场价格偏低。', '1.此项目为联合投标，代理主投。投标保函，履约保函由代理提供                                            2.不需要样机，只需准备相关商务和技术文件，扫描发给代理。                                                3.代理以前与思达合作有过成功案例，对电力公司和项目情况有一定关系和了解', '庄钦2020-01-06 10:32:00', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('402', '{3BD36129-6D29-4DDF-BAE0-63751D6E24F8}', '60', 'INHE-0434', '2020-01-04 10:59:01', '0000-00-00 00:00:00', '2020-01-07 13:52:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010401/TND', '', 'Rfx4000032323', '2020年1月21日', '用于智能账单项目部署的智能计量表的供应和交付PEMBEKALAN & PENGIRIMAN SMART METER FOR SMART BILLING PROJECT DEPLOYMENT', '电力公司与DPM之间：\r\r\r\n1. 报DDP价格（DPM负责马来境内运输，清关，管理）\r\r\r\n2. 无预付款；\r\r\r\n3. 若供货地点在马来西亚属地管辖内，将在收到供应商的发票后30天内支付\r\r\r\n4. 第一个交期为正式订购单发出日期后的八(8)至十六(16)周，第二个交期是正式采购订单日期后的四(4)周。如有需要，TNB保留更改船期的权利\r\r\r\n5. 质保：电表交付之日起5年\r\r\r\n6. 违约金：\r\r\r\n6.1 按合同金额的0.15%/天\r\r\r\n或\r\r\r\n6.2 按延期交货合同价格的0.15%/天(长期供货)\r\r\r\n6.3 最高不超过合同金额的15%\r\r\r\n故障率：单份合同下电表可接受的故障率为0.1％（未能满足的，中止/终止合同）。\r\r\r\n罚款：对每台表故障的罚款最低为RM30.00，最高为每台表的成本。\r\r\n\r\r\nDPM与银河之间：LC付款', '{3BD361296D294DDFBAE063751D6E24F88442F4C2B3234363A3D51C033076BD50}_VOL 3.pdf', '先评技术，后评商务\r，通过技术以及商务评审再开价格。\r\r\r\n\r\r\r\r\n1. 任何不符强制性门槛要求的，将出局，不能进入下一轮评估\r\r\r\r\n2. 投标有效期内撤回报价将从TNB投标中列入黑名单。\r\r\r\r\n3. 完整地、按模板填写所有投标表格M，尤其是（Volume 2 Borong F 技术应答表) \r\r\r\r\n4. 投标评估过程将基于报价、供货经验、投标者的生产能力/交期、所提供的材料/样机质量。', '', '不仅限一家中标', '', 'DPM负责投标保函，履约保函以及质保保函的开立', '', '无公司年限要求，DPM需提交近12月财报，股本股东权益为正，实收资本大于RM 750,000 ，速动比率大于等于1.0，NMIM测试报告、SIRIM测试报告，COA证书，\r\r\r\r\n，SIRIM QAS证书，至少1年为其他电力公司供应同型号智能电表至少10万套；需要提交电力公司证明文件/用户证明，电表型号相同。', '', 'SIRIM QAS证书已过期，DPM希望1月14~17日完成，需安排江西工业园提供支持\r（代理安排SIRIM机构来人验厂验产品）\r\r\n脉压10KV，IP54防护等级，需提供型式测试报告（有广东计量院出具的单相模块表、三相模块表10KV测试报告。但广东计量院不是标书指定实验室，此为不符点），最迟需1月17日前提交', '', '代理商投标，银河直供给DPM', '', 'TND为电力公司邀标项目，主要决策在TNB', '', '电力公司与DPM之间：\r\r\r\r\n1. 无预付款；\r\r\r\n2. 若供货地点在马来西亚属地管辖内，将在收到供应商的发票后30天内支付\r\r\r\n\r\r\nDPM与银河之间：LC付款						\r\r\n', '', '业主支付能力没问题', '', '代理与项目经理以及采购部主管有一定关系，综合竞争力不足需提升，DPM内部更换了员工，老板性格较为沉稳', '', '与前项目经理有一定联系', '', '竞争对手：1. FH System（与Itron合作） 2. MIM（与深科技合作） 3. Iskraemeco（Iskraemeco本地工厂） 4. Krizik（与Secure合作） 5. Deltaprima（与银河合作） 6. MISA（与Genus合作） 7. SMT（与鼎信合作）,上一个标的投标价格都高于最终成交价', '', '从上一个项目拿到产品成交价，DPM尚未供货智能表给TNB（本地表厂仅Krizik为上一个项目中标方）\r\r\r\n\r\r\r\n竞争策略：\r\r\n1、确保银河满足技术强制要求，否则在第一轮评标将会出局\r\r\n2、确保DPM商务资质没问题，否则在第二轮评标将会出局\r\r\n3、结合TNB上一个项目产品成交价与代理协商TND最终投标价\r\r\n4、去一线联合代理获取项目经理以及采购部主管支持', '', '务必确保技术强制要求满足标书要求，样机满足标书要求，否则在第一轮评标将会出局。报价需结合上一个项目产品成交价做调整。需TNB尤其评标团队里有支持DPM/银河的人，及时反馈评标进展。', '1、上一个即TNB项目有不是表厂也中标，显示DPM实力存在不足（我方投标资料准备也尚不充分）；\r\r\r\n2、DPM对智能表项目也感兴趣，否则不会又是建厂又是投入兼容；\r\r\r\n3、TND为针对本地7家表厂邀标，当前再找其他本地表厂来不及；\r\r\r\n\r\r\r\n综合评估：建议公司同意TND立项并做好充分准备竞投。', '钟云林2020-01-04 13:11:47', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('403', '{F57C5895-4A04-4C74-A3E0-F4BC86BFE9A2}', '60', 'INHE-0781', '2020-01-04 17:15:05', '0000-00-00 00:00:00', '2020-01-07 13:56:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010501/BPA', '', '27.11.0000.304.20.222.19', '2020.1.23', 'DESIGN, SUPPLY, INSTALLATION, TESTING, COMMISSIONING OF ADVANCED METERING INFRASTRUCTURE (AMI) INCLUDING UPGRADATION OF UNIFIED PREPAID SYSTEM ON TURNKEY BASIS WITH 3 YEARS SERVICE (OPERATION & MAINTENANCE) AGREEMENT AFTER WARRANTY PERIOD. 供应，安装，测试和调试AMI系统，其中包括基于交钥匙工程基础，包含保修期满后三年运维服务的对Unified系统的升级项目。', '电力公司仅付款给JV的主投方，主投方再付款给个分包商。付款分为外汇和当地币，外汇支付设备、物质软件等系统的采购，安装、调试、运维服务等，本地币支付本地运输、保险、服务等相关费用。\r\n项目完成时间至合同签署40个月，项目交付后需提供36个月的质保期，质保期结束后需再提供36个月的运维服务。', '', '先做技术评标，再做商务评标，', '', '一个LOT,一家中标', '', '投标保函53.2万美元；履约保函合同总金额10%，覆盖工程安装期40个月+质保期3年+28天', '', '1.过去10年里完成至少2个合同金额在18亿塔卡（约2118万美元）以上，与此AMI项目具备相似性质、复杂性和方法/施工技术的项目（主投人必须独立满足）；\r\r\r\n2.过去3年年均营业额在75亿塔卡（约8824万美元）以上；\r\r\r\n3.投标人最低流动资金/营运资金/授信额度在12亿塔卡（约1412万美元）以上；\r\r\r\n4.MDMS供应商必须提供其所供系统在过去5年中，至少有2年名列Gartner list，Magic Quadrant for Meter Data Management Products；\r\r\n5.主要系统和部件（电表、RF模块、MDMS、HES）等供应商必须提供过去7年内，来自于电力公司证明其供应产品稳定运行两年以上的用户证明。', '{F57C58954A044C74A3E0F4BC86BFE9A203404677E4D44E9EB56B3D512B2AF9CC}_资质条件.rar', '研发部门需根据技术解析准备相应技术方案。', '', '暂定联合投标', '单纯银河无法满足资质要求，需联合投标。银河主投，负责表计、RF模块、MDMS、HES、AMI基础设备，代理负责表计安装、AMI基础设备安装、运营维护、市场关系等。双方按各自合同份额承担履约保函职责。', '此项目主要决策权在能源部', '', '设备物资采购：\r\n1.10%预付款，即期L/C，签署合同并提交履约保函后支付；\r\n2.60%货款，发货并提供货运单据；\r\n3.10%到货验收后；\r\n4.10%,项目交付并取得临时验收证明；\r\n5.10%，取得临时验收证明，并开具覆盖三年质保期的保函。\r\n硬件、软件、网络设计和其他服务：\r\n1.10%预付款，合同签署，并提供覆盖40个月工期的履约保函后支付；\r\n2.70%设计被认可并提交相关证明后45天内；\r\n3.10%拿到临时验收证明后；\r\n4.10%拿到临时验收证明且开具覆盖3年质保期的履约保函。\r\n', '{F57C58954A044C74A3E0F4BC86BFE9A2DC30B63FF962416CACC9A604CE6ABE1F}_付款条款.rar', 'BPDB运营良好，支付有保障。', '', 'IEEL在当地电力行业经营三十多年，在BPDB和能源部均具备相当深厚的人脉关系，MD本人市场活动能力强，安装运营团队经验丰富。 ', '', '银河已在BPDB供应大量电表，同时正有项目在执行，具备相当的客户美誉度', '', '此项目资质要求高，主要竞争对手将是欧美厂家，尤其是兰吉尔，才通过能源部长拿下了DPDC类似项目，此项目的运作痕迹也很类似他们的手笔。', '', '因此项目要求很高，银河不仅在资质上存在诸多不足，而且在项目经验、公司实力、技术方面全方面都落后与欧美厂家，电力公司也比较倾向于欧美厂家。从现状来看，银河的胜算很小。但是，银河如果想向更高端发展，这种项目就必须要参加，在实战中积累经验。而且我们也不是完全没有优势，一方面我们在BPDB已供应大量电表，积累一定的产品美誉度，另外欧美厂家的成本始终是最大的劣势。', '', '此项目资质要求高，技术复杂，项目难度大，需要研发部门组织最精干力量来准备相关资料、方案及演示等。', '此项目难度极高，电表反而居于次要地位，基本可算又是为欧美厂家量身定做的项目。现在我们一方面在让代理尝试运作能降低某些条款，另一方面也在积极寻找合适的合作伙伴。个人建议先立项，努力参与进去。', '李启坦2020-01-06 02:02:10', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('404', '{2AA0A186-7398-4F3C-95B2-94CDF4FBBFA3}', '60', 'INHE-0781', '2020-01-09 04:22:19', '0000-00-00 00:00:00', '2020-01-13 10:05:21', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010901/WZP', '', '27.22.4785.905.50.040.19/346', '2020.01.27', 'Design, Manufacture, Supply, Installation, Testing & Commissioning of 1,05,000 nos. Smart Pre-Payment Meter with Related Services on Turn Key Basis. 基于交钥匙工程基础的，制造，供应，安装，测试和调试105000台智能电表及相关服务的工程', '暂定商务合作方式为：中标后，代理开具100%不可测试即期信用证给银河，发货后凭相关单证收取货款。', '', '先做资质预审，合格厂家会被通知做技术演示，在演示前需完成与WZPDCL现有Unified系统及HES的兼容工作。技术演示合格后的厂家，再开价格标，低价中标。', '', '一个LOT，一家中标', '', '所有保函均应该由国际知名银行在当地分支机构或者当地知名银行开具。投标保函金额USD212140.00,有效期120+148天；履约保函10%的合同金额，覆盖自收到中标通知到质保期结束30天后。', '{2AA0A18673984F3C95B294CDF4FBBFA31DD410FC292E4E1893AFBEF9F88431CD}_投标保函.jpg', '1.过去5年至少一个合同供应50000台PLC通信智能电表+250台集中器；\r\r\n2.提供在过去5年内2份以上来自于电力公司的类似项目的用户证明，其中至少一份来自于制造商本国以外的电力公司，用户证明上需要使用该电力公司抬头，注明电话、传真及Email等联系方式；\r\r\n3.制造商需提供过去5年内主要硬件（智能电表，集中器等）的供货记录；\r\n4.流动资金9.5亿当地币（约1120万USD）以及其他常规要求。', '{2AA0A18673984F3C95B294CDF4FBBFA303404677E4D44E9EB56B3D512B2AF9CC}_资质要求.rar', '需准备2份来自第三方厂家的授权函，授权使用我们的集中器来兼容他们的电表', '', '暂定联合投标', '此项目属于交钥匙工程，除工程安装、维护之外，还有售电站点、网络架构建设等，与代理联合投标有助于发挥各自的优势。暂定代理主投，银河负责供应电表、集中器等产品，代理负责项目运作、安装、维护、运营等其他工作。', '此项目主要由电力公司内部决定，但能源部也具有相当影响力。', '', '无预付款\r\n70%，L/C，发货后凭相关单据申请付款；\r\n10%，L/C，到货并验货后付款；\r\n10%，L/C，临时验收后付款；\r\n10%，L/C，临时验收3年后，获得终验报告后付款。', '{2AA0A18673984F3C95B294CDF4FBBFA3DC30B63FF962416CACC9A604CE6ABE1F}_付款条件.rar', '此项目来自孟加拉国政府资金及电力公司自有资金，来源有保障。', '', '代理在能源部和电力公司均有广泛的关系，有专人在当地打理关系，电力公司从上到下都很熟。', '', '银河已在当地有项目执行，与电力公司相关人员均有较多接触，银河的产品也得到了广泛的认可。', '', '主要对手是海兴，他们拉来华为一起推宽带PLC，可能增加一点变数。', '', '这个项目我们通过标书运作，有成功的埋一些雷进去，因此理想目标是能高价中标。但因为海兴跟华为最终也将宽带PLC做了进去，因此也得万一要拼价格的打算。', '', '因为前期工作消耗太多时间，再加上又有春节的因素，现在时间很紧，其中还有第三方兼容样机与Unified兼容的问题，继电器还双路继电器的问题，因此样机制作需要得到研发及实验室的大力支持。', '此项目我们通过前期运作，已具备不少优势。现在需要的就是利用好这些优势，争取能以较好的价格中标。', '李启坦2020-01-09 05:39:13', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('405', '{7163BCA9-87BD-4A02-A2F1-5B0E8F10B670}', '60', 'INHE-0781', '2020-01-09 13:23:03', '0000-00-00 00:00:00', '2020-01-13 10:00:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010902/WEP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目使用的是以前DPDC601的产品，仅需提供部分库存产品做测试，不需要我们过多的资源投入。而且可以为我们在公开招标之外再开辟一块新的市场，因此建议立项。', '李启坦2020-01-09 13:36:39', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('406', '{DCD553BE-5458-46FC-A8B2-62C40DF6F2F1}', '61', 'INHE-0772', '2020-01-10 16:10:04', '0000-00-00 00:00:00', '2020-01-13 14:54:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011001/MLH', '', '55/2019/PERREL', '2020年2月3日', 'PROJET D EXTENSION ET DE RENFORCEMENT DES RESEAUX ELECTRONIQUES(PERREL)电网扩展和加强计划（PERREL）', '与代理交易', '{DCD553BE545846FCA8B262C40DF6F2F18442F4C2B3234363A3D51C033076BD50}_AO 55 2019 PERRELDAO Acquisition Matériel de Branchement d\'exploitation et de maintenance.pdf', '评标规则非常简单：无本地保护', '', '允许一家中多个标段', '', '代理投标，代理公司开具', '', '伊斯兰发展银行成员国，或本地成分超过50%', '', '技术应答表，技术资料，商务投标文件，厂家授权函，截止时间 2020/02/01', '', '代理投标', '', '', '', '', '', '', '', '原西非代理Azon，与我司配合多年，有丰富投标经验', '', '', '', '思达，科陆，海兴，隆基，华立，ELSWEDY（业务常驻BFN）；BFN的价格竞争极为激烈', '', '我司资质不符，只能授权代理Azon投标,代理投标经验丰富是优势，但代理他本人的健康较差对客情的把控力有所下降。', '', '及时准备电表投标资料', '本标为伊斯兰发展银行资金，其要求投标人必须为该银行的成员国或公司为受益人本国国内公司，我司资质不符，必须授权代理投标。标书无要求样机，业务初步分析技术规格与MAF项目基本一样（请客服核实），准备电表部分投标文件即可，工作量不大。新年假期将至，建议在放假前将资料准备好。', '张子琦2020-01-10 17:56:26', '02', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('407', '{30609FDE-C5BC-4ECE-9218-4CA686507B00}', '61', 'INHE-0885', '2020-01-17 18:45:33', '0000-00-00 00:00:00', '2020-01-18 14:01:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011701/BST', '1.请核实代理实力和客情；2.请整理不服，说明应对策略；3.请延标。而后，再决定是否竞投。市场需要调研，提前开发，不能守株待兔。							', '3890-19', '2020年2月5日', '具有开放式标准通讯协议的单（1）相和三（3）相分离，3相集成GPRS STS预付款智能表的供应和交付THE SUPPLY AND DELIVERY OF SINGLE (1) PHASE AND THREE (3) PHASE SPLIT, 3 PHASE INTERGRATED GPRS BASED STS PREPAYMENT SMART METERS WITH OPEN STANDARD COMMUNICATION PROTOCOLS', '1.中标14内签署合同\r\n\r\n\r\n2.贸易条款DDP', '{30609FDEC5BC4ECE92184CA686507B008442F4C2B3234363A3D51C033076BD50}_Tender?no?3890-19-?The?supply?&amp#FE54`?delivery?of?Single&nbsp#FE54`&nbsp#FE54`?Three?phase?split?STS?Split?Smart?Meters?with?open?standard?protocols?(3).docx', '先评商务（评标打分规则详见附件中标书文件），再评技术标', '{30609FDEC5BC4ECE92184CA686507B00074E749A304748709C51373D9D483750}_Tender?no?3890-19-?The?supply?&amp#FE54`?delivery?of?Single&nbsp#FE54`&nbsp#FE54`?Three?phase?split?STS?Split?Smart?Meters?with?open?standard?protocols?(3).docx', '三家中标', '', '没有要求', '', '1.符合最低技术规格\r\r\n2.过去5年至少有3份类似的合同，用户证明\r\r\n3.产品测试报告\r\r\n4.权威机构的产品认证证明\r\r\n5.IDIS\r\r\n\r\r\n', '{30609FDEC5BC4ECE92184CA686507B0003404677E4D44E9EB56B3D512B2AF9CC}_表1：BST投标项目信息归纳表.doc', '1.用户证明文件\r\r\r\n2.产品测试报告\r\r\r\n3.厂家授权函\r\r\r\n4.产品概要图\r\r\r\n5.提供智能电表的保修详情\r\r\n6.IDIS认证（待核查）\r\r\n', '', '代理商投标', '代理商投标', 'BPC是国企，政府控制其走向', '', '电力公司在货物抵达后的14天内全额付款', '', '电力公司财务状况良好', '', 'Business Systems Experts Proprietary Limited\r\n\r\n\r\n在熟悉本地市场，在BPC有一定的客户关系', '', '一线客户关系一般', '', '主要竞争对手是海兴和兰吉尔', '', '1.熟络标书，提交完整的投标资料\r\r\r\n2.此项目先开商务标，可以通过商务标的结果有针对性的打击竞争对手\r\n3.将选择三家投标者中标\r\n\r\n', '', '熟络标书，通过代理运作客户关系，适当价格', '该项目为电表项目，电力公司决定进行大量的电表更换，目前是需要供应符合IDIS标准的电表。业务可以在春节期间实时跟进项目进展，如市场需要亦可以第一时间前往现场。', '潘健康2020-01-17 19:57:36', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('409', '{04794806-68ED-43AA-ACFE-2FBC4B015DCC}', '17', 'INHE-0450', '2020-01-18 18:22:31', '0000-00-00 00:00:00', '2020-01-18 18:22:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011803/t1132', '', 'TENDER No. PA/001/ 2019- 20/WZN/G/ 27', '', '', '\"TANESCO付坦先令。国内付款条件为： (1)无预付款和发货款。（3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                                         质保期限：接受货物起12个月，发货后18个月。交期：一年内交完各分订单/LPO的货。违约：百分之0.2/天，未发货产品，最多10%。', '', '\"', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '郭林鹏2020-01-18 18:23:39', '', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('410', '{902CA591-7799-4B41-8CEE-D079E9B3321B}', '61', 'INHE-0440', '2020-01-18 18:25:40', '0000-00-00 00:00:00', '2020-02-13 10:24:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011804/TTJ', '', 'TENDER No. PA/001/ 2019- 20/WZN/G/ 27', '1月24日', 'SUPPLY OF SPLIT TYPE METERS FOR WEST ZONE REGIONS UNDERFRAMEWORK ARRANGEMENT 框架合同供应分体式电表给西部各地区', 'TANESCO付坦先令。国内付款条件为： (1)无预付款和发货款。（3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                                         质保期限：接受货物起12个月，发货后18个月。交期：一年内交完各分订单/LPO的货。违约：百分之0.2/天，未发货产品，最多10%。', '{902CA59177994B418CEED079E9B3321B8442F4C2B3234363A3D51C033076BD50}_商务标书.doc', '框架合同国内限制性招标，只允许本地厂商参与。先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。\r\n', '', '只允许本地厂商投标，目前有5家工厂，每个厂家最多分2个LOTS，一个LOT可以分给不止一家厂家。', '', 'ITL/Africarriers 准备投标保证声明/投标保函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '2017和2018年审计的财务报告和银行流水。供应/生产类似规模产品的经验,人员资质，设备和生产能力，相关的注册证书等。', '', '技术应答表，非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （3）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，但支付信用证问题不大，目前银行融资额度为5百万美元。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理，区域的区域经理和等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表业务。', '', '配电副总，采购经理，电表部经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU等，EDMI主要支持者是电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix和Engineer。威胜主要支持者电表部经理，采购经理，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，高级配电经理，实验室工程师等。EDMI主要是供单相，三相分体式直通/CT/VT表。海兴目前暂无中标记录。威胜和CLOU主要供货单三相直通表，本地价格可以做到EXW 40 USD。目前市场上主要的本地厂家为ITL，EDMI，WASION, CLOU, HEXING, 其中ITL，EDMI,WASION和CLOU四家可以合作。\r\n', '', '本地限制性招标，电力公司主要开放给ITL，EDMI,CLOU和WASION, HEXING等。ITL目前已经和我司签了批量SKD合同，满足供货要求。框架合同，标书的技术规格为分体式单相和三相直通表。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员。我司支持ITL投标和中标的几率较大，可以在未来3年获得较稳定的订单来源。\r\n', '', '产品报价符合市场形势，技术支持，商务和研发人员响应到位，给予合作伙伴必要的技术和商务支持，必要的客户关系建设开销等。', '建议立项，准备文件，支持ITL投标和争取订单。', '汤伟2020-01-18 18:41:13', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('411', '{A54EB4FB-9782-43EB-B68B-04DC5F4D27F9}', '61', 'INHE-0500', '2020-02-05 16:25:19', '0000-00-00 00:00:00', '2020-02-13 10:27:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2020020501/ZIT', '', 'RBT 01/2020', '2020年2月27日', 'REQUEST FOR PROPOSALFOR THESMART ELECTRICITY METERING MANUFACTURINGSOLUTION IN ZIMBABWE限制性招标：招标针对津巴布韦能源管理局ZERA和电力公司ZETDC批准的6家合格制造厂商，银河、海兴、兰吉尔、Itron、EDMI和Iskarmeco招标内容：从以上6家OEM中寻找一家合作在津巴布韦建设电能表的SKD组装工厂', '价格条款：标书未注明，银河投标时做申明；\r\n付款主体：TelOne (Private) Limited\r\n付款条件：标书未注明，银河投标时做申明可以接受的付款条件；\r\n质保和违约条款：标书未注明，银河投标时做申明。', '{A54EB4FB978243EBB68B04DC5F4D27F98442F4C2B3234363A3D51C033076BD50}_doc10496920200204063433.pdf', '第一步：资格预审\r\n主要针对公司资质等进行评审，评审通过才能进入第二步：技术评审\r\n第二步：技术评审\r\n达到标书中要求的最低70%技术评分才能进入到第三步：价格评审\r\n第三步：价格评审\r\n提供JV合作融资的优先获得10%的综合优势评分\r\n', '{A54EB4FB978243EBB68B04DC5F4D27F9074E749A304748709C51373D9D483750}_RFP FOR SMART METERING BUSINESS V5.0 27-1-20.pdf', '一家中标', '', '无需投标保函，收到中标通知28天内需要开立履约保函', '', '限制性招标，只能从银河、海兴、兰吉尔、Itron、EDMI和Iskarmeco\r 六家厂商选择合作建厂伙伴', '', '1.需要工厂工程部根据该市场供货状况以及ZWS执行进展，制作建厂技术方案；\r\n', '', '此项目为限制性招标，招标对象为银河、海兴、兰吉尔、Itron、EDMI和Iskarmeco 六家厂商，只能由OEM投标', 'N/A', '1.此项目授标决策大概率不涉及到政府层面政客影响，招标的主要驱动在于ZIT公司计划在当前ICT设备组装厂的基础上增加电能表的组装，且由于是国有企业采购需要进行公开招标，评标层面决策主要在于该项目的项目经理团队，2019年10月项目经理团队已实地到访银河总部交流，反馈较好，标书中部分技术资料取用银河标准建厂技术方案；', '', '待了解。银河投标文件中做可接受付款条件的申明', '', '待了解。\r\n', '', '银河直接投标', '', '2019年10月项目经理团队已实地到访银河总部交流，反馈较好，标书中部分技术资料取用银河标准建厂技术方案；\r\r\n', '', '海兴：海兴预测是该项目最大竞争对手，预计会在合作方式上提出较有吸引力的合作方式；\r\r\n\r\n', '', '银河竞争策略：1.运用标书中已运作部分银河规格的优势，准时提交建厂技术和商务方案；2.待授标后到访现场协商付款条件和发货方式；3.开始接洽其他有兴趣的第三方合作代理洽谈融资。', '', '1.运用标书中已运作部分银河规格的优势，准时提交建厂技术和商务方案；2.待授标后到访现场协商付款条件和发货方式；3.开始接洽其他有兴趣的第三方合作代理洽谈融资。\r\n', '1.此建厂项目银河势在必得，需要准时提交投标资料，并准备好后期授标后的付款条款等融资谈判；\r\n2.需要针对该项目，联合业务、融资、财务提出建设性的财务融资方案，扩大项目金额和范围。', '李忠鹏2020-02-05 17:31:59', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('412', '{4D9A4D53-1DC3-47E4-859B-085F659C5826}', '60', 'INHE-0781', '2020-02-13 09:20:55', '0000-00-00 00:00:00', '2020-02-19 08:47:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020021301/NSO', '', 'NESCO/PD-SMP/2019-2020/152', '2020.03.02', 'Supply, Installation, Testing & Commissioning of Smart Pre-Payment Meter with related services on Turn-key Basis for NESCO Ltd.', '70%：L/C，提供货运单据后\r\n10%：L/C，业主出具验收证书后\r\n10%：L/C，安装和调试预付费系统后，提交文件（如临时验收证书，系统发票等）后支付\r\n10%：L/C，安装以及成功调试预付费系统后，出具最终验收证书后支付', '{4D9A4D531DC347E4859B085F659C58268442F4C2B3234363A3D51C033076BD50}_付款条款.png', '先做资质审核，然后做技术演示，进行技术评标，最后开价格标，低价中标。						\r\n', '', '一个LOT，一家中标', '', '投标保函金额：USD 290,000.00，有效期：150+28天，应为不可撤销的银行保函；履约保函为合同金额10%，有效期为完工后三年+28天', '', '1. 投标人在最近5年内的仲裁数不超过3次。\r\r\r\r\r\n2. 投标人必须合法注册，并有至少十（10）年在电力公司开展类似于招投标业务的经验。\r\r\r\r\r\n3. 至少有5年的电力公司交钥匙工程项目管理经验，AMI与通信网络和电力公司的硬件、软件、电表、DCU、HES、MDMS集成(兼容)的经验。\r\r\r\r\r\n4. 在智能电表部署的智能计量/ AMI交钥匙项目领域，投标人至少在近60个月（5年）内与两家电力公司有一般项目经验。 须提交至少两份用户证明。\r\r\r\r\r\n5. 投标人须提供DCU /模块化DCU和HES系统，该系统需要与电力公司现有系统整合，中标人必须要完成所提供电表和系统与招标人系统的整合与兼容工作。\r\r\r\r\r\n6. 投标人至少应在近60个月（五年）内，为两家电力公司提供智能电表/预付费电表。须提供来自电力公司的用户证明。为了确保兼容，投标人需要提供国际知名实验室出具的PLC标准化和性能认证。另外，对于那些PLC工作不正常或者采集成功率不高的地方，投标人需要替换成GPRS通信并自行承担所有成本。\r\r\r\r\r\n7. 厂商应在近60个月（五年）内有在单个合同里成功供应至少50,000 台智', '', '', '', '联合投标', '此项目为包含安装、调试和后续维护的交钥匙工程，因我们暂不具备这些能力，必须具有一个本地机构承担这些职责，同时替我们承担收款风险。因此必须以JV形式投标。因标书明确要求主投标人必须是电表厂商或者系统厂商，因此银河将作为主投标人。', '能源部对NESCO具有相当大的影响力。', '', '见上述付款条件', '', 'GOB项目，资金支付有保障。', '', '合作代理与电力部以及电力公司有较好关系，尽管在NCO上运作失败，但暂时还没有发现更合适的合作伙伴，同时因为疫情的影响，暂时还没法由我们直接运作，因此先更现有代理合作相对最合适。', '', '银河产品有一定的知名度，但是与电力公司直接关系的建立尚需时间，暂时只能依靠代理。', '', '此项目的竞争对手主要为海兴、思达、科陆、林洋、三星、开发这些常规竞争对手，其中思达的竞争力最强，上个项目直接由能源部长打招呼，内定给他们。此项目据说也是内定，但能源部人事上可能有变动，有了松动空间。', '', '我们有PLC项目的实施经验，因此在技术及成本控制上将更有优势，劣势则主要是客户关系这一块，受疫情影响，我们暂时难以直接去做客户关系，只能通过代理，而这导致难以直接和思达竞争。此外，与电力公司现有系统的兼容，预计思达也将从中作梗，到时候需要重点做电力公司关系，由他们推动。', '', '此项目被运作的痕迹很重，因此需要技术人员更周到细致的查阅标书，查出隐藏的暗雷。此外，与现有系统的兼容方面主要是提供技术方案供电力公司评审，需要投入足够人力认真整理。', '思达现在市场关系投入很高，同时近期BKW，NCO两个项目接连高价成功中标让他们利益链上的一串人都获益很多，这个项目基本内定给了他们。但是，紧随其后还有一个项目，如果他们都吃掉引起的反弹太高，因此代理认为还是有一定的争取空间，建议立项。', '李启坦2020-02-17 17:50:18', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('413', '{CDE7B452-87EC-4A41-87F3-B4A04DAAEA6D}', '60', 'INHE-0781', '2020-02-18 16:25:55', '0000-00-00 00:00:00', '2020-02-20 17:51:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2020021802/NCT', '', 'NESCO/PD-SMP/2019-2020/159', '2020.03.10', 'Supply, Installation, Testing & Commissioning of Smart Pre-Payment Meter with Related Services on Turn Key Basis for NESCO Ltd.', '70%：L/C，提供货运单据后#FE54`\r\n10%：L/C，业主出具验收证书后#FE54`\r\n10%：L/C，安装和调试预付费系统后，提交文件（如临时验收证书，系统发票等）后支付#FE54`\r\n10%：L/C，安装以及成功调试预付费系统后，出具最终验收证书后支付.', '', '先做资质审核，然后做技术演示，进行技术评标，最后开价格标，低价中标。', '', '一个LOT，一家中标', '', '投标保函金额：USD 290,000.00，有效期：150+28天，应为不可撤销的银行保函；履约保函为合同金额10%，有效期为完工后三年+28天', '', '1. 投标人在最近5年内的仲裁数不超过3次。\r\n2. 投标人必须合法注册，并有至少十（10）年在电力公司开展类似于招投标业务的经验。（十年运营资质）\r\n一般经验：3. 至少有5年的电力公司交钥匙工程项目管理经验，AMI与通信网络和电力公司的硬件、软件、电表、DCU、HES、MDMS集成(兼容)的经验。\r\n4. 在智能电表部署的智能计量/ AMI交钥匙项目领域，投标人至少在近60个月（5年）内与两家电力公司有一般项目经验。 须提交至少两份用户证明。\r\n5. 投标人须提供DCU /模块化DCU和HES系统，该系统需要与电力公司现有系统整合，中标人必须要完成所提供电表和系统与招标人系统的整合与兼容工作。\r\n6. 投标人至少应在近60个月（五年）内，为两家电力公司提供智能电表/预付费电表。须提供来自电力公司的用户证明。为了确保兼容，投标人需要提供国际知名实验室出具的PLC标准化和性能认证。另外，对于那些PLC工作不正常或者采集成功率不高的地方，投标人需要替换成GPRS通信并自行承担所有成本。\r\n7. 厂商应在近60个月（五年）内有在单个合同里成功供应至少50,000 台智能电表/预付费电表/ ', '', '', '', '联合投标', '此项目为包含安装、调试和后续维护的交钥匙工程，因我们暂不具备这些能力，必须具有一个本地机构承担这些职责，同时替我们承担收款风险，同时标书又要求表厂作为联合体的leader，所以采取联合投标，银河主投的方式。', '能源部对NESCO具有相当大的影响力。', '', '见上述付款条款', '', 'GOB项目，资金支付有保障。', '', '合作代理与电力部以及电力公司有较好关系，尽管在NCO上运作失败，但暂时还没有发现更合适的合作伙伴，同时因为疫情的影响，暂时还没法由我们直接运作，因此先跟现有代理合作相对最合适。', '', '银河产品有一定的知名度，但是与电力公司直接关系的建立尚需时间，暂时只能依靠代理。', '', '此项目的竞争对手主要为海兴、思达、科陆、林洋、三星、开发这些常规竞争对手，其中思达的竞争力最强，上个项目直接由能源部长打招呼，内定给他们。此项目据说也是内定，但能源部人事上可能有变动，有了松动空间。', '', '我们有PLC项目的实施经验，因此在技术及成本控制上将更有优势，劣势则主要是客户关系这一块，受疫情影响，我们暂时难以直接去做客户关系，只能通过代理，而这导致在客户关系投入这一块难以和思达相比。此外，与电力公司现有系统的兼容，预计思达也将从中作梗，到时候需要重点做电力公司关系，由他们推动。但因为同时两个项目发标，思达也难以都吃下引起的反弹太大，因此代理认为这个项目的希望还是很大的。', '', '此项目被运作的痕迹很重，因此需要技术人员更周到细致的查阅标书，查出隐藏的暗雷。此外，与现有系统的兼容方面主要是提供技术方案供电力公司评审，需要投入足够人力认真整理。不过要求基本与NSO一致，可以同时处理。', '尽管有消息来源这个项目也被内定，但是因为同时两个标发出，都内定给一家引起的反弹太大，经代理与电力公司及能源部相关人士沟通，这个项目我们将会具备一定的优势，因此建议好好准备，全力拿下。', '李启坦2020-02-18 17:24:21', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('414', '{6DC9A7E8-9CE5-45B6-A573-AE139664C7C2}', '60', 'INHE-0781', '2020-02-20 11:12:16', '0000-00-00 00:00:00', '2020-02-24 09:15:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022001/BPB', '', '27.11.0000.304.20.248.20', '2020.4.2', 'Supply of Single Phase & Three Phase Solid State Smart Prepayment Meter with modem under Existing unified Pre-payment System for Chattogram and Cumilla Zone.提供带用于在现有Unified预付费系统下的通讯模块的单相和三相固态智能预付费电表。', '电力公司对代理：无预付款,70%收到发货单据后支付，30%到货验收合格后30天内支付。\r\n代理对银河：100%不可撤销L/C，银河发货后凭单据收取全部货款。', '', '先做资质审核，然后做技术演示，进行技术评标，最后开价格标，低价中标。', '', '一个LOT,一家中标', '', '投标保函及履约保函由代理负责', '', '1.过去5年内仲裁次数不超过3次；\r\n2.至少3年以上投标产品的供货经验；\r\n3.在过去5年内，不超过两个合同的情况下，类似投标产品的供货金额需不少于180万美元；\r\r\n\r4.最小年供应量/产能不小于两倍标书需求量（10万单相表，1万三相表）；\r\n\r5.流动资产不少于供货金额的150%。\r\n\r6.单三相表均需提供国际权威实验室测试报告（KEMA,SABS,MID等）\n\r\n\r\n', '', '', '', '代理商投标', '', '能源部对项目有一定影响力，主要由BPDB内部高层决策。', '', '见上述付款方式', '', 'BPDB预算收入下的现金外汇，支付有保证。', '', '代理在能源部及BPDB均有良好的关系，我们有一个5.5万台4G表项目正在执行中，此项目把握较大。', '', '银河的产品在BPDB大量使用，具有相当的产品美誉度，客户关系也还不错，但尚未建立较深的利益关系，因此还是需要代理来做。', '', '此项目资质要求不高，竞争激烈，主要还是拼价格。上一个项目由我们低价中标，但威盛报价仅比我们高出一万多美金，可算是险胜。但真正对我们构成较大威胁的，还是海兴、林洋等厂家。', '', '此项目因为是纯供货项目，技术标准相比之前，主要变化是零线也需要继电器控制，这样成本会有一定的上浮。上次项目，竞争对手都已经知道我们的中标价格，因此不排除有人会超出底线的压价，但我们没法跟进，因此运作重点将是资质审查与技术演示，需要代理的大力配合，同时我们自己也需要与相关人员保持畅通的沟通渠道。', '', '需要公司严格控制成本，尽量能提供有竞争力的价格。', '欧美大厂在全力争取在BPDB部署AMI项目，我们很难直接竞争。除了这个项目的85000台，后续很快还有另外一个85000台，因此我们需要抓住AMI未实际部署的窗口期，努力提高我们产品的占有率，后续才有较大的回旋空间。因此需要公司支持，全力争取这个项目。', '李启坦2020-02-20 16:13:05', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('415', '{9BD20E66-9B1E-4E2C-80C0-5E0E27571AD9}', '60', 'INHE-0680', '2020-02-21 11:08:35', '0000-00-00 00:00:00', '2020-02-24 17:33:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022102/MBO', '', '', '2020.3.4 下午 16：00', '阿塞拜疆电力2020年第一阶段采购单相智能电表 SMS', '\r\r\r\r\r\r\n预付款：30%\r\r\r\r\r\r\r\n付款主体：阿塞电力\r\r\r\n代理商：预付款30% ，余款：70%或信用证\r\r\r\n交期：签合同后1年内', '', '先开价格，后评审资质和技术，根据比较投标的标准，其得分最高，最高分将视为中标\r\n', '', '一家中标', '', '代理商开立', '', '代理提供自己资质，银河提供投标产品相关资料文件', '', '投标产品相关资料文件\r\n', '', '代理商投标', '否', '评标委员会审核资质，技术人员审核技术符合与否。', '', '签订合同后预付款30%', '', '采购预算来自政府，', '', '合作伙伴总经理与电力公司新任主席有交往，在之前合作伙伴总经理与电力公司新任主席秘密私下会面谈过此项目', '', '客户关系做到电力公司技术负责人（电表和系统）', '', '印度，埃及，英国，伊朗的表厂', '', '优势：通过前期努力，技术方面获得电力公司认可。搜集和分析竞争对手报价，引导代理投出价格为所有投标者里面最低。按时提供所有制造商所有资质文件，提醒代理商按时提交所有投标文件，引导代理商总经理与电力公司新主席达成协助，支持其中标。', '', '按时提供必要的投标文件和相关技术支持给代理商，必须引导让代理是投出最低价格，代理商总经理与电力公司新主席达成协助，支持其中标。', 'ASE项目和本次招标是独立的，ASE项目代理是通过在招标前运作，提供样机，完成试点，商务报价，签订合同，最后再走招标流程。\r\r\r\r\r\r\r\r\r\n本次招标是延续了之前向伊朗供应商采购的计划里面，初步判断银河产品满足此次技术要求，而且技术评审也是我们内线说了算，我们之前已经获得了试点验收证明。我们和内线的协议仍然生效。\r\r\r\r\r\r\r\r\r\n\r\r\r本次主要竞争对手仍然是伊朗供应商，目前除了伊朗供应商和银河的技术方面已经被技术部门认可外，其他供应商技术方面应该未被技术部门接纳。\r\r\r\r\n\r\r\r\r\r\r综合以上，向公司申请立项。\r\r\n								\r\r\r\r\r\n', '陈嘉豪2020-02-21 16:28:47', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('416', '{6D9413DF-7BFD-446D-8080-7B3AD4CF781C}', '61', 'INHE-0853', '2020-02-24 10:44:46', '0000-00-00 00:00:00', '2020-02-25 17:11:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022403/SBD', '', 'DAOI-N。BJ-PIU-36256-GO-RFB', '3月10日（正在沟通延标）', '贝宁能源服务改善项目（PASE项目）', '老代理AZON：按20%预付款，80%尾款，L/C结算。', '', '符合技术规格，价低者中标；', '', '一家中标，项目分两个部分：Part 1：按定单订购1,500电表（1,000个间接计量高压用户CT表和500个中压用户三相电表），并在2020年期间进行供应和安装；已确定订购1,500电表（250个间接计量高压用户CT表和1,250个中压用户三相电表），并于2021年供货；\r\r\r\r\r\r\r\nPart 2：第二批可能后续采购的订单，根据首批中标的执行情况是否让SBEE满意，再决定是否继续采购：3000电表（2750个中压用户三相电表和250个间接计量高压用户CT表）', '', '投标保函 25 000 000FCFA，截标日后120天有效；', '', '1.财务数据：近三年年营业额至少超过 2500 000 000FCFA；2.供货记录：近五年内至少有一例实施电表+AMI系统的合同经验，并提供相关用户证明验收证明等材料；3.测试报告：所提供产品可在40摄氏度高温状态下运行良好的证明；', '', '技术资料/样机规格书最迟2月28日提供：商务协助翻译，整理投标资料，申请和寄出样机；', '', '代理商投标', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '尤其是软件的报价要特别注意：1.软件开发费用：报价应包含前2年质保期内的开发费用，2年后才可额外收取；2.运营商的通讯费用应包含在报价内（代理报价）；3.软件维护费用：应包含软件的安装/调试/人员培训/软件版本更新费用，年维护费，及其他所有的属于维护范畴的费用。\"', '虽然此前的电表项目因为价格因素未曾中过标，本次为电表+软件的项目，我司售电系统已成功打入该市场并且正在做智能代理系统的试点，在软件方面还是有一定优势的。', '胡亚婵2020-02-24 15:39:29', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('417', '{A0DB2639-EC62-44C1-820E-BD511521570A}', '61', 'INHE-0913', '2020-02-25 09:47:34', '0000-00-00 00:00:00', '2020-02-26 18:45:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022502/MEB', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目为MEE项目内线介绍，可靠性较高，虽然项目数量较少，但有利于促进以后与电力公司内线与代理商继续合作，建议立项', '魏紫薇2020-02-25 10:10:14', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('418', '{F2536EA0-2265-4D01-91C0-9A25CC7AD7AE}', '93', 'INHE-0811', '2020-02-25 13:30:14', '0000-00-00 00:00:00', '2020-02-26 09:55:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022503/BGC', '市场总监选杨爱军（杨总）', 'N°: 01/IB13/AOI/REGIDESO/PHJIMU/F/2019', '2019/06/24', 'Jiji and Mulembwe Hydroelectric Project (PHJIMU)', 'DDP价格条款；付款条件：20%预付款（同等金额的保函），合同签订后30天内支付；60%合同款，业主提供其所在国银行保兑不可撤销的信用证，投标人提供相应的运输单据后支付；20%尾款，验收之后30天内支付，附买方验收证明；交期：见上（工期）；质保：电表及其设备的使用期限为10年，系统故障率每年不超过3次，出现故障时，系统恢复的时间不超过4小时，项目质保期限为1年；违约条款：延期交付的违约为每周合同额的0.5%，罚款总金额不超过合同额的10%\r\r\r\r\r\n', '', 'Review quotations, financial capabilities, bidder information, experience and technical capabilities评审报价、财务能力、投标人信息、经验与技术能力\r\n', '', '唯一标段Unique lot\r\n', '', '1.投标保函金额30000美元，有效期至标书失效之后28天；买方国家以外的银行需要在当地有合作行或转开行；2.履约保函金额为合同金额的10%，于验收28天后到期；3.预付款保函与合同预付款金额一致，有效期至交付完成\r\n', '', '投标人近四年的平均年度营业额不低于300万美元 The average annual turnover of bidders in the past four years does not exceed US$3 million；近4年内有2个类似的合同经验，并提供供货证明 2 similar contract experience in the past 4 years, and provide proof of supply；投标人公司存在的年限至少10年 The bidder\'s existence period is at least 10 years(P42)', '', '需要技术部门协助技术解析；截标时间为2019年6月24日，需要截标前两周完成\r\r\n', '', '银河电力名义投标 Bidding in the name of INHEMETER', '无\r\n', '该项目为世界银行IDA/欧洲投资银行EIB/欧盟EU/非洲发展基金AFD联合出资，项目招标方为布隆迪水电局，主要决策人是布隆迪水电局，出资人对该项目决策可产生一定的影响\r\r\nThe project is jointly funded by IDA/EIB/EU/AFD.The bidder is the REGIDESO-Burundi. The main decision maker is theEGIDESO-Burundi.The funders can have certain influence on the project decision.\r\n', '', '供应商提供发票其其他相应单据后，向买方和银行申请支付\r\r\nAfter the supplier provides the invoice with its other corresponding documents, it applies to the buyer and the bank for payment.\r', '', '银行及国际机构出资的项目，风险较小\r\r\nWe are facing less risk from project funded by banks and international institutions.\r', '', '我们的合作伙伴与水电局保持良好的关系，可以帮助我们竞标，收集市场及项目信息，建立客户关系\r\r\r\r\r\nOur partner has a good relationship with the utility company to help us bid, collect market and project information, and build customer relationships.\r\r\r\r\n', '', '\r\r\r\r\r\n银河已经与布隆迪水电局的CEO及技术顾问等客户建立了良好的客户关系，对于之后的项目竞标有很大的帮助\r\r\r\r\nINHE has established good customer relationships with clients such as the CEO and technical consultant of the Burundi utility company, which will greatly assist in the subsequent bidding for the project.', '', '之前为该国家供应电表的厂家有海兴/宁波三星等中国厂家，主要的竞争对手为海兴电力，海兴的价格及项目的预算有一定的了解', '', '银河在该市场有实力较强的合作伙伴，与高层客户建立了联系\r\r\r\r\nINHE has strong partner in this market, and has established contacts with senior customers of utility company\r\r\r\r\n', '', '我们在布隆迪有可靠的合作伙伴，有高层客户关系，而且银河有大用户计量领域有专业的经验，这些是该项目成功的关键；需申请技术解析以及商务组提供总部类似的经验及供货证明\r\r\r\r\nWe have reliable partners in Burundi, high-level customer relationships, and INHE has professional experience in LPU smartmetring, which is the key to the success of the project#FE54` we need to apply for technical analysis and business team to provide similar experience and proof of supply.\r', '', '宁桃美(Viki Ning)2020-02-25 14:52:24', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('419', '{03C33468-9FCE-457E-987E-B68BFFDCB82F}', '61', 'INHE-0885', '2020-02-25 13:43:01', '0000-00-00 00:00:00', '2020-05-28 11:05:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022504/SRI', '', 'ICB No : EEU/AMI/ICB 001/2012', '待定', 'Design, Manufacturing, Supply, Installation and Commissioning of Advanced Metering Infrastructure (GPRS Meters and Associated Facilities) System 设计，制造，供应，安装和调试 AMI（GPRS及相关设施）系统', 'Schedule NO. 1-3 海外/Schedule No. 6本地供货：\r\n1. 预付款:合同总时间表的10％作为预付款的发票收据，并以埃塞俄比亚任何信誉良好的银行作为担保的买方柜台开出的等额预付款保证金。 如安装服务发票所示，预付款保证金可能会与承包商完成的工作价值成比例地减少\r\n2.项目期间：60% LC：合同总价的百分之六十（60％）将通过提交给运输商及其他相关文件的，对供应商有利的不可撤销信用证来支付。\r\n3. 验收后：25% TT：AMI电表的安装完成和相关服务完成并由采购商和承包商共同核实后，此时间表下总合同价格的百分之二十五（25％）将通过电汇（TT）支付。\r\n4. 责任期后：5%，从开始到结束，两（2）年AMI电能表的运行和维护调试。\r\n\r\n\r\nSchedule No. 4安装付款方式：\r\n1. 预付款:合同总时间表的10％作为预付款的发票收据，并以埃塞俄比亚任何信誉良好的银行作为担保的买方柜台开出的等额预付款保证金。\r\n2. 安装中: 80%\r\n2.1. AMI电表安装付款?每位客户完成AMI电表安装后，付款的30％（百分之三十）由购买者和承包商共同核实。\r\n2', '{03C334689FCE457E987EB68BFFDCB82F8442F4C2B3234363A3D51C033076BD50}_1?Bidding?Procdure.pdf', '1.	初步评标，确认标书的完整性#FE54`填妥并签署的投标书#FE54`委托书#FE54`投标保证金#FE54`提供证书,投标的有效性；合格国家的投标人。\r\r\n2.	技术评标\r\r\n3.	商务评标，投标价格#FE54`调整价格以纠正算术错误#FE54`因折扣而调整的价格#FE54`不符合和遗漏的调整#FE54`适用所有评价因素、评价和资格标准#FE54`和由于适用优惠幅度而作出的调', '{03C334689FCE457E987EB68BFFDCB82F074E749A304748709C51373D9D483750}_PART?3?GC.pdf', '共1个Lot，一家中标', '', '投标保函\r\n1. 投标保函开立金额：USD 400,000\r\n2. 投标保证金应由信誉良好的银行提供无条件的银行担保，并必须由埃塞俄比亚商业银行提供反担保，有效期在原投标有效期后30天\r\n3. 投标有效期为自开标之日起90(90)天。投标保证金的有效期为投标有效期满后30天。\r\n\r\n履约保函\r\n1.	承包商应在合同授予通知后的二十八（28）天内，按照PC中规定的数量，为合同的应有履行提供保证书。\r\n2.	PC 6.3绩效保证金（占合同价格的百分之十（10％））和ESHS绩效保证金（占合同价格的百分之二（2））应减少为合同价值的五（5）％和合同价格的两（2）％ 分别。', '', '财务能力：\r\n1. 过去5年未出现未履行合同的情况\r\n2. Not being under execution of a BidSecuring Declaration pursuant to ITB 4.6 for 3 years（标书应有误，无ITB4.6）\r\n3. 所有未决诉讼的总额不得超过出价人对出价人净资产的50％\r\n4. 过去5年财报，以证明投标人财务状况的当前稳健性及其长期预期 盈利能力。\r\n5. 在过去五（5）年内（自2015年1月起），根据已收到或已完成合同的总认证付款额计算的最低平均年营业额为4000万美元。\r\n\r\n技术和经验：\r\n1. 竞标者必须具有将AMI解决方案与SAP ERP集成的经验。\r\n2. 投标人必须具有建筑控制/指挥中心的运营监控经验。\r\n3. 过去5年至少完成了三份价值2500万美元的类似合同，并提供详细说明\r\n4. 制造商应有10年以上电表经验，因已供100万台电表或有7500万美元的订单\r\n5. 竞标人过去5年已成功完成至少3个合同具有相似的性质，价值和复杂性\r\n6. 投标人至少提交三（3）张证书，地址明确，例如电话和传真号码，电子邮件地址等他', '', '技术资料需要客服协助评估', '', '银河投标', '银河投标', '国企，政府直接控制走向。电力公司EEU的最终决策人为埃塞教育部部长，直接控制EEU，并做最终决定。', '', '按付款方式进行付款', '', '世行资助项目，付款无障碍', '', '银河直投', '', '一线有一定的客户关系，正在逐步公关SRI项目的重点决策人。\r\n', '', '竞争对手主要是海兴，西门子，科陆，itron，许继仪表。许继在本地有设立工厂，此项目上有明显运作痕迹。					', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\n2. 业务自行并推动代理运作客户关系，同时把控评标团队，实施竞标策略\r\n3. 获取招标预算，报出合适价格', '', '1. 完善的投标文件，适当的报价\r\n2. 跟进已有的客户关系，推动高层\r\n3. 后续待正式开标后待定	', '该项目为AMI-LPU-EPC项目，项目预算金额大，值得参与投标和运作。银河已经提前拿到标书文件，目前尚未开标。银河可以提前做好准备，完善投标资料等工作。', '潘健康2020-05-25 16:21:14', '03', '★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('420', '{4FF4DC43-859F-47F5-BE33-F6E9DCD74CE0}', '66', 'INHE-0634', '2020-02-25 16:26:56', '0000-00-00 00:00:00', '2020-02-26 13:30:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022505/WLM', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '需要客服部完善制作专业的技术规格书作为合同附件。', '付款方式：100%TT预付；贸易条款：CIF仰光；交期：付款后75天内到仰光港口；质保：1年。根据客户需求，我已经推荐了PAR项目中使用的单三相表计和短信售电方案。（注：与PAR项目的关键不同点，表计安装在用户可及处，不需要CIU，表计需要带键盘）个人认为，付款方式好，且我们在缅甸已有多个类似的微电网项目经验（表计和系统全套），产品和方案的要求很基础不涉及研发，建议立项。', '陈雁2020-02-25 16:45:53', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('421', '{F104B1DA-841D-423A-9EB2-3C4A5B619B72}', '60', 'INHE-0781', '2020-02-26 08:58:18', '0000-00-00 00:00:00', '2020-02-26 20:06:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022601/PDT', '', 'G Central/SE-C&P/19-20/018', '3.23', 'Procurement of Single Phase Pre-payment Energy Meter单相预付费电能表的采购', '此项目银河仅为供货方，代理中标后开具100%即期不可撤销L/C予银河，发货后凭单据收取100%货款。', '', '网上提交投标资料，初审合格后送样机到电力公司实验室测试，测试合格且价格最低者中标。', '', '一个LOT，一家中标', '', '投标/履约保函均由代理负责', '', '5年运营资质，2份以上电力公司终端用户证明，80000台单相电表以上的产能要求。', '', '', '', '代理投标，银河仅作为供应商授权给代理。因为此项目为本地标，一般默认由当地企业可以参与。', '', '此项目数量不多，又为单纯的电表采购项目，在维持基本的客户关系前提下各自拼价格，电力公司内部高层即可决定项目归属。', '', '见上述付款条款', '', 'DPDC经营稳定，业绩稳步增长，资金来源有保证。', '', '代理在电力行业深耕多年，之前在DPDC也有中标多个项目，客户关系很深。', '', '银河已在电力公司供过类似电表，也去电力公司做过宣讲，产品具备相当的美誉度。', '', '此项目要求简单，资质要求不高，主要拼价格，除国内厂家之外，当地很多小厂也会参与。', '', '银河之前有给DPDC供应过类似产品，模具等都是现成的，技术要求比较熟悉，成本控制上应该也具备一定的优势。', '', '此项目价格是关键，需要注意成本控制。', '此项目数量不多，技术要求相对也低，主要就是拼价格。但因为我们之前有供应过类似的电表，同时作为供应商授权代理投标，仅需准备样机（初步看可使用库存）及部分投标资料，需要的资源投入很少，建议参加。', '李启坦2020-02-26 17:03:41', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('422', '{CC732B4E-B62E-489D-AA2B-500544949850}', '93', 'INHEGRID-0013', '2020-02-26 10:17:12', '0000-00-00 00:00:00', '2020-02-27 15:51:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022602/RCI', '配电补流程项目', 'RW-EUCL-110835-GO-RFB', '2019年8月30日，10:00（GMT+2)Date: 30/08/2019 Time: 10.00 Hours local time (08.00 Hours GMT)', '向EUCL供应1000台大用户智能电表（600台三相四线电表及400台100A三相直通表）Supply of One Thousand (1,000) Smart Meters for EUCL Big Customers (600 Three Phase 4 wire Electronic Meters and 400 Three Phase 100A Direct Connected Meters)', '价格条款：CIP Kigali, at EUCL Warehouses/ Stores in Gikondo付款主体：ENERGY UTILITY CORPORATION LIMITED (EUCL)付款条件：10%的预付款：在合同签订、收到预付款保函之后的45天内支付 ；80%的货款：在货物装船后以信用证支付；10%的尾款：在货物验收后、颁发验收证明后的45天内支付；(i) Advance Payment: Ten (10) percent of Goods supplied from abroad shall be paid within Forty Five (45) days of signing of the Contract, and upon submission of claim and a bank guarantee for equivalent amount valid until the Goods are delivered and in the form provided in the bidding documents or another form ac', '', '符合资质条件，符合技术标准的价格最低者。lowest-evaluated and substantially responsive bid is qualified to perform the Contract satisfactorily。.交期对评标的影响：交期每比要求的最早交期晚一周，影响价格因数为0.5%；Deviation in Delivery schedule: Yes. The adjustment factor will be 0.5% of the bid price for every week later than the Earliest Delivery Date and before the Latest Delivery Date.						\r\n', '', '唯一标的one lot						\r\n', '', '投标保函bid security: 金额：10000USD；货币：美元或其他可自由兑换货币；有效期：投标有效期+28天；开立行资质要求：资格国家内的公认银行、当地金融机构；开立方式：银行保函、不可撤销的信用证、支票；amount：10000USDCurriencies: USD or a freely convertible currencyvalid：twenty-eight (28) days beyond the original validity period of the bid#FE54`from a reputable source from an eligible country. If the unconditional guarantee is issued by a financial institution located outside the Purchaser s Country,the issuing financial institution shall have a correspondent financial institution locate', '', '财务能力financial ability：前两年营业收入至少为投标价格的两倍；Average annual revenues for the two years prior to bid submission must be at least twice the bid price；供货记录/项目经验supply record：制造商需有三年制造招标产品的经验；Manufacturers shall have at least three years of experience in manufacturing the required equipment.其他others：证书：有ISO类证书；型式测试报告：投标人须提供相似电缆及电表的型式测试报告；? Manufacturer Factory Certification - The manufacturer factory shall have a valid certification for such as an ISO certificate or equivalent. Formal certification of su', '', '无none						\r\n', '', '银河投标', '无none								\r\n', '客户决定采购，出资方对决策有一定影响client decide procurement， the Bank has some influence for decision；						\r\n', '', '10%的预付款：在合同签订、收到预付款保函之后的45天内支付 ；\r\n80%的货款：在货物装船后以信用证支付；\r\n10%的尾款：在货物验收后、颁发验收证明后的45天内支付；\r\n(i) Advance Payment: Ten (10) percent of Goods supplied from abroad shall be paid within Forty Five (45) days of signing of the Contract, and upon submission of claim and a bank guarantee for equivalent amount valid until the Goods are delivered and in the form provided in the bidding documents or another form acceptable to the Purchaser.\r\n(ii) On Shipment: Eighty (80) percent of the Contract Price of the Good', '', '世行出资项目 project financed by World Bank						\r\n', '', '佣金代理与电力公司有合作经验，有一定的客户关系基础						\r\r\n', '', '曾在该国家参与三个项目的招标，与领导层有联系						\r\n', '', '该市场已有海兴、正泰、思达、科陆、三星等竞争对手，华为为电力公司供应了软件和系统，另外存在一些当地公司及英国公司，历史中标者电表价格都非常低						\r\n', '', '银河曾三次参与投标，对市场比较了解，但是均因价格问题出局。该国家反腐力度大，提倡政府廉洁，基本只有价格最低者才有机会得标；银河以自有产品参标，机会较大，但需给出合理报价；						\r\n', '', '需要业务拿到电力公司参考预算，公司给出合理报价；								\r\r\n', '该项目由电网以电力名义投标，已中标，现在处于合同签订阶段', '姜盼(Nadine Jiang)2020-02-26 10:39:53', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('423', '{A0C0DCED-9809-4AC5-9FE4-635482CE9F40}', '61', 'INHE-0913', '2020-02-26 20:45:31', '0000-00-00 00:00:00', '2020-02-28 16:56:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022603/MEC', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此次项目为与Seth的再一次合作，有利于我们与代理商建立良好的关系。同时，此次项目中国电建也以相同的产品向我们询价，猜测Seth与中国电建投标了莫桑比克的同一项目。\r经商议决定为Seth和中国电建分别提供报价。建议立项', '魏紫薇2020-02-27 13:48:02', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('424', '{02A7AC70-D191-43BD-BE07-124B1A830A95}', '61', 'INHE-0744', '2020-02-27 06:02:10', '0000-00-00 00:00:00', '2020-02-27 16:54:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022701/NGA', '', 'N°02/AFD/CNE1157/20', '2020年3月12日9时（本地时间）', 'Projet d’Extension de l’electricite en zone urbaine et de developpement de l’acces a l’electricite en zone rurale (CNE 1157)城市电力拓宽和农村接电发展项目（CNE 1157）', '资金来源：尼日尔政府向法国发展署借款用于支付本项目\r\r\n付款条件：买方收到货并完成临时验收且卖方提供相关资料原件，买方才支付100%合同金额（待澄清）\r\r\n交期：90天，DDP交至电力公司仓库\r\r\n质保：自验收之日起12个月\r\r\n违约条款：若未能如期交货或未能提供服务，每个自然日罚款合同金额的0.5%，罚款金额最对可至合同金额的5%', '{02A7AC70D19143BDBE07124B1A830A958442F4C2B3234363A3D51C033076BD50}_Consultation compteurs CNE   1157_VC.docx', '先做技术评审，通过技术评审后最低价中标', '', '独家中标', '', '无要求', '', '只邀请资质符合的厂家参与', '', '1、公司资质文件；2、电表产品技术资料及相关证书；3、供货记录', '', '银河投标', '不适用', '法国发展署项目，技术部分由电力公司进行评审，商务部分由电力公司和法国发展署组成的项目协调组进行评审，最终决策由项目协调组进行最终决策', '', '资金来源：尼日尔政府向法国发展署借款用于支付本项目\r\n付款条件：买方收到货并完成临时验收且卖方提供相关资料原件，买方才支付100%合同金额（待澄清）\r\n交期：90天，DDP交至电力公司仓库\r\n质保：自验收之日起12个月\r\n违约条款：若未能如期交货或未能提供服务，每个自然日罚款合同金额的0.5%，罚款金额最对可至合同金额的5%						\r\n', '', '该项目由法国发展署进行融资，支付能力可以保证', '', '合作伙伴为尼日尔电力公司的大项目经理，直接负责招投标。其与中国人打交道多年，也多次到过中国。与银河之前在配电的项目上有些合作，但是最终因为保函问题未能中标。但是其支持银河，帮助业务做了一些标书的运作						\r\n', '', '同上', '', '本次招标为邀请性招标，除银河外还有以下几家厂商：\r\r\r\n科陆\r\r\r\n三星电子\r\r\r\n海兴\r\r\nItron\r\nConnect Africa Technologies', '', '竞争策略：\r\r\r\n优势：1、银河可以实现90天内交货至电力公司仓库；（该条款为业务运作）；2、价格优势：TTA单相表有价格优势，三相表可以使用库存表；3、有一定的客户关系。\r\r\n劣势：银河未在该市场进行过供货，对该市场不了解，无可靠的代理和非常可靠的关系', '', '1、业务需要到现场了解整个电力公司的实际情况，做好相关的市场调研工作，为下一步的客情建设和精准报价做准备；\r\n2、尼日尔是内陆国家，DDP条款下的价格组成计算复杂，需要提前找相关货代做好费用的核算，精准报价；\r\n3、通过内线运作需要提供样机，通过澄清改变付款方式', '尼日尔国家虽穷，但是潜力不仅仅在于电表，更多的在于太阳能和配电。由于是新市场，需要先有机会切入进入该市场，而本次的招标就是个很好的机会。本次招标前期通过内线做了部分的运作，有很大的中标可能。在执行阶段，该项目最大的问题可能在于付款方式，但是我认为因为是法国发展署的项目，风险还是在可控范围内。同时，通过澄清看是否可以先让招标方支付预付款，剩余的尾款通过中信保或者其他方式进行风险规避。', '郑超波2020-02-27 08:02:47', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('425', '{64E7F991-4899-4895-A079-B4080F2B92E7}', '61', 'INHE-0772', '2020-02-27 10:42:53', '0000-00-00 00:00:00', '2020-02-28 16:50:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022702/MLL', '', '001/2020/AOI/MEE/AMADER/PERSHY22', '2020年3月15', 'REALISATION CLE EN MAIN DES OUVRAGES ELECTRIQUES HYBRIDE SOLAIRE PV/DIESEL, DES RESEAUX DE DISTRIBUTION ET DE BRANCHEMENTS POUR 22 LOCALITES EN REPUBLIQUE DU MALI 马里22座混合太阳能光伏/柴油电气结构，配电网络和连接的交钥匙项目', '', '', '', '', '', '', '', '', '', '', '', '', '代理商投标', '', '', '', '', '', '', '', 'KAMA 有经验的代理商，此前合作过电表投标项目，公司有专门的投标团队', '', '银河与业主AMADER之间没有建立联系', '', '马里是伊斯兰教国家，随着马里政局形势的变化，当前马里对法国人态度转变，今年依赖局势不稳定，政府极管罢工，从11月开始发起罢工驱逐法国企业。下一次总统大选是2024年	\r\r\r\n', '', '优势：代理有投标经验和专业的投标团队\r，马里市场已有供货经验\r\r\r\n劣势：本项目为EPC项目，涉及设计，安装和运营，对代理商资质要求高，由于电表部分占比小，影响有限，中标与否受EPC项目主体（太阳能电站，输电线路）部分影响大			\r\r\n				\r\r\r\r\n', '', '及时提供厂家授权文件和投标文件即可', '本项目的电表技术规格开放，由EPC承包商自主提出，标书无技术参数要求，KAMA作为承包商给出的电表要求为：单相两线预付费代码表，最大电流规格仅仅为15A。 不需要样机，也无技术解析需求，我司投入资源很少。建议:选用价格有优势的单相表型', '张子琦2020-02-27 17:38:21', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('426', '{D3FA1F94-CB7A-4F05-B8EC-83911CC5DB46}', '60', 'INHE-0781', '2020-03-03 16:27:52', '0000-00-00 00:00:00', '2020-03-16 09:54:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030301/BPE', '', '27.11.0000.304.20.112.20', '2020.4.8', 'Supply of Single Phase & Three Phase Solid State Smart Prepayment Meter with modem under Existing unified Prepayment System for Mymensingh and Sylhet Zone.', '电力公司对代理：无预付款,70%收到发货单据后支付，30%到货验收合格后30天内支付。\r\n代理对银河：100%不可撤销L/C，银河发货后凭单据收取全部货款。', '', '先做资质审核，然后做技术演示，进行技术评标，最后开价格标，低价中标。', '', '一个LOT，一家中标', '', '投标保函及履约保函由代理负责', '', '1.过去5年内仲裁次数不超过3次；\r\n2.至少3年以上投标产品的供货经验；\r\n3.在过去5年内，不超过两个合同的情况下，类似投标产品的供货金额需不少于180万美元；\r\n4.最小年供应量/产能不小于两倍标书需求量（10万单相表，1万三相表）；\r\n5.流动资产不少于供货金额的150%。\r\n6.单三相表均需提供国际权威实验室测试报告（KEMA,SABS,MID等）', '', '', '', '代理投标', '', '此项目主要由BPDB高层决定，能源部掌握最终审批权', '', '见上述付款方式', '', 'BPDB预算收入下的现金外汇，付款有保障', '', '代理在BPDB有良好关系，可以保证我们在评标环节不出太大问题，此项目主要还是拼价格，现有代理成本控制有优势，加价幅度相对较低。', '', '银河的产品在BPDB大量使用，具有相当的产品美誉度，客户关系也还不错，但尚未建立较深的利益关系，因此还是需要代理来做。', '', '此项目主要竞争对手将是海兴、林洋，海兴在孟加拉当地经营多年，关系深厚，而林洋则是后起之秀，在市场开拓上非常舍得投入，同时有一个54000台表的项目在执行，以此为契机，与电力公司相关链条上的人都建立了联系，在标书条款上已经给我们设置了障碍，还在努力解决中。', '', '此项目与BPB一样是纯供货项目，现在难点就在IDIS认证跟单三相通讯模块互换问题。后者我们已经有应对方案，但IDIS认证还在努力运作中。', '', '标书条款的运作及较低的价格', '此项目与BPB一样，仅投标时间不一样，只需追加制作样机即可，建议参加。', '李启坦2020-03-12 16:16:43', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('427', '{F6315EE5-1D02-4D28-82CD-C0DB8BAE810F}', '61', 'INHE-0772', '2020-03-04 08:42:46', '0000-00-00 00:00:00', '2020-04-09 10:58:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030401/MFF', '', '暂无，标书发标后补充', '暂无，标书发标后补充', '暂无，标书发标后补充', '暂无，标书发标后补充			\r\n	\r\r\n', '', '暂无，标书发标后补充			\r\n', '', '暂无，标书发标后补充			\r\n', '', '暂无，标书发标后补充			\r\n', '', '暂无，标书发标后补充			\r\n', '', '暂无，标书发标后补充			\r\n', '', '暂时定义为授权代理投标，等标书正式完成后，若代理资质不满足，或将修改为银河投标。', '', '马里电力公司EDM，评标人员为电力公司人员', '', '暂无，标书发标后补充			\r\n', '', 'EDM的支付能力弱，代理的支付能力强', '', '代理与电力公司稳定的大供应商之一，在电力公司有内线，和高层关系较好。目前主管马里业务的是代理的儿子，年龄在30+左右。性格直接，不罗嗦，客户关系自己把控。当时立场对接厂家和电力公司由财务负责。', '', '2017年，银河曾派业务千万一线，2018年至今，我们与电力公司只有简单邮件沟通技术，技术部分对银河及时的技术响应比较满意。', '', '华立，华越，威胜，', '', '优势：代理的内线消息灵通，与电力公司合作多年，目前是唯一将资料给我们的代理。在以往项目的经验，代理的支付能力和配合能力都不错。\r\r\r\r\r\r\n劣势：如代理投标，这个代理的报价很高，在以往电力公司的竞价采购中，多次高价中标。但本项目为世行项目，价格起主导作用，报价部分需要与代理进行彻底沟通。\r\r\r\r\n\r\r\r\n建议：1.单相表使用TTL表型应标，有成本优势。2. 一线客情需要加强', '', '1. 如果是代理投标，需要助其准备投标文件和样机，同时沟通投标策略和报价。\r\n2. 如果是银河投标，保函，样机，资料准备后，还需前往一项经营客户关系。', '现阶段为标前拿到技术规格，据代理内线消息：该项目为紧急采购，目前标书的草稿还未完成，技术规格提供给我们提前准备样机和资料。考虑到当前疫情问题，航班和物流无法正常运行，寄送时间不可控。稳妥起见，需提前把样机制作准备。其他的商务条款和所需资料，将在招标公告正式发出后补充。								\r\r\r\r\n', '张子琦2020-04-03 16:43:58', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('428', '{A19617DA-12EC-4998-A24B-8BE4845662BE}', '61', 'INHE-0744', '2020-03-05 01:55:59', '0000-00-00 00:00:00', '2020-03-09 09:11:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030501/NGB', '', 'AOI-21/CGP/NELACEP2/20', '2020年4月9日当地时间上午9时', 'Fourniture de 73500 compteurs intelligents采购73500台智能电表', '资金来源：世界银行的捐赠\r\r\n付款主体：电力公司\r\r\n付款条件：合同签署后的30天内，支付10%的预付款；货物装船并提供相关文件后，买方以不可撤销的保兑信用证支付80%；买方验收并出具验收证明后的30天内，支付剩下的10%\r\r\n交期：120天，DDP交至电力公司仓库\r\r\n质保：360天\r\r\n违约条款：每晚一周罚款合同金额的0.5%，最高罚款可至合同金额的10%', '', '先做技术评审，通过技术评审后价低者中标', '', '独家中标', '', '投标保函：2700万西非法郎\r\r\r\r\r\n预付款保函：买方应随预付款申请附上相同金额的预付款保函，有效期为交货日\r\n履约保函：合同金额的10%，最终验收后解除', '', '财务数据：近三年的年平均营业额不得低于本次投标价格的两倍，近五年至少曾在一个市场供应金额不低于10亿八千万西非法郎的电表，或曾在两个类似的市场各供应金额不低于7亿西非法郎的电表', '', '1、	投标保函-截标前10天；\r\r\n2、	气候适应性用户证明（苏丹、布基纳法索、马里、毛里塔尼亚）；\r\r\n3、样机-截标前10天\r\r\n', '', '银河投标', '不适用', '世界银行项目，技术部分由电力公司进行评审，商务部分由电力公司和世界银行组成的项目协调组进行评审，由项目协调组进行最终决策', '', '合同签署后的30天内，支付10%的预付款；货物装船并提供相关文件后，买方以不可撤销的保兑信用证支付80%；买方验收并出具验收证明后的30天内，支付剩下的10%\r\r\n', '', '该项目由世界银行提供资金，支付能力可以保证', '', '合作伙伴为尼日尔电力公司的大项目经理，直接负责招投标。其与中国人打交道多年，也多次到过中国。与银河之前在配电的项目上有些合作，但是最终因为保函问题未能中标。但是其支持银河，帮助业务做了一些标书的运作\r\n', '', '同上', '', '该项目属于世行的国际性公开招标项目，预计各产商均会参与竞投。其中需要特别关注的是已经在该市场有过供货经验的三家公司：\r\n科陆：17年中标6万台，18年进行交付；\r\n宁波三星：17年中标1万台，代理为南非的Connect Africa；\r\n海兴：对该市场进行过供货（具体数量和时间还未调查清楚）。\r\nNG市场属于刚开始用智能表，对智能表的功能基本无特殊要求，导致各厂商基本可以满足标书要求，虽属于低端市场，但是预计竞争压力较大。\r\n', '', '优势：1、银河的产品能够完全满足标书的要求；2、业务在现场，能够调研客户需求及DDP报价所需的各类费用的核算信息；3、有一定的客户关系。\r\n劣势：1、银河在该市场无供货经验；2、银河之前在该市场无市场调研和客户关系基础，一切均从零开始；3、电力公司对电表技术规格要求低。\r\n竞争策略：1、通过运作使用样机（内线已经答应），技术部门提供项目运作的技术规范，以及制定样机测试流程并教会电力公司测试人员，在测试阶段争取将低于银河价格的厂商测出局；2、商务上使用合适的价格，严格根据标书准备资料。\r\n', '', '1、符合标书的要求的投标文件；2、样机及测试流程运作；3、深化客户关系。', '该项目属于世行项目，共计73500只可更换模块的智能表（不带模块）。将采用公司现有的模块表进行投标，无需进行特殊研发。该项目有一定的客户关系，加上业务已经在现场，能够继续深化客户关系，通过运作样机和测试，争取能够中标。', '郑超波2020-03-05 07:56:04', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('429', '{CA5E054F-850E-47D6-BBAB-276A89D1D3EE}', '153', 'INHE-0535', '2020-03-06 18:28:41', '0000-00-00 00:00:00', '2020-03-09 17:36:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030601/APS', 'APS-EOI', 'CGM/PROJ/T&D/NCB-24/2019-20', '2020.03.11', 'Survey, Design, supply, installation, commissioning, integration of 5,64,000Nos 3Ph, 4W whole current (10A-60A)/CT Operated DLMS meters with built in modem on LV side of Agriculture DTRs & data acquisition to MDAS server of APSPDCL and 5 years AMCAPSPDCL电力公司的564,000个农业配电变压器低压侧三相四线直通表和CT电表（10A-60A）的勘测，设计，供应，安装，调试，兼容，以及MDAS服务器的数据获取和5年维护服务。', '付款主体：APSPDCL电力公司；\r\r\n付款条款：电力公司审批当月账单后45天内支付相应款项，款项基于电表读数按每表月服务费支付：\r\r\n          项目执行期：基于电表安装数量和抄读数据，按季度支付；\r\r\n          运维期：基于抄读数据，按月支付。\r\r\n交期：LOA后18个月执行期+5年运维期；\r\r\n质保：5年质保期+持续的2%备品；\r\r\n违约：SLA通讯率需维持在98%，通讯故障时，需在5个工作日内完成维护且返回数据。若通讯率低于98%，将按电表通讯失败率罚款。', '{CA5E054F850E47D6BBAB276A89D1D3EE8442F4C2B3234363A3D51C033076BD50}_Tendernotice_1.pdf.pdf', 'EOI中未明确。', '', 'EOI中未明确。只提出最低价中标。', '', 'EOI中未明确。', '', '投标人在过去5年需要有50万台单相/三相/CT表的供货记录；\r\n可以联合投标，但需在EOI应标资料中提交联合体说明；', '', '无需提交商务文件如财务报告等，只需提交技术文件如供货记录，产品技术资料，方案资料等。需商务部协助在3月10号完成EOI资格预审资料整理。', '', '联合投标', 'XIOTA主投，INHE联合体成员。\r\r\n1.该项目涉及产品，软件，及系统运维，项目周期长达6年半，需要本地合作伙伴负责项目本地管理，售后，本地雇员，现场服务、联络，客户关系维护等；\r\r\r\r\n2.INHE提供电表，XIOTA提供MDAS系统。\r\r\r\r\n3.该项目在电表安装、上线后根据数据抄读按每表月服务费用支付货款，需要融资。', '电力公司自主招标，评标。', '', 'EOI中未明确。', '', '投标人融资。电表和系统工作效率（数据抄读）会影响当月账单提交及收款。', '', '1.各项目中接触和沟通较多。但是第一次与INHE正式合作预投标。\r\n2.投标经验较多，老板工作效率高，有一定运作能力。', '', '尚未与AP邦电力公司有过直接接触。', '', 'GENUS, L&T, HPL等。', '', 'EOI阶段，主要证明XIOTA+INHE的技术实力和经验，尤其凸出三相表，CT表和系统的供货和执行经验，以及提出对本项目的初步方案建议。确保不会因技术资质问题而被淘汰，不能进入下一阶段正式招标。', '', '技术资料的充分性及预投标资料的及时提交。', '1.该项目为资格预审，暂未提出正式招标为本地招标还是国际招标，需要进一步运作将来允许国外厂家参与投标；\r\n2.由资格预审的付款条款来看，该项目执行中需要融资，需要进一步了解电力公司的项目预算，以便后续正式招标中提出合适的产品方案（该项目对通讯方案无明确限制）和报价建议；\r\n', '左亚楠2020-03-06 20:59:58', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('430', '{5EF324D2-00B4-46AE-96D2-F1C0A13A308C}', '66', 'INHE-0634', '2020-03-11 10:02:48', '0000-00-00 00:00:00', '2020-03-12 15:10:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031101/PNY', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '缅甸微电网项目，产品和方案不涉及研发。付款方式：100%TT预付；贸易条款：CIF仰光；交期：60天；质保：1年。建议立项。', '陈雁2020-03-11 10:09:39', '00', '★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('431', '{2E0F6581-E134-465C-A853-3A612C1C3D2B}', '66', 'INHE-0634', '2020-03-12 17:11:37', '0000-00-00 00:00:00', '2020-03-13 09:21:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031201/WLT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'ECT于1999年成立，在土耳其和周边国家提供电能质量和电力效率的相关方案20年。其主要生产产品有：低压配电板， MCC面板，控制面板，谐波滤波器面板，工业自动化面板，OG / YG保护控制面板。\r\n\r\nECT目前销售的产品范围广泛，主要有8大版块：计量（便携式功率分析仪，电流互感器和分流器，最大需量控制系统，CVM能量分析器等 ）；保护和控制（工业接地漏电保护，接地漏电保护和过载/自闭短路保护，继电器，过滤反应堆等 ）；电表（http://www.ectgrup.com.tr/kalite_ve_olcumleme.asp）；谐波滤波和功率因数校正；高压保护系统；智能停车系统；智能识别系统；电动车充电系统。\r\n\r\n主要的客户群体有发电公司和配电公司以及机场、酒店和商场等大用户，因其项目较多，目前ECT在土耳其全境已经设立5个办公地点。已知ECT的大型战略合作伙伴有：circutor, circontrol, CPT cirprotect, lifasa。\r\n\r\nECT希望与银河合作，其项目中有需要用到银河的电表的时候即从银河直接采购，电表将成为其方案的一部分，银河的电表也将出现在其公司产品主页上做推广，因此这不是独立的项目，而是长久的合作。\r\n\r\n建议立项，设计匹配需求的方案，从ECT借力进入土耳其及其周边市场。', '陈雁2020-03-12 17:16:03', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('432', '{2D4C98DC-64D2-4812-BF07-336F3690CBBE}', '66', 'INHE-0634', '2020-03-18 09:18:37', '0000-00-00 00:00:00', '2020-03-18 13:18:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031801/BOS', '', '9590-IFT-47658', '2020年6月3日', 'Supply and Installation of Smart Metering in 9 business units of Elektrokrajina in Republic of Srpska, Bosnia and Herzegovina', '交期：合同签订后3个月内开始分批交付，24个月内要交付完毕。价格条款：DAP。交付地点：波黑境内9个不同仓库。付款方式：20%预付+70%交货后45天内支付+10%验收合格后支付。', '{2D4C98DC64D24812BF07336F3690CBBE8442F4C2B3234363A3D51C033076BD50}_EK AMM-Technical part of Tender - final all with appendices.pdf', '', '{2D4C98DC64D24812BF07336F3690CBBE074E749A304748709C51373D9D483750}_EK AMM-Procurement part of Tender_final OK.pdf', '', '', '投标保函1500欧元，从波黑银行开出', '', '(1)投标人在过去五（5）年（2015、2016、2017、2018、2019）的平均年营业额累计不少于750万欧元。 如果是合资企业，所有合作伙伴必须累计达到要求。\r\r\n(2)在过去五（5）年（2015年至2019年）内，作为承包商（独家承包商，主要合伙人或合资企业的合伙人或分包商）在供应和安装包括自动仪表管理（AMM）软件的一项合同方面的成功经验。 所提供的AMM软件应至少一（1）个最终用户成功实施，每个用户安装的智能电表总量不得少于50,000个。\r\r\n(3)根据招标文件中的要求，具备可及时成功地实施项目所需的足够关键人员和设备；\r\r\n(4)投标者应拥有ISO 9001，ISO 14001，ISO 18001或ISO 45001，标准证书或涵盖上述领域的任何其他可比较的标准证书，以及环境管理和健康与安全证书。 如果是JV则合并资质需符合要求。\r\r\n(5)在合同规定的期限内，证明的制造能力应不少于每年30,000台智能智能计量设备和30,000台表箱。\r\r\n(6)最近三（3）年内具有制造所提供或类似型号的设备的成功经验。 制造商应证明所提供的设备型号已在气候条件相似的国家的农村和城', '', '重要：必须要IDIS证书！！', '', '正在与本地合作方洽谈中，认真研读标书后再决定参与方式。', '', '', '', '', '', '欧洲复兴开发银行提供资金支持，业主付款能力有保障。', '', '代理是第一次做电表类项目，但有能力供应本波黑项目中的AMM和MDM系统，建议银河供应产品设备，代理负责软件部分。代理的更多情况需要进一步核实了解。', '', '', '', '2019年中标的表厂是塞尔维亚表厂METER&CONTROL，其合作伙伴是波黑的两家IT企业PROINTER和MIKROELEKTRONIKA。', '', '初来乍到，需要比对手花更多精力研究和理解技术要求；IDIS证书不知道什么时候可以拿到。但不尝试迈出第一步，永远也追不上别人的步伐。投标期间没有样机要求，还有余地操作。', '', 'IDIS证书要尽快拿到；与代理同心协力才可能有赢面；尽快熟悉技术要求准备投标资料。', '建议立项，争取竞标机会。', '陈雁2020-03-18 10:30:15', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('433', '{4F076C84-F175-4950-98FB-7F524E6BBE14}', '61', 'INHE-0793', '2020-03-18 14:00:42', '0000-00-00 00:00:00', '2020-03-20 15:42:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031803/TTH', '坦桑250A低压计量箱招标', 'TENDER No. PA/001/2019-20/HQ/G/222', '2020年4月14日', 'SUPPLY OF 250A AMR THREE PHASE PREPAYMENT RF SMART SPLIT METERS COMPLETE WITH METER CABINET             供应250A AMR三相预付费分体式RF通讯智能电表配计量箱', 'TANESCO付坦先令。                                                     国内付款条件为： (1)无预付款和发货款。（2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后45天内支付。                                                                         质保期限：接受货物起24个月。交期：合同签署后三个月内交货。            违约：百分之0.2/天，未发货产品，最多10%。                             国外付款条件为：(1)10%的货款将通过不可撤销的信用证在供应商发货后，提交提单，商业发票等支付。(2)90%的尾款将在供应商提供采购方签发的验收证书后45天内TT支付。质保期限，交期，违约条款上同。', '', '\"国际性招标，本地和国际厂家都可以投标，本地厂家有15%的价格优势。先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。', '', '国际性招标，只有一个lot，可能一家厂家中标，也可能分标，标书未明确。', '', '无需投标保函，本次投标建议由ITL/Africarriers 准备投标保证声明，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '1. 财务能力\r\n1.过去三年平均年度营业额，不低于TZS. 1,000,000,000.00或相等金额。\r\n2.2016，2017和2018年审计的财务报告（含资产负债表）。\r\n3.流动资产总额至少为100%的投标价格。\r\n2. 技术能力和经验\r\n投标者/厂家至少5年的制造或供货计量材料经验\r\n符合标书的技术要求\r\n投标者应该提供文件证明其符合以下经验要求：\r\n至少5年经验供货和制造招标要求的类似产品\r\n过去三年成功完成的合同符合以下最低要求：\r\n至少3个相同规模的合同\r\n合同清单包含至少所供货的物料信息，数量，服务，合同金额，买方联系方式。\r\n3.生产能力\r\n提供厂家证明来证明生产能力和执行供货能力。\r\n4.法律能力\r\n提供文件证明完成了付税和社会安全贡献义务。\r\n没有因欺诈，腐败，不诚信而被定罪\r\n具备签订合同的法律能力\r\n投标人要求在其文件中提供在坦桑尼亚供货产品的厂家的授权', '', '技术应答表，非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书技术要求。最迟4月3日提供。', '{4F076C84F175495098FB7F524E6BBE14C675BD0CC93442C09B990884D4324504}_G222 - DOC LV METERING.pdf', '银河支持ITL工厂投标，ITL中标后，从银河采购整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后45天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，ITL在短期内扩建了新的绝缘子工厂，导致财政紧张，TT支付难度大，但支付信用证问题不大，目前银行融资额度为5百万美元。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU，STAR等，EDMI主要支持者是电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者电表部经理，采购经理，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，高级配电经理，实验室工程师等。STAR目前客户关系较弱，直接做本地的市场，代理商还有待确认。EDMI主要是供单相，三相分体式直通/CT/VT表。海兴目前暂无中标记录。目前市场上主要的本地厂家为ITL，EDMI，WASION, CLOU, HEXING,其中ITL，EDMI,WASION和CLOU四家可以合作。', '', '该标为国际招投标，如果我司直投，除了要介入较为复杂的本地税外，付款条件90%为到货验收后付款，还没有本地工厂15%的价格优势，故而考虑授权给ITL代投，LV250A计量箱需要制样和提供给ITL投标。虽然配电产品算是初次投标，但是合作伙伴在本地已经有较好的基础和积累。而真正的强力竞争对手是EDMI，其它厂家在配电上的水平差别不大，我司可以灵活操作。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员，我司支持ITL投标和中标的几率较大。', '', '产品报价符合市场形势，样机制作按时交付，技术支持，商务和研发人员响应到位，必要的客户关系建设开销等。', '建议立项，准备文件和样机，支持ITL投标和争取订单。', '辛方腾2020-03-18 17:57:43', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('434', '{48E2739F-A73E-4177-9545-D6D46EE1DE85}', '61', 'INHE-0432', '2020-03-19 14:34:04', '0000-00-00 00:00:00', '2020-03-20 15:38:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031901/KF04', '项目代号为KFD', '等正式发标后给出。预计下周二发标（3月24号）', '预计发标至截标只有2-4个星期。', '本地工厂预付费电表供货', '1.此次招标为限制性招标，只针对本地厂商招标；\r\r\n2.银河（非洲）直接参与招标，代理获取佣金；\r\r\n3.KPLC对银河（非洲）付款。标书结算方式：满意交付产品及递交所有票据及文件后30天内付款。\r\r\n', '', '一审：商务文件、本地资质认证等。\r\n二审：技术资料评审、样机测试等。\r\n终审：财务及报价。', '', '每个投标人最多只能中标1个包。', '', '投标保函：需要。具体金额等正式发标后再提供。\r本地银行出具。\r\r\n履约保函：合同金额10%。本地银行出具。', '', '基本同KF03，等拿到标书草稿后再提供。', '', '提交给电子投标网站。', '', 'IAC直接投标。', 'N/A', '1.MD/CEO直接任命评标团队。\r\n2.评标团队组成：采购（1名）、用服工程师（1-2名）、实验室工程师（1名）、标准部工程师（1名）.\r\n3.评标委员会评标完，由采购专员递交给采购总监审批，而后上交MD/CEO审批。\r\n4.MD/CEO审批完后，经过董事会审批，而后下发中标涵、合同等。\r\n整个决策过程中，能源部（尤其是部长）对电力公司决策影响很大。', '', '满意交付后30天起，提交发票等相关资料，向电力公司索求货款支付。', '', '2019、2020年电力公司利润连续骤降，更多的是前任管理层留下的历史问题，比如过度采购、过度招标（尤其是变电站EPC项目）等。2019年6月财报显示：2019年税后利润骤降92%，仅为260多万美元。', '', '1.最大竞争对手：科陆本地代理商Magnet。其公司本身财力雄厚，代理商与政府高层、能源部客户关系深厚。\r\n2.思达代理商：公司实力弱，但是代理商一直积极的在折腾运作。\r\n3.海兴：这两年海兴没有以前活跃，有恶意低价竞争的趋势（KLA项目2次降价16%，后声称是报价失误）。\r\n4.Smart Metering Technology:科陆业务自己注册的本地公司，没有工厂。但是有能源部部长的关系，所以也得以入围。目前正在想办法使其出局。\r\n5.Yocean Group:本地中国人开的变压器厂，与能源部部长、副部长关系深厚，在KPLC、农网等均有较好的业务。此前与三星合作，本地工厂有电表组装线等设备，预计KF04会参与/中标，供应商可能是三星也可能是科陆。', '', '由于管理层频繁变更，直至最近才趋于稳定。银河目前与采购部客户关系需加深；同时最好是能与能源部部长建立起客户关系。', '', '', '', '优势：银河产品质量与口碑很好，也有较好的客户关系。\r\n劣势：目前与采购部关系需加强。\r\n\r\n策略：\r\n1.与科陆代理商Magnet谈合作，分第一和第二个LOT。\r\n2.第一点不一定行得通，所以需要同时做强采购部的关系。\r\n3.加强与评标委员会尤其是实验室的客情建设，确保样机无误。', '', '特别说明：KLA01 5000台验货过程中，按照标书要求，需证明“MCU与能集中器通讯”。此项以前从未测试过，但此次工程师测试时，为了测试MCU能通讯，把CIU接在进线端，然后发现CIU无法与MCU通讯。其表示科陆和思达的CIU，接在进线端，均是可以与MCU通讯的。我们当时只能解释说是“G3 频段”与CIU的频段不一样，所以无法通讯。对方没有过多追究，发货正常继续。但是，考虑KF04投标，万一电力公司要求MCU与CIU均为G3，我们现场产品就有失败的风险。目前业务已搜集了科陆代理Magnet和思达的样机寄回去了，尤其是思达的样机上面，MCU和CIU均打了“G3 PLC”的标志。请研发做详细对比和分析，同时也需要公司此次做样机时，满足“MCU”与“CIU”均为“G3-PLC”通讯。', '此次KF04截标时间很短（预计只有2个星期，业务争取延标至4个星期），因为电力公司默认大家本地工厂都有样机/产品。所以我们样机制作时间非常紧（只能给1个星期），还要寄出来至现场（1-2个星期），所以还请研发大力支持。谢谢。', '谭东羊2020-03-19 16:22:08', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('435', '{A11C8D94-AA17-4A76-B7B3-BDC4CB406E18}', '66', 'INHE-0634', '2020-03-20 08:53:54', '0000-00-00 00:00:00', '2020-03-20 15:49:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032001/FNS', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '付款方式：100%TT预付；贸易术语：CIF仰光；交期：75天到港。技术方案已谈妥确认，详见产品列表和右侧附件，均为公司现有产品，不涉及研发。建立立项。', '陈雁2020-03-20 09:53:02', '00', '★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('436', '{2E313751-74C9-49D3-96E8-BE3DC3D38847}', '61', 'INHE-0793', '2020-03-23 15:33:05', '0000-00-00 00:00:00', '2020-03-24 14:40:21', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032302/TTO', '33KV柱上安装自动重合器配电产品投标 			', 'TENDER No. PA/146/2019 - 2020/HQ/G/32', '2020年3月27日', 'SUPPLY OF POLE MOUNTED AUTORECLOSER 33KV IN KAGERA REGION                                            供应33KV柱上安装自动重合器给KAGERA REGION', 'TANESCO付坦先令。                                                     国内付款条件为： (1)无预付款和发货款。（2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                                         质保期限：接受货物起12个月。交期：合同签署后三个月内交货。            违约：百分之0.1/天，未发货产品，最多10%。                             国外付款条件为：(1)无预付款和发货款。（2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。', '', '\"本地性招标，本地厂家和本地供应商都可以投标。先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。', '', '本地招标，只有一个lot，可能一家厂家中标，也可能分标，标书未明确。', '', '无需投标保函，本次投标建议由ITL/Africarriers 准备投标保证声明，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '\"1. 财务能力\n1.过去两年年平均年度营业额，不低于TZS. 100,000,000.00或相等金额。\n2.过去两年审计的财务报告（含资产负债表）。\n3.投标者需要证明有足够的流动资产和银行信用，符合供货的现金流要求。\n2. 技术能力和经验\n投标者/厂家至少2年制造或供货计量材料经验\n符合标书的技术要求\n投标者应该提供文件证明其符合以下经验要求：\n至少2年经验供货和制造招标要求的类似产品\n过去两年成功完成的合同符合以下最低要求：\n至少两个相同规模的合同\n合同清单包含至少所供货的物料信息，数量，服务，合同金额，买方联系方式。\n3.生产能力\n提供厂家证明来证明生产能力和执行供货能力。\n4.法律能力\n提供文件证明完成了付税和社会安全贡献义务。\n没有因欺诈，腐败，不诚信而被定罪\n具备签订合同的法律能力\n投标人要求在其文件中提供在坦桑尼亚供货产品的厂家的授权\"						\r\n', '', '技术应答表，非危险物质申明里面的重合器器件供应商证书，图纸和装箱信息，常规测试报告，型式测试报告，防腐蚀报告，镀锌测试报告。具体参考标书技术要求，最迟3月25日提供。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，ITL在短期内扩建了新的绝缘子工厂，导致财政紧张，TT支付难度大，但支付信用证问题不大，目前银行融资额度为5百万美元。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手TANELEC，AFRICAB，MULTICABLE，MACROPLAST等，各厂家的主要支持者待确认，判断和电表业务类似的参与和决策人员。目前市场上主要的本地厂家为TANELEC，AFRICAB，MULTICABLE，MACROPLAST,其中TANELEC和AFRICAB在本地有较好的供货基础和客户基础。', '', '该标为本地招标，我司不能直接投，付款条件100%为到货验收后付款，故而考虑授权给ITL代投，只需要提供资料，不需要样机和保函投标，风险和投入较小。虽然中压配电产品是初次投标，但是合作伙伴在本地已经有较好的基础和积累。而真正的强力竞争对手是TANELEC，AFRICAB，其它电表厂家在配电上的水平差别不大，我司可以灵活操作。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员，我司可支持ITL投标，中标几率可观。', '', '产品报价符合市场形势，技术支持，商务和研发人员等响应到位，必要的客户关系建设开销等。', '建议立项，准备文件，支持ITL投标和争取订单。', '辛方腾2020-03-23 16:10:31', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('437', '{E45EF7FC-A828-4B62-B4A7-B985D25D53BD}', '61', 'INHE-0793', '2020-03-23 16:56:18', '0000-00-00 00:00:00', '2020-03-24 14:26:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032303/TTQ', '33KV 负荷开关配电产品招标', 'TENDER No. PA/146/2019 - 2020/HQ/G/31', '2020年3月30日', 'SUPPLY OF LOAD BREAK SWITCHES 33KV IN KAGERA REGION                                                  供应33KV负荷开关给KAGERA REGION', 'TANESCO付坦先令。                                                     国内付款条件为： (1)无预付款和发货款。（2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                                         质保期限：接受货物起12个月。交期：合同签署后三个月内交货。            违约：百分之0.1/天，未发货产品，最多10%。                             国外付款条件为：(1)无预付款和发货款。（2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。', '', '\"本地性招标，本地厂家和本地供应商都可以投标。先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。', '', '本地招标，只有一个lot，可能一家厂家中标，也可能分标，标书未明确。', '', '无需投标保函，本次投标建议由ITL/Africarriers 准备投标保证声明，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '\"1. 财务能力\n1.过去两年年平均年度营业额，不低于TZS. 100,000,000.00或相等金额。\n2.过去两年审计的财务报告（含资产负债表）。\n3.投标者需要证明有足够的流动资产和银行信用，符合供货的现金流要求。\n2. 技术能力和经验\n投标者/厂家至少2年制造或供货计量材料经验\n符合标书的技术要求\n投标者应该提供文件证明其符合以下经验要求：\n至少2年经验供货和制造招标要求的类似产品\n过去两年成功完成的合同符合以下最低要求：\n至少两个相同规模的合同\n合同清单包含至少所供货的物料信息，数量，服务，合同金额，买方联系方式。\n3.生产能力\n提供厂家证明来证明生产能力和执行供货能力。\n4.法律能力\n提供文件证明完成了付税和社会安全贡献义务。\n没有因欺诈，腐败，不诚信而被定罪\n具备签订合同的法律能力\n投标人要求在其文件中提供在坦桑尼亚供货产品的厂家的授权\"						\r\n', '', '技术应答表，非危险物质申明里面的负荷开关供应商证书，图纸和装箱信息，常规测试报告，型式测试报告，防腐蚀报告，镀锌测试报告。具体参考标书技术要求，最迟3月28日提供。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，ITL在短期内扩建了新的绝缘子工厂，导致财政紧张，TT支付难度大，但支付信用证问题不大，目前银行融资额度为5百万美元。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电业务。', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手TANELEC，AFRICAB，MULTICABLE，MACROPLAST等，各厂家的主要支持者待确认，判断和电表业务类似的参与和决策人员。目前市场上主要的本地厂家为TANELEC，AFRICAB，MULTICABLE，MACROPLAST,其中TANELEC和AFRICAB在本地有较好的供货基础和客户基础。', '', '该标为本地招标，我司不能直接投，付款条件100%为到货验收后付款，故而考虑授权给ITL代投，只需要提供资料，不需要样机和保函投标，风险和投入较小。虽然中压配电产品是初次投标，但是合作伙伴在本地已经有较好的基础和积累。而真正的强力竞争对手是TANELEC，AFRICAB，其它电表厂家在配电上的水平差别不大，我司可以灵活操作。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员，我司支持ITL投标和中标的几率较大。', '', '产品报价符合市场形势，技术支持，商务和研发人员等响应到位，必要的客户关系建设开销等。', '建议立项，准备文件，支持ITL投标和争取订单。', '辛方腾2020-03-23 17:29:31', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('438', '{4759512C-57C7-4EA0-9002-620A3F6A6000}', '61', 'INHE-0860', '2020-03-23 19:08:43', '0000-00-00 00:00:00', '2020-03-26 08:56:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032304/GNJ', '', '01/PAAEG/EDG/F/2020', '2020年5月4日当地时间上午10:00', '几内亚通电改善项目Projet D’Amelioration de L’acces A L’Electricite En Guinee (PAAEG)', '价格条款：CIP交至电力公司仓库\r\r\n付款主体：世界银行和法国发展署\r\r\n付款条件：开具发票和预付款保函后，付10%预付款；收到发票和相关发货文件后德5天内，付80%；收货并完成验收后，在收到发票、付款申请以及公共合同和大项目管理部的验收证明后，支付剩下的10%\r\r\n交期：合同生效之日起7个月\r\r\n质保：12个月\r\r\n违约条款：若晚交付，则每天罚款合同金额的0.07%，最高为合同金额的10%', '{4759512C57C74EA09002620A3F6A60008442F4C2B3234363A3D51C033076BD50}_DAO_Compteur_REGUL.BRANCHEM_VF 15 03 2020.docx', '满足技术条款的情况下，价低者中标', '', '一家中标', '', '投标保函：10万美元\r\n履约保函：合同金额的10%\r\n预付款保函：支付预付款前应开好同等金额的预付款保函\r\r\n', '', '应书面证明满足以下资质：\r\n1）300万美元的现金流\r\n2）资金实力应足以支持正在履行及即将履行的合同\r\n3）提供最近三年经审计的财报，以证明公司目前的支付能力及未来长期的盈利能力\r\n4）最近5年内履行过2个单个金额不低于200万美元的类似合同（以最终验收纪要或供货证明为佐证）\r\n5）最近5年内以主要承包商或联合投标方的一员或分包商的身份圆满履行过2个单个金额不低于200万美元、总金额不低于600万美元的类似合同', '', '整套投标资料', '', '代理商投标', '', '由电力公司及出资方共同评审决定', '', '开具发票和预付款保函后，付10%预付款；收到发票和相关发货文件后的45天内，付80%；收货并完成验收后，在收到发票、付款申请以及公共合同和大项目管理部的验收证明后，支付剩下的10%', '', '资金来源：世界银行和法国发展署\r', '', '代理凭借其在该市场多年的积累，已经有了一定的客户关系，也为银河获取了部分订单\r\n', '', '代理凭借其在该市场多年的积累，已经有了一定的客户关系，也为银河获取了部分订单；而到目前为止，银河尚未参与该市场客户关系的运作，且由于代理极力反对银河自己经营客户关系，因此，在今后的一段时间内还是很难有所突破。\r', '', '该项目属于国际性公开招标项目，预计各产商均会参与竞投。\r', '', '', '', '- 符合标书要求的投标资料和样机；\r\n- 有竞争力的价格；\r\n- 代理方面良好的客户关系。', '受疫情影响，各大厂家肯定早已摩拳擦掌、跃跃欲试，我们银河当然也得结合近期在GN和NG市场与其他厂家交手的经验争取杀出重围、实现突破。\r\n代理对此次项目显得胸有成竹，那就更要利用其客户关系进一步运作，争取能够中标。', '张祥英2020-03-23 22:46:07', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('439', '{4191C6B2-8698-4BD9-87C8-21F4F2F21F7F}', '61', 'INHE-0432', '2020-04-07 01:19:35', '0000-00-00 00:00:00', '2020-04-09 09:15:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2020040701/KTM', '', 'KPI/6A.1/PT/2/14/20/A74', '待定。纸质投标+U盘存放电子档。', '变压器计量方案交钥匙工程', '\r\r\r\n1.交期：12个月完成项目安装\r\n2.报价：CIP内罗毕仓库。免税项目：关税、IDF、VAT、RDL。\r\n3.付款条件：\r\na) 产品供货费：10%预付（与发票等额的预付款不可撤销保函），80%在发货后的45天内支付（收到付款资料），5%在收到完工证明后支付，5%在收到运营证明后支付。\r\nb) 项目方案涉及费：10%预付（等额预付款不可撤销保函），90%在项目经理确认【接受】设计方案后，由项目经理审批，45天内付款。\r\nc) 安装费用：10%预付（等额预付款不可撤销保函），80%在KPLC验收后的45天内支付；5%在出具完工证明后的45天内支付；5%在出具运营证明后的45天支付。\r\n\r\n', '', '1.技术评审：\r\na)技术资料评审\r\nb)DTMS安全性评审\r\nc)项目经验评审，其中需评估厂商兼容以下系统的能力：SCADA、IMS、CRM、CMIS/INCM、GIS等。\r\n2.财务评审\r\na)项目完成时间：12个月。超出12个月的直接出局。\r\nb)运营及维护成本考虑。\r\nc)设备的功能性保障。\r\nd)若需要KPLC配合提供的工作、服务、设施等超出了标书的范围，KPLC则需要评估这些额外的工作/服务的报价，并纳入评标范围。\r\ne)评标报价计算公式：参考标书P39。', '', '综合评标价格最低者中标。\r\n', '', '投标保函：11万美元，或等额的肯尼亚先令\r\r\r\r\n履约保函：合同金额的10%\r\r\r\r\n\r预付款保函：供货、涉及、安装分开收款，所以各自需提供10%等额预付款保函。\r\r\n\r\r\r\n', '', '投标资料特殊要求：\r\r\r\r\r\r\n1.形式测试报告及认证：\r\r\r\r\r\r\na)形式测试报告需由独立于厂商以外的第三方测试机构认证，或者由第三方测试实验室现场见证。第三方测试实验室需提供认证。\r\r\r\r\r\r\nb)形式测试报告需包含技术规格所有要求。\r\r\r\r\r\r\nc)形式测试报告需包含报告编号供核实。\r\r\r\r\r\r\nd)提供形式测试认证的实验室需提供该实验室的认证。\r\r\r\r\r\r\n2.提供供货记录文件，包含客户的具体信息如地址、联系方式等；同时提供签署的合同、中标涵、PO的复印件等。\r\r\r\r\r\r\n3.厂家质保、过去5年内的审计财报。\r\r\r\r\r\r\n4.至少2份官方的DTMS的用户信函，证明他们用的DTMS系统满足本标书要求的DTMS系统的功能等级。\r\r\r\r\r\r\n5.已执行过的DTMS的合同文件。\r\r\r\r\r\r\n6.至少5份DTMS用户证明，证明该系统包含至少3000个计量点的电表数据管理。用户证明需包含业主详细信息。\r\r\r\r\r\r\n7.DTMS的用户官方信函和用户证明，需证明厂商已兼容过至少2家不同厂商的HES系统。\r\r\r\r\r\r\n8.至少在1家电力公司完全部署和运行过和本标书同级别的DTMS系统。\r\r\r\r', '', '1.需要银河电力采购部，或者珠海配网协助寻找合作DTMS的厂商。\r\n2.需要商务部协助制作投标资料。', '', '需要与合适的厂商联合投标。', '银河电力自己投或者珠海配网自己投均无法满足要求。\r\n', '电力公司评标团队的评审是非常关键的一环，但能源部部长，甚至总统及副总统对此类世行项目影响很大，甚至决定项目最终结果。PZ03最后中兴中标是很好的例子。', '', '供应商提交付款资料给电力公司，电力公司根据项目完工进度评估、审批，最后付款。但最终是电力公司直接付，还是世行直接付，现在无法确定。', '', '该项目由世行赞助。', '', '1.目前预估最大的竞争对手是中兴。因为中兴中标了PZ03，即将部署其MDMS系统，及智能电表，所以有一定的优势。其业务比我早了2-3个月拿到项目信息。\r\r\n2.中兴在能源部的客户关系比我方更强；同时其与世行也有直接的客户关系，我方没有。在电力公司内部，我方与之可抗衡，但电力公司自己无法完全单独决策。\r\r\n3.剩下的竞争对手预计有海兴、华为（不会自己直接投标，我方可考虑与其合作）、四方电气（2018年中标世行的ADMS高级配网EPC项目）、思达（PZ03与华为合作并且把中兴告上了法庭，但最后中兴胜出）。', '', '1.与电力公司的客户关系：较深入。可与各家抗衡。\r\n2.与能源部客户关系：较弱。尤其与部长客户关系有待建立。\r\n3.与世行客户关系：有待建立。', '', '见：第15点描述。', '', '优势：银河在电力公司有一定的品牌影响力，客户关系较好。\r\r\r\r\r\n劣势：\r\r\r\r\r\n1.商务资质质不符，需要找合适的厂商合作，联合投标。而联合投标方面，需要公司适当放开合作要求，如果有太多的限制/要求，很难达成合作。所以建议首先本着从“拿项目”的角度出发，支持、配合业务。\r\r\r\r\r\n2.与能源部、世行的客户关系必须要建立起来，单靠电力公司无法拿下此项目。\r\r\r\n', '', '\r1.关键：需要寻找合适的厂商合作，联合投标。\r\r\r\r\n2.找到合适厂商后，需要商务部、厂商一起配合，支持业务：需要删除哪些不利条款、运作哪些有利条款。此项：预计我们有1个月的时间来运作。世行的项目，一旦关键的商务条款定下来后，基本无法通过澄清更改。\r\r\r\n3.与厂商谈合作的过程中，需要风控协助，支持业务，最短的时间达成合作条件、确认合作模式，投标、竞标。\r\r\n4.业务客户关系建立：建立与能源部、世行的客户关系。', '1.本项目预计会在2-3个左右后发标。现阶段我知道的中兴的业务比我更早拿到了项目信息及资料，其他厂商应该知道的不多。建议我们对外尽量做到项目信息保密。\r\r\r\r\n2.目前至发标前，我们还有一些时间，需要公司大力支持，配合业务运作、竞投。', '谭东羊2020-04-07 11:31:27', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('440', '{29082309-6C27-43AF-B87A-BD10909BD0B0}', '153', 'INHE-0015', '2020-04-10 15:55:01', '0000-00-00 00:00:00', '2020-04-15 09:56:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041001/SSAC', '', '', '', '', '银河与客户签订供货合同，结算条件为：10%预付款，40%即期信用证，50% 120天远期信用证；', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '快速提交样机进行初步测试，支持客户运作产品通过初步测试，同时快速完成100%符合要求的产品研发，确保第三方实验室测试不出问题，尽快通过；', '此项目电力公司招标采购流程已经走完并授标，银河需要利用符合要求的产品、快速而高效的研发和服务争取进入供应商名录并获取订单，项目需求的产品技术要求明确，需求数量潜力巨大，值得下功夫争取。', '王维2020-04-10 16:29:59', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('441', '{D9732777-B388-4DA0-8733-6B4B1F7D22E3}', '93', 'INHEGRID-0013', '2020-04-13 10:40:47', '0000-00-00 00:00:00', '2020-04-15 09:54:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041302/TEN', '', '001/MME/PRMP/2020', '2020年5月8日10:00（UTC+0）', 'Fourniture et pose de matériels électriques de réseaux MT/BT dans les quatre (04) régions économiques du Togo 多哥4个经济区中压/低压电网设备供货及安装', '价格条款：DDP；\r\r\r\n\r\r\r\n付款主体：多哥能源部；\r\r\r\n\r\r\r\n付款条件：1）30%预付款：30%的预付款将在合同授予后60天内支付，需提交等额预付款保函；\r\r\r\n2）65%的合同款：65%的合同款将在供货并安装，临时验收后以信用证支付；\r\r\r\n3）5%尾款：在最终验收后60天内支付，提供验收证明；若提供了等金额的银行保函，此尾款可在临时验收后支付；\r\r\r\n\r\r\r\n工期：供货加安装最长4个月；工期每延迟一天罚金为合同金额的1/1000，达到10%时合同解除；\r\r\r\n\r\r\r\n质保和违约：质保期为一年，坏损件修复更换时间为7天；', '', '满足资质要求，符合技术规范的价格最低者中标；\r\n', '', '一个投标人不可中标超过两个lot；\r\n', '', '投标保函（由联合体另一方开立）：\r\r\r\r\n金额：4个lot，每个lot保函金额为2 000 000FCFA；\r\r\r\r\n货币：西非法郎；\r\r\r\r\n有效期：投标有效期+28天；\r\r\r\r\n保函形式：银行保函；\r\r\r\n\r\r\r\n履约保函：\r\r\r\n金额：合同金额的5%；\r\r\n有效期：完工后28天；\r\r\n开立形式：银行保函；\r\n\r\n预付款保函：\r\n金额：合同金额的30%；\r\n有效期：直至交货；\r\n开立形式：银行保函', '', '财务数据：\r\r\n1. 过去三年年平均营业额为投标金额的0.5倍，提供审计财报；\r\r\n2. 信贷额度至少为投标金额的0.5倍；\r\r\n\r\r\n项目经验：\r\r\n过去5年至少执行过两个类似的中压线路建设合同，每个金额不低于投标金额的50%，提供完工证明；\r\r\n\r\r\n其他条件：\r\r\n人员：1.至少一名电气工程师，硕士学历，至少5年项目经验，执行过至少2个中压电网项目；2.至少一名高级电气技术员，专科学历，至少5年项目经验，执行过至少2个中压电网项目；提供简历及学历证明；\r\n设备：一台起重机，一台联络车辆，一台电缆车，提供灰卡、购买证明或租赁证明；', '', '技术部门：最晚于4月23日提供所有技术资料', '', '联合投标', '1）联合投标原因：\r\r\r\r\r\n1. 标书中所有保函均遵循OHADA准则，国内银行一般不会接受；截标时间紧，保函转开费用高且时间上来不及；\r\r\r\n2. 该项目产品需安装，当地公司有当地项目施工经验，涉及电力及土木工程，对我司有补充作用；但当地公司在财务及类似项目经验上有不足，单独投标也不满足资质要求；\r\r\r\n3. 目前疫情形式严峻，与当地公司一起投标，可尽量避免出差，依靠当地公司处理投标及项目实施过程中的大部分问题；\r\r\r\n\r\r\r\n2）当地公司主投，银河为联合体成员。投标保函由当地公司开立，鉴于疫情，投标文件将由当地公司签署，并负责与业主的沟通联络；当地公司主要负责安装，按照付款条件，大部分合同款将在项目临时验收之后才会支付，项目施工部分是关键；\r\r\r\n\r\r\r\n3）银河：大部分产品的供货、提供资质要求文件；\r\r\r\n   当地公司：开立保函、当地采购产品供货、全部产品的安装施工、与业主的沟通联络；', '国家预算项目，招标方决定采购', '', '1）30%预付款：30%的预付款将在合同授予后60天内支付，需提交等额预付款保函；\r\r\r\n2）65%的合同款：65%的合同款将在供货并安装，临时验收后以信用证支付；\r\r\r\n3）5%尾款：在最终验收后60天内支付，提供验收证明；若提供了等金额的银行保函，此尾款可在临时验收后支付；\r', '', '业主多哥能源部支付能力良好，当地电力不足，近年国家预算多用于电力投资及基础设施建设；', '', '首次合作，与业主客户关系有待考量。该公司有15年以上项目经验，除本地项目外，还拥有在布基纳法索、科特迪瓦等国家的施工经验。', '', '银河电网此前未参与该国家的项目，客户关系待建立', '', '项目较小，难度较低，但多哥及周边国家有较多符合资质要求的工程公司，预测将会有一些本地企业及布基纳法索、贝宁的公司参标。', '', '除电线杆及其配件外，其他产品银河均有合适供应商；银河无需开立投标保函，联合体另一方负责当地协调，前期投标成本较小；项目涉及断路器、负荷开关等产品，若能中标，可积累电网在配电项目方面的经验。', '', '需技术部门寻找合适厂家，及时提供技术资料', '银河电力与当地公司组成联合体投标（已通过OA申请）', '姜盼(Nadine Jiang)2020-04-13 15:30:51', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('442', '{B3375615-EDD0-4D77-8E27-DA688B5309C4}', '61', 'INHE-0913', '2020-04-14 09:01:20', '0000-00-00 00:00:00', '2020-04-24 13:33:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041402/MATB', '', 'DA N42/EDM/2019 du 31/12/2019', '2020/4/30', '数字单相表采购咨询（Consultation pour l`acquisition de compteurs monophasé numérique）', 'CIF价格条款，付款方式为不可撤销的信用证', '', '评标将分为两个阶段进行，技术评估和符合技术规格报价的财务评估\r\r\r\r\n经核查技术符合附件所列规格后，投标书宣布基本上符合规范，报价将有资格进行财务评估。\r\r合同应授予投标基本上符合规定，且报价较低的投标者\r\r\r\r\n', '', '', '', '无', '', 'MTE为邀标，筛选后从候选人名单中选择供应商						\r\r\n', '', '需要客服提供相关产品技术资料', '', '银河投标', '', 'Somelec保留不进行这次招标的权利，或只进行部分内容的权利。电力公司内部运作会对投标产生很大影响。\r\r\r\n', '', '', '', '', '', '', '', '此前，银河曾在当地与代理合作，并与电力公司人员建立过关系，但是，投标失败后就没有再联系，因而现在需要重新进行客户关系建设，寻找新的合作伙伴', '', 'MTE项目与MATA项目情况相似：\r\r\nMATA中标厂商为：科陆（单相表）和海兴（三相表），两个厂商当时的报价都属于较低报价。另外，当地市场的电表还包含，法国萨基姆，兰吉尔，科陆等供应商		', '', '优势：此前已经去过毛塔市场，对当地市场情况有一定掌握；银河已经提交过样机，MATA，MTE技术规格一致，技术规格推断应该是符合电力公司要求的\r\r\r\n\r\r\r\n劣势：MATA项目为未中标，且后续失败原因没有总结；电表技术规格简单，技术上不存在很大的运作空间；相比其他厂家，银河的产品报价过高；\r\r\r\n\r\r\r\n借鉴MATA项目的投标经验，MTE项目，还是需要我们与电力公司内部决策链人员建立关系。鉴于现在的疫情情况，实际去拜访十分困难，会尽力进行线上运作，看是否可能进行客情建设。同时询问现在非洲一线业务是否可能寻找相关代理进行合作。\r\r\n								\r\r\n的主要竞标策略建议为客情运作，寻找项目和电力公司决策链中的关键人物进行客情建设，以提供佣金的方式推动合作，以便于银河能够在项目中获取一手信息，取得优势，以达到中标的目的；同时，可能情况下一定程度降低报价', '', '\r\r\nMTE项目，还是需要我们与电力公司内部决策链人员建立关系。鉴于现在的疫情情况，实际去拜访十分困难，会尽力进行线上运作，看是否可能进行客情建设。同时询问现在非洲一线业务是否可能寻找相关代理进行合作。\r\r\n', 'MTE项目情况与MATA相似，技术规格基本一致，需借鉴MATA的失败经验，从客情方面进行运作，建议立项\r\r\n', '魏紫薇2020-04-14 14:45:58', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('443', '{D8B796DE-6DB1-4B24-8488-F8C8F6875C02}', '61', 'INHE-0721', '2020-04-15 11:06:45', '0000-00-00 00:00:00', '2020-04-17 09:49:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041502/ESE', '', 'CRW 70850', '2020/5/7', 'SUMINISTRO DE MEDIDORES DE ENERGIA ELéCTRICA  电表招标项目', '标书价格条款：100%货款在交货电力公司仓库后30天内支付，结算货币为本地币-哥伦比亚比索。合同交期为485天，期间电力公司分批下单，合同期内完成供货。质保要求24个月。违约中标人须向电力公司支付合同金额10%的违约金。目前银河与代理的结算方式为T/T或信用证，待具体每批发货金额确定。\r\r\r\r\r\n', '', '每种表型可作为1个Lote,投标人可选择一至多个Lote参与投标，以权重计分。第一轮根据报价和满足项进行打分、排名。报价项占90分，投标人报价分数=最低报价/投标人报价*90，每个lote可接受不带条件的折扣；满足项占10分，近3年没有执行存在罚款、合同违约记录，得满分10分。排名前3家，进入第二轮评审，评审标书中要求的投标资格、技术要求、其他正式的及文件的要求。\r\r\r\n						\r\n', '', '每个lote汇总一个分数，得分最高者中标，如果一个lote中出现重分，则取最低报价得投标者。厂商只能授权一个代理投标。', '', '代理开投标保函和履约保函', '', '代理公司提供\r\r\n', '', '技术应答表，供货记录证明等文件；\r\r\r\n', '', '银河授权代理投标', '', '该电力公司为国有电力公司，政府对采购决策影响较大，但据国家智能电表更新政策，正常情况下不会出现政府强行干预。\r\r\n', '', '100%货款在交货电力公司仓库后30天内支付，结算货币为本地币-哥伦比亚比索。', '', '电力公司财务状况良好，支付能力较好', '', '本地代理MESSEN投标经验较丰富，团队技术实力较强。老板年轻有激情，性格比较强势，通过本地服务与电力公司建立客户关系。2015年与此代理合作中标，给EPM电力公司供货约3万台电表。\r\r\n', '', '该代理MESSEN与我司在PSA市场合作多年，互相之间了解度较高。\r\n', '', '该项目目前了解到的竞争对手有海兴、浙江超仪、华越南方等。海兴18年中标EPM国电11万台DIN单相智能电表，以FOB低于银河约6美金中标，且海兴本地设有分公司。华越南方此前与本地经销商DISICO合作，该经销商综合实力较强，待确认DISICO此次是否继续与华越合作投标。\r目前来看此项目中海兴是最具威胁的竞争对手，需要重视。\r\r\r\r\n', '', '银河在该项目中优势有：1，有过供货经验，电力公司客户对银河产品有一定的了解，且对我司产品技术及质量较认可；2.招标数量最大的产品-DIN预付费分体式单相表，与此前银河供货EPM电表技术规格基本一致，我司产品基本满足，且有本地认证；3.目前有备选两款产品（DIN3.5和DIN5），增加报价优势； 4，代理态度诚恳，并且在积极推动              劣势：1，相比海兴本地分公司提供长期的技术支持，建立比较好的客情，同时能够提供有竞争力的最终报价，银河处于比较劣势的地位； 2，招标技术有一个点，需要在强磁1.4T干扰下电表保持正确计量且不不影响电表内部继电器正常工作，以达到防窃电的效果（因为本地市场居名用户容易购买到强磁磁铁，对电表进行干扰，影响电表正常运行，从而达到窃电，电力公司比较头疼）。据了解目前公司产品暂不满足标书中此点技术要求，需要公司评估、给与支持。且从代理口中了解，海兴、ITRON及本地厂商如TECUN等，都能提供满足此要求的电表。3，参考历史中标价格，银河的报价没有较大竞争力。           目前来看，受疫情影响，该国许多电力公司招标都被延迟了，此项目招标数量虽不是很多，但在今年内本市场算是较可观，且电力公司影响较大。 \r\r\n', '', '1，有竞争力的报价，该项目评标权重计分的比重最大的是报价，报价最低前3才有资格入围第二轮评审（公司可参考市场情况适当调整价格） 2，符合技术要求的样机  3，有效的客户内部关系\r\r\n', 'PSA市场电力公司较多分散，此项目招标数量在本市场算是比较可观的招标。EPM集团电力公司用户数量占整个市场35%的份额，是潜力比较大的客户。目前市场逐渐进入更换AMI集抄电表时代，银河需借此机会进一步打开PSA市场智能电表供应，增加智能电表市场份额。', '胡云义2020-04-15 11:17:59', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('444', '{BF77B3A7-91F3-4951-B77A-10A60B5F821B}', '61', 'INHE-0793', '2020-04-18 01:39:12', '0000-00-00 00:00:00', '2020-04-20 15:40:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041801/TTK', '坦桑单三相电表招标（标前立项，已获文件）', 'PA/001/2019-20/HQ/G/236', '预计5月4日', 'SUPPLY OF SINGLE PHASE AND THREE PHASE PRE-PAYMENT SPLIT TYPE RF SMART METERS COMPLETE WITH ENCLOSURES FOR REPLACEMENT OF DEFECTIVES LOT 1, 2, 3 AND 4                                            供应单三相预付费分体式RF通讯带表箱智能电表以供替换问题表计 LOT 1,2,3和4', 'TANESCO付坦先令。                                                    国内付款条件为：                                                     (1)无预付款和发货款。                                                （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后60天内支付。                                                           质保期限：接受货物起12个月，发货后18个月。                            交期：合同签署后三个月内交货。违约：百分之0.2/天，未发货产品，最多10%。  国外付款条件为：不适用                                                代理商对银河支付方式为：不可撤销的远期保兑信用证或者中信保承保的赊销。', '{BF77B3A791F34951B77A10A60B5F821B8442F4C2B3234363A3D51C033076BD50}_1+3.pdf', '本地限制性招标，只有本地厂家可以投标，先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。', '', '只能本地厂家投标，一个厂家最多中两个LOT，且单相最多中一个，三相也最多中一个，即不存在厂家能单相通吃和三相通吃的情况。', '', '需投标保函，价值一亿先令，合人民币30万左右；本次投标建议由ITL/Africarriers准备投标包函，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。', '', '1. 财务能力\r\r\n1.过去三年年平均年度营业额，不低于TZS. 1，000,000,000.00或相等金额。\r\r\n2.过去三年审计的财务报告（含资产负债表）。\r\r\n3.投标者需要证明有足够的流动资产和银行信用，符合供货的现金流要求。\r\r\n2. 技术能力和经验\r\r\n投标者/厂家需提供足够的文件材料来证明有足够的技术实力执行合同，包括但不限于合格的员工，设备和生产设施。\r\r\n经验方面标书未明确，按照此前投标文件整理提供完备即可。\r\r\n3.生产能力\r\r\n提供厂家证明等必须资料来证明生产能力和执行供货能力，标书未明确。\r\r\n4.法律能力\r\r\n提供文件证明完成了付税和社会安全贡献义务。\r\r\n没有因欺诈，腐败，不诚信而被定罪\r\r\n具备签订合同的法律能力等。                                            5.商务文件                                                           a，公司注册证书等 b,有效的营业执照 c,Declaration of Interest Form d,有效的VAT和TIN证', '', '技术应答表，非危险物质申明里面的表计元器件供应商证书，图纸和装箱信息，样机常规测试报告，主要配件微处理器，继电器，锂电池，浪涌保护器型式试验和常规试验报告等。具体参考标书要求。本地标一般截标时间短，虽然提前获得标书，但需一周内提供，即4月27日前。', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后60天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，ITL在短期内扩建了新的绝缘子工厂，导致财政紧张，TT支付难度大，但支付信用证问题不大，目前银行融资额度为5百万美元。', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电业务。', '', '电力公司副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI，海兴，威胜，CLOU，STAR等，EDMI主要支持者是电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者电表部经理，采购经理，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，高级配电经理，实验室工程师等。STAR目前客户关系较弱，直接做本地的市场，代理商还有待确认。EDMI主要是供单相，三相分体式直通/CT/VT表。海兴目前暂无中标记录。威胜和CLOU主要供货单三相直通表，本地价格可以做到EXW40USD。目前市场上主要的本地厂家为ITL，EDMI，WASION, CLOU, 其中ITL，EDMI,WASION和CLOU四家可以合作。', '', '该标为本地限制性投标，可按与代理的既定合作方式投标，去年业务主投的TTX,TTB,TTF,TTJ等已陆续中标，整体上对该市场的技术，商务都有较大把控力。目前主要竞争对手有EDMI，海兴，威胜，CLOU，STAR等代理商，此前已打交道，有应对经验和策略，可以灵活处理关系；本标需要和代理协商并考量可合作的竞争对手而后给出相应竞争策略，有关OA将很快发出。客情方面和电力公司，以及政府的关系较好，银河也有自己的内线人员。整体上我司支持ITL投标和中标的几率较大，LOT可保一争二,继续增加坦桑今年订单量。', '', '产品报价符合市场形势，样机技术解析合格，技术支持，商务和研发人员响应到位，必要的客户关系建设开销等。', '项目数量较大，重要性较高。电力公司内部关系有较好基础，中标概率较高。目前在标前获取了相关文件，建议立项，由商务和客服提供支持以便快速响应支持业务投标和争取订单。', '辛方腾2020-04-18 01:54:54', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('445', '{DC7180CF-30FF-4EAB-B3B0-342F7145C711}', '61', 'INHE-0744', '2020-04-22 00:23:10', '0000-00-00 00:00:00', '2020-04-23 14:40:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2020042201/NGC', '', 'N°04/AFD/CNE1157/20', '2020年5月7日9:30（本地时间）', 'Projet d’Extension de l’électricité en zone urbaine et de développement de l’accès à l’électricité en zone rurale (CNE 1157)城市电力拓宽和农村接电发展项目（CNE 1157）', '资金来源：尼日尔政府向法国发展署借款用于支付本项目\r\n付款条件：开好相同金额的预付款保函后付20%预付款，收到相关单据后付FOB价的70%， 收货时付10%\r\n交期：90天，DDP交至电力公司仓库，每逾期一个自然日罚款合同金额的0.5%\r\n质保：自收货之日起12个月\r\n', '{DC7180CF30FF4EABB3B0342F7145C7118442F4C2B3234363A3D51C033076BD50}_Consultation compteurs CNE    1157 20200328.docx', '先做技术评审，通过技术评审后最低价中标\r\n', '', '独家中标', '', '无要求', '', '只邀请资质符合的厂家参与\r\n', '', '1、公司资质文件；2、电表产品技术资料及相关证书；3、供货记录\r\n', '', '银河直投', '不适用', '法国发展署项目，技术部分由电力公司进行评审，商务部分由电力公司和法国发展署组成的项目协调组进行评审，最终决策由项目协调组进行最终决策\r\n', '', '开好相同金额的预付款保函后付20%预付款，收到相关单据后付FOB价的70%， 收货时付10%\r\n', '', '该项目由法国发展署提供资金，支付能力可以保证\r\n', '', '合作伙伴为尼日尔电力公司的大项目经理，直接负责招投标。其与中国人打交道多年，也多次到过中国。与银河之前在配电的项目上有些合作，但是最终因为保函问题未能中标。但是其支持银河，帮助业务做了一些标书的运作						\r\n', '', '同上', '', '本次招标为邀请性招标，除银河外还有以下几家厂商：\r\n科陆\r\n三星电子\r\n海兴\r\nItron\r\nConnect Africa Technologies\r\n', '', '竞争策略：\r\n优势：1、银河可以实现90天内交货至电力公司仓库；（该条款为业务运作）；2、价格优势：TTA单相表有价格优势，三相表可以使用库存表；3、有一定的客户关系。\r\n劣势：银河未在该市场进行过供货，对该市场不了解，无可靠的代理和非常可靠的关系\r\n', '', '1、业务需要到现场了解整个电力公司的实际情况，做好相关的市场调研工作，为下一步的客情建设和精准报价做准备；\r\n2、尼日尔是内陆国家，DDP条款下的价格组成计算复杂，需要提前找相关货代做好费用的核算，精准报价；\r\n3、通过内线运作需要提供样机，通过澄清改变付款方式\r\n', '通过NGA的投标经验，加上本地的调研，该市场属于低端市场，主要是价格上的竞争。本标属于邀请性招标，标书条款和技术规格与NGA基本一直，不需要样机和保函。只需要将NGA的资料稍微做修改即可。', '郑超波2020-04-22 01:37:55', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('446', '{299D8392-9669-45FF-A2DE-4AD27927356E}', '66', 'INHE-0634', '2020-04-27 09:19:46', '0000-00-00 00:00:00', '2020-04-27 17:11:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2020042701/AKD', '', '254/ITB/UNDP-PDSPE/2020', '2020年5月5日', 'Supply, installation and commissioning of electricity generation and distribution facilities and customer connection equipment for electrification of rural municipalities of Antanimora Atsimo and Bekitro in Androy Region', '【一】业主付款条款：根据完工比例，相应支付货款：第一笔（完工35%，支付35%）；第二笔（完工60%，支付25%）；第三笔（完工80%，支付20%）；第四笔（完工100%，支付10%）；第五笔（验收通过1年后，支付10%）。【二】代理与银河之间的结算方式：30%预付款+70%保兑远期30天信用证。【三】整个项目的工期交付要求是4个月，设备的交付最迟在2个月内需要完成。【四】质保要求在标书有的地方说1年，有的地方说2年，正在澄清中。', '', '投标文件审核、资质审核、技术方案和报价方案评估（详见EN版标书第4个section）', '', '分2个LOT，LOT1：两个光伏/柴油混合电站和两个低压微型配电网的供应，安装和调试；LOT2：供应用户连接设备。2个包可分2家中标，也可1家中2个包。', '', '投标保函（LOT1：19000美元；LOT2：6000美元）；履约保函：10%合同总额', '', '资质要求不高。过去3年内有类似项目的经验；仅LOT1的最近三年平均最低营业额为200,000美元#FE54`最近3年的平均最低营业额为100,000美元（仅限LOT 2）；过去三年中，针对02个LOTS（LOT 1和LOT 2）竞标的竞标者的平均最低成交额为300,000美元。', '', '投标资料为【法语】', '', '代理投标，银河授权供货', '', '', '', '每一期完工验收通过后30天内付款', '', '联合国资金支持，付款能力较好。', '', '合作伙伴具有较强的运作能力，能抓住问题的关键并很好地配合银河。老板正值盛年，野心勃勃，非常活跃，本地关系脉络广。', '', '银河与业主无直接联系。', '', '已知有5家竞争对手，更多详情仍在了解中。', '', '优势：本地活动能力强的代理关系+执行力强的银河团队。劣势：实施设计方面经验不足，对银河有一定的挑战。', '', '1.项目时间，正在争取延期中，预计可延到5月22日。2.紧密的团队合作和专业的技术支持。', '该项目总的规模不大却比较精细，与银河+耐吉亦有较多的相关性，对转型成长有一定的垫脚石意义，值得尝试,争取拿下。', '陈雁2020-04-27 10:46:59', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('447', '{5673CB21-D908-4BFE-8E4A-B15FF51CD4F7}', '61', 'INHE-0793', '2020-05-01 23:12:01', '0000-00-00 00:00:00', '2020-05-06 10:57:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2020050101/TTP\r\n', '坦桑市场电表周边产品“塑胶旋钮卷线铅封”招标，银河直投', 'PA/001/2019-20/HQ/G/246', '2020年5月22日', 'SUPPLY OF PLASTIC TWIST TIGHT SEALS TO BE USED ON SINGLE PHASE AND THREEE PHASE PRE-PAYMENT SPLIT TYPE RF SMART METERS FOR REPLACEMENT OF DEFECTIVES                                                    供应可用于单三相预付费分体式RF通讯智能电表上的聚碳酸酯卷线铅封以供替换问题铅封', 'TANESCO付坦先令。                                                    国外付款条件为：                                                     (1)10%的合同金额在收到供应商提供的提单，商业发票，保险证书，原产地证书，装箱清单，测试证书，质量证书后以不可撤销的信用证的方式在供应商授信的其国内银行开出。(2)90%的货款在供应商提供付款申请和由采购方签署的验收证明后的60天内支付。                                                         国内付款条件为（本次标书条款注明不适用，估计有误，以下为常规国内付款条件）：                                                              (1)无预付款和发货款。                                                (2)100%的合同金额，收货后在提交付款申请和电力公司的验收证明后60天', '{5673CB21D9084BFE8E4AB15FF51CD4F78442F4C2B3234363A3D51C033076BD50}_G 246 SEALS FINAL VERS.pdf', '公开性国际招标，本地厂家有15%的优势(主要体现在价格),先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。\r\n', '', '公开性国际招标，只有一个lot，标书未明确可分标，参考历史中标记录，只有一个厂家可以中标。\r\n', '', '需投标保函，价值两千三百万先令或1万美金，合人民币7万左右；本次投标我司准备投标保函。                                                       投标有效期：投标有效期后28天，即148天，可按150天出具。履约保函为每个分订单和LPO的10%，质保保函2%，由我司负责所有的保函。\r\r\n', '', '\"1. 财务能力\r\r\n1.过去三年年平均年度营业额，不低于TZS. 700,000,000.00或相等金额。\r\r\n2.过去三年审计的财务报告（含资产负债表），现金流等。\r\r\n3.投标者需要证明有足够的流动资产和银行信用，符合供货的现金流要求。\r\r\n2. 技术能力和经验\r\r\na,至少三年供货或生产类似产品的经验。                                                  b.过去三年内完成类似合同且满足以下条件：至少三个体量相同的合同且每个合同金额不低于TZS 900,000,000.00\r\r\n3.生产能力\r\r\n提供厂家证明等必须资料来证明生产能力和执行供货能力。\r\r\n4.法律能力\r\r\n提供文件证明完成了付税和社会安全贡献义务。\r\r\n没有因欺诈，腐败，不诚信而被定罪\r\r\n具备签订合同的法律能力等。投标人也需提供相应文件证明其经厂家授权且可以在坦桑境内供货。                                                       5.商务文件                                     ', '', '技术应答表，技术无偏差申明，非危险物质申明里面的元器件供应商证书，装箱信息,灼热丝测试证书，相关常规测试证书和形式测试证书（如有），详情可参照标书要求。\r\n', '', '银河直接投标，给ITL佣金（主要是公关事宜）。', '不适用\r\n', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。合作伙伴在本地有较好的经济实力。\r\n', '', 'TANESCO 电汇和LC付款美元/坦先令。主要对接部门为采购，用服和财务。TANESCO付坦先令。                                                    国外付款条件为：                                                     (1)10%的合同金额在收到供应商提供的提单，商业发票，保险证书，原产地证书，装箱清单，测试证书，质量证书后以不可撤销的信用证的方式在供应商授信的其国内银行开出。                                                    (2)90%的货款在供应商提供付款申请和由采购方签署的验收证明后的60天内支付。  				\r\r\n国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后60天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。\r\r\r\n', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好。\r\n', '', '本标为我司直接投标，本地有小A可以作为合作伙伴协助推进。经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电及电表周边产品业务。\r\r\n', '', '电力公司副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。\r\n', '', '主要竞争对手EDMI，海兴，威胜，CLOU，STAR等，EDMI主要支持者是电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。威胜主要支持者电表部经理，采购经理，电力化部门经理等。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。海兴和CONLOG的坦桑代理ACHELIS合做，主要支持者为电表部经理，高级配电经理，实验室工程师等。STAR目前客户关系较弱，直接做本地的市场，代理商还有待确认。目前市场上主要的本地厂家为ITL，EDMI，WASION, CLOU,海兴其中ITL，EDMI,WASION和CLOU四家可以合作。铅封作为电表周边产品，国际招标，也将牵涉到其它国际厂家，如深圳Intersky等本地关系较弱厂家/经销商。此标的价值较小，本地的电表厂家不一定都会参与投标。\r\r\r\n', '', '该标为公开性国际投标，银河可以直接参与投标。作为电表周边产品，该标目前主要吸引的是坦桑一些本地厂商/经销商，根据TTE的经验，威盛和海兴也肯定会参与。目前主要竞争对手有海兴，威胜，STAR等代理商，此前已打交道多次，有应对经验和策略，可以灵活处理关系进行竞争；本标只有一个LOT，需要和代理协商并考量相应竞争策略以便约见合适内线洽谈利益，有关OA将很快发出。经过标前解析，目前已经确定我司有现成产品，只需根据技术规格做相应调整，报价方面将根据去年TTE的开标均价给到公司以做参考。客情方面和电力公司，以及政府的关系较好，银河也有自己的内线人员。整体上我司投标和中标的几率较大,可以逐步增加坦桑供应产品的种类。\r\n', '', '产品报价符合市场形势，样品符合电力公司要求，技术支持，商务和研发人员响应到位，必要的客户关系建设开销等。\r\n', '项目数量大，有一定利润，电力公司内部关系有较好基础，公司有现成产品，将争取中标并通过此标巩固银河自身的客户关系网；目前在标前已经有进行技术解析，对产品情况有所了解，建议立项，由商务和客服提供支持以便快速响应支持业务投标和争取订单。\r\r\n', '辛方腾2020-05-01 23:48:42', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('448', '{59E06073-1646-44DF-81F4-C352F6A7B5F2}', '66', 'INHE-0634', '2020-05-08 09:38:50', '0000-00-00 00:00:00', '2020-05-12 08:49:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020050801/KKA', '', '1-23（T）/MESC/2019-2020', '5月28日', '采购三相智能电表', '标书中价格条款：DDP Mandalay,本项目为缅甸币项目，且对投标人有限制，必须本地企业主投。代理与银河之间的价格条款为CIF仰光，付款方式待协商。', '', '样机通过测试的最低价中标', '', '1个LOT，1家中', '', '由代理负责', '', '电表需要提供TYPE TEST报告，其余条件银河均满足', '', '同APE项目', '', '银河授权代理投标，银河仅供货', 'N/A', '所有技术要求和评估结果由仰光实验室和MESC评标团队决定，仰光实验室决定样机是否合格，MESC评标团队决定投标文件是否合格，双方意见出来以后不容外界质疑，具有绝对的权威性。但是其决策过程不透明，决策结果也不完全公正，需要有稳固的客情建设。', '', '验收合格后30天安排付款。', '', '从历史情况来看，招标方的支付能力好，信誉高。', '', '合作伙伴PME与仰光实验室较为熟悉，已经从实验室处了解我们与Alpha在APE项目中的情况；其在MESC内部应该也是有一定的关系（有待核实）。从目前网络上可以搜集到的信息来看，其公司规模不算小，与其合作有一定的财力保障。（右侧附件是PME的董事长，执行董事和总部大楼照片，仅供参考。）', '{59E06073164644DF81F4C352F6A7B5F2D18C251E4D454BA8A05CF92EE9AFCB77}_PME董事长照片.png', '（1)银河与仰光实验室二把手较为熟悉，但是未与实验室一把手建立起直接联系；与MESC评标团队无联系。(2)银河在缅的主要合作方曾经有Alpha和KMN，Aplha与secure独家合作，与银河分道扬镳；与KMN合作过NBL（考虑充分，价格太高）和MMR（价格几无利润，以0.5美元的价差与成功失之交臂）项目都失败了，合作积极性不高。综合来看，银河客户关系有很大的提升空间。', '{59E06073164644DF81F4C352F6A7B5F2829EEF953ECA4F9B96CB5DED652FA321}_PME执行董事照片.png', '主要竞争对手是来自中国的各个表厂，价格水平较低。详见MMR竞投OA。', '{59E06073164644DF81F4C352F6A7B5F2C8C3CDC70C5243B796247CC1ED7EC56E}_PME总部大楼外观.png', '银河在缅甸市场已经非常熟悉技术要求也有对应的技术方案，缺乏的是客情建设（与本地合作方和业主2处都不够紧密），可借助新开发客户PME的关系，重整旗鼓。', '', '（1）符合要求的样机和投标文件（2）有竞争力的产品方案和报价（3）客户关系【第一点是门槛，第二三点是翅膀，少哪一边都飞不起来】', '（1）与APE项目曾经中标的1万台三相表要求基本一致，但是报价方案万不可参照APE，需要进一步了解行情变化，谨慎报价。（2）虽然在缅甸市场多次失败，但是每次的情况都不一样，我们确实积累了经验和教训，不会摔倒在同一个地方，从MMR项目开标结果来看，我们已经非常接近，说不定成功就在下一个拐角，不应止步。（3）建议立项，继续努力！', '陈雁2020-05-08 11:16:17', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('449', '{AC689EA3-FDAA-45F7-A1E2-9671FC40D370}', '61', 'INHE-0432', '2020-05-08 15:47:02', '0000-00-00 00:00:00', '2020-05-12 08:47:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020050802/KFE', '', '1.该标2019年招标，2020年2月截标。2020年5月废标。2.预计2020年5月中下旬重新招标。', '待定。', '后付费电表供货（公开国际招标）', '1.价格条款：DDP含VAT\r\n2.付款主体：KPLC\r\n3.交期：拿到合同、PO开始交付，分3批交付。\r\n4.质保：5年。', '{AC689EA3FDAA45F7A1E29671FC40D3708442F4C2B3234363A3D51C033076BD50}_后付费简单表招标 商务标书 201912.pdf', '1.商务评审\r\n2.技术评审：资料、样机测试。\r\n3.财务评审。', '', '综合评标价格最低者中标（1个LOT,1家中标人）', '', '投标保函：2万美元；履约保函：合同10%', '', '1.需提供2份用户证明', '', '1.需要研发做样机；投标资料由IAC商务完成。', '', '1.IAC直接投标。', 'N/A', '1.评标团队评标起关键作用；\r\n2.需要做好采购总监及MD的客户关系。', '', '满意交付及提交资料后的30天起，开始付款。', '', '', '', '1.IAC直接竞投，或者IAC投标，代理负责竞投。届时再和代理商量。\r\n2.代理与高层客户及评标团队关系较好，但与采购总监无合作关系；IAC自己与采购总监有直接合作，所以必要时，IAC可以直接自己竞投。', '', '较好', '', '本次招标又被废标的项目，主要参与者有：思达、华越、东孙电子，海兴（但是未提交样机）。思达、华越、东孙电子均过了技术评审。', '', '1.请公司参考价格，给出较合适的价格。\r\n2.鉴于前几家均过了技术样机测试和技术评审，所以此次，估计是需要“最低价”中标。\r\n3.同步提前做好客户关系。', '', '1.价格合适，样机能及时交付，且通过测试。', '后付费电表价格低，利润低，但是对IAC是个不错的业绩机会，值得争取。', '谭东羊2020-05-08 18:51:31', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('450', '{FBBCFA11-375D-4E40-A9DA-7E0E12756036}', '61', 'INHE-0440', '2020-05-14 02:31:08', '0000-00-00 00:00:00', '2020-05-15 18:04:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2020051401/TTU', '', '不适用', '不适用', '不适用', '经销商直接采购，远期180天信用证付款，允许我司融资和即期贴现，客户承担融资费用。', '', '不适用', '', '不适用', '', 'ITL负责各类保函', '', 'ITL负责提供，我司支持相关的资质文件，供货记录和证书', '', '不适用，如果需要，后期再找公司提供相关的技术和商务资料', '', 'ITL授权本地EPC合同商投标，或银河授权ITL投标。', '不适用', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。', '', '电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后60天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，ITL在短期内扩建了新的绝缘子工厂，导致财政紧张，TT支付难度大，但支付信用证问题不大，目前银行融资额度为5百万美元。\r', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电业务。', '', '电力公司副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。', '', '主要竞争对手EDMI和CLOU，EDMI主要支持者是电表部经理，实验室电表工程师，采购部经理，以及本地的代理商Comfix&Engineer。CLOU主要是采购经理和电表部经理，以及本地的代理商Bahdela。EDMI和CLOU主要供货单三相直通表，本地价格可以做到EXW 40 USD。目前市场上主要的本地厂家为ITL，EDMI，WASION, CLOU, HEXING。READY BOARD的主要经销商为EDMI和CLOU代理。农电低价单三相表的主要供货厂家为CLOU，EDMI和威胜。', '', '整体上对该市场的技术，商务都有较大把控力。目前主要竞争对手有EDMI和CLOU等代理商，此前已打交道，有应对经验和策略，可以灵活处理关系；客情方面和电力公司，以及政府的关系较好，银河也有自己的内线人员，本地的EPC合同商也有一定的合作经验。', '', '产品设计和报价符合市场形势，技术支持，商务和研发人员响应到位，经销关系维护，必要的客户关系建设开销等。						\r', '建议立项，改善和降低产品成本，争取农电项目的订单。客户这边每年损失较多的订单，主要是由于产品的价格高，若降价后销售，无利润或利润很小。', '汤伟2020-05-14 02:42:13', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('451', '{05D35616-3399-43BD-9FE1-0B485B525829}', '61', 'INHE-0772', '2020-05-14 16:19:56', '0000-00-00 00:00:00', '2020-05-15 18:18:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020051402/ABF', '', '002-2020/ABER/PASEL/DG/DM', '2020.05.26', '为电力支持项目（PASEL）的电气化地区提供10,500个智能通信仪表和连接附件Fourniture de 10 500 compteurs intelligents communicants et accessoires de branchement au profit des localités électrifiées du Projet d’Appui au Secteur de l’Electricité (PASEL)', '', '{05D35616339943BD9FE10B485B5258298442F4C2B3234363A3D51C033076BD50}_DAO pour la fourniture de compteurs intélligents PASEL-Lot Unique 23avril2020.pdf', '基本符合技术要求的最低价者中标', '', '一家中标', '', '代理开保函', '', '过去5年至少有1个相似项目；STS证书', '', '智能表项目用户证明，HES与后台系统的集成方案', '', '代理投标', '否', 'ABER负责评标', '', '						\r\r\r\r\r\r\r\r\r\r\r\n预付款：将在合同签署后30天内支付合同价格的百分之十（10％），以支付请求为准，（I）并提供同等金额的银行担保（II） 有效期至供应品交付为止；(III)并且符合招标文件中提供的标准格式或买方可接受的其他格式。\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\n发货：将通过供应商在其所在国家/地区的银行的信用证中开立的，不可撤销的信用证，支付发货合同价格的百分之八十（80％） 在CCAG第13条中指定合同金额10%的履约保函。\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\n验收后：将在收到货物后三十（30）天内支付所供应供应品合同价格的百分之十（10％），并附有由买家签发的验收证明的，履约保函释放', '', '本项目由世界银行出资', '', '\r\r\n合作伙伴为SOCOTAN：由SONABEL内线推荐，多次中标，本地关系和实力较好', '', '银河与农电局的联系不多，上一次ABE项目也是支持当地代理投标。', '', '最大竞争对手为本地公司ALIOTH ，她们供应了后台系统。\r\r', '', '银河与农电局的联系不多，客情薄弱。在标书条款允许厂家不直接投标的情况下，可以支持多个投标人投标。在无法判断代理实力和不需要样机的情况下，支持多个代理投标争取胜算最大化。', '', '本项目为授权投标，代理的当地与农电客情起关键作用，银河及时提供投标文件给即可。', 'ABF项目有多个公司联系银河希望我们提供厂家授权支持她们投标，筛选出两个合作，其中一个为ETBL（询盘）和SACOTEN（内线推荐），标书允许厂家不投标的情况下，可以支持多个投标人，不形成利益冲突。目前通过代理ETBL澄清为不需提供样机，减少了样机投入。公平支持2个代理投标，无需开保函，只需提供电子档资料给代理投标即可。', '张子琦2020-05-14 19:22:15', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('452', '{67487C3F-A96A-49AC-8CB5-32146C413384}', '61', 'INHE-0885', '2020-05-18 15:19:27', '0000-00-00 00:00:00', '2020-05-20 09:03:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020051802/MER', '', '047-MoE-MAREP-PH9-G-NCBFY19/20-08', '2020年6月12日，当地时间10点', 'Supply and Delivery of MAREP Phase 9 Materials供应和配送Marep第9阶段所需产品', '价格条款：DDP\r\n交期：产品需在签订合同后的6-10周运抵\r\n违约金：违约金应为：每周0.5％，最高3%\r\n付款条件：买方应在交货日起的30天内全额付款', '{67487C3FA96A49AC8CB532146C4133848442F4C2B3234363A3D51C033076BD50}_表1：Marep投标项目信息归纳表.doc', '1.	初步评标，确认标书的完整性#FE54`填妥并签署的投标书#FE54`委托书#FE54`投标保证金#FE54`提供证书,投标的有效性；合格国家的投标人；确认投标人已接受GCC和SCC中规定的所有条款和条件。\r\n2.	技术评标\r\n3.	商务评标，投标价格#FE54`调整价格以纠正算术错误#FE54`因折扣而调整的价格#FE54`不符合和遗漏的调整#FE54`适用所有评价因素、评价和资格标准#FE54`和由于适用优惠幅度而做出的调整，\r\n', '{67487C3FA96A49AC8CB532146C413384074E749A304748709C51373D9D483750}_Gds- NCB-SBD-Section 2f.pdf', '共计4个LOT，一个LOT只有一家可以中。\r\n符合技术规格，低价者中标', '', '1.	投标人必须签署并见证的投标保证金或投标保证声明表格。或\r\n2.	对于选择提供投标保证金的投标人，其金额和币种投标保证金应为 MK 1,000,000.00\r\n3.	投标保证金的有效期为投标有效期结束后的28天\r\n', '', '1.	符合最低技术规格\r\n2.	ISO 9001 and ISO 14001\r\n3.	厂家授权书\r\n4.	制造商具有足够的技术知识和实践经验的证明，过去5年内每年至少有1000万台电表的生产和出口能力。\r\n5.	投标人应提供书面证据证明：a。在截至2019年12月的过去两年中，至少为两份合同提供类似的货物，每一份合同的价值等于或大于其投标金额。\r\n6.	过去两年中一直在提供类似类型的商品（电子材料）的书面证据，还随附成员可用来确定经验的文件（仅供参考）或推荐信。提供至少两（2）件具有相似商品和价值的可追溯合同的书面证据\r\n7.	资金可用性证明：超过或等于投标金额1.5倍的资本或信贷额度或\r\n8.	最近3年的经审核账目\r\n', '{67487C3FA96A49AC8CB532146C41338403404677E4D44E9EB56B3D512B2AF9CC}_Gds- NCB-SBD-Section 3.pdf', '技术资料需客户协助', '', '代理直投', '', '能源部为政府单位，政府直接决定', '', '在交货日起的30天内全额付款', '', '由马拉维国家政府直接拨款', '', '合作伙伴比较熟悉马拉维的招标流程，有一定的客户关系。', '', '银河的客户关系主要在电力公司ESCOM，能源部主要依靠与代理的客户关系', '', '该项目主要竞争对手为海兴和科陆。科陆代理为山东机械进出口，其主要背景关系为前董事会主席以及有政府背景人士，科陆在该市场供货单相表8万台左右，市场口碑较差。海兴在本地市场新代理目前不详，之前项目竞争策略为低价竞争。', '', '1. 通过熟络标书商务和技术条款，制定技术澄清进攻策略。\r\r\r\n2. 通过代理的客户关系与采购和评标团队达成合作，进行项目运作\r\r\n3. 取得竞争对手投标资料，针对竞争对手的弱项制定进攻计划', '', '项目成功的关键：1. 符合要求的投标资料和与合适代理的合作 2. 通过代理完成客户关系的运作 3. 针对竞争对手的弱项制定进攻计划。', '该项目标书中存在一些不清楚的点，建议尽快完成商务和技术解析，以便制定完整的竞争策略。', '潘健康2020-05-18 15:52:47', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('453', '{1A5FBF7E-5505-4249-A7BF-7618AD38CAFD}', '66', 'INHE-0634', '2020-05-22 14:07:55', '0000-00-00 00:00:00', '2020-05-26 10:58:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052201/NAL', '', '非投标', '', '智能城市Pyin Ma Nar', '价格条款：CIF仰光；运输方式：海运（15-20台样机可协商DHL快递或交由客户在深圳的货代进行安排）；质保：1年；付款方式：样机和1000台表采购均为100%TT预付，系统付款方式待协商，5万台表付款方式待协商。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '客户的合作方直接投资，与MOEE合作。资金是否真实到位有待进一步了解。', '', '', '', '', '', '', '', '', '', '符合要求的技术方案+与客户友好密切的配合协作', '从目前的沟通判断，客户配合度高，技术沟通无障碍。附客户设计的抄表系统界面（虚拟数据）供参考：\r\r\r\r\r\r\r\r\r\nhttp://103.83.190.197/meter/public/admin 用户名：admin@gmail.com 密码：admin123\r\r\r\r\r\r\r\r\r\nMOEE对于系统有明确规定必须是缅甸文，客户团队愿意全力配合我方做必要翻译，可为将来参与电力局直接招标的AMI项目做铺垫，还可节省下一大笔翻译费（缅甸小语种，翻译费用高昂）。纯电表招投标竞争激烈且利润低，带AMI系统这样附加值较高的项目是不错的商机，建议参与。', '陈雁2020-05-22 15:15:03', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('454', '{8D88733A-9713-471A-B192-069DA2A0CD11}', '61', 'INHE-0793', '2020-05-25 04:21:45', '0000-00-00 00:00:00', '2020-05-25 18:09:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052501/TPA\r\n', 'TPA项目坦桑湖区招标采购11KV&33KV自动重合器和负荷开关', 'TENDER NO.  PA/001/2019-20/LZN/G/41', '2020年6月8日', 'SUPPLY OF LOAD BREAKER SWITCHES (LBS) AND AUTO-RECLOSURES (AR) FOR 33KV AND 11KV AT LAKE ZONE         供应11KV和33KV柱上安装自动重合器和负荷开关给坦桑湖区', 'TANESCO付坦先令。                                                    国内付款条件为： (1)无预付款和发货款。（2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。                                                                         质保期限：接受货物起12个月。交期：合同签署后三年内执行，然而本地厂家需要在收到电力公司签发的LPO后4周内供货。                                           违约：百分之0.1/天，未发货产品，最多10%。                                   国外付款条件为：不适用                                                     代理对银河电力/银河电网付款方式：不可撤销的远期180天保兑信用证或中信保承保赊销\r\r\r\n', '{8D88733A9713471AB192069DA2A0CD118442F4C2B3234363A3D51C033076BD50}_Bidding TANEPS used  Document  -LBS-G.41.doc', '本地限制性招标，本地厂家和本地供应商都可以投标。先评估技术，然后评估商务，实际上一审是商务和技术一起评估，最后从技术合格的里面选价格较低者中标。\r\n', '', '本地招标，一共有5个lot，投标人可以任投每个LOT或全投，但是单个厂家最多只能中两个LOT。\r\n', '', '无需投标保函，本次投标建议由ITL/Africarriers 准备投标保证声明，投标有效期：投标有效期后30天，即150天。履约保函为每个分订单和LPO的10%，质保保函2%，由ITL/Africarriers 负责所有的保函。\r\n', '', '1. 财务能力（未明确，按常规标书出具）\r\n1.过去两年年平均年度营业额，不低于TZS. 100,000,000.00或相等金额。\r\n2.2018年审计的财务报告（含资产负债表）。\r\n3.投标者需要证明有足够的流动资产和银行信用，符合供货的现金流要求。\r\n2. 技术能力和经验\r\n投标者/厂家至少2年制造或供货中压配电产品经验\r\n符合标书的技术要求\r\n投标者应该提供文件证明其符合以下经验要求：\r\n至少2年经验供货和制造招标要求的类似产品\r\n过去两年成功完成的合同符合以下最低要求：\r\n至少两个相同规模的合同\r\n合同清单包含至少所供货的物料信息，数量，服务，合同金额，买方联系方式。\r\n3.生产能力\r\n提供厂家证明来证明生产能力和执行供货能力。\r\n4.法律能力\r\n提供文件证明完成了付税和社会安全贡献义务。\r\n没有因欺诈，腐败，不诚信而被定罪\r\n具备签订合同的法律能力\r\n投标人要求在其文件中提供在坦桑尼亚供货产品的厂家的授权                     5.商务文件                                                            ', '', '技术应答表，非危险物质申明里面的重合器和断路器器件供应商证书，图纸和装箱信息，常规测试报告，型式测试报告，防腐蚀报告，镀锌测试报告。具体参考标书技术要求，最迟6月2日提供。\r\n', '', '银河支持ITL工厂投标，ITL中标后，从银河采购SKD/整机。', '不适用\r\n', '电力公司为半国营，政府对采购的决策影响较大，资金来源主要依靠政府的年度财务预算和国际贷款，有较多的债务需要偿还，整体朝好的方向发展。经销商在本地有较好的经济实力，中标后希望我们帮忙LC融资付款，愿意付贴现费用，给予他们付款灵活的期限。\r\n', '', 'TANESCO 电汇付坦先令。主要对接部门为采购，用服和财务。国内付款条件为： (1)无预付款和发货款 （2）100%的合同金额，收货后在提交付款申请和电力公司各批次的验收证明后30天内支付。正常交货后，提交发票，FAT报告，VAT单据，验收证明和交货单据给合同经理，跟进合同经理提交资料给财务经理，跟进财务经理找财务总监付款。\r\n', '', '电力公司目前收了较多的欠款回来，支付能力较之前要好，主要依赖政府资金，国际援助资金和贷款等。代理商/经销商公司较大，目前现金流不大好，ITL在短期内扩建了新的绝缘子工厂，导致财政紧张，TT支付难度大，但支付信用证问题不大，目前银行融资额度为5百万美元。\r\n', '', '经销商可以接触到政府能源部和工业部，甚至是总统，有专人做政府关系。电力公司高层MD,配电副总，TB主席，财务总监，采购经理，电表部经理，实验室经理等。和经销商关系融洽，经销商老板年纪较大，性格比较温和，公司经济和政治实力较好，但缺乏做电力公司项目的团队和经验，需要我司支持做好电表和配电业务。\r\n', '', '配电副总，采购经理，电表部经理，市场经理，AMR中心主管，实验室主管，配电和测试工程师等。\r\n', '', '主要竞争对手TANELEC，AFRICAB，MULTICABLE，MACROPLAST等，各厂家的主要支持者待确认，初步判断参与和决策人员与电表业务类似。目前市场上主要的本地厂家为TANELEC，AFRICAB，MULTICABLE，MACROPLAST,其中TANELEC和AFRICAB在本地有较好的供货基础和客户基础。本标为TANESCO湖区招标，ITL有较好的内线关系，电表类产品也已有供货经验，可以同比提升配电业务的竞争力。\r\n', '', '该标为本地招标，我司不能直接投，付款条件为100%到货验收后付款，故而考虑授权给ITL代投，只需要提供资料，不需要样机和保函投标，风险和投入较小。中压配电产品在投了TTO，TTQ项目以后，目前对商务、技术文件以及价格都有一定把控力，坦桑湖区在电表业务也有供货基础，可以作为跳板。ITL在本地已经有较好客情积累，而真正的强力竞争对手只是TANELEC，AFRICAB，其它厂家在配电上的水平差别不大，我司可以灵活操作，且本标LOT较多，运作空间较大。代理商和电力公司，以及政府的关系较好，银河也有自己的内线人员，我司支持ITL投标和中标的几率可控。\r\n', '', '产品报价符合市场形势，技术支持，商务和研发人员等响应到位，必要的客户关系建设开销等。\r\n', '本标招标产品和TTO，TTQ项目招标产品相似度高，此前两个项目投完后业务已经对配电项目有一定经验，再者ITL在本标采购主体“坦桑湖区TANESCO分公司”已有电表供货经验，是发展配电业务的较好跳板。建议立项，准备文件，支持ITL投标和争取订单。\r\n', '辛方腾2020-05-25 04:36:19', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('455', '{96A4E3EF-9B7D-4D45-86D6-6A8EDE67798F}', '61', 'INHE-0772', '2020-05-27 18:33:10', '0000-00-00 00:00:00', '2020-06-05 13:38:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052701/LBB', '', 'Q19047EK', '2020.07', 'IMPLEMENTATION, OPERATION AND MAINTENANCE OF A CENTRAL ADVANCED METERING INFARASTRUCTURE(AMI) SYSTEM 中央高级计量基础设施（AMI）系统的实施，操作和维护', '对软件，硬件，施工和服务均规定了明确的付款节点。 要求预付款保函，履约保函. \r\r\r\r\r\r\r\n\r\r\r\n1. 10%预付款：在合同生效后60天内，收到中标人等额的预付款保函。\r\r\r\r\r\r\r\n\r\r\r\r\r\n2. 项目执行款80%：\r\r\r\r\r\r\r\n（1）系统相关类付款80%：            \r\r\n系统类：完成主备服务器所有系统安装付20%+完成SAT现场验收付40%+现场验收完成后支付15%+FAT完成付5%.\r\r\n系统设备类付款：\r设备供应完成付20%+SAT完成付40%+现场验收完成后支付15%+FAT完成付5%.\r\n（2）系统相关付款80%：\r\n设计阶段+开发阶段：80%；\r\n需求变更：80%，36个月，每个月1%+44%变更收到FAC；\r\n运营和维护：80%，执行54%+IAT13%+FAC13%；\r\n项目管理80%：4年项目管理月度报告72%，每月支付1.5% + 4年终项目管理报告8%，每年支付2%\r\r\n\r\r\r\r\r\n3. 项目抵押款10%\r\r\r\r\r\n-质保期结束后付5%\r\r\r\r\r\n-质保验收证颁发后付5%', '{96A4E3EF9B7D4D4586D66A8EDE67798F8442F4C2B3234363A3D51C033076BD50}_7- Terms and Procedure of Payment.pdf', '技术符合的最低价中标', '{96A4E3EF9B7D4D4586D66A8EDE67798F074E749A304748709C51373D9D483750}_3- Instructions to Bidders.pdf', '1家中标', '{96A4E3EF9B7D4D4586D66A8EDE67798F2B47EB25ABE84FF19C47768372BB342D}_3- Instructions to Bidders.pdf', '投标保函30万美金，履约保函10%，预付款保函10% ', '', '最近5年平均营业额为8000万美金，或收入是5倍当前项目报价。财务能力要求盈利，要体现可持续盈利，稳定经营', '{96A4E3EF9B7D4D4586D66A8EDE67798F03404677E4D44E9EB56B3D512B2AF9CC}_2- Post Qualifications.pdf', '财报要经过双边公证（中国外交部，黎巴嫩驻中国的商赞处）', '', '联合投标', '1.联合投标的原因：一是我们在黎巴嫩市场的开发程度有限，受宗教影响，政治交替频繁，环境复杂，这个项目执行的周期长，该类型项目的审批流程长，需要当地有关系有项目经验的公司领路和配合。二是投标游戏规则不熟悉，从使馆公开的央企投标记录看，当地的游戏规则偏袒本地且业主由绝对的权利，我们也需要依靠代理的当地关系和投标经验。三是中标后的回款问题。\r\r\n\r\n2. 我建议是代理主投，代理开保函。黎巴嫩属于战乱国家，近年开始慢慢恢复稳定，以往记录项目履约能力较差，目前业主履约能力仍有待中信保考证。 \r\r\n\r\n3. 分工（暂定）：代理负责保函开立，当地客情攻克，争取中标，中标后付款跟催，验收文件签回。项目实施：工期前两年的实施部分由银河负责，后2年的维运工作由代理负责。 ', '业主EDL的决策权占大比重\r\n', '', '', '', 'EDL的支付能力很差，本项目是与世行的混合融资，世行项目，付款有一定背书。\r\n', '', '从代理网站和公司介绍上看：代理有电力行业（发电，中高压输变电，配电箱）的经验，且有发电站设备运维，输配电的供货经验，部分GIS系统运维经验。在ABF项目的合作中可以看出他们对招投标熟悉。但当前对代理的缺少实地考察和交叉验证，电力公司网站的信息有限，对于代理提及自己是EDL认可的供应商，他自称的项目经验真实的验证待完成。\r\n', '', '无', '', 'EDL下有3个配电服务商分别为NEEDS, BUS，KVA，负责电表安装服务，采购由EDL资金由EDL承担。在2014年，新闻报道有几家欧美厂家中了EDL的4年框架总计120万的电表合同，分别为：Itron, Echelon, Sagem, ZIV , El Sewedy Electrometer / ZPA Smart Energy.低压用户电表为通讯方式PLC PRIME，高压为GSM。中国厂家没有太多信息，供货记录需查看海关数据。该市场地理位置靠近欧洲，此前项目资金多来自欧洲附信银河和巴黎俱乐部，项目资金带有偏向性，多被欧洲厂家获得合同。其他的行业看，中东市场是更偏爱欧美厂家，因为产品质量和售后服务有保证，分析评估该市场的中国电表厂家较少。', '', 'S：我们软件产品符合标书技术要求，项目资质也基本符合。对标欧美厂家，我们有价格和服务优势。\r\r\r\r\nW：对于市场很陌生，没有客情建设。\r\r\r\r\nO：本地竞争者是欧美参加为主，不必打价格战；项目对系统的证书要求少，安全层面证书要求也少。\r\r\r\r\nT：当地客情依赖代理。当地市场对中国供应商的偏见。\r有多个供货的电表厂家。兼容任务多。\r\r\r\n', '', '资格审核是目前最大的难关，其中的财务文件涉及双边公证，非常耗时，也有成本投入。\r\r\n需要支持：1. 公证费用投入。 2. 财务部门提供精简版的财报（目前公司投标所用的财报是完整版，对比同行财报精简版）\r\r\n费用降低建议：\r\r\n1. 简化公证材料，资料少了，能够同时减少公证的审批时间和成本。\r\r\n2. 公证翻译成本也可通过，被公证处认可的翻译公司盖章。\r\r\r\n', '这个项目对标欧美软件厂家，考验我们的做软件方案的能力。但是2个月的投标准备时间充足，证书要求比较少，主要是人力投入为主。本次合作的代理，有较多的投标和项目经验，借助代理的能量可以借助开拓本市场。如中标后，系统要集成多个欧美厂家的电表，业主对在项目管理和执行等等要求，对于我们是一次难得的提升机会。							\r\r\r\r\r\r\r\r\r\n', '张子琦2020-05-28 18:21:25', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('456', '{D3BDEF2F-9A5C-4BC6-BF7F-50BAA3A3F8AD}', '61', 'INHE-0853', '2020-05-28 18:46:43', '0000-00-00 00:00:00', '2020-06-02 10:48:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052801/GSB', '', 'AOO  N° 02/PDSDE/BIENS/2020', '2020年7月21日，当地时间上午10点', '比绍市配电系统开发项目（PDSDE）', '1.质保：12个月，其中包括6个月的电表安装服务期。\r\r\r\n2.违约条款：未在规定交期内交付产品及服务，超出1天支付合同金额0.05%（1/2000）的违约金，违约金额不可超过合同总金额的5%。\r\r\r\n3.标书结算方式：  \r\n35,000个电表+配件的预付款（总金额的20％）：将由招标方指定的银行签发的保函100%担保（有效期至货物交付之前）。\r\r\r\n35,000个电表+配件的尾款（总金额的80%）：在收到发票及要求相关单据的45天内支付。\r\r\r\n校验台及安装、调试的服务费：在收到发票及相关单据的45天内支付全款。\r\r\r\n培训费用：收到发票及相关单据的45天内支付全款。\r\r\r\n安装电表费用：35000套电表在收到发票并附上UPG和EAGB签署的文件后，在6个月内安装完，并根据投标报价的电表安装费用单价，按月结算。', '', '基本符合招标文件的规定，且符合第三节评估和资格标准中规定的资质的，的最低价者中标。', '', '只有一个LOT，一家中标。', '', '投标保函：18万欧元或等值的自由兑换货币。 开立方为银行。有效期至投标有效期届满后的28天.\r\n', '', '1.近3年内无中标不履行合同的历史。\r\n2.财务能力：\r\n在过去三年中（2017年，2018年和2019年），经营活动的年均营业额至少等于1千4百75万欧元（14,750,000欧元）。\r\n投标人必须证明除了可能的启动预付款外，它还可以使用流动资产，未支配资产，信贷额度等融资：\r\n244万4千欧元（2,440,000欧元）\r\n注意：此财务能力必须出具银行证明。\r\n3.供货经验：\r\n过去五（5）年中在至少1个供应类似产品及相关服务的经验，合同金额至少为590万欧元。', '', '技术支持：输出样机规格书，技术应答表，提供技术资料等。\r\r\r\r\n商务资料：厂家授权，签字授权，财务能力，供货经验，ISO证书等。', '', '代理商投标', '', '业主方为国电，隶属于能源部，受政府影响大。', '', '由招标方审核评标并签订合同，融资银行审核最终中标结果并直接向供应商支付项目款。', '', '非洲发展银行直接支付，财务能力和资金状况有保障。', '', '基本国内的各大厂家海兴、科陆、思达、隆基等等都购买了标书，准备参与。', '', '代理在该市场多次供货，客户关系较强；银河出货过同类型的电表及电表配件，和售电系统。', '', ' AGS项目投标，海兴中标，供应过预付费电表。但并非本次招标的内置断路器款电表。', '', 'GS01中标，供过内置断路器的电表，本次标书技术规格基本为历史供货的电表规格。并且电力公司使用的是我们的售电系统。目前银河电表是最符合技术规格的。在此情况下，只要按要求提供技术文件，提供有竞争力的报价，银河赢标的可能性极大。\r\r\r\n', '', '保证电表、表箱严格符合技术规格，投标资料符合要求，尽快提供样机并保证样机测试符合要求，提供有竞争力的报价。', '本次招标为特殊定制的内置断路器电表，银河现有的电表产品是最符合技术规格的。在此情况下，只要保证表箱严格符合技术规格，并提供有竞争力的报价，银河赢标的可能性极大。', '胡亚婵2020-05-29 10:47:58', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('457', '{5BED5D32-1D3F-435E-8D19-DE274EE92A9F}', '66', 'INHE-0774', '2020-05-29 15:44:49', '0000-00-00 00:00:00', '2020-06-01 11:49:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052901/ECP', '', '43-V-10/20', '2020-06-29', 'Pilot project Advanced Measurement Infrastructure智能计量基础设施试点项目', '1. 价格条款：DDP 电力公司仓库\r\r\n2. 付款方式：收到发票后30天内\r\r\n3. 质保：最低3年\r\r\n\r\r\n', '', '在满足招标要求的前提下低价中标', '', '1个Lot,一家中标', '', '投标保函：1,400,000.00HRK(18,500 EURO)银行保函，期限长于报价有效期；\r\n履约保函：10% 合同金额，期限不短于交货后30天\r\n质保保函：10%合同金额，期限不短于验收后36个月\r\n', '', '证书：MID认证，CE认证\r\r\n供货记录：在投标截止日期之前的最近三年中，投标人已执行相似采购合同，累计金额等于或大于24,00万克罗地亚库纳（346万美元）\r\r\n\r\r\n', '', 'ESPD文件，电表操作手册、图纸、画册，证书等，供货记录，标书商务文件附件等', '{5BED5D321D3F435E8D19DE274EE92A9FC675BD0CC93442C09B990884D4324504}_DON_NMI EN.docx', '代理商投标', '', '', '', '收到电子发票后30天内付款', '', '预算700万欧左右', '', '合作方去年中通信模块招标，参与了2019年PLC电表招标，对当地招标流程熟悉；公司规模中上，有丰富的电力工程和电气安装经验。', '', '', '', '该市场主要被Iskraemeco垄断，供应GPRS和PLC电表；兰吉尔和本地电表公司RIZ占少部分份额			\r\r\n', '', '策略：该市场投标公司较少，通常是一两家投标，Iskraeneco中标，我们首次参与可以让竞争对手出其不意；我们可以充分发挥价格优势。\r\n劣势：标书为克罗地亚语，投标资料要翻译成克罗地亚语，投标要求尤其是技术规格难以理解透；当地的特殊要求我们不熟悉，希望通过当地合作方的支持能让我们熟悉当地的招标流程和技术要求。\r\n\r\n', '', '集中器的技术偏差和当地电表的特别要求，比如外置的按钮开关需要研发支持；三相表的MID证书，集中器的CE认证；', '克罗地亚市场需求大，竞争相对小，从以往招标技术规格来看要求相对没那么复杂，资质门槛也比较低，是我们进入欧洲市场的目标市场之一；参与具体的投标项目有利于我们了解招标流程，逐步了解技术要求，也有助于和合作方建立更紧密的联系。建议公司支持参投。 ', '何森华2020-05-29 21:08:26', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('458', '{EA7D2B15-BA9D-4EA2-824D-A5305B5AFB79}', '61', 'INHE-0432', '2020-06-12 17:00:46', '0000-00-00 00:00:00', '2020-06-16 09:32:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061201/KFF', '', '等正式发布标书后更新。', '等正式发布标书后更新。', '边界计量项目供货、安装及启动', '参考KE02：\r\n1.价格条款：DDP含税\r\n2.付款：满意交货（交付后由电力公司实验室测试）后30天起。且：\r\n产品：\r\n80%交付至现场后付；10%安装后付；10%滞纳金在保修期后付\r\n安装费：\r\n80%安装完成及系统启动后付；10%测试完成后付；10%滞纳金在保修期后付。\r\n保修期：成功安装及启动、测试后1年。\r\n3.质保期：系统及产品启动后18个月。\r\n', '', '参考KE02：\r\r\n1.商务评审\r\r\n2.技术评审：技术得分超过75分的才可以进入下一步评审。\r\r\n3.财务评审。\r\r\n综合评审，价格最低者中标。', '', '一个投标人只能中标1个LOT。\r\n', '', '投标保函金额：待定。履约保函金额：10%合同金额', '', '参考KE02：国际公开招标。供货记录：3份用户证明', '', '由IAC戴萍主导、总部商务组同事支持。', '', '银河直接投。', 'N/A', '涉及的部门有：采购部、能源损耗管理部、用服部、标准部等4个部门。项目金额不大，不要求样机，所以主要是评标组有决策权。', '', '同历史项目。', '', '受疫情影响，电力公司付款能力差。', '', '已知竞争对手：\r\r\n1.海兴：一直垄断LPU计量箱供货并控制着系统，且运行稳定。电力公司依赖程度高。\r\r\n2.IET：KE02有中标。且据说最终从海兴购买计量箱产品。\r\r\n3.思达、科陆等。\r\r\n', '', '较好。', '', '已知竞争对手：\r\r\n1.海兴：一直垄断LPU计量箱供货并控制着系统，且运行稳定。电力公司依赖程度高。\r\r\n2.IET：KE02有中标。且据说最终从海兴购买计量箱产品。\r\r\n3.思达、科陆等。\r\r\n', '', '银河优势：\r\r\n1.业务自己和代理均与电力公司有较好的客户关系。\r\r\n2.银河品牌影响力较好。\r\r\n银河劣势：\r\r\n1.目前在肯尼亚市场从未供过货。\r\r\n2.产品需要与海兴或中兴的系统兼容。按电力公司目前的态度，他们不愿意再额外使用另外1套系统，且项目数量本身不大。但业务会尽量去运作。\r\r\n\r\r\n银河策略：\r\r\n1.加深客户关系。\r\r\n2.按KE02项目，本项目预计将是2个LOT，2家投标人分。我们争取运作成1个LOT。\r\r\n3.说服电力公司愿意用我们的系统，银河将系统升级成SmartAMI.\r\r\n', '', '1.客情建设、商务运作（1个LOT，同意使用我们的系统，即去掉兼容的要求）\r\n2.报价：吸取KE02的教训，合理报价。', '业务认为是个不错的机会，值得去竞标，请公司支持。技术规格将单独发OA。', '谭东羊2020-06-12 18:18:02', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('459', '{2875A037-19E2-49F1-931C-1F19F511CE71}', '61', 'INHE-0913', '2020-06-16 09:27:18', '0000-00-00 00:00:00', '2020-06-18 15:06:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061501/CMC', '售电系统', 'N°2020/01/Comorsol/Log', '2020-07-07', '科摩罗信息系统设计，供应和安装', '标书价格条款:CIP\r\r\n代理商付款方式：暂定', '', '技术，商务和财政部分有单独的分数计算公式，总分数计算公式为：\r\n（评估报价/合规的最低价格）*标书指定价格权重+分配给报价的技术点总数/获得最高技术分数的合格投标的技术点数*(1-标书指定价格权重)', '', '共八个lot，联合投标成员不超过三个，现场开标', '', '投标保函：27900欧元（代理商开具）', '', '针对银河分包的STS部分：标书要求投标人必须是STS协会成员，并且至少有两个以上STS项目的成功经验', '', '需要软件部门给出完整的STS方案', '', '银河作为分包商授权，代理投标', '', '此项目为政府招标项目，与当地政府情况息息相关', '', '', '', '', '', '为突尼斯软件供应商，有30多年的历史，且为电力公司的现有供应商，有一定的客户关系；从目前沟通情况来看，比较专业。', '', '', '', '', '', '优点：\r\r\r\r\r\r\n此前银河的smart vending system已经在当地投入运营，有一定的技术基础\r\r\r\r\r\r\n标书要求投标人必须是STS协会成员，并且至少有两个以上STS项目的成功经验，从技术和资历方面来看，银河的满足度较高。\r\r\r\r\r\r\n\r\r\r\r\r\r\n劣势：\r\r\r\r\r\r\r\n项目要求参与筹备会议，当地部署环境实地考察（非必须），现场开标，目前的疫情情况，银河无法实地参与，因此只能选择与代理合作。\r\r\r从目前的技术规格初步判断，银河很难做到独自直投，能够承包的标段有限\r\r\r\n\r\r\r\n', '', '希望软件部技术人员给予技术评估，解析与相关支持', '从目前的分析情况来看，银河无法做到直投，承包所有标段。但是与代理合作，授权投标，减少了银河的投入与应承担的风险。加上银河和代理此前都有过供货经验，与技术规格相符度较高，项目成功几率较大', '魏紫薇2020-06-16 09:41:32', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('460', '{3D115228-40FA-4C07-B8CA-EFEB4752BABB}', '61', 'INHE-0843', '2020-06-16 10:41:54', '0000-00-00 00:00:00', '2020-06-17 11:26:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061601/MXP02', '项目代号为MXC。', 'No. CFE-0001-CAAAT-0032-2020', '2020-06-22', 'Adquisición de Medidores de Baja Tensión（低压电表采购）', '代理商投标，对银河付款方式为：生产前30% T/T预付款；发货前70%不可撤销的保兑的远期90天信用证。\r\n', '{3D11522840FA4C07B8CAEFEB4752BABB8442F4C2B3234363A3D51C033076BD50}_1. 标书_Pliego de Requisitos Medidos de Baja Tensión D 08062020.doc', '1. 技术评标：评定技术、法律、行政要求，符合要求者进入经济评标；\r\n2. 经济评标：对报价及融资资料进行评标，折扣比例最大且价格最低者中标。投标者必须在财务报价中提供包含折扣的价格，不包含折扣的投标将被拒绝。（电力公司在标书中给出了最高采购价，投标者需要在最高采购价基础上提供折扣价）\r\n3. 平局标准：如果在经济标评标时有平局，将采用如下标准：1）与投标者直接谈判还价；2）人工抽签。\r\n', '', '多家中标；每个LOT只授予一个厂家；投标者可以参加一个或多个LOT。\r\n', '', '1. 履约和质量保函。要求出具SHCP或备用信用证授权的担保机构的保函，其金额为合同总金额的10％。履约和质量保函的提交将在合同正式签订之日起的7个日历日内。履约和质量保函必须是可分割的，其有效性将从合同签署起至本次招标的最后一批货物交付后12个月。\r\n2. 生产保函。供应商应随货交付制造商出具的保函。如果供应商与货物的制造商不同，则供应商必须以CFE的名义交付制造商的保函，并附带权利转让。\r\n', '', '1. 凡与墨西哥签署自由贸易协定并遵守标书所述要求的本国和外国的个人和法人实体均可参加；\r\n2. 所有投标者必须在电子招标网站上正式注册#FE54`\r\n3. 需获得由LAPEM出具的供应商资格证书；如果没有此证书，则提交由符合联邦计量和标准化法律的认可质量体系的公司或认证机构或独立的国际质量体系认证机构（经原产国权威机构认可）出具的公司评估报告；如果没有前述所有资质证书，还可以提交由设备与材料检测实验室管理部门出具的本公司目前批准的同一工厂生产的、按适用规格在资质证书中注明的同一品种、同一生产工艺的供应商资质证书复印件；\r\n4. 需提供由LAPEM出具的对所投标产品有效的样机接收证明，否则，必须出示LAPEM的正式信函，说明在样机测试中，产品测试结果良好，符合CFE的规格和/或技术标准；如果没有上述文档，则投标者必须提供：1）由独立的国际认证机构签发，并经原产国主管当局认可的产品合格证书。 该证明书必须带有认可标志；或2）由认可的认证机构根据《联邦计量和标准化法》的规定颁发的样机测试产品的合格证书；或3）由原产国主管当局认可的实验室签发的产品合格证书；或4）由原产国主管当局认可的实验室', '', '投标资料主要由代理提供，银河提供必要的协助\r\n截标时间：2020年6月22日\r\n投标文件：\r\n1. 营业执照和法人资格认定声明(附件9.1)；对外国法人资格进行认证或合法化，并附西班牙文翻译；\r\n2. 投标的自然人或法人代表的有效官方身份证明(公民投票证书、护照、身份证明)的复印件；\r\n3. 道德和诚信声明(附件9.2)；\r\n4. 适用法律和主管法院的接受书（仅适用于外国投标者）（附件9.3）；\r\n5. 投标者的国籍声明（自由格式）；\r\n6. 投标者根据第IV.4条的声明(附件14)#FE54`\r\n7. 货物原产地证明 (视乎情况，附件19、20或21)#FE54`\r\n8. 投标人签署的书面文件，声明本招标所提供的有关货物标的的信息真实、完整，不影响第三方的知识产权权利#FE54`\r\n9. 符合标书附件1、附件2要求的技术标#FE54`\r\n10. 经济标（附件7）；\r\n11. 符合标书第IV.7条规定的融资资料（包含在经济标中)#FE54`\r\n12. 由LAPEM出具的供应商资格证书的正反两面复印件。\r\n', '', '代理投标', '', '电力公司直接决定中标\r\n', '', '对于在2020年11月30日之前的交付，CFE将在货物和发票交付和接收后的15天（日历日）内支付货款。对于在2020年12月18日之前的交付，即在收到付款文件后的10个日历日内进行支付。\r\n', '', '详见附件《2020年CFE财政计划》', '{3D11522840FA4C07B8CAEFEB4752BABB108D268797C74834B1DDE2FC1083AA37}_2020年CFE财政计划_PAFCFE020_翻译.docx', '代理PROTECSA是电力公司CFE多年供应商，主要供应电表、配电、系统等产品，同时CFE IOT通讯标准制定的顾问。\r\nPROTECSA有专业的技术团队，熟悉圆表标准，对ANSI标准、CFE标准有多年研究，已有完整的全套电表产品线。\r\n老板Ruben是70年代生人，敢闯敢拼，有干劲，思维活跃；十年前成立PROTECSA，在此之前曾担任ABB墨西哥办事处配电业务销售总监，主要负责开拓CFE业务，与CFE内部有超过二十年的客情关系；\r\nPROTECSA目前还属于发展中的中小企业，规模不算太大；在前几年墨西哥电表市场被寡头垄断的情况下，主要靠配电业务支撑；同时积极发展软件、太阳能、IOT通讯等领域。\r\n', '', '暂时没有建立CFE客情\r\n', '', '1. IUSA：墨西哥最大的电表制造商，占据墨西哥近90%的电表市场份额，处于绝对的垄断地位。是GE在墨西哥的代工厂。有全套完整的电力产品线，技术实力非常强。与墨西哥政府有十分紧密的关系，前总统Carlos Salinas的弟弟是CFE的董事长顾问。\r\r\n2. Conymed：品牌MIAL，大股东是IUSA老板的亲戚，外界普遍认为Conymed的实际幕后老板是IUSA。Conymed和IUSA在电表招标项目中经常伪装成竞争对手竞标，但实际上两家实行垄断合作，几乎占据了墨西哥电表市场的全部份额。IUSA主投单相电表，Conymed主投两相电表。两家电表的模具、结构基本一致。\r\r\n3. Electrometer：El SEWEDY在墨西哥的分公司，主供单相/两相简单表。\r\r\n4. 威盛：此前与西门子合作，给西门子贴牌，曾为墨西哥供应了约2万台智能圆表。但电表安装后却出现了严重的通讯故障、模块失灵、数据丢失，无法兼容 CFE 系统，几乎所有电表都无法通讯。曾一度被CFE拉入黑名单。同时与ITRON合作群表。威盛计划这两年在墨西哥设立办事处及工厂。\r\r\n5. 华立：2019年华立与墨西哥当地一', '', '1. 优势：代理具有丰富的行业经验，技术和商务能力较强，在CFE有可靠的客情关系，合作意愿强烈；此前曾合作过MXP01项目，银河产品已经符合市场技术需求，获得CFE认可，质量和价格均有竞争力。\r\r\n2. 劣势：银河暂时没有直接与电力公司建立客情，业务关系覆盖和渗透能力弱；圆表经验不足。\r\r\n3. 机会：电力公司每年电表招标数量超百万台，订单量可观；目前进入该市场的中国厂家较少；\r\r\n4. 挑战：竞争对手强大；电表标准自成一派，且需求多变，对我司技术和业务人员的要求很高，要十分熟悉市场及产品。\r\r\n5.策略：由于银河暂无投标资格（必须是与墨西哥签订了自贸协定的国家的厂家才能参加），MXC将沿用MXP01的合作方式。银河的固件程序目前已经完全满足CFE技术需求，从MXP01的成功合作来看，银河可以在最快时间内为代理提供大批量的供货；如果代理想发展其他供应商，从固件开发的角度看，银河尚且需要半年多时间完成研发，其他厂家大概率需用上一年半载才能完成。考虑成本和时间等因素，代理与银河继续合作的可能性很大。同时，业务将继续与客户保持紧密沟通、稳固合作关系，维护良好客情。\r\r\n', '', '银河协助提供技术支持（主要是固件方面）；提供价格支持；保证交期。\r\n', '由于银河暂时没有投标资格（必须是与墨西哥签订了自贸协定的国家的厂家才能参加），MXC仍采用MXP01的OEM合作模式，由代理投标，银河提供SKD物料及技术支持。此前银河与代理的合作的MXP01项目产品获得了CFE的认可与肯定，在本次招标中代理将有更显著的优势赢标。本次招标将进一步增加银河对墨西哥市场情况、产品技术和规格的了解，增加银河的供货经验，希望公司能够给予MXC项目必要支持。\r\r\n', '刘畑杏2020-06-16 13:54:29', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('461', '{FBD3BB7C-3C34-44D5-B4FF-47F46613B806}', '153', 'INHE-0535', '2020-06-16 13:54:18', '0000-00-00 00:00:00', '2020-06-17 11:22:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061602/MEP', '代号为MPD', 'MePDCL/CE(RE)/T-191/2019-20/Pkg-I, Dated 4th February 2020', '2020.06.19', 'Supply of Smart Meters and Associated Services智能电表和相关服务的供应', '价格条款：对于招标方境外供应的产品，投标人按EXW报价；\r\r\r\r\r\r\r\r\n对于招标方境内供应的产品，投标人按CIP报价；\r\r\r\r\r\r\r\n报价货币：印度卢比INR，或USD, 或EUR,或JPY\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n税费：如果在合同期内，由于税率变化或新税种引入或现有税种的取下等原因导致税费上升或下降，招标方将报销实际所缴税费全额；但招标方不负责报销上述超过合同执行期限所发生的税费。\r\r\r\r\r\r\n\r\r\r\r\r\n付款主体：MePDCL\r\r\r\r\r\n\r\r\r\r\r\n付款条款：\r\r\r\r\r\n供货部分：\r\r\r\r\r\n10%合同预付款在签署合同及提交等额预付款保函（有效期12个月）后的45天内支付；\r\r\r\r\r\n80%在每批货交付，安装，运营后45天内支付；每批次货物最少20000台；\r\r\r\r\r\n10%在供货全部完成且验收后45天内支付；\r\r\r\r\r\n服务部分：\r\r\r\r\r\n10%预付款在签署合同及提交等额预付款保函（有效期12个月）后45天内支付；\r\r\r\r\r\r\n80%在服务安装实施后45天内支付；按每批次至少20000台电表的相关服务；	\r\r\r\r\r\n10%在服务完成且验收后的45天内支付；	\r\r\r\r\r\n', '{FBD3BB7C3C3444D5B4FF47F46613B8068442F4C2B3234363A3D51C033076BD50}_payment terms－MePDCL-Smart_Meter_Vol_I_05.02.2020_pdf.pdf', '评标流程：先评技术标，再评通过技术标的投标人的商务标。最低价者中标。\r\n\r\n评标币种全部转换为印度卢比INR进行评标，货币汇率按截标日State Bank of India的汇率进行换算。', '', '一个lot，一家中标，最低价者中标。', '', '投标保函：USD250,000#FE54`\r\n履约保函：10%合同额\r\n保函由主投负责开立', '', '1.过去5年内成功执行过2个或以上累计USD18mn的计量项目；\r\r\r\r\r\r\n2.至少一个印度本地AMI项目实施经验（主投已满足）；\r\r\r\r\r\r\n3.过去3年内供应至少50万台电表；\r\r\r\r\n4.智能电表最小日产能3000台；\r\r\r\r\n5.有符合IS标准的生产测试设备；\r\r\r\n6.最近一年总资产-总负债为正值；\r\r\n7.过去3年年平均营业额至少为USD32mn；\r\n8.流动资产最少为USD4mn；', '{FBD3BB7C3C3444D5B4FF47F46613B80603404677E4D44E9EB56B3D512B2AF9CC}_PQR－MePDCL-Smart_Meter_Vol_I_05.02.2020_pdf-2.pdf', '1.过去3年财务资质（特许会计师签字盖章）；\r\n2.供货记录，用户证明，合同；\r\n3.应答表，产品画册，操作手册，图纸等技术资料；\r\n4.银河授权函（需公证）', '{FBD3BB7C3C3444D5B4FF47F46613B806C675BD0CC93442C09B990884D4324504}_Documents Checklist for MePDCL Tender.xlsx', '联合投标', '联合投标原因：\r\n1）需要有至少一个印度本地AMI项目实施经验（主投满足）；\r\n2）需要提交产品BIS认证，IS16444测试报告（JPM满足）；\r\n3）需要有本地合作伙伴负责与电力公司和其他产品和配件供应商/分包商联络和沟通；需要本地合作伙伴负责本地安装，项目管理及本地售后服务中心的建立和维护；\r\n4）需要有力的客户关系以保证货款回收；\r\n\r\n联合体成员及各方权责：\r\n1）主投：Satnam Global Infra Projects Ltd. (SGIL)，成立于1987年，是一家综合性的工程类承包商和服务贸易公司，涉及电子电器类，机械类，民事类，基础设施类等多行业项目参与和实施。\r\n负责代表联合体提交投标文件，与电力公司联络；\r\n产品的现场安装，测试，调试，兼容，售前售后服务和现场维护；\r\n项目的现场实施和管理；\r\n软件的供应，安装和兼容；\r\n与MePDCL的货款结算；\r\n2）联合体成员JPM:\r\n协助投标文件准备和提交；\r\n智能电表和表箱产品的供应和安装；\r\n产品测试；\r\n3）联合体成员INHEMETER:\r\n协助投标文件的准备和提交；\r\n表计产品的设计，开发和技术支持；\r\n质', 'MePDCL自主决策', '', 'ADB融资，有MePDCL电力公司直接支付给主投', '', 'ADB融资，备案项目编号Pkg-I/SM/ADB/2020', '', '如上述6.项目潜力所述。', '', '第一次接触Meghalaya邦的招标项目，尚未直接见过MePDCL电力公司相关人员。\r\n主投负责运作项目，主投由JPM接洽和介绍。\r\n后续投标，评标及项目执行中，需与主投进行进一步关系维护。', '', '招标的PLC通讯产品在印度市场上尚未有任何一家供应商有满足要求且经过认证的产品；\r\nGPRS通讯产品其他厂家多以3G通讯产品为主。', '', '1.受本地经验和BIS认证要求的限制，银河在此项目中主要作为JPM的技术伙伴直接供应产品给JPM，由JPM供应给主投/业主。\r\r\r\r\n2.由于PLC表计产品在印度市场上并不常见，主投期望在后续供货中将表计全部运作为GPRS通讯，以便更快交付和供货；\r\r\r\n3.目前已知该市场其他常见竞争对手都在争取延标和资质修改，主投希望按最新版资质要求按时投标及围标，争取SGIL+JPM+INHE一家中标。', '', '成功关键：主投的项目把控力度，是否能做到一家投标，一家中标；或者多家围标或投标，评标过程中踢掉竞争对手，确保SGIL+JPM+INHE联合体中标。\r\r\n\r\r\n需要支持：投标文件准备。', '该标的澄清（2份），修正（4份）和技术规格修改（3次）较多，商务组需结合所有澄清、修正和技术规格修改来准备投标文件。\r\n投标文件列表已初步整理，需商务组对照，核查并准备。', '左亚楠2020-06-16 17:46:55', '04', '★★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('462', '{19D97624-8B0D-44C5-B4C2-FCF950AAC262}', '61', 'INHE-0432', '2020-06-17 02:54:22', '0000-00-00 00:00:00', '2020-06-18 15:03:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061701/KFG', '', 'KP1/9A.3/OT/36/19-20', '2020年7月9号', '绝缘子供货', '1.价格条款：DDP含VAT\r\r\n2.付款主体：KPLC\r\r\n3.交期：拿到合同、PO开始交付，12个月内交付完毕。\r\r\n4.质保：5年。						\r\r\n', '', '1.商务评审\r\n2.技术评审：资料、样机测试。\r\n3.财务评审。						\r\n', '', '综合评标价格最低者中标（只有1个LOT）						\r\r\r\n', '', '投标保函：319,600 KSH（约3196美元），但是不同产品有对应的保函金额。\r\n履约保函：合同金额10%。', '', '1.仅限于本地投标人（本地厂商和非厂商都可以）\r\n2.要求投标人提供4份用户证明。', '', '需要国内采购部和客服部提供协助：寻找合适的厂商，配合做技术解析、投标、报价等。\r\n', '', 'IAC直接投标。', '无', '本项目主要决策过程取决于评标团队。', '', '满意交付及提交资料后的30天起，开始付款。						\r\n', '', '', '', '主要竞争对手为本地的印度人公司。', '', '业务与相关负责人通过KCB项目有直接的客户关系基础。', '', '主要为印度公司如Lomas&Lomas,THAMES ELECTRICALS LTD等。这些印度公司常年在KPLC经营，同时也做经销。所以客户关系基础好，同时供应商渠道宽。相关历史信息已发OA。', '', '1.IAC直接投标，业务直接负责竞投、建立客户关系等。\r\n2.劣势：此前没有合作的中国厂商，所以需要国内支持，与厂商沟通合作事宜，配合投标等。业务现场调查的相关中国厂商及价格，已发至相关的OA。\r\n3.优势：相关负责人已通过KCB项目与我方有合作基础。', '', '需要找到合适的厂商配合投标，且时间紧，需要提高效率来应标。', '作为IAC拓展电表以外的产品机会，希望公司支持。', '谭东羊2020-06-17 03:20:00', '', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('463', '{0D6A30E8-7755-4A54-8EC6-CA90599CD208}', '66', 'INHE-0774', '2020-06-17 08:59:17', '0000-00-00 00:00:00', '2020-06-18 14:25:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061704/BLS', '', 'GAZ20/00032', '2020年6月29日 北京时间下午5点', 'Purchase of Smart meters for (Gaza Electricity Distribution corporation) GEDCo为加沙电力公司GEDCO采购智能电表', '价格条款：FOB中国港口或CFR 约旦港\r\r\r\r\n付款主体：International Committee of the Red Cross\r\r\r\r\n交期：部分不晚于2020年10月（仅供参考，可能会更改）\r\r\r\r\n付款条件：Payment will be done by bank transfer within 30 days against original shipping documents（收到海运单据30天内银行转账）\r\r\r\n违约条款：卖方未能在规定日期之前交付全部数量，将对未未交付货物施加货值每天1％的罚款。\r\r\r\n如果延误超过10天，红十字国际委员会有权全部或部分取消合同。\r\r\r\n\r\r\r\n', '{0D6A30E877554A548EC6CA90599CD2088442F4C2B3234363A3D51C033076BD50}_(RFT GAZ2000032) Smart meters for Gaza.pdf', '', '', '一个LOT，一家中标', '', '投标保函：无\r\n履约保函：暂无规定\r\n\r\n', '', '无明确要求', '', '技术应答表等技术规格规定的技术资料', '', '银河投标', '', '', '', '\r\r\n付款条件：Payment will be done by bank transfer within 30 days against original shipping documents（收到海运单据30天内银行转账）\r\r\r\r\n\r\r\r\n						\r\r\r\n', '', '', '', 'BAL项目代理，主要提供当地的服务支持和本地联络', '', '', '', '', '', '因为BAL项目中标,招标方指定银河参与投标。，BAL项目的6个电力公司，其中一个是加沙GEDCO.', '', '项目成功关键在于技术方案和专业的技术资料', '1.该项目为约旦红十字委员会援助巴勒斯坦为巴勒斯坦加沙电力公司GEDCO采购电表项目，加沙GEDCO也是BAL项目涉及的电力公司之一；\r\r\r\r\n2. 参与投标不要求样机和保函；\r\r\r\r\n3. 招标方指定银河参与投标；\r\r\r\n建议公司支持参与投标。\r\r\n\r\n\r\n', '何森华2020-06-17 09:48:10', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('464', '{39C54896-8714-4F27-96FE-F6B96CD2AA33}', '61', 'INHE-0916', '2020-06-17 11:20:12', '0000-00-00 00:00:00', '2020-06-20 15:24:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061705/ZBD', '', 'ZINWA/ GOO/ 2020/14', '2020年7月28日', 'Standard Bidding Document for the Procurement of FINANCING, SUPPLY, INSTALLATION, TESTING & COMMISSIONING OF  PREPAID WATER MANAGEMENT SYSTEM FOR ZINWAZINWA预付费水管理系统的融资，供应，安装，测试和调试的标准招标文件', '价格条款：DDP报价，美元(USD)。\r\r\n付款主体：招标方ZINWA津巴布韦国家水务局\r\r\n付款条件：项目为卖方融资模式，具体融资模式需要投标方在投标文件中提出和经过招标方评审；\r\r\n交期：投标方给出交期申明，招标方根据交期长短进行评审；\r\r\n质保和违约：投标方应在本地提供售后和维护服务，且应当库存备件。该服务期限为安装水表后的一年或以上。暂无违约的要求。\r\r\n\r\r\n银河对FHL报价：待协商，基本原则按照T/T预付或者保兑信用证执行。\r\r\n						\r\r\r\n', '', '1.资质预审评估（确认所有投标资料齐全，审查投标者资质，且资格预审评分达到70%）\r\r\n2.技术评估（满足technical specification的所有要求）\r\r\n3.财务评估（价低者得；存在本地优惠政策）\r\r\n4.融资能力评估\r\r\n						\r\r\r\n', '{39C5489687144F2796FEF6B96CD2AA33074E749A304748709C51373D9D483750}_Std Bidding Doc (Goods) for Water meters final final  (3).pdf', '按照评标规则评估，ZINWA可以将7个lot全部授予一个投标者,或者将每个lot根据报价最低的原则分别授予不同的投标者。\r\r\n一家制造商可授权投标者数量：作为分包商，无限制\r\r\n', '', '投标保函：由投标人开具20,000 USD的投标保函，有效期不早于2020年12月4日\n履约保函：无要求\n质保保函：无要求						\r\n', '', '1.资质证书：PRAZ注册，供应商注册缴费证明，ISO 9001；\n2.供货记录：需提供过往类似项目的描述、规模、金额、期限。\n3.财务数据：融资资金证明文件（或融资方同意进行融资的证明）\n\n\"					\r\n', '', '\"1.需要客服同事协助提供符合标书要求的水表产品画册、操作手册、技术应答表等；\n2.商务部分的资料由业务组赖星威主导制作、李忠鹏审核完成，无需商务协助。					\r\n', '', 'FHL直接投标，银河作为厂商支持', 'N/A								\r\n', 'ZINWA为国有企业，政府100%控股且由津巴布韦政府直接领导。政治关系在授标中占据主导作用						\r\n', '', '此项目属于EPC+卖方融资模式，招标方和投标方的付款条件和模式需投标时申明、以及中标后合同谈判时具体协商实施。						', '', '待进一步分析ZINWA年度财务报告						\r\n', '', 'FHL和ZINWA内部关系：待进一步反馈；\r\n\r\nFHL政府关系：FHL老板David与现任总统儿子关系密切，靠山较强；和PRAZ津巴布韦采购管理总局CEO私交较深；						\r\r\n', '', '新项目和新业主，待开拓', '', '待进一步调查', '', '劣势：\r\n1.针对该项目，银河暂无完整的预付费水表硬件方案，需要投入时间和资金研发。\r\n2.银河不具备相关项目的历史供货记录\r\n优势：\r\n1.银河有完善的预付费系统方案，可以短时间内完成水表系统的搭建；\r\n2.因银河电表在当地市场份额高，已形成一定的品牌效应\r\n3.FHL作为本地实力强劲的公司，满足投标资质，能够享受本地优惠政策，且能够发挥其强大的政治关系运作该项目\r\n策略：\r\n1.通过澄清，将历史供货记录的要求运作为非必须的选项\r\n2.尽早完成预付费水表方案&解决技术不符点', '', '1.银河：需要尽早完成预付费水表方案&解决技术不符点\r\r\n2.代理：需要通过其强大的政治关系运作ZINWA的内部关系					', '津巴布韦及其邻国（南非、博茨瓦纳，纳米比亚等）有着潜在的预付费水表需求，若该项目银河中标，将有利于银河在东南非地区开拓水表业务。								\r\n', '赖星威2020-06-17 11:46:05', '02', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('465', '{895162B5-D4B7-414E-B530-B62AE8BABD5A}', '61', 'INHE-0819', '2020-06-18 05:24:39', '0000-00-00 00:00:00', '2020-06-22 09:27:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061803/NFC', '', 'SM4109268', '2020年7月22日上午9点（摩洛哥时间）', 'fourniture d,un systeme numerique de comptage d,electricite pour les clients moyenne tension', '1,DDP条款，电力公司地区部仓库交货。2，电力公司自有资金。3，一次交货，临时验收之后TT或信用证付93%，最终验收TT支付尾款7%。4,交期为三个月。5，质保为两年。						\r\r\r\r\r\n', '', '先评行政再评技术，最后商务。评标委员会：1.先评行政文件如供货记录，授信额度，财报等；2.再评技术文件如技术应答表，操作手册，图纸等，挂网测样机；3. 评价格\r\r\r\r\r\n', '', '一个LOT一家中标。', '', '投标保函为100000摩洛哥迪拉姆，月10344USD.履约保函为合同金额的3%。', '', '1，无公司年限要求。2，要求至少五年内一次类似供货经验。3，要求电表本地认证（NF7中压表已获得）。						\r\r\n', '', '暂无', '', '银河投标', '', '配电部主导该项目，CEO拍板						\r\n', '', '临时验收之后TT或信用证付93%，最终验收TT支付尾款7%。						\r\r\r\r\n						\r\r\r\n', '', '', '', '1.与电力公司CEO有一定关系，目前和配电部负责人接洽，让其指导应标。\r\r\r\r\n2.与中国中车CRRC参与过一个大型电车招标，对招投标项目操作熟悉，知晓项目运作，据中车员工透露老板有些手段，在知道开标结果将对其不利的情况下，其在开标前半小时强行取消了开标会。\r\r\r\r\n3.老板50来岁，但有激情，性格外向。但是强势。\r\r\r\r\n4.按其所说，在银行，政府部门特别是工业部有关系，其近期在于比亚迪合作在首都拉巴特郊区建厂，据其介绍，代理占股45%，政府占股25%，比亚迪30%。', '', '代理和业务正在主导此项目的配电部交流，邀请其指导制作标书资料，建立长期合作。', '', '目前银河、科陆、海兴、威胜、三星、正泰、华立等中国厂商在摩洛哥市场比较活跃，此外ITRON和兰吉尔也可能会搅局。', '', '1. 弄清标书具体要求，准备对应投标资料\r\r\r\r\n2. 客户关系层面获得评标团队支持，让评标团队成员指导投标资料的准备，获得CEO的支持。\r\r\r\r\n3. 优势：NF2，NF7中标且供货，NF2预付费表用户反映良好，IT部门对银河软件实力满意，代理老板有一定人脉手段，懂投标项目运作。\r\r\r\r\n4. 劣势：NF7产品交付问题遭诟病，且这次供货大同小异，对手可能拿此做文章。', '', '1.投标资料跟样机准备无误\r\r\r\r\n2.价格\r', '此项目是NF7的延续，NF7我们中标，此项目和NF7大同小异，且电力公司新立门槛（本地认证）已不是问题，银河有优势。结合此项目拉拢配电部负责人及其团队，也有利于后续其他项目的发展。摩洛哥市场我们要坚持，希望公司支持！', '付为2020-06-18 06:40:47', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('466', '{0C49F952-2A18-4D43-8E31-52F599153755}', '61', 'INHE-0725', '2020-06-18 10:09:58', '0000-00-00 00:00:00', '2020-06-20 15:19:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061806/AGP', '', '待定', '业务与GIZ内线确认我方运作的技术规格后发标，投标截止时间一般为发标后40-50天', 'Supply of Electricity Meters, Accessories and relative Software电表，配件及相应系统供应', '价格条款：FOB Shenzhen, China\r\r\r\r\r\r\n付款主体：GIZ（招标方），欧盟资金；\r\r\r\r\r\r\n交期要求：预付款支付后35天\r\r\r内货备待运\r\r\r\n质保：1年', '', '价格较低者，技术方案完全满足中标\r\r\n评标流程：初审，商务评标，技术评标（GIZ内线Fatoki负责撰写标书，除了在标书撰写时协助我们运作技术规格，也可在技术评标阶段建议中标人）\r\r\n实质不符项：无', '', '一家中标，AGP银河直投，通过内线运作我方技术规格。', '', '要求开立投标保函，金额2万美金左右，标书草稿尚未完善，其余信息会继续核实。', '', '无公司年限要求，标书草稿尚未完善，其余信息会继续核实', '', '需客服部协助提供产品画册手册图纸，需商务部协助提供财务数据，供货记录。业务有需要会申请', '', '银河投标', '非联合体投标', 'GIZ既是融资机构又是招标方，属第三方监管机构，截标后投标文件需扫描电子档发给德国GIZ总部，由总部人员评标（6人左右），都是德国人，政府或政治对决策影响不大，评标过程较公平且关系难以渗透。在评标流程最后一阶段标书撰写人Fatiko（内线）有推荐中标权。', '', '标书草稿未完成，付款方式GIZ在内部核实', '', 'GIZ 1973年成立，作为老牌德国融资机构，德国政府所有，融资及支付实力较强。附件财报供参考', '{0C49F9522A184D438E3152F599153755108D268797C74834B1DDE2FC1083AA37}_GIZ 2018年财报.pdf', '本次合作伙伴MNP01客户主做微网项目，实力较强，此前与我方成单MNP01项目（1000台电表），老板也是本地AMDA（微网联盟）的前任CEO，客情广泛。本次MNP01客户介绍了GIZ内线Fatoki（负责标书撰写）\r\r\r\nGIZ针对微网项目招标一般先招标某些区域的发输配电业务，而后再为这些区域的中标方统一采购电表。去年年末招标了7个区域的微网项目，共有七家公司中标（名单如附），AGP就是为这七家公司采购电表，MNP01(ACOB Lighting）也是中标方之一。', '{0C49F9522A184D438E3152F599153755D18C251E4D454BA8A05CF92EE9AFCB77}_七家公司名单.jpg', '业务目前已经和GIZ内线Fatoki直接沟通AGP招标技术规格及商务条款，同时此前开发了GIZ项目部内线Felix可核实项目进度。AGP项目最终用表的七家公司中，有三家已与银河有一次或多次订单合作（GA, AN, MNP01)，另外一家Darway Coast正在联络洽谈订单，可借由这四家获取竞争对手信息，公开或私下支持银河，影响决策。', '', '【Mojec】：与三星合作，占据本地市场70%以上的份额，本地有厂，主做大型项目，对于微网项目未放过多精力，产品报价待核实；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n【Spark Meter】：美方厂商，主做微网项目，与GIZ联络密切，为AGP主要竞争对手，产品报价待核实；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n【Steamco】：英国厂商，主做微网，影响力次于Spark Meter，Steamco参考报价如附件；\r\r\r\r\r\r\r\r\r\r\r\r\r\n【科林】：科林从2018年以来在本地微网市场较活跃，低价竞争策略，主推DIN单相分体式代码智能电表（PLC通讯），1000台售价39美金（FOB），售电软件0.5美金/用户/年\r\r\r\r\r\r\r\r。\r\r\r\n同时从MNP01及Darway Coast处了解到科陆最近也比较活跃，需谨慎。', '{0C49F9522A184D438E3152F599153755C8C3CDC70C5243B796247CC1ED7EC56E}_SteamaCo Product方案及报价.pdf', '【竞争策略】：\r\r\r\r\r\r\r\r\r\r\r\n借由GIZ内线Fatoki运作技术规格，运作UNW项目DIN四代表（对方要求DIN表最大电流一定≥100A，此前计划运作带LCD的DIN表(3.5代或者5代），但经与客服确认DIN3.5或5代无法做到100A最大电流），规格如附（此规格已发给GIZ内线）。同时GA, AN, MNP01和Darway Coast是AGP项目表计最终使用方，可借用与这些公司的关系获取项目及竞争对手信息，并在一定程度上引导GIZ决策。\r\r\r\r\r\r\r\r\r\r\r\n【银河的优势】：\r\r\r\r\r\r\r\r\r\r\r\n1.GIZ内线Fatiko，可协助运作我方技术规格，提供竞争对手信息并在评标最终阶段建议我方中标；\r\r\r\r\r\r\n2.AGP项目表计最终使用方GA, AN, MNP01与银河已经合作，已经使用我方电表及软件，可借由这三家公司获取项目信息，影响决策；\r\r\r\r\r\n3.业务去年拜访GIZ，做了公司宣讲，同时在今年也安排了远程的技术培训，对方对我方产品方案认可。\r\r\r\r\r\n【银河的挑战（劣势）】：\r\r\r\r\r\n1.本地微网项目竞争对手众多，有本地第一表厂也有欧美厂商，中国厂商也在活跃，我方在价格方面需做一定让步；\r\r\r\r\r\n2.业务不在现场，需要更积极的运作和沟通。', '{0C49F9522A184D438E3152F599153755B79221563C224206B274FD7CD6B16366}_与GIZ沟通的技术规格（UNW项目）.xlsx', '【成功的关键】：\r\r\r\r\r\r\r\r\r\r\r\n1. 技术规格运作一定要具体排他性，UNW表表体小巧，超声焊，最大电流100A，断路器开窗（弹簧窗），表箱带三角锁，可排除大部分竞争对手，业务也在于客服部沟通运作其他技术点；\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n2. 高质量的技术及商务文件，招标方是德国人，审查时会极其细致，业务会多次核查资料避免出错；\r\r\r\r\r\r\r\r\r\r\r\r\r\n3. 持续性的项目运作，避免技术规格运作后万事大吉，需监控竞争对手动态\r，联络本地客情核实项目进度，推动快速授标。\r\r\r\r\r\r\r\r\r\r\n【需要的支持】：后续涉及保函开立需公司协助，因是小单，业务会尽量自行准备投标资料，少占用公司资源。', '尼日利亚市场电力公司经营不善，无钱购表，MAP项目因为表计关税上涨35%的问题执行困难。GIZ作为尼国政府官方认证的微网项目招标方（GIZ项目都是免税项目），有计划也有能力管理尼国微网项目，重要程度在11家电力公司之上。如能在初期与其展开合作，对于后续NG市场业务拓展有重要意义。在GIZ内线及本地老客户（GA, AN, MNP01)的协助下，银河有较大机会中标此项目。项目规模较小，所需支持较少，自评二星。', '赵政洁2020-06-18 15:34:00', '01', '★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('467', '{F2E94786-CCDC-469A-8814-C3B749A0E389}', '61', 'INHE-0434', '2020-06-19 08:26:54', '0000-00-00 00:00:00', '2020-06-23 17:58:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061901/NED', '', 'NEDCo/GD/025/2020', '2020年6月30日', '智能分体式预付费电表供货与安装Supply and Installation of Smart Split-type Prepayment Meters', '标书对中标方付款条件如下：\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\n1、合同签订后30天\r\r\r\r\r\r\r\r内支付总货值20%作为预付款，中标方需\r\r\r\r\r\r\r\r提交预付款保函\r\r\r\r\r\r\r\r\r\r\r\r\n2、余下80%分16期分期支付，每期支付总货值5%，第一次分期为发货后6个月内，第二次分期为第一次分期后3个月，第三次分期为第二次分期后3个月，以此类推至16期\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n与代理付款条件：\r\r\r\r\r\r\r\r\r\r\n中标后可谈预付款，尾款通过L/C，LC细节以及预付款比例有待进一步商榷\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n整个项目需在合同生效日后10个月内需完工，例如4个月交付产品，6个月完成安装\r\r\r\r\r\r\r\n质保为业主发布试运行成功证明文件后12个月或发布验收证明后14个月，针对电表电池与继电器，需额外提供5年质保\r\r\r\r\r\r\n\r\r\r\r\r\r\n若晚于合同里规定的时间交付产品，每周罚金合同金额0.5%直至达到合同金额10%，达到10%后业务将考虑终止合同\r\r\r\r\r\n\r\r\r\r\r\n价格条款为DDP(CIP项目地点)，与代理间价格条款为CIF亚历山大港。我们供货SK', '{F2E94786CCDC469A8814C3B749A0E3898442F4C2B3234363A3D51C033076BD50}_SUPPLY AND INSTALLATION OF PRE-PAYMENT METERS - FINAL COPY(1).docx', '先评技术资料，后评商务资料及价格。未采用打分机制评标。', '{F2E94786CCDC469A8814C3B749A0E389074E749A304748709C51373D9D483750}_Schedules of Requirements for NEDCo-187,000 PPM Project_ 08.05.2020.pdf', '最低价者中标，同一投标人最多中标两个LOT。\r\n标书中未提一家电表制造商只能授权一家本地表厂投标。', '{F2E94786CCDC469A8814C3B749A0E3892B47EB25ABE84FF19C47768372BB342D}_specs for veding terminal, laptops and report printer.pdf', '代理开立投标保函，履约保函\r\n1、LOT1投标保函金额44.6万美金\r\n2、LOT2投标保函金额15.8万美金\r\n3、LOT3投标保函金额20.6万美金\r\n4、LOT4投标保函金额14.9万美金\r\n投标保函有效期为投标截止日后178个工作日\r\n履约保函需在收到中标通知书14内提供，履约保函金额为合同金额10%', '{F2E94786CCDC469A8814C3B749A0E3891DD410FC292E4E1893AFBEF9F88431CD}_Installation Arrangements rev.docx', 'STS证书\r\r\r\n最近2年财报\r\r\r\r\n过去5年供货记录，至少4家用户证明。同型号产品两年内的供货记录以及用户信息电表测试设施，测试设备校验记录，过去供货过加纳的证明，过去加纳项目融资情况，GSA加纳标准局的证书，质量实验室设备清单，产能说明\r\r\n过去两年供货20万台同类产品的证明，DLMS/COSEM证书，ISO9001,ISO17025证书，G3-PLC联盟证书', '', '所有表型型式试验报告跟证书\r\r\r\n闭锁继电器型式试验报告跟证书\r\r\r\r\n晶体钟型式试验报告跟证书\r\r\r\n电池型式试验报告跟证书\r\r\n集中器型式试验报告跟证书\r\r\n通信模块型式试验报告跟证书', '', '代理商投标，银河授权投标，供货SKD，产品打联合品牌', 'N/A', '待定，此前未对北方配电公司NEDCO有过多了解，但海兴一直在北方配电供货电表，也供了售电系统', '', '标书对中标方付款条件如下：\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n1、合同签订后30天\r\r\r\r\r\r\r\r内支付总货值20%作为预付款，中标方需\r\r\r\r\r\r\r\r提交预付款保函\r\r\r\r\r\r\r\r\r\r\r\n2、余下80%分16期分期支付，每期支付总货值5%，第一次分期为发货后6个月内，第二次分期为第一次分期后3个月，第三次分期为第二次分期后3个月，以此类推至16期\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\n与代理付款条件：\r\r\r\r\r\r\r\r\r\n中标后可谈预付款，尾款通过L/C，LC细节以及预付款比例有待进一步商榷\r\r\r					\r\r\r\n', '', '代理商为埃及知名本地表厂，在加纳有分公司，资金上没太大问题', '', '代理商在加纳有电表分公司，常年供货ECG以及NEDCo，综合实力靠前。此项目为与代理商合作的第一个项目，客户关系方面待进一步考证。', '', 'ROCK项目组可能与业主有一定联系，代理商与业主有一定联系', '', '主要竞争对手为海兴与科陆，科陆去年与ECG做过类似项目。因本项目为限制性招标（邀标），邀请加纳本地表厂参与投标，以下公司受到邀请：\r\r\n1、MBH Power and Gas Limited#FE54`\r\r\n2、Alpha TND Limited (formerly Alpha Power Ventures Limited)#FE54`\r\r\n3、Ghana Electrometer#FE54`\r\r\n4、SNEDA Smart Meters Ltd#FE54`\r\r\n5、Nuri Telecom Company Limited#FE54`\r\r\n6、Intelligent Metering and Energy Solutions Ltd#FE54`\r\n7、Meinergy Technology Limited.\r\n', '', '协助代理商投标，同时挖掘埃及项目机会。项目已延期过一次从6月10日延期至6月30日，考虑样机制作以及文件准备，还需至少延期2周时间。去年同海兴以及科陆竞争发现其报价都低价，本项目建议采用低价策略支持代理商，同时督促代理商尽早处理本地安装报价事宜。\r\n\r\n银河收到消息较晚且前期花了时间核查项目真实性，目前剩余时间紧张，代理商在本地实力与MBH相当，本项目4个LOT至少可以拿一个。银河层面需配合尽快完成样机制作，联合代理商延标，尽快商讨报价。', '', '最低价中标，报价方面需与代理商尽快商讨。没投标样机可能导致失去投标资格，需公司加急制作样机。资料的制作希望安排商务组支持，配合业务投标。', '代理商在埃及原与科陆有过合作，但科陆在埃及设厂后，双方未继续合作。\r\r\r\r\r\r\n本项目在加纳，但代理商对银河后续进入埃及市场也会有较大帮助。\r\r\r\r\r\n代理商在加纳有电表分公司，且一直给ECG以及NEDCO供货，实力较上游。\r\r\r\n本次为刚开始与代理商接触沟通合作，本项目希望公司支持', '钟云林2020-06-19 11:48:31', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('468', '{437F1BD5-3516-468C-BCDA-9F356CA72C71}', '153', 'INHE-0535', '2020-06-19 10:35:35', '0000-00-00 00:00:00', '2020-06-23 11:49:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061902/ADA', 'ADA', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.该项目非直接应标型，而是希望通过提供样机和电表测试，达到电力公司对产品设计和功能的认可目的，推动后续直接采购；并在测试中弄清电力公司对RF方案的真实需求；\r\r\r\r\r\r\n\r\r\r\r\n2.早期我司对该电力公司RF产品招标的单相表技术解析偏差主要如下：1）LCD数字尺寸：要求10mm × 6mm，我们的是7.98mm × 2.81mm，该不符点涉及硬件改动；\r\r\r\r\n2）负荷曲线：要求15/30分间隔，记录60天，6条数据；需添加大容量flash、E方；\r\r\r\r\n3）模块插针定义，和我们现有模块插针定义不同；\r\r\r\r\n4）LCD轮显不支持编程，是固定死的，并且和标书要求的轮显项不同；\r\r\r\r\n\r\r\n3.样机数量需求不大，建议可以提供样机，支持客户项目运作。', '左亚楠2020-06-19 14:48:22', '03', '★★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('469', '{76DAB5E4-374F-4600-9F6E-12EFDE67CA11}', '153', 'INHE-0922', '2020-06-23 17:41:15', '0000-00-00 00:00:00', '2020-06-30 09:24:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2020062301/XLY', '下一步请选择王维总监', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '石洋2020-06-28 14:18:56', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('470', '{A175AB2B-2ABF-450D-B166-75FCAF1EA871}', '60', 'INHE-0868', '2020-06-29 09:04:14', '0000-00-00 00:00:00', '2020-07-21 14:56:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2020062901/BTM', '项目代号为BTM', '暂未正式发标', '', '暂未正式发标', '', '', '', '', '', '', '', '', '', '', '', '', '代理投标，银河提供产品授权', '', '电力公司自主评标', '', '', '', '', '', 'Interlink是当地老牌上市公司。电力公司PEA和MEA在全国的光纤均由Interlink提供，国家铁路及MEA，PEA电线杆的电信网络也都是由Interlink安装运营。', '', '', '', '主要竞争对手都是国内所支持的本地厂家，如华立（当地自有工厂），开发，科陆，台湾大同等。同时日本三菱和本地表厂smart TTC 分别为当地领头的机械表和智能表供应商', '', '结合代理的本地关系，同时此项目中将有部门要求本地安装及维护，代理作为当地电信电缆领域的领头企业，在这方面有很大优势。', '', '1. 样机将由电力公司在投标前测试，合格者颁发认证，后续此产品投标不需样机，所以我们样机必须百分百符合标书要求。 2. 此项目蓝牙表虽是新表型，但总体功能要求并不复杂，结合同行竞争来看，价格竞争将会非常激烈。', '泰国市场潜力很大，此蓝牙方案为泰国AMI计划前期试行方案，计划第一年2M台，三年内6.5M台。根据市场投标规则，必须有本地工厂和本地认证。代理在当地有一定实力，且合作意愿较强，已经投入建厂及完成部分表型认证，同时接受在我们提供符合要求样机的前提下支付合作抵押金。同时蓝牙通讯表为第一次招标且有未来长期采购规划，是进入市场的契机。目前尚未正式发标（技术部分已定案），电力公司已发出样机提交邀请（7.27前提交），测试45天后预计九月初发标。申请提前立项，尽快准备。', '庄钦2020-07-20 16:53:47', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('471', '{5BA0E1B6-37E8-47B2-98B8-9CD6F58B4E02}', '66', 'INHE-0634', '2020-07-03 09:03:46', '0000-00-00 00:00:00', '2020-07-06 12:40:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2020070301/SWG', '', 'N° AO – 97 314 – E', '2020年7月17日', 'SUPPLY OF REMOTE AND MANUAL CIRCUIT BREAKERS FOR ALL CENTERS DISTRIBUTED IN THREE (03) LOTS', '与代理之间：价格条款：CIF TAMATAVE；交期：1个月；付款方式：可协商（30%TT预付+70%发货前TT）', '', '3个包分别评比，在符合技术要求的前提下，价格最低者中标', '', '对中标家数没有限制，3个包分别评比', '', '代理负责开立', '', '供应商需要提供过去3年内类似项目的供货经验证明', '', '需要银河电网提供技术资料；需要商务部对技术资料进行法语翻译', '', '代理投标，银河供货', '', '', '', '', '', '', '', '代理与电力公司关系密切，屡屡中标不同电力设备项目（电表、掌机、电缆、变压器等）。', '', '', '', '断路器的竞争详情有待进一步了解', '', '采购数目不大，建议速战速决，提供技术资料和报价，试一试水。', '', '及时提供技术资料和报价；代理发挥影响力促成中标。', '合作代理与RMY,URV项目代理相同，与电力局内部关系较好，有较强的控局能力，在电力局中供货较多。代理与我在闲谈中得知银河还可以做中压产品，才透露该项目信息，希望与银河在除电表以外的项目上继续合作。建议立项，速战速决。', '陈雁2020-07-03 11:04:36', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('472', '{1D9CED11-B63F-4415-8BCB-8EA13FCB2C6B}', '61', 'INHE-0725', '2020-07-06 09:36:07', '0000-00-00 00:00:00', '2020-07-20 15:14:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020070601/PFL', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '代理直采', '直采订单，非联合体', '如需获得ECG直采短名单，样机测试和试点测试是基础，而客情方面，据内线和PFL代理透露，ECG MD、能源部、政客对决策影响较大，尤其ECGMD和能源部层面。', '', '付款基本原则为：\r\r\r\n1) Advance Payment: 20%-30%  \r\r\r\n2) Showing BL to ECG: Around 30%  \r\r\n3) Payment Upon Completion: 30%-40% \r\r\n4) Retention: 10%(Normally one year)。\r\r\n各表厂和ECG可以就付款条款谈判（付款条款受客情影响较大）', '', 'ECG经营状况良好，支付能力较强。请见附件2018年财报', '{1D9CED11B63F44158BCB8EA13FCB2C6B108D268797C74834B1DDE2FC1083AA37}_GEDAP-ECG-Financial-Statements-Dec-2018.pdf', 'PFL客户此前在本地主做变压器及输配电项目（和某中国厂商合作），和能源部客情较紧密，也很熟悉如何拿项目（目前已有项目在执行），与ECG MD熟识，同时借由能源部及MD客情在一周内快速与电表部和软件部建立了联系。\r\r\r\r\n公司实力较强，在沟通中，团队成员思路清晰，积极活跃，老板Frank有建厂意愿（有地皮），执行很多大项目，一起运作项目成功率较高，目前其暂无电表稳定合作方，我司入驻较容易。团队内部意见较一致，Frank决策有时会受制于董事会，但其董事会也较明事理，业务也经常与其董事会沟通。\r\r\r\r\n', '', '与ECG表计技术部门总监，表计测试部门两个技术员，软件部门一个技术员较为熟识，可侧面核实信息', '', '【科陆】，本地合作伙伴MBH，在本地有厂，SKD产线，目前在加纳运作积极；\r\r\r\r\n【隆基】，本地合作伙伴Meinergy，Meinergy老板原为福星晓程代理，福星晓程推出加纳电力市场后，自己成立了新公司与隆基合作，在ECG及NEDCO均已拿到订单，实力强劲；\r\r\n【El Sewedy】：2003年本地成立Ghana Elector Meter，实力较强，西非多个国家都在推项目；\r\n【Secure Meter Ltd】:本地合作伙伴Alpha TND，2014年建厂，实力次于上述三家；\r\n【Sneda Smart Meter】：合作伙伴核实中（一家中国公司，初步核实龙电），实力次于前三家；\r\n【IMES】：合作伙伴核实中，目前正在参与北方电力18.7万台电表项目投标，去年年末刚经历税务风波，被罚款。目前仍在活跃但实力不强。\r\n海兴正在执行GLZ（LPU）项目尚未完成，经核实，海兴尚未进入ECG采购短名单。', '', '竞争策略：与PFL客户合作，通过PFL项目完成样机测试和试点测试，进入ECG直采短名单后搭配PFL客情，获取订单并力争好的付款条件；\r\r\r\r\r\r\r\r\r\r\n优势：\r\r\r\r\r\r\r\r\r\r\n1. PFL实力强劲，有多次执行过大的电力项目，在ECG及能源部积累了人脉，愿意投入，做电表意愿强烈；\r\r\r\r\r\r\r\r\r\r\n2. 银河在ECG有内线（表计技术部门总监，电表实验室及软件部联络人），熟悉组织架构，决策流程；\r\r\r\r\r\r\r\r\r\r\n劣势：\r\r\r\r\r\r\r\r\r\r\n1. 本地竞争对手较多，大多深耕多年实力较强；\r\r\r\r\r\r\r\r\r\r\n做PFL项目的原因：\r\r\r\r\r\r\r\r\r\r\n银河已在ECG市场投入多年，GLZ/GLA/JJN失败让业务明白ECG市场如果只一味投标，竞争更激烈，做进ECG只能深耕，在电力公司打响银河品牌，才有订单拿。PFL是深耕ECG市场的第一步，如能快速完成样机及试点测试，则非常有利于我方从ECG拿到直采订单，推进本地建厂。', '', '成功关键：\r\r\r\n1. 优质的样机（电表+软件），一次性通过ECG实验室测试证明我方技术能力，快速通过试点测试；\r\r\r\n2. PFL处的客情配合，政客+ECG MD；\r\r\r\n需要的支持：\r\r\r\n1. 恳请公司解析本表附件2 ECG最新技术规格，基于此规格制作样机；\r\r\r\n2. 快速完成样机制作，尽快完成样机及试点测试，力争今年参与分蛋糕。客户要求2周内完成制作，业务可与客户协调三周，恳请公司尽快', '业务认为PFL项目是我方深耕ECG市场，进入ECG电力公司采购短名单的第一步，也通过此项目与后续试点合同绑定，如我方能借由PFL项目完成样机及试点测试，配合PFL客情，我方即可进入ECG直采短名单，很有利于我方从ECG获取直采订单。因PFL项目对于开拓ECG市场具有重大意义，也需公司提供样机制作及技术支持，业务自评星三星。', '赵政洁2020-07-06 11:29:29', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('473', '{01A0CD71-1999-4926-A5C0-43145AB4E909}', '66', 'INHE-0634', '2020-07-06 16:08:34', '0000-00-00 00:00:00', '2020-07-08 09:11:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020070602/SHP', '', '', '', '“节能/智能电力设备零售商店”', '交期可协商，付款方式可协商（30%预付款+70%发货前支付），质保为厂家质保（如厂家决定是1年则为1年）', '', '', '', '', '', '', '', '', '', '', '', '代理直接采购，银河供货', '', '', '', '', '', '', '', '', '', '', '', '无其他竞争对手，本项目电力局仅与我方代理洽谈合作。电力局免费试用代理的房产，以减免代理的电费作为交换。', '', '电力局内部高层请代理的帮助，希望通过此类电力设备零售店铺（兼客户服务中心）提升服务质量和形象；代理作为顾问协助提供执行方案并采购设备最后转卖给电力局。预计在本年内可转换为实际订单。', '', '需要有熟悉该类产品的技术支持配合。', '建议立项，推动新业务领域的扩张。（备注：上述采购数量仅是初期为报价提供价格水平有依据而保守估计。）', '陈雁2020-07-06 17:23:27', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('474', '{CACC6358-3C3A-44ED-8742-ACA4C551D5E3}', '61', 'INHE-0654', '2020-07-10 05:24:25', '0000-00-00 00:00:00', '2020-07-13 13:53:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071001/MCM', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.该代理和CENENAR电力公司均是该市场的新客户，此批订单作为电力公司的试点，试点满意后会增加数量（该电力公司需求量一年仅有5万台，但这只是哥伦比亚其中一个地区的电力公司）；2.电力第一次了解银河，需要样机进行测试（可以先收取项目保证金，同步进行）；3.附件是电力公司给出的简版技术规格，较为简单，待立项通过业务发出解析；4.此订单为直采；', '李明2020-07-10 06:03:24', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('475', '{3ECD8064-93CE-44A1-8269-EF40BBDC8073}', '61', 'INHE-0876', '2020-07-11 03:24:51', '0000-00-00 00:00:00', '2020-07-14 09:50:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071101/SNA', '', 'Appel d’Offres International No 30/ 2020Réf PPM : Fpee_290', '2020年8月19日当地时间09:30', 'SNA', '价格条款：20%预付+70%到货+10%验收\r\r\n付款主体：德复行\r\r\n交期：合同签署后60天', '', '', '', '一家中标', '', '保函需转开 181，000 欧元\r\n', '', '满足', '', '暂无', '', '银河投标', '', '采购将按照KFW（德复行）准则和公共采购法规中定义的国际招标进行，并向所有合格候选人开放。如果KFW合同授予规则与塞内加尔公共采购法规相抵触，则以KFW合同授予规则为准；', '', '20%预付+70%到货+10%验收', '', '第三方融资 德复行', '', '只有一个当地电力公司任职的客户关系，职位中层，未曾见面；\r\r\n市场被海兴和科陆常年盘踞并竞争激烈，基于此次第三方资金，业主决策能力有限，因此直投；', '', '只有一个当地电力公司任职的中层关系，未曾见面；', '', '市场被海兴和科陆常年盘踞并竞争激烈，基于此次第三方资金，业主决策能力有限，因此直投；', '', '电力公司新任总经理希望引入新的供应商以平衡现有的供应体系', '', '1. 技术方案和资料需要精准制作；\r\n2. 基于技术资料无误的情况下，优厚的商务才能保证杀入市场', '第三方资金，建议直投；', '邓彧2020-07-11 03:39:41', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('476', '{A320CF0A-4887-44D3-9FE4-98533421B8DD}', '61', 'INHE-0744', '2020-07-13 00:00:04', '0000-00-00 00:00:00', '2020-07-14 09:46:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071301/CNE', '', 'AOI N° : 06/SNEL/CEP/PEPUR/TRV-SNT/2020', '2020年7月24日', 'Programme d’assainissement et de renforcement des réseaux Moyenne Tension (MT) & Basse Tension(BT) dans huit communes de Kinshasa-Sud et Kinshasa-Est  金沙萨市东区和南区中压和低压电网的整改', '中标后代理商直接向银河进行采购，30%预付款进行订货，交货前支付70%尾款', '{A320CF0A488744D39FE498533421B8DD8442F4C2B3234363A3D51C033076BD50}_刚果金项目20200711.rar', '综合打分，商务和技术部分分别评审，最高分者中标', '', '独家中标', '', '代理商出保函', '', '代理商资质', '', '投标授权书、用户证明、产品画册、参数表、型测报告、报价单', '', '代理商投标', '', '非洲发展银行项目，由政府、电力公司、非洲发展银河共同决策', '', '30%预付款，70%交货前付清', '', '						\r\r						\r\r\n\r\n中标后代理商采购，代理商为央企，支付能力充足						\r\n', '', '代理商在当地的在手电力项目总合同超7亿美金，与电力公司及政府关系良好。2020年已经中了一个世界银行的1千万美元+的电网改造标段。', '', '银河只有一些初步的接触，由于未批量供货，并未有很深的直接关系', '', '本次的招标为电网改造，电表只是本合同中很小的一个部分。代理商的主要竞争对手为国内的几大电力央企', '', '之前跟代理有过几个项目的合作，但是由于代理商未中标，导致未能供货。银河业务跟代理商在当地的总经理私人交情很好，主要依靠代理商的关系进行运作。', '', '提供符合标书要求的资料和合理的报价', '该项目是一个很大的招标，电表只是其中的很小的一个部分，银河并无资格直接参与招标。虽然电表招标数量不多，但是不需要保函、样机等，只需要提供资料和报价，整体投入较小。代理商在该市场深耕多年，有强大的客情关系。在2020年疫情的影响下异常艰难，不应该放过任何一个有可能的销售机会。', '郑超波2020-07-13 00:30:57', '00', '★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('477', '{92DC747F-323D-44FC-905A-5F079CEF3BBA}', '66', 'INHE-0774', '2020-07-14 08:54:54', '0000-00-00 00:00:00', '2020-07-16 12:41:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071401/NAS', '', '', '', '', '价格条款：CIF\r\n付款方式：信用证\r\n质保：3年\r\n\r\n\r\n\r\n', '{92DC747F323D44FC905A5F079CEF3BBA8442F4C2B3234363A3D51C033076BD50}_Smart Meter - RFQ.pdf', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '据此客户介绍，2018年电力局和多家合资公司签署了初始合同（YDD项目为其中之一），由这些公司供应智能电表，并管理和运营伊拉克的整个电力网络。但是这些公司无法满足电力局的严格要求和技术规格，导致合同被取消。现在电力局重启项目，希望达成的目标是：\r\r\r\r\r\n1. 项目由Qarnass 投资，6年内供应安装500万台智能电表，由Qarnass收取电费；\r\r\r\r\r\n2. 整个项目覆盖伊拉克19个省的所有用户；\r\r\r\r\n3. 更换智能电表后，用电用户总数达到7百万。								\r\r\r\r\r\n								\r\r\r\r\r\n\rYDD项目代理和电力局的合同已取消，代理对继续推动项目不积极也没信心。我们需要同时从其他客户入手才有机会进入市场，因此希望给客户Qarnass报价，并提供技术支持,帮助其和电力局达成最终协议。\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n', '何森华2020-07-15 15:15:24', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('478', '{60AD3E38-DFBB-4714-B8E8-22E205681BDE}', '61', 'INHE-0381', '2020-07-14 10:43:38', '0000-00-00 00:00:00', '2020-07-16 17:24:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071402/ALP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1.需要技术支持提供远程培训。\r\n2.需要软件部提供可做试点的能源云系统。2个月试点结束满意，电力公司将直接采购。', '1.现任总经理新上任想做政绩，所在在找厂家提供技术支持。目前电力公司面临的问题主要还是窃电、回收电费的困难。他首要提出抄读变电站后馈线总表的供电量，即CT表，然后跟抄读回来的用户用电量做对比，分析线损。\r其次，\r电力公司有3、4套系统，总经理想使用一套集计量、抄读、账单、付费等一体的系统，不想多套系统同步使用，已给他推荐了能源云。\r\r\r\r\r\n2.项目分三个阶段：阶段一：采购3台CT表作为样机+3台掌机抄机械表+2个月的能源云系统试用。\r\r\r\r\r\r\r\r\r\r\r\n阶段二： 如果试点一效果好，采购200台CT表+能源云系统\r\r\r\r\r\r\r\r\r\r\r\n阶段三：找世行融资，运作招投标十万以上电表（单三相表）。\r\r\r\r\r\r\r\r\r\n\r\r\r\r\n', '张柳芳2020-07-14 15:09:34', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('479', '{508A62D8-B61C-4925-ADDF-357F5DB13E77}', '66', 'INHE-0634', '2020-07-21 11:00:42', '0000-00-00 00:00:00', '2020-07-21 17:09:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2020072102/TDA', '', '', '', '', '（1）价格条款：CIF仰光；（2）付款方式：30%TT预付+70%发货前TT支付；（3）交期：1个月（4）质保：1年', '', '', '', '', '', '', '', '', '', '', '', '客户直采，银河供货', '', '', '{508A62D8B61C4925ADDF357F5DB13E774B57BEDC2B9B49859FFB35E337472DB5}_项目经验-1.png', '', '{508A62D8B61C4925ADDF357F5DB13E77DC30B63FF962416CACC9A604CE6ABE1F}_项目经验-2.png', '95年成立，业务稳定，项目经验见右侧附件，主要包括：230kV，常规和G.I.S变电站。\r\r\r\r\n66kV，33kV，11kV，常规和G.I.S变电站。\r\r\r\r\n架空输电线路，最高230kV。\r\r\r\r\n地下电缆配电网络（最高66kV）\r\r。\r\r\n低压电缆和母线分配系统。\r\r\r\r\n适用于商业，住宅和工业项目的所有类型的MSB，EMSB和DB。', '{508A62D8B61C4925ADDF357F5DB13E77108D268797C74834B1DDE2FC1083AA37}_项目经验-3.png', '', '{508A62D8B61C4925ADDF357F5DB13E77D18C251E4D454BA8A05CF92EE9AFCB77}_项目经验-4.png', '', '', '', '', '', '', '须有满足客户需求的产品和合适的报价。', '该客户项目众多，每年对电表都会有一定的需求（单位：千），如发展成忠实买家，则多一个短平快的销售渠道。建议立项，提供offer。', '陈雁2020-07-21 11:20:54', '00', '★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('480', '{C67B3F29-C27C-462C-A5DD-66DCE8F432CF}', '61', 'INHE-0434', '2020-07-24 11:47:33', '0000-00-00 00:00:00', '2020-07-27 21:17:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2020072401/AGL', '直接收钱做货吧。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '1. 客户与银河有过业务往来，AGL为新订单，后续有机会扩大LPU业务\r\r\r\n2. 与EVANS沟通调用CDE 50台BOX300发货\r\r\r\n3. AGL将采用100%发货前T/T\r\r\n4. 经与客户沟通要求提供合同与PI\r\n\r\n综合以上，希望公司同意立项。', '钟云林2020-07-24 13:51:23', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('481', '{CC42462F-9F42-4CCF-B023-6FE605CC66EB}', '153', 'INHE-0015', '2020-08-06 09:09:04', '0000-00-00 00:00:00', '2020-08-07 11:03:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020080601/ZHX', '', 'CALL-FOR-PROPOSAL TO DEVELOP AND TEST-BED NARROWBAND INTERNET-OF-THINGS ADVANCED ELECTRICITY METERS', '　２０２０／０９／２３', 'CALL-FOR-PROPOSAL TO DEVELOP AND TEST-BED NARROWBAND INTERNET-OF-THINGS ADVANCED ELECTRICITY METERS 基于NB－IOT的先进电表研发及试点建议书邀请', '目前项目处于资格审查阶段，因此付款条件未知，计划通过商务协商要求合作伙伴以ｔｔ或者LC进行采购', '{CC42462F9F424CCFB0236FE605CC66EB8442F4C2B3234363A3D51C033076BD50}_CFP for NB-Iot Trial Media Release2.pdf', '评审委员会根据投标人提交的项目建议书、研发工作计划时间表、提出的产品设计方案对技术要求的响应度、项目执行成本、类似项目执行经验等内容确定通过资格审查、可以参与试点项目投标的投标人，其中项目建议书内容占比４０分，建议方案经济性４０分，建议书提出方团队经验、能力２０分，附件是客服对产品技术规格要求的解析结果，我司现有产品方案基本满足９０％的要求，证书／测试报告方面的偏差主要缺乏的是加速寿命实验报告；', '{CC42462F9F424CCFB0236FE605CC66EB074E749A304748709C51373D9D483750}_Page_24-_31_NB-IoT_metering_requirement[1].docx', '由于是研发项目，因此没有规定是否一家中标，据客户告知，根据智能水表项目经验，业主倾向于选择２－３家投标人执行此项目，以分散风险', '', '无保函要求', '', '暂无特殊要求，', '', '需要提供资料给客户、协助客户起草并完善项目建议书，８月底之前应准备好并提供给客户', '', '暂定银河授权客户参与', '', '', '', '招标文件暂未说明', '', '业主支付能力无问题', '', '合作伙伴已经在同一业主处中标智能水表项目并完成交付，对当地市场运作熟悉，', '', '目前和业主尚无直接联系', '', '与合作伙伴签订保密协议后会继续获取相关信息', '', '银河现有方案的产品功能上与技术要求偏差较小，已经有NB－IOT通讯方案产品，合作伙伴已经和本项目同一个业主有过同一个规划下的智能水表项目中标、履约、交付经验，在客户关系和渠道上有优势，中标关键在于项目建议书的内容；', '', '提出合理的产品定制化研发时间计划，有价格竞争力的产品设计方案（能够１００％满足电力公司要求），快速的研发执行和交付，成功的现场试运行（满足业主方提出的、明确的试点项目KPI考核要求），竞标阶段主要需要的支持是客服部提供的项目建议书内容和不出问题的样机', '新加坡市场是发达国家市场，此项目虽然从长期看数量相对不大（总需求在１００万台，初期需求２０万台，银河预期拿到三分之一左右），但市场含金量较高，此项目实质为研发／试点项目，竞标期间投入以现有方案产品样机为主，不需要研发额外投入，产品研发工作在获得研发合同后６个月之内完成研发及试点项目产品交付，获标重点在提交的项目建议书内容和质量上，我司合作伙伴之前已经有类似水表项目中标及执行交付经验，而本次招标的评标团队与水表项目团队是同一批人，其在客户关系和项目建议书起草经验上具备足够的经验；一旦研发产品通过试点项目验收，即可以参加首批２０万只的议标采购，一旦在议标项目中标并完成履约供货，银河就成功切入新加坡市场，因此，此项目值得认真对待，投入一定资源支持合作伙伴参与', '王维2020-08-06 10:57:13', '03', '', '02');
INSERT INTO `crs_tabledata1533` VALUES ('482', '{CCAEB566-D26F-4158-A3F5-00B0EC3CA551}', '60', 'INHE-0680', '2020-08-11 10:20:11', '0000-00-00 00:00:00', '2020-08-11 17:20:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081101/AFD', '', 'NPA/DABS/99/G-2802/ICB/ AF-DABS-147417-GO-RFB', '2020.9.2', 'Procurement of supply and delivery of Smart Prepaid Electricity Meters for Herat Province. Herat省只能预付费电表采购', '价格条款：CIP\r\n付款主体：电力公司DABS（世界银行贷款资金）.\r\n付款条款：10%TT预付+80%LC见单+10%TT验收\r\n          \r\n交期：电表，CMRI：4-6个月；系统及相关硬件和服务器销售点：6-9个月；安装及培训：18个月\r\n质保：5year\r\n备注：交货违约最高10%。				  代理付款方式：从第三国，30%预付款+70%发货前 TT 或由银河接受的银行开出LC\r\n', '', '先开技术标，通过者再开商务标\r\n', '', '一家中标，价格最低	\r\n', '', '投标保函：Bid-Securing Declaration，生效至投标有效期后28天，若违反，三年不得参与该业主投标；\r\n履约保函： 10%合同额，中标通知后28天内开立，代理可提供所有保函\r\n', '', 'P52-53 Technical Part & Financial Part        \r\n', '', '', '', '联合投标', '银河主投，代理负责开立所有保函，银河提供产品，对代理培训及售后，代理负责安装及对业主培训，售后\r\n', 'DABS自主采购，评标。\r\n', '', '10%TT预付+80%LC见单+10%TT验收', '', '世界银行已贷款给电力公司6000万USD，部分资金将用于此项目，由电力公司付款\r\r\r\n', '', '电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。\r\n', '', '尚未与DABS建立直接关系。\r\n', '', '这次是该市场第一个智能表系统项目，价格定位及对手产品方案暂不明确。竞争者可能思达，科陆，威胜及国外表厂。\r\r\n', '', '利用合作伙伴在DABS电力公司的人脉关系和渠道，并在价格上领先。\r\n', '', '结合代理关系运作，投标价格建立优势。\r\n', '1.此项目为联合投标，银河主投。投标保函，履约保函由代理提供                                              2.不需要样机，投标资料准备主要在文挡工作。                                                             3.代理以前与电力公司有较好的关系。\r\r\r\r\r\r\r\n4.阿富汗市场有AFH项目由庄钦负责，现因庄钦其他项目与本项目时间上造成冲突，本人申请协助\r庄钦负责此项目，具体工作职责和业绩分配，请杨经理斟酌。\r\r\r\r\n      \r\r\r\r\r', '陈嘉豪2020-08-11 11:02:15', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('483', '{8450C666-4B55-4CA6-A379-5148E79E8CB9}', '61', 'INHE-0772', '2020-08-12 17:21:35', '0000-00-00 00:00:00', '2020-08-18 09:16:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081201/SAO', '', 'EIB/01/G/PSR/2019', '2020.9.4', 'Sao Tome and Príncipe Power Sector Recovery Project 圣多美岛店里复兴项目', '国外投标人：CIP圣多美岛，欧元结算。付款主体：EIB 欧洲发展银行\r\r\n交期：120天\r\r\n付款方式是：T/T +L/C\r\r\n付款条件：开立预付款保函，支付10%预付款。 交付发票，装箱单，产地证和提单后，支付80%发货款。验收后30天，支付10%余款\r\r\n', '{8450C6664B554CA6A3795148E79E8CB98442F4C2B3234363A3D51C033076BD50}_Meters_20200709_BD_Smart?Meters?3?Lots_Final?version?-20200709.docx', '符合技术规格的最低价中标', '', '可1家中多个标段，但要求最终3个标段的授标合同总价最低。', '', '代理开立；投标保函46000欧元，120天，如中标需要开立履约保函，预付款保函都是合同金额的10%', '', '投标人过去3年的年均营业额，过去3年类似项目项目清单', '', '商务部分：协助投标资料准备\r\r\n技术部分：除了客服部，软件部和电网公司的技术支持。技术解析需要在8月\r\r\n21完成，技术投标文件在8月24号完成。', '', '代理商投标', 'EPC项目，涉及到当地安装和后续的2年售后维护。 代理主投，银河是联合体成员。 原因：全新市场，无积累。 代理在当地有供货经验。 这个代理强势，如仅提供厂家授权，后续与代理的合作如有变动，存在代理不下单的可能。一开始明确联合体的合作方式，后续绑定关系牢固。大致分工：代理负责当地客情，保函开立，收款与售后等。 银河负责供货，与代理结算。', '政府不影响采购，项目组PIU由电力公司EMAE和AFAP派人组成，电力公司负责技术部分的评审，技术评审结束后取最低价，评审结构由AFAP对接银行，银行审核通过后执行', '', '根据合同准备发票，装箱单，产地证和工厂验收证书等发送给AFAP，AFAP审核后向EIB发起支付请求，EIB审核同意后付款。', '', '代理与银河合作多年，支付能力强', '', '代理在本市场有供货电线电缆', '', '银河无一线客情，当地关系依靠代理', '', '根据电力公司当前项目的报告，SAO市场用的机械表。SAO智能表项目是第一个，智能表竞争对手多数是本地代理商，情况不了解。', '', '银河形式：新市场无客情，对市场需求不熟，截标时间紧。应对：无耕耘市场通\r\r\r\r\r\r\r\r\r\r\r\r\n过代理去投标，降低自己的投标成本，时间不足我们自己无法直投，开保函时间不足，但对于做资料，时间还是充足的。授权代理投标，保函代理开，同时由代理去争取延标。新市场对所有的厂家是起点一致的，欧美厂家价格没有优势。其他中国厂家不如银河的外海资源多。项目虽然没有要求样机，当时要求MID证书，证书要求可淘汰部分低价厂家，对于银河竞争有好处。本项目对商务资质要求不高，难点在于技术部分，种类多，涉及到电表，软件和配电设备，跨部门的沟通很困难，当务之急是我们抓紧时间对产品做技术解析，立项同时，先发出技术分析申请，以节约时间。', '', '本项目对商务资质要求不高，难点在于技术部分，种类多，涉及到电表，软件和配电设备，跨技术部门的沟通很困难，当务之急是我们抓紧时间对产品做技术解析，立项同时，先发出技术分析申请，以节约时间。', '市场虽小，但内有LPU产品和软件产品，项目金额值得我们支持代理参与。', '张子琦2020-08-14 11:24:53', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('484', '{79AA1C03-36E3-A5A7-F616-51379B70750F}', '61', 'INHE-0819', '2020-08-12 22:48:16', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', 'NFD', '', null, null, null, 'sm3110383', null, 'MISE EN PLACE DUNE SOLUTION DE LECTURE EN LOCAL DES COMPTEURS PREPAIEMENT STS DE MARQUE INHEMETER', null, '1,蓝牙红外头供货，签合同后TT或LC支付93%，最终验收后TT支付7%。                            2，软件供货，拿到ONEE签发的临时验收PV后TT或LC支付93%，最终验收后TT支付7%。                               3，培训，拿到培训PV后支付100%培训款。', null, null, null, null, null, '1，投标保函：20000摩洛哥迪拉姆，约2000美金左右。2，履约保函为合同金额（含增值税）的3%。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '此项目目的是服务于NF2 STS预付费表的，为后续预付费电表招标项目做准备。', null, null, null);
INSERT INTO `crs_tabledata1533` VALUES ('485', '{1108F210-7673-4B46-A0DF-293B39003267}', '61', 'INHE-0819', '2020-08-13 16:55:21', '0000-00-00 00:00:00', '2020-08-14 17:19:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081302/NFE', '', 'SM3110383', '2020年8月26日', 'MISE EN PLACE D\'UNE SOLUTION DE LECTURE EN LOCAL DES COMPTEURS PREPAIEMENT STS DE MARQUE INHEMETER(给INHEMETER的STS预付费电表实施本地读表解决方案)', '1,蓝牙红外头供货，签合同后TT或LC支付93%，最终验收后TT支付7%。                            2，软件供货，拿到ONEE签发的临时验收PV后TT或LC支付93%，最终验收后TT支付7%。                               3，培训，拿到培训PV后支付100%培训款。', '', '议标流程', '', '银河中标', '', '1，投标保函：20000摩洛哥迪拉姆，约2000美金左右。2，履约保函为合同金额（含增值税）的3%。3.质量保函：10%。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '此项目目的是服务于NF2 STS预付费表的，为后续预付费电表招标项目做准备。', '付为2020-08-13 17:07:20', '01', '', '01');
INSERT INTO `crs_tabledata1533` VALUES ('486', '{9561E024-F6EE-46B9-9558-5D852A39BB5B}', '93', 'INHEGRID-0048', '2020-08-14 10:14:44', '0000-00-00 00:00:00', '2020-08-18 10:29:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081402/SPM', '', 'EIB/01/G/PSR/2019', '2020年9月4日', 'Supply and Installation of Equipment for Metering Solution 供应和安装计量方案产品', '质保：365天 需要在30天内更换或维修缺陷产品\r\r\n交期：最早60天，最晚120天\r\r\n价格条款： CIP San Tomé Island\r\r\n付款条件： \r\r\n1.在签订合同后的三十（30）天内支付合同货款的百分之十。供应商需提供与合同合同10%预付款金额相当的预付款保函；\r\r\n2.供应商发货后需提供在其所在国家/地区的银行开立信用证，业主支付合同货款的百分之八十（80）。\r\r\n3.供应商在收到业主发的验收通知30天内，业主应支付余下10%货款。', '{9561E024F6EE46B995585D852A39BB5B8442F4C2B3234363A3D51C033076BD50}_表1：SPM项目投标信息归纳表.xlsx', '本项目共有3个lot,lot将会被逐次评标\r\n', '', '每个lot最低价中标且投标文件响应标书要求', '', '标书要求投标保函转开\r\r\r\n投标保函：Lot 1: 欧元4,000#FE54`\r\r\nLot 2: 欧元10,000#FE54`\r\r\nLot 3. 欧元32,000.\r\r\n投标保函有效期应该在投标有效期后28天，即为148天。\r\n投标保函有效期应至2021年2月4日\r\n\r\n\r\n收到中标通知后的二十八（28）天内，中标人应提供履约保函\r\n履约保函为合同金额的10%\r\n\r\n预付款保函应与合同10%预付款金额相当。', '', '财务：\r\r\n1. 过去3年设备制造总营业额：2,000,000美元；\r\r\n2. 必须提交最近三年的财务报表；\r\r\n\r\r\n供货：\r\n过去三年提供类似规格产品的供货记录\r\n\r\n过去三年生产制造与本标书要求产品数量相当的生产能力证明', '', '8月20日上午11:00前', '', '代理商投标注：经与电力财务部沟通，目前中国的银行在当地没有合作行，所以目前在与代理沟通由他们在当地开投标保函，电力授权代理投标。', '', '', '', '圣普政府已申请或收到了来自欧洲投资银行的融资，圣普政府打算将部分资金用于本项目。在AFAP将中标结果告知圣普政府后，圣普政府向欧洲投资银行（EIB）提交付款申请。EIB之后会审核招标并在审核完成后向供应商支付货款。      \r\n', '', '', '', '代理CIEM业务涉及汽车经销，医疗设备，发电机安装。\r\r\nCIEM与AFAP和EMAE有着良好的客情关系，并且已中标并为AFAP合EMAE提供过发电机产品和安装服务。\r\n\r\r\n', '', '圣普是新市场，客户关系待建立', '', '欧洲厂家参与的较多', '', '', '', '', '此项目招标中低压计量产品和安装培训服务，在银河电网的经营范围之内。由于电表产品需求较多，此项目银河电网主导，由电力出具厂家授权书；\r\r\n\r\r\n经技术支持同事对技术规格书的解析，此项目具有投标可行性；\r\r\n\r\r\n标书要求投标保函转开，经与电力财务部沟通，国内的银行在当地没有转开行，所以目前在与代理沟通：由代理在当地开投标保函，电力授权代理投标。\r\r\n\r\r\n圣普国家较小，此次项目规模较大，未来几年很少再有类似规模的电力项目，项目机会宝贵。\r\n本人一直联系圣普当地电力代理并跟进，代理参与度高，当地代理与AFAP和电力公司EMAE客情关系好。\r\n请公司支持此项目立项。\r\n\r\n\r\n\r\n', '李林（Wilson Li)2020-08-14 15:52:57', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('487', '{73404422-E12C-4F61-95C0-1DF7655E741F}', '172', 'INHE-0913', '2020-08-18 17:09:57', '0000-00-00 00:00:00', '2020-08-24 09:16:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081801/GAB', '', '', '', '此项目预计进行限制性招标，目前还未正式公开招标信息，预计标书将于九月初发出', '', '', '', '', '', '', '', '', '', '', '', '', '银河投标', '', '因项目资金来源为电力公司的自有资金，因此招标方的决策权限较大', '', '', '', 'SEEG为私有化公司，且为上市公司，加上近几年SEEG财政盈利状况好，支付能力有一定的保障', '', '与银河合作的代理，此前已经有过经验，和其他厂商合作，在加蓬安装了水表的AMI系统，并且已经投入运营。同时，代理与电力公司有一定的客户关系，客情条件较好，对于信息的获取都比较及时。此项目还未正式发标，但是已经获知电力公司的需求', '', '目前还未与电力公司建立客户关系', '', '已知参与厂商有兰吉尔等三家厂商，并且兰吉尔已经在电力公司内部进行了AMI系统的演示', '', '优势：\r\r\n在发标之前银河已经获知项目情报，并且在代理的帮助下，可以争取到与电力公司直接进行内部演示的机会，抢占先机\r\r\n劣势：\r\r\n1.银河此前未进入过加蓬市场，对于电力公司以及市场情况了解不够深入\r\r\n2.主要客户关系都握在代理手中，所有项目信息均由代理提供，和电力公司没有直接的客户关系，受限大\r\r\n\r\r\n竞标策略：\r\r\n加蓬作为一个新市场，虽然银河的客户关系和市场信息不够完善，但是参与是十分有必要的，能够为未来打下基础。一方面，需要尽快调查加蓬市场的情况，输出市场调查报告；另一方面，目前暂时判断，代理的客户关系比较靠谱，需要电力公司和代理两边同时进行，尽快建立起与电力公司的直接客户关系，有可能的话直接对接客户，跳过代理\r\r\n', '', '本周内，希望能够安排客服部支持，与代理进行一次银河AMI系统的线上演示，并尽快推动与电力公司的内部演示', '加蓬此AMI项目，由于还未正式发出投标信息，希望能够尽快推动与代理进行电力公司的直接接洽，抢占先机', '魏紫薇2020-08-18 17:44:11', '02', '★★★', '01');
INSERT INTO `crs_tabledata1533` VALUES ('488', '{6C3E4DEE-BF54-4DAE-88DE-9A8BC2694A1E}', '75', 'INHE-0432', '2020-09-01 01:44:46', '0000-00-00 00:00:00', '2020-09-02 10:52:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2020090101/KDA', '', 'KP1/9A.3/OT/07/20-21', '2020年9月10号。标书早已发布，IAC团队也已经准备了2个星期多，目前有较好的厂商愿意合作，所以才决定立项。', '低压、11KV和33KV熔断器招标。', '价格条款：DDP\r\n付款主体：KPLC\r\n付款条件：满意交付后30天起开始走付款流程。\r\n交期：1年\r\n质保和违约条款：交付后5年\r\n', '', '一审：商务资质审核。\r\n二审：技术资料评审\r\n三审：报价评审。', '', '一共有3个LOT，每个LOT有14种产品，评标按每个LOT的每个产品评标，最低价中标。但同一种产品，不可重复中标。', '', '投标保函：\r\nLOT1: 约2.5万美元的肯先令\r\nLOT2: 约2万美元的肯先令\r\nLOT3: 约1万美元的肯先令\r\n每个LOT，都必须开对应的保函。\r\n\r\n履约保函：合同金额10%。', '', '1.用户证明：4份\r\n2.要求提供形式测试报告、ISO17025认证。\r\n', '', 'IAC团队自己投标、直接竞标。技术资料由厂商提供，IAC自行审核，无需国内技术解析。', '', 'IAC直接投标', 'N/A', '主要决策链为评标团队：采购部、标准部最重要，其次是配网部工程师；采购总监和MD不反对授标即可。', '', '同以往项目。', '', '', '', '', '', 'IAC业务直接做客户关系。目前和采购部、标准部客户关系较好。', '', '						\r\r\n主要竞争对手为中国厂商和部分印度厂商（授权本地代理）。\r\nIAC第一次参与此类项目投标。						\r\n', '', '策略：\r\r\n1.IAC目前在和几家厂商谈合作，寻求资料和报价。IAC自己会先把好关，确保与有一定资质和业绩的厂商合作。\r\r\n2.资料准备好后，会请内线核查。\r\r\n3.IAC适当加一点利润空间，确保略有盈余即可，中/低价中标。\r\r\n4.IAC提前做好客户关系布局。', '', '成功关键：\r\n1.有较好资质的厂商合作（IAC在跟进）\r\n2.客户关系（IAC已开始准备）\r\n\r\n需要的支持：\r\n公司同意立项，并同意IAC竞投。\r\n', 'IAC正大力拓展电表以外产品项目，此前KFG绝缘子招标项目，当时没有经验，参照电力公司预算报价，结果发现预算价格比实际投标偏高太多，因而无法中标。此次IAC将大幅度降低利润空间，确保略有盈余即可，保证价格有竞争力；客户关系方面目前有较好的进展。希望公司支持。', '谭东羊(Timon)2020-09-01 03:18:55', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('489', '{D1C7D34B-11D7-424D-96F9-7E070DB55A80}', '60', 'INHE-0680', '2020-09-01 09:37:09', '0000-00-00 00:00:00', '2020-09-07 10:07:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2020090102/EGM', '', '', '2020.9.11', 'Equipment, Materials and Conceptual Design Drawings of 33 kV overhead distribution lines and LV networks within the villages as well as distribution transformer stations and consumer connections.', 'T/T预付30%, 尾款70% T/T 或 LC', '', '先提交资料和报价，通过资质评审阶段后再提供样机做Demo，最后评价格。初步评估标准样机符合，不需要额外研发。', '', '一家中标', '', '代理商开立投标保函，履约保函', '', ' STS会员，IEC or ISO\r\r\nIEC 62052-\r\r\n11:2002\r\r\nElectricity metering equipment (ac) - General requirements, tests\r\r\nand test conditions- Part 11: Metering equipment\r\r\nIEC62053-\r\r\n11:2003\r\r\nElectricity metering equipment (ac) - Particular requirements. Part\r\r\n11: Electromechanical meters for active energy (classes 0,5, 1 and 2\r\r\nclasses)\r\r\nIEC62053-21 Electricity metering equipment (ac) – Particular requirements –Part\r\r\n21:\r\r\nStatic meters for active energy (class 1)\r\r\nIEC 62055-52 Standard Transfer S', '{D1C7D34B11D7424D96F97E070DB55A8003404677E4D44E9EB56B3D512B2AF9CC}_STS Prepayment Meters.pdf', ' 投标/报价所需的提交：\r\n1.填写技术数据表\r\n2.外形尺寸/总体布置图，显示组件的布局图。\r\n3.所提供设备的完整技术细节的描述性文献\r\n4.仪表的形式测试证书/报告\r\n5.已经使用所提供仪表类型的客户的详细证明清单\r\n6.制造商质量保证政策/计划的详细信息\r\n7.偏差规格\r\n8.样机\r\n9.制造商授权\r\n10.用户证明\r\n\r\n授予合同后需要提交的文件：\r\n1.设备的详细尺寸/布置/布局/示意图/接线图。\r\n2.详细的安装和调试说明。\r\n3.生产和测试计划\r\n4.工厂测试报告\r\n5.操作和维护手册		', '', '授权代理商投标', '', '', '', '', '', '', '', '代理商在黎巴嫩电力公司已经多次中标，有输电线路，变电站成功中标经验。', '', '暂无', '', '科陆，海兴低价策略', '', '1.银河符合投资资质，产品技术规格符合；\r\r\r\n2.借助代理的承包商资质和其丰富项目运作经验；\r\r', '', '按时提交投标文件，符合要求的样机，通过技术评审，方案评审，价格最低。', '1）代理做投标方（总承包），银河做电表供应商。\r\r\r\n2）授权代理投标，提供资质，技术和授权投标文件（扫描版），标准样机。\r\r\r\n3）代理与电力公司结算，银河与代理结算。\r\r', '陈嘉豪2020-09-02 10:43:59', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('490', '{7A1D93E5-2BDD-4C3D-A45D-9FBFB8F0C862}', '173', 'INHE-0500', '2020-09-04 14:27:59', '0000-00-00 00:00:00', '2020-09-08 09:07:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2020090402/BCM', '', 'CE 393', '2020年9月22日当地时间12点', 'Supply,Install and Management of Prepaid Electricity Vending System Incorporating Third Party Collection Service for BCM for a period of Three(3) Years.STS预付费售电系统3年期框架合同(涵盖第三方售电系统平台兼容），设计、供应、安装、托管一体化', '市政公司对投标人价格和付款条款：服务商和市政公司按照投标报价的售电比例佣金和手续费，按照双方约定的时间周期（如每天或者每周），由服务商开具以当地币计价的并经过审计的售电佣金发票给市政公司核算和确认，确认后服务商扣减掉对应的佣金金额后，售电余额转至市政公司指定财务账户。\r\r\n\r\r\n银河和代理的价格和付款条件：待中标后协商，预计将需要采用共同监管账户的模式保障银河利益和收入。\r\r\n', '', '\r\r\n1.商务评审（基础商务门槛审核，如BBBEE资质、财务资质等）；\r\r\r\n2.技术门槛审核（资料审核+演示审核），符合技术基本门槛才能进入到最终报价核算阶段。\r\r\r\n3.报价核算和BBBEE资质（BBBEE资质占比10%）混合计算后，得出最优中标推荐名单。', '', '一家中标\r', '', '无需投标保函，中标后需要在本地开立Bank Insurance Guarantee，不低于1千万兰特，有效期三年。', '', '1.投标人须提供已在当地正在或者已提供过涉及现金、银行卡、EFT等售电途径的成功项目案例，不少于三个类似项目。银河合作代理满足；\r\r\r\n2.STS 2证书；\r\r\r\n3.ISO9001:2015证书；\r\r\r\n4.不少于5个售电系统成功实施案例。', '', '主要需要商务组同事协助对接技术解析和技术应答表资料的提供，主要技术资料需要软件部同事协助参与制作和应答。其余资料业务组内自行完成。', '', '银河授权本地代理Tsogatec (Pty) Ltd投标', 'N/A', '1.大都市市政公司项目核心决策层和拍板权在市政CEO处（一般为本地政党代言人）层面，评标决策圈较小；\r\r\n2.评标技术团队和商务团队业务能力和技术能力较弱，一般无法从技术严格上区分和筛选淘汰，主要依靠上层的指示行事。', '', '市政公司对投标人价格和付款条款：服务商和市政公司按照投标报价的售电比例佣金和手续费，按照双方约定的时间周期（如每天或者每周），由服务商开具以当地币计价的并经过审计的售电佣金发票给市政公司核算和确认，确认后服务商扣减掉对应的佣金金额后，售电余额转至市政公司指定财务账户。\r\n', '', '待了解', '', '1.银河该项目合作代理，为2016年新成立的第三方售电系统ICT类型公司，公司主营业务范围主要从事为南非市政公司提供涵盖新能源系统管理、新型第三方售电平台及相关软件系统业务，公司正式员工9名（4名管理人员，5名程序开发工程师），其独立开发的本地第三方售电平台在当地已和各大银行、Whatsup平台完成兼容交互；\r\r\r\r\n\r\r\r\n\r\r2.代理公司股权简单，公司老板之前在兰吉尔任职销售总监长达7年，在电能表和售电领域经验丰富，熟悉南非政府招标和市场信息；\r\r\n\r\r\r\n3.截止目前为主，该公司已中标如下第三方售电/售水授权合同：\r\r\r\r\r\n*** 大都市市政公司City of Ekurhuleni的第三方售电（4个第三方售电平台之一）\r\r\r\r\r\n*** Sekhukhune地区市政公司售水系统平台和水表项目（目前正在和其洽谈银河提供水表一\r\r\n体化方案）\r\r', '', '银河第一次投标该大都市市政公司，无客户关系。\r\r\n\r\r\n此次合作代理透露，他们和该市政公司高层已接触过，目前进展较为不错，待持续跟进代理反馈详细的核心关系网和竞标策略。', '', '该项目预计竞争较为激烈，主要竞争对手为本地主流售电系统服务商：\r\r\r\r\r\r\r\n兰吉尔：南非最大的和最有影响力的售电系统服务提供商；\r\r\r\r\r\r\r\nOntec：南非第二大售电系统服务提供商；\r\r\r\r\r\r\r\nConlog：南非主要售电系统服务提供商；\r\r\r\r\r\r\nCigcell：南非本地最大第三方售电平台公司；\r\r\r\r\r\r\nSyntell：南非主要售电系统服务提供商；\r\r\r\r\nContour Technology：南非主要售电系统服务提供商；\r\r\n\r\r\n\r\r\n相对来说，银河主要缺乏本地售电系统的实施经验和XMLVend标准技术的实践和运用。', '', '银河劣势：\r\r\r\r\n银河主要缺乏本地售电系统的实施经验和XMLVend标准技术的实践和运用。\r\r\r\n银河确认和本地第三方售电系统兼容、第三方收电费模式的实践和运用。\r\r\r\n该市政客户关系基础为0，需要联合代理共同推进。\r\r\r\n\r\r\r\n\r\r\r\n主要竞争策略：\r\r\r\n1.尽快完成本地第三方售电平台的兼容（当前代理的第三方平台和EasyPay 平台），以便后续演示顺利进行；\r\r\r\n2.和代理共同商议重点攻克的核心人员，支持我们竞标；\r\r\r\n3.在报价方式和价格上保持相对竞争力。', '', '1.代理当前客户关系的验证和新客户关系的拓展；\r\n2.本地第三方售电平台兼容工作及早完成。\r\n3.报价需要保持相对优势。', '8大市政之一STS售电系统投标，尝试NYC以外的有潜力代理合作投标，请公司支持', '李忠鹏(Evans)2020-09-04 15:31:35', '01', '★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('491', '{28B7EDEF-755D-44C9-A854-4D5B92F5A835}', '66', 'INHE-0774', '2020-09-16 11:03:07', '0000-00-00 00:00:00', '2020-09-17 18:25:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2020091605/SIP', '', 'N° AO - 97 235 - E', '2020年10月6日', 'SUPPLY OF WORK EQUIPMENT, RAKING AND STANDARDISATION OF ELECTRICAL CONNECTIONS电力设备的供应，连接和标准化', '价格条款：DDP\r\r\n付款条件：招标付款方式是交货后，收到发票起75天内支付；银河和代理的付款方式是30%预付款+70%不可撤销保兑信用证\r\r\n交期：订单确认后30天内；银河给代理的交货时间在和代理商量\r\r\n', '{28B7EDEF755D44C9A8544D5B92F5A8358442F4C2B3234363A3D51C033076BD50}_CDC AO - 97 235 - E en.docx', '满足技术规格前提下低价中标', '{28B7EDEF755D44C9A8544D5B92F5A835074E749A304748709C51373D9D483750}_CDC AO - 97 235 - E fr.docx', '一家可以中多个LOT', '', '代理开保函', '', '根据标书要求的格式提供技术实力证明，财务证明和供货证明等资料', '', '', '', '代理商投标', '', '', '', '\r\r\n招标付款方式是交货后，收到发票起75天内支付；\r\r\n', '', '', '', '', '', '', '', '', '', '', '', '需要准备法语投标资料', '1. 该项目不需要样机；\r\r\n2. 马上还有一个4.5万台电表采购项目将发标；\r\r\n3. 代理实力较强和电力公司有良好的关系\r\r\n\r\r\n\r\r\n\r\r\n', '何森华2020-09-16 14:39:24', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('492', '{22E30039-9EE6-44AD-AA1A-A5A41D8AF508}', '66', 'INHE-0774', '2020-09-17 09:38:12', '0000-00-00 00:00:00', '2020-09-21 13:58:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2020091701/PEK', '', 'DD-V-20/20-D2', '暂未发标', 'advanced measuring infrastructure ( meters)高级计量基础设施（电表）', '1. 价格条款：CIF（报给合作方）\r\n2. 付款条件：交货后60天内\r\n3. 交期：下单后45天内\r\n4. 质保：3年', '', '暂未发标', '', '暂未发标						\r\n', '', '暂未发标						\r\n', '', '\r\r\n\r\r\r\r\r\nLot1:2017-2020年间相同或相似产品供货金额不少于20,667,000欧\r\r\r\nLot2:2017-2020年间相同或相似产品供货金额不少于8,534,000欧\r\r\r\r\n\r\r\r\r\n						\r\r\r\n\r\r\r\n\r\r\r\n', '', '技术资料；产品寿命承诺书；ESPD文件；供货记录', '{22E300399EE644ADAA1AA5A41D8AF508C675BD0CC93442C09B990884D4324504}_statements engl..pdf', '代理商投标', '', '', '', '', '', '', '', '最近有通信模块中标记录；上一次PLC电表投标，只有该公司和Iskraemeco公司参与，价格比Iskraemeco低，因保函问题没中标；\r\n该公司在克罗地亚规模偏中大型，有一定实力和经验。\r\n\r\n', '', '', '', 'Iskraemeco是最大竞争对手，但价格较高', '', '和当地公司ELEKTROCENTAR PETEK达成合作，当地公司主导投标，和电力公司沟通并翻译资料；银河做电表分包商', '', '成功关键：绑定强有力的合作方', '1. 如果参与LOT1，需要解决G3-PLC集中器没CE认证问题；罗马尼亚EPG项目面临同样问题\r\r\r\n2. 该项目还处于咨询阶段，未正式发标，目前最重要的是绑定合作方；\r\r\r\n3. 该市场处于智能电表部署初步阶段，Iskraemeco一家独大，竞争相对没那么激烈。\r\r\r\n', '何森华2020-09-17 11:09:19', '03', '★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('493', '{12C193DA-396D-4924-9792-D2199A1C9951}', '169', 'INHE-0381', '2020-09-21 09:04:22', '0000-00-00 00:00:00', '2020-09-22 16:22:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2020092101/CMD', '', 'N ° 2020/02 / COMORSOL / STS', '2020.11.16', 'PROJET COMORSOL科摩索项目', '标书条款：\r\r\r\r\r\r\n1.交付合同的40%货物，在验收和安装之后，见单据支付合同金额的40%；\r\r\r\r\n2.交付合同的30%货物，在验收和安装之后，见单据支付合同金额的30%； 	3.交付合同的30%货物，在验收和安装之后，见单据支付合同金额的30%；	\r\r\n4.10%的尾款在买家发出验收函之后的12个月支付。			\r\r\r\n						\r\r\r\n本次授权代理商投标，结算方式为100%全款LC或者20%预付款+尾款LC。', '', '1.必须投2个LOT，只投一个LOT将出局。\r2.技术评标将根据标书技术要求，一条一条评分，技术评标通过后，价格最低者中标。\r\r\r\r\n\r\r\r\r\n', '', '一家中标，每个投标商只能投一次标，不能即使独立投标商又JV投标。但是厂家可以作为多个分包商。', '', '投标保函：45000欧。履约保函为10%合同金额\r\r\r\n', '', '1.最近5年内，最少3份类似项目的用户满意度证明。2.需要有金额为1,500,000欧元的现金流。', '', '需要提供商务和技术资料（法语版），最迟10月15号提供。', '', '代理商投标，银河做为厂家授权', '不适用', '', '', '', '', '', '', '代理在此市场有一定的客情，此前供货售电系统，卡表，代码表。', '', '银河在此市场几乎无经营，都是通过代理商投标或者供货。', '', '威盛在此市场供货代码表。', '', '银河形式：市场无客情，对市场需求不熟，标书结算方式差。授权代理投标，一是代理在此市场有一定客情并供货，结合代理优势，争取最大中标可能性；二是直接与代理商结算，降低银河风险，收款有保障。', '', '提供符合要求的资料，价格至关重要。', '市场虽小，但是本次产品需求量几乎是整个市场的需求，本次投标不需要样机，将是价格战，值得努力拿下。', '张柳芳(Alexie)2020-09-21 11:09:35', '02', '★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('494', '{E2D0F263-44D8-4397-99F8-D0688CA8F086}', '66', 'INHE-0901', '2020-09-23 13:34:25', '0000-00-00 00:00:00', '2020-09-25 11:10:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2020092302/GCF', '', '503013', '2020年10月26日', '供应三相智能电表和通讯模块（Supply Three-phase \"smart\" electronic meters and communication modem）', '付款主体：HEDNO电力局\r  付款条件：暂定为代理直接投标，银河交货到电力局希腊雅典仓库后95-115天内电力局付现金给代理，银河与代理履行背靠背责任  \r交期：在最终样机确认批准后，每三个月供货1次，总共4次，持续1年\r  价格条款：暂定为CIF 雅典Piraeus港口  质保期：5年  备品：质保期结束后，至少保证5年  违约条款：1.每延迟一周，按延迟部分交付的合同价值计算为0.5％，最高可达部分交付的合同价值的20％，总的延迟罚款总额不能超过合同总价值的5％。 2.如果在保修期内出现错误操作或设备损坏，HEDNO有资格要求赔偿损失（最高至合同总价的50％）', '{E2D0F26344D8439799F8D0688CA8F0868442F4C2B3234363A3D51C033076BD50}_Tender No.503013 EN document.docx', '投标书的截止日期和时间后四（4）个工作日开始以电子方式开标，及10月30日。在评估结束后10天内，主管委员会将以书面形式通知项目出价最低的供应商（临时承包商），临时承包商将在3个工作日内以电子方式提交PDF格式的“临时承包商文档”。主管委员会收到文件后电子加盖章并检查承包商的证明文件，之后送给HEDNO主管决策机构进行审批，如若确认，则HEDNO签发裁决书。', '', '1家中标', '', '投标保证金：94800欧元，有效期超过HEDNO投标截止日期的13个月  履约保证金：合同总价的5%\r\n', '', '公司年限：在生产和供应电表系统及供应方面至少5年经验  工厂及产品资质：EN/ISO 9001:2008,EN/ISO14001:2004,2014/32/EC(MID),B/Class2014/32、EC(MID), EN ISO/IEC 17025:2005, DLMS/COSEM兼容证书（根据EN/IEC62056）, 电表及通信介质CE符合性声明。  供货记录：1.过去5年内，至少有4800三相电表集成到X.T.网络及系统中并运行良好。2.过去5年内，至少有4800个通信模块集成到系统中并运行良好。  ', '', '技术合规表，合同条款，信用及履约保函条款，制造检测，供货资质等等  在投标截止日期（10月26日）前电子方式递交', '', '代理投标', '', '希腊HEDNO决策过程比较正规，通过评标选出价格最低的供应商，政治政府对评标无影响，一切评标操作都为评标委员会进行，最后给HEDNO进行审批确认。', '', '赊销，无预付款，银河与代理履行背靠背，银河每次将货物交货到电力局雅典仓库后，电力局在95-115天后给代理付现金，每三个月交货一次，总共四次，持续1年。', '', 'HEDNO信用良好，华立去年中标并供货正常付款，且华立2020年上半年也在正常供货出口给HEDNO。  HEDNO为上市公司，财报见附件，为希腊文。主要数据如下：总资产为9.09417亿欧元，2019年全年营业额1.62465亿欧元，2019年全年净利润1495.7万欧元', '{E2D0F26344D8439799F8D0688CA8F086108D268797C74834B1DDE2FC1083AA37}_στοιχεια-και-πληροφοριεσ-χρησησ-2019-δεδδηε-αε.pdf', '代理给为HEDNO的AMR/MDM系统提供维护服务，并协助HEDNO进行样机测试，为希腊系统供应商，了解HEDNO操作模式，于2011年与华立合作并将华立带到希腊市场，在投标项目上有经验。年营业额目前查询为437万美元，我们需要给出很好的价格才有合作的可能，关于项目合作细节还在和代理确认。  联系人Sotiris在兰吉尔工作15年，在ABB工作10年，对技术方面很了解，对我司过去给希腊SFALCO发过样机一事耿耿于怀,但我们并没有与SFALCO参加任何希腊项目，一直说明需要很好的价格才有继续合作的可能。', '', '目前银河与代理还在需要对合作细节进行商谈，代理给HEDNO做系统维护，并协助HEDNO测试样机，与HEDNO内部有一定关系，了解一些情况。', '', '竞争对手：1.华立 2019年出口希腊55500台三相表 CIF价平均为40.9美元，可能是SKD供货。 2.三星 2019年出口希腊13600台三相表 CIF价平均为63.9美元，有参考价值，通过ODD供货。 2020年1-4月出口希腊16796台单相表 CIF价平均为26美元', '', '优势：1.价格优势  2.能满足技术要求，有认证  劣势：1.背靠背责任，电力局无预付款。 ', '', '样机最晚需要在10月14提供，14日当天需要发出，如若样机时间来不及则一切努力都白费了。', '欧洲国家很多都有当地认证需求（如塞尔维亚当地认证,英国电表当地认证），且欧洲很多国家电表抗磁要求为500mT（目前了解到荷兰，保加利亚，波兰都有此要求），银河目前MID认证的电表都只能做200mT，是重要偏差。此次希腊招标只需提供MID认证，我司资质能够满足，且样机能满足要求（希腊项目技术规格没明确说明抗磁具体数值），是难得的进入欧洲市场并进行投标的机会，如若投标顺利，将有利于银河打开欧洲其他市场，并提升银河形象。如若未能中标，也是一次很好的参投的经验，毕竟我们能够投的欧洲项目且有机会中标的并不多。						\r\r\r\n', '徐周泽弈2020-09-23 16:25:49', '04', '★★★★★', '02');
INSERT INTO `crs_tabledata1533` VALUES ('495', '{A5E22F20-ABF3-4DFF-96A5-A7AE9A5319AC}', '75', 'INHE-0432', '2020-09-25 16:42:18', '0000-00-00 00:00:00', '2020-09-27 13:23:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020092501/SLC', '', 'SL-EDSA-166445-GO-RFB', '2020年11月17号。', 'Design, Supply & Installation Procurement of Supply of Pre-Paid Meters and Accessories电表及配件设计、供应、安装', '交货地点：弗里敦市内\r\r\n报价条款 ：CIP弗里敦\r\r\n交期条款（交期，违约金等）：按合同规定的开工日期起，18个月内完成供货及安装等。\r\r\n项目延期罚金：每天支付合同金额的0.05%\r\r\n\r\r\n付款条件：\r\r\n电表等主要供货产品：\r\r\n10%预付：需提供预付款保函\r\r\n80%货款：在收到交货单据后的45天内支付\r\r\n5%：收到完工证明且提交发票后的45天内支付\r\r\n5%：收到运营接受证明且提交发票后的45天内支付\r\r\n\r\r\n设计费：\r\r\n10%预付：提供预付款保函\r\r\n90%：项目经理审批通过方案且提交发票后的45天内支付。\r\r\n\r\r\n安装服务：\r\r\n10%预付：需提供预付款保函\r\r\n80%货款：在收到交货单据后的45天内支付\r\r\n5%：收到完工证明且提交发票后的45天内支付\r\r\n5%：收到运营接受证明且提交发票后的45天内支付\r\r\n\r\r\n如果电力公司未能及时付款，将支付承包商利息。\r\r\n\r\r\n具体付款方式：将在预授合同会议上讨论并确定。\r\r\n\r\r\n项目启动及运营接受测试：完工日期起的8个星期内完成', '', '初审：技术评审\r\n二审：财务评审\r\n', '', '综合评标，价格最低这中标，1个LOT，1个中标人。\r\n', '', '\r\n投标保函：10万美元。\r\n\r\n履约保函要求：10%合同金额\r\n', '', '商务：\r\r\n1.过去3年里，输电或配电网络设备及材料的供货与安装，每年的营业额至少750万美元。\r\r\n2.审计财报：2016，2017，2018年这3年的。\r\r\n3.现金流：170万美元\r\r\n4. 3年内:\r\r\n总资产/总负债>1.25；\r\r\n流动资产/流动负债比例>1.20\r\r\n\r\r\n5.供货：过去5年内，自2013年1月起的供货经验。此处有矛盾。需澄清\r\r\n（1）过去5年内以承包商，联合体成员，管理承包方，或者分包商身份参与执行并完成， 或者大部分完成，至少2个合同，每个合同金额至少400万美元。至少有1个合同是在类似于塞拉利昂这样的发展中国家完成的。\r\r\n（2）合同类似度需包含：电表产品及配件、电缆等供货及安装；具体的工程设计及安装服务等。\r\r\n（3）STS预付费电表及安装、连接服务完成的数量：至少80,0000只。此处有歧义，看起来是80万只，但根据商务标书P61，其要求分包商过去20年至少生产了10万只电表，且其中8万只为海外供货。\r\r\n（4）分包商可以是特特殊的分包商。\r\r\n\r\r\n技术：\r\r\n1.电缆，电表必须提供形式测试报告（10年以内，第三方独立测试机构及相关认证，没有', '', '需商务部协助投标资料制作', '', '银河投标', '', '1.根据目前的信息，商务总监及商务总监主导的评标组起决策作用；2.高层MD及能源部对授标有影响力。', '', '', '', '该项目为世行融资项目', '', '1.本项目将与利比里亚代理商合作，其在塞拉利昂有分公司；与政府高层、电力公司技术部高层均有较好的客户关系\r\n2.代理商年龄40岁左右，在利比里亚有较大的公司，且注册了多家当地公司参与电力公司的项目；做生意的欲望教强烈。此次也是其向我们提供全套标书，并同意将去塞拉利昂现场竞标。业务将与其进一步沟通合作、及竞投标策略。\r\n', '', '银河业务与目前电力公司的商务总监、技术副总，及评标团队均熟悉，有打过初步交道。但未能深入合作过。\r\n', '', '1.主要竞争对手为华立。其已中标且在供货。本地代理实力教强。\r\n2.科陆：据说其代理与科陆上次SLA投标因佣金问题未达成一致，科陆未中标。但科陆此前有中标且供货过。\r\n', '', '优势：代理在政府高层有人脉，可以用来与电力公司高层谈合作。\r\n\r\n劣势：此前未中标过，业务自己与电力公司高层关系一般，而华立，科陆已经有一定的基础。\r\n\r\n竞争策略：\r\n\r\n1.与利比里亚代理商达成合作，利用其政府高层客户关系，牵线至电力公司商务总监、MD等高层，达成合作；\r\n\r\n2.利用业务本身在电力公司已有的客户关系，与代理一起商讨竞投策略，引导代理执行，与评标团队达成合作。\r\n', '', '关键：提前与电力公司高层达成合作，做好客户关系。\r\n需要的支持：该市场竞争激烈，又是世行的标，所以价格方面需要有优势；同时该市场是新市场，对代理的佣金或电力公司高层相关的营销费用（如有必要）需要公司支持，业务根据现场情况向公司说明、申请。', '项目潜力较好，请公司支持。标书太大，将单独发OA。', '谭东羊(Timon)2020-09-25 17:45:57', '03', '★★★★', '02');
